-- Saves the original character Animate LocalScript before parking and installs a fresh copy after restore so idle/walk/run/jump resume.
    local Environment = getgenv and getgenv() or _G
    local PreviousInstance = Environment.__BANANIHUB_INSTANCE
    local PreviousUnload = nil
    if type(PreviousInstance) == "table" and type(PreviousInstance.Unload) == "function" then
        PreviousUnload = PreviousInstance.Unload
    elseif type(Environment.__BANANIHUB_UNLOAD) == "function" then
        PreviousUnload = Environment.__BANANIHUB_UNLOAD
    end
    if type(PreviousUnload) == "function" then
        -- Only a deliberate replacement is allowed to tear down an existing BananiHub runtime.
        -- Normal UI close/minimize/toggle paths never receive this lifecycle token.
        pcall(PreviousUnload,"replacement")
    end
    Environment.__BANANIHUB_UNLOAD = nil
    Environment.__BANANIHUB_INSTANCE = nil

    -- Hard-clean orphaned BananiHub GUI roots from interrupted/older executions.
    -- This runs before the new UI is created, so it cannot delete the new instance.
    local function PurgeBananiHubGui(Parent)
        if not Parent then return end
        for _,Name in ipairs({
            "BananiHubUI",
            "BananiHubBootDiagnostic",
            "BananiHubPremiumApple51412",
            "BananiMM2ESPPlus",
            "BananiHubToastLayer",
            "BananiBloxFruitDetector"
        }) do
            local Object=Parent:FindFirstChild(Name)
            if Object then pcall(function() Object:Destroy() end) end
        end
    end
    pcall(function() PurgeBananiHubGui(game:GetService("CoreGui")) end)
    pcall(function()
        local P=game:GetService("Players").LocalPlayer
        if P then PurgeBananiHubGui(P:FindFirstChildOfClass("PlayerGui")) end
    end)
    pcall(function()
        if type(gethui)=="function" then PurgeBananiHubGui(gethui()) end
    end)
end
