local function SetEarlyBootText(_) end

-- The premium shell owns all visible UI. Keep theme names only for config compatibility.
local DEFAULT_GRAY_THEME = "Default"
local Rayfield = {
    Flags = {}, _Tabs = {}, _PremiumRegistry = {}, _PremiumRegistryCounter = 0,
    _Mirrors = {}, _Ready = true, _Visible = true, _Compact = false
}
local Window

local function RegistryClean(Value)
    local Text=tostring(Value or "")
    local Pos=Text:find("[%w]")
    if Pos then Text=Text:sub(Pos) end
    return Text:gsub("%s+$","")
end
local function RegistryOptionList(Value)
    if type(Value)=="table" then
        local Out={}
        for _,V in ipairs(Value) do table.insert(Out,tostring(V)) end
        return Out
    end
    if Value==nil or Value=="" then return {} end
    return {tostring(Value)}
end
local function RegistrySection(Target,Tab)
    return tostring((Target and Target._SectionTitle) or (Tab and Tab._CurrentSection) or "General")
end
local function RegistryRegister(Kind,Target,Tab,Obj,Options,Extra)
    Options=type(Options)=="table" and Options or {}
    Rayfield._PremiumRegistryCounter+=1
    local Record={
        Kind=Kind,Obj=Obj,Options=Options,Extra=Extra,
        Name=RegistryClean(Options.Name or Options.Title or (Extra and Extra.Text) or Kind),
        Flag=Options.Flag,Tab=Tab and RegistryClean(Tab.Name) or "Unknown",
        Section=RegistrySection(Target,Tab),Order=Rayfield._PremiumRegistryCounter,
        Callback=Options.Callback,
    }
    table.insert(Rayfield._PremiumRegistry,Record)
    return Obj
end
function Rayfield:RegisterMirror(FlagName,Control)
    if type(FlagName)~="string" or type(Control)~="table" then return Control end
    self._Mirrors[FlagName]=self._Mirrors[FlagName] or {}
    table.insert(self._Mirrors[FlagName],Control)
    local Source=self.Flags[FlagName]
    if Source and Source~=Control and Control.Set then
        local Value=Source.CurrentValue
        if Value==nil then Value=Source.CurrentOption end
        if Value==nil then Value=Source.CurrentKeybind end
        if Value==nil then Value=Source.Color end
        if Value~=nil then pcall(function() Control:Set(Value,true) end) end
    end
    return Control
end
function Rayfield:_SyncMirrors(FlagName,Source,Value)
    local List=self._Mirrors[FlagName]
    if not List then return end
    for I=#List,1,-1 do
        local Mirror=List[I]
        if type(Mirror)~="table" or not Mirror.Set then
            table.remove(List,I)
        elseif Mirror~=Source then
            pcall(function() Mirror:Set(Value,true) end)
        end
    end
end
local function RegistrySync(Options,Obj,Value)
    if Options and Options.Flag then Rayfield:_SyncMirrors(Options.Flag,Obj,Value) end
end
local function RegistryInvoke(Options,...)
    if Options and type(Options.Callback)=="function" then return Options.Callback(...) end
end
local function BindRegistryControls(Target,Tab)
    function Target:CreateParagraph(O)
        O=type(O)=="table" and O or {Title=tostring(O)}
        local Obj={Title=RegistryClean(O.Title or "Info"),Content=tostring(O.Content or "")}
        function Obj:Set(Value)
            if type(Value)=="table" then
                if Value.Title~=nil then self.Title=RegistryClean(Value.Title) end
                if Value.Content~=nil then self.Content=tostring(Value.Content) end
            else self.Content=tostring(Value or "") end
        end
        return RegistryRegister("Paragraph",Target,Tab,Obj,O)
    end
    function Target:CreateButton(O)
        O=type(O)=="table" and O or {Name=tostring(O)}
        local Obj={Name=RegistryClean(O.Name or "Button")}
        function Obj:Set(Value) self.Name=RegistryClean(Value) end
        return RegistryRegister("Button",Target,Tab,Obj,O)
    end
    function Target:CreateToggle(O)
        O=type(O)=="table" and O or {Name=tostring(O)}
        local Obj={CurrentValue=false}
        function Obj:Set(Value,Silent)
            self.CurrentValue=Value==true
            RegistrySync(O,self,self.CurrentValue)
            if not Silent then RegistryInvoke(O,self.CurrentValue) end
        end
        if O.Flag then Rayfield.Flags[O.Flag]=Obj end
        return RegistryRegister("Toggle",Target,Tab,Obj,O)
    end
    function Target:CreateSlider(O)
        O=type(O)=="table" and O or {}
        local Range=O.Range or {0,100}
        local Min,Max=tonumber(Range[1]) or 0,tonumber(Range[2]) or 100
        if Max<Min then Min,Max=Max,Min end
        local Obj={Range={Min,Max},CurrentValue=math.clamp(tonumber(O.CurrentValue) or Min,Min,Max)}
        function Obj:Set(Value,Silent)
            self.CurrentValue=math.clamp(tonumber(Value) or Min,Min,Max)
            RegistrySync(O,self,self.CurrentValue)
            if not Silent then RegistryInvoke(O,self.CurrentValue) end
        end
        if O.Flag then Rayfield.Flags[O.Flag]=Obj end
        return RegistryRegister("Slider",Target,Tab,Obj,O)
    end
    function Target:CreateDropdown(O)
        O=type(O)=="table" and O or {}
        local Obj={Options={},CurrentOption=RegistryOptionList(O.CurrentOption)}
        for _,V in ipairs(O.Options or {}) do table.insert(Obj.Options,tostring(V)) end
        function Obj:Refresh(NewOptions)
            self.Options={}
            for _,V in ipairs(NewOptions or {}) do table.insert(self.Options,tostring(V)) end
            -- A changing inventory/player list must not silently erase the user's selection.
        end
        function Obj:Set(Value,Silent)
            local Requested=RegistryOptionList(Value)
            local Clean={}
            for _,V in ipairs(Requested) do
                if #self.Options==0 or table.find(self.Options,tostring(V)) then table.insert(Clean,tostring(V)) end
            end
            self.CurrentOption=Clean
            RegistrySync(O,self,table.clone(self.CurrentOption))
            if not Silent then RegistryInvoke(O,table.clone(self.CurrentOption)) end
        end
        if O.Flag then Rayfield.Flags[O.Flag]=Obj end
        return RegistryRegister("Dropdown",Target,Tab,Obj,O)
    end
    function Target:CreateInput(O)
        O=type(O)=="table" and O or {}
        local Obj={CurrentValue=tostring(O.CurrentValue or "")}
        function Obj:Set(Value,Silent)
            self.CurrentValue=tostring(Value or "")
            RegistrySync(O,self,self.CurrentValue)
            if not Silent then RegistryInvoke(O,self.CurrentValue) end
        end
        if O.Flag then Rayfield.Flags[O.Flag]=Obj end
        return RegistryRegister("Input",Target,Tab,Obj,O)
    end
    function Target:CreateKeybind(O)
        O=type(O)=="table" and O or {}
        local Current=typeof(O.CurrentKeybind)=="EnumItem" and O.CurrentKeybind.Name or tostring(O.CurrentKeybind or "L")
        local Obj={CurrentKeybind=Current}
        function Obj:Set(Value,Silent)
            local Key=typeof(Value)=="EnumItem" and Value.Name or tostring(Value or "")
            if Key=="" then return end
            self.CurrentKeybind=Key
            RegistrySync(O,self,Key)
            if not Silent then RegistryInvoke(O,Enum.KeyCode[Key] or Key) end
        end
        if O.Flag then Rayfield.Flags[O.Flag]=Obj end
        return RegistryRegister("Keybind",Target,Tab,Obj,O)
    end
    function Target:CreateColorPicker(O)
        O=type(O)=="table" and O or {}
        local Obj={Color=typeof(O.Color)=="Color3" and O.Color or Color3.fromRGB(255,193,63)}
        function Obj:Set(Value,Silent)
            if typeof(Value)~="Color3" then return end
            self.Color=Value
            RegistrySync(O,self,Value)
            if not Silent then RegistryInvoke(O,Value) end
        end
        if O.Flag then Rayfield.Flags[O.Flag]=Obj end
        return RegistryRegister("Color",Target,Tab,Obj,O)
    end
    function Target:CreateLabel(Text,Image)
        local Obj={TextLabel={Text=tostring(Text or "")},Image=tostring(Image or "")}
        function Obj:Set(NewText,NewImage)
            if NewText~=nil then self.TextLabel.Text=tostring(NewText) end
            if NewImage~=nil then self.Image=tostring(NewImage or "") end
        end
        return RegistryRegister("Label",Target,Tab,Obj,{Name=tostring(Text or "Label")},{Text=Text,Image=Image})
    end
end
function Rayfield:CreateWindow(_)
    local W={CurrentTab="Main"}
    function W:CreateTab(Name)
        local Tab={Name=RegistryClean(Name),RawName=Name,_CurrentSection="General",_Dashboard=false,_Visible=true}
        function Tab:CreateSection(Title) self._CurrentSection=RegistryClean(Title); return {Name=self._CurrentSection} end
        function Tab:EnableDashboard(Columns) self._Dashboard=true; self._DashboardColumns=tonumber(Columns) or 2 end
        function Tab:DashboardSection(Column,Title)
            local Proxy={_SectionTitle=RegistryClean(Title),_Column=Column}
            BindRegistryControls(Proxy,Tab)
            function Proxy:AddInfoLogo(GetInfo)
                local Obj={TextLabel={Text=""}}
                function Obj:Refresh()
                    local Value=type(GetInfo)=="function" and GetInfo() or GetInfo
                    self.TextLabel.Text=tostring(Value or "")
                end
                Obj:Refresh()
                return RegistryRegister("InfoLogo",Proxy,Tab,Obj,{Name=Title or "Information"})
            end
            return Proxy
        end
        function Tab:Filter(_) end
        BindRegistryControls(Tab,Tab)
        table.insert(Rayfield._Tabs,Tab)
        return Tab
    end
    function W:SelectTab(Name)
        self.CurrentTab=RegistryClean(Name)
        local Env=(getgenv and getgenv()) or _G
        local API=Env and Env.BananiHubPremiumUI
        if API and type(API.SelectPage)=="function" then pcall(API.SelectPage,self.CurrentTab,true) end
        return true
    end
    function W:SetTabVisible(Name,Visible)
        local Wanted=RegistryClean(Name)
        for _,Tab in ipairs(Rayfield._Tabs) do if Tab.Name==Wanted then Tab._Visible=Visible==true; return true end end
        return false
    end
    function W:ModifyTheme(_) return true end
    function W:SetLoadingSubtitle(_) end
    function W:ModifyLoadingSubtitle(_) end
    return W
end
function Rayfield:SetCompactMode(Value) self._Compact=Value==true end
function Rayfield:SetReady() self._Ready=true end
function Rayfield:CloseDropdown() end
function Rayfield:Destroy() end
function Rayfield:Unload() end
function Rayfield:ToggleUI()
    local Env=(getgenv and getgenv()) or _G
    local API=Env and Env.BananiHubPremiumUI
    if API and type(API.SetVisible)=="function" then
        local Visible=not (API.Window and API.Window.Visible==true)
        pcall(API.SetVisible,Visible,false)
    end
end

-- Premium-style standalone toast layer. This is not the removed legacy UI.
function Rayfield:Notify(Data)
    Data=type(Data)=="table" and Data or {Title="BananiHub",Content=tostring(Data)}
    local Parent=Player:FindFirstChildOfClass("PlayerGui") or CoreGui
    if not Parent then warn("BANANIHUB | "..tostring(Data.Title).." | "..tostring(Data.Content)); return end
    local Screen=Parent:FindFirstChild("BananiHubToastLayer")
    if not Screen then
        Screen=Instance.new("ScreenGui")
        Screen.Name="BananiHubToastLayer"; Screen.ResetOnSpawn=false; Screen.IgnoreGuiInset=true; Screen.DisplayOrder=2147482990; Screen.ZIndexBehavior=Enum.ZIndexBehavior.Sibling; Screen.Parent=Parent
        local Host=Instance.new("Frame"); Host.Name="Host"; Host.AnchorPoint=Vector2.new(1,1); Host.Position=UDim2.new(1,-18,1,-24); Host.Size=UDim2.fromOffset(330,420); Host.BackgroundTransparency=1; Host.Parent=Screen
        local Layout=Instance.new("UIListLayout"); Layout.HorizontalAlignment=Enum.HorizontalAlignment.Right; Layout.VerticalAlignment=Enum.VerticalAlignment.Bottom; Layout.Padding=UDim.new(0,8); Layout.SortOrder=Enum.SortOrder.LayoutOrder; Layout.Parent=Host
    end
    local Host=Screen:FindFirstChild("Host"); if not Host then return end
    local Card=Instance.new("Frame"); Card.Size=UDim2.fromOffset(0,62); Card.BackgroundColor3=Color3.fromRGB(14,14,16); Card.BackgroundTransparency=.04; Card.BorderSizePixel=0; Card.ClipsDescendants=true; Card.LayoutOrder=-math.floor(os.clock()*1000); Card.Parent=Host
    local C=Instance.new("UICorner"); C.CornerRadius=UDim.new(0,11); C.Parent=Card
    local S=Instance.new("UIStroke"); S.Color=Color3.fromRGB(217,177,55); S.Thickness=1; S.Transparency=.24; S.Parent=Card
    local Bar=Instance.new("Frame"); Bar.Size=UDim2.fromOffset(4,44); Bar.Position=UDim2.fromOffset(8,9); Bar.BackgroundColor3=Color3.fromRGB(235,190,58); Bar.BorderSizePixel=0; Bar.Parent=Card
    local BC=Instance.new("UICorner"); BC.CornerRadius=UDim.new(1,0); BC.Parent=Bar
    local T=Instance.new("TextLabel"); T.BackgroundTransparency=1; T.Position=UDim2.fromOffset(20,7); T.Size=UDim2.new(1,-30,0,20); T.Font=Enum.Font.GothamBold; T.TextSize=12; T.TextColor3=Color3.fromRGB(248,248,250); T.TextXAlignment=Enum.TextXAlignment.Left; T.TextTruncate=Enum.TextTruncate.AtEnd; T.Text=tostring(Data.Title or "BananiHub"); T.Parent=Card
    local B=Instance.new("TextLabel"); B.BackgroundTransparency=1; B.Position=UDim2.fromOffset(20,28); B.Size=UDim2.new(1,-30,0,25); B.Font=Enum.Font.Gotham; B.TextSize=10; B.TextColor3=Color3.fromRGB(177,179,187); B.TextXAlignment=Enum.TextXAlignment.Left; B.TextWrapped=true; B.TextYAlignment=Enum.TextYAlignment.Top; B.Text=tostring(Data.Content or ""); B.Parent=Card
    local TS=game:GetService("TweenService")
    local ToastScale=Instance.new("UIScale"); ToastScale.Scale=.975; ToastScale.Parent=Card
    TS:Create(Card,TweenInfo.new(.28,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Size=UDim2.fromOffset(320,62)}):Play()
    TS:Create(ToastScale,TweenInfo.new(.30,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Scale=1}):Play()
    task.delay(tonumber(Data.Duration) or 3,function()
        if not Card.Parent then return end
        TS:Create(ToastScale,TweenInfo.new(.15,Enum.EasingStyle.Quint,Enum.EasingDirection.In),{Scale=.985}):Play()
        TS:Create(Card,TweenInfo.new(.24,Enum.EasingStyle.Quint,Enum.EasingDirection.In),{Size=UDim2.fromOffset(0,62),BackgroundTransparency=1}):Play()
        task.delay(.22,function() if Card.Parent then Card:Destroy() end end)
    end)
end

