-- Telemetry is independent from UI rendering so removing the legacy UI cannot break FPS/ping.
local TelemetryConnection
do
    local Frames,Elapsed,Last=0,0,os.clock()
    TelemetryConnection=RunService.Heartbeat:Connect(function(Dt)
        Frames+=1; Elapsed+=Dt
        if Elapsed<0.75 then return end
        local Now=os.clock(); local Span=math.max(Now-Last,0.001)
        LiveTelemetry.FPS=math.floor(Frames/Span+0.5)
        Frames=0; Elapsed=0; Last=Now
        local Ping="--"
        pcall(function()
            local Item=Stats.Network.ServerStatsItem["Data Ping"]
            local Raw=Item and Item:GetValueString() or ""
            Ping=tostring(Raw):match("[%d%.]+") or "--"
        end)
        LiveTelemetry.Ping=Ping
        LiveTelemetry.UpdatedAt=Now
    end)
end

