-- One ownership registry for durable runtime resources. The goal is the same
-- as established Roblox Maid/Janitor patterns: every long-lived disposable
-- created by BananiHub has one lifecycle owner and one final teardown path.

-- ==================================================================
-- [BH:LIFECYCLE] UNIFIED LIFECYCLE CLEANUP
-- Owns long-lived connections, tweens, temporary instances, and teardown.
-- ==================================================================
local CleanupRegistry={
    Items=setmetatable({}, {__mode="k"}),
    Keys={},
    Groups={}
}
Runtime.CleanupRegistry=CleanupRegistry

local function CleanupOne(Item,Method)
    if Item==nil then return end
    if type(Method)=="function" then pcall(Method,Item); return end

    if type(Method)=="string" and type(Item)~="function" then
        local F=nil
        pcall(function() F=Item[Method] end)
        if type(F)=="function" then pcall(F,Item); return end
    end

    local Kind=typeof(Item)
    if Kind=="RBXScriptConnection" then
        pcall(function() Item:Disconnect() end)
    elseif Kind=="Instance" then
        pcall(function() Item:Destroy() end)
    elseif Kind=="thread" then
        pcall(function()
            if coroutine.running()~=Item then task.cancel(Item) end
        end)
    elseif type(Item)=="function" then
        pcall(Item)
    elseif type(Item)=="table" then
        if type(Item.Destroy)=="function" then pcall(Item.Destroy,Item)
        elseif type(Item.Disconnect)=="function" then pcall(Item.Disconnect,Item)
        elseif type(Item.Cancel)=="function" then pcall(Item.Cancel,Item)
        elseif type(Item.Stop)=="function" then pcall(Item.Stop,Item) end
    end
end

function CleanupRegistry:Add(Item,Method,Key,Group)
    if Item==nil then return Item end

    if Key~=nil then
        local Old=self.Keys[Key]
        if Old and Old~=Item then self:Remove(Old,true) end
        self.Keys[Key]=Item
    end

    self.Items[Item]={Method=Method,Key=Key,Group=Group}
    if Group then
        local Bucket=self.Groups[Group]
        if not Bucket then
            Bucket=setmetatable({}, {__mode="k"})
            self.Groups[Group]=Bucket
        end
        Bucket[Item]=true
    end
    return Item
end

function CleanupRegistry:Release(ItemOrKey)
    local Item=ItemOrKey
    if self.Keys[ItemOrKey] then Item=self.Keys[ItemOrKey] end
    if Item==nil then return end

    local Meta=self.Items[Item]
    if not Meta then return end
    self.Items[Item]=nil
    if Meta.Key and self.Keys[Meta.Key]==Item then self.Keys[Meta.Key]=nil end
    if Meta.Group and self.Groups[Meta.Group] then self.Groups[Meta.Group][Item]=nil end
end

function CleanupRegistry:Remove(ItemOrKey,DoCleanup)
    local Item=ItemOrKey
    if self.Keys[ItemOrKey] then Item=self.Keys[ItemOrKey] end
    if Item==nil then return end

    local Meta=self.Items[Item]
    self:Release(Item)
    if DoCleanup and Meta then CleanupOne(Item,Meta.Method) end
end

function CleanupRegistry:CleanupGroup(Group)
    local Bucket=self.Groups[Group]
    if not Bucket then return end
    local Copy={}
    for Item in pairs(Bucket) do table.insert(Copy,Item) end
    for _,Item in ipairs(Copy) do self:Remove(Item,true) end
    self.Groups[Group]=nil
end

function CleanupRegistry:CleanupAll()
    -- Signals go first so no callback runs while instances are being destroyed.
    local Connections,Rest={},{}
    for Item in pairs(self.Items) do
        if typeof(Item)=="RBXScriptConnection" then table.insert(Connections,Item)
        else table.insert(Rest,Item) end
    end
    for _,Item in ipairs(Connections) do
        if self.Items[Item] then self:Remove(Item,true) end
    end
    for _,Item in ipairs(Rest) do
        if self.Items[Item] then self:Remove(Item,true) end
    end
    table.clear(self.Keys)
    table.clear(self.Groups)
end

Runtime.TrackCleanup=function(Item,Method,Key,Group)
    return CleanupRegistry:Add(Item,Method,Key,Group)
end
Runtime.ReleaseCleanup=function(ItemOrKey)
    CleanupRegistry:Release(ItemOrKey)
end
Runtime.TrackTransient=function(Object,Group)
    if Object then CleanupRegistry:Add(Object,"Destroy",nil,Group or "TransientInstances") end
    return Object
end
Runtime.TrackTween=function(Tween,Key,Group)
    if not Tween then return Tween end
    CleanupRegistry:Add(Tween,"Cancel",Key,Group or "Tweens")
    local Completion
    Completion=Tween.Completed:Connect(function()
        if Completion then
            pcall(function() Completion:Disconnect() end)
            CleanupRegistry:Release(Completion)
            Completion=nil
        end
        CleanupRegistry:Release(Tween)
    end)
    CleanupRegistry:Add(Completion,"Disconnect",nil,"TweenCompletionConnections")
    return Tween
end

if TelemetryConnection then
    table.insert(Runtime.Connections,TelemetryConnection)
    CleanupRegistry:Add(TelemetryConnection,"Disconnect","TelemetryHeartbeat","Connections")
end

-- v5.18.38 Smart Dynamic Island status provider.
-- Read-only display layer: it reports existing runtime/game state and never starts gameplay features.
Runtime.DynamicIslandSmart = Runtime.DynamicIslandSmart or {Tick=0,LastRotate=0,RotateIndex=1}
Runtime.GetBloxRaidClockText = function()
    local Now=os.clock()
    local Cache=Runtime.BloxRaidClockCache
    if type(Cache)=="table" and Now-(tonumber(Cache.At) or 0)<.30 then return Cache.Text end
    local BestText,BestScore=nil,-math.huge
    local PG=Player:FindFirstChildOfClass("PlayerGui")
    if PG then
        for _,Obj in ipairs(PG:GetDescendants()) do
            if (Obj:IsA("TextLabel") or Obj:IsA("TextButton")) and Obj.Visible then
                local Text=tostring(Obj.Text or ""):match("^%s*(.-)%s*$")
                local M,S=Text:match("^(%d+):(%d%d)$")
                M,S=tonumber(M),tonumber(S)
                if M and S and S<=59 then
                    local Total=M*60+S
                    if Total>=0 and Total<=900 then
                        local Name=string.lower(tostring(Obj.Name or ""))
                        local Score=0
                        if Name:find("raid",1,true) then Score+=5 end
                        if Name:find("timer",1,true) or Name:find("time",1,true) then Score+=4 end
                        if Total<=750 then Score+=2 end
                        if Obj.AbsoluteSize.X>=30 and Obj.AbsoluteSize.Y>=10 then Score+=1 end
                        if Score>BestScore then BestScore=Score; BestText=Text end
                    end
                end
            end
        end
    end
    Runtime.BloxRaidClockCache={At=Now,Text=BestText}
    return BestText
end
Runtime.GetSmartIslandStatus = function()
    local S = Runtime.GameProfileState or {}
    local Kind = tostring(Runtime.DetectedGameProfileKind or "Universal")
    local function activeLoop(Name)
        local E=Runtime.AutomationStatus and Runtime.AutomationStatus[Name]
        return E and tostring(E.State or "Idle")~="Idle"
    end
    local function pack(Title,Detail,Progress,StateText,IconKey,Extra)
        local Out={
            Title=tostring(Title or "BananiHub"),
            Detail=tostring(Detail or ""),
            Progress=math.clamp(tonumber(Progress) or 0,0,1),
            State=tostring(StateText or "Active"),
            Kind=Kind,
            IconKey=tostring(IconKey or "idle")
        }
        if type(Extra)=="table" then
            for K,V in pairs(Extra) do Out[K]=V end
        end
        return Out
    end
    -- The notch Pause button stores a snapshot so the island still shows
    -- what is paused even after the original feature toggle is temporarily off.
    if Runtime.DynamicIslandPausedFlag then
        local P=Runtime.DynamicIslandPausedSnapshot or {}
        return {
            Title="Paused • "..tostring(P.Title or Runtime.DynamicIslandPausedLabel or "Task"),
            Detail="Tap Resume to continue",
            Progress=math.clamp(tonumber(P.Progress) or 0,0,1),
            State="Paused",
            Kind=tostring(P.Kind or Kind),
            IconKey=tostring(P.IconKey or "work")
        }
    end

    local function level()
        local N=0
        pcall(function()
            local D=Player:FindFirstChild("Data")
            local L=D and D:FindFirstChild("Level")
            N=L and tonumber(L.Value) or 0
        end)
        return math.floor(tonumber(N) or 0)
    end
    local function parseProgress(Text)
        local A,B=tostring(Text or ""):match("(%d+)%s*/%s*(%d+)")
        A,B=tonumber(A),tonumber(B)
        if A and B and B>0 then return math.clamp(A/B,0,1),A,B end
        return 0,nil,nil
    end
    local function cleanState(Text,Fallback)
        local X=tostring(Text or "")
        if X=="" or X=="nil" then return tostring(Fallback or "Working") end
        return X
    end

    if Kind=="BloxFruits" then
        local L=level()
        if Runtime.BloxThirdSeaProgressionActive or Runtime.BloxSea3ProgressionActive then
            return pack("Sea 3 Progression • Lv."..L,cleanState(Runtime.BloxThirdSeaStatus or Runtime.BloxProgressionStatus,"Working through unlock steps"),0,"Progressing","travel",{DetailLabel="STEP",StatusText="PROGRESSING"})
        end

        local RaidActive=S.BloxSmartRaid==true or Runtime.BloxWasInSmartRaid==true or Runtime.BloxRaidCombatActive==true
        if RaidActive then
            local StartedAt=tonumber(Runtime.BloxRaidStartedAt) or tonumber(Runtime.BloxRaidTeleportDetectedAt)
            local Clock=Runtime.GetBloxRaidClockText and Runtime.GetBloxRaidClockText() or nil
            if not Clock then
                Clock="--:--"
                if StartedAt then
                    local Remaining=math.max(0,750-(os.clock()-StartedAt))
                    Clock=string.format("%02d:%02d",math.floor(Remaining/60),math.floor(Remaining%60))
                end
            end
            local Island=tostring(Runtime.BloxRaidCurrentIsland or Runtime.BloxRaidArrivalIsland or "Raid")
            local IslandNumber=tonumber(Island:match("(%d+)")) or 0
            local Detail=Island.." • "..Clock
            local Target=Runtime.BloxRaidLockedTarget
            if Target and Target.Parent then Detail=Detail.." • "..tostring(Target.Name) end
            local StateText=cleanState(Runtime.BloxRaidStatus,StartedAt and "Fighting" or "Starting")
            return pack("Raid • Lv."..L,Detail,math.clamp(IslandNumber/5,0,1),StateText,"raid",{ProgressMode="progress",ProgressLabel="RAID PROGRESS",DetailLabel="ISLAND"})
        end

        -- v5.18.62: spawned-fruit detection has its own dedicated detector card/notification.
        -- Do NOT let detection or collection hijack the Dynamic Island/notch. When Auto Farm is
        -- running, the notch stays on Auto Farm while the fruit interrupt happens in the background;
        -- otherwise the normal active/idle state below remains visible.

        if Runtime.BloxMaterialFarmActive then
            local Mat=tostring(S.BloxMaterial or "Material")
            local Detail=cleanState(Runtime.BloxCombatLastResult,"Locating material source")
            return pack("Material Farm • "..Mat,Detail,0,"Farming","combat",{DetailLabel="MATERIAL",StatusText="ACTIVATED"})
        end

        if Runtime.BloxAutoFishActive then
            local Bait=tostring(S.BloxFishingBait or "Basic Bait")
            return pack("Auto Fish • "..Bait,cleanState(Runtime.BloxFishingStatus,"Waiting for bite"),0,"Fishing","fish",{DetailLabel="ACTION",StatusText="ACTIVATED"})
        end

        if activeLoop("BloxBoss") or tostring(Runtime.ActiveAutomationName or "")=="BloxBoss" then
            local BossTarget=Runtime.BloxCurrentCombatTarget
            local BossHum=BossTarget and BossTarget.Parent and BossTarget:FindFirstChildOfClass("Humanoid") or nil
            local BossHealth=BossHum and tonumber(BossHum.Health) or nil
            local BossMaxHealth=BossHum and tonumber(BossHum.MaxHealth) or nil
            local BossRatio=(BossHealth and BossMaxHealth and BossMaxHealth>0) and math.clamp(BossHealth/BossMaxHealth,0,1) or 0
            local BossName=(BossTarget and BossTarget.Parent and tostring(BossTarget.Name)) or tostring(S.SelectedBoss or "Nearest Boss")
            return pack("Boss Farm",BossName,BossRatio,cleanState(Runtime.ActiveAutomationState,"Hunting"),"boss",{
                BossHealth=BossHealth,BossMaxHealth=BossMaxHealth,BossName=BossName,DetailLabel="BOSS"
            })
        end

        local SpecialBossName=nil
        for _,LoopName in ipairs({"BloxBossDrop","BloxCakePrince","BloxDoughKing","BloxElite","BloxLaw","BloxFactory"}) do
            if activeLoop(LoopName) then SpecialBossName=LoopName; break end
        end
        if SpecialBossName then
            local BossTarget=Runtime.BloxCurrentCombatTarget
            local BossHum=BossTarget and BossTarget.Parent and BossTarget:FindFirstChildOfClass("Humanoid") or nil
            local BossHealth=BossHum and tonumber(BossHum.Health) or nil
            local BossMaxHealth=BossHum and tonumber(BossHum.MaxHealth) or nil
            local BossRatio=(BossHealth and BossMaxHealth and BossMaxHealth>0) and math.clamp(BossHealth/BossMaxHealth,0,1) or 0
            local Pretty={BloxBossDrop="Boss Drop",BloxCakePrince="Cake Prince",BloxDoughKing="Dough King",BloxElite="Elite Hunter",BloxLaw="Order / Law",BloxFactory="Factory"}
            local BossName=(BossTarget and BossTarget.Parent and tostring(BossTarget.Name)) or tostring(Pretty[SpecialBossName] or "Boss")
            local E=Runtime.AutomationStatus and Runtime.AutomationStatus[SpecialBossName]
            return pack(tostring(Pretty[SpecialBossName] or "Boss Fight"),BossName,BossRatio,cleanState(E and E.State,"Fighting"),"boss",{
                BossHealth=BossHealth,BossMaxHealth=BossMaxHealth,BossName=BossName,DetailLabel="BOSS"
            })
        end

        if Runtime.BloxAutoLevelActive then
            local P,A,B=parseProgress(Runtime.BloxQuestProgress)
            local Q=Runtime.ActiveBloxQuest
            local Enemy=(type(Q)=="table" and (Q.Enemy or Q.EnemyName or Q.Target or Q.Mob)) or nil
            local Detail=Enemy and tostring(Enemy) or cleanState(Runtime.BloxCombatLastResult,"Finding quest target")
            local StateText=cleanState(Runtime.ActiveAutomationState,"Working")
            -- The fruit detector has its own popup. Suppress fruit-interrupt wording from the notch
            -- so detection never appears there, even while Auto Farm temporarily yields movement.
            local FruitInterruptText=(Detail.." "..StateText):lower()
            if FruitInterruptText:find("fruit detected",1,true)
                or FruitInterruptText:find("fruit collection",1,true)
                or FruitInterruptText:find("yielding auto farm",1,true)
