            return pack("Adopt Me • Auto Care",cleanState(E and E.Reason,"Checking pet needs"),0,cleanState(E and E.State,"Caring"),"care",{DetailLabel="TASK",StatusText="ACTIVATED"})
        end
        if A=="AdoptWork" or activeLoop("AdoptWork") then
            local E=Runtime.AutomationStatus and Runtime.AutomationStatus.AdoptWork
