        end
        return pack("Adopt Me","Waiting for a need",0,"Ready","idle")
    end

    -- Remaining supported profiles: translate internal loop names into human-facing notch states.
    -- This keeps the expanded panel tied to what the feature is actually doing instead of showing
    -- raw loop identifiers or fake progress.
    local Active=tostring(Runtime.ActiveAutomationName or "")
    local ActiveState=tostring(Runtime.ActiveAutomationState or "Idle")
    local ActiveReason=tostring(Runtime.ActiveAutomationReason or "")
    local function isActive(Name)
        return Active==Name or activeLoop(Name)
    end
    local function stateOr(Fallback)
        return cleanState(ActiveState,Fallback)
    end
    local function reasonOr(Fallback)
        return cleanState(ActiveReason,Fallback)
    end
    local function semanticExtra(Title,Icon)
        local L=string.lower(tostring(Title or ""))
        Icon=tostring(Icon or "work")
        local Label="DETAIL"
        if Icon=="combat" then Label="TARGET"
        elseif Icon=="travel" then Label="LOCATION"
        elseif Icon=="shield" then Label="STATUS"
        elseif Icon=="care" then Label="TASK"
        elseif L:find("job",1,true) then Label="JOB"
        elseif L:find("aim",1,true) then Label="TARGET"
        elseif L:find("weapon",1,true) or L:find("gun",1,true) then Label="MODE"
        elseif L:find("item",1,true) or L:find("pickup",1,true) then Label="ITEM"
        end
        return {DetailLabel=Label,StatusText="ACTIVATED"}
    end

    if Kind=="BuildABoat" then
        if isActive("BuildABoatGoldFarm") or isActive("BuildABoatSingleRun") then
            local Stage=tostring(S.BuildABoatCurrentStage or "Starting")
            local N=tonumber(Stage:match("(%d+)"))
            local P=N and math.clamp(N/10,0,1) or (Stage:find("Treasure",1,true) and 1 or 0)
            local Status=cleanState(S.BuildABoatLastStatus,"Running treasure route")
            return pack("Build A Boat • Gold Farm",Stage.." • "..Status,P,"Farming","travel",{ProgressMode="progress",ProgressLabel="ROUTE",DetailLabel="STAGE"})
        end
        return pack("Build A Boat For Treasure","Ready for a gold run",0,"Ready","idle")
    end

    if Kind=="Bloxburg" then
        if isActive("BloxburgJob") then
            local Job=tostring(S.BloxburgJob or "Selected Job")
            return pack("Bloxburg • "..Job,reasonOr("Working shift"),0,stateOr("Working"),"work",{DetailLabel="JOB",StatusText="ACTIVATED"})
        elseif isActive("BloxburgMood") then
            return pack("Bloxburg • Needs",reasonOr("Restoring needs"),0,stateOr("Caring"),"care",{DetailLabel="NEED",StatusText="ACTIVATED"})
        elseif isActive("BloxburgBills") then
            return pack("Bloxburg • Bills",reasonOr("Checking bills and paycheck"),0,stateOr("Checking"),"work",{DetailLabel="BILLS",StatusText="ACTIVATED"})
        elseif isActive("BloxburgCook") then
            return pack("Bloxburg • Cooking",reasonOr("Looking for cooking actions"),0,stateOr("Working"),"work",{DetailLabel="ACTION",StatusText="ACTIVATED"})
        elseif isActive("BloxburgGarden") then
            return pack("Bloxburg • Garden",reasonOr("Looking for garden actions"),0,stateOr("Working"),"care",{DetailLabel="ACTION",StatusText="ACTIVATED"})
        elseif isActive("BloxburgClean") then
            return pack("Bloxburg • Cleaning",reasonOr("Looking for cleanup actions"),0,stateOr("Working"),"work",{DetailLabel="ACTION",StatusText="ACTIVATED"})
        elseif isActive("BloxburgDoors") then
            return pack("Bloxburg • Door Assist",reasonOr("Opening nearby doors"),0,stateOr("Active"),"travel",{DetailLabel="ACTION",StatusText="ACTIVATED"})
        elseif isActive("BloxburgSkill") then
            return pack("Bloxburg • "..tostring(S.BloxburgSkill or "Skill"),reasonOr("Training skill"),0,stateOr("Training"),"work",{DetailLabel="SKILL",StatusText="ACTIVATED"})
        end
        return pack("Welcome to Bloxburg","Ready",0,"Ready","idle")
    end

    if Kind=="BasketballLegends" then
        local Map={
            BasketShoot={"Basketball • Auto Green","Timing the shot meter","work"},
            BasketAid={"Basketball • Shooting Aid","Watching shot conditions","work"},
            BasketDunk={"Basketball • Auto Dunk","Moving into dunk range","travel"},
            BasketGuard={"Basketball • Guard","Tracking opponent","shield"},
            BasketSteal={"Basketball • Auto Steal","Watching steal range","combat"},
            BasketBlock={"Basketball • Auto Block","Watching block range","shield"},
            BasketPass={"Basketball • Pass Assist","Finding pass target","work"},
            BasketMagnet={"Basketball • Ball Magnet","Watching loose ball","work"},
            BasketRebound={"Basketball • Rebound","Tracking rebound","work"},
            BasketFaceHolder={"Basketball • Face Holder","Tracking ball holder","work"},
            BasketDrive={"Basketball • Drive","Driving toward hoop","travel"},
            BasketAntiFall={"Basketball • Anti Fall","Protecting position","shield"},
            BasketAntiPush={"Basketball • Anti Push","Protecting position","shield"}
        }
        for Name,Data in pairs(Map) do
            if isActive(Name) then
                local Detail=reasonOr(Data[2])
                if Name=="BasketShoot" then Detail="Shot power "..tostring(math.floor((tonumber(S.BasketShootPower) or .85)*100+0.5)).."%" end
                return pack(Data[1],Detail,0,stateOr("Active"),Data[3],semanticExtra(Data[1],Data[3]))
            end
        end
        return pack("Basketball Legends","Ready",0,"Ready","idle")
    end

    if Kind=="Arsenal" then
        local Map={
            ArsenalAim={"Arsenal • Aim","Finding best visible target","combat"},
            ArsenalTrigger={"Arsenal • Trigger","Watching crosshair target","combat"},
            ArsenalHitbox={"Arsenal • Hitbox","Applying selected hitbox settings","work"},
            ArsenalWeaponMods={"Arsenal • Weapon Mods","Applying current weapon settings","work"},
            ArsenalBhop={"Arsenal • Bunny Hop","Movement assist active","travel"},
            ArsenalPickups={"Arsenal • Pickups","Looking for nearby pickups","travel"},
            ArsenalStrafe={"Arsenal • Strafe","Circling selected target","travel"},
            ArsenalCloseMelee={"Arsenal • Close Melee","Watching close-range target","combat"}
        }
        for Name,Data in pairs(Map) do
            if isActive(Name) then
                local Detail=reasonOr(Data[2])
                if (Name=="ArsenalAim" or Name=="ArsenalStrafe") and S.ArsenalTargetPlayer then Detail=tostring(S.ArsenalTargetPlayer) end
                return pack(Data[1],Detail,0,stateOr("Active"),Data[3],semanticExtra(Data[1],Data[3]))
            end
        end
        return pack("Arsenal","Ready",0,"Ready","idle")
    end

    if Kind=="MVS" then
        local Map={
            MVSAim={"MVS • Aim","Finding visible opponent","combat"},
            MVSProximity={"MVS • Nearby Warning","Watching nearby opponents","shield"},
            MVSHealth={"MVS • Health Warning","Watching your health","shield"},
            MVSRoster={"MVS • Roster","Refreshing team and health data","work"}
        }
        for Name,Data in pairs(Map) do
            if isActive(Name) then return pack(Data[1],reasonOr(Data[2]),0,stateOr("Active"),Data[3],semanticExtra(Data[1],Data[3])) end
        end
        return pack("Murderers VS Sheriffs","Ready",0,"Ready","idle")
    end

    if Kind=="PrisonLife" then
        local Map={
            PrisonGunMods={"Prison Life • Gun Mods","Applying current weapon settings","work"},
            PrisonAutoLoose={"Prison Life • Loose Items","Collecting loose armory items","travel"},
            PrisonAutoArrest={"Prison Life • Auto Arrest","Watching players in arrest range","shield"},
            PrisonMeleeAura={"Prison Life • Melee Aura","Watching close-range players","combat"}
        }
        for Name,Data in pairs(Map) do
            if isActive(Name) then return pack(Data[1],reasonOr(Data[2]),0,stateOr("Active"),Data[3],semanticExtra(Data[1],Data[3])) end
        end
        return pack("Prison Life","Ready",0,"Ready","idle")
    end

    -- Other profiles use the shared automation registry so the notch follows whichever feature
    -- is actually active instead of depending on profile-specific guessed state names.
    if Active~="" and ActiveState~="Idle" then
        local PrettyMap={
            AdaptiveAttack="Adaptive • Attack",AdaptiveFarm="Adaptive • Farm",AdaptiveAutoPickup="Adaptive • Auto Pickup",
            AdaptiveAutoPrompts="Adaptive • Nearby Interactions",CoreNearbyPrompt="Nearby Interaction",CoreKeepTool="Keep Tool Equipped",CoreUseTool="Auto Use Tool"
        }
        local Pretty=PrettyMap[Active] or Active:gsub("(%l)(%u)","%1 %2"):gsub("_"," ")
        local Lower=(Pretty.." "..ActiveState.." "..ActiveReason):lower()
        local Icon="work"
        if Lower:find("travel",1,true) or Lower:find("move",1,true) then Icon="travel"
        elseif Lower:find("boss",1,true) then Icon="boss"
        elseif Lower:find("fish",1,true) then Icon="fish"
        elseif Lower:find("fight",1,true) or Lower:find("combat",1,true) or Lower:find("farm",1,true) then Icon="combat" end
        return pack(Pretty,ActiveReason~="" and ActiveReason or ActiveState,0,ActiveState,Icon,semanticExtra(Pretty,Icon))
    end

    local H=Humanoid()
    local HP=(H and H.MaxHealth and H.MaxHealth>0) and math.floor((H.Health/H.MaxHealth)*100+0.5) or 0
    local GameName=tostring((PlaceInfo and PlaceInfo.Name) or Kind or "BananiHub")
    return pack(GameName,"HP "..HP.."% • "..tostring(LiveTelemetry.FPS or 0).." FPS",HP/100,"Idle","idle")
end

-- v5.18.78 notch event layer: centered level-up composition, refined tab-style reward iconography, unified smooth-motion timing, and late-loading-safe level watcher.
Runtime.DynamicIslandTakeover = Runtime.DynamicIslandTakeover or nil
Runtime.DynamicIslandNotificationQueue = Runtime.DynamicIslandNotificationQueue or {}
Runtime.DynamicIslandQueueActive = Runtime.DynamicIslandQueueActive or nil
Runtime.DynamicIslandQueueSequence = tonumber(Runtime.DynamicIslandQueueSequence) or 0
Runtime.DynamicIslandQueueGeneration = tonumber(Runtime.DynamicIslandQueueGeneration) or 0
Runtime.DynamicIslandQueueMax = math.clamp(tonumber(Runtime.DynamicIslandQueueMax) or 12,4,24)
Runtime.DynamicIslandImportance = {LOW=1,NORMAL=2,HIGH=3,CRITICAL=4}
Runtime.DynamicIslandImportanceName = {[1]="LOW",[2]="NORMAL",[3]="HIGH",[4]="CRITICAL"}
Runtime.DynamicIslandLastLevel = Runtime.DynamicIslandLastLevel or nil
Runtime.DynamicIslandLevelConnection = Runtime.DynamicIslandLevelConnection or nil
Runtime.DynamicIslandPlayerDataConnection = Runtime.DynamicIslandPlayerDataConnection or nil
Runtime.DynamicIslandDataChildConnection = Runtime.DynamicIslandDataChildConnection or nil
Runtime.DynamicIslandResumeSnapshot = Runtime.DynamicIslandResumeSnapshot or nil
Runtime.DynamicIslandResumeSnapshotUntil = tonumber(Runtime.DynamicIslandResumeSnapshotUntil) or 0

Runtime.CopyDynamicIslandSnapshot = function(Source)
    if type(Source)~="table" then return nil end
    local Snapshot={}
    for Key,Value in pairs(Source) do
        local Kind=type(Value)
        if Kind=="string" or Kind=="number" or Kind=="boolean" then Snapshot[Key]=Value end
    end
    return Snapshot
end

-- Blox Fruits level-up audio: prefer the game's own loaded Sound so the takeover matches
-- the real experience instead of hardcoding an unverified community audio ID.
Runtime.LevelUpSFXLastAt = Runtime.LevelUpSFXLastAt or 0
Runtime.LevelUpSFXActive = Runtime.LevelUpSFXActive or nil
Runtime.LevelUpSFXFallbackId = Runtime.LevelUpSFXFallbackId or "rbxassetid://9067086084"

local function NormalizeLevelUpSoundName(Name)
    return tostring(Name or ""):lower():gsub("[%s_%-%.]","")
end

local function FindBloxFruitsLevelUpSound()
    local Roots={
        game:GetService("ReplicatedStorage"),
        game:GetService("SoundService"),
        Player:FindFirstChildOfClass("PlayerGui")
    }
    local Exact={
        ["levelup_proxy"]=true,["level up_proxy"]=true,["level up"]=true,["levelup"]=true,
        ["level up sound"]=true,["levelupsound"]=true
    }
    local Fuzzy=nil
    for _,Root in ipairs(Roots) do
        if Root then
            for _,Obj in ipairs(Root:GetDescendants()) do
                if Obj:IsA("Sound") then
                    local Raw=tostring(Obj.Name or ""):lower()
                    local Compact=NormalizeLevelUpSoundName(Raw)
                    if Exact[Raw] or Compact=="levelup" or Compact=="levelupproxy" or Compact=="levelupsound" then
                        return Obj
                    end
                    if not Fuzzy and Compact:find("levelup",1,true) then Fuzzy=Obj end
                end
            end
        end
    end
    return Fuzzy
end

Runtime.PlayBloxFruitsLevelUpSFX = function()
    if tostring(Runtime.DetectedGameProfileKind or "")~="BloxFruits" then return false,"profile" end
    local Now=os.clock()
    if Now-(tonumber(Runtime.LevelUpSFXLastAt) or 0)<.28 then return false,"debounce" end
    Runtime.LevelUpSFXLastAt=Now

    local Source=nil
    pcall(function() Source=FindBloxFruitsLevelUpSound() end)
    if Source then
        local AlreadyPlaying=false
        pcall(function() AlreadyPlaying=(Source.IsPlaying==true or Source.Playing==true) end)
        if AlreadyPlaying then return true,"game-already-playing" end
    end

    if Runtime.LevelUpSFXActive and Runtime.LevelUpSFXActive.Parent then
        pcall(function() Runtime.LevelUpSFXActive:Stop(); Runtime.LevelUpSFXActive:Destroy() end)
    end

    local Sound
    if Source then
        local OK,Clone=pcall(function() return Source:Clone() end)
        if OK and Clone and Clone:IsA("Sound") then Sound=Clone end
    end
    if not Sound then
        Sound=Instance.new("Sound")
        Sound.Name="BananiLevelUpFallback"
        Sound.SoundId=Runtime.LevelUpSFXFallbackId
        Sound.Volume=.42
        Sound.PlaybackSpeed=1
    else
        Sound.Name="BananiBloxFruitsLevelUpSFX"
        pcall(function() Sound.Looped=false end)
        pcall(function() Sound.TimePosition=0 end)
        pcall(function() Sound.Volume=math.clamp(tonumber(Sound.Volume) or .65,.35,.90) end)
    end
    Sound.Parent=game:GetService("SoundService")
    Runtime.LevelUpSFXActive=Sound
    pcall(function() Sound.TimePosition=0; Sound:Play() end)
    task.delay(4.5,function()
        if Sound and Sound.Parent then pcall(function() Sound:Stop(); Sound:Destroy() end) end
        if Runtime.LevelUpSFXActive==Sound then Runtime.LevelUpSFXActive=nil end
    end)
    return true,Source and "game-sound" or "fallback"
end

local function NormalizeDynamicIslandImportance(Value)
    if type(Value)=="number" then
        local N=math.clamp(math.floor(Value+0.5),1,4)
        return N,Runtime.DynamicIslandImportanceName[N]
    end
    local Key=string.upper(tostring(Value or "NORMAL")):gsub("[%s_%-]","")
    if Key=="CRITICAL" or Key=="URGENT" or Key=="EMERGENCY" then return 4,"CRITICAL" end
    if Key=="HIGH" or Key=="IMPORTANT" or Key=="MILESTONE" then return 3,"HIGH" end
    if Key=="LOW" or Key=="INFO" or Key=="BACKGROUND" then return 1,"LOW" end
    return 2,"NORMAL"
end

local function InferDynamicIslandImportance(Title,Detail,IconKey)
    local Text=(tostring(Title or "").." "..tostring(Detail or "")):lower()
    local Icon=tostring(IconKey or ""):lower()
    if Text:find("critical",1,true) or Text:find("emergency",1,true)
        or Text:find("failed",1,true) or Text:find("failure",1,true)
        or Text:find("error",1,true) or Text:find("disconnected",1,true)
        or Text:find("low health",1,true) then
        return 4,"CRITICAL"
    end
    if Icon=="level" or Icon=="raid" or Icon=="boss" or Icon=="shield"
        or Text:find("milestone",1,true) or Text:find("rare",1,true) then
        return 3,"HIGH"
    end
    if Text:find("tip",1,true) or Text:find("info",1,true) or Text:find("background",1,true) then
        return 1,"LOW"
    end
    return 2,"NORMAL"
end

local function DynamicIslandQueueSort()
    table.sort(Runtime.DynamicIslandNotificationQueue,function(A,B)
        local AP=tonumber(A and A.ImportanceValue) or 2
        local BP=tonumber(B and B.ImportanceValue) or 2
        if AP~=BP then return AP>BP end
        return (tonumber(A and A.Sequence) or 0)<(tonumber(B and B.Sequence) or 0)
    end)
end

local function DynamicIslandDuplicateKey(Item)
    if type(Item)~="table" then return "" end
    return table.concat({
        tostring(Item.Title or ""),
        tostring(Item.Detail or ""),
        tostring(Item.IconKey or ""),
        tostring(Item.Importance or "NORMAL")
    },"\31")
end

local function StartDynamicIslandQueueItem(Item)
    if type(Item)~="table" then return false end
    -- Snapshot at the moment the level-up actually becomes active. A queued level-up may have
    -- waited behind another notification, so an enqueue-time snapshot can be stale.
    if tostring(Item.IconKey or "")=="level" and type(Runtime.GetSmartIslandStatus)=="function" then
        local OK,Previous=pcall(Runtime.GetSmartIslandStatus)
        if OK and type(Previous)=="table" then Item.ResumeSnapshot=Runtime.CopyDynamicIslandSnapshot(Previous) end
    end
    Runtime.DynamicIslandQueueGeneration+=1
    local Generation=Runtime.DynamicIslandQueueGeneration
    Item.Started=os.clock()
    Item.QueueState="ACTIVE"
    Runtime.DynamicIslandTakeover=Item
    Runtime.DynamicIslandQueueActive=Item
    if type(Runtime.DynamicIslandUIOnTakeover)=="function" then
        task.defer(function()
            if Runtime.DynamicIslandQueueGeneration~=Generation or Runtime.DynamicIslandQueueActive~=Item then return end
            pcall(Runtime.DynamicIslandUIOnTakeover,Item)
        end)
    end
    task.delay(math.max(.35,tonumber(Item.Duration) or 2.35),function()
        if Runtime.DynamicIslandQueueGeneration~=Generation or Runtime.DynamicIslandQueueActive~=Item then return end
        -- Once the real Blox Fruits level-up feed is successfully bound to the notch, its
        -- actual on-screen lifetime owns the takeover. The normal queue timer must not cut it off.
        if Item.HoldUntilUIFinish==true and Item.UIFinished~=true then return end
        Runtime.DynamicIslandTakeover=nil
        Runtime.DynamicIslandQueueActive=nil
        if type(Runtime.AdvanceDynamicIslandNotificationQueue)=="function" then
            Runtime.AdvanceDynamicIslandNotificationQueue()
        end
    end)
    return true
end

Runtime.AdvanceDynamicIslandNotificationQueue=function()
    local Active=Runtime.DynamicIslandQueueActive or Runtime.DynamicIslandTakeover
    if Active then
        if Active.HoldUntilUIFinish==true and Active.UIFinished~=true then return false,"active-ui-held" end
        local Age=os.clock()-(tonumber(Active.Started) or os.clock())
        if Age<(tonumber(Active.Duration) or 2.35) then return false,"active" end
        if Runtime.DynamicIslandQueueActive==Active then Runtime.DynamicIslandQueueActive=nil end
        if Runtime.DynamicIslandTakeover==Active then Runtime.DynamicIslandTakeover=nil end
    end
    if #Runtime.DynamicIslandNotificationQueue<=0 then return false,"empty" end
    DynamicIslandQueueSort()
    local Next=table.remove(Runtime.DynamicIslandNotificationQueue,1)
    return StartDynamicIslandQueueItem(Next),"started"
end

Runtime.ClearDynamicIslandNotificationQueue=function(KeepActive)
    table.clear(Runtime.DynamicIslandNotificationQueue)
    if KeepActive==true then return true end
    Runtime.DynamicIslandQueueGeneration+=1
    Runtime.DynamicIslandTakeover=nil
    Runtime.DynamicIslandQueueActive=nil
    Runtime.DynamicIslandResumeSnapshot=nil
    Runtime.DynamicIslandResumeSnapshotUntil=0
    return true
end

Runtime.ReleaseDynamicIslandUIHold=function(CaptureResume)
    local Active=Runtime.DynamicIslandQueueActive or Runtime.DynamicIslandTakeover
    if not Active or Active.HoldUntilUIFinish~=true then return false end
    Active.UIFinished=true
    Active.HoldUntilUIFinish=false
    Active.Duration=0
    if CaptureResume==true and type(Active.ResumeSnapshot)=="table" then
        Runtime.DynamicIslandResumeSnapshot=Runtime.CopyDynamicIslandSnapshot(Active.ResumeSnapshot)
        Runtime.DynamicIslandResumeSnapshotUntil=os.clock()+.65
    end
    task.defer(function()
        if type(Runtime.AdvanceDynamicIslandNotificationQueue)=="function" then Runtime.AdvanceDynamicIslandNotificationQueue() end
    end)
    return true
end

Runtime.GetDynamicIslandNotificationQueue=function()
    local Snapshot={}
    for I,Item in ipairs(Runtime.DynamicIslandNotificationQueue) do
        Snapshot[I]={
            Title=tostring(Item.Title or ""),Detail=tostring(Item.Detail or ""),IconKey=tostring(Item.IconKey or ""),
            Importance=tostring(Item.Importance or "NORMAL"),ImportanceValue=tonumber(Item.ImportanceValue) or 2,
            Duration=tonumber(Item.Duration) or 2.35,Sequence=tonumber(Item.Sequence) or 0,QueueState="WAITING"
        }
    end
    return Snapshot
end

Runtime.GetDynamicIslandQueueStatus=function()
    local Active=Runtime.DynamicIslandQueueActive
    local ActiveText=Active and ((tostring(Active.Importance or "NORMAL")).." • "..tostring(Active.Title or "Event")) or "None"
    local Counts={LOW=0,NORMAL=0,HIGH=0,CRITICAL=0}
    for _,Item in ipairs(Runtime.DynamicIslandNotificationQueue) do
        local K=tostring(Item.Importance or "NORMAL")
        Counts[K]=(Counts[K] or 0)+1
    end
    return "Active: "..ActiveText
        .." • Waiting "..tostring(#Runtime.DynamicIslandNotificationQueue)
        .." [C:"..Counts.CRITICAL.." H:"..Counts.HIGH.." N:"..Counts.NORMAL.." L:"..Counts.LOW.."]"
end

Runtime.TriggerDynamicIslandTakeover = function(Title,Detail,IconKey,Duration,Importance,Options)
    IconKey=tostring(IconKey or "level")
    -- Fruit alerts intentionally never enter the notch queue. They keep their dedicated card.
    if IconKey=="fruit" then return false,"fruit-isolated" end

    local ImportanceValue,ImportanceName
    if Importance==nil then ImportanceValue,ImportanceName=InferDynamicIslandImportance(Title,Detail,IconKey)
    else ImportanceValue,ImportanceName=NormalizeDynamicIslandImportance(Importance) end
    Runtime.DynamicIslandQueueSequence+=1
    local Item={
        Title=tostring(Title or "BANANIHUB"),
        Detail=tostring(Detail or ""),
        IconKey=IconKey,
        Duration=math.clamp(tonumber(Duration) or 2.35,.35,8),
        Progress=1,
        State="Milestone",
        Kind=tostring(Runtime.DetectedGameProfileKind or "Universal"),
        Importance=ImportanceName,
        ImportanceValue=ImportanceValue,
        Sequence=Runtime.DynamicIslandQueueSequence,
        EnqueuedAt=os.clock(),
        QueueState="WAITING"
    }
    if type(Options)=="table" then
        if Options.State~=nil then Item.State=tostring(Options.State) end
        if Options.Progress~=nil then Item.Progress=math.clamp(tonumber(Options.Progress) or 0,0,1) end
        if Options.Kind~=nil then Item.Kind=tostring(Options.Kind) end
    end

    local Key=DynamicIslandDuplicateKey(Item)
    local Active=Runtime.DynamicIslandQueueActive or Runtime.DynamicIslandTakeover
    if Active and DynamicIslandDuplicateKey(Active)==Key then
        return false,"duplicate-active",Active
    end
    for _,Queued in ipairs(Runtime.DynamicIslandNotificationQueue) do
        if DynamicIslandDuplicateKey(Queued)==Key then return false,"duplicate-queued",Queued end
    end

    if not Active then
        if #Runtime.DynamicIslandNotificationQueue==0 then
            StartDynamicIslandQueueItem(Item)
            return true,"started",Item
        end
        table.insert(Runtime.DynamicIslandNotificationQueue,Item)
        DynamicIslandQueueSort()
        while #Runtime.DynamicIslandNotificationQueue>Runtime.DynamicIslandQueueMax do
            table.remove(Runtime.DynamicIslandNotificationQueue,#Runtime.DynamicIslandNotificationQueue)
        end
        Runtime.AdvanceDynamicIslandNotificationQueue()
        local State=(Runtime.DynamicIslandQueueActive==Item) and "started" or "queued"
        return true,State,Item
    end
    local Age=os.clock()-(tonumber(Active.Started) or os.clock())
    if not (Active.HoldUntilUIFinish==true and Active.UIFinished~=true) and Age>=(tonumber(Active.Duration) or 2.35) then
        Runtime.DynamicIslandTakeover=nil
        Runtime.DynamicIslandQueueActive=nil
        table.insert(Runtime.DynamicIslandNotificationQueue,Item)
        DynamicIslandQueueSort()
        while #Runtime.DynamicIslandNotificationQueue>Runtime.DynamicIslandQueueMax do
            table.remove(Runtime.DynamicIslandNotificationQueue,#Runtime.DynamicIslandNotificationQueue)
        end
        Runtime.AdvanceDynamicIslandNotificationQueue()
        local State=(Runtime.DynamicIslandQueueActive==Item) and "started" or "queued"
        return true,State,Item
    end

    table.insert(Runtime.DynamicIslandNotificationQueue,Item)
    DynamicIslandQueueSort()
    while #Runtime.DynamicIslandNotificationQueue>Runtime.DynamicIslandQueueMax do
        table.remove(Runtime.DynamicIslandNotificationQueue,#Runtime.DynamicIslandNotificationQueue)
    end
    return true,"queued",Item
end
Runtime.QueueDynamicIslandTakeover=Runtime.TriggerDynamicIslandTakeover
Runtime.QueueNotchNotification=Runtime.TriggerDynamicIslandTakeover

Runtime.GetDynamicIslandDisplayStatus = function()
    local T=Runtime.DynamicIslandQueueActive or Runtime.DynamicIslandTakeover
    if T then
        if T.HoldUntilUIFinish==true and T.UIFinished~=true then return T end
        local Age=os.clock()-(tonumber(T.Started) or 0)
        if Age<(tonumber(T.Duration) or 2.35) then return T end
        if Runtime.DynamicIslandQueueActive==T then Runtime.DynamicIslandQueueActive=nil end
        if Runtime.DynamicIslandTakeover==T then Runtime.DynamicIslandTakeover=nil end
    end

    -- After a level-up finishes, repaint the exact activity that was visible before it for one
    -- short UI beat. Normal live polling resumes immediately after, so gameplay state stays current.
    local Resume=Runtime.DynamicIslandResumeSnapshot
    if Resume and os.clock()<(tonumber(Runtime.DynamicIslandResumeSnapshotUntil) or 0) then return Resume end
    if Resume then
        Runtime.DynamicIslandResumeSnapshot=nil
        Runtime.DynamicIslandResumeSnapshotUntil=0
    end

    if #Runtime.DynamicIslandNotificationQueue>0 then
        Runtime.AdvanceDynamicIslandNotificationQueue()
        local Next=Runtime.DynamicIslandQueueActive or Runtime.DynamicIslandTakeover
        if Next then return Next end
    end
    return Runtime.GetSmartIslandStatus and Runtime.GetSmartIslandStatus() or nil
end
Runtime.GetDynamicIslandStatus = Runtime.GetDynamicIslandDisplayStatus

Runtime.BindDynamicIslandLevelWatcher = function()
    if Runtime.DynamicIslandLevelConnection then pcall(function() Runtime.DynamicIslandLevelConnection:Disconnect() end); Runtime.DynamicIslandLevelConnection=nil end
    if Runtime.DynamicIslandDataChildConnection then pcall(function() Runtime.DynamicIslandDataChildConnection:Disconnect() end); Runtime.DynamicIslandDataChildConnection=nil end
    local Data=Player:FindFirstChild("Data")
    if not Data then return false end
    local function BindLevel(LevelValue)
        if not LevelValue then return false end
        if Runtime.DynamicIslandLevelConnection then pcall(function() Runtime.DynamicIslandLevelConnection:Disconnect() end) end
        Runtime.DynamicIslandLastLevel=tonumber(LevelValue.Value)
        Runtime.DynamicIslandLevelConnection=Runtime.TrackCleanup(LevelValue:GetPropertyChangedSignal("Value"):Connect(function()
            local New=tonumber(LevelValue.Value)
            local Old=tonumber(Runtime.DynamicIslandLastLevel)
            Runtime.DynamicIslandLastLevel=New
            if tostring(Runtime.DetectedGameProfileKind or "")=="BloxFruits" and New and Old and New>Old then
                Runtime.TriggerDynamicIslandTakeover("LEVEL "..tostring(math.floor(New)),"Level Up!","level",4.50,"HIGH")
            end
        end),"Disconnect","DynamicIslandLevel","Connections")
        return true
    end
    local LevelValue=Data:FindFirstChild("Level")
    if LevelValue then BindLevel(LevelValue) end
    Runtime.DynamicIslandDataChildConnection=Runtime.TrackCleanup(Data.ChildAdded:Connect(function(Child)
        if Child and Child.Name=="Level" then task.defer(function() BindLevel(Child) end) end
    end),"Disconnect","DynamicIslandDataChild","Connections")
    return LevelValue~=nil
end
if Runtime.DynamicIslandPlayerDataConnection then pcall(function() Runtime.DynamicIslandPlayerDataConnection:Disconnect() end) end
Runtime.DynamicIslandPlayerDataConnection=Runtime.TrackCleanup(Player.ChildAdded:Connect(function(Child)
    if Child and Child.Name=="Data" then task.defer(function() Runtime.BindDynamicIslandLevelWatcher() end) end
end),"Disconnect","DynamicIslandPlayerData","Connections")
task.defer(function()
    if not Runtime.BindDynamicIslandLevelWatcher() then
        -- A few executors start the script before replicated Data arrives. Retry briefly without
        -- blocking boot; ChildAdded remains as the long-term fallback.
        for _=1,20 do
            task.wait(.5)
            if Runtime.BindDynamicIslandLevelWatcher() then break end
        end
    end
end)

