local function Character()
    local UniversalState=Runtime and Runtime.UniversalInvisibleState
    if UniversalState and UniversalState.Active and UniversalState.FakeCharacter and UniversalState.FakeCharacter.Parent then
        return UniversalState.FakeCharacter
    end
    return Player.Character
end
local function Humanoid()
    local InvisibleState = Runtime and Runtime.MM2InvisibleState
    if InvisibleState and InvisibleState.ProxyActive then

        if InvisibleState.BlinkInvisibility and InvisibleState.Character and InvisibleState.Character.Parent then
            local RealHumanoid=InvisibleState.Character:FindFirstChildOfClass("Humanoid")
            if RealHumanoid and RealHumanoid.Health>0 then return RealHumanoid end
        end
        local ProxyHumanoid = InvisibleState.ProxyHumanoid
        if ProxyHumanoid and ProxyHumanoid.Parent and ProxyHumanoid.Health > 0 then
            return ProxyHumanoid
        end
    end
    local C = Character()
    return C and C:FindFirstChildOfClass("Humanoid")
end
local function Root()
    local InvisibleState = Runtime and Runtime.MM2InvisibleState
    if InvisibleState and InvisibleState.ProxyActive then
        local ProxyRoot = InvisibleState.ProxyRoot
        if ProxyRoot and ProxyRoot.Parent then
            return ProxyRoot
        end
    end
    local C = Character()
    return C and C:FindFirstChild("HumanoidRootPart")
end
Runtime.ActiveMovementCharacter = function()
    local InvisibleState = Runtime and Runtime.MM2InvisibleState
    if InvisibleState and InvisibleState.ProxyActive then
        local ProxyCharacter = InvisibleState.ProxyCharacter
        if ProxyCharacter and ProxyCharacter.Parent then return ProxyCharacter end
    end
    return Player.Character
end
Runtime.CharacterRaycastIgnore = function(...)
    local Out={}
    local Real=Player.Character
    if Real then table.insert(Out,Real) end
    local Active=Runtime.ActiveMovementCharacter and Runtime.ActiveMovementCharacter() or nil
    if Active and Active~=Real then table.insert(Out,Active) end
    for I=1,select("#",...) do
        local Obj=select(I,...)
        if Obj and not table.find(Out,Obj) then table.insert(Out,Obj) end
    end
    return Out
end
Runtime.ResolveKeyCode = function(Value)
    if typeof(Value) == "EnumItem" then
        return Value.EnumType == Enum.KeyCode and Value.Value ~= 0 and Value or nil
