local function SetAutoWalk(Value)
    AutoWalkEnabled = Value == true
    if AutoWalkConnection then
        AutoWalkConnection:Disconnect()
        AutoWalkConnection = nil
    end
    if not AutoWalkEnabled then
        local H = Humanoid()
        if H then H:Move(Vector3.zero, false) end
        return
    end
    local JumpCooldown = false
    local RayParams = RaycastParams.new()
    RayParams.FilterType = Enum.RaycastFilterType.Exclude

    AutoWalkConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function()
        if not AutoWalkEnabled or Unloaded then return end
        local H, R = Humanoid(), Root()
        local C = Runtime.ActiveMovementCharacter()
        if not H or not R or not C or H.Health <= 0 then return end
        if FreezeEnabled or FlyEnabled or (Runtime.Movement and Runtime.Movement.Owner) then return end

        local Source = (AutoWalkMode == "Character") and R.CFrame or Camera.CFrame
        local Flat = Vector3.new(Source.LookVector.X, 0, Source.LookVector.Z)
        if Flat.Magnitude < 0.01 then return end
        local Direction = Flat.Unit
        H:Move(Direction, false)

        if AutoWalkJump and not JumpCooldown then
            RayParams.FilterDescendantsInstances = {C}
            local Hit = workspace:Raycast(R.Position, Direction * 3, RayParams)
            if Hit and H.FloorMaterial ~= Enum.Material.Air then
                JumpCooldown = true
                H:ChangeState(Enum.HumanoidStateType.Jumping)
                task.delay(0.35, function() JumpCooldown = false end)
            end
        end
    end),"Disconnect","AutoWalkHeartbeat","Connections")
end

Runtime.TweenSpeed = Runtime.TweenSpeed or 80
Runtime.TweenActive = false
Runtime.TweenCancel = false
Runtime.WalkActive = false
Runtime.WalkCancel = false
Runtime.WalkRunId = Runtime.WalkRunId or 0
Runtime.RouteTravelMode = "Walk"

local function CancelTween()
    if Runtime.TweenActive then
        Runtime.TweenCancel = true
    end
    -- Restore synchronously: task.cancel does not unwind a suspended coroutine.
    local TweenRun=Runtime.ActiveTweenRun
    if TweenRun and TweenRun.Cleanup then TweenRun.Cleanup() end
    local Underground=Runtime.UndergroundTravel
    Runtime.UndergroundTravel=nil
    if Underground and Underground.Root==Root() and Underground.Root.Parent then
        pcall(function()
            Underground.Root.CFrame=Underground.Origin
            Underground.Root.AssemblyLinearVelocity=Vector3.zero
            Underground.Root.AssemblyAngularVelocity=Vector3.zero
        end)
    end
    if Runtime.ActiveWalkCleanup then Runtime.ActiveWalkCleanup() end
    if Runtime.WalkActive then
        if Runtime.Navigation then Runtime.Navigation.Cancel() end
        Runtime.WalkCancel = true
        Runtime.WalkRunId += 1
        local H = Humanoid()
        local R = Root()
        if H and R then

            pcall(function() H:MoveTo(R.Position) end)
        end
    end
end
Runtime.CancelTravel = CancelTween

local function TweenRootTo(TargetCFrame, Smooth)
    if Unloaded or typeof(TargetCFrame) ~= "CFrame" then return false end
    local R,H=Root(),Humanoid()
    if not R or not H or H.Health<=0 then return false end
    local Previous=Runtime.ActiveTweenRun
    if Previous and Previous.Cleanup then Previous.Cleanup() end
    local ResetGeneration=Runtime.ResetGeneration
    local Run={Root=R,Humanoid=H,PlatformStand=H.PlatformStand,Noclip=NoclipEnabled}
    Runtime.ActiveTweenRun=Run
    Runtime.TweenActive=true
    Runtime.TweenCancel=false
    function Run.Cleanup()
        if Run.Cleaned then return end
        Run.Cleaned=true
        pcall(function() if H.Parent then H.PlatformStand=Run.PlatformStand end end)
        if not Run.Noclip then pcall(function() SetNoclip(false) end) end
        if Runtime.ActiveTweenRun==Run then
            Runtime.ActiveTweenRun=nil
            Runtime.TweenActive=false
        end
    end
    local OK,Result=pcall(function()
        if not Run.Noclip then SetNoclip(true) end
        H.PlatformStand=true
        local CurrentTarget=TargetCFrame
        local InitialDistance=(CurrentTarget.Position-R.Position).Magnitude
        local MaxDuration=math.clamp((InitialDistance/40)*1.45+20,30,1800)
        local Elapsed,MoveSpeed=0,0
        local LastDistance,LastProgress=InitialDistance,os.clock()
        local LastRotation=R.CFrame.Rotation
        Runtime.TravelFailure=nil
        while Elapsed<MaxDuration do
            if Run.Cleaned or Runtime.TweenCancel or Unloaded or Runtime.ResetGeneration~=ResetGeneration then return false end
            if Root()~=R or Humanoid()~=H or not R.Parent or H.Health<=0 then return false end
            local Dt=RunService.Heartbeat:Wait()
            Elapsed+=Dt
            -- A stop, replacement, death or respawn may happen during Heartbeat:Wait().
            if Run.Cleaned or Runtime.ActiveTweenRun~=Run or Runtime.TweenCancel or Unloaded
                or Runtime.ResetGeneration~=ResetGeneration or Root()~=R or Humanoid()~=H
                or not R.Parent or H.Health<=0 then return false end
            local Provider=Runtime.ActiveTravelTargetProvider
            if type(Provider)=="function" then
                local TargetOK,Value=pcall(Provider)
                if not TargetOK or typeof(Value)~="CFrame" then
                    Runtime.TravelFailure="invalid target"
                    return false
                end
                if (Value.Position-CurrentTarget.Position).Magnitude>1 then
                    LastDistance=(Value.Position-R.Position).Magnitude
                    LastProgress=os.clock()
                end
                CurrentTarget=Value
            end
            local Offset=CurrentTarget.Position-R.Position
            local Distance=Offset.Magnitude
            if Distance<=1.6 then
                R.CFrame=CurrentTarget
                R.AssemblyLinearVelocity=Vector3.zero
                R.AssemblyAngularVelocity=Vector3.zero
                return true
            end
            -- Progress means getting closer, not merely oscillating in place.
            if LastDistance-Distance>=0.75 then
                LastDistance,LastProgress=Distance,os.clock()
            elseif os.clock()-LastProgress>=5 then
                Runtime.TravelFailure="stuck"
                return false
            end
            local Speed=math.max(tonumber(Runtime.TweenSpeed) or 140,1)
            if Smooth~=false then
                local Desired=Speed*math.clamp(Distance/14,0.28,1)
                MoveSpeed+=(Desired-MoveSpeed)*math.clamp(Dt*9,0,1)
            else
                MoveSpeed=Speed
            end
            local Direction=Offset.Unit
            local Flat=Vector3.new(Direction.X,0,Direction.Z)
            if Flat.Magnitude>0.05 then LastRotation=CFrame.lookAt(Vector3.zero,Flat.Unit).Rotation end
            R.CFrame=CFrame.new(R.Position+Direction*math.min(Distance,MoveSpeed*Dt))*LastRotation
            R.AssemblyLinearVelocity=Vector3.zero
            R.AssemblyAngularVelocity=Vector3.zero
        end
        Runtime.TravelFailure="TIMEOUT"
        return false
    end)
    Run.Cleanup()
    if not OK then error(Result,0) end
    return Result==true
end

do
    local Nav = {
        Interval = 0.50, MoveThreshold = 3, ObstacleInterval = 1.0,
        Pending = nil, Busy = false, LastCompute = -math.huge,
        Owner = nil, Serial = 0, Computations = 0, LastDuration = 0
    }
    Runtime.Navigation = Nav

    function Nav.Begin()
        Nav.Serial += 1
        Nav.Owner = Nav.Serial
        Nav.Pending = nil
        return Nav.Owner
    end

    function Nav.Cancel(Owner)
        if Owner == nil or Nav.Owner == Owner then
            Nav.Owner = nil
            Nav.Pending = nil
        end
    end

    function Nav.Request(Owner, Target, Callback)
        if Unloaded or Nav.Owner ~= Owner then return end

        Nav.Pending = {Owner = Owner, Target = Target, Callback = Callback}
        if Nav.Busy then return end
        Nav.Busy = true
        task.spawn(function()
            while Nav.Pending and not Unloaded do
                local Delay = Nav.Interval - (os.clock() - Nav.LastCompute)
                if Delay > 0 then task.wait(Delay) end
                local Request = Nav.Pending
                Nav.Pending = nil
                if not Request or Request.Owner ~= Nav.Owner or Unloaded then continue end
                local R, H = Root(), Humanoid()
                if not R or not H or H.Health <= 0 then continue end
                local Started = os.clock()
                Nav.LastCompute = Started
                local Path
                local Success, Points = pcall(function()
                    Path = game:GetService("PathfindingService"):CreatePath({
                        AgentRadius = math.max(1.5, R.Size.X * 0.5),
                        AgentHeight = math.max(5, H.HipHeight * 2 + R.Size.Y),
                        AgentCanJump = true, AgentCanClimb = true, WaypointSpacing = 3
                    })
                    Path:ComputeAsync(R.Position, Request.Target)
                    if Path.Status ~= Enum.PathStatus.Success then return nil end
                    return Path:GetWaypoints()
                end)
                Nav.LastDuration = os.clock() - Started
                Nav.Computations += 1
                if Unloaded or Request.Owner ~= Nav.Owner or Root() ~= R or Humanoid() ~= H then
                    if Path then Path:Destroy() end
                    continue
                end
                local Usable = Success and type(Points) == "table" and #Points > 1
                local Delivered, Failure = pcall(Request.Callback, Usable and Points or nil, Path)
                if not Delivered then
                    if Path then Path:Destroy() end
                    warn("BANANIHUB | Navigation update failed: " .. tostring(Failure))
                end
            end
            Nav.Busy = false
        end)
    end

    function Nav.NearestSegment(Points, Position)
        local BestIndex, BestDistance = 2, math.huge
        for Index = 2, #Points do
            local A, B = Points[Index - 1].Position, Points[Index].Position
            local Segment = B - A
            local LengthSquared = Segment:Dot(Segment)
            local Alpha = LengthSquared > 0 and math.clamp((Position - A):Dot(Segment) / LengthSquared, 0, 1) or 0
            local Distance = (Position - (A + Segment * Alpha)).Magnitude
            if Distance < BestDistance then BestIndex, BestDistance = Index, Distance end
        end
        return BestIndex, BestDistance
    end
end

Runtime.WalkRootTo = function(TargetCFrame)
    if Unloaded or typeof(TargetCFrame) ~= "CFrame" then return false end
    local R, H = Root(), Humanoid()
    if not R or not H or H.Health <= 0 then return false end
    local Nav = Runtime.Navigation
    local InvalidWalkTarget=false
    local function LiveTarget()
        local Provider = Runtime.ActiveTravelTargetProvider
        if Provider then
            local Ok, Value = pcall(Provider)
            if Ok and typeof(Value) == "CFrame" then return Value end
            InvalidWalkTarget=true
            Runtime.TravelFailure="invalid target"
        end
        return TargetCFrame
    end
    local Owner = Nav.Begin()
    local Generation = Runtime.ResetGeneration
    Runtime.WalkRunId += 1
    local RunId = Runtime.WalkRunId
    Runtime.WalkActive, Runtime.WalkCancel = true, false
    Runtime.WalkRecoveryCount, Runtime.WalkRecoveryReason = 0, "Finding path"
    local Restore = {Fly = FlyEnabled, Freeze = FreezeEnabled, AutoWalk = AutoWalkEnabled,
        AutoRotate = H.AutoRotate, PlatformStand = H.PlatformStand}
    if Restore.AutoWalk then SetAutoWalk(false) end
    if Restore.Fly then StopFly() end
    if Restore.Freeze then SetFreeze(false) end
    H.AutoRotate, H.PlatformStand = true, false
    local Points, Path, BlockConnection
    local Index, Revision, IssuedRevision = 2, 0, -1
    local Blocked, Reached = false, false
    local LastRequest, LastMove = -math.huge, -math.huge
    local RequestedOrigin = R.Position
    local LastProgressPosition, LastProgressTime = R.Position, os.clock()
    local FailureCount, Failure = 0, nil
    local function Active()
        return not Unloaded and Runtime.WalkActive and not Runtime.WalkCancel
            and Runtime.WalkRunId == RunId and Runtime.ResetGeneration == Generation
            and Nav.Owner == Owner and Root() == R and Humanoid() == H and H.Health > 0
    end
    local function DropPath()
        if BlockConnection then BlockConnection:Disconnect() BlockConnection = nil end
        if Path then Path:Destroy() Path = nil end
    end
    local Cleaned=false
    local function CleanupWalk()
        if Cleaned then return end
        Cleaned=true
        Nav.Cancel(Owner)
        DropPath()
        pcall(function()
            if H.Parent then
                if Root()==R and R.Parent then H:MoveTo(R.Position) end
                H.PlatformStand=Restore.PlatformStand
                if Runtime.ResetGeneration==Generation then H.AutoRotate=Restore.AutoRotate end
            end
        end)
        if Runtime.WalkRunId==RunId then
            Runtime.WalkActive,Runtime.WalkCancel=false,false
            Runtime.WalkRecoveryReason=Reached and "Reached" or (Failure or "Cancelled")
            if Runtime.ClearNavigationDrawing then Runtime.ClearNavigationDrawing() end
        end
        if Runtime.ActiveWalkCleanup==CleanupWalk then Runtime.ActiveWalkCleanup=nil end
    end
    Runtime.ActiveWalkCleanup=CleanupWalk
    local function RequestPath()
        LastRequest, RequestedOrigin = os.clock(), R.Position
        Nav.Request(Owner, LiveTarget().Position, function(NewPoints, NewPath)
            if not Active() then if NewPath then NewPath:Destroy() end return end
            if not NewPoints then
                if NewPath then NewPath:Destroy() end
                FailureCount += 1
                Runtime.WalkRecoveryCount = FailureCount
                Runtime.WalkRecoveryReason = "Blocked: no reachable path; retrying"
                return
            end
            local NewIndex, Deviation = Nav.NearestSegment(NewPoints, R.Position)
            if Deviation > 8 then

                if NewPath then NewPath:Destroy() end
                LastRequest = -math.huge
                return
            end
            DropPath()
            Points, Path, Index = NewPoints, NewPath, NewIndex
            Revision += 1
            Blocked, FailureCount = false, 0
            Runtime.WalkRecoveryReason = "Live path"
            BlockConnection = Path.Blocked:Connect(function(BlockedIndex)
                if BlockedIndex >= Index then
                    Blocked = true LastRequest = -math.huge
                    Runtime.WalkRecoveryReason = "Blocked at waypoint " .. tostring(BlockedIndex) .. "; rerouting"
                end
            end)
            if Runtime.RenderNavigationPath then Runtime.RenderNavigationPath(Points, Index, R.Position) end
        end)
    end
    local Success, ErrorMessage = pcall(function()
        RequestPath()
        while Active() do
            local Now, Position = os.clock(), R.Position
            local Target = LiveTarget()
            if InvalidWalkTarget then Failure="Target disappeared"; break end
            if (Position - Target.Position).Magnitude <= 3 then Reached = true break end
            local RecoveryLimit = Runtime.SmartRouteRecovery and Runtime.WalkRecoveryLimit or 0
            if Runtime.RouteFailureRule == "Stop Route" then RecoveryLimit = 0 end
            if FailureCount > RecoveryLimit then
                Failure = "No reachable path"; Runtime.TravelFailure="stuck"; break
            end
            local Moved = (Position - RequestedOrigin).Magnitude >= Nav.MoveThreshold
            if Now - LastRequest >= Nav.Interval
                and (Blocked or Moved or Now - LastRequest >= Nav.ObstacleInterval) then
                RequestPath()
            end
            if Points and not Blocked then
                while Index <= #Points and (Position - Points[Index].Position).Magnitude <= 3 do Index += 1 end
                local Point = Points[Index]
                if Point then
                    if IssuedRevision ~= Revision or Now - LastMove >= 0.10 then
                        if Point.Action == Enum.PathWaypointAction.Jump then H.Jump = true end
                        H:MoveTo(Point.Position)
                        IssuedRevision, LastMove = Revision, Now
                    end
                    if Runtime.UpdateNavigationOrigin then Runtime.UpdateNavigationOrigin(Position, Index) end
                else
                    LastRequest = -math.huge
                end
            elseif Blocked then
                H:MoveTo(Position)
            end

            if (Position - LastProgressPosition).Magnitude >= 0.75 then
                LastProgressPosition, LastProgressTime = Position, Now
            elseif Now - LastProgressTime >= 1.0 and not UserInputService:GetFocusedTextBox() then
                H.Jump = true
                if Now - LastProgressTime >= 5 then Failure = "Movement blocked"; Runtime.TravelFailure="stuck"; break end
            end
            RunService.Heartbeat:Wait()
        end
    end)
    local WasActive = Active()
    CleanupWalk()
    if WasActive and not Unloaded and Runtime.ResetGeneration == Generation and Root() == R then
        if Restore.Freeze then SetFreeze(true) end
        if Restore.Fly then StartFly() end
        if Restore.AutoWalk then SetAutoWalk(true) end
    end
    if not Success then warn("BANANIHUB | Walk failed: " .. tostring(ErrorMessage)) end
    return Success and Reached and WasActive
end

Runtime.GroundSnapTeleport = false
local function SafeTeleport(TargetCFrame)
    if Unloaded or typeof(TargetCFrame) ~= "CFrame" then return false end
    if Runtime.Movement and Runtime.Movement.InternalThread ~= coroutine.running() then
        return Runtime.TravelToCFrame(TargetCFrame, "Teleport", "Location")
    end
    CancelTween()
    local R = Root()
    if not R then return false end
    local Goal = TargetCFrame
    if Runtime.GroundSnapTeleport then
        local Params = RaycastParams.new()
        Params.FilterType = Enum.RaycastFilterType.Exclude
        Params.FilterDescendantsInstances = Runtime.CharacterRaycastIgnore()
        local Hit = workspace:Raycast(
            TargetCFrame.Position + Vector3.new(0, 8, 0),
            Vector3.new(0, -50, 0),
            Params
        )
        if Hit then
            Goal = CFrame.new(Hit.Position + Vector3.new(0, 3.2, 0)) * TargetCFrame.Rotation
        end
    end
    R.CFrame = Goal
    R.AssemblyLinearVelocity = Vector3.zero
    R.AssemblyAngularVelocity = Vector3.zero
    return true
end

Runtime.TravelToCFrame = function(TargetCFrame, Mode, Source, TargetProvider)
    if Unloaded or typeof(TargetCFrame) ~= "CFrame" then return false end
    local ExistingRoot = Root()
    if ExistingRoot and (ExistingRoot.Position - TargetCFrame.Position).Magnitude <= 3 then
        ExistingRoot.AssemblyLinearVelocity = Vector3.zero
        ExistingRoot.AssemblyAngularVelocity = Vector3.zero
        return true
    end
    if Source ~= "Route" and Runtime.RouteRunning and Runtime.StopWaypointRoute then
        Runtime.StopWaypointRoute(true)
    end
    Runtime.TravelRequestId = (Runtime.TravelRequestId or 0) + 1
    local RequestId = Runtime.TravelRequestId
    local ResetGeneration = Runtime.ResetGeneration
    local SelectedMode = tostring(Mode or "Teleport")
    -- Blox Fruits has large ocean volumes between islands. Underground Tween can cross
    -- those volumes and let the server apply water/death state before the route surfaces.
    -- Keep the user's selected setting for other games, but make Blox travel water-safe.
    if Runtime.DetectedGameProfileKind == "BloxFruits" and SelectedMode == "Underground Tween" then
        SelectedMode = "Smooth Tween"
        Runtime.BloxMovementSafetyStatus = "Underground Tween replaced by water-safe Smooth Tween"
    end

    if Runtime.ClearPathPreview then
        pcall(Runtime.ClearPathPreview)
    end

    CancelTween()
    local WaitStart = os.clock()
    while (Runtime.TweenActive or Runtime.WalkActive)
        and os.clock() - WaitStart < 2 and not Unloaded do
        task.wait()
    end

    if Unloaded or RequestId ~= Runtime.TravelRequestId
        or ResetGeneration ~= Runtime.ResetGeneration then return false end
    if Runtime.TweenActive or Runtime.WalkActive then
        Notify("Travel", "The previous trip is still stopping. Try again shortly.")
        return false
    end
    Runtime.ActiveTravelTargetProvider = TargetProvider
    local TravelHumanoid = Humanoid()
    local OldPlatformStand = TravelHumanoid and TravelHumanoid.PlatformStand
    local OldAutoRotate = TravelHumanoid and TravelHumanoid.AutoRotate
    local HadNoclip = NoclipEnabled
    local Success, Reached = pcall(function()
        if SelectedMode == "Underground Tween" then
            local Current = Root()
            if not Current then return false end
            Runtime.ActiveTravelTargetProvider = nil
            Runtime.UndergroundTravel={Root=Current,Origin=Current.CFrame,RequestId=RequestId}
            local Depth = 5.5
            local CruiseY = math.min(Current.Position.Y, TargetCFrame.Position.Y) - Depth
            if CruiseY<=workspace.FallenPartsDestroyHeight+10 then
                Runtime.TravelFailure="UNSAFE_UNDERGROUND_ROUTE"
                return false
            end
            local Down = CFrame.new(Current.Position.X, CruiseY, Current.Position.Z) * Current.CFrame.Rotation
            local Across = CFrame.new(TargetCFrame.Position.X, CruiseY, TargetCFrame.Position.Z) * TargetCFrame.Rotation
            Runtime.ActiveTravelWaypoints={Down.Position,Across.Position,TargetCFrame.Position}
            Runtime.ActiveTravelWaypointIndex=1
            if not TweenRootTo(Down) then return false end
            if RequestId ~= Runtime.TravelRequestId or ResetGeneration ~= Runtime.ResetGeneration then return false end
            Runtime.ActiveTravelWaypointIndex=2
            if not TweenRootTo(Across) then return false end
            if RequestId ~= Runtime.TravelRequestId or ResetGeneration ~= Runtime.ResetGeneration then return false end
            Runtime.ActiveTravelWaypointIndex=3
            Runtime.ActiveTravelTargetProvider = TargetProvider
            return TweenRootTo(TargetCFrame)
        elseif SelectedMode == "Smooth Tween" or SelectedMode == "Tween" then
            Runtime.ActiveTravelWaypointIndex=3
            Runtime.ActiveTravelTargetProvider = TargetProvider
            return TweenRootTo(TargetCFrame,SelectedMode=="Smooth Tween")
        elseif SelectedMode == "Walk" then
            return Runtime.WalkRootTo(TargetCFrame)
        end
        return SafeTeleport(TargetCFrame)
    end)
    local Underground=Runtime.UndergroundTravel
    if Underground and Underground.RequestId==RequestId then
        if Success and Reached==true then
            Runtime.UndergroundTravel=nil
        else
            CancelTween()
        end
    end
    -- A cancelled route must never clear a replacement route's shared state.
    if RequestId~=Runtime.TravelRequestId or ResetGeneration~=Runtime.ResetGeneration then return false end
    if not Success then

        CancelTween()
        Runtime.TweenActive = false
        Runtime.WalkActive = false
        if not HadNoclip then pcall(function() SetNoclip(false) end) end
        if TravelHumanoid and TravelHumanoid.Parent then
            pcall(function()
                TravelHumanoid.PlatformStand = OldPlatformStand
                if Runtime.ResetGeneration == ResetGeneration then
                    TravelHumanoid.AutoRotate = OldAutoRotate
                end
            end)
        end
        warn("BANANIHUB | Travel failed: " .. tostring(Reached))
        Notify("Travel", "Travel stopped after an error. Check the output and try again.")
        Runtime.ActiveTravelTargetProvider=nil
        Runtime.ActiveTravelWaypoints=nil
        Runtime.TravelFailure="ROUTE_FAILED: "..tostring(Reached)
        return false
    end
    Runtime.ActiveTravelTargetProvider = nil
    Runtime.ActiveTravelWaypoints=nil
    return Reached == true
end

do
    -- Shared Movement Controller v2
    -- One owner, one route, one recovery state machine for every game profile.
    local M = {
        Contexts = setmetatable({}, {__mode="k"}), Owner=nil, OwnerContext=nil, Serial=0,
        State="Idle", LastReason="", Phase="Idle", TargetLabel="", ActiveRouteKey=nil,
        LastSuccess=nil, LastObservedPosition=nil, LastObservedAt=0, ExternalTeleportAt=0,
        RouteCooldowns={}, RecoveryCount=0, MaxRecoveryCount=2,
    }
    Runtime.Movement = M
    local RawTravel, RawCancel = Runtime.TravelToCFrame, Runtime.CancelTravel
    local RecoverableStates = {
        [Enum.HumanoidStateType.Seated]=true,
        [Enum.HumanoidStateType.Ragdoll]=true,
        [Enum.HumanoidStateType.FallingDown]=true,
        [Enum.HumanoidStateType.PlatformStanding]=true,
        [Enum.HumanoidStateType.Physics]=true,
    }
    local function Round(N,Step)
        Step=Step or 2
        return math.floor((tonumber(N) or 0)/Step+0.5)*Step
    end
    local function RouteKey(Owner,CF,Mode,Source)
        if typeof(CF)~="CFrame" then return tostring(Owner).."|invalid" end
        local P=CF.Position
        return table.concat({tostring(Owner),tostring(Mode),tostring(Source),Round(P.X),Round(P.Y),Round(P.Z)},"|")
    end
    function M.Context() return M.Contexts[coroutine.running()] end
    function M.Claim(Source)
        M.Guard()
        local Context=M.Context()
        local Owner=Context and Context.Name or tostring(Source or "Manual")
        if M.Owner and (M.Owner~=Owner or M.OwnerContext~=Context or not Context) then
            if Context then error("BANANI_MOVEMENT_BUSY",0) end
            M.Stop()
        end
        M.Owner=Owner
        M.OwnerContext=Context
        if Source~=nil then M.TargetLabel=tostring(Source) end
        return Owner
    end
    function M.Release(Owner)
        if Owner and M.Owner~=Owner then return false end
        M.Owner=nil
        M.OwnerContext=nil
        M.ActiveRouteKey=nil
        M.TargetLabel=""
        M.TargetPosition=nil
        if M.Phase~="Recovering" and M.Phase~="Respawn" then M.SetState("Idle","") end
        return true
    end
    function M.Valid()
        local C=M.Context()
        return not Unloaded and (not C or (not C.Cancelled and C.Valid()))
    end
    function M.Guard()
        if not M.Valid() then error("BANANI_CANCELLED",0) end
    end
    function M.StatusText()
        local Owner=tostring(M.Owner or "None")
        local Phase=tostring(M.Phase or M.State or "Idle")
        local Reason=tostring(M.LastReason or "")
        local Target=tostring(M.TargetLabel or "")
        local R=Root()
        local Distance=R and M.TargetPosition and (R.Position-M.TargetPosition).Magnitude
        local Path=Phase
        if Phase=="Door" then Path="Moving → Door"
        elseif Phase=="Target" or Phase=="Traveling" then Path="Moving → Target"
        elseif Phase=="Recovering" then Path="Moving → Recovering → Target"
        elseif Phase=="Reached" then Path="Moving → Target ✓"
        elseif Phase=="Respawn" then Path="Respawn → Recovering → Target" end
        return "Owner: "..Owner.."\nRoute: "..Path
            ..(Target~="" and ("\nTarget: "..Target) or "")
            ..(Reason~="" and ("\nStatus: "..Reason) or "\nStatus: Ready")
            ..(Distance and ("\nDistance: "..string.format("%.1f",Distance)) or "")
            .."\nRetry: "..tostring(M.RetryCount or 0).."/"..tostring(M.MaxRecoveryCount)
    end
    function M.SetState(Phase,Reason,TargetLabel)
        M.Phase=tostring(Phase or "Idle")
        M.State=(M.Phase=="Target" and "Traveling") or M.Phase
        M.LastReason=tostring(Reason or "")
        if TargetLabel~=nil then M.TargetLabel=tostring(TargetLabel or "") end
        Runtime.MovementDebugText=M.StatusText()
        local Context=M.Context()
        if Runtime.SetAutomationState and Context and Context.Name then
            local AutomationPhase=(M.Phase=="Recovering" or M.Phase=="Respawn") and "Recovering"
                or ((M.Phase=="Idle" or M.Phase=="Reached") and "Working" or "Traveling")
            Runtime.SetAutomationState(Context.Name,AutomationPhase,M.LastReason)
        end
        if Runtime.MovementDebugParagraph and Runtime.MovementDebugParagraph.Set then
            pcall(function()
                Runtime.MovementDebugParagraph:Set({Title="Shared Movement",Content=Runtime.MovementDebugText})
            end)
        end
    end
    function M.RecoverCharacter(Reason,Serial)
        if Serial and Serial~=M.Serial then return false end
        M.RecoveryCount=(tonumber(M.RecoveryCount) or 0)+1
        M.SetState("Recovering",Reason or "Recovering character")
        local Deadline=os.clock()+3.5
        local R,H
        repeat
            if Unloaded or (Serial and Serial~=M.Serial) then return false end
            R,H=Root(),Humanoid()
            if R and H and H.Health>0 then break end
            task.wait(0.08)
        until os.clock()>=Deadline
        if not R or not H or H.Health<=0 then
            M.LastReason="Character did not recover"
            return false
        end
        pcall(function()
            if H.Sit then H.Sit=false end
            if H.PlatformStand then H.PlatformStand=false end
            local StateNow=H:GetState()
            if RecoverableStates[StateNow] then
                H:ChangeState(Enum.HumanoidStateType.GettingUp)
                task.wait()
                H:ChangeState(Enum.HumanoidStateType.Running)
            end
            if R.AssemblyLinearVelocity.Magnitude>180 or R.AssemblyAngularVelocity.Magnitude>90 then
                R.AssemblyLinearVelocity=Vector3.zero
                R.AssemblyAngularVelocity=Vector3.zero
            end
        end)
        M.LastObservedPosition=R.Position
        M.LastObservedAt=os.clock()
        return true
    end
    function M.Stop(Owner)
        for _,Context in pairs(M.Contexts) do
            if (not Owner or Context.Name==Owner) and Context~=M.Context() then Context.Cancelled=true end
        end
        if Owner and M.Owner~=Owner then return end
        local PreviousOwner=M.Owner
        M.Serial+=1
        Runtime.TravelRequestId=(Runtime.TravelRequestId or 0)+1
        RawCancel()
        M.InternalThread=nil
        Runtime.ActiveTravelTargetProvider=nil
        M.Owner=nil
        M.OwnerContext=nil
        M.ActiveRouteKey=nil
        M.RecoveryCount=0
        M.TargetLabel=""
        M.TargetPosition=nil
        M.RetryCount=0
        M.SetState("Idle","")
        Runtime.ActiveTravelWaypoints=nil
        if not Owner or PreviousOwner=="MM2Coins" then
            Runtime.MM2RollingRoute={}
            if Runtime.ClearMM2CoinPath then Runtime.ClearMM2CoinPath() end
        end
        local R,H=Root(),Humanoid()
        if R then R.AssemblyLinearVelocity=Vector3.zero; R.AssemblyAngularVelocity=Vector3.zero end
        if R and H then pcall(function() H:MoveTo(R.Position) end) end
    end
    -- Cancel only the current motion/tween without cancelling the owner's loop context.
    -- Fruit collection uses this to interrupt Auto Farm travel while keeping Auto Farm alive
    -- so it can resume immediately after the fruit disappears or is picked up.
    function M.CancelMotion(Owner)
        if Owner and M.Owner and M.Owner~=Owner then return false end
        M.Serial+=1
        Runtime.TravelRequestId=(Runtime.TravelRequestId or 0)+1
        RawCancel()
        M.InternalThread=nil
        Runtime.ActiveTravelTargetProvider=nil
        if not Owner or not M.Owner or M.Owner==Owner then
            M.Owner=nil
            M.OwnerContext=nil
        end
        M.ActiveRouteKey=nil
        M.RecoveryCount=0
        M.TargetLabel=""
        M.TargetPosition=nil
        M.RetryCount=0
        Runtime.ActiveTravelWaypoints=nil
        M.SetState("Idle","")
        local R,H=Root(),Humanoid()
        if R then
            R.AssemblyLinearVelocity=Vector3.zero
            R.AssemblyAngularVelocity=Vector3.zero
        end
        if R and H then pcall(function() H:MoveTo(R.Position) end) end
        return true
    end
    Runtime.CancelTravel=function() M.Stop() end
    Runtime.TravelToCFrame=function(CF,Mode,Source,Provider)
        M.Guard()
        if typeof(CF)~="CFrame" then return false end
        local Context=M.Context()
        local Owner=Context and Context.Name or (Source or "Manual")
        M.Claim(Owner)
        local R0=Root()
        local H0=Humanoid()
        if R0 and H0 and H0.Health>0 and (R0.Position-CF.Position).Magnitude<=3 then
            M.Owner=Owner; M.TargetLabel=tostring(Source or Mode or "Target")
            M.SetState("Reached","Already within 3 studs")
            if not Context then M.Owner=nil end
            return true
        end
        M.TargetLabel=tostring(Source or Mode or "Target")
        local Key=RouteKey(Owner,CF,Mode,Source)
        local Last=M.LastSuccess
        if Last and Last.Key==Key and os.clock()-(Last.At or 0)<1.25 then
            local R=Root()
            if R and (R.Position-CF.Position).Magnitude<=4 then
                M.SetState("Reached","Same route already completed")
                if not Context then M.Owner=nil end
                return true
            end
        end
        M.ActiveRouteKey=Key
        M.TargetPosition=CF.Position
        M.RecoveryCount=0
        M.SetState("Target","Starting route",M.TargetLabel)
        local Serial=M.Serial
        local Ok,Reached=pcall(function()
            for Attempt=1,M.MaxRecoveryCount+1 do
                M.Guard()
                if M.Serial~=Serial then return false end
                local R,H=Root(),Humanoid()
                if not R or not H or H.Health<=0 then
                    if not M.RecoverCharacter("Waiting for respawn",Serial) then return false end
                    R,H=Root(),Humanoid()
                end
                local StateNow=H and H:GetState()
                if H and (H.Sit or H.PlatformStand or RecoverableStates[StateNow]) then
                    if not M.RecoverCharacter("Recovering from "..tostring(StateNow.Name),Serial) then return false end
                end
                M.RetryCount=Attempt-1
                M.SetState("Target","Attempt "..tostring(Attempt),M.TargetLabel)
                M.InternalThread=coroutine.running()
                Runtime.TravelFailure=nil
                local Result=RawTravel(CF,Mode,Source,Provider)
                if M.InternalThread==coroutine.running() then M.InternalThread=nil end
                if M.Serial~=Serial then return false end
                M.Guard()
                if Result then
                    M.LastSuccess={Key=Key,At=os.clock(),Owner=Owner,Position=CF.Position}
                    local Entry=Runtime.AutomationStatus and Runtime.AutomationStatus[Owner]
                    if Entry then
                        Entry.Target=tostring(Source or "Target")
                        Entry.LastSuccess={At=os.clock(),Action="Movement",Position=CF.Position}
                        Entry.RetryCount=Attempt-1
                    end
                    M.SetState("Reached","Route completed",M.TargetLabel)
                    return true
                end
                local Failure=tostring(Runtime.TravelFailure or "target changed")
                if Failure=="stuck" or Failure=="Movement blocked" then
                    M.SetState("Recovering","Route stopped moving • recovery "..tostring(Attempt),M.TargetLabel)
                    M.RecoverCharacter("Route stopped moving",Serial)
                    task.wait(0.12)
                elseif Failure=="invalid target" then
                    M.SetState("Recovering","Target disappeared",M.TargetLabel)
                    return false
                else
                    M.SetState("Recovering",Failure,M.TargetLabel)
                    task.wait(0.12)
                    if Attempt>=2 then return false end
                end
            end
            return false
        end)
        if M.InternalThread==coroutine.running() then M.InternalThread=nil end
        if M.Serial~=Serial then return false end
        M.ActiveRouteKey=nil
        if not Context and M.Owner==Owner then M.Owner=nil; M.OwnerContext=nil end
        if not Ok then
            M.SetState("Recovering",tostring(Reached),M.TargetLabel)
            error(Reached,0)
        end
        if Reached~=true and M.Owner==Owner then M.SetState("Recovering",M.LastReason~="" and M.LastReason or "Route failed",M.TargetLabel) end
        return Reached==true
    end
    TrackConnection(Player.CharacterRemoving:Connect(function()
        if M.Owner then M.SetState("Respawn","Character removed • waiting for respawn",M.TargetLabel) end
        M.LastObservedPosition=nil
        RawCancel()
    end))
    TrackConnection(Player.CharacterAdded:Connect(function()
        if M.Owner then
            M.SetState("Respawn","Character respawned • re-acquiring route",M.TargetLabel)
            task.delay(0.15,function()
                if not Unloaded and M.Owner then M.RecoverCharacter("Respawn recovery",M.Serial) end
            end)
        end
    end))
    -- Lightweight recovery monitor. It never creates a second movement route; it only repairs
    -- seated/ragdoll/knockback state for the current owner and records unexpected teleports.
    local MovementMonitorAccumulator=0
    TrackConnection(RunService.Heartbeat:Connect(function(DeltaTime)
        if Unloaded or not M.Owner then M.LastObservedPosition=nil; MovementMonitorAccumulator=0; return end
        MovementMonitorAccumulator+=tonumber(DeltaTime) or 0
        if MovementMonitorAccumulator<0.08 then return end
        MovementMonitorAccumulator=0
        local R,H=Root(),Humanoid()
        if not R or not H or H.Health<=0 then return end
        local Now=os.clock()
        local Pos=R.Position
        if M.LastObservedPosition then
            local Delta=(Pos-M.LastObservedPosition).Magnitude
            if Delta>85 and Now-(M.LastObservedAt or 0)<0.45 then
                M.ExternalTeleportAt=Now
                M.SetState("Recovering","External teleport detected • route re-based",M.TargetLabel)
            end
        end
        M.LastObservedPosition=Pos
        M.LastObservedAt=Now
        local StateNow=H:GetState()
        if (H.Sit or H.PlatformStand or RecoverableStates[StateNow])
            and not Runtime.MM2FlingActive and not Runtime.TweenActive then
            pcall(function()
                H.Sit=false; H.PlatformStand=false
                H:ChangeState(Enum.HumanoidStateType.GettingUp)
            end)
        end
        if not Runtime.MM2FlingActive and (R.AssemblyLinearVelocity.Magnitude>260 or R.AssemblyAngularVelocity.Magnitude>125) then
            pcall(function()
                R.AssemblyLinearVelocity=Vector3.zero
                R.AssemblyAngularVelocity=Vector3.zero
            end)
            M.SetState("Recovering","Knockback cancelled",M.TargetLabel)
        end
    end))
end

do
    local Folder, Nodes, Links = nil, {}, {}
    local DrawPoints, DrawIndex, PreviewOwner
    local LastRequest, LastOrigin, StatusAt = -math.huge, nil, 0
    local MaxNodes = 96
    local Yellow, Green, Red = Color3.fromRGB(255, 221, 70), Color3.fromRGB(160, 255, 150), Color3.fromRGB(255, 75, 65)
    Runtime.NavigationBlockedReason = "None"
    local function EnsureFolder()
        if Folder and Folder.Parent then return end
        Folder = Instance.new("Folder")
        Folder.Name = "__BananiPathPreview"
        Folder.Parent = workspace
        Nodes, Links = {}, {}
    end
    local function Node(Index)
        EnsureFolder()
        if Nodes[Index] then return Nodes[Index] end
        local Part = Runtime.TrackTransient(Instance.new("Part"),"TransientParts")
        Part.Name = "RoutePoint"
        Part.Shape, Part.Material = Enum.PartType.Ball, Enum.Material.Neon
        Part.Anchored, Part.CanCollide, Part.CanTouch, Part.CanQuery = true, false, false, false
        Part.CastShadow = false
        Part.Size, Part.Color = Vector3.new(0.25, 0.25, 0.25), Yellow
        Part.Parent = Folder
        local Attachment = Instance.new("Attachment")
        Attachment.Parent = Part
        Nodes[Index] = {Part = Part, Attachment = Attachment}
        return Nodes[Index]
    end
    local function Link(Index)
        if Links[Index] then return Links[Index] end
        local Beam = Instance.new("Beam")
        Beam.Name = "LiveRoute"
        Beam.Width0, Beam.Width1, Beam.Segments = 0.18, 0.18, 3
        Beam.FaceCamera, Beam.LightEmission = true, 1
        Beam.Color = ColorSequence.new(Yellow)
        Beam.Transparency = NumberSequence.new(0.02)
        Beam.Parent = Folder
        Links[Index] = Beam
        return Beam
    end
    Runtime.ClearNavigationDrawing = function()
        DrawPoints, DrawIndex = nil, nil
        for _, Item in ipairs(Nodes) do Item.Part.Transparency = 1 end
        for _, Beam in ipairs(Links) do Beam.Enabled = false end
    end
    Runtime.RenderNavigationPath = function(Points, Index, Origin)
        if Unloaded or not Runtime.PathPreviewEnabled or not Points or #Points == 0 then
            Runtime.ClearNavigationDrawing()
            return
        end
        DrawPoints, DrawIndex = Points, Index
        local Count = 1
        local First = Node(1)
        First.Part.Position = Origin + Vector3.new(0, 0.2, 0)
        First.Part.Size, First.Part.Color, First.Part.Transparency = Vector3.new(0.72, 0.72, 0.72), Green, 0.02
        for PointIndex = Index, math.min(#Points, Index + MaxNodes - 2) do
            Count += 1
            local Item, Point = Node(Count), Points[PointIndex]
            local Size = PointIndex == #Points and 0.8 or (Point.Action == Enum.PathWaypointAction.Jump and 0.55 or 0.25)
            Item.Part.Size = Vector3.new(Size, Size, Size)
            Item.Part.Position = Point.Position + Vector3.new(0, 0.2, 0)
            Item.Part.Color, Item.Part.Transparency = Yellow, 0.05
            local Beam = Link(Count - 1)
            Beam.Attachment0, Beam.Attachment1 = Nodes[Count - 1].Attachment, Item.Attachment
            Beam.Enabled = true
        end
        for Extra = Count + 1, #Nodes do Nodes[Extra].Part.Transparency = 1 end
        for Extra = Count, #Links do Links[Extra].Enabled = false end
    end
    Runtime.RenderTweenLine = function(Origin, Target)
        if not Origin or not Target then return end
        Runtime.ClearNavigationDrawing()
        local Params = RaycastParams.new()
        Params.FilterType = Enum.RaycastFilterType.Exclude
        Params.FilterDescendantsInstances = Runtime.CharacterRaycastIgnore(Folder)
        local Count = 1
        local Segments = math.clamp(math.ceil((Target - Origin).Magnitude / 5), 1, MaxNodes - 1)
        Node(1).Part.Position = Origin + Vector3.new(0, 0.2, 0)
        Node(1).Part.Color, Node(1).Part.Size, Node(1).Part.Transparency = Green, Vector3.new(0.72, 0.72, 0.72), 0.02
        Runtime.NavigationBlockedReason = "None"
        local Hits = {}
        for I = 1, Segments do
            local A = Origin:Lerp(Target, (I - 1) / Segments)
            local B = Origin:Lerp(Target, I / Segments)
            Hits[I] = workspace:Raycast(A, B - A, Params)
        end
        for I = 1, Segments do
            local B = Origin:Lerp(Target, I / Segments)
            Count += 1
            local Item = Node(Count)
            Item.Part.Position, Item.Part.Color, Item.Part.Transparency = B + Vector3.new(0, 0.2, 0), Yellow, 0.05
            local Hit = Hits[I]

            local NearWall = Hit or Hits[I - 1] or Hits[I + 1]
            local Beam = Link(Count - 1)
            Beam.Attachment0, Beam.Attachment1, Beam.Enabled = Nodes[Count - 1].Attachment, Item.Attachment, true
            Beam.Color = ColorSequence.new(NearWall and Red or Yellow)
            if Hit then Runtime.NavigationBlockedReason = "Blocked by " .. Hit.Instance.Name end
        end
        for Extra = Count + 1, #Nodes do Nodes[Extra].Part.Transparency = 1 end
        for Extra = Count, #Links do Links[Extra].Enabled = false end
    end
    Runtime.UpdateNavigationOrigin = function(Position, Index)
        if not Runtime.PathPreviewEnabled then Runtime.ClearNavigationDrawing() return end
        if DrawPoints and Index ~= DrawIndex then
            Runtime.RenderNavigationPath(DrawPoints, Index, Position)
        elseif DrawPoints and Nodes[1] then
            Nodes[1].Part.Position = Position + Vector3.new(0, 0.2, 0)
        end
    end
    Runtime.ClearPathPreview = function()
        Runtime.PathPreviewTarget, Runtime.PathPreviewMode, Runtime.PathPreviewTargetProvider = nil, nil, nil
        if PreviewOwner then Runtime.Navigation.Cancel(PreviewOwner) end
        PreviewOwner, LastOrigin = nil, nil
        Runtime.ClearNavigationDrawing()
    end
    Runtime.RefreshPathPreview = function(TargetCFrame, Mode)
        if Unloaded or not Runtime.PathPreviewEnabled or typeof(TargetCFrame) ~= "CFrame" then
            Runtime.ClearPathPreview()
            return
        end

        if Runtime.WalkActive or Runtime.TweenActive then return end
        Runtime.PathPreviewTargetProvider = nil
        Runtime.PathPreviewTarget = TargetCFrame
        Runtime.PathPreviewMode = Mode or Runtime.WaypointTravelStyle or "Walk"
        PreviewOwner = Runtime.Navigation.Begin()
        LastRequest, LastOrigin = -math.huge, nil
        Runtime.ClearNavigationDrawing()
    end
    TrackConnection(RunService.Heartbeat:Connect(function()
        if Unloaded then return end
        local Nav = Runtime.Navigation
        local Target, Mode = Runtime.PathPreviewTarget, Runtime.PathPreviewMode
        if Runtime.PathPreviewTargetProvider then
            local Ok, Value = pcall(Runtime.PathPreviewTargetProvider)
            if Ok and typeof(Value) == "CFrame" then Target = Value Runtime.PathPreviewTarget = Value end
        end
        local NeedsPreview = Target and Runtime.PathPreviewEnabled and not Runtime.WalkActive and not Runtime.TweenActive
        local StatusInterval = (Runtime.WalkActive or Runtime.TweenActive or NeedsPreview) and 0.20 or 1.00
        if not NeedsPreview and (not Runtime.NavigationParagraph or os.clock() - StatusAt < StatusInterval) then return end
        local R, H = Root(), Humanoid()
        if not R or not H or H.Health <= 0 then Runtime.ClearNavigationDrawing() return end
        if Target and Runtime.PathPreviewEnabled and not Runtime.WalkActive and not Runtime.TweenActive then
            if Mode == "Walk" then
                local Now = os.clock()
                if Now - LastRequest >= Nav.Interval
                    and (not LastOrigin or (R.Position - LastOrigin).Magnitude >= Nav.MoveThreshold
                        or Now - LastRequest >= Nav.ObstacleInterval) then
                    local Owner = PreviewOwner
                    LastRequest, LastOrigin = Now, R.Position
                    Nav.Request(Owner, Target.Position, function(Points, Path)
                        if Path then Path:Destroy() end
                        if Unloaded or PreviewOwner ~= Owner or Nav.Owner ~= Owner then return end
                        if not Points then Runtime.ClearNavigationDrawing() return end
                        local CurrentRoot = Root()
                        if not CurrentRoot then return end
                        local Index = Nav.NearestSegment(Points, CurrentRoot.Position)
                        Runtime.RenderNavigationPath(Points, Index, CurrentRoot.Position)
                    end)
                end
                Runtime.UpdateNavigationOrigin(R.Position, DrawIndex)
            elseif Mode == "Smooth Tween" or Mode == "Tween" then
                if not DrawPoints then
                    Runtime.RenderTweenLine(R.Position, Target.Position)
                else Runtime.UpdateNavigationOrigin(R.Position, 1) end
            else

                if not DrawPoints then
                    Runtime.RenderNavigationPath({{Position = Target.Position}}, 1, R.Position)
                end
            end
        end
        if os.clock() - StatusAt >= StatusInterval and Runtime.NavigationParagraph then
            StatusAt = os.clock()
            Runtime.NavigationParagraph:Set({Title = "⚡ Live Navigation", Content =
                "State: " .. tostring(Runtime.WalkActive and Runtime.WalkRecoveryReason or (Target and "Live preview" or "Idle"))
                .. "\nReason: " .. tostring(Runtime.NavigationBlockedReason or Runtime.WalkRecoveryReason or "Ready")
                .. "\nSolver: " .. (Nav.Busy and "Updating in background" or "Ready")
                .. "\nLast solve: " .. tostring(math.floor(Nav.LastDuration * 1000)) .. " ms"
                .. "\nMovement checked continuously • path requests capped at 2/s"})
        end
    end))
    Runtime.DestroyNavigation = function()
        Runtime.Navigation.Cancel()
        Runtime.ClearPathPreview()
        if Folder then Folder:Destroy() Folder = nil end
        Nodes, Links = {}, {}
    end
end

local function CaptureLightingSnapshot()
    Runtime.LightingSnapshot = {
        Brightness = Lighting.Brightness,
        ClockTime = Lighting.ClockTime,
        FogEnd = Lighting.FogEnd,
        GlobalShadows = Lighting.GlobalShadows,
        EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale,
        EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale
    }
end
local function RefreshLightingState()
    local Base = Runtime.LightingSnapshot or OriginalLighting
    if FullbrightEnabled then
        Lighting.Brightness = 2
        Lighting.ClockTime = 14
        Lighting.FogEnd = 100000
    else
        Lighting.Brightness = Base.Brightness
        Lighting.ClockTime = Base.ClockTime
        Lighting.FogEnd = Base.FogEnd
    end
    Lighting.GlobalShadows = if FullbrightEnabled or LowGraphicsEnabled then false else Base.GlobalShadows
    Lighting.EnvironmentDiffuseScale =
        LowGraphicsEnabled and 0 or Base.EnvironmentDiffuseScale
    Lighting.EnvironmentSpecularScale =
        LowGraphicsEnabled and 0 or Base.EnvironmentSpecularScale
end
local function SetFullbright(Value)
    if Value and not FullbrightEnabled and not LowGraphicsEnabled then
        CaptureLightingSnapshot()
    end
    FullbrightEnabled = Value
    RefreshLightingState()
    if not FullbrightEnabled and not LowGraphicsEnabled then
        Runtime.LightingSnapshot = nil
    end
end

