            PlaceIds = {[537413528] = true},
            NameKeywords = {"build a boat for treasure", "build a boat"},
            ItemKeywords = {"treasure", "gold", "chest", "crate", "block", "seat", "motor", "tool", "candy", "star"},
            RareKeywords = {"golden chest", "legendary chest", "treasure", "royal"},
            BossKeywords = {}
        }
    }

    local BaseItemWords = {
        "item", "loot", "drop", "pickup", "collectible", "weapon", "sword",
        "gun", "fruit", "scroll", "chest", "crate", "key", "potion", "tool",
        "ore", "gem", "coin", "relic", "artifact", "material", "reward"
    }
    local PromptWords = {"take", "pick", "pickup", "collect", "grab", "loot", "equip", "claim", "harvest", "open"}
    local GenericRareWords = {"rare", "epic", "legendary", "mythic", "divine", "celestial", "ancient", "secret"}

    local function Disconnect(Connection)
        if Connection then pcall(function() Connection:Disconnect() end) end
    end

    local function Lower(Value)
        return string.lower(tostring(Value or ""))
    end

    local function ContainsAny(Text, Words)
        local LowerText = Lower(Text)
        for _, Word in ipairs(Words or {}) do
            if Word ~= "" and string.find(LowerText, Lower(Word), 1, true) then return true, Word end
        end
        return false, nil
    end

    local function AppendUnique(Target, Value)
        Value = tostring(Value or "")
        if Value == "" then return end
        for _, Existing in ipairs(Target) do
            if Existing == Value then return end
        end
        table.insert(Target, Value)
    end

    local function PulseAmount(Speed, Amount)
        if not Engine.Settings.GlowPulse then return 0 end
        if Runtime.AFKMode and Runtime.AFKMode.Active then return 0 end
        return math.sin(os.clock() * (Speed or 3)) * (Amount or 0.05)
    end

    local function DistanceFromMe(Position)
        local MyRoot = Root()
        if not MyRoot or not Position then return math.huge end
        return (MyRoot.Position - Position).Magnitude
    end

    local function FindPart(Object)
        if not Object then return nil end
        if Object:IsA("BasePart") then return Object end
        if Object:IsA("Tool") then
            return Object:FindFirstChild("Handle") or Object:FindFirstChildWhichIsA("BasePart", true)
        end
        if Object:IsA("Model") then
            return Object.PrimaryPart
                or Object:FindFirstChild("HumanoidRootPart")
                or Object:FindFirstChild("Head")
                or Object:FindFirstChildWhichIsA("BasePart", true)
        end
        return Object:FindFirstChildWhichIsA("BasePart", true)
    end

    local function IsCharacterObject(Object)
        if not Object then return false end
        local Model = Object:IsA("Model") and Object or Object:FindFirstAncestorOfClass("Model")
        if not Model then return false end
        if Players:GetPlayerFromCharacter(Model) then return true end
        return Model:FindFirstChildOfClass("Humanoid") ~= nil
    end

    local function AddCorner(Object, Radius)
        local Corner = Instance.new("UICorner")
        Corner.CornerRadius = UDim.new(0, Radius or 7)
        Corner.Parent = Object
        return Corner
    end

    local function AddStroke(Object, Color, Thickness, Transparency)
        local Stroke = Instance.new("UIStroke")
        Stroke.Color = Color
        Stroke.Thickness = Thickness or 1
        Stroke.Transparency = Transparency or 0
        Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        Stroke.Parent = Object
        return Stroke
    end

    local function MakeNameplate(RootPart, ObjectName, Color, Prefix)
        local Gui = Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
        Gui.Name = Prefix
        Gui.Adornee = RootPart
        Gui.AlwaysOnTop = true
        Gui.MaxDistance = 0
        Gui.LightInfluence = 0
        Gui.Size = UDim2.fromOffset(190, 50)
        Gui.StudsOffset = Vector3.new(0, 2.7, 0)
        Gui.Parent = RootPart

        local Shadow = Instance.new("Frame")
        Shadow.Name = "Shadow"
        Shadow.AnchorPoint = Vector2.new(0.5, 0.5)
        Shadow.Position = UDim2.new(0.5, 2, 0.5, 3)
        Shadow.Size = UDim2.new(1, -14, 1, -10)
        Shadow.BackgroundColor3 = Color3.new(0, 0, 0)
        Shadow.BackgroundTransparency = 0.55
        Shadow.BorderSizePixel = 0
        Shadow.Parent = Gui
        AddCorner(Shadow, 8)

        local Panel = Instance.new("Frame")
        Panel.Name = "Panel"
        Panel.AnchorPoint = Vector2.new(0.5, 0.5)
        Panel.Position = UDim2.fromScale(0.5, 0.5)
        Panel.Size = UDim2.new(1, -14, 1, -10)
        Panel.BackgroundColor3 = Engine.Settings.PanelColor
        Panel.BackgroundTransparency = 0.18
        Panel.BorderSizePixel = 0
        Panel.Parent = Gui
        AddCorner(Panel, 8)
        local Stroke = AddStroke(Panel, Color, 1.4, 0.08)
        Stroke.Name = "AccentStroke"

        local Accent = Instance.new("Frame")
        Accent.Name = "Accent"
        Accent.Position = UDim2.new(0, 0, 0, 6)
        Accent.Size = UDim2.new(0, 3, 1, -12)
        Accent.BackgroundColor3 = Color
        Accent.BorderSizePixel = 0
        Accent.Parent = Panel
        AddCorner(Accent, 3)

        local Title = Instance.new("TextLabel")
        Title.Name = "Title"
        Title.BackgroundTransparency = 1
        Title.Position = UDim2.new(0, 12, 0, 4)
        Title.Size = UDim2.new(1, -18, 0, 18)
        Title.Font = Enum.Font.GothamBold
        Title.Text = ObjectName
        Title.TextColor3 = Color3.fromRGB(250, 250, 252)
        Title.TextSize = 13
        Title.TextXAlignment = Enum.TextXAlignment.Left
        Title.TextTruncate = Enum.TextTruncate.AtEnd
        Title.Parent = Panel

        local Meta = Instance.new("TextLabel")
        Meta.Name = "Meta"
        Meta.BackgroundTransparency = 1
        Meta.Position = UDim2.new(0, 12, 0, 22)
        Meta.Size = UDim2.new(1, -18, 0, 13)
        Meta.Font = Enum.Font.GothamMedium
        Meta.Text = "..."
        Meta.TextColor3 = Color3.fromRGB(188, 190, 198)
        Meta.TextSize = 10
        Meta.TextXAlignment = Enum.TextXAlignment.Left
        Meta.TextTruncate = Enum.TextTruncate.AtEnd
        Meta.Parent = Panel

        return Gui, Panel, Accent, Stroke, Title, Meta
    end

    local function StyleHighlight(Model, Name, FillColor, OutlineColor, FillTransparency, OutlineTransparency)
        if not Model or not Model.Parent then return nil end
        local Highlight = Model:FindFirstChild(Name)
        if not Highlight or not Highlight:IsA("Highlight") then
            if Highlight then Highlight:Destroy() end
            Highlight = Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
            Highlight.Name = Name
            Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            Highlight.Adornee = Model
            Highlight.Parent = Model
        end
        Highlight.Enabled = true
        Highlight.FillColor = FillColor
        Highlight.OutlineColor = OutlineColor
        Highlight.FillTransparency = math.clamp(FillTransparency, 0, 1)
        Highlight.OutlineTransparency = math.clamp(OutlineTransparency, 0, 1)
        return Highlight
    end

    local function GetProfile()
        return Engine.CurrentProfile or Engine.Profiles.Universal
    end

    function Engine.ApplyProfile(ProfileName, DetectedBy, Quiet)
        local Profile = Engine.Profiles[ProfileName] or Engine.Profiles.Universal
        Engine.CurrentProfile = Profile
        Engine.Settings.ProfileName = Profile.Name
        Engine.ProfileDetectedBy = tostring(DetectedBy or "Manual selection")
        if Profile.Name == "Bloodlines" then
            Engine.Settings.DetectorMode = "Smart"
            Engine.Settings.ItemMaxDistance = math.max(Engine.Settings.ItemMaxDistance, 1400)
        end
        if Engine.ItemESPEnabled then Engine.RequestItemRescan(0.10) end
        if not Quiet then Notify("Game Profile", Profile.Name .. " profile loaded.") end
        return Profile
    end

    function Engine.DetectProfile(Quiet)
        local PlaceId = tonumber(game.PlaceId) or 0
        local GameName = Lower((PlaceInfo and PlaceInfo.Name) or game.Name)
        for Key, Profile in pairs(Engine.Profiles) do
            if Key ~= "Universal" then
                if Profile.PlaceIds and Profile.PlaceIds[PlaceId] then
                    return Engine.ApplyProfile(Key, "Place ID " .. tostring(PlaceId), Quiet)
                end
                local Match = ContainsAny(GameName, Profile.NameKeywords)
                if Match then
                    return Engine.ApplyProfile(Key, "Game name", Quiet)
                end
            end
        end
        return Engine.ApplyProfile("Universal", "Universal fallback", Quiet)
    end

    function Engine.SetWhitelist(Text)
        Engine.Settings.WhitelistText = tostring(Text or "")
        Engine.Settings.Whitelist = {}
        for Token in string.gmatch(Engine.Settings.WhitelistText, "[^,;\n]+") do
            local Clean = Lower(Token):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
            if Clean ~= "" then Engine.Settings.Whitelist[Clean] = true end
        end
        Engine.RefreshFilters("Players")
    end

    function Engine.IsWhitelisted(Target)
        if not Target then return false end
        local List = Engine.Settings.Whitelist
        return List[Lower(Target.Name)] == true
            or List[Lower(Target.DisplayName)] == true
            or List[tostring(Target.UserId)] == true
    end

    local function IsFriend(Target)
        if not Target then return false end
        local UserId = Target.UserId
        if Engine.FriendCache[UserId] ~= nil then return Engine.FriendCache[UserId] end
        local Success, Result = pcall(function() return Player:IsFriendsWith(UserId) end)
        Engine.FriendCache[UserId] = Success and Result == true or false
        return Engine.FriendCache[UserId]
    end

    function Engine.PlayerAllowed(Target)
        if not Target or Target == Player then return false end
        if Engine.Settings.FocusMode == "Items Only" or Engine.Settings.FocusMode == "NPCs Only" then return false end
        if Engine.IsWhitelisted(Target) then return false end
        local Mode = Engine.Settings.PlayerFilterMode
        local SameTeam = Player.Team ~= nil and Target.Team ~= nil and Player.Team == Target.Team
        if Mode == "Friends Only" then return IsFriend(Target) end
        if Mode == "Team Only" then return SameTeam end
        if Mode == "Ignore Teammates" then return not SameTeam end
        if Mode == "Enemies Only" then
            if Player.Team ~= nil and Target.Team ~= nil then return not SameTeam end
            return true
        end
        return true
    end

    function Engine.IsPlayerVisible(Target)
        if not Engine.Settings.OcclusionMode then return true end
        if not Target or not Target.Character then return true end
        local TargetCharacter = Target.Character
        local TargetPart = TargetCharacter:FindFirstChild("Head")
            or TargetCharacter:FindFirstChild("HumanoidRootPart")
        local CurrentCamera = workspace.CurrentCamera or Camera
        if not TargetPart or not CurrentCamera then return true end

        local Now = os.clock()
        local Cached = Engine.OcclusionCache[Target]
        local Interval = Engine.Settings.OcclusionCheckInterval or 0.18
        if Cached and Cached.Character == TargetCharacter
            and (Now - Cached.CheckedAt) < Interval then
            return Cached.Visible
        end

        local Origin = CurrentCamera.CFrame.Position
        local Direction = TargetPart.Position - Origin
        if Direction.Magnitude < 0.05 then return true end

        local Ignore = Runtime.CharacterRaycastIgnore()
        local Visible = false
        for _ = 1, 4 do
            Engine.OcclusionParams.FilterDescendantsInstances = Ignore
            local Result = workspace:Raycast(Origin, Direction, Engine.OcclusionParams)
            if not Result then
                Visible = true
                break
            end
            local Hit = Result.Instance
            if Hit and Hit:IsDescendantOf(TargetCharacter) then
                Visible = true
                break
            end
            if Hit and Hit:IsA("BasePart") and Hit.Transparency >= 0.95 then
                table.insert(Ignore, Hit)
            else
                Visible = false
                break
            end
        end
        Engine.OcclusionCache[Target] = {
            Character = TargetCharacter,
            CheckedAt = Now,
            Visible = Visible
        }
        return Visible
    end

    local function BrightReadableColor(Color)
        if typeof(Color)~="Color3" then return ChamsFillColor end
        local Brightness=math.max(Color.R,Color.G,Color.B)
        if Brightness<0.58 then
            return Color:Lerp(Color3.new(1,1,1),math.clamp((0.58-Brightness)*0.72,0.12,0.34))
        end
        return Color
    end

    Engine.PlayerRoleCache = Engine.PlayerRoleCache or setmetatable({}, {__mode = "k"})

    local function ESPParseColor(Value)
        if typeof(Value)=="Color3" then return Value end
        if typeof(Value)=="BrickColor" then return Value.Color end
        if type(Value)=="string" then
            local Hex=Value:gsub("#","")
            if #Hex==6 and Hex:match("^[%x]+$") then
                local R=tonumber(Hex:sub(1,2),16)
                local G=tonumber(Hex:sub(3,4),16)
                local B=tonumber(Hex:sub(5,6),16)
                if R and G and B then return Color3.fromRGB(R,G,B) end
            end
        end
        return nil
    end

    local function ESPSemanticRoleColor(Label)
        local L=string.lower(tostring(Label or ""))
        if L=="" then return nil end
        if L:find("murder",1,true) or L:find("killer",1,true) or L:find("assassin",1,true) then
            return Color3.fromRGB(255,55,72)
        end
        if L:find("sheriff",1,true) or L:find("hero",1,true) or L:find("guard",1,true)
            or L:find("police",1,true) or L:find("cop",1,true) or L:find("law",1,true) then
            return Color3.fromRGB(55,177,255)
        end
        if L:find("criminal",1,true) or L:find("outlaw",1,true) then
            return Color3.fromRGB(255,94,72)
        end
        if L:find("prison",1,true) or L:find("inmate",1,true) then
            return Color3.fromRGB(255,169,62)
        end
        if L:find("innocent",1,true) or L:find("civilian",1,true) or L:find("survivor",1,true) then
            return Color3.fromRGB(78,235,130)
        end
        if L:find("infect",1,true) or L:find("zombie",1,true) then
            return Color3.fromRGB(184,93,255)
        end
        return nil
    end

    local function ESPAttributeRole(Target)
        if not Target then return nil,nil end
        local Keys={"Role","Class","Faction","Job"}
        local Sources={Target,Target.Character}
        for _,Obj in ipairs(Sources) do
            if Obj then
                for _,Key in ipairs(Keys) do
                    local Ok,Value=pcall(function() return Obj:GetAttribute(Key) end)
                    if Ok and Value~=nil and tostring(Value)~="" then
                        local Label=tostring(Value)
                        local Color=nil
                        for _,ColorKey in ipairs({Key.."Color","RoleColor","ESPColor"}) do
                            local Good,Raw=pcall(function() return Obj:GetAttribute(ColorKey) end)
                            if Good then Color=ESPParseColor(Raw) or Color end
                        end
                        return Label,Color or ESPSemanticRoleColor(Label)
                    end
                    local Child=Obj:FindFirstChild(Key)
                    if Child and (Child:IsA("StringValue") or Child:IsA("ObjectValue")) then
                        local Label=Child:IsA("StringValue") and tostring(Child.Value) or tostring(Child.Value and Child.Value.Name or "")
                        if Label~="" then return Label,ESPSemanticRoleColor(Label) end
                    end
                end
            end
        end
        return nil,nil
    end

    function Engine.GetPlayerESPRoleInfo(Target)
        if not Target then return {Label="Player",Color=nil,Source="Fallback"} end
        local Now=os.clock()
        local Cached=Engine.PlayerRoleCache[Target]
        if Cached and Cached.Character==Target.Character and Cached.Team==Target.Team and (Now-Cached.At)<0.18 then
            return Cached
        end

        local Info={Label="Player",Color=nil,Source="Fallback",At=Now,Character=Target.Character,Team=Target.Team}
        local Kind=tostring(Runtime and Runtime.DetectedGameProfileKind or "")

        if Kind=="MM2" and type(Runtime.MM2RoleForPlayer)=="function" then
            local Ok,Role=pcall(Runtime.MM2RoleForPlayer,Target)
            if Ok and Role then
                Info.Label=tostring(Role)
                Info.Source="Role"
                if type(Runtime.MM2RoleColorForPlayer)=="function" then
                    local Good,Col=pcall(Runtime.MM2RoleColorForPlayer,Target)
                    if Good and typeof(Col)=="Color3" then Info.Color=Col end
                end
                Info.Color=Info.Color or ESPSemanticRoleColor(Info.Label)
            end
        end

        if not Info.Color then
            local Label,Col=ESPAttributeRole(Target)
            if Label then
                Info.Label=Label
                Info.Color=Col
                Info.Source="Role"
            end
        end

        if not Info.Color and Target.Team then
            Info.Label=tostring(Target.Team.Name or "Team")
            Info.Color=Target.Team.TeamColor and Target.Team.TeamColor.Color or nil
            Info.Source="Team"
        elseif not Info.Color and Target.Neutral==false then
            local Ok,Col=pcall(function() return Target.TeamColor.Color end)
            if Ok and typeof(Col)=="Color3" then
                Info.Label=tostring((Target.Team and Target.Team.Name) or Target.TeamColor.Name or "Team")
                Info.Color=Col
                Info.Source="Team"
            end
        end

        Info.Color=Info.Color or ESPSemanticRoleColor(Info.Label)
        if Info.Color then Info.Color=BrightReadableColor(Info.Color) end
        Engine.PlayerRoleCache[Target]=Info
        return Info
    end

    function Engine.GetPlayerESPColor(Target)
        local Info=Engine.GetPlayerESPRoleInfo(Target)
        local Occluded=Engine.Settings.OcclusionMode and Target and not Engine.IsPlayerVisible(Target) or false
        if Info and typeof(Info.Color)=="Color3" then

            return BrightReadableColor(Info.Color),Occluded,Info.Label,Info.Source
        end
        if Occluded then
            return Engine.Settings.OccludedColor,true,"Player","Occlusion"
        end
        return BrightReadableColor(ChamsFillColor),false,"Player","Fallback"
    end

    function Engine.RefreshOcclusion()
        Engine.OcclusionCache = setmetatable({}, {__mode = "k"})
        Engine.RefreshFilters("Players")
    end

    function Engine.IsBoss(Model)
        if not Model or not Model.Parent then return false end
        local Profile = GetProfile()
        local Descriptor = Lower(Model.Name)
        local Attrs = Model:GetAttributes()
        for Name, Value in pairs(Attrs) do
            Descriptor ..= " " .. Lower(Name) .. " " .. Lower(Value)
        end
        local Match = ContainsAny(Descriptor, Profile.BossKeywords or {})
        if Match then return true end
        if Model:GetAttribute("IsBoss") == true or Model:GetAttribute("Boss") == true then return true end
        local H = Model:FindFirstChildOfClass("Humanoid")
        return H ~= nil and H.MaxHealth >= Engine.Settings.BossHealthThreshold
    end

    function Engine.NPCAllowed(Model)
        if Engine.Settings.FocusMode == "Items Only" or Engine.Settings.FocusMode == "Players Only" then return false end
        if Engine.Settings.NPCBossesOnly and not Engine.IsBoss(Model) then return false end
        return true
    end

    function Engine.GetNPCTargetOptions()
        local Options, Map = {}, {}
        for Model, Record in pairs(Engine.NPCRecords) do
            if Model.Parent and Record.Root and Record.Root.Parent and Engine.NPCAllowed(Model) then
                local Label = tostring(Model.Name) .. "  [" .. Model:GetDebugId() .. "]"
                table.insert(Options, Label) Map[Label] = Model
            end
        end
        table.sort(Options)
        Engine.NPCTargetOptionMap = Map
        return Options
    end
    function Engine.SelectNPCTarget(Option)
        local Label = type(Option) == "table" and Option[1] or Option
        local Model = Engine.NPCTargetOptionMap and Engine.NPCTargetOptionMap[Label]
        if not Model or not Model.Parent then return false end
        Engine.SelectedNPCRoot = Model
        local Record = Engine.NPCRecords[Model]
        local CF = Record and Record.Root and CFrame.new(Record.Root.Position)
        if CF and Runtime.PathPreviewEnabled then
            Runtime.RefreshPathPreview(CF, Runtime.ItemTravelMode)
            Runtime.PathPreviewTargetProvider = function() return Engine.GetSelectedNPCCFrame() end
        end
        return true
    end
    function Engine.GetSelectedNPCCFrame()
        local Model, Record = Engine.SelectedNPCRoot, Engine.SelectedNPCRoot and Engine.NPCRecords[Engine.SelectedNPCRoot]
        if not Model or not Model.Parent or not Record or not Record.Root or not Record.Root.Parent then return nil end
        return CFrame.new(Record.Root.Position)
    end
    function Engine.TravelToSelectedNPC()
        local Target = Engine.GetSelectedNPCCFrame()
        if not Target then Notify("NPC Target", "Pick an NPC first.") return end
        local Mode = Runtime.ItemTravelMode or "Walk"
        task.spawn(function() Runtime.TravelToCFrame(Target, Mode, "NPC", function() return Engine.GetSelectedNPCCFrame() end) end)
    end

    function Engine.ItemAllowed()
        return Engine.Settings.FocusMode ~= "Players Only" and Engine.Settings.FocusMode ~= "NPCs Only"
    end

    function Engine.RefreshPlayerHighlights()
        local Pulse = PulseAmount(3.0, 0.055)
        for _, Target in ipairs(Runtime.CachedPlayers()) do
            if Target ~= Player and Target.Character then
                if not Engine.PlayerAllowed(Target) then
                    local Existing = Target.Character:FindFirstChild("BananiPlayerChams")
                    if Existing then Existing:Destroy() end
                else
                    local TargetRoot = Target.Character:FindFirstChild("HumanoidRootPart")
                    local PlayerColor,Occluded = Engine.GetPlayerESPColor(Target)
                    local Highlight = StyleHighlight(
                        Target.Character,
                        "BananiPlayerChams",
                        PlayerColor,
                        Occluded and Engine.Settings.OccludedColor or PlayerColor,
                        math.clamp(ChamsFillTransparency + Pulse,0.05,0.96),
                        Occluded and 0.03 or ChamsOutlineTransparency
                    )
                    if Highlight then Highlight.Enabled = ChamsEnabled and TargetRoot~=nil end
                end
            end
        end
    end

    function Engine.SetChams(Value)
        ChamsEnabled = Value == true
        Disconnect(ChamsConnection)
        ChamsConnection = nil
        if not ChamsEnabled then
            for _, Target in ipairs(Runtime.CachedPlayers()) do
                local C = Target.Character
                local Existing = C and C:FindFirstChild("BananiPlayerChams")
                if Existing then Existing:Destroy() end
            end
            return
        end
        Engine.RefreshPlayerHighlights()
        local Accumulator = 0
        ChamsConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
            if not ChamsEnabled or Unloaded then return end
            Accumulator += Delta
            if Accumulator < Engine.Settings.UpdateInterval*Runtime.GetVisualUpdateScale() then return end
            Accumulator = 0
            Engine.RefreshPlayerHighlights()
        end),"Disconnect","ChamsHeartbeat","Connections")
    end

    local function ClearNPCRecord(Model)
        local Record = Engine.NPCRecords[Model]
        if Record then
            if Record.Highlight then pcall(function() Record.Highlight:Destroy() end) end
            if Record.Gui then pcall(function() Record.Gui:Destroy() end) end
            Engine.NPCRecords[Model] = nil
        end
        if Model and Model.Parent then
            local H = Model:FindFirstChild("BananiNPCChams")
            if H then H:Destroy() end
            local R = FindPart(Model)
            local G = R and R:FindFirstChild("BananiNPCPlate")
            if G then G:Destroy() end
        end
    end

    local function EnsureNPC(Model)
        if not NPCChamsEnabled or not Model or not Model.Parent or not IsNPC(Model) then return end
        if not Engine.NPCAllowed(Model) then ClearNPCRecord(Model) return end
        local H = Model:FindFirstChildOfClass("Humanoid")
        if H and H.Health <= 0 then return end
        local R = FindPart(Model)
        if not R then return end
        local Record = Engine.NPCRecords[Model]
        if not Record then
            local Color = Engine.Settings.NPCColor
            local Highlight = StyleHighlight(Model, "BananiNPCChams", Color, Color3.new(1, 1, 1), 0.78, 0.08)
            local Prefix = Engine.IsBoss(Model) and "BOSS  •  " or "NPC  •  "
            local Gui, Panel, Accent, Stroke, Title, Meta = MakeNameplate(R, Prefix .. Model.Name, Color, "BananiNPCPlate")
            Record = {
                Model = Model, Root = R, Highlight = Highlight, Gui = Gui,
                Panel = Panel, Accent = Accent, Stroke = Stroke,
                Title = Title, Meta = Meta
            }
            Engine.NPCRecords[Model] = Record
        end
        return Record
    end

    local function UpdateNPCs()
        local Pulse = PulseAmount(2.6, 0.05)
        local ToClear = {}
        for Model, Record in pairs(Engine.NPCRecords) do
            if not Model.Parent or not Record.Root or not Record.Root.Parent or not Engine.NPCAllowed(Model) then
                table.insert(ToClear, Model)
            else
                local H = Model:FindFirstChildOfClass("Humanoid")
                if H and H.Health <= 0 then
                    table.insert(ToClear, Model)
                else
                    local Distance = DistanceFromMe(Record.Root.Position)
                    local Visible = NPCChamsEnabled
                    local Color = Engine.Settings.NPCColor
                    if Record.Gui then Record.Gui.Enabled = Visible end
                    if Record.Highlight then
                        Record.Highlight.Enabled = Visible
                        Record.Highlight.FillColor = Color
                        Record.Highlight.OutlineColor = Color3.new(1, 1, 1)
                        Record.Highlight.FillTransparency = math.clamp(0.78 + Pulse, 0.62, 0.90)
                    end
                    if Record.Accent then Record.Accent.BackgroundColor3 = Color end
                    if Record.Stroke then Record.Stroke.Color = Color end
                    if Record.Title then Record.Title.Text = (Engine.IsBoss(Model) and "BOSS  •  " or "NPC  •  ") .. Model.Name end
                    if Record.Meta then
                        local HealthText = H and ("HP " .. math.floor(H.Health) .. "/" .. math.floor(H.MaxHealth) .. "  •  ") or ""
                        Record.Meta.Text = HealthText .. math.floor(Distance + 0.5) .. " studs"
                    end
                end
            end
        end
        for _, Model in ipairs(ToClear) do ClearNPCRecord(Model) end
    end

    function Engine.SetNPCChams(Value)
        NPCChamsEnabled = Value == true
        Disconnect(NPCChamsConnection)
        Disconnect(Engine.NPCAddedConnection)
        Disconnect(Engine.NPCHeartbeatConnection)
        NPCChamsConnection = nil
        Engine.NPCAddedConnection = nil
        Engine.NPCHeartbeatConnection = nil
        if not NPCChamsEnabled then
            local Models = {}
            for Model in pairs(Engine.NPCRecords) do table.insert(Models, Model) end
            for _, Model in ipairs(Models) do ClearNPCRecord(Model) end
            return
        end

        task.spawn(function()
            local Descendants = workspace:GetDescendants()
            for Index, Object in ipairs(Descendants) do
                if not NPCChamsEnabled or Unloaded then return end
                if Object:IsA("Model") and IsNPC(Object) then EnsureNPC(Object) end
                if Index % 400 == 0 then task.wait() end
            end
        end)
        Engine.NPCAddedConnection = Runtime.TrackCleanup(workspace.DescendantAdded:Connect(function(Object)
            if NPCChamsEnabled and Object:IsA("Model") then task.defer(EnsureNPC, Object) end
        end),"Disconnect","NPCDescendantAdded","Connections")
        local Accumulator = 0
        NPCChamsConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
            if not NPCChamsEnabled or Unloaded then return end
            Accumulator += Delta
            if Accumulator < Engine.Settings.UpdateInterval*Runtime.GetVisualUpdateScale() then return end
            Accumulator = 0
            UpdateNPCs()
        end),"Disconnect","NPCChamsHeartbeat","Connections")
        Engine.NPCHeartbeatConnection = NPCChamsConnection
    end

    local function ClearHitboxFor(Target)
        local C = Target and Target.Character
        local R = C and C:FindFirstChild("HumanoidRootPart")
        if not R then return end
        local Box = R:FindFirstChild("BananiHitbox")
        local Glow = R:FindFirstChild("BananiHitboxGlow")
        if Box then Box:Destroy() end
        if Glow then Glow:Destroy() end
    end

    local function ClearHitboxes()
        for _, Target in ipairs(Runtime.CachedPlayers()) do ClearHitboxFor(Target) end
    end

    local function EnsureHitbox(Target)
        if Target == Player or not Target.Character or not Engine.PlayerAllowed(Target) then
            ClearHitboxFor(Target)
            return
        end
        local R = Target.Character:FindFirstChild("HumanoidRootPart")
        if not R then return end
        local Box = R:FindFirstChild("BananiHitbox")
        if not Box then
            Box = Instance.new("BoxHandleAdornment")
            Box.Name = "BananiHitbox"
            Box.Adornee = R
            Box.AlwaysOnTop = true
            Box.ZIndex = 10
            Box.Size = Vector3.new(math.max(R.Size.X, 4.2), math.max(R.Size.Y, 6.4), math.max(R.Size.Z, 2.7))
            Box.Transparency = 0.82
            Box.Color3 = Engine.Settings.HitboxColor
            Box.Parent = R
        end
        local Glow = R:FindFirstChild("BananiHitboxGlow")
        if not Glow then
            Glow = Instance.new("BoxHandleAdornment")
            Glow.Name = "BananiHitboxGlow"
            Glow.Adornee = R
            Glow.AlwaysOnTop = true
            Glow.ZIndex = 9
            Glow.Size = Box.Size + Vector3.new(0.20, 0.20, 0.20)
            Glow.Transparency = 0.94
            Glow.Color3 = Color3.new(1, 1, 1)
            Glow.Parent = R
        end
        local Distance = DistanceFromMe(R.Position)
        local Visible = Distance <= Engine.Settings.MaxDistance
        Box.Visible = Visible
        Glow.Visible = Visible
        local RoleInfo=Engine.GetPlayerESPRoleInfo(Target)
        local ESPColor,Occluded=Engine.GetPlayerESPColor(Target)
        Box.Color3 = (RoleInfo and RoleInfo.Color) and ESPColor or Engine.Settings.HitboxColor
        Glow.Color3 = Occluded and Engine.Settings.OccludedColor or ESPColor
        Box.Transparency = math.clamp(0.82 + PulseAmount(3.5, 0.05), 0.72, 0.90)
    end

    function Engine.SetHitboxes(Value)
        HitboxEnabled = Value == true
        Disconnect(HitboxConnection)
        HitboxConnection = nil
        if not HitboxEnabled then
            ClearHitboxes()
            return
        end
        local Accumulator = 0
        for _, Target in ipairs(Runtime.CachedPlayers()) do EnsureHitbox(Target) end
        HitboxConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
            if not HitboxEnabled or Unloaded then return end
            Accumulator += Delta
            if Accumulator < Engine.Settings.UpdateInterval*Runtime.GetVisualUpdateScale() then return end
            Accumulator = 0
            for _, Target in ipairs(Runtime.CachedPlayers()) do EnsureHitbox(Target) end
        end),"Disconnect","HitboxHeartbeat","Connections")
    end

    local function GetRarity(Source)
        local Candidates = {Source}
        local Model = Source and Source:FindFirstAncestorOfClass("Model")
        if Model and Model ~= Source then table.insert(Candidates, Model) end
        for _, Object in ipairs(Candidates) do
            if Object then
                for _, AttributeName in ipairs({"Rarity", "Tier", "Quality"}) do
                    local Value = Object:GetAttribute(AttributeName)
                    if Value ~= nil and tostring(Value) ~= "" then return tostring(Value) end
                end
                local ValueObject = Object:FindFirstChild("Rarity") or Object:FindFirstChild("Tier") or Object:FindFirstChild("Quality")
                if ValueObject and ValueObject:IsA("ValueBase") then return tostring(ValueObject.Value) end
            end
        end
        return ""
    end

    local function RarityColor(Rarity)
        local Value = Lower(Rarity)
        if Value:find("divine", 1, true) or Value:find("mythic", 1, true) or Value:find("celestial", 1, true) then
            return Color3.fromRGB(255, 82, 214)
        elseif Value:find("legend", 1, true) or Value:find("ancient", 1, true) then
            return Color3.fromRGB(255, 195, 54)
        elseif Value:find("epic", 1, true) then
            return Color3.fromRGB(177, 92, 255)
        elseif Value:find("rare", 1, true) then
            return Color3.fromRGB(74, 194, 255)
        elseif Value:find("uncommon", 1, true) then
            return Color3.fromRGB(86, 238, 132)
        elseif Value:find("common", 1, true) then
            return Color3.fromRGB(225, 228, 235)
        end
        return Engine.Settings.ItemColor
    end

    local function AddDescriptorBits(Bits, Object, LimitChildren)
        if not Object then return end
        AppendUnique(Bits, Object.Name)
        local Success, Attributes = pcall(function() return Object:GetAttributes() end)
        if Success then
            for Name, Value in pairs(Attributes) do
                AppendUnique(Bits, Name)
                if type(Value) == "string" or type(Value) == "number" then AppendUnique(Bits, Value) end
            end
        end
        if Object:IsA("ProximityPrompt") then
            AppendUnique(Bits, Object.ActionText)
            AppendUnique(Bits, Object.ObjectText)
        end
        local Seen = 0
        if LimitChildren and Object.GetDescendants then
            for _, Child in ipairs(Object:GetDescendants()) do
                if Seen >= LimitChildren then break end
                if Child:IsA("ProximityPrompt") then
                    AppendUnique(Bits, Child.ActionText)
                    AppendUnique(Bits, Child.ObjectText)
                    Seen += 1
                elseif Child:IsA("StringValue") then
                    AppendUnique(Bits, Child.Name)
                    AppendUnique(Bits, Child.Value)
                    Seen += 1
                elseif Child:IsA("TextLabel") or Child:IsA("TextButton") then
                    AppendUnique(Bits, Child.Text)
                    Seen += 1
                elseif Child:IsA("ObjectValue") and Child.Value then
                    AppendUnique(Bits, Child.Name)
                    AppendUnique(Bits, Child.Value.Name)
                    Seen += 1
                end
            end
        end
    end

    local function BuildDescriptor(Object, Candidate)
        local Bits = {}
        AddDescriptorBits(Bits, Object, 8)
        if Candidate and Candidate ~= Object then AddDescriptorBits(Bits, Candidate, 20) end
        local Parent = Candidate and Candidate.Parent or Object and Object.Parent
        if Parent then AddDescriptorBits(Bits, Parent, 4) end
        return table.concat(Bits, " ")
    end

    local function ProfileItemWords()
        local Words = table.clone(BaseItemWords)
        for _, Word in ipairs(GetProfile().ItemKeywords or {}) do table.insert(Words, Word) end
        return Words
    end

    local function ShouldInspectObject(Object)
        if not Object or not Object.Parent then return false end
        if Object:IsA("Tool") or Object:IsA("ProximityPrompt") then return true end
        if Engine.Settings.DetectorMode ~= "Smart" then return false end
        if not (Object:IsA("Model") or Object:IsA("BasePart")) then return false end
        local Quick = Object.Name .. " " .. (Object.Parent and Object.Parent.Name or "")
        local Match = ContainsAny(Quick, ProfileItemWords())
        if Match then return true end
        if Object:GetAttribute("Rarity") ~= nil or Object:GetAttribute("Tier") ~= nil
            or Object:GetAttribute("ItemName") ~= nil or Object:GetAttribute("ItemId") ~= nil then
            return true
        end
        return false
    end

    local function CandidateFrom(Object)
        local Mode = Engine.Settings.DetectorMode
        if Object:IsA("Tool") then
            local Descriptor = BuildDescriptor(Object, Object)
            return Object, Object.Name, Descriptor
        end
        if Object:IsA("ProximityPrompt") and Mode ~= "Tools Only" then
            local Action = Object.ActionText or ""
            local ObjectText = Object.ObjectText or ""
            local ParentName = Object.Parent and Object.Parent.Name or ""
            local Candidate = Object:FindFirstAncestorOfClass("Tool")
                or Object:FindFirstAncestorOfClass("Model")
                or Object.Parent
            local Descriptor = BuildDescriptor(Object, Candidate)
            local ProfileMatch = ContainsAny(Descriptor, GetProfile().ItemKeywords or {})
            if Mode == "Tools + Prompts"
                or ContainsAny(Action, PromptWords)
                or ContainsAny(ObjectText, ProfileItemWords())
                or ContainsAny(ParentName, ProfileItemWords())
                or ProfileMatch then
                local Display = ObjectText ~= "" and ObjectText or ParentName
                return Candidate, Display, Descriptor
            end
        end
        if Mode == "Smart" and ShouldInspectObject(Object) then
            local Candidate = Object
            local Descriptor = BuildDescriptor(Object, Candidate)
            if ContainsAny(Descriptor, ProfileItemWords()) then
                return Candidate, Object.Name, Descriptor
            end
        end
        return nil, nil, nil
    end

    local function PassesItemFilter(Name, Descriptor)
        local Combined = Lower((Name or "") .. " " .. (Descriptor or ""))
        local Filter = Lower(Engine.Settings.ItemFilter)
        if Filter ~= "" and string.find(Combined, Filter, 1, true) == nil then
            return false
        end
        local Blocked = ContainsAny(Combined, Engine.Settings.ItemBlacklist)
        if Blocked then return false end
        if #Engine.Settings.ItemWhitelist > 0 then
            local Allowed = ContainsAny(Combined, Engine.Settings.ItemWhitelist)
            if not Allowed then return false end
        end
        return true
    end

    local function ParseItemKeywords(Text)
        local Keywords = {}
        local Seen = {}
        for Token in string.gmatch(tostring(Text or ""), "[^,;\n]+") do
            local Clean = Lower(Token):gsub("^%s+", ""):gsub("%s+$", "")
            if Clean ~= "" and not Seen[Clean] then
                Seen[Clean] = true
                table.insert(Keywords, Clean)
            end
        end
        return Keywords
    end

    function Engine.UpdateItemCollectorStatus(State)
        local Allow = #Engine.Settings.ItemWhitelist > 0
            and table.concat(Engine.Settings.ItemWhitelist, ", ") or "Everything"
        local Ignore = #Engine.Settings.ItemBlacklist > 0
            and table.concat(Engine.Settings.ItemBlacklist, ", ") or "Nothing"
        local Refresh = Engine.Settings.AutoRescanEnabled
            and (tostring(Engine.Settings.AutoRescanSeconds) .. " seconds") or "Off"
        local Content = "Status: " .. tostring(State or "Ready")
            .. "\nFound: " .. tostring(Engine.ItemCount)
            .. "\nCollect: " .. Allow
            .. "\nIgnore: " .. Ignore
            .. "\nAuto refresh: " .. Refresh
        for _, Paragraph in pairs({Runtime.ItemCollectorStatusParagraph}) do
            if Paragraph and Paragraph.Set then
                pcall(function()
                    Paragraph:Set({Title = "🍌 Smart Item Collector", Content = Content})
                end)
            end
        end
    end

    function Engine.SetItemWhitelist(Text)
        Engine.Settings.ItemWhitelistText = tostring(Text or "")
        Engine.Settings.ItemWhitelist = ParseItemKeywords(Text)
        Engine.UpdateItemCollectorStatus("Filters updated")
        if Engine.ItemESPEnabled then Engine.RequestItemRescan(0.10) end
    end

    function Engine.SetItemBlacklist(Text)
        Engine.Settings.ItemBlacklistText = tostring(Text or "")
        Engine.Settings.ItemBlacklist = ParseItemKeywords(Text)
        Engine.UpdateItemCollectorStatus("Filters updated")
        if Engine.ItemESPEnabled then Engine.RequestItemRescan(0.10) end
    end

    function Engine.SetAutoRescan(Value)
        Engine.Settings.AutoRescanEnabled = Value == true
        Engine.AutoRescanAccumulator = 0
        Engine.UpdateItemCollectorStatus(Engine.Settings.AutoRescanEnabled and "Auto refresh on" or "Auto refresh off")
    end

    function Engine.SetCustomRareKeywords(Text)
        Engine.Settings.CustomRareKeywords = {}
        for Token in string.gmatch(tostring(Text or ""), "[^,;\n]+") do
            local Clean = Lower(Token):gsub("^%s+", ""):gsub("%s+$", "")
            if Clean ~= "" then table.insert(Engine.Settings.CustomRareKeywords, Clean) end
        end
        if Engine.ItemESPEnabled then Engine.RequestItemRescan(0.12) end
    end

    function Engine.IsRareItem(Rarity, Descriptor, Name)
        local Combined = Lower((Name or "") .. " " .. (Descriptor or "") .. " " .. (Rarity or ""))
        local ProfileMatch, ProfileWord = ContainsAny(Combined, GetProfile().RareKeywords or {})
        if ProfileMatch then return true, "Profile target: " .. tostring(ProfileWord) end
        local CustomMatch, CustomWord = ContainsAny(Combined, Engine.Settings.CustomRareKeywords)
        if CustomMatch then return true, "Custom target: " .. tostring(CustomWord) end
        local RareMatch, RareWord = ContainsAny(Combined, GenericRareWords)
        if RareMatch then return true, tostring(RareWord) end
        return false, ""
    end

    local function EnsureAlertOverlay()
        if Engine.AlertOverlay and Engine.AlertOverlay.Gui and Engine.AlertOverlay.Gui.Parent then
            return Engine.AlertOverlay
        end
        local ParentGui = nil
        if gethui then pcall(function() ParentGui = gethui() end) end
        if not ParentGui then ParentGui = Player:FindFirstChildOfClass("PlayerGui") end
        if not ParentGui then return nil end

        local Gui = Instance.new("ScreenGui")
        Gui.Name = "BananiRareAlertOverlay"
        Gui.IgnoreGuiInset = true
        Gui.ResetOnSpawn = false
        Gui.DisplayOrder = 999998
        Gui.Parent = ParentGui
        if ParentGui:IsA("PlayerGui") then HubGuiTracker.Owned[Gui] = true end

        local Container = Instance.new("Frame")
        Container.Name = "Direction"
        Container.AnchorPoint = Vector2.new(0.5, 0.5)
        Container.Size = UDim2.fromOffset(190, 54)
        Container.BackgroundTransparency = 1
        Container.Visible = false
        Container.Parent = Gui

        local Arrow = Instance.new("TextLabel")
        Arrow.Name = "Arrow"
        Arrow.AnchorPoint = Vector2.new(0.5, 0.5)
        Arrow.Position = UDim2.fromOffset(28, 27)
        Arrow.Size = UDim2.fromOffset(44, 44)
        Arrow.BackgroundColor3 = Color3.fromRGB(15, 15, 20)
        Arrow.BackgroundTransparency = 0.18
        Arrow.BorderSizePixel = 0
        Arrow.Font = Enum.Font.GothamBold
        Arrow.Text = "▲"
        Arrow.TextColor3 = Color3.fromRGB(255, 214, 54)
        Arrow.TextSize = 28
        Arrow.Parent = Container
        AddCorner(Arrow, 12)
        AddStroke(Arrow, Color3.fromRGB(255, 229, 120), 1.5, 0.08)

        local Info = Instance.new("TextLabel")
        Info.Name = "Info"
        Info.Position = UDim2.fromOffset(54, 7)
        Info.Size = UDim2.fromOffset(132, 40)
        Info.BackgroundColor3 = Color3.fromRGB(13, 13, 17)
        Info.BackgroundTransparency = 0.15
        Info.BorderSizePixel = 0
        Info.Font = Enum.Font.GothamBold
        Info.TextColor3 = Color3.fromRGB(250, 250, 252)
        Info.TextSize = 11
        Info.TextWrapped = true
        Info.Text = "Rare item"
        Info.Parent = Container
        AddCorner(Info, 8)
        AddStroke(Info, Color3.fromRGB(255, 214, 54), 1.2, 0.12)

        Engine.AlertOverlay = {Gui = Gui, Container = Container, Arrow = Arrow, Info = Info}
        return Engine.AlertOverlay
    end

    local function FindBestAlertTarget()
        local BestRoot, BestRecord, BestDistance
        for RootPart, Record in pairs(Engine.ItemRecords) do
            if RootPart.Parent and Record.IsRare then
                local Distance = DistanceFromMe(RootPart.Position)
                if Distance <= Engine.Settings.AlertMaxDistance and (not BestDistance or Distance < BestDistance) then
                    BestRoot, BestRecord, BestDistance = RootPart, Record, Distance
                end
            end
        end
        Engine.AlertTarget = BestRoot
        return BestRoot, BestRecord, BestDistance
    end

    local function PlayAlertSound()
        if not Engine.Settings.RareAlertSound then return end
        if not Engine.AlertSound or not Engine.AlertSound.Parent then
            local Sound = Instance.new("Sound")
            Sound.Name = "BananiRareItemPing"
            Sound.SoundId = "rbxasset://sounds/electronicpingshort.wav"
            Sound.Volume = 0.55
            Sound.Parent = game:GetService("SoundService")
            Engine.AlertSound = Sound
        end
        pcall(function()
            Engine.AlertSound.TimePosition = 0
            Engine.AlertSound:Play()
        end)
    end

    local function UpdateAlertArrow()
        local Overlay = EnsureAlertOverlay()
        if not Overlay then return end
        if not Engine.Settings.RareAlerts or not Engine.Settings.RareDirectionArrow then
            Overlay.Container.Visible = false
            return
        end
        local RootPart, Record, Distance = FindBestAlertTarget()
        if not RootPart or not Record then
            Overlay.Container.Visible = false
            return
        end
        local CurrentCamera = workspace.CurrentCamera
        if not CurrentCamera then Overlay.Container.Visible = false return end
        local Point, OnScreen = CurrentCamera:WorldToViewportPoint(RootPart.Position)
        if OnScreen and Point.Z > 0 then
            Overlay.Container.Visible = false
            return
        end
        local View = CurrentCamera.ViewportSize
        local Center = Vector2.new(View.X * 0.5, View.Y * 0.5)
        local Delta = Vector2.new(Point.X - Center.X, Point.Y - Center.Y)
        if Point.Z < 0 then Delta = -Delta end
        if Delta.Magnitude < 1 then Delta = Vector2.new(0, -1) end
        local Unit = Delta.Unit
        local MarginX, MarginY = 120, 80
        local ScaleX = (Center.X - MarginX) / math.max(math.abs(Unit.X), 0.001)
        local ScaleY = (Center.Y - MarginY) / math.max(math.abs(Unit.Y), 0.001)
        local Position = Center + Unit * math.min(ScaleX, ScaleY)
        Overlay.Container.Position = UDim2.fromOffset(Position.X, Position.Y)
        Overlay.Container.Visible = true
        Overlay.Arrow.Rotation = math.deg(math.atan2(Unit.Y, Unit.X)) + 90
        Overlay.Arrow.TextColor3 = Record.Color or Engine.Settings.ItemColor
        Overlay.Info.Text = tostring(Record.Name) .. "\n" .. tostring(math.floor((Distance or 0) + 0.5)) .. " studs"
    end

    function Engine.SetRareAlerts(Value)
        Engine.Settings.RareAlerts = Value == true
        if Engine.Settings.RareAlerts and not Engine.ItemESPEnabled then
            Engine.SetItemESP(true)
            if Rayfield and Rayfield.Flags and Rayfield.Flags.Visuals_ItemESP
                and Rayfield.Flags.Visuals_ItemESP.Set then
                pcall(function() Rayfield.Flags.Visuals_ItemESP:Set(true) end)
            end
        end
        Disconnect(Engine.AlertRenderConnection)
        Engine.AlertRenderConnection = nil
        if not Engine.Settings.RareAlerts then
            if Engine.AlertOverlay and Engine.AlertOverlay.Container then Engine.AlertOverlay.Container.Visible = false end
            return
        end
        EnsureAlertOverlay()
        local Accumulator = 0
        Engine.AlertRenderConnection = Runtime.TrackCleanup(RunService.RenderStepped:Connect(function(Delta)
            if Unloaded or not Engine.Settings.RareAlerts then return end
            Accumulator += Delta
            if Accumulator < 0.05 then return end
            Accumulator = 0
            UpdateAlertArrow()
        end),"Disconnect","RareAlertRender","Connections")
        UpdateAlertArrow()
    end

    local function AlertRareItem(RootPart, Record)
        if not Engine.Settings.RareAlerts or not RootPart or not Record or not Record.IsRare then return end
        if Engine.AlertedItems[RootPart] then return end
        local Distance = DistanceFromMe(RootPart.Position)
        if Distance > Engine.Settings.AlertMaxDistance then return end
        Engine.AlertedItems[RootPart] = true
        Notify("⭐ RARE ITEM FOUND", Record.Name .. " • " .. math.floor(Distance + 0.5) .. " studs")
        PlayAlertSound()
        Engine.AlertTarget = RootPart
        UpdateAlertArrow()
    end

    function Engine.GetItemTargetOptions()
        local Entries = {}
        for RootPart, Record in pairs(Engine.ItemRecords) do
            if RootPart and RootPart.Parent and Record and Record.Source and Record.Source.Parent then
                table.insert(Entries, {
                    Root = RootPart,
                    Record = Record,
                    Distance = DistanceFromMe(RootPart.Position)
                })
            end
        end
        table.sort(Entries, function(A, B)
            if math.abs(A.Distance - B.Distance) > 0.1 then return A.Distance < B.Distance end
            return tostring(A.Record.Name) < tostring(B.Record.Name)
        end)

        local Options = {}
        local Map = {}
        local Seen = {}
        for _, Entry in ipairs(Entries) do
            local Base = tostring(Entry.Record.Name or "Item")
            Seen[Base] = (Seen[Base] or 0) + 1
            local Suffix = Seen[Base] > 1 and (" • " .. tostring(Seen[Base])) or ""
            local Label = Base .. Suffix .. "  •  " .. tostring(math.floor(Entry.Distance + 0.5)) .. " studs"
            table.insert(Options, Label)
            Map[Label] = Entry.Root
        end
        Engine.ItemOptionMap = Map
        return Options
    end

    function Engine.RefreshItemTargetDropdowns()
        local Options = Engine.GetItemTargetOptions()
        if Runtime.ItemTargetDropdown and Runtime.ItemTargetDropdown.Refresh then
            pcall(function() Runtime.ItemTargetDropdown:Refresh(Options) end)
        end
    end

    function Engine.RequestItemTargetRefresh(DelaySeconds)
        Engine.ItemTargetRefreshRequest += 1
        local Request = Engine.ItemTargetRefreshRequest
        task.delay(tonumber(DelaySeconds) or 0.12, function()
            if Unloaded or Request ~= Engine.ItemTargetRefreshRequest then return end
            Engine.RefreshItemTargetDropdowns()
        end)
    end

    function Engine.SelectItemOption(Option)
        local Label = type(Option) == "table" and Option[1] or Option
        local RootPart = Label and Engine.ItemOptionMap[Label] or nil
        local Record = RootPart and Engine.ItemRecords[RootPart] or nil
        if not RootPart or not RootPart.Parent or not Record then
            Engine.SelectedItemRoot = nil
            Engine.SelectedItemLabel = nil
            Notify("Item Target", "That item is no longer available. Scan again.")
            return false
        end
        Engine.SelectedItemRoot = RootPart
        Engine.SelectedItemLabel = tostring(Label)
        if Runtime.PathPreviewEnabled then
            Runtime.RefreshPathPreview(CFrame.new(RootPart.Position), Runtime.ItemTravelMode)
            Runtime.PathPreviewTargetProvider = function() return Engine.GetSelectedItemCFrame() end
        end
        return true
    end

    function Engine.GetSelectedItemCFrame()
        local RootPart = Engine.SelectedItemRoot
        if not RootPart or not RootPart.Parent or not Engine.ItemRecords[RootPart] then
            Engine.SelectedItemRoot = nil
            Engine.SelectedItemLabel = nil
            return nil
        end
        return CFrame.new(RootPart.Position)
    end

    function Engine.TravelToSelectedItem()
        local Target = Engine.GetSelectedItemCFrame()
        if not Target then
            Notify("Item Target", "Pick an item first.")
            return
        end
        local Record = Engine.ItemRecords[Engine.SelectedItemRoot]
        local Name = Record and Record.Name or "item"
        local Mode = Runtime.ItemTravelMode or "Teleport"
        task.spawn(function()
            local Reached = Runtime.TravelToCFrame(Target, Mode, "Item", function() return Engine.GetSelectedItemCFrame() end)
            if Mode ~= "Teleport" and not Reached and not Unloaded then
                Notify("Item Target", Mode .. " could not reach " .. tostring(Name) .. ".")
            end
        end)
    end

    local function ActivateNearbyItem(RootPart, Record)
        if not RootPart or not RootPart.Parent then return true end
        local Source = Record and Record.Source
        local Prompt = Source and Source:IsA("ProximityPrompt") and Source
            or (Source and Source:FindFirstChildWhichIsA("ProximityPrompt", true))
        if not Prompt then Prompt = RootPart:FindFirstChildWhichIsA("ProximityPrompt", true) end
        if not Prompt and RootPart.Parent and RootPart.Parent:IsA("Model") then
            Prompt = RootPart.Parent:FindFirstChildWhichIsA("ProximityPrompt", true)
        end
        if Prompt and type(fireproximityprompt) == "function" then
            pcall(fireproximityprompt, Prompt)
        end
        local MyRoot = Root()
        if MyRoot and type(firetouchinterest) == "function" then
            pcall(firetouchinterest, MyRoot, RootPart, 0)
            pcall(firetouchinterest, MyRoot, RootPart, 1)
        end
        task.wait(0.14)

        return not RootPart:IsDescendantOf(workspace)
    end

    function Engine.StopPickupAll(Quiet)
        if not Runtime.PickupAllRunning then return end
        Runtime.PickupAllCancel = true
        Runtime.PickupAllRunId += 1
        Runtime.PickupAllRunning = false
        if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
        Engine.UpdateItemCollectorStatus("Stopped")
        if not Quiet then Notify("Pick Up All", "Stopped.") end
    end

    function Engine.PickUpAllItems()
        if Runtime.PickupAllRunning then
            Engine.StopPickupAll(false)
            return
        end
        if not Engine.ItemESPEnabled then
            Notify("Pick Up All", "Turn Item ESP on first so items can be detected.")
            return
        end
        if Engine.ItemCount <= 0 then
            Notify("Pick Up All", "No detected items are available yet.")
            Engine.RequestItemRescan(0)
            return
        end

        Runtime.PickupAllRunId += 1
        local ThisRun = Runtime.PickupAllRunId
        Runtime.PickupAllRunning = true
        Runtime.PickupAllCancel = false
        task.spawn(function()
            local Collected, Visited = 0, 0
            local Skipped = {}
            Notify("Pick Up All", "Collecting matching items nearest-first. Press Stop Pick Up All to cancel.")
            Engine.UpdateItemCollectorStatus("Collecting")
            local Success, Failure = pcall(function()
                while not Unloaded and not Runtime.PickupAllCancel
                    and Runtime.PickupAllRunId == ThisRun do
                    local MyRoot = Root()
                    if not MyRoot then break end
                    local BestRoot, BestRecord, BestDistance
                    for ItemRoot, Record in pairs(Engine.ItemRecords) do
                        if not Skipped[ItemRoot] and ItemRoot and ItemRoot.Parent
                            and Record and Record.Source and Record.Source.Parent
                            and ItemRoot:IsDescendantOf(workspace)
                            and PassesItemFilter(Record.Name, Record.Descriptor) then
                            local Distance = (MyRoot.Position - ItemRoot.Position).Magnitude
                            if not BestDistance or Distance < BestDistance then
                                BestRoot, BestRecord, BestDistance = ItemRoot, Record, Distance
                            end
                        end
                    end
                    if not BestRoot then break end
                    Visited += 1
                    local Reached = Runtime.TravelToCFrame(CFrame.new(BestRoot.Position), Runtime.ItemTravelMode)
                    if Unloaded or Runtime.PickupAllCancel or Runtime.PickupAllRunId ~= ThisRun then break end
                    if Reached and PassesItemFilter(BestRecord.Name, BestRecord.Descriptor)
                        and ActivateNearbyItem(BestRoot, BestRecord) then Collected += 1 end

                    Skipped[BestRoot] = true
                    task.wait(0.05)
                end
            end)
            local WasCancelled = Runtime.PickupAllCancel or Runtime.PickupAllRunId ~= ThisRun
            if Runtime.PickupAllRunId == ThisRun then
                Runtime.PickupAllRunning = false
                Runtime.PickupAllCancel = false
            end
            if not Success and not Unloaded and not WasCancelled then
                if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                warn("BANANIHUB | Item collection failed: " .. tostring(Failure))
                Engine.UpdateItemCollectorStatus("Failed; ready to retry")
                Notify("Pick Up All", "Collection stopped after an error. Check the output and try again.")
            elseif not Unloaded and not WasCancelled then
                Notify("Pick Up All", "Finished • " .. Collected .. " no longer in world • " .. Visited .. " visited.")
                Engine.UpdateItemCollectorStatus("Finished")
                Engine.RequestItemRescan(0.15)
            end
        end)
    end

    local function ClearItemRecord(RootPart, SuppressRefresh)
        local Record = Engine.ItemRecords[RootPart]
        if not Record then return end
        if Record.Highlight then pcall(function() Record.Highlight:Destroy() end) end
        if Record.Gui then pcall(function() Record.Gui:Destroy() end) end
        Engine.ItemRecords[RootPart] = nil
        Engine.ItemCount = math.max(0, Engine.ItemCount - 1)
        if Engine.AlertTarget == RootPart then Engine.AlertTarget = nil end
        if Engine.SelectedItemRoot == RootPart then
            Engine.SelectedItemRoot = nil
            Engine.SelectedItemLabel = nil
            if Runtime.ClearPathPreview then pcall(Runtime.ClearPathPreview) end
        end
        if not SuppressRefresh then Engine.RequestItemTargetRefresh(0.08) end
    end

    function Engine.ClearItems()
        local Roots = {}
        for RootPart in pairs(Engine.ItemRecords) do table.insert(Roots, RootPart) end
        for _, RootPart in ipairs(Roots) do ClearItemRecord(RootPart, true) end
        Engine.ItemRecords = {}
        Engine.ItemCount = 0
        Engine.RequestItemTargetRefresh(0.02)
    end

    function Engine.TryRegisterItem(Object)
        if not Engine.ItemESPEnabled or not Engine.ItemAllowed() or not Object or not Object.Parent then return end
        local Candidate, DisplayName, Descriptor = CandidateFrom(Object)
        if not Candidate or not Candidate.Parent or IsCharacterObject(Candidate) then return end
        DisplayName = tostring(DisplayName or Candidate.Name or "Item")
        Descriptor = tostring(Descriptor or DisplayName)
        if not PassesItemFilter(DisplayName, Descriptor) then return end
        local RootPart = FindPart(Candidate)
        if not RootPart or not RootPart.Parent or Engine.ItemRecords[RootPart] then return end
        if Engine.ItemCount >= Engine.Settings.MaxItems then return end

        local VisualTarget = Candidate
        if Candidate:IsA("Tool") then VisualTarget = RootPart end
        if not (VisualTarget:IsA("Model") or VisualTarget:IsA("BasePart")) then VisualTarget = RootPart end
        local Rarity = GetRarity(Candidate)
        local IsRare, RareReason = Engine.IsRareItem(Rarity, Descriptor, DisplayName)
        local ProfileRare, ProfileWord = ContainsAny(Descriptor, GetProfile().RareKeywords or {})
        if ProfileRare then
            DisplayName = tostring(ProfileWord):find("chakra", 1, true) and "Chakra Fruit" or DisplayName
        end
        local Color = RarityColor(Rarity)
        if IsRare and Rarity == "" then Color = Color3.fromRGB(255, 200, 55) end
        if ProfileRare then Color = Color3.fromRGB(255, 231, 72) end

        local Highlight = Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
        Highlight.Name = "BananiItemHighlight"
        Highlight.Adornee = VisualTarget
        Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        Highlight.FillColor = Color
        Highlight.OutlineColor = Color3.new(1, 1, 1)
        Highlight.FillTransparency = IsRare and 0.68 or 0.80
        Highlight.OutlineTransparency = IsRare and 0 or 0.08
        Highlight.Parent = RootPart

        local Gui, Panel, Accent, Stroke, Title, Meta = MakeNameplate(
            RootPart,
            (IsRare and "★  " or "◆  ") .. DisplayName,
            Color,
            "BananiItemESP"
        )
        Gui.StudsOffset = Vector3.new(0, 2.2, 0)
        local Record = {
            Root = RootPart,
            Source = Candidate,
            Highlight = Highlight,
            Gui = Gui,
            Panel = Panel,
            Accent = Accent,
            Stroke = Stroke,
            Title = Title,
            Meta = Meta,
            Name = DisplayName,
            Descriptor = Descriptor,
            Rarity = Rarity,
            Color = Color,
            IsRare = IsRare,
            RareReason = RareReason
        }
        Engine.ItemRecords[RootPart] = Record
        Engine.ItemCount += 1
        AlertRareItem(RootPart, Record)
        Engine.RequestItemTargetRefresh(0.12)
    end

    function Engine.RescanItems(Quiet, PreserveExisting)
        if not Engine.ItemESPEnabled then return end
        Engine.ItemScanGeneration += 1
        local Generation = Engine.ItemScanGeneration

        if not PreserveExisting then Engine.ClearItems() end
        if not Engine.ItemAllowed() then return end
        task.spawn(function()
            local Descendants = workspace:GetDescendants()
            for Index, Object in ipairs(Descendants) do
                if not Engine.ItemESPEnabled or Unloaded or Generation ~= Engine.ItemScanGeneration then return end
                if ShouldInspectObject(Object) then Engine.TryRegisterItem(Object) end
                if Index % 550 == 0 then task.wait() end
            end
            if Engine.ItemESPEnabled and Generation == Engine.ItemScanGeneration then
                Engine.RequestItemTargetRefresh(0.02)
                Engine.UpdateItemCollectorStatus("Ready")
                if not Quiet then
                    Notify("Item ESP", "Scan complete • " .. tostring(Engine.ItemCount) .. " item(s) marked.")
                end
            end
        end)
    end

    function Engine.RequestItemRescan(DelaySeconds)
        if not Engine.ItemESPEnabled then return end
        Engine.ItemRescanRequest += 1
        local Request = Engine.ItemRescanRequest
        task.delay(tonumber(DelaySeconds) or 0.12, function()
            if Unloaded or not Engine.ItemESPEnabled or Request ~= Engine.ItemRescanRequest then return end
            Engine.RescanItems(true)
        end)
    end

    local function UpdateItems()
        local Pulse = PulseAmount(3.2, 0.055)
        local ToRemove = {}
        for RootPart, Record in pairs(Engine.ItemRecords) do
            if not RootPart.Parent or not Record.Source or not Record.Source.Parent or not Engine.ItemAllowed() then
                table.insert(ToRemove, RootPart)
            else
                local Distance = DistanceFromMe(RootPart.Position)
                local Visible = Distance <= Engine.Settings.ItemMaxDistance
                local Selected = Engine.SelectedItemRoot == RootPart
                local BaseColor = Record.Color or RarityColor(Record.Rarity)
                local Color = Selected and Color3.fromRGB(255, 225, 74) or BaseColor
                if Record.Gui then Record.Gui.Enabled = Visible or Selected end
                if Record.Highlight then
                    Record.Highlight.Enabled = Visible or Selected
                    Record.Highlight.FillColor = Color
                    Record.Highlight.OutlineColor = Selected and Color3.fromRGB(255, 255, 255) or Color3.new(1, 1, 1)
                    Record.Highlight.FillTransparency = Selected
                        and math.clamp(0.38 + Pulse, 0.28, 0.48)
                        or math.clamp((Record.IsRare and 0.68 or 0.80) + Pulse, 0.55, 0.90)
                    Record.Highlight.OutlineTransparency = Selected and 0 or (Record.IsRare and 0 or 0.08)
                end
                if Record.Accent then Record.Accent.BackgroundColor3 = Color end
                if Record.Stroke then Record.Stroke.Color = Color end
                if Record.Title then
                    Record.Title.Text = Selected
                        and ("▶ SELECTED  •  " .. Record.Name)
                        or ((Record.IsRare and "★  " or "◆  ") .. Record.Name)
                end
                if Record.Meta then
                    local RarityText = Record.Rarity ~= "" and string.upper(Record.Rarity)
                        or (Record.IsRare and "RARE TARGET" or "ITEM")
                    Record.Meta.Text = RarityText .. "  •  " .. math.floor(Distance + 0.5) .. " studs"
                end
                AlertRareItem(RootPart, Record)
            end
        end
        for _, RootPart in ipairs(ToRemove) do ClearItemRecord(RootPart) end
    end

    function Engine.SetItemESP(Value)
        Engine.ItemESPEnabled = Value == true
        Disconnect(Engine.ItemAddedConnection)
        Disconnect(Engine.ItemHeartbeatConnection)
        Engine.ItemAddedConnection = nil
        Engine.ItemHeartbeatConnection = nil
        Engine.AutoRescanAccumulator = 0
        if not Engine.ItemESPEnabled then
            Engine.ItemScanGeneration += 1
            Engine.ItemRescanRequest += 1
            Engine.ClearItems()
            Engine.UpdateItemCollectorStatus("Scanner off")
            return
        end
        Engine.UpdateItemCollectorStatus("Scanning")
        Engine.RescanItems()
        Engine.ItemAddedConnection = Runtime.TrackCleanup(workspace.DescendantAdded:Connect(function(Object)
            if Engine.ItemESPEnabled and ShouldInspectObject(Object) then
                task.defer(Engine.TryRegisterItem, Object)
            end
        end),"Disconnect","ItemDescendantAdded","Connections")
        local Accumulator = 0
        Engine.ItemHeartbeatConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
            if not Engine.ItemESPEnabled or Unloaded then return end
            Accumulator += Delta
            if Engine.Settings.AutoRescanEnabled and not Runtime.PickupAllRunning then
                Engine.AutoRescanAccumulator += Delta
                if Engine.AutoRescanAccumulator >= Engine.Settings.AutoRescanSeconds then
                    Engine.AutoRescanAccumulator = 0
                    Engine.RescanItems(true, true)
                end
            end
            if Accumulator < Engine.Settings.UpdateInterval*Runtime.GetVisualUpdateScale() then return end
            Accumulator = 0
            UpdateItems()
        end),"Disconnect","ItemESPHeartbeat","Connections")
    end

    function Engine.RefreshFilters(Scope)
        Scope = tostring(Scope or "All")
        local RefreshPlayers = Scope == "All" or Scope == "Players"
        local RefreshNPCs = Scope == "All" or Scope == "NPCs"
        local RefreshItems = Scope == "All" or Scope == "Items"

        if RefreshPlayers then
            if ChamsEnabled then Engine.RefreshPlayerHighlights() end
            if HitboxEnabled then
                for _, Target in ipairs(Runtime.CachedPlayers()) do EnsureHitbox(Target) end
            end
            task.defer(function()
                if Runtime.RefreshPlayerESP then pcall(Runtime.RefreshPlayerESP) end
            end)
        end

        if RefreshNPCs and NPCChamsEnabled then
            local Models = {}
            for Model in pairs(Engine.NPCRecords) do table.insert(Models, Model) end
            for _, Model in ipairs(Models) do
                if not Engine.NPCAllowed(Model) then ClearNPCRecord(Model) end
            end
            task.spawn(function()
                local Descendants = workspace:GetDescendants()
                for Index, Object in ipairs(Descendants) do
                    if not NPCChamsEnabled or Unloaded then return end
                    if Object:IsA("Model") and IsNPC(Object) then EnsureNPC(Object) end
                    if Index % 550 == 0 then task.wait() end
                end
            end)
        end

        if RefreshItems and Engine.ItemESPEnabled then
            Engine.RequestItemRescan(0.12)
        end
    end
    function Engine.ApplyPreset(Name)
        Name = tostring(Name or "Banana Neon")
        Engine.Settings.Preset = Name
        if Name == "Cyber Blue" then
            ChamsFillColor = Color3.fromRGB(56, 171, 255)
            ChamsOutlineColor = Color3.fromRGB(178, 235, 255)
            Engine.Settings.NPCColor = Color3.fromRGB(87, 255, 226)
            Engine.Settings.ItemColor = Color3.fromRGB(91, 139, 255)
            Engine.Settings.HitboxColor = Color3.fromRGB(63, 210, 255)
        elseif Name == "Violet" then
            ChamsFillColor = Color3.fromRGB(176, 89, 255)
            ChamsOutlineColor = Color3.fromRGB(247, 210, 255)
            Engine.Settings.NPCColor = Color3.fromRGB(255, 91, 211)
            Engine.Settings.ItemColor = Color3.fromRGB(109, 190, 255)
            Engine.Settings.HitboxColor = Color3.fromRGB(215, 111, 255)
        elseif Name == "Crimson" then
            ChamsFillColor = Color3.fromRGB(255, 74, 91)
            ChamsOutlineColor = Color3.fromRGB(255, 215, 220)
            Engine.Settings.NPCColor = Color3.fromRGB(255, 137, 68)
            Engine.Settings.ItemColor = Color3.fromRGB(255, 196, 70)
            Engine.Settings.HitboxColor = Color3.fromRGB(255, 80, 80)
        elseif Name == "Ghost" then
            ChamsFillColor = Color3.fromRGB(210, 225, 255)
            ChamsOutlineColor = Color3.fromRGB(255, 255, 255)
            Engine.Settings.NPCColor = Color3.fromRGB(174, 207, 255)
            Engine.Settings.ItemColor = Color3.fromRGB(225, 242, 255)
            Engine.Settings.HitboxColor = Color3.fromRGB(188, 218, 255)
        else
            ChamsFillColor = Color3.fromRGB(255, 221, 0)
            ChamsOutlineColor = Color3.fromRGB(255, 255, 255)
            Engine.Settings.NPCColor = Color3.fromRGB(194, 92, 255)
            Engine.Settings.ItemColor = Color3.fromRGB(255, 213, 54)
            Engine.Settings.HitboxColor = Color3.fromRGB(255, 171, 38)
        end
        Engine.RefreshFilters("Players")
        if Engine.ItemESPEnabled then Engine.RequestItemRescan(0.10) end
        Notify("Visual Style", Name .. " applied.")
    end

    function Engine.ResetVisualState()
        Engine.SetRareAlerts(false)
        Engine.SetItemESP(false)
        Engine.Settings.FocusMode = "Everything"
        Engine.Settings.PlayerFilterMode = "Everyone"
        Engine.Settings.NPCBossesOnly = false
        Engine.Settings.Whitelist = {}
        Engine.Settings.WhitelistText = ""
        Engine.Settings.ItemWhitelist = {}
        Engine.Settings.ItemWhitelistText = ""
        Engine.Settings.ItemBlacklist = {}
        Engine.Settings.ItemBlacklistText = ""
        Engine.Settings.AutoRescanEnabled = false
        Engine.AutoRescanAccumulator = 0
        Engine.UpdateItemCollectorStatus("Reset")
    end

    function Engine.Shutdown()
        Engine.SetRareAlerts(false)
        Engine.SetItemESP(false)
        Disconnect(Engine.NPCAddedConnection)
        Disconnect(Engine.NPCHeartbeatConnection)
        if Engine.AlertOverlay and Engine.AlertOverlay.Gui then pcall(function() Engine.AlertOverlay.Gui:Destroy() end) end
        if Engine.AlertSound then pcall(function() Engine.AlertSound:Destroy() end) end
        Engine.AlertOverlay = nil
        Engine.AlertSound = nil
    end

    Engine.DetectProfile(true)
    task.delay(1.5, function()
        if not Unloaded then Engine.DetectProfile(true) end
    end)
end

local function SetChams(Value)
    Runtime.VisualEngine.SetChams(Value)
end
local function SetNPCChams(Value)
    Runtime.VisualEngine.SetNPCChams(Value)
end
local function SetHitboxes(Value)
    Runtime.VisualEngine.SetHitboxes(Value)
