Runtime.RefreshVisualCadence = function()
    local Engine = Runtime.VisualEngine
    if not Engine or not Engine.Settings then return end
    if Runtime.AFKMode and Runtime.AFKMode.Active then
        Engine.Settings.UpdateInterval = 0.55
        Engine.Settings.PlayerUpdateInterval = 0.45
    elseif LowGraphicsEnabled then
        Engine.Settings.UpdateInterval = 0.25
        Engine.Settings.PlayerUpdateInterval = 0.20
    else
        Engine.Settings.UpdateInterval = 0.15
        Engine.Settings.PlayerUpdateInterval = 0.12
    end
end
Runtime.SetAFKActive = function(Value, Silent)
    local State = Runtime.AFKMode
    if not State then return end
    Value = Value == true
    if State.Active == Value then return end
    State.Active = Value
    Runtime.RefreshVisualCadence()
    if Runtime.VisualEngine and Runtime.VisualEngine.OcclusionCache then
        Runtime.VisualEngine.OcclusionCache = setmetatable({}, {__mode = "k"})
    end
    if not Silent then
        if Value then
            Notify("💤 AFK Mode", "Idle detected. ESP and visual updates are now using less CPU.")
        else
            Notify("💤 AFK Mode", "Welcome back. Normal refresh speed restored.")
        end
    end
    Runtime.UpdatePreferenceDisplays()
end
Runtime.MarkActivity = function()
    local State = Runtime.AFKMode
    if not State then return end
    State.LastActivity = os.clock()
    if State.Active then Runtime.SetAFKActive(false, false) end
end
Runtime.SetAFKMode = function(Value, Silent)
    local State = Runtime.AFKMode
    if not State then return end
    State.Enabled = Value == true
    State.LastActivity = os.clock()
    State.CheckAccumulator = 0
    if not State.Enabled then Runtime.SetAFKActive(false, true) end
    if Runtime.UpdateAFKConnections then Runtime.UpdateAFKConnections() end
    Runtime.RefreshVisualCadence()
    Runtime.UpdatePreferenceDisplays()
    if not Silent then
        Notify("💤 AFK Performance Saver", State.Enabled
            and ("On • activates after " .. tostring(State.Delay) .. " seconds without input")
            or "Off")
    end
end
Runtime.SetAFKDelay = function(Seconds)
    local State = Runtime.AFKMode
    if not State then return end
    State.Delay = math.clamp(tonumber(Seconds) or 60, 15, 900)
    State.LastActivity = os.clock()
    if State.Active then Runtime.SetAFKActive(false, true) end
end
Runtime.AFKConnections = Runtime.AFKConnections or {}
Runtime.UpdateAFKConnections = function()
    for _, Connection in ipairs(Runtime.AFKConnections) do
        pcall(function() Connection:Disconnect() end)
    end
    table.clear(Runtime.AFKConnections)
    local State = Runtime.AFKMode
    if Unloaded or not State or not State.Enabled then return end

    table.insert(Runtime.AFKConnections, UserInputService.InputBegan:Connect(function()
        if not Unloaded then Runtime.MarkActivity() end
    end))

    local LastPointerActivity = 0
    table.insert(Runtime.AFKConnections, UserInputService.InputChanged:Connect(function(Input)
        if Unloaded then return end
        local Type = Input.UserInputType
        if Type == Enum.UserInputType.MouseMovement
            or Type == Enum.UserInputType.MouseWheel
            or Type == Enum.UserInputType.Touch then
            local Now = os.clock()
            if Now - LastPointerActivity >= 0.20 then
                LastPointerActivity = Now
                Runtime.MarkActivity()
            end
        end
    end))

    table.insert(Runtime.AFKConnections, Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
        if Unloaded or not State.Enabled then return end
        State.CheckAccumulator += Delta
        if State.CheckAccumulator < 1 then return end
        State.CheckAccumulator = 0
        if not State.Active and (os.clock() - State.LastActivity) >= State.Delay then
            Runtime.SetAFKActive(true, false)
        end
    end),"Disconnect","AFKHeartbeat","AFKConnections"))
end
local function SetLowGraphics(Value)
    if Value == LowGraphicsEnabled then return end
    if Value and not LowGraphicsEnabled and not FullbrightEnabled then
        CaptureLightingSnapshot()
    end
    LowGraphicsEnabled = Value
    Runtime.RefreshVisualCadence()
    Runtime.PerformanceGeneration += 1
    local Generation = Runtime.PerformanceGeneration
    for _, Connection in ipairs(Runtime.PerformanceConnections) do
        pcall(function() Connection:Disconnect() end)
    end
    Runtime.PerformanceConnections = {}
    local function IsEffect(Object)
        return Object:IsA("ParticleEmitter")
            or Object:IsA("Trail")
            or Object:IsA("Beam")
            or Object:IsA("Smoke")
            or Object:IsA("Fire")
            or Object:IsA("Sparkles")
            or Object:IsA("BloomEffect")
            or Object:IsA("BlurEffect")
            or Object:IsA("SunRaysEffect")
            or Object:IsA("DepthOfFieldEffect")
            or Object:IsA("ColorCorrectionEffect")
    end
    local function SaveOriginal(Object, Data)
        if OriginalGraphics[Object] == nil then
            OriginalGraphics[Object] = Data
        end
    end
    local function ApplyObject(Object)
        if not Value or not Object or not Object.Parent
            or Generation ~= Runtime.PerformanceGeneration then
            return
        end
        if Object:IsA("BasePart") then
            SaveOriginal(Object, {
                Material = Object.Material,
                Reflectance = Object.Reflectance,
                CastShadow = Object.CastShadow
            })
            pcall(function()
                Object.Material = Enum.Material.SmoothPlastic
                Object.Reflectance = 0
                Object.CastShadow = false
            end)
        elseif IsEffect(Object) then
            SaveOriginal(Object, { Enabled = Object.Enabled })
            pcall(function() Object.Enabled = false end)
        end
    end
    if not Value then
        RefreshLightingState()
        if not FullbrightEnabled then
            Runtime.LightingSnapshot = nil
        end
        local SavedGraphics = OriginalGraphics
        OriginalGraphics = setmetatable({}, {__mode = "k"})
        task.spawn(function()
            local Index = 0
            for Object, Data in pairs(SavedGraphics) do
                if Generation ~= Runtime.PerformanceGeneration then return end
                if Object and Object.Parent then
                    for Property, OriginalValue in pairs(Data) do
                        pcall(function() Object[Property] = OriginalValue end)
                    end
                end
                Index += 1
                if Index % 250 == 0 then task.wait() end
            end
            if Generation == Runtime.PerformanceGeneration and not Unloaded then
                LogSuccess("Performance Mode disabled and visuals restored")
            end
        end)
        return
    end
    OriginalGraphics = setmetatable({}, {__mode = "k"})
    RefreshLightingState()
    table.insert(Runtime.PerformanceConnections,
        workspace.DescendantAdded:Connect(function(Object)
            task.defer(ApplyObject, Object)
        end))
    table.insert(Runtime.PerformanceConnections,
        Lighting.ChildAdded:Connect(function(Object)
            task.defer(ApplyObject, Object)
        end))
    task.spawn(function()
        local DisabledCount = 0
        local SimplifiedCount = 0
        local Descendants = workspace:GetDescendants()
        for Index, Object in ipairs(Descendants) do
            if not LowGraphicsEnabled
                or Generation ~= Runtime.PerformanceGeneration
                or Unloaded then
                return
            end
            if Object:IsA("BasePart") then
                SimplifiedCount += 1
            elseif IsEffect(Object) then
                DisabledCount += 1
            end
            ApplyObject(Object)
            if Index % 250 == 0 then task.wait() end
        end
        for _, Object in ipairs(Lighting:GetChildren()) do
            ApplyObject(Object)
        end
        if Generation == Runtime.PerformanceGeneration then
            LogSuccess(
                "Performance Mode enabled: "
                .. DisabledCount .. " effects disabled, "
                .. SimplifiedCount .. " parts simplified"
            )
        end
    end)
end
local StopSpectating
local function SetCharacterLocked(Value)
    local R = Root()
    if not R then return end
    if Value then
        if Runtime.AnchorStates[R] == nil then
            Runtime.AnchorStates[R] = R.Anchored
        end
        R.Anchored = true
        R.AssemblyLinearVelocity = Vector3.zero
        R.AssemblyAngularVelocity = Vector3.zero
    else
        local OriginalAnchored = Runtime.AnchorStates[R]
        if OriginalAnchored ~= nil then
            R.Anchored = OriginalAnchored
            Runtime.AnchorStates[R] = nil
        end
    end
end

local FreecamLooking = false
local function DisconnectFreecamInputs()
    for _, Connection in pairs({
        FreecamMouseConnection,
        FreecamEndConnection,
        FreecamChangedConnection
    }) do
        if Connection then
            pcall(function() Connection:Disconnect() end)
        end
    end
    FreecamMouseConnection = nil
    FreecamEndConnection = nil
    FreecamChangedConnection = nil
end
local function StopFreecam()
    local WasEnabled = FreecamEnabled
    FreecamEnabled = false
    FreecamLooking = false
    if FreecamConnection then
        FreecamConnection:Disconnect()
        FreecamConnection = nil
    end
    DisconnectFreecamInputs()
    if not WasEnabled then return end
    UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    Camera.CameraType = Enum.CameraType.Custom
    Camera.FieldOfView = FreecamOriginalFOV
    local H = Humanoid()
    if H and not Spectating then
        Camera.CameraSubject = H
    end
    if not Spectating then
        SetCharacterLocked(false)
    end
    if WasEnabled then
        LogSuccess("Freecam disabled")
    end
end
local function StartFreecam()
    StopSpectating()
    StopFreecam()
    if not Root() then
        Notify("Freecam", "Your character is unavailable.")
        LogWarning("Freecam failed: character unavailable")
        return
    end
    SetCharacterLocked(true)
    FreecamEnabled = true
    FreecamCFrame = Camera.CFrame
    FreecamOriginalFOV = Camera.FieldOfView
    local X, Y = FreecamCFrame:ToOrientation()
    FreecamRotation = Vector2.new(X, Y)
    Camera.CameraType = Enum.CameraType.Scriptable
    UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    if FreecamCinematicEnabled then
        Camera.FieldOfView = 50
    end
    FreecamMouseConnection = Runtime.TrackCleanup(UserInputService.InputBegan:Connect(function(Input, Processed)
        if Processed or not FreecamEnabled then return end
        if Input.UserInputType == Enum.UserInputType.MouseButton2 then
            FreecamLooking = true
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
        end
    end),"Disconnect","FreecamInputBegan","Connections")
    FreecamEndConnection = Runtime.TrackCleanup(UserInputService.InputEnded:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton2 then
            FreecamLooking = false
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        end
    end),"Disconnect","FreecamInputEnded","Connections")
    FreecamChangedConnection = Runtime.TrackCleanup(UserInputService.InputChanged:Connect(function(Input)
        if not FreecamEnabled then return end
        if Input.UserInputType == Enum.UserInputType.MouseMovement and FreecamLooking then
            local Sensitivity = FreecamCinematicEnabled and 0.0018 or 0.0028
            FreecamRotation -= Vector2.new(Input.Delta.Y, Input.Delta.X) * Sensitivity
            FreecamRotation = Vector2.new(
                math.clamp(FreecamRotation.X, -1.55, 1.55),
                FreecamRotation.Y
            )
        elseif Input.UserInputType == Enum.UserInputType.MouseWheel then
            local Direction = Input.Position.Z > 0 and 1 or -1
            FreecamSpeed = math.clamp(FreecamSpeed + Direction * FreecamScrollStep, 5, 250)
        end
    end),"Disconnect","FreecamInputChanged","Connections")
    FreecamConnection = Runtime.TrackCleanup(RunService.RenderStepped:Connect(function(Delta)
        if not FreecamEnabled then return end
        local Rotation = CFrame.fromOrientation(FreecamRotation.X, FreecamRotation.Y, 0)
        local Direction = Vector3.zero
        if not UserInputService:GetFocusedTextBox() then
            if UserInputService:IsKeyDown(Enum.KeyCode.W) then Direction += Rotation.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then Direction -= Rotation.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then Direction -= Rotation.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then Direction += Rotation.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.E) then Direction += Vector3.yAxis end
            if UserInputService:IsKeyDown(Enum.KeyCode.Q) then Direction -= Vector3.yAxis end
        end
        if Direction.Magnitude > 0 then Direction = Direction.Unit end
        local SpeedMultiplier = FreecamCinematicEnabled and 0.45 or 1
        local Position = FreecamCFrame.Position + Direction * FreecamSpeed * SpeedMultiplier * Delta
        local TargetCFrame = CFrame.new(Position) * Rotation
        FreecamCFrame = TargetCFrame
        if FreecamSmoothEnabled or FreecamCinematicEnabled then
            local Amount = FreecamCinematicEnabled
                and math.min(FreecamSmoothness, 0.12)
                or FreecamSmoothness
            local Alpha = 1 - math.pow(1 - math.clamp(Amount, 0.02, 1), Delta * 60)
            Camera.CFrame = Camera.CFrame:Lerp(TargetCFrame, Alpha)
        else
            Camera.CFrame = TargetCFrame
        end
    end),"Disconnect","FreecamRender","Connections")
    LogSuccess("Freecam enabled")
end
local function SaveFreecamPosition()
    if not FreecamEnabled then
        Notify("Freecam", "Enable Freecam first.")
        return
    end
    SavedFreecamCFrame = Camera.CFrame
    Notify("Freecam", "Camera position saved.")
end
local function ReturnToSavedFreecamPosition()
    if not SavedFreecamCFrame then
        Notify("Freecam", "Save a camera position first.")
        return
    end
    if not FreecamEnabled then StartFreecam() end
    FreecamCFrame = SavedFreecamCFrame
    Camera.CFrame = SavedFreecamCFrame
    local X, Y = SavedFreecamCFrame:ToOrientation()
    FreecamRotation = Vector2.new(X, Y)
    LogSuccess("Returned to saved Freecam position")
end
local function SetCameraShake(Value)
    CameraShakeEnabled = Value
    if CameraShakeConnection then
        CameraShakeConnection:Disconnect()
        CameraShakeConnection = nil
    end
    if not Value then return end
    CameraShakeConnection = Runtime.TrackCleanup(RunService.RenderStepped:Connect(function()
        if CameraShakeEnabled and not FreecamEnabled then
            local Offset = Vector3.new(
                (math.random() - 0.5) * CameraShakeStrength,
                (math.random() - 0.5) * CameraShakeStrength,
                0
            )
            Camera.CFrame = Camera.CFrame * CFrame.new(Offset)
        end
    end),"Disconnect","CameraShakeRender","Connections")
end
StopSpectating = function()
    Spectating = false
    if SpectatorConnection then
        SpectatorConnection:Disconnect()
        SpectatorConnection = nil
    end
    Camera.CameraType = Enum.CameraType.Custom
    local H = Humanoid()
    if H and not FreecamEnabled then
        Camera.CameraSubject = H
    end
    if not FreecamEnabled then
        SetCharacterLocked(false)
    end
    if SpectatorInfo then
        local SelectedText = SpectatorTarget
            and ("Selected: " .. SpectatorTarget.DisplayName .. " (@" .. SpectatorTarget.Name .. ")")
            or "Select a player above."
        SpectatorInfo:Set({ Title = "Spectator", Content = SelectedText })
    end
end
local function StartSpectating(Target)
    if not Target or Target == Player then
        Notify("Spectator", "Select another player first.")
        return
    end
    StopFreecam()
    StopSpectating()
    SetCharacterLocked(true)
    SpectatorTarget = Target
    Spectating = true
    LogSuccess("Spectating " .. Target.DisplayName)
    local InitialCharacter = Target.Character
    local InitialHumanoid = InitialCharacter and InitialCharacter:FindFirstChildOfClass("Humanoid")
    if InitialHumanoid then
        Camera.CameraType = Enum.CameraType.Custom
        Camera.CameraSubject = InitialHumanoid
    end
    local Accumulator = 0.25
    SpectatorConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
        if not Spectating or not SpectatorTarget or not SpectatorTarget.Parent then
            StopSpectating()
            return
        end
        Accumulator += Delta
        if Accumulator < 0.25 then return end
        Accumulator = 0
        local TargetCharacter = SpectatorTarget.Character
        local TargetHumanoid = TargetCharacter and TargetCharacter:FindFirstChildOfClass("Humanoid")
        local TargetRoot = TargetCharacter and TargetCharacter:FindFirstChild("HumanoidRootPart")
        local MyRoot = Root()
        if TargetHumanoid then
            Camera.CameraType = Enum.CameraType.Custom
            Camera.CameraSubject = TargetHumanoid
        end
        if SpectatorInfo then
            local Distance = MyRoot and TargetRoot
                and math.floor((MyRoot.Position - TargetRoot.Position).Magnitude) or 0
            local Health = TargetHumanoid
                and (math.floor(TargetHumanoid.Health) .. "/" .. math.floor(TargetHumanoid.MaxHealth))
                or "N/A"
            local Speed = TargetHumanoid and math.floor(TargetHumanoid.WalkSpeed) or "N/A"
            SpectatorInfo:Set({
                Title = "👀 " .. SpectatorTarget.DisplayName,
                Content =
                    "Username: @" .. SpectatorTarget.Name
                    .. "\nHealth: " .. Health
                    .. "\nDistance: " .. tostring(Distance) .. " studs"
                    .. "\nState: " .. CharacterState(TargetHumanoid)
                    .. "\nWalkSpeed: " .. tostring(Speed)
                    .. "\nAccount Age: " .. tostring(SpectatorTarget.AccountAge) .. " days"
                    .. "\nUser ID: " .. tostring(SpectatorTarget.UserId)
            })
        end
    end),"Disconnect","SpectatorHeartbeat","Connections")
end
local function GetSpectatorCandidates()
    local List = {}
    for _, Target in ipairs(Runtime.CachedPlayers()) do
        if Target ~= Player then
            table.insert(List, Target)
        end
    end
    table.sort(List, function(A, B)
        return string.lower(A.DisplayName .. A.Name) < string.lower(B.DisplayName .. B.Name)
    end)
    return List
end
local function SwitchSpectator(Direction)
    local Candidates = GetSpectatorCandidates()
    if #Candidates == 0 then
        StopSpectating()
        Notify("Spectator", "No other players are available.")
        return
    end
    local CurrentIndex = 0
    for Index, Target in ipairs(Candidates) do
        if Target == SpectatorTarget then
            CurrentIndex = Index
            break
        end
    end
    local NextIndex
    if Direction < 0 then
        NextIndex = CurrentIndex > 1 and CurrentIndex - 1 or #Candidates
    else
        NextIndex = CurrentIndex < #Candidates and CurrentIndex + 1 or 1
    end
    SpectatorTarget = Candidates[NextIndex]
    if Spectating then
        StartSpectating(SpectatorTarget)
    elseif SpectatorInfo then
        SpectatorInfo:Set({
            Title = "Spectator",
            Content = "Selected: " .. SpectatorTarget.DisplayName .. " (@" .. SpectatorTarget.Name .. ")"
        })
    end
end

local function RefreshPlayers()
    local Names = GetDisplayNames()
    if PlayerDropdown then PlayerDropdown:Refresh(Names) end
    if SpectatorDropdown then SpectatorDropdown:Refresh(Names) end
    if Runtime.RefreshStatsPlayers then Runtime.RefreshStatsPlayers() end
    if SelectedPlayer and not FindPlayerByDisplayName(SelectedPlayer) then
        SelectedPlayer = nil
    end
    if SpectatorTarget and not SpectatorTarget.Parent then
        SpectatorTarget = nil
    end
end
local function SchedulePlayerRefresh()
    if Runtime.RefreshPlayersPending then return end
    Runtime.RefreshPlayersPending = true
    task.defer(function()
        Runtime.RefreshPlayersPending = false
        if not Unloaded then RefreshPlayers() end
    end)
end
TrackConnection(Players.PlayerAdded:Connect(function(Target)
    SchedulePlayerRefresh()
    LogInformation(Target.DisplayName .. " joined the server.", "Server")
end))
TrackConnection(Players.PlayerRemoving:Connect(function(Target)
    local WasSpectated = Spectating and SpectatorTarget == Target
    LogInformation("Player left: " .. Target.DisplayName .. " (@" .. Target.Name .. ")", "Spectator")
    SchedulePlayerRefresh()
    if WasSpectated then
        task.defer(function()
            if Unloaded then return end
            SpectatorTarget = nil
            local Candidates = GetSpectatorCandidates()
            if #Candidates > 0 then
                SpectatorTarget = Candidates[1]
                StartSpectating(SpectatorTarget)
                LogInformation("Automatically switched to " .. SpectatorTarget.DisplayName, "Spectator")
            else
                StopSpectating()
                Notify("Spectator", "The player left and nobody else is available.")
            end
        end)
    end
end))

local LastSafeCFrame = nil
local AntiVoidHeight = -50
local function SetAntiVoid(Value)
    AntiVoidEnabled = Value
    if AntiVoidConnection then
        AntiVoidConnection:Disconnect()
        AntiVoidConnection = nil
    end
    if not Value then return end
    local Accumulator = 0
    AntiVoidConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
        Accumulator += Delta
        if Accumulator < 0.10 then return end
        Accumulator = 0
        local R = Root()
        local H = Humanoid()
        if not R or not H or H.Health <= 0 then return end
        if H.FloorMaterial ~= Enum.Material.Air and R.Position.Y > AntiVoidHeight + 15 then
            LastSafeCFrame = R.CFrame
        elseif R.Position.Y <= AntiVoidHeight and LastSafeCFrame then
            R.AssemblyLinearVelocity = Vector3.zero
            R.AssemblyAngularVelocity = Vector3.zero
            R.CFrame = LastSafeCFrame + Vector3.new(0, 4, 0)
            Notify("Anti Void", "Returned you to your last safe position.")
        end
    end),"Disconnect","AntiVoidHeartbeat","Connections")
end
local function SetAntiRagdoll(Value)
    AntiRagdollEnabled = Value
    if AntiRagdollConnection then
        AntiRagdollConnection:Disconnect()
        AntiRagdollConnection = nil
    end
    if not Value then return end
    local Accumulator = 0
    AntiRagdollConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
        Accumulator += Delta
        if Accumulator < 0.10 then return end
        Accumulator = 0
        local H = Humanoid()
        if not H or H.Health <= 0 then return end
        H.PlatformStand = false
        H.Sit = false
        local State = H:GetState()
        if State == Enum.HumanoidStateType.Ragdoll
            or State == Enum.HumanoidStateType.FallingDown
            or State == Enum.HumanoidStateType.Physics then
            H:ChangeState(Enum.HumanoidStateType.GettingUp)
        end
    end),"Disconnect","AntiRagdollHeartbeat","Connections")
end
local function SetSpiderClimb(Value)
    SpiderClimbEnabled = Value
    if SpiderClimbConnection then
        SpiderClimbConnection:Disconnect()
        SpiderClimbConnection = nil
    end
    if not Value then return end
    local Accumulator = 0
    local Params = RaycastParams.new()
    Params.FilterType = Enum.RaycastFilterType.Exclude
    SpiderClimbConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
        Accumulator += Delta
        if Accumulator < 0.05 then return end
        Accumulator = 0
        local R = Root()
        local H = Humanoid()
        local C = Runtime.ActiveMovementCharacter()
        if not R or not H or not C then return end
        Params.FilterDescendantsInstances = Runtime.CharacterRaycastIgnore()
        local Result = workspace:Raycast(R.Position, R.CFrame.LookVector * 3.5, Params)
        if Result and UserInputService:IsKeyDown(Enum.KeyCode.W) then
            R.AssemblyLinearVelocity = Vector3.new(R.AssemblyLinearVelocity.X, 32, R.AssemblyLinearVelocity.Z)
            H:ChangeState(Enum.HumanoidStateType.Climbing)
        end
    end),"Disconnect","SpiderHeartbeat","Connections")
end

local function RemoveESPFromCharacter(CharacterModel)
    if not CharacterModel then return end
    local RootPart = CharacterModel:FindFirstChild("HumanoidRootPart")
    if RootPart then
        local Existing = RootPart:FindFirstChild("BananiESP")
        if Existing then Existing:Destroy() end
        local Info = RootPart:FindFirstChild("BananiInfo")
        if Info then Info:Destroy() end
    end
end

local function SmoothESPFill(Fill,Ratio)
    if not Fill or not Fill.Parent then return end
    Ratio=math.clamp(tonumber(Ratio) or 0,0,1)
    local Current=tonumber(Fill.Size.X.Scale) or 0
    local Next=Current+(Ratio-Current)*0.36
    if math.abs(Ratio-Next)<0.008 then Next=Ratio end
    Fill.Size=UDim2.new(Next,0,1,0)
end

local function GetESPCharacterScreenHeight(CharacterModel)
    local CurrentCamera = workspace.CurrentCamera or Camera
    if not CurrentCamera or not CharacterModel then return nil end

    local Ok, BoundsCF, BoundsSize = pcall(function()
        local CF, Size = CharacterModel:GetBoundingBox()
        return CF, Size
    end)
    if not Ok or typeof(BoundsCF) ~= "CFrame" or typeof(BoundsSize) ~= "Vector3" then return nil end

    local HalfHeight = math.max(BoundsSize.Y * 0.5, 2.5)
    local Top = CurrentCamera:WorldToViewportPoint(BoundsCF.Position + Vector3.new(0, HalfHeight, 0))
    local Bottom = CurrentCamera:WorldToViewportPoint(BoundsCF.Position - Vector3.new(0, HalfHeight, 0))
    if Top.Z <= 0 or Bottom.Z <= 0 then return nil end

    return math.abs(Bottom.Y - Top.Y)
end

local function LayoutESPInfoCard(InfoBillboard, NamePlate, ScreenHeight, ForceFullInfo)
    if not InfoBillboard or not NamePlate then return "Hidden" end
    ScreenHeight = tonumber(ScreenHeight) or 0

    local RoleText = NamePlate:FindFirstChild("RoleText")
    local NameText = NamePlate:FindFirstChild("NameText")
    local MetaText = NamePlate:FindFirstChild("MetaText")
    local HealthBack = NamePlate:FindFirstChild("HealthBack")
    local HealthText = NamePlate:FindFirstChild("HealthText")
    local Accent = NamePlate:FindFirstChild("Accent")
    local ScaleObj = NamePlate:FindFirstChild("DistanceScale")
    if ScaleObj then ScaleObj.Scale = 1 end

    -- Chams info must keep the SAME fields at every distance. It may scale down gently,
    -- but role/name/meta/health are never removed just because the target is far away.
    if ForceFullInfo then
        local VisibleHeight=math.max(ScreenHeight,8)
        local Width=math.clamp(150 + VisibleHeight*0.20,150,198)
        local Height=math.clamp(58 + VisibleHeight*0.05,58,68)
        InfoBillboard.Size=UDim2.fromOffset(Width,Height)
        InfoBillboard.StudsOffset=Vector3.zero
        InfoBillboard.StudsOffsetWorldSpace=Vector3.new(0,2.05,0)
        NamePlate.Visible=true
        if Accent then Accent.Position=UDim2.fromOffset(0,5); Accent.Size=UDim2.new(0,3,1,-10) end
        if RoleText then RoleText.Visible=true; RoleText.Position=UDim2.fromOffset(9,3); RoleText.Size=UDim2.new(1,-18,0,11); RoleText.TextSize=9 end
        if NameText then NameText.Visible=true; NameText.Position=UDim2.fromOffset(9,15); NameText.Size=UDim2.new(1,-18,0,16); NameText.TextSize=11.5; NameText.TextXAlignment=Enum.TextXAlignment.Left end
        if MetaText then MetaText.Visible=true; MetaText.Position=UDim2.fromOffset(9,32); MetaText.Size=UDim2.new(1,-18,0,11); MetaText.TextSize=8.5; MetaText.TextXAlignment=Enum.TextXAlignment.Left end
        if HealthBack then HealthBack.Visible=true; HealthBack.Position=UDim2.fromOffset(9,Height-11); HealthBack.Size=UDim2.new(1,-18,0,6) end
        if HealthText then HealthText.Visible=true; HealthText.Position=UDim2.new(1,-9,0,35); HealthText.Size=UDim2.fromOffset(78,11); HealthText.TextSize=8.5 end
        return "Full"
    end

    -- v5.16.0: distance may shrink the card, but never squeeze readable information away.
    -- Keep a readable minimum size at distance; only hide when the projected avatar is essentially a dot.
    if ScreenHeight < 8 then
        InfoBillboard.Size = UDim2.fromOffset(1, 1)
        InfoBillboard.StudsOffset = Vector3.zero
        InfoBillboard.StudsOffsetWorldSpace = Vector3.new(0, 1.45, 0)
        NamePlate.Visible = false
        return "Hidden"
    end

    NamePlate.Visible = true

    if ScreenHeight < 70 then
        -- Tiny is still readable: name + distance/meta. Never collapse below a practical 112x32.
        local Width = math.clamp(112 + (ScreenHeight-8)*0.30, 112, 132)
        InfoBillboard.Size = UDim2.fromOffset(Width, 32)
        InfoBillboard.StudsOffset = Vector3.zero
        InfoBillboard.StudsOffsetWorldSpace = Vector3.new(0, 1.62, 0)
        if Accent then Accent.Position=UDim2.fromOffset(0,3); Accent.Size=UDim2.new(0,3,1,-6) end
        if RoleText then RoleText.Visible=false end
        if NameText then
            NameText.Position=UDim2.fromOffset(7,1)
            NameText.Size=UDim2.new(1,-14,0,15)
            NameText.TextSize=11.5
            NameText.TextXAlignment=Enum.TextXAlignment.Left
        end
        if MetaText then
            MetaText.Visible=true
            MetaText.Position=UDim2.fromOffset(7,17)
            MetaText.Size=UDim2.new(1,-14,0,11)
            MetaText.TextSize=9.5
            MetaText.TextXAlignment=Enum.TextXAlignment.Left
        end
        if HealthBack then HealthBack.Visible=false end
        if HealthText then HealthText.Visible=false end
        return "Tiny"
    end

    if ScreenHeight < 150 then
        -- Compact keeps the important text and health strip while remaining smaller at range.
        local Width = math.clamp(ScreenHeight * 0.66 + 92, 138, 166)
        InfoBillboard.Size = UDim2.fromOffset(Width, 48)
        InfoBillboard.StudsOffset = Vector3.zero
        InfoBillboard.StudsOffsetWorldSpace = Vector3.new(0, 1.82, 0)
        if Accent then Accent.Position=UDim2.fromOffset(0,4); Accent.Size=UDim2.new(0,3,1,-8) end
        if RoleText then RoleText.Visible=false end
        if NameText then
            NameText.Position=UDim2.fromOffset(8,2)
            NameText.Size=UDim2.new(1,-16,0,17)
            NameText.TextSize=12.5
            NameText.TextXAlignment=Enum.TextXAlignment.Left
        end
        if MetaText then
            MetaText.Visible=true
            MetaText.Position=UDim2.fromOffset(8,20)
            MetaText.Size=UDim2.new(1,-16,0,12)
            MetaText.TextSize=9.5
            MetaText.TextXAlignment=Enum.TextXAlignment.Left
        end
        if HealthBack then HealthBack.Visible=true; HealthBack.Position=UDim2.fromOffset(8,39); HealthBack.Size=UDim2.new(1,-16,0,5) end
        if HealthText then HealthText.Visible=false end
        return "Compact"
    end

    -- Full stays noticeably larger than v5.15.4 but is still capped well below the old 218px panel.
    local Width = math.clamp(ScreenHeight * 0.42 + 120, 174, 198)
    InfoBillboard.Size = UDim2.fromOffset(Width, 68)
    InfoBillboard.StudsOffset = Vector3.zero
    InfoBillboard.StudsOffsetWorldSpace = Vector3.new(0, 2.15, 0)
    if Accent then Accent.Position=UDim2.fromOffset(0,6); Accent.Size=UDim2.new(0,3,1,-12) end
    if RoleText then RoleText.Visible=true; RoleText.Position=UDim2.fromOffset(10,3); RoleText.Size=UDim2.new(1,-20,0,12); RoleText.TextSize=9.5 end
    if NameText then NameText.Position=UDim2.fromOffset(10,16); NameText.Size=UDim2.new(1,-20,0,17); NameText.TextSize=12; NameText.TextXAlignment=Enum.TextXAlignment.Left end
    if MetaText then MetaText.Visible=true; MetaText.Position=UDim2.fromOffset(10,34); MetaText.Size=UDim2.new(1,-20,0,11); MetaText.TextSize=9; MetaText.TextXAlignment=Enum.TextXAlignment.Left end
    if HealthBack then HealthBack.Visible=true; HealthBack.Position=UDim2.fromOffset(10,57); HealthBack.Size=UDim2.new(1,-20,0,7) end
    if HealthText then HealthText.Visible=true; HealthText.Position=UDim2.new(1,-10,0,38); HealthText.Size=UDim2.fromOffset(82,12); HealthText.TextSize=9.0 end
    return "Full"
end

local function UpdatePlayerESP(Target)
    if Target == Player then return end
    local SharedESPState=Runtime.PlayerESPState
    local ProfileOnly=SharedESPState and SharedESPState.ProfileEnabled and not SharedESPState.Enabled
    local ProfileOptions=ProfileOnly and SharedESPState.ProfileOptions or nil
    local function ProfileOption(Key,Default,...)
        if not ProfileOptions then return Default end
        local Value=ProfileOptions[Key]
        if type(Value)=="function" then
            local Ok,Result=pcall(Value,...)
            if Ok then Value=Result else Value=nil end
        end
        if Value==nil then return Default end
        return Value
    end
    local EffectiveBox=ProfileOption("ShowBox",BoxESPEnabled,Target)==true
    local EffectiveHealth=ProfileOption("ShowHealth",HealthESPEnabled,Target)==true
    local EffectiveNames=ProfileOption("ShowNames",true,Target)==true
    local EffectiveDistance=ProfileOption("ShowDistance",true,Target)==true
    if SharedESPState and SharedESPState.ProfileEnabled and not SharedESPState.Enabled
        and type(SharedESPState.ProfileFilter)=="function" then
        local Ok,Allowed=pcall(SharedESPState.ProfileFilter,Target)
        if not Ok or not Allowed then RemoveESPFromCharacter(Target.Character); return end
    end
    if Runtime.VisualEngine and not Runtime.VisualEngine.PlayerAllowed(Target) then
        RemoveESPFromCharacter(Target.Character)
        return
    end
    local C = Target.Character
    local R = C and C:FindFirstChild("HumanoidRootPart")
    local H = C and C:FindFirstChildOfClass("Humanoid")
    if not C or not R or not H or H.Health <= 0 or (not EffectiveBox and not EffectiveHealth and not ChamsEnabled) then
        RemoveESPFromCharacter(C)
        return
    end

    -- Chams owns the custom overhead card, so suppress Roblox's normal local name/health tag.
    -- This is also applied here so respawned/new players inherit it while Chams stays enabled.
    if ChamsEnabled then
        Runtime.ChamsHumanoidDisplayBackup = Runtime.ChamsHumanoidDisplayBackup or setmetatable({}, {__mode="k"})
        local Backup=Runtime.ChamsHumanoidDisplayBackup
        if not Backup[H] then
            Backup[H]={DisplayDistanceType=H.DisplayDistanceType,NameDisplayDistance=H.NameDisplayDistance,HealthDisplayType=H.HealthDisplayType}
        end
        pcall(function()
            H.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None
            H.NameDisplayDistance=0
            H.HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff
        end)
    end

    local Settings = Runtime.VisualEngine and Runtime.VisualEngine.Settings
    local MaxDistance = tonumber(ProfileOption("MaxDistance",Settings and Settings.MaxDistance or 1200,Target)) or 1200
    local MyRoot = Root()
    local Distance = MyRoot and (R.Position - MyRoot.Position).Magnitude or 0
    local Billboard = R:FindFirstChild("BananiESP")
    if not Billboard then
        Billboard = Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
        Billboard.Name = "BananiESP"
        Billboard.AlwaysOnTop = true
        Billboard.LightInfluence = 0
        Billboard.Size = UDim2.fromOffset(240, 190)
        Billboard.StudsOffset = Vector3.new(0, 0.55, 0)
        Billboard.Adornee = R
        Billboard.Parent = R

        local Box = Instance.new("Frame")
        Box.Name = "Box"
        Box.AnchorPoint = Vector2.new(0.5, 0.5)
        Box.Position = UDim2.new(0.5, 0, 0.56, 0)
        Box.Size = UDim2.fromOffset(70, 98)
        Box.BackgroundTransparency = 1
        Box.Parent = Billboard

        local Glow = Instance.new("UIStroke")
        Glow.Name = "GlowStroke"
        Glow.Thickness = 5
        Glow.Transparency = 0.82
        Glow.Color = ChamsFillColor
        Glow.Parent = Box

        local function Corner(Name, Position, Size)
            local Line = Instance.new("Frame")
            Line.Name = Name
            Line.Position = Position
            Line.Size = Size
            Line.BorderSizePixel = 0
            Line.BackgroundColor3 = ChamsFillColor
            Line.Parent = Box
            local Stroke = Instance.new("UIStroke")
            Stroke.Thickness = 1
            Stroke.Transparency = 0.30
            Stroke.Color = Color3.new(1, 1, 1)
            Stroke.Parent = Line
            return Line
        end
        local L = 16
        local T = 2
        Corner("TL_H", UDim2.fromOffset(0, 0), UDim2.fromOffset(L, T))
        Corner("TL_V", UDim2.fromOffset(0, 0), UDim2.fromOffset(T, L))
        Corner("TR_H", UDim2.new(1, -L, 0, 0), UDim2.fromOffset(L, T))
        Corner("TR_V", UDim2.new(1, -T, 0, 0), UDim2.fromOffset(T, L))
        Corner("BL_H", UDim2.new(0, 0, 1, -T), UDim2.fromOffset(L, T))
        Corner("BL_V", UDim2.new(0, 0, 1, -L), UDim2.fromOffset(T, L))
        Corner("BR_H", UDim2.new(1, -L, 1, -T), UDim2.fromOffset(L, T))
        Corner("BR_V", UDim2.new(1, -T, 1, -L), UDim2.fromOffset(T, L))

        local InfoBillboard = Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
        InfoBillboard.Name = "BananiInfo"
        InfoBillboard.AlwaysOnTop = true
        InfoBillboard.LightInfluence = 0
        InfoBillboard.MaxDistance = 0
        InfoBillboard.Size = UDim2.fromOffset(218, 78)
        InfoBillboard.StudsOffset = Vector3.new(0, 3.85, 0)
        InfoBillboard.Adornee = C:FindFirstChild("Head") or R
        InfoBillboard.Parent = R

        local NamePlate = Instance.new("Frame")
        NamePlate.Name = "NamePlate"
        NamePlate.AnchorPoint = Vector2.new(0.5, 0.5)
        NamePlate.Position = UDim2.fromScale(0.5, 0.5)
        NamePlate.Size = UDim2.fromScale(1, 1)
        NamePlate.BackgroundColor3 = Color3.fromRGB(10, 10, 14)
        NamePlate.BackgroundTransparency = 0.10
        NamePlate.BorderSizePixel = 0
        NamePlate.Parent = InfoBillboard
        local DistanceScale = Instance.new("UIScale")
        DistanceScale.Name = "DistanceScale"
        DistanceScale.Scale = 1
        DistanceScale.Parent = NamePlate
        local CornerObject = Instance.new("UICorner")
        CornerObject.CornerRadius = UDim.new(0, 9)
        CornerObject.Parent = NamePlate
        local NameStroke = Instance.new("UIStroke")
        NameStroke.Name = "AccentStroke"
        NameStroke.Thickness = 1.25
        NameStroke.Color = ChamsFillColor
        NameStroke.Transparency = 0.08
        NameStroke.Parent = NamePlate

        local Accent = Instance.new("Frame")
        Accent.Name = "Accent"
        Accent.Position = UDim2.fromOffset(0, 8)
        Accent.Size = UDim2.new(0, 4, 1, -16)
        Accent.BackgroundColor3 = ChamsFillColor
        Accent.BorderSizePixel = 0
        Accent.Parent = NamePlate
        local AccentCorner = Instance.new("UICorner")
        AccentCorner.CornerRadius = UDim.new(0, 4)
        AccentCorner.Parent = Accent

        local RoleText = Instance.new("TextLabel")
        RoleText.Name = "RoleText"
        RoleText.BackgroundTransparency = 1
        RoleText.Position = UDim2.fromOffset(12, 4)
        RoleText.Size = UDim2.new(1, -24, 0, 15)
        RoleText.Font = Enum.Font.GothamBold
        RoleText.TextSize = 10
        RoleText.Text = "PLAYER"
        RoleText.TextColor3 = ChamsFillColor
        RoleText.TextXAlignment = Enum.TextXAlignment.Left
        RoleText.TextTruncate = Enum.TextTruncate.AtEnd
        RoleText.Parent = NamePlate

        local NameText = Instance.new("TextLabel")
        NameText.Name = "NameText"
        NameText.BackgroundTransparency = 1
        NameText.Position = UDim2.fromOffset(12, 20)
        NameText.Size = UDim2.new(1, -24, 0, 18)
        NameText.Font = Enum.Font.GothamBold
        NameText.TextSize = 13
        NameText.TextColor3 = Color3.fromRGB(250, 250, 252)
        NameText.TextXAlignment = Enum.TextXAlignment.Left
        NameText.TextTruncate = Enum.TextTruncate.AtEnd
        NameText.Parent = NamePlate

        local MetaText = Instance.new("TextLabel")
        MetaText.Name = "MetaText"
        MetaText.BackgroundTransparency = 1
        MetaText.Position = UDim2.fromOffset(12, 39)
        MetaText.Size = UDim2.new(1, -24, 0, 14)
        MetaText.Font = Enum.Font.GothamMedium
        MetaText.TextSize = 9.5
        MetaText.TextColor3 = Color3.fromRGB(192, 194, 203)
        MetaText.TextXAlignment = Enum.TextXAlignment.Left
        MetaText.TextTruncate = Enum.TextTruncate.AtEnd
        MetaText.Parent = NamePlate

        local HealthBack = Instance.new("Frame")
        HealthBack.Name = "HealthBack"
        HealthBack.AnchorPoint = Vector2.new(0, 0)
        HealthBack.Position = UDim2.fromOffset(12, 61)
        HealthBack.Size = UDim2.new(1, -24, 0, 7)
        HealthBack.BackgroundColor3 = Color3.fromRGB(19, 19, 24)
        HealthBack.BackgroundTransparency = 0.06
        HealthBack.BorderSizePixel = 0
        HealthBack.ClipsDescendants = true
        HealthBack.Parent = NamePlate
        local HC = Instance.new("UICorner")
        HC.CornerRadius = UDim.new(1, 0)
        HC.Parent = HealthBack
        local HS = Instance.new("UIStroke")
        HS.Name = "RoleStroke"
        HS.Thickness = 1
        HS.Transparency = 0.30
        HS.Color = ChamsFillColor
        HS.Parent = HealthBack

        local HealthFill = Instance.new("Frame")
        HealthFill.Name = "HealthFill"
        HealthFill.Size = UDim2.fromScale(1, 1)
        HealthFill.BackgroundColor3 = Color3.fromRGB(75, 255, 110)
        HealthFill.BorderSizePixel = 0
        HealthFill.Parent = HealthBack
        local HFC = Instance.new("UICorner")
        HFC.CornerRadius = UDim.new(1, 0)
        HFC.Parent = HealthFill

        local HealthText = Instance.new("TextLabel")
        HealthText.Name = "HealthText"
        HealthText.BackgroundTransparency = 1
        HealthText.AnchorPoint = Vector2.new(1, 0)
        HealthText.Position = UDim2.new(1, -12, 0, 40)
        HealthText.Size = UDim2.fromOffset(88, 13)
        HealthText.Font = Enum.Font.GothamBold
        HealthText.TextSize = 9
        HealthText.TextXAlignment = Enum.TextXAlignment.Right
        HealthText.TextColor3 = Color3.fromRGB(246, 246, 249)
        HealthText.TextStrokeTransparency = 0.55
        HealthText.Parent = NamePlate
    end

    if Distance > MaxDistance and not ChamsEnabled then
        Billboard.Enabled = false
        local FarInfo=R:FindFirstChild("BananiInfo")
        if FarInfo then FarInfo.Enabled=false end
        return
    end
    Billboard.Enabled = Distance <= MaxDistance and (EffectiveBox or EffectiveHealth)

    local Color,Occluded,DetectedRole,RoleSource = ChamsFillColor,false,"Player","Fallback"
    if Runtime.VisualEngine and Runtime.VisualEngine.GetPlayerESPColor then
        Color,Occluded,DetectedRole,RoleSource = Runtime.VisualEngine.GetPlayerESPColor(Target)
    elseif Target.Team then
        Color = Target.Team.TeamColor.Color
    end

    local DistanceRatio=math.clamp(Distance/math.max(MaxDistance,1),0,1)
    local Fade=ChamsEnabled and 0 or (math.clamp((DistanceRatio-0.55)/0.45,0,1)*0.52)
    local PulseAllowed = Settings and Settings.GlowPulse and not (Runtime.AFKMode and Runtime.AFKMode.Active)
    local Pulse = PulseAllowed and (math.sin(os.clock() * 3.4) * 0.07) or 0
    local Box = Billboard:FindFirstChild("Box")
    local InfoBillboard = R:FindFirstChild("BananiInfo")
    local NamePlate = InfoBillboard and InfoBillboard:FindFirstChild("NamePlate")
    local InfoMode="Hidden"
    if InfoBillboard then
        InfoBillboard.MaxDistance=0
        -- Size from what the avatar ACTUALLY occupies on the screen, not world distance.
        -- This handles different camera FOVs, resolutions, avatar scales, and zoom levels.
        -- Chams keeps the full identity, role, distance and health card at every range.
        local ScreenHeight=GetESPCharacterScreenHeight(C) or 8
        InfoMode=LayoutESPInfoCard(InfoBillboard,NamePlate,ScreenHeight,ChamsEnabled)
        InfoBillboard.Enabled = (InfoMode~="Hidden") and (ChamsEnabled or (Distance <= MaxDistance and (EffectiveBox or EffectiveHealth)))
    end
    local HealthBack = NamePlate and NamePlate:FindFirstChild("HealthBack")
    local HealthText = NamePlate and NamePlate:FindFirstChild("HealthText")
    if Box then
        Box.Visible = EffectiveBox
        local Glow = Box:FindFirstChild("GlowStroke")
        if Glow then
            Glow.Color = Occluded and ((Settings and Settings.OccludedColor) or Color3.fromRGB(255,68,76)) or Color
            local GlowOpacity=Settings and tonumber(Settings.PlayerGlowOpacity) or 0.50
            local BaseTransparency=1-math.clamp(GlowOpacity,0.10,0.90)
            Glow.Transparency = math.clamp(BaseTransparency + Fade*0.28 + Pulse, 0.08, 0.94)
        end
        for _, Child in ipairs(Box:GetChildren()) do
            if Child:IsA("Frame") then
                Child.BackgroundColor3 = Color
                Child.BackgroundTransparency=math.clamp(Fade*0.55,0,0.62)
            end
        end
    end

    if NamePlate then
        NamePlate.Visible = InfoMode~="Hidden" and (EffectiveBox or EffectiveHealth or ChamsEnabled)
        NamePlate.BackgroundTransparency=math.clamp(0.12+Fade*0.52,0.12,0.72)
        local Stroke = NamePlate:FindFirstChild("AccentStroke")
        local Accent = NamePlate:FindFirstChild("Accent")
        local RoleText = NamePlate:FindFirstChild("RoleText")
        local NameText = NamePlate:FindFirstChild("NameText")
        local MetaText = NamePlate:FindFirstChild("MetaText")
        if Stroke then
            Stroke.Color = Occluded and ((Settings and Settings.OccludedColor) or Color3.fromRGB(255,68,76)) or Color
            Stroke.Transparency=math.clamp(0.08+Fade*0.58,0.08,0.72)
        end
        if Accent then Accent.BackgroundColor3 = Color; Accent.BackgroundTransparency=Fade*0.38 end
        if RoleText then
            local Label=tostring(DetectedRole or "Player")
            local Source=tostring(RoleSource or "")
            RoleText.Visible=InfoMode=="Full"
            RoleText.Text=string.upper(Label)..((Source~="" and Source~="Fallback") and ("  •  "..string.upper(Source)) or "")
            RoleText.TextColor3=Color
            RoleText.TextTransparency=Fade*0.38
        end
        if NameText then
            local CustomName=ProfileOption("NameText",nil,Target,Distance)
            NameText.Visible=InfoMode~="Hidden" and (EffectiveNames or ChamsEnabled) and tostring(CustomName or Target.DisplayName or "")~=""
            NameText.Text=tostring(CustomName or (Target.DisplayName.."  @"..Target.Name))
            NameText.TextTransparency=Fade*0.46
        end
        if MetaText then
            local CustomMeta=ProfileOption("MetaText",nil,Target,Distance)
            MetaText.Visible=(InfoMode=="Full" or InfoMode=="Compact") and (ChamsEnabled or EffectiveDistance or (CustomMeta~=nil and tostring(CustomMeta)~=""))
            MetaText.Text=tostring(CustomMeta~=nil and CustomMeta or (math.floor(Distance+0.5).." studs"))
            MetaText.TextTransparency=Fade*0.50
        end
    end

    if HealthBack then
        HealthBack.Visible = (InfoMode=="Full" or InfoMode=="Compact") and (EffectiveHealth or ChamsEnabled)
        HealthBack.BackgroundTransparency=math.clamp(0.06+Fade*0.56,0.06,0.72)
        local RoleStroke=HealthBack:FindFirstChild("RoleStroke")
        if RoleStroke then RoleStroke.Color=Color; RoleStroke.Transparency=math.clamp(0.30+Fade*0.48,0.30,0.82) end
    end
    if HealthText then HealthText.Visible = InfoMode=="Full" and (EffectiveHealth or ChamsEnabled); HealthText.TextTransparency=Fade*0.52 end
    if (EffectiveHealth or ChamsEnabled) and HealthBack and HealthText then
        local Ratio = math.clamp(H.Health / math.max(H.MaxHealth, 1), 0, 1)
        local Fill = HealthBack:FindFirstChild("HealthFill")
        if Fill then
            SmoothESPFill(Fill,Ratio)
            Fill.BackgroundColor3 = Color3.fromRGB(255,67,76):Lerp(Color3.fromRGB(245,195,58),math.clamp(Ratio*2,0,1)):Lerp(Color3.fromRGB(72,255,118),math.clamp((Ratio-0.5)*2,0,1))
            Fill.BackgroundTransparency=Fade*0.32
        end
        HealthText.Text = math.floor(H.Health) .. " / " .. math.floor(H.MaxHealth) .. " HP"
    end
end

local function SetPlayerESP()
    if ESPConnection then
        ESPConnection:Disconnect()
        ESPConnection = nil
    end
    Runtime.PlayerESPSchedule=Runtime.PlayerESPSchedule or setmetatable({}, {__mode="k"})
    Runtime.PlayerESPMetricCache=Runtime.PlayerESPMetricCache or setmetatable({}, {__mode="k"})
    local Schedule=Runtime.PlayerESPSchedule
    local MetricCache=Runtime.PlayerESPMetricCache
    if not BoxESPEnabled and not HealthESPEnabled and not ChamsEnabled then
        for _,Target in ipairs(Runtime.CachedPlayers()) do
            RemoveESPFromCharacter(Target.Character)
            Schedule[Target]=nil
            MetricCache[Target]=nil
        end
        return
    end
    for _,Target in ipairs(Runtime.CachedPlayers()) do UpdatePlayerESP(Target); Schedule[Target]=0 end
    local Clock=0
    ESPConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
        if Unloaded then return end
        Clock += Delta
        if Clock < 0.045*Runtime.GetVisualUpdateScale() then return end
        local Step=Clock; Clock=0
        local Me=Root()
        local Cam=workspace.CurrentCamera
        for _,Target in ipairs(Runtime.CachedPlayers()) do
            if Target~=Player then
                local Due=(Schedule[Target] or 0)-Step
                if Due<=0 then
                    local TR=Target.Character and Target.Character:FindFirstChild("HumanoidRootPart")
                    local Metric=MetricCache[Target]
                    local Now=os.clock()
                    if not Metric or Metric.Root~=TR
                        or Now-(tonumber(Metric.At) or 0)>=0.10*Runtime.GetVisualUpdateScale() then
                        local Distance=(Me and TR) and (TR.Position-Me.Position).Magnitude or math.huge
                        local OnScreen=false
                        if Cam and TR then
                            local _,Visible=Cam:WorldToViewportPoint(TR.Position)
                            OnScreen=Visible==true
                        end
                        Metric={Root=TR,Distance=Distance,OnScreen=OnScreen,At=Now}
                        MetricCache[Target]=Metric
                    end
                    local Distance=Metric.Distance or math.huge
                    local OnScreen=Metric.OnScreen==true
                    -- Visible/near targets stay fluid. Off-screen and far targets are deliberately
                    -- cheaper, while the same renderer objects are pooled/reused by UpdatePlayerESP.
                    local Interval
                    if OnScreen and Distance<300 then Interval=0.065
                    elseif OnScreen then Interval=0.11
                    elseif Distance<450 then Interval=0.20
                    elseif Distance<1000 then Interval=0.38
                    else Interval=0.70 end
                    Schedule[Target]=Interval
                    UpdatePlayerESP(Target)
                else Schedule[Target]=Due end
            end
        end
    end),"Disconnect","ESPHeartbeat","Connections")
end

Runtime.RefreshPlayerESP = SetPlayerESP

do
    Runtime.PlayerESPState = Runtime.PlayerESPState or {Enabled=false,Chams=false,ProfileEnabled=false,ProfileFilter=nil}
    Runtime.ChamsHumanoidDisplayBackup = Runtime.ChamsHumanoidDisplayBackup or setmetatable({}, {__mode="k"})

    Runtime.SetChamsDefaultNameplates = function(Hide)
        local Backup=Runtime.ChamsHumanoidDisplayBackup
        for _,Target in ipairs(Runtime.CachedPlayers()) do
            if Target~=Player then
                local H=Target.Character and Target.Character:FindFirstChildOfClass("Humanoid")
                if H then
                    if Hide then
                        if not Backup[H] then
                            Backup[H]={DisplayDistanceType=H.DisplayDistanceType,NameDisplayDistance=H.NameDisplayDistance,HealthDisplayType=H.HealthDisplayType}
                        end
                        pcall(function()
                            H.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None
                            H.NameDisplayDistance=0
                            H.HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff
                        end)
                    else
                        local Old=Backup[H]
                        if Old then
                            pcall(function()
                                H.DisplayDistanceType=Old.DisplayDistanceType
                                H.NameDisplayDistance=Old.NameDisplayDistance
                                H.HealthDisplayType=Old.HealthDisplayType
                            end)
                            Backup[H]=nil
                        end
                    end
                end
            end
        end
        if not Hide then
            for H,Old in pairs(Backup) do
                if H and H.Parent then
                    pcall(function()
                        H.DisplayDistanceType=Old.DisplayDistanceType
                        H.NameDisplayDistance=Old.NameDisplayDistance
                        H.HealthDisplayType=Old.HealthDisplayType
                    end)
                end
                Backup[H]=nil
            end
        end
    end


    Runtime.ApplyPlayerESP = function(Value)
        local State = Runtime.PlayerESPState
        State.Enabled = Value == true
        BoxESPEnabled = State.Enabled or State.ProfileEnabled==true
        HealthESPEnabled = BoxESPEnabled
        SetPlayerESP()
    end

    Runtime.ApplyProfilePlayerESP = function(Value,Filter,Options)
        local State=Runtime.PlayerESPState
        State.ProfileEnabled=Value==true
        State.ProfileFilter=State.ProfileEnabled and Filter or nil
        State.ProfileOptions=State.ProfileEnabled and Options or nil
        BoxESPEnabled=State.Enabled==true or State.ProfileEnabled==true
        HealthESPEnabled=BoxESPEnabled
        SetPlayerESP()
    end

    Runtime.ApplyPlayerChams = function(Value)
        local State = Runtime.PlayerESPState
        State.Chams = Value == true
        SetChams(State.Chams)
        Runtime.SetChamsDefaultNameplates(State.Chams)
        -- Chams owns the overhead identity/info card without forcing the ESP box on.
        BoxESPEnabled = State.Enabled == true or State.ProfileEnabled==true
        HealthESPEnabled = BoxESPEnabled
        SetPlayerESP()
    end
end

do
    local UIVisuals = {
        Entries = {},
        EntryByKey = {},
        LabelToKey = {},
        Filtered = {},
        Groups = {},
        Edits = {},
        EditCount = 0,
        Connections = {},
        SelectedKey = nil,
        SearchText = "",
        PendingText = "",
        GroupFilter = nil,
        KeepApplied = true,
        IncludeHidden = false,
        InputIsRich = false,
        UseColor = false,
        EditColor = Color3.fromRGB(80, 140, 255),
        ColorHexInput = "",
        MatchGameColor = false,
        Palette = {},
        PaletteDropdown = nil,
        PaletteNone = "(use my own colour)",
        Bold = false, Italic = false, Underline = false, Strike = false,
        SizeOverride = 0,
        AllowEnableRich = true,
        EditMode = "auto",
        TargetIndex = 1,
        Scanning = false,
        LastScanCount = 0,
        LastScanSeconds = 0,
        MaxOptions = 150,
        Placeholder = "Press Scan / Refresh UI",

        Dropdown = nil,
        GameParagraph = nil,
        InfoParagraph = nil
    }
    Runtime.UIVisuals = UIVisuals

    local StatKeywords = {
        "cash", "money", "coin", "coins", "gem", "gems", "level", "lvl",
        "xp", "experience", "win", "wins", "kill", "kills", "score", "rank",
        "point", "points", "credit", "credits", "token", "tokens", "gold",
        "balance", "health", "currency", "stat", "stats", "bank", "wallet",
        "diamond", "diamonds", "star", "stars", "trophy", "trophies", "cost",
        "price", "amount", "total", "count", "value"
    }
    local CurrencySymbols = {"$", "€", "£", "¥", "₽", "R$"}

    local Helper = {}

    function Helper.GetPlayerGui()
        local Success, Gui = pcall(function()
            return Player:FindFirstChildOfClass("PlayerGui")
        end)
        if Success then return Gui end
        return nil
    end

    function Helper.IsTextObject(Object)
        return Object:IsA("TextLabel")
            or Object:IsA("TextButton")
            or Object:IsA("TextBox")
    end

    function Helper.IsRich(Object)
        if not Object then return false end
        local Success, Value = pcall(function() return Object.RichText end)
        return Success and Value == true
    end

    function Helper.IsHubOwned(Object)
        local Current = Object
        local Depth = 0
        while Current and Depth < 40 do
            if HubGuiTracker.Owned[Current] then return true end
            if Current:IsA("LayerCollector") then
                local LowerName = string.lower(Current.Name)
                if string.find(LowerName, "rayfield", 1, true)
                    or string.find(LowerName, "banani", 1, true) then
                    return true
                end
                return false
            end
            Current = Current.Parent
            Depth += 1
        end
        return false
    end

    function Helper.IsShown(Object, Cache, Gui)
        if not Object or Object == Gui then return true end
        local Cached = Cache[Object]
        if Cached ~= nil then return Cached end
        local Result
        if Object:IsA("LayerCollector") then
            Result = Object.Enabled ~= false
        elseif Object:IsA("GuiObject") then
            Result = Object.Visible ~= false
                and Helper.IsShown(Object.Parent, Cache, Gui)
        else
            Result = Helper.IsShown(Object.Parent, Cache, Gui)
        end
        Cache[Object] = Result
        return Result
    end

    function Helper.GetPathParts(Object, Gui)
        local Parts = {}
        local Current = Object
        local Depth = 0
        while Current and Current ~= Gui and Depth < 40 do
            table.insert(Parts, 1, Current.Name)
            Current = Current.Parent
            Depth += 1
        end
        if Current ~= Gui then return nil end
        return Parts
    end

    function Helper.PathString(Parts)
        return "PlayerGui." .. table.concat(Parts, ".")
    end

    function Helper.ResolveParts(Gui, Parts, ClassName)
        local Current = Gui
        for _, Name in ipairs(Parts) do
            local Found
            local Success = pcall(function()
                Found = Current:FindFirstChild(Name)
            end)
            if not Success or not Found then return nil end
            Current = Found
        end
        if ClassName and Current.ClassName ~= ClassName then return nil end
        return Current
    end

    function Helper.Trim(Text, Limit)
        Text = tostring(Text or "")
        Text = (Text:gsub("[\r\n\t]", " "))
        if #Text > Limit then
            Text = string.sub(Text, 1, Limit) .. "..."
        end
        return Text
    end

    function Helper.Tokenize(Source, IsRich)
        Source = tostring(Source or "")
        if not IsRich then
            return {{Kind = "text", Value = Source}}
        end
        local Tokens = {}
        local Index = 1
        while Index <= #Source do
            local TagStart, TagEnd = string.find(Source, "<[^<>]*>", Index)
            if not TagStart then
                table.insert(Tokens, {Kind = "text", Value = string.sub(Source, Index)})
                break
            end
            if TagStart > Index then
                table.insert(Tokens, {
                    Kind = "text",
                    Value = string.sub(Source, Index, TagStart - 1)
                })
            end
            table.insert(Tokens, {
                Kind = "tag",
                Value = string.sub(Source, TagStart, TagEnd)
            })
            Index = TagEnd + 1
        end
        return Tokens
    end

    function Helper.Rebuild(Tokens)
        local Pieces = {}
        for _, Token in ipairs(Tokens) do
            table.insert(Pieces, Token.Value)
        end
        return table.concat(Pieces)
    end

    function Helper.StripTags(Source, IsRich)
        if not IsRich then return tostring(Source or "") end
        local Plain = string.gsub(tostring(Source or ""), "<[^<>]*>", "")
        Plain = string.gsub(Plain, "&lt;", "<")
        Plain = string.gsub(Plain, "&gt;", ">")
        Plain = string.gsub(Plain, "&quot;", '"')
        Plain = string.gsub(Plain, "&apos;", "'")
        Plain = string.gsub(Plain, "&#39;", "'")
        Plain = string.gsub(Plain, "&amp;", "&")
        return Plain
    end

    function Helper.EscapeRich(Value)
        Value = string.gsub(tostring(Value or ""), "&", "&amp;")
        Value = string.gsub(Value, "<", "&lt;")
        Value = string.gsub(Value, ">", "&gt;")
        return Value
    end

    function Helper.EntitySpans(Value, IsRich)
        if not IsRich then return {} end
        local Spans = {}
        local Index = 1
        while true do
            local Start, Finish = string.find(Value, "&#?%w+;", Index)
            if not Start then break end
            table.insert(Spans, {Start = Start, Finish = Finish})
            Index = Finish + 1
        end
        return Spans
    end

    function Helper.NumberRuns(Value, IsRich)
        local Spans = Helper.EntitySpans(Value, IsRich)
        local Runs = {}
        local Index = 1
        while true do
            local Start, Finish = string.find(Value, "%d[%d,%.]*", Index)
            if not Start then break end
            local Blocked = false
            for _, Span in ipairs(Spans) do
                if Start <= Span.Finish and Finish >= Span.Start then
                    Blocked = true
                    break
                end
            end
            if not Blocked then

                local Piece = string.sub(Value, Start, Finish)
                local Clean = string.gsub(Piece, "[,%.]+$", "")
                if Clean ~= "" then
                    table.insert(Runs, {
                        Start = Start,
                        Finish = Start + #Clean - 1
                    })
                end
            end
            Index = Finish + 1
        end
        return Runs
    end

    function Helper.DecodeEntity(Entity)
        local Named = {
            ["&lt;"] = "<", ["&gt;"] = ">", ["&amp;"] = "&",
            ["&quot;"] = '"', ["&apos;"] = "'"
        }
        local Direct = Named[string.lower(Entity)]
        if Direct then return Direct end
        local Number = string.match(Entity, "^&#(%d+);$")
        if Number then
            local Code = tonumber(Number)
            if Code and Code >= 32 and Code < 127 then
                return string.char(Code)
            end
        end
        return "?"
    end
    function Helper.Project(Source, IsRich)
        local Tokens = Helper.Tokenize(Source, IsRich)
        local Characters = {}
        local Map = {}
        for TokenIndex, Token in ipairs(Tokens) do
            if Token.Kind == "text" then
                local Value = Token.Value
                local Index = 1
                while Index <= #Value do
                    local Char = string.sub(Value, Index, Index)
                    local Finish = Index
                    if IsRich and Char == "&" then
                        local Start, EntityEnd = string.find(Value, "^&#?%w+;", Index)
                        if Start then
                            Finish = EntityEnd
                            Char = Helper.DecodeEntity(string.sub(Value, Start, EntityEnd))
                        end
                    end
                    table.insert(Characters, Char)
                    table.insert(Map, {
                        Token = TokenIndex, Start = Index, Finish = Finish
                    })
                    Index = Finish + 1
                end
            end
        end
        return table.concat(Characters), Map, Tokens
    end

    function Helper.Splice(Tokens, Map, PlainStart, PlainFinish, Replacement)
        local First, Last = Map[PlainStart], Map[PlainFinish]
        if not First or not Last then return nil end
        if First.Token == Last.Token then
            local Token = Tokens[First.Token]
            Token.Value = string.sub(Token.Value, 1, First.Start - 1)
                .. Replacement
                .. string.sub(Token.Value, Last.Finish + 1)
        else
            local Head = Tokens[First.Token]
            Head.Value = string.sub(Head.Value, 1, First.Start - 1) .. Replacement
            for Index = First.Token + 1, Last.Token - 1 do
                if Tokens[Index].Kind == "text" then Tokens[Index].Value = "" end
            end
            local Tail = Tokens[Last.Token]
            Tail.Value = string.sub(Tail.Value, Last.Finish + 1)
        end
        return Helper.Rebuild(Tokens)
    end

    function Helper.BracketSpans(Plain)
        local Spans = {}
        local Index = 1
        while true do
            local Start, Finish = string.find(Plain, "%[[^%[%]]*%]", Index)
            if not Start then break end
            if Finish - Start > 1 then

                table.insert(Spans, {Start = Start + 1, Finish = Finish - 1})
            end
            Index = Finish + 1
        end
        return Spans
    end

    function Helper.NameRuns(Plain)
        local Brackets = Helper.BracketSpans(Plain)
        local Runs = {}
        local Index = 1
        while true do
            local Start, Finish = string.find(Plain, "%a[%a%s'&%-]*", Index)
            if not Start then break end
            Index = Finish + 1

            local Previous = Start > 1 and string.sub(Plain, Start - 1, Start - 1) or ""
            if string.find(Previous, "%d") then
                Start += 1
                while Start <= Finish
                    and string.find(string.sub(Plain, Start, Start), "[%s'&%-]") do
                    Start += 1
                end
            end
            if Start <= Finish then

                local Piece = string.sub(Plain, Start, Finish)
                local Clean = string.gsub(Piece, "[%s'&%-]+$", "")
                Finish = Start + #Clean - 1
                local Inside = false
                for _, Span in ipairs(Brackets) do
                    if Start >= Span.Start and Finish <= Span.Finish then
                        Inside = true
                        break
                    end
                end
                if #Clean > 1 and not Inside then
                    table.insert(Runs, {Start = Start, Finish = Finish})
                end
            end
        end
        return Runs
    end

    function Helper.Segments(Source, IsRich)
        local Tokens = Helper.Tokenize(Source, IsRich)
        local Segments = {}
        local ColorStack = {}
        for TokenIndex, Token in ipairs(Tokens) do
            if Token.Kind == "tag" then
                local Lower = string.lower(Token.Value)
                if string.find(Lower, "^</font") then
                    if #ColorStack > 0 then table.remove(ColorStack) end
                elseif string.find(Lower, "^<font") then
                    local Color = string.match(Token.Value, 'color%s*=%s*"([^"]*)"')
                        or string.match(Token.Value, "color%s*=%s*'([^']*)'")
                    table.insert(ColorStack, Color or "inherited")
                end
            elseif string.find(Token.Value, "%S") then
                table.insert(Segments, {
                    TokenIndex = TokenIndex,
                    Text = Token.Value,
                    Color = ColorStack[#ColorStack] or "label default"
                })
            end
        end
        return Segments, Tokens
    end

    function Helper.ColorHex(Color)
        if typeof(Color) ~= "Color3" then return "#FFFFFF" end
        return string.format("#%02X%02X%02X",
            math.floor(Color.R * 255 + 0.5),
            math.floor(Color.G * 255 + 0.5),
            math.floor(Color.B * 255 + 0.5))
    end

    function Helper.ParseHex(Text)
        Text = tostring(Text or ""):gsub("%s", "")
        if Text == "" then return nil end
        local Digits = string.match(Text, "^#?(%x%x%x%x%x%x)$")
        if not Digits then return nil end
        return "#" .. string.upper(Digits)
    end

    function Helper.TokenColors(Tokens)
        local Colors = {}
        local Stack = {}
        for Index, Token in ipairs(Tokens) do
            if Token.Kind == "tag" then
                local Lower = string.lower(Token.Value)
                if string.find(Lower, "^</font") then
                    if #Stack > 0 then table.remove(Stack) end
                elseif string.find(Lower, "^<font") then
                    local Color = string.match(Token.Value, 'color%s*=%s*"([^"]*)"')
                        or string.match(Token.Value, "color%s*=%s*'([^']*)'")
                    table.insert(Stack, Color or false)
                end
            end
            Colors[Index] = Stack[#Stack] or nil
        end
        return Colors
    end

    function Helper.ColorOfSpan(Tokens, Map, PlainStart, Object)
        local Entry = Map[PlainStart]
        if Entry then
            local Tagged = Helper.TokenColors(Tokens)[Entry.Token]
            if Tagged then return Helper.ParseHex(Tagged) or Tagged end
        end
        if Object then
            local Ok, Color = pcall(function() return Object.TextColor3 end)
            if Ok and Color then return Helper.ColorHex(Color) end
        end
        return nil
    end

    function Helper.ColorName(Hex)
        local Named = {
            {"black", 0, 0, 0}, {"white", 255, 255, 255},
            {"grey", 128, 128, 128}, {"silver", 200, 200, 200},
            {"red", 255, 0, 0}, {"dark red", 140, 0, 0},
            {"orange", 255, 140, 0}, {"gold", 255, 200, 0},
            {"yellow", 255, 255, 0}, {"lime", 120, 255, 0},
            {"green", 0, 200, 0}, {"dark green", 0, 110, 0},
            {"teal", 0, 180, 180}, {"cyan", 0, 255, 255},
            {"blue", 0, 90, 255}, {"dark blue", 0, 0, 150},
            {"purple", 150, 0, 220}, {"pink", 255, 105, 180},
            {"magenta", 255, 0, 255}, {"brown", 130, 80, 40}
        }
        local Digits = string.match(tostring(Hex or ""), "^#(%x%x%x%x%x%x)$")
        if not Digits then return "colour" end
        local Red = tonumber(string.sub(Digits, 1, 2), 16) or 0
        local Green = tonumber(string.sub(Digits, 3, 4), 16) or 0
        local Blue = tonumber(string.sub(Digits, 5, 6), 16) or 0
        local Best, BestDistance = "colour", math.huge
        for _, Entry in ipairs(Named) do
            local Distance = (Red - Entry[2]) ^ 2
                + (Green - Entry[3]) ^ 2
                + (Blue - Entry[4]) ^ 2
            if Distance < BestDistance then
                BestDistance = Distance
                Best = Entry[1]
            end
        end
        return Best
    end

    function Helper.CollectColors(Entry, Sink)
        local function Add(Hex, Sample)
            Hex = Helper.ParseHex(Hex)
            if not Hex then return end
            local Bucket = Sink[Hex]
            if not Bucket then
                Bucket = {Hex = Hex, Count = 0, Sample = Sample}
                Sink[Hex] = Bucket
            end
            Bucket.Count += 1
            if (not Bucket.Sample or Bucket.Sample == "") and Sample then
                Bucket.Sample = Sample
            end
        end
        local Sample = Helper.Trim(Entry.PlainText, 18)
        if Entry.IsRich then
            for _, Token in ipairs(Helper.Tokenize(Entry.Text, true)) do
                if Token.Kind == "tag"
                    and string.find(string.lower(Token.Value), "^<font") then
                    local Color = string.match(Token.Value, 'color%s*=%s*"([^"]*)"')
                        or string.match(Token.Value, "color%s*=%s*'([^']*)'")
                    if Color then Add(Color, Sample) end
                end
            end
        end
        if Entry.Object then
            local Ok, Color = pcall(function() return Entry.Object.TextColor3 end)
            if Ok and Color then Add(Helper.ColorHex(Color), Sample) end
        end
    end

    function Helper.WrapStyle(Payload, Style)
        local Attributes = {}
        if Style.ColorHex then
            table.insert(Attributes, 'color="' .. Style.ColorHex .. '"')
        end
        if Style.Size and Style.Size > 0 then
            table.insert(Attributes, 'size="' .. tostring(math.floor(Style.Size)) .. '"')
        end
        if Style.Face and Style.Face ~= "" then
            table.insert(Attributes, 'face="' .. Style.Face .. '"')
        end
        local Inner = Payload
        if Style.Strike then Inner = "<s>" .. Inner .. "</s>" end
        if Style.Underline then Inner = "<u>" .. Inner .. "</u>" end
        if Style.Italic then Inner = "<i>" .. Inner .. "</i>" end
        if Style.Bold then Inner = "<b>" .. Inner .. "</b>" end
        if #Attributes > 0 then
            Inner = "<font " .. table.concat(Attributes, " ") .. ">"
                .. Inner .. "</font>"
        end
        return Inner
    end

    function Helper.WrappingFontTag(Tokens, Map, PlainStart, PlainFinish)
        local First, Last = Map[PlainStart], Map[PlainFinish]
        if not First or not Last then return nil end
        if First.Token ~= Last.Token then return nil end
        local Index = First.Token
        local Token = Tokens[Index]
        if First.Start ~= 1 or Last.Finish ~= #Token.Value then return nil end
        local Open, Close = Tokens[Index - 1], Tokens[Index + 1]
        if not Open or not Close then return nil end
        if Open.Kind ~= "tag" or Close.Kind ~= "tag" then return nil end
        if not string.find(string.lower(Open.Value), "^<font") then return nil end
        if not string.find(string.lower(Close.Value), "^</font") then return nil end
        return Index - 1, Index
    end

    function Helper.SetFontAttribute(Tag, Name, Value)
        local Pattern = Name .. '%s*=%s*"[^"]*"'
        if string.find(Tag, Pattern) then
            return (string.gsub(Tag, Pattern, Name .. '="' .. Value .. '"', 1))
        end
        Pattern = Name .. "%s*=%s*'[^']*'"
        if string.find(Tag, Pattern) then
            return (string.gsub(Tag, Pattern, Name .. '="' .. Value .. '"', 1))
        end
        return (string.gsub(Tag, "%s*>$", " " .. Name .. '="' .. Value .. '">', 1))
    end

    function Helper.ResolveAuto(Plain, Value, WantsColor)
        local Text = tostring(Value or "")
        local Numbers = #Helper.NumberRuns(Plain, false)
        local Brackets = #Helper.BracketSpans(Plain)
        local Names = #Helper.NameRuns(Plain)
        local Typed = Text ~= ""
        local TypedDigits = string.find(Text, "%d") ~= nil

        local ShortTag = #Text <= 3 and string.find(Text, "%s") == nil
        if Typed and TypedDigits and Numbers > 0 then return "number" end
        if Typed and not TypedDigits then
            if Brackets > 0 and ShortTag then return "bracket" end
            if Names > 0 then return "name" end
            if Brackets > 0 then return "bracket" end
        end
        if WantsColor and not Typed then
            if Brackets > 0 then return "bracket" end
            if Numbers > 0 then return "number" end
            if Names > 0 then return "name" end
        end
        if Numbers > 0 then return "number" end
        if Brackets > 0 then return "bracket" end
        if Names > 0 then return "name" end
        return "whole"
    end

    function Helper.PartKey(Mode, Occurrence)
        return tostring(Mode) .. "#" .. tostring(Occurrence)
    end

    function Helper.PartIsStyled(Part)
        return Part.UseColor == true or Part.Bold == true or Part.Italic == true
            or Part.Underline == true or Part.Strike == true
            or (tonumber(Part.Size) or 0) > 0
    end

    function Helper.SpanOn(Plain, Mode, Index, Source, IsRich, Map)
        if Mode == "bracket" then
            return Helper.BracketSpans(Plain)[Index]
        elseif Mode == "name" then
            return Helper.NameRuns(Plain)[Index]
        elseif Mode == "segment" then
            local Target = Helper.Segments(Source, IsRich)[Index]
            if not Target then return nil end
            local First, Last
            for Position, Entry in ipairs(Map) do
                if Entry.Token == Target.TokenIndex then
                    First = First or Position
                    Last = Position
                end
            end
            if not First then return nil end
            return {Start = First, Finish = Last}
        end
        return Helper.NumberRuns(Plain, false)[Index]
    end

    function Helper.Compose(Record, Source, IsRich, Object)
        local Changes = Record.Changes or {}
        if #Changes == 0 then return Source, false, "noparts" end

        local WantsStyle = false
        for _, Part in ipairs(Changes) do
            if Helper.PartIsStyled(Part) then WantsStyle = true break end
        end
        local Convert = WantsStyle and (not IsRich or Record.EnabledRich == true)
        if Convert and not Record.AllowEnableRich then
            return Source, false, "needsrich"
        end
        local ProjectRich = IsRich and not Convert

        local Plain, Map, Tokens = Helper.Project(Source, ProjectRich)

        local Planned = {}
        local WholePart = nil
        local Missed = 0
        for _, Part in ipairs(Changes) do
            local Styled = Helper.PartIsStyled(Part)
            local Mode = Part.Mode
            if Mode == "auto" then
                Mode = Helper.ResolveAuto(Plain, Part.Value, Styled)
            end
            Part.ResolvedMode = Mode
            if Mode == "whole" then
                WholePart = Part
            else
                local Span = Helper.SpanOn(Plain, Mode, Part.Occurrence, Source, ProjectRich, Map)
                if Span then
                    table.insert(Planned, {Part = Part, Span = Span, Styled = Styled})
                else
                    Missed += 1
                end
            end
        end

        local function Payload(Part, Span, Styled)
            local Value = Part.Value
            local Verbatim = Part.InputIsRich
            if Value == "" then

                Value = string.sub(Plain, Span.Start, Span.Finish)
                Verbatim = false
            end
            if (ProjectRich or Convert) and not Verbatim then
                Value = Helper.EscapeRich(Value)
            end
            if not Styled then return Value, false end
            local Color = Part.ColorHex
            if Part.MatchGameColor then
                Color = Helper.ColorOfSpan(Tokens, Map, Span.Start, Object) or Color
            end
            if not Part.UseColor then Color = nil end
            return Helper.WrapStyle(Value, {
                ColorHex = Color,
                Size = tonumber(Part.Size) or 0,
                Bold = Part.Bold, Italic = Part.Italic,
                Underline = Part.Underline, Strike = Part.Strike
            }), true, Color
        end

        if WholePart then
            local Styled = Helper.PartIsStyled(WholePart)
            local Value = WholePart.Value
            if (ProjectRich or Convert) and not WholePart.InputIsRich then
                Value = Helper.EscapeRich(Value)
            end
            if Styled then
                local Color = WholePart.UseColor and WholePart.ColorHex or nil
                Value = Helper.WrapStyle(Value, {
                    ColorHex = Color,
                    Size = tonumber(WholePart.Size) or 0,
                    Bold = WholePart.Bold, Italic = WholePart.Italic,
                    Underline = WholePart.Underline, Strike = WholePart.Strike
                })
            end
            return Value, true, Convert and "convert" or nil
        end

        if #Planned == 0 then return Source, false, "nomatch" end

        table.sort(Planned, function(A, B) return A.Span.Start < B.Span.Start end)

        local Accepted = {}
        local Reach = 0
        local Overlaps = 0
        for _, Item in ipairs(Planned) do
            if Item.Span.Start > Reach then
                table.insert(Accepted, Item)
                Reach = Item.Span.Finish
            else
                Overlaps += 1
            end
        end
        Record.LastSkipped = Missed + Overlaps

        if Convert then

            local Pieces = {}
            local Cursor = 1
            for _, Item in ipairs(Accepted) do
                table.insert(Pieces,
                    Helper.EscapeRich(string.sub(Source, Cursor, Item.Span.Start - 1)))
                table.insert(Pieces, (Payload(Item.Part, Item.Span, Item.Styled)))
                Cursor = Item.Span.Finish + 1
            end
            table.insert(Pieces, Helper.EscapeRich(string.sub(Source, Cursor)))
            return table.concat(Pieces), true, "convert"
        end

        local Result = Source
        for Index = #Accepted, 1, -1 do
            local Item = Accepted[Index]
            local Text, Styled, Color = Payload(Item.Part, Item.Span, Item.Styled)
            local Written = false
            if Styled and Color then

                local TagIndex, TextIndex =
                    Helper.WrappingFontTag(Tokens, Map, Item.Span.Start, Item.Span.Finish)
                if TagIndex then
                    local Plainer = select(1, Payload(Item.Part, Item.Span, false))
                    local OnlyColour = not (Item.Part.Bold or Item.Part.Italic
                        or Item.Part.Underline or Item.Part.Strike
                        or (tonumber(Item.Part.Size) or 0) > 0)
                    if OnlyColour then
                        Tokens[TagIndex].Value =
                            Helper.SetFontAttribute(Tokens[TagIndex].Value, "color", Color)
                        Tokens[TextIndex].Value = Plainer
                        Result = Helper.Rebuild(Tokens)
                        Written = true
                    end
                end
            end
            if not Written then
                local Spliced = Helper.Splice(Tokens, Map, Item.Span.Start, Item.Span.Finish, Text)
                if Spliced then Result = Spliced end
            end
        end
        return Result, true, nil
    end

    function Helper.Describe(Object)
        local Lines = {}
        local function Add(LabelText, Getter)
            local Ok, Value = pcall(Getter)
            if Ok and Value ~= nil then
                table.insert(Lines, LabelText .. ": " .. tostring(Value))
            end
        end
        Add("RichText", function() return Object.RichText end)
        Add("TextColor3", function()
            local C = Object.TextColor3
            return string.format("#%02X%02X%02X",
                math.floor(C.R * 255 + 0.5),
                math.floor(C.G * 255 + 0.5),
                math.floor(C.B * 255 + 0.5))
        end)
        Add("Font", function()
            local Ok, Face = pcall(function() return Object.FontFace end)
            if Ok and Face then return tostring(Face) end
            return tostring(Object.Font)
        end)
        Add("TextSize", function() return Object.TextSize end)
        Add("Scaled", function() return Object.TextScaled end)
        Add("TextTransparency", function() return Object.TextTransparency end)
        Add("StrokeTransparency", function() return Object.TextStrokeTransparency end)
        local Extras = {}
        local Ok = pcall(function()
            if Object:FindFirstChildOfClass("UIGradient") then
                table.insert(Extras, "UIGradient")
            end
            if Object:FindFirstChildOfClass("UIStroke") then
                table.insert(Extras, "UIStroke")
            end
        end)
        if Ok and #Extras > 0 then
            table.insert(Lines, "Children: " .. table.concat(Extras, ", "))
        end
        return table.concat(Lines, " • ")
    end

    function Helper.Score(Name, Text)
        local Score = 0
        local LowerName = string.lower(Name)
        local LowerText = string.lower(Text)
        for _, Keyword in ipairs(StatKeywords) do
            if string.find(LowerName, Keyword, 1, true) then
                Score += 60
                break
            end
        end
        for _, Keyword in ipairs(StatKeywords) do
            if string.find(LowerText, Keyword, 1, true) then
                Score += 25
                break
            end
        end
        if string.find(Text, "%d") then Score += 15 end

        for _, Symbol in ipairs(CurrencySymbols) do
            if string.find(Text, Symbol, 1, true) then
                Score += 20
                break
            end
        end

        if string.find(Text, "^%s*[%d%.,]+%s*%a*%s*$") then Score += 20 end
        if string.find(LowerText, "%d%s*[kmb]$") then Score += 10 end

        if string.find(Text, "%d%s*/%s*%d") then Score += 25 end
        return Score
    end

    function Helper.Rect(Object)
        local Ok, Position, Size = pcall(function()
            return Object.AbsolutePosition, Object.AbsoluteSize
        end)
        if not Ok or not Position or not Size then return nil end
        if Size.X <= 0 and Size.Y <= 0 then return nil end
        return {
            X = Position.X, Y = Position.Y,
            W = Size.X, H = Size.Y,
            CenterY = Position.Y + Size.Y / 2
        }
    end

    function Helper.BuildGroups(Entries)
        local ByParent = {}
        for _, Entry in ipairs(Entries) do
            local Parent = Entry.Object and Entry.Object.Parent
            if Parent then
                Entry.Rect = Helper.Rect(Entry.Object)
                if Entry.Rect then
                    ByParent[Parent] = ByParent[Parent] or {}
                    table.insert(ByParent[Parent], Entry)
                end
            end
        end

        local Groups = {}
        local NextId = 0
        for _, Siblings in pairs(ByParent) do
            if #Siblings > 1 then
                table.sort(Siblings, function(A, B) return A.Rect.X < B.Rect.X end)
                local Current = {Siblings[1]}
                for Index = 2, #Siblings do
                    local Previous = Siblings[Index - 1]
                    local Entry = Siblings[Index]
                    local Tallest = math.max(Previous.Rect.H, Entry.Rect.H, 1)
                    local SameRow =
                        math.abs(Previous.Rect.CenterY - Entry.Rect.CenterY) <= Tallest * 0.6
                    local Gap = Entry.Rect.X - (Previous.Rect.X + Previous.Rect.W)
                    local Adjacent = Gap <= math.max(24, Tallest * 0.75)
                    if SameRow and Adjacent then
                        table.insert(Current, Entry)
                    else
                        if #Current > 1 then table.insert(Groups, Current) end
                        Current = {Entry}
                    end
                end
                if #Current > 1 then table.insert(Groups, Current) end
            end
        end

        local Result = {}
        for _, Members in ipairs(Groups) do
            NextId += 1
            local Id = NextId
            local Pieces = {}
            for Position, Entry in ipairs(Members) do
                Entry.GroupId = Id
                Entry.GroupIndex = Position
                Entry.GroupSize = #Members
                table.insert(Pieces, Entry.PlainText)
            end
            Result[Id] = {Members = Members, Preview = table.concat(Pieces, " ")}
        end
        return Result
    end

    function Helper.Write(Record, Value)
        local Object = Record.Object
        if not Object then return false end
        Record.Applying = true
        local Success = pcall(function()
            Object.Text = Value
        end)
        Record.Applying = false
        if Success then Record.LastApplied = Value end
        return Success
    end

    function Helper.Reapply(Record, Source)
        local Object = Record.Object
        if not Object then return false end
        local IsRich = Helper.IsRich(Object)
        local Result, Ok, Note = Helper.Compose(Record, Source, IsRich, Object)
        if not Ok then

            Record.LastNote = Note
            return false
        end
        Record.LastNote = nil
        if Note == "convert" and not IsRich then

            local Flipped = pcall(function() Object.RichText = true end)
            if Flipped then
                Record.EnabledRich = true
                Record.RichTextWasEnabled = false
            else
                return false
            end
        end
        return Helper.Write(Record, Result)
    end

    function Helper.Detach(Record)
        for _, Field in ipairs({"TextConnection", "AncestryConnection"}) do
            local Connection = Record[Field]
            if Connection then
                pcall(function() Connection:Disconnect() end)
                Record[Field] = nil
            end
        end
    end

    function Helper.Attach(Record, Object)
        Helper.Detach(Record)
        Record.Object = Object
        if not Object then return end

        local ReadOk, CurrentText = pcall(function() return Object.Text end)
        if ReadOk and CurrentText ~= Record.LastApplied then
            Record.RealText = CurrentText
        end

        local TextOk, TextConnection = pcall(function()
            return Object:GetPropertyChangedSignal("Text"):Connect(function()
                if Record.Applying or Unloaded then return end
                local Ok, Value = pcall(function() return Object.Text end)
                if not Ok then return end
                if Value == Record.LastApplied then return end

                Record.RealText = Value
                if UIVisuals.KeepApplied and Record.Active then
                    Helper.Reapply(Record, Value)
                end
            end)
        end)
        if TextOk then Record.TextConnection = TextConnection end

        local AncestryOk, AncestryConnection = pcall(function()
            return Object.AncestryChanged:Connect(function(_, NewParent)
                if not NewParent and Record.Object == Object then

                    Record.Object = nil
                end
            end)
        end)
        if AncestryOk then Record.AncestryConnection = AncestryConnection end

        if Record.Active then
            Helper.Reapply(Record, Record.RealText)
        end
    end

    function Helper.Relocate(Record)
        local Gui = Helper.GetPlayerGui()
        if not Gui then return nil end

        local Exact = Helper.ResolveParts(Gui, Record.Parts, Record.ClassName)
        if Exact and Helper.IsTextObject(Exact) and not Helper.IsHubOwned(Exact) then
            return Exact
        end

        local Match, MatchCount = nil, 0
        local Success = pcall(function()
            for _, Object in ipairs(Gui:GetDescendants()) do
                if Object.Name == Record.Name
                    and Object.ClassName == Record.ClassName
                    and Helper.IsTextObject(Object)
                    and not Helper.IsHubOwned(Object) then
                    local Parent = Object.Parent
                    if Parent and Parent.Name == Record.ParentName then
                        MatchCount += 1
                        Match = Object
                        if MatchCount > 1 then break end
                    end
                end
            end
        end)
        if Success and MatchCount == 1 then return Match end
        return nil
    end

    function Helper.Remove(Record, Restore)
        if Restore then
            local Object = Record.Object
            if Object then
                Record.Applying = true

                if Record.EnabledRich then
                    pcall(function()
                        Object.RichText = Record.RichTextWasEnabled == true
                    end)
                    Record.EnabledRich = false
                end

                pcall(function() Object.Text = Record.RealText end)
                Record.Applying = false
            end
        end
        Helper.Detach(Record)
        Record.Active = false
        if UIVisuals.Edits[Record.Key] == Record then
            UIVisuals.Edits[Record.Key] = nil
            UIVisuals.EditCount = math.max(UIVisuals.EditCount - 1, 0)
        end
        if UIVisuals.EditCount == 0 and Helper.ReleaseConnectionsIfIdle then
            Helper.ReleaseConnectionsIfIdle()
        end
    end

    function Helper.TryReattach(Object)
        if Unloaded or UIVisuals.EditCount == 0 then return end
        if not Object or not Object.Parent then return end
        local Gui = Helper.GetPlayerGui()
        if not Gui then return end
        if Helper.IsHubOwned(Object) then return end
        local Parts = Helper.GetPathParts(Object, Gui)
        if not Parts then return end
        local Key = Helper.PathString(Parts) .. "|" .. Object.ClassName
        local Record = UIVisuals.Edits[Key]
        if Record and Record.Active and Record.Object ~= Object then
            Helper.Attach(Record, Object)
        end
    end

    function Helper.EnsureConnections()
        local Gui = Helper.GetPlayerGui()
        if not Gui then return false end

        if not UIVisuals.Connections.DescendantAdded then
            UIVisuals.Connections.DescendantAdded =
                Gui.DescendantAdded:Connect(function(Object)
                    if Unloaded or UIVisuals.EditCount == 0 then return end
                    local Ok, IsText = pcall(Helper.IsTextObject, Object)
                    if not Ok or not IsText then return end

                    task.defer(Helper.TryReattach, Object)
                end)
        end

        if not UIVisuals.Connections.Maintenance then
            local Accumulator = 0
            UIVisuals.Connections.Maintenance =
                Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
                    if Unloaded or UIVisuals.EditCount == 0 then
                        Accumulator = 0
                        return
                    end
                    Accumulator += Delta
                    if Accumulator < 0.5 then return end
                    Accumulator = 0
                    for _, Record in pairs(UIVisuals.Edits) do
                        if Record.Active then
                            local Object = Record.Object
                            local Alive = false
                            if Object then
                                local Ok, Parent = pcall(function()
                                    return Object.Parent
                                end)
                                Alive = Ok and Parent ~= nil
                            end
                            if not Alive then
                                Record.Object = nil
                                local Replacement = Helper.Relocate(Record)
                                if Replacement then
                                    Helper.Attach(Record, Replacement)
                                end
                            elseif UIVisuals.KeepApplied then
                                local Ok, Value = pcall(function()
                                    return Object.Text
                                end)
                                if Ok and Value ~= Record.LastApplied then
                                    Record.RealText = Value
                                    Helper.Reapply(Record, Value)
                                end
                            end
                        end
                    end
                end),"Disconnect","UIVisualsMaintenance","UIVisualsConnections")
        end
        return true
    end

    function Helper.ReleaseConnectionsIfIdle()
        if UIVisuals.EditCount > 0 then return false end
        for _,Name in ipairs({"DescendantAdded","Maintenance"}) do
            local Connection=UIVisuals.Connections[Name]
            if Connection then pcall(function() Connection:Disconnect() end) end
            UIVisuals.Connections[Name]=nil
        end
        return true
    end

    function UIVisuals.UpdateGameInfo()
        if not UIVisuals.GameParagraph then return end
        local GroupCount = 0
        for _ in pairs(UIVisuals.Groups) do GroupCount += 1 end
        pcall(function()
            UIVisuals.GameParagraph:Set({
                Title = "🎮 Game Information",
                Content =
                    "Game: " .. tostring(PlaceInfo.Name)
                    .. "\nPlaceId: " .. tostring(game.PlaceId)
                    .. "\nDetected UI Text Elements: " .. tostring(UIVisuals.LastScanCount)
                    .. "\nMulti-Label Stat Groups: " .. tostring(GroupCount)
                    .. "\nColours Used In This Game: " .. tostring(#UIVisuals.Palette)
                    .. "\nShown In Dropdown: " .. tostring(#UIVisuals.Filtered)
                    .. (UIVisuals.GroupFilter and " (group isolated)" or "")
                    .. "\nActive UI Edits: " .. tostring(UIVisuals.EditCount)
                    .. "\nLast Scan: "
                    .. (UIVisuals.LastScanSeconds > 0
                        and (string.format("%.2f", UIVisuals.LastScanSeconds) .. "s")
                        or "never")
            })
        end)
    end

    function UIVisuals.UpdateSelectionInfo()
        if not UIVisuals.InfoParagraph then return end
        local Entry = UIVisuals.SelectedKey
            and UIVisuals.EntryByKey[UIVisuals.SelectedKey]
        if not Entry then
            pcall(function()
                UIVisuals.InfoParagraph:Set({
                    Title = "🎯 Selected UI",
                    Content = "Nothing selected. Scan, then pick something from Select UI Text."
                })
            end)
            return
        end
        local Record = UIVisuals.Edits[Entry.Key]
        local Object = (Record and Record.Object) or Entry.Object
        local LiveRaw = "(object missing)"
        local IsRich = false
        if Object then
            local Ok, Value = pcall(function() return Object.Text end)
            if Ok then LiveRaw = Value end
            IsRich = Helper.IsRich(Object)
        end
        local RealRaw = Record and Record.RealText or Entry.Text

        local Breakdown = {}
        local Segments = Helper.Segments(RealRaw, IsRich)
        for Index, Segment in ipairs(Segments) do
            table.insert(Breakdown, "  [" .. Index .. "] "
                .. Helper.Trim(Segment.Text, 24)
                .. "  (" .. Segment.Color .. ")")
        end

        local PlainProjection = Helper.Project(RealRaw, IsRich)
        local NumberList = {}
        for Index, Run in ipairs(Helper.NumberRuns(PlainProjection, false)) do
            table.insert(NumberList, "#" .. Index .. "="
                .. string.sub(PlainProjection, Run.Start, Run.Finish))
        end
        local BracketList = {}
        for Index, Span in ipairs(Helper.BracketSpans(PlainProjection)) do
            table.insert(BracketList, "#" .. Index .. "=["
                .. string.sub(PlainProjection, Span.Start, Span.Finish) .. "]")
        end
        local NameList = {}
        for Index, Span in ipairs(Helper.NameRuns(PlainProjection)) do
            table.insert(NameList, "#" .. Index .. "="
                .. string.sub(PlainProjection, Span.Start, Span.Finish))
        end

        local Preview = "(type a value first)"
        if UIVisuals.PendingText ~= "" or UIVisuals.UseColor then

            local Pending = UIVisuals.BuildPart()
            local Combined = {}
            local PendingKey = Helper.PartKey(Pending.Mode, Pending.Occurrence)
            if Record and Record.Changes then
                for _, Existing in ipairs(Record.Changes) do
                    if Helper.PartKey(Existing.Mode, Existing.Occurrence) ~= PendingKey then
                        table.insert(Combined, Existing)
                    end
                end
            end
            table.insert(Combined, Pending)
            local Draft = {
                Changes = Combined,
                AllowEnableRich = UIVisuals.AllowEnableRich
            }
            local Result, Ok, Note = Helper.Compose(Draft, RealRaw, IsRich, Object)
            if Ok then
                Preview = Helper.Trim(Result, 110)
            elseif Note == "needsrich" then
                Preview = "plain label — enable \"Allow Enabling RichText\" to colour it"
            else
                Preview = "no match at index " .. tostring(UIVisuals.TargetIndex)
            end
        end

        local ChangeLines = {}
        if Record and Record.Changes then
            for Index, Change in ipairs(Record.Changes) do
                local Label = tostring(Change.ResolvedMode or Change.Mode)
                    .. " #" .. tostring(Change.Occurrence)
                    .. " → " .. (Change.Value ~= "" and Helper.Trim(Change.Value, 20)
                        or "(restyled only)")
                local Extras = {}
                if Change.UseColor then
                    table.insert(Extras, Change.MatchGameColor and "game colour"
                        or tostring(Change.ColorHex))
                end
                if Change.Bold then table.insert(Extras, "bold") end
                if Change.Italic then table.insert(Extras, "italic") end
                if Change.Underline then table.insert(Extras, "underline") end
                if Change.Strike then table.insert(Extras, "strike") end
                if (tonumber(Change.Size) or 0) > 0 then
                    table.insert(Extras, "size " .. tostring(Change.Size))
                end
                if #Extras > 0 then
                    Label = Label .. "  [" .. table.concat(Extras, ", ") .. "]"
                end
                table.insert(ChangeLines, "  " .. Index .. ". " .. Label)
            end
        end

        local GameColour = "unknown"
        do
            local Projection, ColorMap, ColorTokens = Helper.Project(RealRaw, IsRich)
            local Mode = UIVisuals.EditMode
            if Mode == "auto" then
                Mode = Helper.ResolveAuto(Projection, UIVisuals.PendingText, UIVisuals.UseColor)
            end
            local Span = Helper.SpanOn(Projection, Mode, UIVisuals.TargetIndex,
                RealRaw, IsRich, ColorMap)
            if Span then
                GameColour = Helper.ColorOfSpan(ColorTokens, ColorMap, Span.Start, Object)
                    or "label default"
            else
                GameColour = "no target at #" .. tostring(UIVisuals.TargetIndex)
            end
        end

        local GroupLine = "single label"
        if Entry.GroupId and UIVisuals.Groups[Entry.GroupId] then
            GroupLine = "part " .. tostring(Entry.GroupIndex) .. " of "
                .. tostring(Entry.GroupSize) .. "  →  ".. Helper.Trim(UIVisuals.Groups[Entry.GroupId].Preview, 50)
        end

        pcall(function()
            UIVisuals.InfoParagraph:Set({
                Title = "🎯 " .. Entry.Name,
                Content =
                    "Object: " .. Entry.Name .. "   Class: " .. Entry.ClassName
                    .. "\nUI Path: " .. Helper.Trim(Entry.Path, 130)
                    .. "\n\nOn Screen Now: " .. Helper.Trim(Helper.StripTags(LiveRaw, IsRich), 70)
                    .. "\nRaw Text: " .. Helper.Trim(LiveRaw, 90)
                    .. "\nOriginal / Real Raw: " .. Helper.Trim(RealRaw, 90)
                    .. "\n\nFormatting: " .. Helper.Describe(Object or Entry.Object)
                    .. "\nRichText Segments:\n"
                    .. (#Breakdown > 0 and table.concat(Breakdown, "\n") or "  (none)")
                    .. "\nNumbers: "
                    .. (#NumberList > 0 and table.concat(NumberList, "  ") or "(none)")
                    .. "\nBrackets: "
                    .. (#BracketList > 0 and table.concat(BracketList, "  ") or "(none)")
                    .. "\nNames: "
                    .. (#NameList > 0 and table.concat(NameList, "  ") or "(none)")
                    .. "\nStat Group: " .. GroupLine
                    .. "\n\nMode: " .. UIVisuals.EditMode
                    .. "  Target #: " .. tostring(UIVisuals.TargetIndex)
                    .. "\nChanges On This Label: "
                    .. (#ChangeLines > 0
                        and ("\n" .. table.concat(ChangeLines, "\n"))
                        or "none yet")
                    .. "\nGame Colour Here: " .. tostring(GameColour)
                    .. "\nColour: " .. (UIVisuals.UseColor
                        and ((UIVisuals.MatchGameColor and "match game"
                                or UIVisuals.CurrentColorHex())
                            .. (IsRich and "" or (UIVisuals.AllowEnableRich
                                and " (will enable RichText)"
                                or " (blocked: label is plain)")))
                        or "off — existing colours kept")
                    .. "\nPreview: " .. Preview
                    .. "\nStatus: "
                    .. (Record and Record.Active
                        and ("edited (" .. Record.Mode .. " → "
                            .. Helper.Trim(Record.Value, 30) .. ")")
                        or "not edited")
            })
        end)
    end

    function UIVisuals.RefreshDropdown()
        local Options = {}
        UIVisuals.LabelToKey = {}
        local Shown = 0
        for _, Entry in ipairs(UIVisuals.Filtered) do
            if Shown >= UIVisuals.MaxOptions then break end
            table.insert(Options, Entry.Label)
            UIVisuals.LabelToKey[Entry.Label] = Entry.Key
            Shown += 1
        end
        if #Options == 0 then
            Options = {UIVisuals.Placeholder}
        end
        if UIVisuals.Dropdown then
            pcall(function()
                UIVisuals.Dropdown:Refresh(Options)
            end)

            local Entry = UIVisuals.SelectedKey
                and UIVisuals.EntryByKey[UIVisuals.SelectedKey]
            if Entry and UIVisuals.LabelToKey[Entry.Label] then
                pcall(function()
                    UIVisuals.Dropdown:Set({Entry.Label})
                end)
            end
        end
        UIVisuals.UpdateGameInfo()
    end

    function UIVisuals.RefreshPalette()
        local Options = {UIVisuals.PaletteNone}
        UIVisuals.PaletteLabelToHex = {}
        for _, Entry in ipairs(UIVisuals.Palette) do
            local Label = Helper.ColorName(Entry.Hex) .. "  " .. Entry.Hex
                .. "  (" .. tostring(Entry.Count) .. ")"
            if Entry.Sample and Entry.Sample ~= "" then
                Label = Label .. "  " .. Entry.Sample
            end
            if not UIVisuals.PaletteLabelToHex[Label] then
                table.insert(Options, Label)
                UIVisuals.PaletteLabelToHex[Label] = Entry.Hex
            end
        end
        if UIVisuals.PaletteDropdown then
            pcall(function() UIVisuals.PaletteDropdown:Refresh(Options) end)
        end
    end

    function UIVisuals.SelectPaletteColor(Label)
        Label = tostring(Label or "")
        if Label == "" or Label == UIVisuals.PaletteNone then
            UIVisuals.ColorHexInput = ""
            UIVisuals.UpdateSelectionInfo()
            Notify("UI Visuals", "Back to your own colour.")
            return
        end
        local Hex = UIVisuals.PaletteLabelToHex and UIVisuals.PaletteLabelToHex[Label]
        if not Hex then return end
        UIVisuals.ColorHexInput = Hex
        UIVisuals.UseColor = true
        UIVisuals.MatchGameColor = false
        UIVisuals.UpdateSelectionInfo()
        Notify("UI Visuals", "Using " .. Helper.ColorName(Hex) .. " " .. Hex .. ".")
    end

    function UIVisuals.ApplyFilter()
        local Query = string.lower(UIVisuals.SearchText or "")
        local Result = {}
        for _, Entry in ipairs(UIVisuals.Entries) do
            local Keep = true
            if UIVisuals.GroupFilter and Entry.GroupId ~= UIVisuals.GroupFilter then
                Keep = false
            end
            if Keep and Query ~= ""
                and not string.find(Entry.SearchBlob, Query, 1, true) then
                Keep = false
            end
            if Keep then table.insert(Result, Entry) end
        end
        UIVisuals.Filtered = Result
        UIVisuals.RefreshDropdown()
    end

    function UIVisuals.SetSearch(Text)
        UIVisuals.SearchText = tostring(Text or "")

        if UIVisuals.SearchText ~= "" then UIVisuals.GroupFilter = nil end
        UIVisuals.ApplyFilter()
    end

    function UIVisuals.ToggleGroupIsolation()
        if UIVisuals.GroupFilter then
            UIVisuals.GroupFilter = nil
            UIVisuals.ApplyFilter()
            Notify("UI Visuals", "Showing all detected UI again.")
            return
        end
        local Entry = UIVisuals.SelectedKey
            and UIVisuals.EntryByKey[UIVisuals.SelectedKey]
        if not Entry or not Entry.GroupId then
            Notify("UI Visuals", "The selected label is not part of a multi-label stat.")
            return
        end
        UIVisuals.GroupFilter = Entry.GroupId
        UIVisuals.SearchText = ""
        UIVisuals.ApplyFilter()
        Notify("UI Visuals",
            "Isolated " .. tostring(Entry.GroupSize) .. " labels: "
            .. Helper.Trim(UIVisuals.Groups[Entry.GroupId].Preview, 40))
    end

    function UIVisuals.Scan()
        if UIVisuals.Scanning then
            Notify("UI Visuals", "A scan is already running.")
            return
        end
        local Gui = Helper.GetPlayerGui()
        if not Gui then
            Notify("UI Visuals", "PlayerGui is not available yet.")
            LogWarning("UI Visuals scan failed: no PlayerGui", "UI Visuals")
            return
        end
        UIVisuals.Scanning = true

        local StartClock = os.clock()
        local Entries = {}
        local EntryByKey = {}
        local VisibilityCache = {}

        local Success, ErrorMessage = pcall(function()
            local Descendants = Gui:GetDescendants()
            for Index, Object in ipairs(Descendants) do
                if Unloaded then break end
                if Helper.IsTextObject(Object) and not Helper.IsHubOwned(Object) then
                    local Raw = Object.Text
                    local IsRich = Helper.IsRich(Object)
                    local Plain = Helper.StripTags(Raw, IsRich)
                    local Shown = UIVisuals.IncludeHidden
                        or (Plain ~= "" and Helper.IsShown(Object, VisibilityCache, Gui))
                    if Shown then
                        local Parts = Helper.GetPathParts(Object, Gui)
                        if Parts then
                            local Path = Helper.PathString(Parts)
                            local Key = Path .. "|" .. Object.ClassName

                            if EntryByKey[Key] then
                                local Suffix = 2
                                while EntryByKey[Key .. "#" .. Suffix] do
                                    Suffix += 1
                                end
                                Key = Key .. "#" .. Suffix
                            end
                            local ParentName = Object.Parent and Object.Parent.Name or ""
                            local Entry = {
                                Object = Object,
                                Key = Key,
                                Name = Object.Name,
                                ClassName = Object.ClassName,
                                Text = Raw,
                                PlainText = Plain,
                                IsRich = IsRich,
                                Path = Path,
                                Parts = Parts,
                                ParentName = ParentName,
                                Score = Helper.Score(Object.Name, Plain)
                            }

                            Entry.SearchBlob = string.lower(
                                Object.Name .. " " .. Plain .. " " .. Raw .. " " .. Path
                            )
                            table.insert(Entries, Entry)
                            EntryByKey[Key] = Entry
                        end
                    end
                end

                if Index % 400 == 0 then task.wait() end
            end
        end)

        if not Success then
            UIVisuals.Scanning = false
            LogError("UI Visuals scan failed: " .. tostring(ErrorMessage), "UI Visuals")
            Notify("UI Visuals", "Scan failed. Check the executor output.")
            return
        end

        local ColorSink = {}
        pcall(function()
            for _, Entry in ipairs(Entries) do
                Helper.CollectColors(Entry, ColorSink)
            end
        end)
        local Palette = {}
        for _, Bucket in pairs(ColorSink) do table.insert(Palette, Bucket) end
        table.sort(Palette, function(A, B)
            if A.Count ~= B.Count then return A.Count > B.Count end
            return A.Hex < B.Hex
        end)
        while #Palette > 40 do table.remove(Palette) end
        UIVisuals.Palette = Palette

        local Groups = {}
        pcall(function() Groups = Helper.BuildGroups(Entries) end)
        UIVisuals.Groups = Groups

        table.sort(Entries, function(A, B)
            if A.Score ~= B.Score then return A.Score > B.Score end
            if A.Name ~= B.Name then return string.lower(A.Name) < string.lower(B.Name) end
            return A.Path < B.Path
        end)

        local UsedLabels = {}
        for _, Entry in ipairs(Entries) do
            local Base = Entry.Name .. ' | "' .. Helper.Trim(Entry.PlainText, 26) .. '"'
            if Entry.IsRich then Base = Base .. " 🎨" end
            if Entry.GroupId then
                Base = Base .. " ⛓" .. tostring(Entry.GroupIndex)
                    .. "/" .. tostring(Entry.GroupSize)
            end
            local Label = Base
            if UsedLabels[Label] then
                local Depth = #Entry.Parts
                local Context = Depth >= 3
                    and (Entry.Parts[Depth - 2] .. "/" .. Entry.Parts[Depth - 1])
                    or (Entry.ParentName ~= "" and Entry.ParentName or "root")
                Label = Base .. "  •  " .. Context
            end
            if UsedLabels[Label] then
                local Suffix = 2
                while UsedLabels[Label .. " #" .. Suffix] do
                    Suffix += 1
                end
                Label = Label .. " #" .. Suffix
            end
            UsedLabels[Label] = true
            Entry.Label = Label
        end

        UIVisuals.Entries = Entries
        UIVisuals.EntryByKey = EntryByKey
        UIVisuals.LastScanCount = #Entries
        UIVisuals.LastScanSeconds = os.clock() - StartClock

        for Key, Record in pairs(UIVisuals.Edits) do
            local Entry = EntryByKey[Key]
            if Entry then
                if Record.Object ~= Entry.Object then
                    Helper.Attach(Record, Entry.Object)
                end
            elseif not Record.Object then
                local Replacement = Helper.Relocate(Record)
                if Replacement then Helper.Attach(Record, Replacement) end
            end
        end

        if UIVisuals.SelectedKey and not EntryByKey[UIVisuals.SelectedKey] then
            UIVisuals.SelectedKey = nil
        end
        if UIVisuals.GroupFilter and not Groups[UIVisuals.GroupFilter] then
            UIVisuals.GroupFilter = nil
        end

        UIVisuals.Scanning = false
        UIVisuals.ApplyFilter()
        UIVisuals.RefreshPalette()
        UIVisuals.UpdateSelectionInfo()
        LogSuccess(
            "UI Visuals scanned " .. tostring(#Entries) .. " text elements in "
            .. string.format("%.2f", UIVisuals.LastScanSeconds) .. "s",
            "UI Visuals"
        )
        Notify("UI Visuals", "Found " .. tostring(#Entries) .. " editable text elements.")
    end

    function UIVisuals.SelectLabel(Label)
        Label = tostring(Label or "")
        if Label == "" or Label == UIVisuals.Placeholder then return end
        local Key = UIVisuals.LabelToKey[Label]
        if not Key then return end
        UIVisuals.SelectedKey = Key
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetPendingText(Text)
        UIVisuals.PendingText = tostring(Text or "")
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetEditMode(Mode)
        Mode = tostring(Mode or "")
        if string.find(Mode, "Auto", 1, true)
            or string.find(Mode, "Figure", 1, true) then
            UIVisuals.EditMode = "auto"
        elseif string.find(Mode, "Bracket", 1, true) then
            UIVisuals.EditMode = "bracket"
        elseif string.find(Mode, "Name", 1, true) then
            UIVisuals.EditMode = "name"
        elseif string.find(Mode, "Segment", 1, true) then
            UIVisuals.EditMode = "segment"
        elseif string.find(Mode, "Everything", 1, true)
            or string.find(Mode, "Whole", 1, true) then
            UIVisuals.EditMode = "whole"
        else
            UIVisuals.EditMode = "number"
        end
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetTargetIndex(Value)
        UIVisuals.TargetIndex = math.max(math.floor(tonumber(Value) or 1), 1)
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetUseColor(Value)
        UIVisuals.UseColor = Value == true
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetEditColor(Color)
        if typeof(Color) == "Color3" then
            UIVisuals.EditColor = Color
        end
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetColorHexInput(Text)
        UIVisuals.ColorHexInput = tostring(Text or "")
        if UIVisuals.ColorHexInput ~= ""
            and not Helper.ParseHex(UIVisuals.ColorHexInput) then
            Notify("UI Visuals", "That colour code should look like #FF00FF.")
        end
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetMatchGameColor(Value)
        UIVisuals.MatchGameColor = Value == true
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetStyleOptions(Options)
        Options = type(Options) == "table" and Options or {}
        UIVisuals.Bold = table.find(Options, "Bold") ~= nil
        UIVisuals.Italic = table.find(Options, "Italic") ~= nil
        UIVisuals.Underline = table.find(Options, "Underline") ~= nil
        UIVisuals.Strike = table.find(Options, "Strikethrough") ~= nil
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.SetSizeOverride(Value)
        UIVisuals.SizeOverride = math.max(math.floor(tonumber(Value) or 0), 0)
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.CurrentColorHex()
        return Helper.ParseHex(UIVisuals.ColorHexInput)
            or Helper.ColorHex(UIVisuals.EditColor)
    end

    function UIVisuals.BuildPart()
        return {
            Mode = UIVisuals.EditMode,
            Occurrence = UIVisuals.TargetIndex,
            Value = UIVisuals.PendingText,
            InputIsRich = UIVisuals.InputIsRich,
            UseColor = UIVisuals.UseColor,
            ColorHex = UIVisuals.CurrentColorHex(),
            MatchGameColor = UIVisuals.MatchGameColor,
            Bold = UIVisuals.Bold, Italic = UIVisuals.Italic,
            Underline = UIVisuals.Underline, Strike = UIVisuals.Strike,
            Size = UIVisuals.SizeOverride
        }
    end

    function UIVisuals.SetRichTextOptions(Options)
        Options = type(Options) == "table" and Options or {}
        UIVisuals.AllowEnableRich = table.find(Options, "Allow RichText When Needed") ~= nil
        UIVisuals.InputIsRich = table.find(Options, "My Input Has RichText Tags") ~= nil
        UIVisuals.UpdateSelectionInfo()
    end

    function UIVisuals.ApplySelected()
        local Entry = UIVisuals.SelectedKey
            and UIVisuals.EntryByKey[UIVisuals.SelectedKey]
        if not Entry then
            Notify("UI Visuals", "Select a UI element first.")
            return
        end
        local Part = UIVisuals.BuildPart()
        local Styled = Helper.PartIsStyled(Part)
        if Part.Value == "" and not Styled then
            Notify("UI Visuals", "Type something into Custom Display Text first.")
            return
        end

        local Object = Entry.Object
        local Alive = false
        if Object then
            local Ok, Parent = pcall(function() return Object.Parent end)
            Alive = Ok and Parent ~= nil
        end

        local Record = UIVisuals.Edits[Entry.Key]
        if not Record then
            Record = {
                Key = Entry.Key,
                Name = Entry.Name,
                ClassName = Entry.ClassName,
                Parts = Entry.Parts,
                ParentName = Entry.ParentName,
                Path = Entry.Path,
                RealText = Entry.Text,
                LastApplied = nil,
                Changes = {},
                Active = true,
                Applying = false,
                Object = nil
            }
            UIVisuals.Edits[Entry.Key] = Record
            UIVisuals.EditCount += 1
        end
        Record.Changes = Record.Changes or {}
        Record.AllowEnableRich = UIVisuals.AllowEnableRich
        Record.Active = true

        local Key = Helper.PartKey(Part.Mode, Part.Occurrence)
        if Part.Mode == "whole" then
            Record.Changes = {Part}
        else
            local Replaced = false
            for Index, Existing in ipairs(Record.Changes) do
                if Helper.PartKey(Existing.Mode, Existing.Occurrence) == Key then
                    Record.Changes[Index] = Part
                    Replaced = true
                    break
                end
            end
            if not Replaced then table.insert(Record.Changes, Part) end
        end

        if not Alive then
            Object = Helper.Relocate(Record)
            if Object then Entry.Object = Object end
        end
        if not Object then
            Notify("UI Visuals", "That element no longer exists. Scan again.")
            LogWarning("UI Visuals apply failed: object missing (" .. Entry.Path .. ")", "UI Visuals")
            return
        end

        Helper.EnsureConnections()
        Helper.Attach(Record, Object)

        if Record.LastNote == "needsrich" then
            Notify("UI Visuals",
                "That label is not RichText. Turn on \"Allow Enabling RichText\" to style it.")
            LogWarning(
                "UI Visuals style refused: RichText disabled and opt-in off ("
                .. Entry.Path .. ")",
                "UI Visuals"
            )
        elseif Record.LastNote == "nomatch" then

            for Index = #Record.Changes, 1, -1 do
                if Helper.PartKey(Record.Changes[Index].Mode,
                    Record.Changes[Index].Occurrence) == Key then
                    table.remove(Record.Changes, Index)
                end
            end
            local Resolved = Part.ResolvedMode or Part.Mode
            local What = "number"
            if Resolved == "segment" then
                What = "segment"
            elseif Resolved == "bracket" then
                What = "[bracket]"
            elseif Resolved == "name" then
                What = "name"
            end
            Notify("UI Visuals",
                "No " .. What .. " #" .. tostring(Part.Occurrence) .. " in that label.")
            if #Record.Changes == 0 then Helper.Remove(Record, true) end
        else
            LogSuccess(
                "UI Visuals set " .. Entry.Path .. " [" .. tostring(Part.ResolvedMode or Part.Mode)
                .. " #" .. tostring(Part.Occurrence) .. "] "
                .. (Part.Value ~= "" and ("to " .. Helper.Trim(Part.Value, 40)) or "restyled")
                .. " (local display only), " .. tostring(#Record.Changes) .. " change(s) on this label",
                "UI Visuals"
            )
            Notify("UI Visuals",
                Entry.Name .. ": " .. tostring(#Record.Changes) .. " change(s) applied.")
        end

        UIVisuals.UpdateSelectionInfo()
        UIVisuals.UpdateGameInfo()
    end

    function UIVisuals.RemoveCurrentPart()
        local Key = UIVisuals.SelectedKey
        local Record = Key and UIVisuals.Edits[Key]
        if not Record or not Record.Changes then
            Notify("UI Visuals", "That label has no changes to remove.")
            return
        end
        local Wanted = Helper.PartKey(UIVisuals.EditMode, UIVisuals.TargetIndex)
        local Removed = 0
        for Index = #Record.Changes, 1, -1 do
            local Existing = Record.Changes[Index]
            if Helper.PartKey(Existing.Mode, Existing.Occurrence) == Wanted then
                table.remove(Record.Changes, Index)
                Removed += 1
            end
        end
        if Removed == 0 then
            Notify("UI Visuals", "No change on that exact target. Use Reset Selected instead.")
            return
        end
        if #Record.Changes == 0 then
            Helper.Remove(Record, true)
            Notify("UI Visuals", "Last change removed, label restored.")
        else

            Record.Applying = true
            pcall(function() Record.Object.Text = Record.RealText end)
            Record.Applying = false
            Helper.Reapply(Record, Record.RealText)
            Notify("UI Visuals",
                tostring(#Record.Changes) .. " change(s) still on this label.")
        end
        UIVisuals.UpdateSelectionInfo()
        UIVisuals.UpdateGameInfo()
    end

    function UIVisuals.ResetSelected()
        local Key = UIVisuals.SelectedKey
        local Record = Key and UIVisuals.Edits[Key]
        if not Record then
            Notify("UI Visuals", "The selected element has no edit to reset.")
            return
        end

        if not Record.Object then
            local Replacement = Helper.Relocate(Record)
            if Replacement then Record.Object = Replacement end
        end
        Helper.Remove(Record, true)
        UIVisuals.UpdateSelectionInfo()
        UIVisuals.UpdateGameInfo()
        Notify("UI Visuals", "Restored " .. Record.Name .. ".")
    end

    function UIVisuals.ResetAll(Silent)
        local Count = 0
        for _, Record in pairs(UIVisuals.Edits) do
            if not Record.Object then
                local Replacement = Helper.Relocate(Record)
                if Replacement then Record.Object = Replacement end
            end
            Helper.Remove(Record, true)
            Count += 1
        end
        UIVisuals.Edits = {}
        UIVisuals.EditCount = 0
        if Helper.ReleaseConnectionsIfIdle then Helper.ReleaseConnectionsIfIdle() end
        UIVisuals.UpdateSelectionInfo()
        UIVisuals.UpdateGameInfo()
        if not Silent then
            Notify("UI Visuals", "Restored " .. tostring(Count) .. " edited element(s).")
            LogSuccess("UI Visuals reset " .. tostring(Count) .. " edits", "UI Visuals")
        end
        return Count
    end

    function UIVisuals.SetKeepApplied(Value)
        UIVisuals.KeepApplied = Value == true
        if UIVisuals.KeepApplied and UIVisuals.EditCount > 0 then
            Helper.EnsureConnections()

            for _, Record in pairs(UIVisuals.Edits) do
                if Record.Active and Record.Object then
                    local Ok, Current = pcall(function() return Record.Object.Text end)
                    Helper.Reapply(Record, Ok and Current or Record.RealText)
                end
            end
        end
    end

    function UIVisuals.SetIncludeHidden(Value)
        UIVisuals.IncludeHidden = Value == true
    end

    function UIVisuals.SelfTest()
        local Blue = "#0000FF"
        local Red = "#FF0000"
        local Cases = {
            {
                Name = "plain number keeps prefix",
                Source = "$2,450", Rich = false,
                Mode = "number", Index = 1, Value = "999",
                Expect = "$999"
            },
            {
                Name = "rich number keeps font tags",
                Source = '<font color="' .. Red .. '">25</font><font color="#FFFFFF"> / 100</font>',
                Rich = true, Mode = "number", Index = 1, Value = "999",
                Expect = '<font color="' .. Red .. '">999</font><font color="#FFFFFF"> / 100</font>'
            },
            {
                Name = "second number targeted",
                Source = '<font color="' .. Red .. '">25</font><font color="#FFFFFF"> / 100</font>',
                Rich = true, Mode = "number", Index = 2, Value = "9999",
                Expect = '<font color="' .. Red .. '">25</font><font color="#FFFFFF"> / 9999</font>'
            },
            {
                Name = "decimal split by a tag is one number",
                Source = 'Strength [<font color="' .. Blue .. '">A</font>]: 2876.48',
                Rich = true, Mode = "number", Index = 1, Value = "1.5",
                Expect = 'Strength [<font color="' .. Blue .. '">A</font>]: 1.5'
            },
            {
                Name = "bracket contents across tags",
                Source = 'Strength [<font color="' .. Blue .. '">A</font>]: 2876.48',
                Rich = true, Mode = "bracket", Index = 1, Value = "S",
                Expect = 'Strength [<font color="' .. Blue .. '">S</font>]: 2876.48'
            },
            {
                Name = "auto picks bracket for a letter",
                Source = 'Strength [A]: 2876.48', Rich = false,
                Mode = "auto", Index = 1, Value = "S",
                Expect = "Strength [S]: 2876.48"
            },
            {
                Name = "auto picks number for digits",
                Source = "Strength [A]: 2876.48", Rich = false,
                Mode = "auto", Index = 1, Value = "9999",
                Expect = "Strength [A]: 9999"
            },
            {
                Name = "typed markup escaped on rich label",
                Source = '<font color="' .. Red .. '">25</font>', Rich = true,
                Mode = "number", Index = 1, Value = "<b>9</b>",
                Expect = '<font color="' .. Red .. '">&lt;b&gt;9&lt;/b&gt;</font>'
            },
            {
                Name = "colour wraps the edited piece",
                Source = 'Strength [A]: 10', Rich = false,
                Mode = "bracket", Index = 1, Value = "S", Color = Red, AllowRich = true,
                Expect = 'Strength [<font color="' .. Red .. '">S</font>]: 10'
            },
            {
                Name = "colour only keeps existing text",
                Source = "Strength [A]: 10", Rich = false,
                Mode = "bracket", Index = 1, Value = "", Color = Red, AllowRich = true,
                Expect = 'Strength [<font color="' .. Red .. '">A</font>]: 10'
            },
            {
                Name = "colour refused without the opt-in",
                Source = "Strength [A]: 10", Rich = false,
                Mode = "bracket", Index = 1, Value = "S", Color = Red, AllowRich = false,
                ExpectFail = "needsrich"
            },
            {
                Name = "missing target is refused",
                Source = "No digits here", Rich = false,
                Mode = "number", Index = 1, Value = "5",
                ExpectFail = "nomatch"
            },
            {
                Name = "name swapped, number kept",
                Source = "Strength [A]: 2876.48", Rich = false,
                Mode = "name", Index = 1, Value = "Power",
                Expect = "Power [A]: 2876.48"
            },
            {
                Name = "multi word name swapped",
                Source = "Total Coins: 300", Rich = false,
                Mode = "name", Index = 1, Value = "Cash",
                Expect = "Cash: 300"
            },
            {
                Name = "name inside font tag keeps the tag",
                Source = '<font color="#00FF00">Coins</font>: 300', Rich = true,
                Mode = "name", Index = 1, Value = "Gems",
                Expect = '<font color="#00FF00">Gems</font>: 300'
            },
            {
                Name = "unit suffix is not a name",
                Source = "1.5k Coins", Rich = false,
                Mode = "name", Index = 1, Value = "Gems",
                Expect = "1.5k Gems"
            },
            {
                Name = "auto picks name for a word",
                Source = "Strength [A]: 2876.48", Rich = false,
                Mode = "auto", Index = 1, Value = "Power",
                Expect = "Power [A]: 2876.48"
            },
            {
                Name = "auto still picks bracket for a short tag",
                Source = "Strength [A]: 2876.48", Rich = false,
                Mode = "auto", Index = 1, Value = "S",
                Expect = "Strength [S]: 2876.48"
            },
            {
                Name = "colour rewrites the existing tag, no nesting",
                Source = 'Strength [<font color="#0000FF">A</font>]: 10', Rich = true,
                Mode = "bracket", Index = 1, Value = "S", Color = "#FF0000",
                AllowRich = true,
                Expect = 'Strength [<font color="#FF0000">S</font>]: 10'
            },
            {
                Name = "bold and italic wrap correctly",
                Source = "Coins: 300", Rich = false,
                Mode = "name", Index = 1, Value = "Gems",
                Bold = true, Italic = true, AllowRich = true,
                Expect = "<b><i>Gems</i></b>: 300"
            },
            {
                Name = "size override emitted",
                Source = "Coins: 300", Rich = false,
                Mode = "number", Index = 1, Value = "9", Size = 40, AllowRich = true,
                Expect = 'Coins: <font size="40">9</font>'
            },
            {
                Name = "name and number changed together",
                Source = "Coins: 300", Rich = false,
                Changes = {
                    {Mode = "name", Occurrence = 1, Value = "Gems"},
                    {Mode = "number", Occurrence = 1, Value = "999"}
                },
                Expect = "Gems: 999"
            },
            {
                Name = "three edits on one rich label",
                Source = 'Strength [<font color="#0000FF">A</font>]: 2876.48', Rich = true,
                Changes = {
                    {Mode = "name", Occurrence = 1, Value = "Power"},
                    {Mode = "bracket", Occurrence = 1, Value = "S"},
                    {Mode = "number", Occurrence = 1, Value = "1000"}
                },
                Expect = 'Power [<font color="#0000FF">S</font>]: 1000'
            },
            {
                Name = "later edit does not undo the earlier one",
                Source = "Coins: 300", Rich = false,
                Changes = {
                    {Mode = "number", Occurrence = 1, Value = "999"},
                    {Mode = "name", Occurrence = 1, Value = "Gems"}
                },
                Expect = "Gems: 999"
            },
            {
                Name = "plain label leaves brackets alone",
                Source = "Level 12", Rich = false,
                Mode = "auto", Index = 1, Value = "100",
                Expect = "Level 100"
            }
        }

        local Passed, Failed = 0, 0
        local Problems = {}
        for _, Case in ipairs(Cases) do
            local Record = {
                Changes = Case.Changes or {{
                    Mode = Case.Mode,
                    Value = Case.Value,
                    Occurrence = Case.Index,
                    InputIsRich = false,
                    UseColor = Case.Color ~= nil,
                    ColorHex = Case.Color,
                    Bold = Case.Bold, Italic = Case.Italic,
                    Underline = Case.Underline, Strike = Case.Strike,
                    Size = Case.Size
                }},
                AllowEnableRich = Case.AllowRich == true
            }
            local Returned
            local Ok = pcall(function()
                Returned = table.pack(Helper.Compose(Record, Case.Source, Case.Rich))
            end)
            local Actual, Success, Reason
            if Ok and Returned then
                Actual, Success, Reason = Returned[1], Returned[2], Returned[3]
            end
            local Good
            if not Ok then
                Good = false
                Reason = "error"
            elseif Case.ExpectFail then
                Good = (Success ~= true) and Reason == Case.ExpectFail
            else
                Good = (Success == true) and Actual == Case.Expect
            end
            if Good then
                Passed += 1
            else
                Failed += 1
                table.insert(Problems, Case.Name .. " → " .. tostring(Actual or Reason))
            end
        end

        local Summary = tostring(Passed) .. " passed, " .. tostring(Failed) .. " failed"
        if Failed == 0 then
            LogSuccess("UI Visuals self test: " .. Summary, "UI Visuals")
            Notify("UI Visuals Self Test", "All " .. tostring(Passed) .. " checks passed.")
        else
            LogError("UI Visuals self test: " .. Summary .. "\n"
                .. table.concat(Problems, "\n"), "UI Visuals")
            Notify("UI Visuals Self Test", Summary .. ". See executor output.")
        end
        if UIVisuals.InfoParagraph then
            pcall(function()
                UIVisuals.InfoParagraph:Set({
                    Title = Failed == 0 and "🧪 Self Test Passed" or "🧪 Self Test Failed",
                    Content = "Text engine: " .. Summary
                        .. "\n\nThese checks run on plain strings only - nothing in your game"
                        .. " was read or changed."
                        .. (Failed > 0 and ("\n\n" .. table.concat(Problems, "\n")) or "")
                        .. "\n\nSelect a UI element to go back to the normal view."
                })
            end)
        end
        return Failed == 0
    end

    function UIVisuals.Shutdown(Silent)
        pcall(function() UIVisuals.ResetAll(true) end)
        for Name, Connection in pairs(UIVisuals.Connections) do
            if Connection then
                pcall(function() Connection:Disconnect() end)
            end
            UIVisuals.Connections[Name] = nil
        end
        UIVisuals.Entries = {}
        UIVisuals.EntryByKey = {}
        UIVisuals.LabelToKey = {}
        UIVisuals.Filtered = {}
        UIVisuals.Groups = {}
        UIVisuals.Palette = {}
        UIVisuals.PaletteLabelToHex = {}
        UIVisuals.GroupFilter = nil
        UIVisuals.SelectedKey = nil
        UIVisuals.LastScanCount = 0
        UIVisuals.Scanning = false
        if not Silent then
            pcall(UIVisuals.RefreshDropdown)
            pcall(UIVisuals.RefreshPalette)
            pcall(UIVisuals.UpdateSelectionInfo)
        end
    end
end

Runtime.CaptureSession = function()
    Runtime.NormalizeWaypointOrder()
    return {
        PlaceId = tostring(game.PlaceId), Points = Waypoints,
        Order = Runtime.WaypointOrder, Route = Runtime.WaypointRoute,
        Favorites = Runtime.GetFavoriteList(),
        TemporaryPosition = SavedPosition and EncodeCFrame(SavedPosition) or nil,
        CameraPosition = SavedFreecamCFrame and EncodeCFrame(SavedFreecamCFrame) or nil
    }
end
Runtime.RestoreSession = function(Data)
    if type(Data) ~= "table" then return end
    Runtime.Favorites = {}
    if type(Data.Favorites) == "table" then
        for _, Name in ipairs(Data.Favorites) do
            if type(Name)=="string" and Name~="" and #Name<=120 then
                Runtime.Favorites[Name] = true
                if not table.find(Runtime.FavoriteOptions, Name) then table.insert(Runtime.FavoriteOptions, Name) end
            end
        end
    end
    if tostring(Data.PlaceId) ~= tostring(game.PlaceId) then
        Notify("Configuration", "Settings loaded. Waypoints belong to a different place and were skipped.")
        return
    end
    Waypoints, Runtime.WaypointOrder = {}, {}
    if type(Data.Points) == "table" then
        for Name, Components in pairs(Data.Points) do
            if type(Name) == "string" and #Name > 0 and #Name <= 100 and DecodeCFrame(Components) then
                Waypoints[Name] = table.clone(Components)
            end
        end
    end
    local function ValidRoute(Value)
        local Result = {}
        if type(Value) ~= "table" then return Result end
        for _, Name in ipairs(Value) do
            if type(Name) == "string" and Waypoints[Name] then table.insert(Result, Name) end
            if #Result >= 500 then break end
        end
        return Result
    end
    Runtime.WaypointOrder = ValidRoute(Data.Order)
    Runtime.NormalizeWaypointOrder()
    Runtime.WaypointRoute = ValidRoute(Data.Route)
    Runtime.RouteCurrentIndex, Runtime.RouteRetryCount = 1, 0
    Runtime.RouteSelectedCheckpoint, Runtime.RouteSelectedWaypoint = nil, nil
    SavedPosition, SavedFreecamCFrame = DecodeCFrame(Data.TemporaryPosition), DecodeCFrame(Data.CameraPosition)
    RefreshWaypoints()
end

local function SafeFeatureCallback(Feature, Callback)
    return function(...)
        if Unloaded then return false end
        local Arguments = table.pack(...)
        local Results
        local Success, Failure = xpcall(function()
            Results = table.pack(Callback(table.unpack(Arguments, 1, Arguments.n)))
        end, function(ErrorMessage)
            local Message = tostring(ErrorMessage)
            local Line = tonumber(Message:match(":(%d+):")) or tonumber(Message:match("line%s+(%d+)"))
            AddActionLog("Error", Message, tostring(Feature or "Unknown"), Line)
            Notify("Feature Error", tostring(Feature or "Unknown") .. " failed. Check the executor output.")
            return Message
        end)
        if not Success then
            if Runtime.ConfigLoadActive then Runtime.ConfigCallbackFailed = true end
            return false, Failure
        end
        if not Results then return true end
        return table.unpack(Results, 1, Results.n)
    end
end
local function ProtectTabCallbacks(Tab)
    if type(Tab) ~= "table" or Tab.__BananiProtected then return Tab end
    Tab.__BananiProtected = true
    for _, MethodName in ipairs({
        "CreateButton", "CreateToggle", "CreateSlider",
        "CreateDropdown", "CreateInput", "CreateKeybind", "CreateColorPicker"
    }) do
        local Original = Tab[MethodName]
        if type(Original) == "function" then
            Tab[MethodName] = function(Self, Options, ...)
                if type(Options) == "table" and type(Options.Callback) == "function" then
                    Options.Callback = SafeFeatureCallback(Options.Name or MethodName, Options.Callback)
                end
                local Control = Original(Self, Options, ...)
                if type(Options) == "table" and type(Options.Flag) == "string" then
                    Rayfield.Flags[Options.Flag] = Control
                    Runtime.ControlTypes[Options.Flag] = MethodName
                end
                return Control
            end
        end
    end
    return Tab
end
do
    local OriginalCreateTab = Window.CreateTab
    if type(OriginalCreateTab) == "function" then
        Window.CreateTab = function(Self, ...)
            return ProtectTabCallbacks(OriginalCreateTab(Self, ...))
        end
    end
end
Runtime.SetInterfaceMode = function(Mode, Silent)
    Runtime.CompactMode = tostring(Mode) == "Compact"
    if Rayfield and Rayfield.SetCompactMode then
        pcall(function() Rayfield:SetCompactMode(Runtime.CompactMode) end)
    end
    Runtime.UpdatePreferenceDisplays()
    if not Silent then
        Notify("Interface", Runtime.CompactMode and "Compact layout enabled." or "Normal layout enabled.")
    end
    return true
end
Runtime.SetFlagValue = function(FlagName, Value)
    local Flag = Rayfield.Flags and Rayfield.Flags[FlagName]
    if Flag and Flag.Set then
        local Success = pcall(function() Flag:Set(Value) end)
        return Success
    end
    return false
end

