Runtime.GetOrganizationSummary=function()
    local Summary={
        Version=Runtime.Organization and Runtime.Organization.Version or "unknown",
        Profile=tostring(Runtime.DetectedGameProfileKind or "Adaptive"),
        ActiveAutomation=tostring(Runtime.ActiveAutomationName or "None"),
        ConnectionCount=0,
        CleanupOwnedCount=0,
        TargetQueueCount=tonumber(Runtime.BloxTargetQueueCount) or 0,
        MovementZoneCount=type(Runtime.BloxMovementZones)=="table" and #Runtime.BloxMovementZones or 0,
        ReferenceMapCount=0
    }
    for _ in pairs(Runtime.ReferenceMethodMap or {}) do Summary.ReferenceMapCount+=1 end
    for _,Connection in ipairs(Runtime.Connections or {}) do
        if Connection then Summary.ConnectionCount+=1 end
    end
    local Registry=Runtime.CleanupRegistry
    if Registry and Registry.Items then
        for _ in pairs(Registry.Items) do Summary.CleanupOwnedCount+=1 end
    end
    return Summary
end

-- ==================================================================
-- [BH:CORE] AUTOMATION HEALTH + PERFORMANCE BUDGET
-- Measures automation cost/errors without changing combat timing.
-- ==================================================================
Runtime.AutomationHealth=Runtime.AutomationHealth or {}

Runtime.RecordAutomationStep=function(Name,Ok,Seconds,Err)
    Name=tostring(Name or "Automation")
    local H=Runtime.AutomationHealth[Name]
    if not H then
        H={
            Runs=0,Successes=0,Errors=0,ConsecutiveErrors=0,
            AverageMs=0,MaxMs=0,LastMs=0,LastSuccessAt=0,
            LastErrorAt=0,LastError=""
        }
        Runtime.AutomationHealth[Name]=H
    end

    local Ms=math.max(0,(tonumber(Seconds) or 0)*1000)
    H.Runs+=1
    H.LastMs=Ms
    H.MaxMs=math.max(tonumber(H.MaxMs) or 0,Ms)
    if H.Runs<=1 then
        H.AverageMs=Ms
    else
        -- Exponential average keeps the number useful during long sessions.
        H.AverageMs=(tonumber(H.AverageMs) or Ms)*0.90+Ms*0.10
    end

    if Ok then
        H.Successes+=1
        H.ConsecutiveErrors=0
        H.LastSuccessAt=os.clock()
        local Entry=Runtime.AutomationStatus and Runtime.AutomationStatus[Name]
        if Entry then
            Entry.LastSuccess=H.LastSuccessAt
            Entry.LastStepMs=Ms
            Entry.AverageStepMs=H.AverageMs
        end
    else
        H.Errors+=1
        H.ConsecutiveErrors+=1
        H.LastErrorAt=os.clock()
        H.LastError=string.sub(tostring(Err or "Unknown error"),1,300)
        local Entry=Runtime.AutomationStatus and Runtime.AutomationStatus[Name]
        if Entry then
            Entry.LastError=H.LastError
            Entry.LastStepMs=Ms
            Entry.AverageStepMs=H.AverageMs
            Entry.RetryCount=H.ConsecutiveErrors
        end
    end
    return H
end

Runtime.GetVisualUpdateScale=function()
    -- Roblox recommends keeping expensive frame-event work limited.
    -- Only visual/status refreshes use this factor; movement/combat do not.
    if Runtime.AFKMode and Runtime.AFKMode.Active then return 2.40 end
    local FPS=tonumber(LiveTelemetry and LiveTelemetry.FPS) or 60
    if FPS>0 and FPS<25 then return 2.00 end
    if FPS>0 and FPS<35 then return 1.65 end
    if FPS>0 and FPS<45 then return 1.30 end
    return 1.00
end

