Runtime.GetAutomationHealthReport=function(MaxRows)
    MaxRows=math.clamp(tonumber(MaxRows) or 10,1,25)
    local Rows={}
    for Name,H in pairs(Runtime.AutomationHealth or {}) do
        table.insert(Rows,{
            Name=Name,
            Runs=tonumber(H.Runs) or 0,
            Errors=tonumber(H.Errors) or 0,
            ConsecutiveErrors=tonumber(H.ConsecutiveErrors) or 0,
            AverageMs=tonumber(H.AverageMs) or 0,
            MaxMs=tonumber(H.MaxMs) or 0,
            LastError=tostring(H.LastError or "")
        })
    end
    table.sort(Rows,function(A,B)
        if A.ConsecutiveErrors~=B.ConsecutiveErrors then return A.ConsecutiveErrors>B.ConsecutiveErrors end
        if A.Errors~=B.Errors then return A.Errors>B.Errors end
        if math.abs(A.AverageMs-B.AverageMs)>0.05 then return A.AverageMs>B.AverageMs end
        return A.Name<B.Name
    end)

    if #Rows==0 then return "No automation has run yet." end
    local Lines={}
    for I=1,math.min(#Rows,MaxRows) do
        local R=Rows[I]
        local Status=R.ConsecutiveErrors>0 and ("ERR x"..R.ConsecutiveErrors) or "OK"
        local Line=Status.." • "..R.Name
            .." • avg "..string.format("%.2f",R.AverageMs).."ms"
            .." • max "..string.format("%.2f",R.MaxMs).."ms"
        if R.Errors>0 then Line..=" • errors "..R.Errors end
        table.insert(Lines,Line)
    end
    return table.concat(Lines,"\n")
end

Runtime.RunProfileSelfTest=function()
    local Profile=tostring(Runtime.DetectedGameProfileKind or "Adaptive")
    local Lines={}
    local Passed,Required=0,0

    local function Test(Name,Condition,RequiredCheck,Detail)
        if RequiredCheck~=false then Required+=1 end
        local Good=Condition==true
        if RequiredCheck~=false and Good then Passed+=1 end
        local Prefix
        if RequiredCheck==false then Prefix=Good and "INFO • " or "CHECK • "
        else Prefix=Good and "PASS • " or "FAIL • " end
        local Text=Prefix..Name
        if Detail and tostring(Detail)~="" then Text..=" • "..tostring(Detail) end
