-- ==================================================================
-- [BH:CORE] GAME MODULE REGISTRY
-- Central profile-module registration starts here.
-- ==================================================================
Runtime.GameModules = Runtime.GameModules or {}
    local ActiveModule = Runtime.GameModules[Kind] or {Kind=Kind,Loops={},API={},Errors={},StartedAt=os.clock()}
    Runtime.GameModules[Kind]=ActiveModule
    Runtime.ActiveGameModule=ActiveModule
    ActiveModule.State=State

    State.MVSAimSmooth = State.MVSAimSmooth or 7
    State.MVSFOV = math.clamp(tonumber(State.MVSFOV) or 280,40,900)
    State.MVSVisibleOnly = State.MVSVisibleOnly ~= false

    Runtime.AutomationStatus = Runtime.AutomationStatus or {}
    Runtime.RefreshActiveAutomation = function()
        local BestName,BestEntry=nil,nil
        local Newest=-math.huge
        for CandidateName,Candidate in pairs(Runtime.AutomationStatus) do
            local CandidateState=Candidate and tostring(Candidate.State or "Idle") or "Idle"
            local Updated=Candidate and tonumber(Candidate.UpdatedAt) or 0
            local Passive=State.PassiveLoops and State.PassiveLoops[CandidateName]==true
            if not Passive and CandidateState~="Idle" and Updated>=Newest then
                BestName,BestEntry,Newest=CandidateName,Candidate,Updated
            end
        end
        Runtime.ActiveAutomationName=BestName
        Runtime.ActiveAutomationState=BestEntry and tostring(BestEntry.State or "Working") or "Idle"
        Runtime.ActiveAutomationReason=BestEntry and tostring(BestEntry.Reason or "") or ""
        Runtime.ActiveAutomationUpdatedAt=BestEntry and tonumber(BestEntry.UpdatedAt) or 0
        return BestName,BestEntry
    end
    Runtime.SetAutomationState = function(Name, Phase, Reason)
        Name=tostring(Name or "Automation")
        local Entry=Runtime.AutomationStatus[Name] or {Target="",LastSuccess=nil,LastError="",RetryCount=0}
        local NewState=tostring(Phase or "Idle")
        local NewReason=tostring(Reason or "")
        local Now=os.clock()
        if tostring(Entry.State or "")~=NewState or tostring(Entry.Reason or "")~=NewReason then
            Entry.StateSince=Now
            Entry.LastChangedAt=Now
        end
        Entry.State=NewState
        Entry.Reason=NewReason
        Entry.UpdatedAt=Now
        Runtime.AutomationStatus[Name]=Entry
        Runtime.LastAutomationName=Name
        Runtime.LastAutomationState=Entry.State
        Runtime.LastAutomationReason=Entry.Reason
        local Passive=State.PassiveLoops and State.PassiveLoops[Name]==true
        if Entry.State~="Idle" and not Passive then
            Runtime.ActiveAutomationName=Name
            Runtime.ActiveAutomationState=Entry.State
            Runtime.ActiveAutomationReason=Entry.Reason
            Runtime.ActiveAutomationUpdatedAt=Entry.UpdatedAt
        elseif Runtime.ActiveAutomationName==Name and Runtime.RefreshActiveAutomation then
            Runtime.RefreshActiveAutomation()
        end
        return Entry
    end

    local function BumpLoop(Name)
        State.Loops[Name] = (tonumber(State.Loops[Name]) or 0) + 1
        return State.Loops[Name]
    end

-- ==================================================================
-- [BH:CORE] AUTOMATION LOOP SCHEDULER
-- Single loop ownership/status layer used by profile automations.
-- ==================================================================
    local function StopLoop(Name)
        local OldThread=State.LoopThreads and State.LoopThreads[Name]
        if State.LoopThreads then State.LoopThreads[Name]=nil end
        if ActiveModule and ActiveModule.Loops then ActiveModule.Loops[Name]=nil end
        BumpLoop(Name)
        if Runtime.Movement then
            Runtime.Movement.Stop(Name)
            if OldThread and Runtime.Movement.Contexts then Runtime.Movement.Contexts[OldThread]=nil end
        end
        if OldThread and OldThread~=coroutine.running() and task.cancel then pcall(task.cancel,OldThread) end
        if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Idle","") end
    end
    local function StartLoop(Name, Step, Delay)
        StopLoop(Name)
        local Token = State.Loops[Name]
        State.LoopFailureCount=State.LoopFailureCount or {}
        State.LoopFailureCount[Name]=0
        State.LoopErrors=State.LoopErrors or {}
        if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Working","") end
        task.spawn(function()
            local ThisThread=coroutine.running()
            local M=Runtime.Movement
            -- One context per loop lifetime avoids table/function allocation on every tick and
            -- lets StopLoop invalidate a sleeping loop immediately.
            local LoopContext={Name=Name,Cancelled=false,Valid=function()
                return not Unloaded and State.Loops[Name]==Token
            end}
            M.Contexts[ThisThread]=LoopContext
            State.LoopThreads[Name]=ThisThread
            if ActiveModule and ActiveModule.Loops then ActiveModule.Loops[Name]=ThisThread end
            local LastWorkingStatusAt=-math.huge
            while not Unloaded and State.Loops[Name] == Token and not LoopContext.Cancelled do
                if Runtime.SetAutomationState and os.clock()-LastWorkingStatusAt>=0.75 then
                    local Existing=Runtime.AutomationStatus and Runtime.AutomationStatus[Name]
                    if not Existing or tostring(Existing.State or "")~="Working" or tostring(Existing.Reason or "")~="" then
                        Runtime.SetAutomationState(Name,"Working","")
                    else
                        Existing.UpdatedAt=os.clock()
                        if Runtime.ActiveAutomationName==Name then Runtime.ActiveAutomationUpdatedAt=Existing.UpdatedAt end
                    end
                    LastWorkingStatusAt=os.clock()
                end
                local StepStarted=os.clock()
                local Ok,Err=pcall(function() M.Guard(); Step() end)
                local StepSeconds=os.clock()-StepStarted
                if Runtime.RecordAutomationStep then Runtime.RecordAutomationStep(Name,Ok,StepSeconds,Err) end
                if M.Owner==Name and M.OwnerContext==LoopContext then M.Release(Name) end
                if Unloaded or State.Loops[Name]~=Token or LoopContext.Cancelled then break end
                if not Ok then
                    local Message=tostring(Err)
                    State.LoopFailureCount=State.LoopFailureCount or {}
                    local HardError=not string.find(Message,"BANANI_MOVEMENT_BUSY",1,true) and not string.find(Message,"BANANI_CANCELLED",1,true)
                    if string.find(Message,"BANANI_MOVEMENT_BUSY",1,true) then
                        State.LoopFailureCount[Name]=0
                        if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Recovering","Waiting for movement controller") end
                    elseif string.find(Message,"BANANI_CANCELLED",1,true) then
                        State.LoopFailureCount[Name]=0
                        if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Recovering","Waiting for character / target") end
                    else
                        State.LoopFailureCount[Name]=(tonumber(State.LoopFailureCount[Name]) or 0)+1
                        if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Recovering",string.sub(Message,1,90)) end
                        State.LastLoopErrors=State.LastLoopErrors or {}
                        State.LastLoopErrors[Name]=string.sub(Message,1,300)
                        if ActiveModule and ActiveModule.Errors then ActiveModule.Errors[Name]=State.LastLoopErrors[Name] end
                        local Entry=Runtime.AutomationStatus[Name]
                        if Entry then Entry.LastError=State.LastLoopErrors[Name]; Entry.RetryCount=State.LoopFailureCount[Name] end
                        local Last=tonumber(State.LoopErrors[Name]) or -math.huge
                        if os.clock()-Last>=6 then
                            warn("BANANIHUB | "..tostring(Runtime.DetectedGameProfileKind or "Game").." | "..tostring(Name).." | "..Message)
                            State.LoopErrors[Name]=os.clock()
                            Notify(tostring(Runtime.DetectedGameProfileKind or "Game").." Error",tostring(Name).." failed: "..string.sub(Message,1,150))
                        end
                    end
                    local Failures=HardError and (tonumber(State.LoopFailureCount[Name]) or 1) or 1
                    task.wait(math.min(0.25+(Failures-1)*0.20,1.25))
                else
                    State.LoopFailureCount=State.LoopFailureCount or {}
                    State.LoopFailureCount[Name]=0
                end
                local DelayOK,WaitTime=pcall(function()
                    return type(Delay)=="function" and Delay() or Delay
                end)
                if not DelayOK then
                    State.LastLoopErrors=State.LastLoopErrors or {}
                    State.LastLoopErrors[Name]=string.sub("Delay: "..tostring(WaitTime),1,300)
                    if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Recovering","Invalid loop delay") end
                    WaitTime=0.1
                end
                task.wait(math.max(tonumber(WaitTime) or 0.1,0.01))
            end
            if M and M.Contexts and M.Contexts[ThisThread]==LoopContext then M.Contexts[ThisThread]=nil end
            if State.Loops[Name]==Token then
                if M and M.Owner==Name and (not M.OwnerContext or M.OwnerContext==LoopContext) then M.Release(Name) end
                if State.LoopThreads and State.LoopThreads[Name]==ThisThread then State.LoopThreads[Name]=nil end
                if ActiveModule and ActiveModule.Loops then ActiveModule.Loops[Name]=nil end
                if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Idle","") end
            end
        end)
    end
    local function StartPassiveLoop(Name,Step,Delay)
        State.PassiveLoops[Name]=true
        -- Passive dashboards/status samplers do not need combat-rate polling. Slow them down
        -- slightly when FPS is low (or AFK saver is active) without changing active automation.
        local function AdaptivePassiveDelay()
            local Base
            local Ok,Value=pcall(function() return type(Delay)=="function" and Delay() or Delay end)
            Base=Ok and tonumber(Value) or 0.5
            Base=math.clamp(Base or 0.5,0.05,10)
            local FPS=tonumber(LiveTelemetry and LiveTelemetry.FPS) or 60
            local Factor=1
            if Runtime.AFKMode and Runtime.AFKMode.Active then Factor=2.0
            elseif FPS>0 and FPS<30 then Factor=1.55
            elseif FPS>0 and FPS<45 then Factor=1.25 end
            return math.clamp(Base*Factor,0.05,12)
        end
        StartLoop(Name,Step,AdaptivePassiveDelay)
    end
    Runtime.GameProfileReset = function(KeepPassive)
        for Name in pairs(State.Loops) do
            if not (KeepPassive and State.PassiveLoops[Name]) then StopLoop(Name) end
        end
        if Runtime.ProfileAimClear then Runtime.ProfileAimClear() end
        Runtime.MM2FarmActive=false
        Runtime.MM2StopGeneration=(tonumber(Runtime.MM2StopGeneration) or 0)+1
        Runtime.MM2FarmGeneration=(tonumber(Runtime.MM2FarmGeneration) or 0)+1
        Runtime.MM2FlingGeneration=(tonumber(Runtime.MM2FlingGeneration) or 0)+1
        Runtime.MM2FlingActive=false
        if Runtime.CancelMM2Travel then pcall(Runtime.CancelMM2Travel) end
        if Runtime.MM2SetInvisible then pcall(function() Runtime.MM2SetInvisible(false,true) end) end
        if Runtime.MM2FOVCircle then
            pcall(function() Runtime.MM2FOVCircle:Remove() end)
            Runtime.MM2FOVCircle=nil
        end
        if Runtime.MM2ESPPlusCleanup then pcall(Runtime.MM2ESPPlusCleanup) end
        if Runtime.MM2CoinESPCleanup then pcall(Runtime.MM2CoinESPCleanup) end
        Runtime.MM2AimLockedPlayer=nil
        Runtime.MM2AimLockedAt=nil
        Runtime.MM2AimMotion=nil
        for _,Gui in pairs(State.MM2Tags or {}) do
            pcall(function() Gui:Destroy() end)
        end
        for _,Gui in pairs(State.MM2ObjectHighlights or {}) do
            pcall(function() Gui:Destroy() end)
        end
        State.MM2Tags = {}
        State.MM2ObjectHighlights = {}
        for _,Highlight in pairs(State.BloxEnemyHighlights or {}) do
            pcall(function() Highlight:Destroy() end)
        end
        State.BloxEnemyHighlights = {}
        if Runtime.AdoptCleanup then pcall(Runtime.AdoptCleanup) end
        if Runtime.BuildABoatCleanup then pcall(Runtime.BuildABoatCleanup) end
        if State.AdoptSafePlatform then pcall(function() State.AdoptSafePlatform:Destroy() end) end
        State.AdoptSafePlatform = nil
        if State.BasketAidHighlight then pcall(function() State.BasketAidHighlight:Destroy() end) end
        State.BasketAidHighlight = nil
        for Part,Old in pairs(State.ArsenalHitboxBackup or {}) do
            if Part and Part.Parent and type(Old)=="table" then
                pcall(function()
                    Part.Size = Old.Size
                    Part.Transparency = Old.Transparency
                    Part.CanCollide = Old.CanCollide
                end)
            end
        end
        State.ArsenalHitboxBackup = {}
        for Tbl,Backup in pairs(State.ArsenalWeaponBackup or {}) do
            if type(Tbl)=="table" and type(Backup)=="table" then
                for K,V in pairs(Backup) do pcall(function() Tbl[K]=V end) end
            end
        end
        State.ArsenalWeaponBackup = {}
        if Runtime.ArsenalRestoreValueMods then pcall(Runtime.ArsenalRestoreValueMods) end
        if Runtime.ArsenalDisconnectWeaponWatch then pcall(Runtime.ArsenalDisconnectWeaponWatch) end
        if Runtime.ArsenalESPCleanup then pcall(Runtime.ArsenalESPCleanup) end
        if Runtime.PrisonRestoreGunMods then pcall(Runtime.PrisonRestoreGunMods) end
        if Runtime.PrisonESPCleanup then pcall(Runtime.PrisonESPCleanup) end
        if Runtime.SetUniversalInvisible then pcall(function() Runtime.SetUniversalInvisible(false,true) end) end
        StopLoop("ProfileExtraOrbit"); StopLoop("ProfileExtraInteract"); StopLoop("ProfileExtraPickup")
        StopLoop("ProfileExtraKeepTool"); StopLoop("ProfileExtraUseTool")
        StopLoop("MVSAim")
        State.ArsenalLockSelected=false
        State.PrisonNoRecoil=false; State.PrisonNoSpread=false; State.PrisonRapidFire=false; State.PrisonInfiniteAmmo=false
        State.PrisonInstantReload=false; State.PrisonAutoFire=false; State.PrisonLongRange=false
    end

    -- IMPORTANT: this profile setup scope is already close to Luau's 200-local/register ceiling.
    -- Store the builder directly on Runtime so declaring it does not consume another long-lived local.
    Runtime.BuildDetectedGameProfile = function()
        if Runtime.DetectedGameProfileBuilt then return true end
        Runtime.DetectedGameProfileBuilt = true

        local BuildOk, BuildErr = pcall(function()
        local function GetRoot(Object)
            if not Object or not Object.Parent then return nil end
            if Object:IsA("BasePart") then return Object end
            if Object:IsA("Model") then
                return Object:FindFirstChild("HumanoidRootPart")
                    or Object.PrimaryPart
                    or Object:FindFirstChild("UpperTorso")
                    or Object:FindFirstChild("Torso")
                    or Object:FindFirstChildWhichIsA("BasePart", true)
            end
            if Object:IsA("Tool") then return Object:FindFirstChild("Handle") end
            return Object:FindFirstChildWhichIsA("BasePart", true)
        end
        local function IsPlayerCharacter(Model)
            if not Model or not Model:IsA("Model") then return false end
            local Node = Model
            while Node and Node ~= workspace do
                if Node:IsA("Model") and Players:GetPlayerFromCharacter(Node) then return true end
                Node = Node.Parent
            end
            return false
        end
        local BloxSmartEntranceTravel

        Runtime.ProfileRouter={}
        State.ProfileSmartRoute = true
        Runtime.ProfileSmartRoute = Runtime.ProfileSmartRoute or {
            LastGame=nil, LastStatus="Ready", LastWaypoints=0, LastAt=0,
        }

        function Runtime.ProfileRouter.Direct(CF,Mode,Provider,Source)
            -- While Player Protection owns the character, no farm/teleport route is allowed to
            -- pull the avatar back out of the underground hold. The protection heartbeat restores
            -- normal routing only after the tracked threat has actually cleared the area.
            if Kind=="BloxFruits" and Runtime.BloxPlayerProtectionActive==true
                and tostring(Source or "")~="BloxPlayerProtection" then
                Runtime.BloxCombatLastResult="Player Protection • hiding underground"
                return false
            end
            -- v5.18.22: every Blox Fruits movement path automatically exits Cursed Ship first
            -- when its real destination is outside the ship. The dedicated exit route sets a
            -- recursion guard while moving across its two trigger points, then this original
            -- movement request resumes normally from the exterior coordinate space.
            if Kind=="BloxFruits" and not Runtime.BloxCursedShipExitRouting
                and type(Runtime.BloxCursedShipExitTravel)=="function"
                and type(Runtime.IsBloxCursedShipInteriorPosition)=="function" then
                local Current=Root()
                local Destination=(typeof(CF)=="CFrame" and CF.Position) or (typeof(CF)=="Vector3" and CF) or nil
                if Current and Destination
                    and Runtime.IsBloxCursedShipInteriorPosition(Current.Position)
                    and not Runtime.IsBloxCursedShipInteriorPosition(Destination) then
                    local ExitOk=Runtime.BloxCursedShipExitTravel("AutoExit:"..tostring(Source or "GameProfile"))
                    if not ExitOk then return false end
                end
            end
            if Runtime.Movement and Runtime.Movement.SetState then
                Runtime.Movement.SetState("Target","Routing to target",tostring(Source or "GameProfile"))
            end
            if not Runtime.TravelToCFrame then
                local Ok=pcall(function() SafeTeleport(CF) end)
                return Ok
            end
            local Ok,Result=pcall(function()
                return Runtime.TravelToCFrame(CF,Mode,Source or "GameProfile",Provider)
            end)
            if not Ok and tostring(Result):find("BANANI_CANCELLED",1,true) then error(Result,0) end
            return Ok and Result~=false
        end

        function Runtime.ProfileRouter.Generic(CF,Mode,Provider,Source)
            Runtime.Movement.Guard()
            local R=Root()
            if not R then return false end
            if (R.Position-CF.Position).Magnitude<=3 then return true end

            local TravelMode=tostring(Mode or "Smooth Tween")
            Runtime.ActiveSmartRouteGame=nil
            Runtime.ActiveTravelWaypoints=nil
            Runtime.ActiveTravelWaypointIndex=nil
            Runtime.ProfileSmartRoute.LastGame=Kind
            Runtime.ProfileSmartRoute.LastWaypoints=0
            Runtime.ProfileSmartRoute.LastAt=os.clock()

            if TravelMode=="Walk" then
                Runtime.ProfileSmartRoute.LastStatus="Walk • obstacle-aware path"

                return Runtime.ProfileRouter.Direct(CF,"Walk",Provider,Source)
            end

            Runtime.ProfileSmartRoute.LastStatus="Direct "..TravelMode

            if TravelMode~="Teleport" and not Runtime.ProfileEntranceRouting
                and type(Runtime.TryProfileEntrance)=="function" then
                local OkEntrance,Used=pcall(Runtime.TryProfileEntrance,CF,TravelMode)
                if not OkEntrance and tostring(Used):find("BANANI_CANCELLED",1,true) then error(Used,0) end
                if OkEntrance and Used then
                    local After=Root()
                    if After and (After.Position-CF.Position).Magnitude<=3 then return true end
                end
            end
            return Runtime.ProfileRouter.Direct(CF,TravelMode,Provider,Source)
        end

        function Runtime.ProfileRouter.Travel(CF,Provider,Options)
            Runtime.Movement.Guard()
            if typeof(CF)~="CFrame" then return false end
            Options=type(Options)=="table" and Options or {}
            local Existing=Root()
            if Existing and (Existing.Position-CF.Position).Magnitude<=3 then return true end
            Runtime.TweenSpeed=math.clamp(tonumber(Options.Speed or State.ProfileTweenSpeed) or 140,35,500)
            local Mode=tostring(Options.Mode or State.ProfileTravelMode or "Smooth Tween")
            if Kind=="BloxFruits" then
                Mode="Smooth Tween"; State.ProfileTravelMode="Smooth Tween"
            elseif Mode~="Smooth Tween" and Mode~="Tween" and Mode~="Underground Tween" and Mode~="Walk" then
                Mode="Teleport"
            end

            if Runtime.TravelToCFrame and Kind=="BloxFruits" then

                local TravelRoot=Root()
                local TravelDistance=TravelRoot and (TravelRoot.Position-CF.Position).Magnitude or 0
                if TravelRoot and TravelDistance>220 and not Runtime.BloxRoutingEntrance
                    and type(BloxSmartEntranceTravel)=="function" then
                    local Routed=false
                    local OkRoute,RouteResult=pcall(function()
                        return BloxSmartEntranceTravel(CF.Position,"Profile")
                    end)
                    if not OkRoute and tostring(RouteResult):find("BANANI_CANCELLED",1,true) then error(RouteResult,0) end
                    Routed=OkRoute and RouteResult==true
                    if Routed then
                        TravelRoot=Root()
                        TravelDistance=TravelRoot and (TravelRoot.Position-CF.Position).Magnitude or TravelDistance
                        if TravelRoot and TravelDistance<=3 then return true end
                    end
                end
                if TravelRoot and TravelDistance>90 then
                    local CruiseY=math.max(TravelRoot.Position.Y,CF.Position.Y,85)
                    local Lift=CFrame.new(TravelRoot.Position.X,CruiseY,TravelRoot.Position.Z)*TravelRoot.CFrame.Rotation
                    local Across=CFrame.new(CF.Position.X,CruiseY,CF.Position.Z)*CF.Rotation
                    if TravelRoot.Position.Y<CruiseY-3 and not Runtime.ProfileRouter.Direct(Lift,Mode,nil,"GameProfileWaterSafe") then return false end
                    if not Runtime.ProfileRouter.Direct(Across,Mode,nil,"GameProfileWaterSafe") then return false end
                    if type(Provider)=="function" then
                        local OkDynamic,Dynamic=pcall(Provider)
                        if OkDynamic and typeof(Dynamic)=="CFrame" then CF=Dynamic end
                    end
                end
                return Runtime.ProfileRouter.Direct(CF,Mode,Provider,Options.Source or "GameProfile")
            end

            if Runtime.TravelToCFrame then
                return Runtime.ProfileRouter.Generic(CF,Mode,Provider,Options.Source or "GameProfile")
            end
            local Ok=pcall(function() SafeTeleport(CF) end)
            return Ok
        end

        Runtime.ProfileSmartTravel=function(CF,Provider,Options)
            return Runtime.ProfileRouter.Travel(CF,Provider,Options)
        end
        local function ProfileTravelToCFrame(CF,Provider)
            return Runtime.ProfileSmartTravel(CF,Provider,nil)
        end

        Runtime.Entrances=Runtime.Entrances or {Cooldowns={}}
        Runtime.EnterThrough=function(Key,Door,Outside,Action,ExpectedExit)
            Runtime.Movement.Guard()
            local E=Runtime.Entrances
            local Now=os.clock()
            if Now<(E.Cooldowns[Key] or 0) then return false end
            local Part=GetRoot(Door)
            if not Part or not Outside then return false end
            local function Status(Text)
                if Runtime.Movement and Runtime.Movement.SetState then Runtime.Movement.SetState("Door",Text,tostring(Key)) end
            end
            Status("Approaching entrance")
            if not ProfileTravelToCFrame(Outside) then return false end
            Runtime.Movement.Guard()
            Part=GetRoot(Door)
            local Me=Root()
            if not Part or not Me then return false end
            local Before=Me.Position
            local Map=workspace:FindFirstChild("Interiors") or workspace:FindFirstChild("Interior") or workspace:FindFirstChild("Map")
            local Children={}
            local InteriorMap=Map and (Map.Name=="Interiors" or Map.Name=="Interior")
            if InteriorMap then for _,Child in ipairs(Map:GetChildren()) do Children[Child]=true end end
            local function Changed()
                local R=Root()
                if not R then return false end
                if typeof(ExpectedExit)=="Vector3" then
                    return (R.Position-Before).Magnitude>35 and (R.Position-ExpectedExit).Magnitude<250
                end
                if not Door.Parent then return true end
                if (R.Position-Before).Magnitude>35 then return true end
                if Map and (not Map.Parent or Map~=(workspace:FindFirstChild("Interiors") or workspace:FindFirstChild("Interior") or workspace:FindFirstChild("Map"))) then return true end
                if InteriorMap and (R.Position-Before).Magnitude>3 then
                    for Child in pairs(Children) do if Child.Parent~=Map then return true end end
                    for _,Child in ipairs(Map:GetChildren()) do if not Children[Child] then return true end end
                end
                return false
            end
            E.Cooldowns[Key]=os.clock()+2
            local Direction=Part.Position-Before
            if Direction.Magnitude<0.1 then Direction=Part.CFrame.LookVector end
            Direction=Direction.Unit
            local function FireDoorPrompt()
                local Prompt=Door:FindFirstChildWhichIsA("ProximityPrompt",true)
                if Prompt and type(fireproximityprompt)=="function" then pcall(function() fireproximityprompt(Prompt) end) end
                local Click=Door:FindFirstChildWhichIsA("ClickDetector",true)
                if Click and type(fireclickdetector)=="function" then pcall(function() fireclickdetector(Click) end) end
            end
            -- Attempt 1 crosses from the detected outside. Attempt 2 deliberately backs up and
            -- approaches from the opposite/alternate side, which fixes many one-way door triggers.
            for Attempt=1,2 do
                Runtime.Movement.Guard()
                Status(Attempt==1 and "Door detected • crossing" or "Door retry • alternate approach")
                Part=GetRoot(Door)
                Me=Root()
                if not Part or not Me then return false end
                local Sign=(Attempt==1) and 1 or -1
                local Through=CFrame.new(Part.Position+Direction*(4*Sign))
                if Attempt==2 then
                    local Back=CFrame.lookAt(Part.Position-Direction*7,Part.Position)
                    Runtime.ProfileRouter.Direct(Back,"Walk",nil,"EntranceBackup")
                    task.wait(0.08)
                end
                FireDoorPrompt()
                if not Changed() then
                    Runtime.ProfileRouter.Direct(Through,"Walk",function()
                        local R=Root()
                        if Changed() and R then return R.CFrame end
                        local Live=GetRoot(Door)
                        return Live and CFrame.new(Live.Position+Direction*(4*Sign)) or Through
                    end,"EntranceCross")
                end
                if not Changed() and Action then pcall(Action) end
                local Deadline=os.clock()+3.25
                repeat
                    Runtime.Movement.Guard()
                    if Changed() then
                        task.wait(0.35)
                        Runtime.Movement.Guard()
                        E.Cooldowns[Key]=os.clock()+5
                        if Runtime.RefreshProfileWorldCache then Runtime.RefreshProfileWorldCache() end
                        Status("Door transition confirmed")
                        return true
                    end
                    task.wait(0.08)
                until os.clock()>=Deadline
            end
            E.Cooldowns[Key]=os.clock()+1
            Status("Door transition not confirmed")
            return false
        end

        Runtime.TryProfileEntrance=function(TargetCF,TravelMode)
            if Kind=="BloxFruits" or Runtime.ProfileEntranceRouting then return false end
            if typeof(TargetCF)~="CFrame" then return false end
            local Me=Root()
            if not Me then return false end
            local Direct=(Me.Position-TargetCF.Position).Magnitude
            if Direct<70 then return false end

            local RayParams=RaycastParams.new()
            RayParams.FilterType=Enum.RaycastFilterType.Exclude
            RayParams.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
            RayParams.IgnoreWater=true
            local Hit=workspace:Raycast(Me.Position,TargetCF.Position-Me.Position,RayParams)
            if not Hit then return false end

            local Best,BestGoal,BestScore=nil,nil,math.huge
            local Objects=type(Runtime.ProfileObjects)=="function" and Runtime.ProfileObjects() or {}
            for _,Obj in ipairs(Objects) do
                if Obj and Obj.Parent then
                    local Lower=string.lower(tostring(Obj.Name))
                    local LooksLikeEntrance=Lower:find("door",1,true) or Lower:find("gate",1,true)
                        or Lower:find("entrance",1,true) or Lower:find("portal",1,true)
                        or Lower:find("elevator",1,true) or Lower:find("teleport",1,true)
                        or Lower:find("exit",1,true) or Lower:find("transition",1,true)
                        or Lower:find("hatch",1,true) or Lower:find("doorway",1,true)
                    if LooksLikeEntrance then
                        local Part=GetRoot(Obj)
                        if Part then
                            local Goal=Obj:GetAttribute("Destination") or Obj:GetAttribute("TargetPosition")
                                or Obj:GetAttribute("TeleportTo") or Obj:GetAttribute("ExitPosition")
                            for _,KeyName in ipairs({"Destination","TargetPosition","TeleportTo","ExitPosition","Exit"}) do
                                local Value=Obj:FindFirstChild(KeyName,true)
                                if Value and (Value:IsA("Vector3Value") or Value:IsA("CFrameValue")) then Goal=Value.Value end
                                if Value and Value:IsA("ObjectValue") and Value.Value then
                                    local ExitPart=GetRoot(Value.Value)
                                    if ExitPart then Goal=ExitPart.Position end
                                end
                            end
                            if typeof(Goal)=="CFrame" then Goal=Goal.Position end
                            local ToTarget=(Part.Position-TargetCF.Position).Magnitude
                            local ToDoor=(Me.Position-Part.Position).Magnitude
                            local Score=nil
                            if typeof(Goal)=="Vector3" and (Goal-TargetCF.Position).Magnitude<180 then
                                Score=ToDoor+(Goal-TargetCF.Position).Magnitude
                            elseif ToTarget<55 then
                                Score=ToDoor+ToTarget+20
                            end
                            if Score then
                                if Obj:FindFirstChildWhichIsA("ProximityPrompt",true) then Score-=18 end
                                if Obj:FindFirstChildWhichIsA("ClickDetector",true) then Score-=10 end
                                if Obj:FindFirstChildWhichIsA("TouchTransmitter",true) then Score-=8 end
                            end
                            if Score and Score+20<Direct and Score<BestScore then
                                Best,BestGoal,BestScore=Obj,Goal,Score
                            end
                        end
                    end
                end
            end
            if not Best then return false end
            local Part=GetRoot(Best)
            if not Part then return false end
            local Away=Me.Position-Part.Position
            if Away.Magnitude<0.1 then Away=Part.CFrame.LookVector end
            local Outside=CFrame.lookAt(Part.Position+Away.Unit*5,Part.Position)

            Runtime.ProfileEntranceRouting=true
            local Ok,Used=pcall(function()
                return Runtime.EnterThrough(
                    "Profile:"..tostring(Kind)..":"..tostring(Best:GetFullName()),
                    Best,Outside,nil,BestGoal
                )
            end)
            Runtime.ProfileEntranceRouting=false
            if not Ok then
                if tostring(Used):find("BANANI_CANCELLED",1,true) then error(Used,0) end
                return false
            end
            if Used then
                Runtime.ProfileSmartRoute.LastStatus="Direct "..tostring(TravelMode).." • entrance shortcut"
                return true
            end
            return false
        end

        local function MoveTo(Object, Offset)
            local Target = GetRoot(Object)
            if not Target then return false end
            local CF = Target.CFrame * (Offset or CFrame.new(0,3,0))
            return ProfileTravelToCFrame(CF, function()
                local R = GetRoot(Object)
                return R and (R.CFrame * (Offset or CFrame.new(0,3,0))) or nil
            end)
        end
        local function TouchObject(Object)
            local Target = GetRoot(Object)
            local Me = Root()
            if not Target or not Me then return false end
            pcall(function() ProfileTravelToCFrame(Target.CFrame * CFrame.new(0,1.5,0)) end)
            if type(firetouchinterest) == "function" then
                pcall(function()
                    firetouchinterest(Me, Target, 0)
                    task.wait()
                    firetouchinterest(Me, Target, 1)
                end)
            end
            local Prompt = Object:FindFirstChildWhichIsA("ProximityPrompt", true)
            if Prompt and type(fireproximityprompt) == "function" then
                pcall(function() fireproximityprompt(Prompt) end)
            end
            return true
        end
        local function CallRemote(Remote, ...)
            Runtime.Movement.Guard()
            if not Remote then return false end
            local Args = table.pack(...)
            local Ok,Result = pcall(function()
                if Remote:IsA("RemoteFunction") then
                    return Remote:InvokeServer(table.unpack(Args,1,Args.n))
                elseif Remote:IsA("RemoteEvent") then
                    Remote:FireServer(table.unpack(Args,1,Args.n))
                    return true
                else
                    error("Unsupported remote type")
                end
            end)
            if not Ok or Result==false then return false,Result end
            return true,Result
        end
        local function PressKey(Key, Hold)
            Runtime.Movement.Guard()
            local Code = typeof(Key)=="EnumItem" and Key or Enum.KeyCode[tostring(Key or "E")]
            if not Code then return false end
            local Duration = math.max(tonumber(Hold) or 0.035,0.01)
            local Ok,VIM = pcall(function() return game:GetService("VirtualInputManager") end)
            if Ok and VIM then
                return pcall(function()
                    VIM:SendKeyEvent(true,Code,false,game)
                    task.wait(Duration)
                    VIM:SendKeyEvent(false,Code,false,game)
                end)
            end
            if type(keypress)=="function" and type(keyrelease)=="function" then
                return pcall(function()
                    keypress(Code.Value)
                    task.wait(Duration)
                    keyrelease(Code.Value)
                end)
            end
            return false
        end
        local function TextOfGui(Gui)
            local Pieces={tostring(Gui.Name or "")}
            if Gui:IsA("TextButton") or Gui:IsA("TextLabel") or Gui:IsA("TextBox") then
                table.insert(Pieces,tostring(Gui.Text or ""))
            end
            return string.lower(table.concat(Pieces," "))
        end
        local function ActivateVisibleGui(Keywords)
            local PG=Player:FindFirstChildOfClass("PlayerGui")
            if not PG then return false end
            local Terms={}
            for _,K in ipairs(Keywords or {}) do table.insert(Terms,string.lower(tostring(K))) end
            for _,Gui in ipairs(PG:GetDescendants()) do
                if Gui:IsA("GuiButton") and Gui.Visible then
                    local Txt=TextOfGui(Gui)
                    local Match=false
                    for _,K in ipairs(Terms) do if string.find(Txt,K,1,true) then Match=true break end end
                    if Match then
                        if type(firesignal)=="function" then
                            local Fired=pcall(function() firesignal(Gui.Activated) end)
                            if not Fired then Fired=pcall(function() firesignal(Gui.MouseButton1Click) end) end
                            if Fired then return true end
                        end
                        local Ok,VIM=pcall(function() return game:GetService("VirtualInputManager") end)
                        if Ok and VIM then
                            local P=Gui.AbsolutePosition+Gui.AbsoluteSize/2
                            local Clicked=pcall(function()
                                VIM:SendMouseButtonEvent(P.X,P.Y,0,true,game,0)
                                task.wait(0.03)
                                VIM:SendMouseButtonEvent(P.X,P.Y,0,false,game,0)
                            end)
                            if Clicked then return true end
                        end
                    end
                end
            end
            return false
        end
        local function MatchKeywords(Text,Keywords)
            local L=string.lower(tostring(Text or ""))
            for _,K in ipairs(Keywords or {}) do
                if string.find(L,string.lower(tostring(K)),1,true) then return true end
            end
            return false
        end
        Runtime.ProfileWorldCache=Runtime.ProfileWorldCache or {
            Objects={},Index=setmetatable({}, {__mode="k"}),
            Prompts={},PromptIndex=setmetatable({}, {__mode="k"}),
            Targets={},TargetIndex=setmetatable({}, {__mode="k"}),
            Ready=false,Bound=false
        }
        local function ProfileCacheInsert(List,IndexMap,Object)
            if IndexMap[Object] then return end
            local Index=#List+1
            List[Index]=Object
            IndexMap[Object]=Index
        end
        local function ProfileCacheRemove(List,IndexMap,Object)
            local Index=IndexMap[Object]
            if not Index then return end
            local LastIndex=#List
            local LastObject=List[LastIndex]
            List[Index]=LastObject
            List[LastIndex]=nil
            IndexMap[Object]=nil
            if LastObject and LastObject~=Object then IndexMap[LastObject]=Index end
        end
        local function AddProfileWorldObject(Cache,Object)
            if not Object then return end
            ProfileCacheInsert(Cache.Objects,Cache.Index,Object)
            if Object:IsA("ProximityPrompt") then
                ProfileCacheInsert(Cache.Prompts,Cache.PromptIndex,Object)
            end
            if Object:IsA("Model") or Object:IsA("BasePart") then
                ProfileCacheInsert(Cache.Targets,Cache.TargetIndex,Object)
            end
        end
        local function RemoveProfileWorldObject(Cache,Object)
            if not Object then return end
            ProfileCacheRemove(Cache.Objects,Cache.Index,Object)
            ProfileCacheRemove(Cache.Prompts,Cache.PromptIndex,Object)
            ProfileCacheRemove(Cache.Targets,Cache.TargetIndex,Object)
        end
        local function RebuildProfileWorldCache(Cache)
            Cache=Cache or Runtime.ProfileWorldCache
            Cache.Objects={}
            Cache.Index=setmetatable({}, {__mode="k"})
            Cache.Prompts={}
            Cache.PromptIndex=setmetatable({}, {__mode="k"})
            Cache.Targets={}
            Cache.TargetIndex=setmetatable({}, {__mode="k"})
            for _,Object in ipairs(workspace:GetDescendants()) do AddProfileWorldObject(Cache,Object) end
            Cache.Ready=true
            Cache.LastRebuildAt=os.clock()
            return Cache
        end
        local function EnsureProfileWorldCache()
            local Cache=Runtime.ProfileWorldCache
            if not Cache then
                Cache={
                    Objects={},Index=setmetatable({}, {__mode="k"}),
                    Prompts={},PromptIndex=setmetatable({}, {__mode="k"}),
                    Targets={},TargetIndex=setmetatable({}, {__mode="k"}),
                    Ready=false,Bound=false
                }
                Runtime.ProfileWorldCache=Cache
            end
            if not Cache.Ready then RebuildProfileWorldCache(Cache) end
            if not Cache.Bound then
                Cache.Bound=true
                TrackConnection(workspace.DescendantAdded:Connect(function(Object)
                    if Unloaded or not Cache.Ready then return end
                    AddProfileWorldObject(Cache,Object)
                end))
                TrackConnection(workspace.DescendantRemoving:Connect(function(Object)
                    if not Cache.Ready then return end
                    RemoveProfileWorldObject(Cache,Object)
                end))
            end
            return Cache
        end
        Runtime.RefreshProfileWorldCache=function()
            return RebuildProfileWorldCache(EnsureProfileWorldCache()).Objects
        end
        Runtime.ProfileObjects=function() return EnsureProfileWorldCache().Objects end
        Runtime.ProfilePrompts=function() return EnsureProfileWorldCache().Prompts end
        Runtime.ProfileTargets=function() return EnsureProfileWorldCache().Targets end
        local function FindPromptByKeywords(Keywords)
            local Me=Root(); local Best,BestDist=nil,math.huge
            local Scanned=0
            for _,Obj in ipairs(Runtime.ProfilePrompts()) do
                Scanned+=1; if Scanned>6000 then break end
                if Obj:IsA("ProximityPrompt") then
                    local Owner=Obj.Parent
                    local Model=Owner and Owner:FindFirstAncestorOfClass("Model")
                    if not (Model and IsPlayerCharacter(Model)) then
                        local S=tostring(Obj.Name).." "..tostring(Obj.ActionText).." "..tostring(Obj.ObjectText).." "..tostring(Owner and Owner.Name or "")
                        if MatchKeywords(S,Keywords) then
                            local R=GetRoot(Owner)
                            local D=(Me and R) and (Me.Position-R.Position).Magnitude or 0
                            if D<BestDist then Best,BestDist=Obj,D end
                        end
                    end
                end
            end
            return Best
        end
        local function UsePrompt(Prompt, MoveFirst)
            Runtime.Movement.Guard()
            if not Prompt or not Prompt.Parent then return false end
            if MoveFirst ~= false then
                local R=GetRoot(Prompt.Parent)
                if R and not ProfileTravelToCFrame(R.CFrame*CFrame.new(0,2,2)) then return false end
            end
            Runtime.Movement.Guard()
            if type(fireproximityprompt)=="function" then
                return pcall(function() fireproximityprompt(Prompt) end)
            end
            return false
        end
        local function FindWorldTarget(Keywords)
            local Objects=Runtime.ProfileTargets()
            local Me=Root(); local Best,BestDist=nil,math.huge; local Scanned=0
            for _,Obj in ipairs(Objects) do
                Scanned+=1; if Scanned>18000 then break end
                if (Obj:IsA("Model") or Obj:IsA("BasePart")) and MatchKeywords(Obj.Name,Keywords) then
                    local M=Obj:IsA("Model") and Obj or Obj:FindFirstAncestorOfClass("Model")
                    if not (M and IsPlayerCharacter(M)) then
                        local R=GetRoot(Obj)
                        if R then
                            local D=Me and (Me.Position-R.Position).Magnitude or 0
                            if D<BestDist then Best,BestDist=Obj,D end
                        end
                    end
                end
            end
            return Best
        end
        local function ToolMatches(Tool, Filter)
            if not Tool or not Tool:IsA("Tool") then return false end
            if not Filter or Filter == "" or Filter == "Any Tool" or Filter == "Any Rod" then return true end
            return string.find(string.lower(Tool.Name), string.lower(tostring(Filter)), 1, true) ~= nil
        end
        local function ToolNames(RodsOnly)
            local Names, Seen = {RodsOnly and "Any Rod" or "Any Tool"}, {}
            Seen[Names[1]] = true
            for _,Container in ipairs({Character(), Player:FindFirstChildOfClass("Backpack")}) do
                if Container then
                    for _,Tool in ipairs(Container:GetChildren()) do
                        if Tool:IsA("Tool") then
                            local IsRod = string.find(string.lower(Tool.Name), "rod", 1, true) ~= nil
                                or (Tool:FindFirstChild("events") and Tool.events:FindFirstChild("cast"))
                            if (not RodsOnly or IsRod) and not Seen[Tool.Name] then
                                Seen[Tool.Name] = true
                                table.insert(Names, Tool.Name)
                            end
                        end
                    end
                end
            end
            table.sort(Names,function(A,B)
                if A == B then return false end
                if A == "Any Tool" or A == "Any Rod" then return true end
                if B == "Any Tool" or B == "Any Rod" then return false end
                return string.lower(A) < string.lower(B)
            end)
            return Names
        end
        local function EquipTool(Filter, RodsOnly)
            local C, H, BP = Character(), Humanoid(), Player:FindFirstChildOfClass("Backpack")
            if not C or not H then return nil end
            local Current = C:FindFirstChildOfClass("Tool")
            if Current and ToolMatches(Current,Filter) then
                if not RodsOnly or string.find(string.lower(Current.Name),"rod",1,true) or (Current:FindFirstChild("events") and Current.events:FindFirstChild("cast")) then
                    return Current
                end
            end
            if BP then
                for _,Tool in ipairs(BP:GetChildren()) do
                    local IsRod = string.find(string.lower(Tool.Name),"rod",1,true) ~= nil
                        or (Tool:FindFirstChild("events") and Tool.events:FindFirstChild("cast"))
                    if ToolMatches(Tool,Filter) and (not RodsOnly or IsRod) then
                        pcall(function() H:EquipTool(Tool) end)
                        return Tool
                    end
                end
            end
            return nil
        end
        local function UseTool(Filter)
            local Tool = EquipTool(Filter,false)
            if Tool then pcall(function() Tool:Activate() end) end
            return Tool
        end
        local function CandidateEnemyFolders()
            local Result = {}
            for _,Name in ipairs({"Enemies","NPCs","Mobs","Characters"}) do
                local Folder = workspace:FindFirstChild(Name)
                if Folder then table.insert(Result,Folder) end
            end
            return Result
        end
        local function GetEnemies()
            local Out,Seen = {},{}
            local function Add(Obj)
                if not Obj or Seen[Obj] or not Obj:IsA("Model") then return end
                if Obj == Character() or IsPlayerCharacter(Obj) then return end
                local H=Obj:FindFirstChildOfClass("Humanoid")
                if not H then return end
                Seen[Obj]=true
                table.insert(Out,Obj)
            end
            for _,Folder in ipairs(CandidateEnemyFolders()) do
                for _,Obj in ipairs(Folder:GetChildren()) do Add(Obj) end

                for _,Obj in ipairs(Folder:GetDescendants()) do
                    if Obj:IsA("Model") and Obj:FindFirstChildOfClass("Humanoid") then Add(Obj) end
                end
            end
            if #Out == 0 then
                local Scanned=0
                for _,Obj in ipairs(Runtime.ProfileTargets()) do
                    Scanned+=1; if Scanned>16000 then break end
                    if Obj:IsA("Model") and Obj:FindFirstChildOfClass("Humanoid") then Add(Obj) end
                end
            end
            return Out
        end
        local function EnemyNames(BossOnly)
            local First = BossOnly and "Nearest Boss" or "Nearest Any"
            local Names,Seen={First},{[First]=true}
            for _,M in ipairs(GetEnemies()) do
                local H=M:FindFirstChildOfClass("Humanoid")
                local IsBoss = string.find(string.lower(M.Name),"boss",1,true) ~= nil or (H and H.MaxHealth >= 50000)
                if (not BossOnly or IsBoss) and not Seen[M.Name] then
                    Seen[M.Name]=true
                    table.insert(Names,M.Name)
                end
            end
            table.sort(Names,function(A,B)
                if A==B then return false end
                if A==First then return true end
                if B==First then return false end
                return string.lower(A)<string.lower(B)
            end)
            return Names
        end
        local function NearestEnemy(Filter, BossOnly)
            local Me=Root()
            if not Me then return nil end
            local Best,Dist=nil,math.huge
            local F=string.lower(tostring(Filter or (BossOnly and "Nearest Boss" or "Nearest Any")))
            for _,M in ipairs(GetEnemies()) do
                local H=M:FindFirstChildOfClass("Humanoid")
                local R=GetRoot(M)
                local IsBoss=string.find(string.lower(M.Name),"boss",1,true)~=nil or (H and H.MaxHealth>=50000)
                local Any=(F=="nearest any" or F=="any" or F=="nearest boss")
                local Match=Any or string.find(string.lower(M.Name),F,1,true)~=nil
                if H and H.Health>0 and R and Match and (not BossOnly or IsBoss) then
                    local D=(Me.Position-R.Position).Magnitude
                    if D<Dist then Best,Dist=M,D end
                end
            end
            return Best
        end
        local function FarmEnemy(Enemy, ToolFilter, Height, Back)
            if not Enemy then return false end
            local R=GetRoot(Enemy)
            if not R then return false end
            pcall(function() ProfileTravelToCFrame(R.CFrame*CFrame.new(0,tonumber(Height) or 5,tonumber(Back) or 4),function()
                local NR=GetRoot(Enemy); return NR and NR.CFrame*CFrame.new(0,tonumber(Height) or 5,tonumber(Back) or 4) or R.CFrame
            end) end)
            UseTool(ToolFilter)
            return true
        end

        Runtime.ProfileIgnoredPlayers={}
        Runtime.ProfileSetIgnoredPlayers=function(Text)
            local Names={}
            for Name in tostring(Text or ""):gmatch("[^,;\n]+") do
                Name=Name:match("^%s*(.-)%s*$"):gsub("^@",""):lower()
                if Name~="" then Names[Name]=true end
            end
            Runtime.ProfileIgnoredPlayers=Names
        end
        Runtime.ProfilePlayerIgnored=function(P)
            return P and Runtime.ProfileIgnoredPlayers[string.lower(P.Name)]==true
        end
        Runtime.ProfileAimAllowed=function(Prefix)
            if UserInputService:GetFocusedTextBox() then return false end
            return not State[Prefix.."HoldAim"] or UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
        end
        Runtime.ProfileAimPosition=function(Prefix,Part)
            if not Part then return nil end
            if not State[Prefix.."Prediction"] then return Part.Position end
            return Part.Position+Part.AssemblyLinearVelocity*math.clamp(tonumber(State[Prefix.."LeadTime"]) or 0.1,0,0.5)
        end
        Runtime.ProfileAimClear=function()
            StopLoop("ProfileAimVisuals")
            if Runtime.ProfileAimGui then Runtime.ProfileAimGui:Destroy(); Runtime.ProfileAimGui=nil end
        end
        Runtime.ProfileAimOptions=function(Host,Prefix,Target,Center)
            State[Prefix.."HoldAim"]=false
            State[Prefix.."Prediction"]=false
            State[Prefix.."DrawFOV"]=false
            State[Prefix.."TargetLine"]=false
            local LastTarget,LastScan=nil,-math.huge
            local function Update()
                if not State[Prefix.."DrawFOV"] and not State[Prefix.."TargetLine"] then Runtime.ProfileAimClear(); return end
                if not Runtime.ProfileAimGui then
                    local Parent=Player:FindFirstChildOfClass("PlayerGui")
                    if not Parent then return end
                    local Gui=Instance.new("ScreenGui")
                    Gui.Name="BananiAimGuide"; Gui.ResetOnSpawn=false; Gui.IgnoreGuiInset=true; Gui.DisplayOrder=50
                    local Circle=Instance.new("Frame")
                    Circle.Name="Circle"; Circle.BackgroundTransparency=1; Circle.AnchorPoint=Vector2.new(0.5,0.5); Circle.Parent=Gui
                    local Round=Instance.new("UICorner"); Round.CornerRadius=UDim.new(1,0); Round.Parent=Circle
                    local Border=Instance.new("UIStroke"); Border.Color=Color3.fromRGB(255,215,70); Border.Thickness=1; Border.Parent=Circle
                    local Line=Instance.new("Frame")
                    Line.Name="Line"; Line.AnchorPoint=Vector2.new(0.5,0.5); Line.BorderSizePixel=0; Line.BackgroundColor3=Color3.fromRGB(255,215,70); Line.Parent=Gui
                    Gui.Parent=Parent; Runtime.ProfileAimGui=Gui
                end
                local Gui=Runtime.ProfileAimGui
                local Cam=workspace.CurrentCamera
                if not Cam then Gui.Enabled=false; return end
                Gui.Enabled=true
                local Origin=Center(Cam)
                local Circle=Gui.Circle
                local Radius=tonumber(State[Prefix.."FOV"]) or 170
                Circle.Visible=State[Prefix.."DrawFOV"]==true
                Circle.Position=UDim2.fromOffset(Origin.X,Origin.Y); Circle.Size=UDim2.fromOffset(Radius*2,Radius*2)
                local Line=Gui.Line
                Line.Visible=false
                if State[Prefix.."TargetLine"] then
                    if os.clock()-LastScan>=0.5 then LastTarget=Target(); LastScan=os.clock() end
                    local Part=LastTarget
                    if Part and Part.Parent then
                        local Point,Visible=Cam:WorldToViewportPoint(Part.Position)
                        if Visible and Point.Z>0 then
                            local End=Vector2.new(Point.X,Point.Y)
                            local Delta=End-Origin
                            Line.Position=UDim2.fromOffset((Origin.X+End.X)/2,(Origin.Y+End.Y)/2)
                            Line.Size=UDim2.fromOffset(Delta.Magnitude,1)
                            Line.Rotation=math.deg(math.atan2(Delta.Y,Delta.X)); Line.Visible=true
                        end
                    end
                end
            end
            local function Refresh()
                LastTarget=nil; LastScan=-math.huge
                Runtime.ProfileAimClear()
                if State[Prefix.."DrawFOV"] or State[Prefix.."TargetLine"] then StartLoop("ProfileAimVisuals",Update,0.05) end
            end
            Host:CreateToggle({Name="Hold Right Mouse to Aim",Flag="GameProfile_"..Prefix.."_HoldAim",CurrentValue=false,Callback=function(V) State[Prefix.."HoldAim"]=V end})
            Host:CreateToggle({Name="Movement Prediction",Flag="GameProfile_"..Prefix.."_Prediction",CurrentValue=false,Callback=function(V) State[Prefix.."Prediction"]=V end})
            Host:CreateSlider({Name="Prediction Lead",Flag="GameProfile_"..Prefix.."_LeadTime",Range={0,0.5},Increment=0.01,Suffix=" s",CurrentValue=0.1,Callback=function(V) State[Prefix.."LeadTime"]=V end})
            Host:CreateToggle({Name="Show Aim FOV",Flag="GameProfile_"..Prefix.."_DrawFOV",CurrentValue=false,Callback=function(V) State[Prefix.."DrawFOV"]=V; Refresh() end})
            Host:CreateToggle({Name="Show Target Line",Flag="GameProfile_"..Prefix.."_TargetLine",CurrentValue=false,Callback=function(V) State[Prefix.."TargetLine"]=V; Refresh() end})
            Host:CreateInput({Name="Ignore Usernames",Flag="GameProfile_"..Prefix.."_Ignored",PlaceholderText="username1, username2",RemoveTextAfterFocusLost=false,Callback=Runtime.ProfileSetIgnoredPlayers})
        end
