            local BloxBossFallbackCFrames={
                ["Diamond"]=CFrame.new(-1576.7167,198.5927,13.7243),
                ["Jeremy"]=CFrame.new(2006.9261,448.9567,853.9828),
                ["Fajita"]=CFrame.new(-2172.7400,103.3222,-4015.0254),
                ["Orbitus"]=CFrame.new(-2172.7400,103.3222,-4015.0254),
                ["Don Swan"]=CFrame.new(2286.2004,15.1778,863.8389),
                ["Smoke Admiral"]=CFrame.new(-5275.1987,20.7573,-5260.6670),
                ["Awakened Ice Admiral"]=CFrame.new(6403.5439,340.2977,-6894.5596),
