            local BossAliasLookup={}
            for _,Display in ipairs(BloxBossOrder) do
                BloxBossAliases[Display]=BloxBossAliases[Display] or {Display}
            end
            for Display,Aliases in pairs(BloxBossAliases) do
                BossAliasLookup[NormalName(Display)]=Display
                for _,Alias in ipairs(Aliases) do BossAliasLookup[NormalName(Alias)]=Display end
            end
            local function BossDisplayForName(Name)
                local Raw=tostring(Name or "")
                local Direct=BossAliasLookup[NormalName(Raw)]
                if Direct then return Direct end
                local Lower=string.lower(Raw)
                if string.find(Lower,"[boss]",1,true) or string.find(Lower,"[raid boss]",1,true)
                    or string.find(Lower,"[dungeon boss]",1,true) then
                    return StripEnemyName(Raw)
                end
                return nil
            end
            local function IsBossObject(Obj)
                if not Obj then return false end
                if Obj:GetAttribute("IsBoss")==true or Obj:GetAttribute("Boss")==true then return true end
                return BossDisplayForName(Obj.Name)~=nil
            end

            local BloxEnemySnapshotState={Entries={},At=0}
            local function BloxLiveEnemies(Force)
                local Now=os.clock()

                if not Force and Now-BloxEnemySnapshotState.At<0.15 then
                    return BloxEnemySnapshotState.Entries
                end
                local Out,Seen={},{}
                local Folder=workspace:FindFirstChild("Enemies")
                if not Folder then
                    BloxEnemySnapshotState.Entries={}
                    BloxEnemySnapshotState.At=Now
                    return BloxEnemySnapshotState.Entries
                end
                local function Add(Obj)
                    if not Obj or Seen[Obj] or not Obj:IsA("Model") then return end
                    if IsPlayerCharacter(Obj) then return end
                    local H=Obj:FindFirstChildOfClass("Humanoid")
                    local R=GetRoot(Obj)
                    if not H or not R then return end
                    Seen[Obj]=true
                    table.insert(Out,Obj)
                end
                for _,Obj in ipairs(Folder:GetChildren()) do Add(Obj) end
                for _,Obj in ipairs(Folder:GetDescendants()) do
                    if Obj:IsA("Model") and Obj:FindFirstChildOfClass("Humanoid") then Add(Obj) end
                end
                BloxEnemySnapshotState.Entries=Out
                BloxEnemySnapshotState.At=Now
                return BloxEnemySnapshotState.Entries
            end

            local function ClearBloxEnemyESP()
                for Model,Highlight in pairs(State.BloxEnemyHighlights or {}) do
                    if Highlight then pcall(function() Highlight:Destroy() end) end
                    State.BloxEnemyHighlights[Model]=nil
                end
            end
            local function RefreshBloxEnemyESP()
                local Live={}
                for _,Model in ipairs(BloxLiveEnemies()) do
                    local Hum=Model:FindFirstChildOfClass("Humanoid")
                    if Hum and Hum.Health>0 then
                        Live[Model]=true
                        local H=State.BloxEnemyHighlights[Model]
                        if not H or not H.Parent then
                            H=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
                            H.Name="BananiBloxEnemyESP"
                            H.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                            H.FillTransparency=0.80
                            H.OutlineTransparency=0.10
                            H.Parent=Model
                            State.BloxEnemyHighlights[Model]=H
                        end
                        local Boss=IsBossObject(Model)
                        H.FillColor=Boss and Color3.fromRGB(205,88,70) or Color3.fromRGB(201,177,42)
                        H.OutlineColor=Boss and Color3.fromRGB(244,143,108) or Color3.fromRGB(226,207,86)
                    end
                end
                for Model,H in pairs(State.BloxEnemyHighlights or {}) do
                    if not Live[Model] or not Model.Parent then
                        if H then pcall(function() H:Destroy() end) end
                        State.BloxEnemyHighlights[Model]=nil
                    end
                end
            end

            local function BloxGuide()
                local Module=ReplicatedStorage:FindFirstChild("GuideModule",true)
                if Module and not Module:IsA("ModuleScript") then
                    Module=Module:FindFirstChild("GuideModule",true) or Module:FindFirstChildWhichIsA("ModuleScript",true)
                end
                if not Module or not Module:IsA("ModuleScript") then return nil end
                local Ok,Guide=pcall(require,Module)
                return Ok and type(Guide)=="table" and Guide or nil
            end

            local BloxQuestCacheState={Entries={},At=0,Module=nil}
            local function ReadBloxQuests(Force)
                local QM=ReplicatedStorage:FindFirstChild("Quests",true)
                if QM and not QM:IsA("ModuleScript") then
                    QM=QM:FindFirstChild("Quests",true) or QM:FindFirstChildWhichIsA("ModuleScript",true)
                end
                if not QM or not QM:IsA("ModuleScript") then return {} end
                local Now=os.clock()
                if not Force and BloxQuestCacheState.Module==QM and Now-BloxQuestCacheState.At<12 then
                    return BloxQuestCacheState.Entries
                end
                local Ok,Quests=pcall(require,QM)
                if not Ok or type(Quests)~="table" then return BloxQuestCacheState.Entries end
                local Entries={}
                local function AddEntry(QuestName,QuestIndex,Q)
                    if type(Q)~="table" or type(Q.Task)~="table" then return end
                    local Req=tonumber(Q.LevelReq) or 0
                    for Mob,Amount in pairs(Q.Task) do
                        if type(Mob)=="string" then
                            local Display=StripEnemyName(Mob)
                            local Num=tonumber(Amount)
                            local Boss=(Num~=nil and Num<=1) or BossDisplayForName(Display)~=nil
                            table.insert(Entries,{
                                QuestName=tostring(QuestName),QuestIndex=QuestIndex,LevelReq=Req,
                                MobName=Display,RawMobName=tostring(Mob),DisplayName=tostring(Q.Name or Display),IsBoss=Boss,
                                RequiredAmount=Num
                            })
                        end
                    end
                end
                for QuestName,Pack in pairs(Quests) do
                    if type(Pack)=="table" then
                        if Pack.LevelReq and Pack.Task then
                            AddEntry(QuestName,1,Pack)
                        else
                            for QuestIndex,Q in pairs(Pack) do AddEntry(QuestName,QuestIndex,Q) end
                        end
                    end
                end
                table.sort(Entries,function(A,B)
                    if A.LevelReq==B.LevelReq then return NormalName(A.MobName)<NormalName(B.MobName) end
                    return A.LevelReq<B.LevelReq
                end)
                BloxQuestCacheState.Entries=Entries
                BloxQuestCacheState.At=Now
                BloxQuestCacheState.Module=QM
                return BloxQuestCacheState.Entries
            end

            local function BloxEnemyCatalog()
                local Out,Seen={"Nearest Enemy"},{[NormalName("Nearest Enemy")]=true}
                local Sea=BloxSeaNumber()
                for _,Name in ipairs(BloxEnemiesBySea[Sea] or BloxRegularEnemyFallback) do
                    AddUnique(Out,Seen,Name)
                end

                for _,Q in ipairs(ReadBloxQuests()) do
                    if not Q.IsBoss and QuestLevelBelongsToSea(Q.LevelReq) then AddUnique(Out,Seen,Q.MobName) end
                end

                for _,M in ipairs(BloxLiveEnemies()) do
                    if not IsBossObject(M) then AddUnique(Out,Seen,M.Name) end
                end
                return Out
            end
            local function BloxBossCatalog()
                local Out,Seen={"Nearest Boss"},{[NormalName("Nearest Boss")]=true}
                local Sea=BloxSeaNumber()
                for _,Name in ipairs(BloxBossesBySea[Sea] or {}) do AddUnique(Out,Seen,Name) end
                for _,Q in ipairs(ReadBloxQuests()) do
                    if Q.IsBoss and QuestLevelBelongsToSea(Q.LevelReq) then
                        AddUnique(Out,Seen,BossDisplayForName(Q.MobName) or Q.MobName)
                    end
                end
                for _,M in ipairs(BloxLiveEnemies()) do
                    local Display=BossDisplayForName(M.Name)
                    if Display or IsBossObject(M) then AddUnique(Out,Seen,Display or M.Name) end
                end
                return Out
            end

            local function TargetNameMatches(ModelName,Filter,BossOnly)
                local F=NormalName(Filter)
                if F=="" then return false end
                if (not BossOnly and (F=="nearest enemy" or F=="nearest any" or F=="any"))
                    or (BossOnly and F=="nearest boss") then return true end
                if BossOnly then
                    local WantedDisplay=BossDisplayForName(Filter) or StripEnemyName(Filter)
                    local ActualDisplay=BossDisplayForName(ModelName) or StripEnemyName(ModelName)
                    if NormalName(ActualDisplay)==NormalName(WantedDisplay) then return true end
                    local Aliases=BloxBossAliases[WantedDisplay]
                    if Aliases then
                        local N=NormalName(ModelName)
                        for _,Alias in ipairs(Aliases) do if NormalName(Alias)==N then return true end end
                    end
                    return false
                end

                local Actual=CompactEnemyName(ModelName)
                local Wanted=CompactEnemyName(Filter)
                if Actual=="posessedmummy" then Actual="possessedmummy" end
                if Wanted=="posessedmummy" then Wanted="possessedmummy" end
                if Actual==Wanted then return true end

                return false
            end

            local function NearestBloxEnemy(Filter,BossOnly,ForceRefresh)
                local Me=Root(); if not Me then return nil end
                local Best,Dist=nil,math.huge
                for _,M in ipairs(BloxLiveEnemies(ForceRefresh)) do
                    local H=M:FindFirstChildOfClass("Humanoid")
                    local R=GetRoot(M)
                    local Boss=IsBossObject(M)
                    local CorrectType=(BossOnly and Boss) or ((not BossOnly) and not Boss)
                    if H and H.Health>0 and R and CorrectType and TargetNameMatches(M.Name,Filter,BossOnly) then
                        local D=(Me.Position-R.Position).Magnitude
                        if D<Dist then Best,Dist=M,D end
                    end
                end
                return Best
            end

            local function FindBloxSpawn(Name)
                local Wanted={}
                local function AddWanted(V)
                    local K=CompactEnemyName(V)
                    if K~="" then Wanted[K]=true end
                end
                AddWanted(Name)
                local Display=BossDisplayForName(Name)
                local Aliases=Display and BloxBossAliases[Display] or BloxBossAliases[Name]
                if Aliases then for _,Alias in ipairs(Aliases) do AddWanted(Alias) end end
                local Containers={workspace:FindFirstChild("EnemySpawns")}
                local WO=workspace:FindFirstChild("_WorldOrigin")
                if WO then table.insert(Containers,WO:FindFirstChild("EnemySpawns")) end
                local Me=Root()
                local Best,BestDist=nil,math.huge
                local function Consider(Obj)
                    local R=GetRoot(Obj)
                    if not R then return end
                    local Candidates={Obj.Name}
                    for _,Attr in ipairs({"Enemy","EnemyName","Mob","MobName"}) do
                        local V=Obj:GetAttribute(Attr)
                        if type(V)=="string" then table.insert(Candidates,V) end
                    end
                    local Match=false
                    for _,Candidate in ipairs(Candidates) do
                        local C=CompactEnemyName(Candidate)
                        if Wanted[C] then Match=true; break end
                        for W in pairs(Wanted) do
                            if #W>=5 and (string.find(C,W,1,true) or string.find(W,C,1,true)) then Match=true; break end
                        end
                        if Match then break end
                    end
                    if Match then
                        local D=Me and (Me.Position-R.Position).Magnitude or 0
                        if D<BestDist then Best,BestDist=Obj,D end
                    end
                end
                for _,Container in ipairs(Containers) do
                    if Container then
                        for _,Obj in ipairs(Container:GetChildren()) do Consider(Obj) end
                        for _,Obj in ipairs(Container:GetDescendants()) do
                            if Obj:IsA("BasePart") or Obj:IsA("Model") then Consider(Obj) end
                        end
                    end
                end
                return Best
            end

            local function ReplicatedBloxTargetCFrame(Filter,BossOnly)

                for _,Obj in ipairs(ReplicatedStorage:GetChildren()) do
                    if Obj:IsA("Model") and TargetNameMatches(Obj.Name,Filter,BossOnly) then
                        local R=GetRoot(Obj)
                        if R and R.Position.Magnitude>1 then return R.CFrame end
                    end
                end
                return nil
            end
            local function StaticBloxTargetCFrame(Name,BossOnly)
                if BossOnly then
                    local Display=BossDisplayForName(Name) or StripEnemyName(Name)
                    return BloxBossFallbackCFrames[Display] or BloxBossFallbackCFrames[StripEnemyName(Name)]
                end
                local Route=BloxKnownQuestRoutes[CompactEnemyName(Name)]
                return Route and Route.Sea==BloxSeaNumber() and Route.MobCF or nil
            end
            local function ResolveBloxEntrance(Destination)
                local Best,Distance=nil,math.huge
                local BestGoal=nil
                local Me=Root()
                if not Me then return nil end
                local DirectDistance=(Me.Position-Destination).Magnitude
                for _,Object in ipairs(Runtime.ProfileObjects()) do
                    if not Object.Parent then continue end
                    local Goal=Object:GetAttribute("Destination") or Object:GetAttribute("TargetPosition")
                    for _,Key in ipairs({"Destination","TargetPosition","TeleportTo"}) do
                        local Value=Object:FindFirstChild(Key)
                        if Value and (Value:IsA("Vector3Value") or Value:IsA("CFrameValue")) then Goal=Value.Value end
                        if Value and Value:IsA("ObjectValue") and Value.Value then
                            local Exit=GetRoot(Value.Value)
                            if Exit then Goal=Exit.Position end
                        end
                    end
                    if typeof(Goal)=="CFrame" then Goal=Goal.Position end
                    if typeof(Goal)=="Vector3" then
                        local Trigger=Object:IsA("BasePart") and Object
                            or Object:FindFirstChild("Trigger",true) or Object:FindFirstChild("TouchInterest",true)
                        if Trigger and Trigger:IsA("TouchTransmitter") then Trigger=Trigger.Parent end
                        if Trigger and Trigger:IsA("BasePart") then
                            local D=(Me.Position-Trigger.Position).Magnitude+(Goal-Destination).Magnitude

                            if D+100<DirectDistance and D<Distance then
                                Best,Distance,BestGoal=Trigger,D,Goal
                            end
                        end
                    end
                end
                return Best,BestGoal
            end
            Runtime.IsBloxCursedShipEntrance=function(Destination)
                if typeof(Destination)=="CFrame" then Destination=Destination.Position end
                if typeof(Destination)~="Vector3" then return false end
                local A=Runtime.BloxCursedShipEntrance or Vector3.new(-6505,83,-127)
                local B=Runtime.BloxCursedShipEntranceFinish or Vector3.new(-6492,83,-109)
                local Legacy=Runtime.BloxCursedShipLegacyEntrance or Vector3.new(923.21252441406,126.9760055542,32852.83203125)
                return (Destination-A).Magnitude<8 or (Destination-B).Magnitude<8 or (Destination-Legacy).Magnitude<8
            end
            Runtime.IsBloxCursedShipInteriorPosition=function(Position)
                if typeof(Position)=="CFrame" then Position=Position.Position end
                if typeof(Position)~="Vector3" then return false end
                local Anchor=Runtime.BloxCursedShipDeckhand and Runtime.BloxCursedShipDeckhand.Position or Vector3.new(921,126,33088)
                return (Position-Anchor).Magnitude<1800
            end
            Runtime.BloxCursedShipExitTravel=function(Key)
                Runtime.Movement.Guard()
                local Me=Root()
                if not Me then return false end
                if not Runtime.IsBloxCursedShipInteriorPosition(Me.Position) then return true end

                local First=CFrame.new(921,125,32855)
                local Second=CFrame.new(919,125,32855)
                Runtime.BloxCursedShipExitRouting=true
                local Ok,Result=pcall(function()
                    if Runtime.Movement and Runtime.Movement.SetState then
                        Runtime.Movement.SetState("Door","Cursed Ship • approaching exit",tostring(Key or "CursedShipExit"))
                    end
                    if (Me.Position-First.Position).Magnitude>3 then
                        if not Runtime.ProfileRouter.Direct(First,"Smooth Tween",nil,"CursedShip:Exit1") then return false end
                    end
                    Runtime.Movement.Guard()
                    Me=Root()
                    if not Me then return false end

                    if Runtime.Movement and Runtime.Movement.SetState then
                        Runtime.Movement.SetState("Door","Cursed Ship • crossing exit",tostring(Key or "CursedShipExit"))
                    end
                    local BeforeSecond=Me.Position
                    local ReachedSecond=Runtime.ProfileRouter.Direct(Second,"Smooth Tween",function()
                        local R=Root()
                        if not R then return Second end
                        -- Crossing the second point can instantly move the character back outside.
                        -- Stop trying to reach the interior trigger once that transition happens.
                        if not Runtime.IsBloxCursedShipInteriorPosition(R.Position)
                            or (R.Position-BeforeSecond).Magnitude>250 then
                            return R.CFrame
                        end
                        return Second
                    end,"CursedShip:Exit2")
                    local After=Root()
                    local Transitioned=After and (not Runtime.IsBloxCursedShipInteriorPosition(After.Position)
                        or (After.Position-BeforeSecond).Magnitude>250)
                    if not ReachedSecond and not Transitioned then return false end

                    task.wait(0.5)
                    Runtime.Movement.Guard()
                    if Runtime.RefreshProfileWorldCache then Runtime.RefreshProfileWorldCache() end
                    BloxEnemySnapshotState.At=0
                    if Runtime.Movement and Runtime.Movement.SetState then
                        Runtime.Movement.SetState("Reached","Cursed Ship exit completed • continuing route",tostring(Key or "CursedShipExit"))
                    end
                    return true
                end)
                Runtime.BloxCursedShipExitRouting=false
                if not Ok then
                    if tostring(Result):find("BANANI_CANCELLED",1,true) then error(Result,0) end
                    Runtime.BloxQuestLastFailure="Cursed Ship exit route error: "..tostring(Result)
                    return false
                end
                return Result==true
            end
            Runtime.BloxCursedShipTravel=function(Key)
                Runtime.Movement.Guard()
                local First=CFrame.new(-6505,83,-127)
                local Second=CFrame.new(-6492,83,-109)
                local Me=Root()
                if not Me then return false end
                -- If the player is already in the interior coordinate space, do not route them back outside.
                if Runtime.IsBloxCursedShipInteriorPosition(Me.Position) then
                    return true
                end
                if Runtime.Movement and Runtime.Movement.SetState then
                    Runtime.Movement.SetState("Door","Cursed Ship • approaching entrance",tostring(Key or "CursedShip"))
                end
                if (Me.Position-First.Position).Magnitude>3 then
                    if not Runtime.ProfileRouter.Direct(First,"Smooth Tween",nil,"CursedShip:Entrance1") then return false end
                end
                Runtime.Movement.Guard()
                Me=Root()
                if not Me then return false end
                if Runtime.Movement and Runtime.Movement.SetState then
                    Runtime.Movement.SetState("Door","Cursed Ship • crossing entrance",tostring(Key or "CursedShip"))
                end
                local BeforeSecond=Me.Position
                local ReachedSecond=Runtime.ProfileRouter.Direct(Second,"Smooth Tween",function()
                    local R=Root()
                    if not R then return Second end
                    -- Touching the second point may immediately move the character into the ship.
                    -- If that happens, stop chasing the outside point and accept the transition.
                    if (R.Position-BeforeSecond).Magnitude>250 then return R.CFrame end
                    return Second
                end,"CursedShip:Entrance2")
                local After=Root()
                local Transitioned=After and ((After.Position-BeforeSecond).Magnitude>250
                    or Runtime.IsBloxCursedShipInteriorPosition(After.Position))
                if not ReachedSecond and not Transitioned then return false end
                task.wait(0.5)
                Runtime.Movement.Guard()
                if Runtime.RefreshProfileWorldCache then Runtime.RefreshProfileWorldCache() end
                BloxEnemySnapshotState.At=0
                if Runtime.Movement and Runtime.Movement.SetState then
                    Runtime.Movement.SetState("Reached","Cursed Ship travel completed",tostring(Key or "CursedShip"))
                end
                return true
            end

            local function RequestBloxEntrance(Destination,Key)

                if typeof(Destination)=="CFrame" then Destination=Destination.Position end
                if typeof(Destination)~="Vector3" then return false end
                if Runtime.IsBloxCursedShipEntrance and Runtime.IsBloxCursedShipEntrance(Destination) then
                    return Runtime.BloxCursedShipTravel(Key or "RequestEntrance")
                end
                local Known=false
                for _,Route in pairs(BloxKnownQuestRoutes) do
                    if Route.Entrance and (Route.Entrance-Destination).Magnitude<3 then Known=true; break end
                end
                if not Known then return false end
                local Me=Root()
                if not Me then return false end
                if (Me.Position-Destination).Magnitude<=3 then return true end
                local Stamp=os.clock()
                Runtime.BloxEntranceRequestAt=Runtime.BloxEntranceRequestAt or {}
                local RequestKey=tostring(Key or (math.floor(Destination.X)..":"..math.floor(Destination.Y)..":"..math.floor(Destination.Z)))
                if Stamp-(Runtime.BloxEntranceRequestAt[RequestKey] or -math.huge)<2 then return false end
                Runtime.BloxEntranceRequestAt[RequestKey]=Stamp
                local Before=Me.Position
                local function Changed()
                    local R=Root()
                    return R~=nil and (R.Position-Before).Magnitude>35 and (R.Position-Destination).Magnitude<125
                end
                local Ok,Result=QueryRemote(BloxCommF(),"requestEntrance",Destination)
                if not Ok then
                    Runtime.BloxQuestLastFailure="requestEntrance rejected: "..tostring(Result or "unknown server response")
                    return false
                end
                local Deadline=os.clock()+4.0
                repeat
                    Runtime.Movement.Guard()
                    if Changed() then
                        task.wait(0.5)
                        if Runtime.RefreshProfileWorldCache then Runtime.RefreshProfileWorldCache() end
                        return true
                    end
                    task.wait(0.08)
                until os.clock()>=Deadline
                Runtime.BloxQuestLastFailure="Entrance arrival was not confirmed"
                return false
            end

            local function KnownBloxEntranceForDestination(Destination)
                if typeof(Destination)=="CFrame" then Destination=Destination.Position end
                if typeof(Destination)~="Vector3" then return nil end
                local Best,BestScore=nil,math.huge
                for _,Route in pairs(BloxKnownQuestRoutes) do
                    if Route.Sea==BloxSeaNumber() and Route.Entrance then
                        local Score=math.huge
                        if Route.MobCF then Score=math.min(Score,(Route.MobCF.Position-Destination).Magnitude) end
                        if Route.QuestCF then Score=math.min(Score,(Route.QuestCF.Position-Destination).Magnitude) end

                        if Score<700 and Score<BestScore then Best,BestScore=Route.Entrance,Score end
                    end
                end
                return Best
            end

            BloxSmartEntranceTravel=function(Destination,Key)
                if Runtime.BloxRoutingEntrance then return false end
                if typeof(Destination)=="CFrame" then Destination=Destination.Position end
                if typeof(Destination)~="Vector3" then return false end
                local Me=Root()
                if not Me or (Me.Position-Destination).Magnitude<=220 then return false end
                local KnownEntrance=KnownBloxEntranceForDestination(Destination)
                if KnownEntrance and Runtime.IsBloxCursedShipEntrance and Runtime.IsBloxCursedShipEntrance(KnownEntrance) then
                    return Runtime.BloxCursedShipTravel("Smart:"..tostring(Key or "Travel"))
                end
                local Door,Exit=ResolveBloxEntrance(Destination)
                if not Door and KnownEntrance then Door,Exit=ResolveBloxEntrance(KnownEntrance) end
                local Entered=false
                Runtime.BloxRoutingEntrance=true
                local Ok,Err=pcall(function()
                    if Door then
                        local Current=Root()
                        if not Current then return end
                        local Away=Current.Position-Door.Position
                        if Away.Magnitude<0.1 then Away=Door.CFrame.LookVector end
                        local Outside=CFrame.lookAt(Door.Position+Away.Unit*6,Door.Position)

                        Entered=Runtime.EnterThrough(
                            "BloxSmart:"..tostring(Key or "Travel")..":"..tostring(Door:GetFullName()),
                            Door,Outside,nil,Exit
                        )
                    end
                    if not Entered and KnownEntrance then
                        Entered=RequestBloxEntrance(KnownEntrance,"Smart:"..tostring(Key or "Travel"))
                    end
                end)
                Runtime.BloxRoutingEntrance=false
                if not Ok then
                    if tostring(Err):find("BANANI_CANCELLED",1,true) then error(Err,0) end
                    Runtime.BloxQuestLastFailure="Entrance route error: "..tostring(Err)
                    return false
                end
                if Entered then
                    BloxEnemySnapshotState.At=0
                    if Runtime.RefreshProfileWorldCache then Runtime.RefreshProfileWorldCache() end
                end
                return Entered==true
            end

            local BloxGroundTravelCFrame
            local function MoveToBloxTargetArea(Name,BossOnly,Q)
                local TargetCF=(Q and Q.MobPosition) or StaticBloxTargetCFrame(Name,BossOnly)
                local Route=(not BossOnly) and BloxKnownQuestRoutes[CompactEnemyName(Name)] or nil
                local Entrance=(Q and Q.EntrancePosition) or (Route and Route.Entrance)
                local Me=Root()
                if Entrance and Me and TargetCF and (Me.Position-TargetCF.Position).Magnitude>220 then
                    local Entered=false
                    if Runtime.IsBloxCursedShipEntrance and Runtime.IsBloxCursedShipEntrance(Entrance) then
                        Entered=Runtime.BloxCursedShipTravel("Quest:"..CompactEnemyName(Name))
                    end
                    local Door,Exit=nil,nil
                    if not Entered then Door,Exit=ResolveBloxEntrance(Entrance) end
                    if Door then
                        local Away=Me.Position-Door.Position
                        if Away.Magnitude<0.1 then Away=Door.CFrame.LookVector end
                        local Outside=CFrame.lookAt(Door.Position+Away.Unit*6,Door.Position)
                        Entered=Runtime.EnterThrough("Blox:"..tostring(Entrance),Door,Outside,function()
                            QueryRemote(BloxCommF(),"requestEntrance",Entrance)
                        end,Exit)
                    else
                        Entered=RequestBloxEntrance(Entrance,"Quest:"..CompactEnemyName(Name))
                    end

                    if Entered then
                        Runtime.BloxQuestLastFailure=nil
                    else
                        Runtime.BloxQuestLastFailure=Runtime.BloxQuestLastFailure or "Entrance unavailable; using direct ground route"
                    end
                    BloxEnemySnapshotState.At=0
                    local Spawn=FindBloxSpawn(Name)
                    if Spawn and GetRoot(Spawn) then TargetCF=GetRoot(Spawn).CFrame end
                end
                if TargetCF then
                    return ProfileTravelToCFrame(BloxGroundTravelCFrame(TargetCF))
                end
                local Spawn=FindBloxSpawn(Name)
                if Spawn then return MoveTo(Spawn,CFrame.new(0,2,2)) end
                local RepCF=ReplicatedBloxTargetCFrame(Name,BossOnly)
                if RepCF then return ProfileTravelToCFrame(RepCF*CFrame.new(0,2,2)) end
                return false
            end

            local function BloxNPCMap()
                local Map={}
                local Guide=BloxGuide()
                local List=Guide and Guide.Data and Guide.Data.NPCList
                if type(List)=="table" then
                    for _,Entry in pairs(List) do
                        if type(Entry)=="table" then
                            local Name=Entry.NPCName or Entry.Name
                            local Pos=Entry.CFrame or Entry.Position
                            if typeof(Pos)=="Vector3" then Pos=CFrame.new(Pos) end
                            if Name and typeof(Pos)=="CFrame" then Map[tostring(Name)]=Pos end
                        end
                    end
                end
                return Map
            end
            local function BloxNPCNames()
                local Out,Seen={"Select NPC"},{[NormalName("Select NPC")]=true}
                for Name in pairs(BloxNPCMap()) do AddUnique(Out,Seen,Name) end

                local Folder=workspace:FindFirstChild("NPCs") or workspace:FindFirstChild("Npcs") or workspace:FindFirstChild("QuestNPCs")
                if Folder then
                    for _,Obj in ipairs(Folder:GetDescendants()) do
                        if Obj:IsA("Model") and GetRoot(Obj) then AddUnique(Out,Seen,Obj.Name) end
                    end
                end
                table.sort(Out,function(A,B)
                    if A==B then return false end
                    if A=="Select NPC" then return true end
                    if B=="Select NPC" then return false end
                    return string.lower(A)<string.lower(B)
                end)
                return Out
            end
            local function GoBloxNPC(Name)
                if not Name or Name=="Select NPC" then return false end
                local Folder=workspace:FindFirstChild("NPCs") or workspace:FindFirstChild("Npcs") or workspace:FindFirstChild("QuestNPCs")
                if Folder then
                    for _,Obj in ipairs(Folder:GetDescendants()) do
                        if Obj:IsA("Model") and NormalName(Obj.Name)==NormalName(Name) and MoveTo(Obj,CFrame.new(0,3,3)) then return true end
                    end
                end
                local Pos=BloxNPCMap()[Name]
                if Pos then return ProfileTravelToCFrame(Pos*CFrame.new(0,3,3)) end
                return false
            end
            local BloxGroundPoint
            local ResolveBloxMovementZone
            Runtime.BloxMovementZones=Runtime.BloxMovementZones or {}
            Runtime.BloxMovementZoneSerial=tonumber(Runtime.BloxMovementZoneSerial) or 0
            Runtime.BloxActiveMovementZone=nil
            Runtime.BloxEnemyGroundCache=Runtime.BloxEnemyGroundCache or setmetatable({}, {__mode="k"})

            local function EffectiveBloxM1Reach()
                if Runtime.BloxAutoLevelActive or Runtime.BloxMaterialFarmActive or Runtime.BloxRaidCombatActive then return 55 end
                return math.clamp(tonumber(State.BloxM1Reach) or 20,15,200)
            end
            local function AutoBloxFarmHeight()
                if not Runtime.BloxAutoLevelActive and not Runtime.BloxMaterialFarmActive and not Runtime.BloxRaidCombatActive and not Runtime.BloxFarmEnemyActive then
                    return math.clamp(tonumber(State.BloxFarmHeight) or 15,3,50)
                end

                local ContactBias=math.clamp(tonumber(Runtime.BloxAutoContactBias) or 0,-6,6)
                local Height=20+ContactBias
                local H=Humanoid()
                if H and H.MaxHealth>0 then
                    local Pct=H.Health/H.MaxHealth*100
                    if Pct<=55 then Height=math.max(Height,24) end
                    if Pct<=30 then Height=math.max(Height,28) end
                    if Pct<=15 then Height=30 end
                end
                if os.clock()<(Runtime.BloxAutoDamageBoostUntil or 0) then
                    Height=math.max(Height,26)
                end
                return math.clamp(Height,14,30)
            end
            local function BloxHoverCFrame(TargetRoot)
                if not TargetRoot then return nil end
                local AutoHover=(Runtime.BloxAutoLevelActive==true or Runtime.BloxMaterialFarmActive==true or Runtime.BloxRaidCombatActive==true or Runtime.BloxFarmEnemyActive==true)
                local Height=AutoBloxFarmHeight()
                if AutoHover or State.BloxHoverAbove then
                    -- Keep one world-space hover lane while handing off between mobs on the same
                    -- flat floor. Previously each new target recomputed its own Y immediately,
                    -- which could make the character pop upward/downward between consecutive kills.
                    local Zone,GroundRef=ResolveBloxMovementZone(TargetRoot,true)
                    GroundRef=GroundRef or TargetRoot.Position.Y
                    local DesiredY=TargetRoot.Position.Y+Height
                    local PreviousY=tonumber(Runtime.BloxStableHoverY)
                    local PreviousGround=tonumber(Runtime.BloxStableHoverGroundY)
                    local Now=os.clock()
                    local Recent=(Now-(tonumber(Runtime.BloxStableHoverAt) or -math.huge))<=5.0
                        or Now<(tonumber(Runtime.BloxHoverHandoffUntil) or 0)
                    local SameZone=AutoHover and Zone and Runtime.BloxActiveMovementZone==Zone
                    local SameFlatGround=AutoHover and Recent and PreviousY and PreviousGround
                        and math.abs(GroundRef-PreviousGround)<=5.5
                    local HoverY

                    if AutoHover and Zone and tonumber(Zone.HoverY) then
                        HoverY=tonumber(Zone.HoverY)
                    elseif SameZone or SameFlatGround then
                        HoverY=PreviousY
                    else
                        -- New terrain/area: calculate the lane once, then remember it.
                        HoverY=DesiredY
                    end

                    -- Health safety may intentionally raise the remembered lane, but only
                    -- outside the short kill -> next-target handoff window.
                    if (SameZone or SameFlatGround)
                        and Now>=(tonumber(Runtime.BloxHoverHandoffUntil) or 0)
                        and DesiredY>HoverY+3 then
                        HoverY=DesiredY
                    end

                    if Zone then
                        Zone.HoverY=HoverY
                        Zone.GroundY=GroundRef
                        Zone.LastSeen=Now
                        Runtime.BloxActiveMovementZone=Zone
                    end
                    Runtime.BloxStableHoverY=HoverY
                    Runtime.BloxStableHoverGroundY=GroundRef
                    Runtime.BloxStableHoverAt=Now

                    local Pos=Vector3.new(TargetRoot.Position.X,HoverY,TargetRoot.Position.Z)
                    local Ok,CF=pcall(function() return CFrame.lookAt(Pos,TargetRoot.Position) end)
                    return Ok and CF or CFrame.new(Pos)
                end
                local Me=Root()
                local Delta=Me and (TargetRoot.Position-Me.Position) or Vector3.new(0,0,-1)
                local Flat=Vector3.new(Delta.X,0,Delta.Z)
                if Flat.Magnitude<0.05 then Flat=Vector3.new(0,0,-1) end
                local Ground=BloxGroundPoint and BloxGroundPoint(TargetRoot.Position-Flat.Unit*6,TargetRoot.Parent)
                if Ground then return CFrame.lookAt(Ground,TargetRoot.Position+Vector3.new(0,1.5,0)) end
                return nil
            end
            BloxGroundPoint=function(Position,Exclude)
                if typeof(Position)~="Vector3" then return nil end
                local Params=RaycastParams.new()
                Params.FilterType=Enum.RaycastFilterType.Exclude
                local Filters={}
                local C=Character()
                if C then table.insert(Filters,C) end
                if Exclude then table.insert(Filters,Exclude) end
                Params.FilterDescendantsInstances=Filters
                Params.IgnoreWater=true
                Params.RespectCanCollide=true
                local Enemies=workspace:FindFirstChild("Enemies")
                if Enemies then table.insert(Filters,Enemies) end
                Params.FilterDescendantsInstances=Filters
                local Hit=workspace:Raycast(Position+Vector3.new(0,30,0),Vector3.new(0,-200,0),Params)
                local Fallen=tonumber(workspace.FallenPartsDestroyHeight) or -500
                if Hit and Hit.Instance and Hit.Instance.CanCollide and Hit.Material~=Enum.Material.Water and Hit.Normal.Y>0.65 and Hit.Position.Y>Fallen+20 then
                    return Hit.Position+Vector3.new(0,3.2,0)
                end
                return nil
            end


-- ==================================================================
-- [BH:BLOX] MOVEMENT ZONES
-- Remembers terrain/floor and exact combat HoverY by area.
-- ==================================================================
            ResolveBloxMovementZone=function(TargetRoot,Create)
                if not TargetRoot then return nil,nil end
                local Now=os.clock()
                local Owner=TargetRoot.Parent
                local Cached=Owner and Runtime.BloxEnemyGroundCache[Owner] or nil
                local GroundRef
                if Cached and Now-(tonumber(Cached.At) or 0)<0.65 then
                    GroundRef=Cached.Y
                else
                    local Ground=BloxGroundPoint(TargetRoot.Position,Owner)
                    GroundRef=Ground and Ground.Y or TargetRoot.Position.Y
                    if Owner then Runtime.BloxEnemyGroundCache[Owner]={Y=GroundRef,At=Now} end
                end

                local P=TargetRoot.Position
                local XZ=Vector3.new(P.X,0,P.Z)
                local Zones=Runtime.BloxMovementZones
                local Best,BestDist=nil,math.huge

                for I=#Zones,1,-1 do
                    local Zone=Zones[I]
                    if not Zone or Now-(tonumber(Zone.LastSeen) or 0)>90 then
                        table.remove(Zones,I)
                    else
                        local Center=Zone.Center
                        local HD=(Vector3.new(Center.X,0,Center.Z)-XZ).Magnitude
                        local GroundDelta=math.abs((tonumber(Zone.GroundY) or GroundRef)-GroundRef)
                        if GroundDelta<=5.5 and HD<=math.max(tonumber(Zone.Radius) or 120,80) and HD<BestDist then
                            Best,BestDist=Zone,HD
                        end
                    end
                end

                if not Best and Create~=false then
                    Runtime.BloxMovementZoneSerial+=1
                    Best={
                        Id=Runtime.BloxMovementZoneSerial,
                        Center=Vector3.new(P.X,GroundRef,P.Z),
                        GroundY=GroundRef,
                        HoverY=nil,
                        Radius=120,
                        LastSeen=Now,
                        Samples=0
                    }
                    table.insert(Zones,Best)
                    while #Zones>12 do table.remove(Zones,1) end
                end

                if Best then
                    Best.LastSeen=Now
                    Best.Samples=(tonumber(Best.Samples) or 0)+1
                    if BestDist and BestDist<=120 then
                        local A=math.clamp(1/math.max(Best.Samples,4),0.05,0.20)
                        Best.Center=Best.Center:Lerp(Vector3.new(P.X,GroundRef,P.Z),A)
                    end
                    Runtime.BloxMovementZoneStatus="Zone "..tostring(Best.Id).." • floor "..tostring(math.floor(GroundRef+0.5))
                end
                return Best,GroundRef
            end

            BloxGroundTravelCFrame=function(CF)
                if typeof(CF)~="CFrame" then return nil end
                local Forward=CF.LookVector
                local Flat=Vector3.new(Forward.X,0,Forward.Z)
                if Flat.Magnitude<0.05 then Flat=Vector3.new(0,0,-1) end
                local Desired=CF.Position-Flat.Unit*6
                local Ground=BloxGroundPoint(Desired,nil)
                if Ground then return CFrame.lookAt(Ground,CF.Position+Vector3.new(0,1.5,0)) end
                -- Some islands/spawn markers sit too far above the streamed floor for the
                -- short floor probe. Never let Auto Farm stall in TravelMobs because of that.
                local Fallback=CF.Position+Vector3.new(0,6,0)-Flat.Unit*4
                return CFrame.lookAt(Fallback,CF.Position+Vector3.new(0,2,0))
            end
            local function WaitForBloxSpawn()
                -- Stay exactly where Auto Farm finished the last mob. Do NOT move underground.
                Runtime.BloxUndergroundWaitCF=nil
                Runtime.BloxWaitingUnderground=false
                local R=Root()
                if R then
                    R.AssemblyLinearVelocity=Vector3.zero
                    R.AssemblyAngularVelocity=Vector3.zero
                end
                Runtime.BloxCombatLastResult="Waiting on surface for quest enemies to respawn"
                return true
            end
            Runtime.BloxPlayerProtection=Runtime.BloxPlayerProtection or {}
            Runtime.BloxPlayerProtection.Collisions=Runtime.BloxPlayerProtection.Collisions or setmetatable({}, {__mode="k"})

            Runtime.BloxPlayerProtection.FindThreat=function(MaxDistance)
                local Me=Root()
                if not Me then return nil,nil end
                local Best,BestDistance=nil,math.huge
                local Limit=tonumber(MaxDistance) or tonumber(State.BloxPlayerProtectionDetectRadius) or 140
                for _,Candidate in ipairs(Players:GetPlayers()) do
                    if Candidate~=Player then
                        local C=Candidate.Character
                        local H=C and C:FindFirstChildOfClass("Humanoid")
                        local R=C and C:FindFirstChild("HumanoidRootPart")
                        if H and R and H.Health>0 then
                            local D=(R.Position-Me.Position).Magnitude
                            if D<=Limit and D<BestDistance then Best,BestDistance=Candidate,D end
                        end
                    end
                end
                return Best,BestDistance
            end

            Runtime.BloxPlayerProtection.RestoreCollision=function()
                local P=Runtime.BloxPlayerProtection
                for Part,Original in pairs(P.Collisions or {}) do
                    if Part and Part.Parent then pcall(function() Part.CanCollide=Original end) end
                end
                P.Collisions=setmetatable({}, {__mode="k"})
            end

            Runtime.BloxPlayerProtection.ApplyCollision=function(CharacterModel,ForceScan)
                local P=Runtime.BloxPlayerProtection
                if not CharacterModel then return end
                local Now=os.clock()
                if ForceScan or Now-(tonumber(P.LastCollisionScan) or 0)>=0.25 then
                    P.LastCollisionScan=Now
                    for _,Object in ipairs(CharacterModel:GetDescendants()) do
                        if Object:IsA("BasePart") then
                            if P.Collisions[Object]==nil then P.Collisions[Object]=Object.CanCollide end
                            if Object.CanCollide then Object.CanCollide=false end
                        end
                    end
                else
                    for Part in pairs(P.Collisions) do
                        if Part and Part.Parent and Part.CanCollide then Part.CanCollide=false end
                    end
                end
            end

            Runtime.BloxPlayerProtection.Exit=function(Reason)
                local P=Runtime.BloxPlayerProtection
                if Runtime.BloxPlayerProtectionActive~=true then return false end
                local R=Root()
                local Surface=P.SurfaceCFrame
                Runtime.BloxPlayerProtectionActive=false
                Runtime.BloxPlayerProtectionThreat=nil
                P.ThreatClearSince=nil
                P.LastTriggerAt=0
                Runtime.BloxPlayerProtection.RestoreCollision()
                if R and Surface then
                    pcall(function()
                        R.CFrame=Surface
                        R.AssemblyLinearVelocity=Vector3.zero
                        R.AssemblyAngularVelocity=Vector3.zero
                    end)
                end
                P.SurfaceCFrame=nil
                P.HideCFrame=nil
                Runtime.BloxCombatLastResult="Player Protection cleared • resuming farm"
                if Runtime.SetAutomationState then Runtime.SetAutomationState("BloxPlayerProtection","Idle",tostring(Reason or "Threat left")) end
                pcall(function() Notify("Player Protection","Threat left • returned to surface") end)
                return true
            end

            Runtime.BloxPlayerProtection.Enter=function(Threat,DamageAmount)
                if State.BloxPlayerProtection~=true or Runtime.BloxPlayerProtectionActive==true then return false end
                local R=Root()
                local H=Humanoid()
                if not R or not H or H.Health<=0 or not Threat then return false end
                local P=Runtime.BloxPlayerProtection
                local Fallen=tonumber(workspace.FallenPartsDestroyHeight) or -500
                local Depth=math.clamp(tonumber(State.BloxPlayerProtectionDepth) or 65,25,120)
                local HideY=math.max(R.Position.Y-Depth,Fallen+28)
                P.SurfaceCFrame=R.CFrame
                P.HideCFrame=CFrame.new(R.Position.X,HideY,R.Position.Z)*R.CFrame.Rotation
                P.ThreatClearSince=nil
                P.LastTriggerAt=os.clock()
                Runtime.BloxPlayerProtectionThreat=Threat
                Runtime.BloxPlayerProtectionActive=true
                -- Interrupt only the physical route. Do not cancel the owning farm loop; it will
                -- keep ticking in a paused state and resume automatically after protection clears.
                Runtime.TweenCancel=true
                if Runtime.ActiveWalkCleanup then pcall(Runtime.ActiveWalkCleanup) end
                Runtime.BloxPlayerProtection.ApplyCollision(Character())
                pcall(function()
                    R.CFrame=P.HideCFrame
                    R.AssemblyLinearVelocity=Vector3.zero
                    R.AssemblyAngularVelocity=Vector3.zero
                end)
                Runtime.BloxCombatLastResult="Player Protection • hiding from @"..tostring(Threat.Name)
                if Runtime.SetAutomationState then Runtime.SetAutomationState("BloxPlayerProtection","Recovering","Hiding from @"..tostring(Threat.Name)) end
                pcall(function() Notify("Player Protection","Heavy damage detected • hiding underground from @"..tostring(Threat.Name)) end)
                return true
            end

            Runtime.BindBloxPlayerProtectionHealth=function()
                local P=Runtime.BloxPlayerProtection
                if P.HealthConnection then pcall(function() P.HealthConnection:Disconnect() end) P.HealthConnection=nil end
                local H=Humanoid()
                if not H then return false end
                P.LastHealth=H.Health
                P.LastHealthAt=os.clock()
                P.DamageWindowStartedAt=os.clock()
                P.DamageWindowBaseline=H.Health
                P.HealthConnection=H.HealthChanged:Connect(function(NewHealth)
                    if Unloaded then return end
                    local Previous=tonumber(P.LastHealth) or tonumber(NewHealth) or 0
                    local Current=tonumber(NewHealth) or Previous
                    local Now=os.clock()
                    if Current>Previous or Now-(tonumber(P.DamageWindowStartedAt) or 0)>0.85 then
                        P.DamageWindowStartedAt=Now
                        P.DamageWindowBaseline=Previous
                    end
                    P.LastHealth=Current
                    P.LastHealthAt=Now
                    if State.BloxPlayerProtection~=true or Runtime.BloxPlayerProtectionActive==true or H.MaxHealth<=0 then return end
                    local Loss=math.max(0,(tonumber(P.DamageWindowBaseline) or Previous)-Current)
                    local Threshold=math.max(22,H.MaxHealth*(math.clamp(tonumber(State.BloxPlayerProtectionDamagePct) or 18,10,50)/100))
                    if Loss<Threshold then return end
                    local Threat=Runtime.BloxPlayerProtection.FindThreat(State.BloxPlayerProtectionDetectRadius)
                    if Threat then
                        P.DamageWindowStartedAt=Now
                        P.DamageWindowBaseline=Current
                        Runtime.BloxPlayerProtection.Enter(Threat,Loss)
                    end
                end)
                return true
            end

            TrackConnection(Player.CharacterAdded:Connect(function()
                task.delay(.25,function()
                    if Unloaded then return end
                    Runtime.BloxPlayerProtectionActive=false
                    Runtime.BloxPlayerProtectionThreat=nil
                    Runtime.BloxPlayerProtection.SurfaceCFrame=nil
                    Runtime.BloxPlayerProtection.HideCFrame=nil
                    Runtime.BloxPlayerProtection.RestoreCollision()
                    Runtime.BindBloxPlayerProtectionHealth()
                end)
            end))
            Runtime.BindBloxPlayerProtectionHealth()

            TrackConnection(RunService.Heartbeat:Connect(function()
                if Unloaded or Runtime.BloxPlayerProtectionActive~=true then return end
                local P=Runtime.BloxPlayerProtection
                local R=Root()
                local H=Humanoid()
                local Threat=Runtime.BloxPlayerProtectionThreat
                if not R or not H or H.Health<=0 or not P.HideCFrame then return end

                Runtime.BloxPlayerProtection.ApplyCollision(Character())
                pcall(function()
                    R.CFrame=P.HideCFrame
                    R.AssemblyLinearVelocity=Vector3.zero
                    R.AssemblyAngularVelocity=Vector3.zero
                end)

                local ThreatPresent=false
                if Threat and Threat.Parent==Players then
                    local TC=Threat.Character
                    local TH=TC and TC:FindFirstChildOfClass("Humanoid")
                    local TR=TC and TC:FindFirstChild("HumanoidRootPart")
                    if TH and TR and TH.Health>0 and P.SurfaceCFrame then
                        ThreatPresent=(TR.Position-P.SurfaceCFrame.Position).Magnitude<=math.clamp(tonumber(State.BloxPlayerProtectionReleaseRadius) or 350,150,800)
                    end
                end

                if ThreatPresent then
                    P.ThreatClearSince=nil
                    Runtime.BloxCombatLastResult="Player Protection • @"..tostring(Threat.Name).." still nearby"
                else
                    P.ThreatClearSince=P.ThreatClearSince or os.clock()
                    local ClearFor=os.clock()-P.ThreatClearSince
                    Runtime.BloxCombatLastResult="Player Protection • threat clear for "..string.format("%.1f",ClearFor).."/5.0s"
                    if ClearFor>=5 then Runtime.BloxPlayerProtection.Exit("Threat left nearby area") end
                end
            end))

            local function BloxCombatSafetyStep(Enemy)
                if Runtime.BloxPlayerProtectionActive==true then
                    Runtime.BloxCombatLastResult="Player Protection • hiding underground"
                    return false
                end
                local MyHum=Humanoid()
                if not MyHum or MyHum.Health<=0 or MyHum.MaxHealth<=0 then return false end
                local HealthPct=MyHum.Health/MyHum.MaxHealth*100

                if MyHum.FloorMaterial==Enum.Material.Water then
                    local WaterRoot=Root()
                    if WaterRoot then
                        pcall(function()
                            WaterRoot.CFrame=WaterRoot.CFrame+Vector3.new(0,28,0)
                            WaterRoot.AssemblyLinearVelocity=Vector3.zero
                            WaterRoot.AssemblyAngularVelocity=Vector3.zero
                        end)
                        Runtime.BloxCombatLastResult="Water detected • lifted to safety"
                    end
                end

                if Runtime.BloxAutoLevelActive or Runtime.BloxMaterialFarmActive or Runtime.BloxRaidCombatActive then

                    local Previous=Runtime.BloxAutoLastPlayerHealth
                    if Previous and MyHum.Health<Previous-0.5 then
                        Runtime.BloxAutoDamageBoostUntil=os.clock()+2.5
                        Runtime.BloxAutoContactBias=math.min((tonumber(Runtime.BloxAutoContactBias) or 0)+3,6)
                        Runtime.BloxCombatLastResult="Player hit • raising hover while keeping target"
                    end
                    Runtime.BloxAutoLastPlayerHealth=MyHum.Health
                    Runtime.BloxSafetyRecovering=false
                    Runtime.BloxSafetyLastRetreat=nil

                    local Me,ER=Root(),GetRoot(Enemy)
                    -- A kill -> next-enemy handoff owns the first movement itself. Do not let the
                    -- safety pass start the normal Blox water-safe travel here, because that route
                    -- intentionally does lift -> across -> descend for long trips and caused the
                    -- exact up/over/down motion the user does not want between farm kills.
                    if Me and ER and Runtime.BloxDirectEnemyHandoffActive~=true then
                        local Desired=BloxHoverCFrame(ER)
                        if Desired and (Me.Position-Desired.Position).Magnitude>2.5 then
                            ProfileTravelToCFrame(Desired,function()
                                local NR=Enemy and Enemy.Parent and GetRoot(Enemy)
                                return NR and BloxHoverCFrame(NR) or nil
                            end)
                        end
                    end
                    return true
                end

                local Low=State.BloxSafetyEnabled and math.clamp(tonumber(State.BloxSafetyLowHealth) or 40,40,75) or 40
                local Resume=State.BloxSafetyEnabled and math.clamp(tonumber(State.BloxSafetyResumeHealth) or 75,math.max(75,Low+5),95) or 75
                if not Runtime.BloxSafetyRecovering and HealthPct>Low then return true end
                if Runtime.BloxSafetyRecovering and HealthPct>=Resume then
                    Runtime.BloxSafetyRecovering=false
                    Runtime.BloxSafetyLastRetreat=nil
                    return true
                end
                Runtime.BloxSafetyRecovering=true
                local Me,ER=Root(),GetRoot(Enemy)
                if not Me then return false end
                if os.clock()-(Runtime.BloxSafetyLastRetreat or 0)<1.0 then return false end
                local Away=ER and Vector3.new(Me.Position.X-ER.Position.X,0,Me.Position.Z-ER.Position.Z) or Vector3.new(1,0,0)
                if Away.Magnitude<1 then Away=Vector3.new(1,0,0) end
                local Distance=math.clamp(tonumber(State.BloxSafetyDistance) or 42,25,100)
                if not ER or (Me.Position-ER.Position).Magnitude>=Distance then return false end
                local Best,BestScore=nil,-math.huge
                for Offset=-3,3 do
                    local Angle=math.rad(Offset*18)
                    local Direction=CFrame.fromAxisAngle(Vector3.yAxis,Angle):VectorToWorldSpace(Away.Unit)
                    local Point=BloxGroundPoint(Me.Position+Direction*Distance,Enemy)
                    if Point then
                        local ThreatGap=ER and (Point-ER.Position).Magnitude or 0
                        local Score=ThreatGap-math.abs(Point.Y-Me.Position.Y)*0.35
                        if Score>BestScore then Best,BestScore=Point,Score end
                    end
                end
                Runtime.BloxSafetyLastRetreat=os.clock()
                if Best then
                    ProfileTravelToCFrame(CFrame.lookAt(Best,Best+Away.Unit))
                else
                    Runtime.BloxCombatLastResult="Low health • waiting for a verified floor"
                end
                return false
            end
            local function TravelAboveBloxTarget(Object)
                local R=GetRoot(Object)
                if not R then return false end

                local Initial=BloxHoverCFrame(R)
                if not Initial then return false end
                return ProfileTravelToCFrame(Initial,function()
                    local NR=Object and Object.Parent and GetRoot(Object)
                    return NR and BloxHoverCFrame(NR) or nil
                end)
            end

            -- Auto Farm / Raid kill handoff: one direct tween from the current hover point to
            -- the next enemy's hover point. This deliberately bypasses ProfileRouter.Travel's
            -- long-distance water-safe lift/across/drop staging. On flat ground BloxHoverCFrame
            -- keeps the previous Y exactly, so this becomes a horizontal enemy -> enemy slide.
            Runtime.BloxDirectEnemyHandoff=function(Object)
                Runtime.Movement.Guard()
                local TargetRoot=GetRoot(Object)
                local Me=Root()
                if not TargetRoot or not Me then return false end
                local TargetCF=BloxHoverCFrame(TargetRoot)
                if not TargetCF then return false end
                if (Me.Position-TargetCF.Position).Magnitude<=3 then return true end
                if Runtime.Movement and Runtime.Movement.SetState then
                    Runtime.Movement.SetState("Target","Direct enemy handoff • holding hover lane","BloxCombatHandoff")
                end
                return Runtime.ProfileRouter.Direct(TargetCF,"Smooth Tween",function()
                    local NR=Object and Object.Parent and GetRoot(Object)
                    return NR and BloxHoverCFrame(NR) or nil
                end,"BloxCombatHandoff")
            end

            local function ExpandBloxEnemyHitbox(Enemy)
                local Automatic=(Runtime.BloxAutoLevelActive or Runtime.BloxMaterialFarmActive or Runtime.BloxRaidCombatActive)

                if Automatic then return end
                if not State.BloxModifyEnemyHitbox then return end
                if not Enemy or not Enemy.Parent then return end
                local R=GetRoot(Enemy)
                local H=Enemy:FindFirstChildOfClass("Humanoid")
                if not R or not H or H.Health<=0 then return end
                if type(sethiddenproperty)=="function" then
                    pcall(function() sethiddenproperty(Player,"SimulationRadius",math.huge) end)
                end
                pcall(function()
                    R.CanCollide=false

                    if not Automatic then
                        local ManualSize=math.clamp(tonumber(State.BloxEnemyHitbox) or 60,20,85)
                        R.Size=Vector3.new(ManualSize,ManualSize,ManualSize)
                        R.Transparency=1
                    end
                    R.AssemblyLinearVelocity=Vector3.zero
                    R.AssemblyAngularVelocity=Vector3.zero
                    H.WalkSpeed=0
                    if H.UseJumpPower then H.JumpPower=0 else H.JumpHeight=0 end
                end)
                local Head=Enemy:FindFirstChild("Head")
                if Head and Head:IsA("BasePart") then
                    pcall(function() Head.CanCollide=false end)
                end
            end

            local function BringMatchingMobs(Target)

                if State.BloxFastAttack then return end
                if Runtime.BloxAutoLevelActive or Runtime.BloxMaterialFarmActive or Runtime.BloxRaidCombatActive then return end
                if not State.BloxBringMobs or not Target then return end
                local TR=GetRoot(Target); if not TR then return end
                if type(sethiddenproperty)=="function" then
                    pcall(function() sethiddenproperty(Player,"SimulationRadius",math.huge) end)
                end

                local Want=CompactEnemyName(Target.Name)
                local TargetIsBoss=IsBossObject(Target)
                local Anchor=Runtime.BloxQuestMobAnchor
                if typeof(Anchor)~="CFrame" then
                    Anchor=TR.CFrame
                    Runtime.BloxQuestMobAnchor=Anchor
                end

                local Slot=0
                local Automatic=(Runtime.BloxAutoLevelActive or Runtime.BloxMaterialFarmActive or Runtime.BloxRaidCombatActive)
                for _,M in ipairs(BloxLiveEnemies(true)) do
                    if M~=Target and IsBossObject(M)==TargetIsBoss and CompactEnemyName(M.Name)==Want then
                        local R=GetRoot(M)
                        local H=M:FindFirstChildOfClass("Humanoid")
                        if R and H and H.Health>0 and (R.Position-TR.Position).Magnitude<=(tonumber(State.BloxBringRadius) or 220) then
                            Slot+=1
                            local Angle=(Slot%8)*(math.pi/4)
                            local Radius=math.min(4.5,1.5+(Slot%3))
                            local Offset=CFrame.new(math.cos(Angle)*Radius,0,math.sin(Angle)*Radius)
                            pcall(function()
                                R.CanCollide=false

                                if not Automatic then
                                    local HitboxSize=math.clamp(tonumber(State.BloxEnemyHitbox) or 60,20,85)
                                    R.Size=Vector3.new(HitboxSize,HitboxSize,HitboxSize)
                                    R.Transparency=1
                                end
                                R.AssemblyLinearVelocity=Vector3.zero
                                R.AssemblyAngularVelocity=Vector3.zero
                                H.WalkSpeed=0
                                if H.UseJumpPower then H.JumpPower=0 else H.JumpHeight=0 end
                                R.CFrame=Anchor*Offset
                            end)
                        end
                    end
                end
            end
            local BloxMoveAppearsUnlocked
            local LastBloxMove=0
            local BloxMoveIndex=0
            local function AimBloxTarget(Enemy,AimCamera)
                if not Enemy then return false end
                local ER=GetRoot(Enemy)
                local Me=Root()
                if not ER or not Me then return false end
                pcall(function()
                    local Delta=ER.Position-Me.Position
                    local Flat=Vector3.new(Delta.X,0,Delta.Z)
                    if Flat.Magnitude>0.05 then
                        Me.CFrame=CFrame.lookAt(Me.Position,Me.Position+Flat.Unit)
                    end
                end)
                if AimCamera then
                    local Cam=workspace.CurrentCamera
                    if Cam then pcall(function() Cam.CFrame=CFrame.lookAt(Cam.CFrame.Position,ER.Position) end) end
                end
                return true
            end
            local function UsableBloxMoveKeys()
                local Out={}
                for _,KeyName in ipairs(State.BloxAbilityKeys or {}) do
                    KeyName=string.upper(tostring(KeyName or ""))
                    if Enum.KeyCode[KeyName] and BloxMoveAppearsUnlocked(KeyName) then
                        table.insert(Out,KeyName)
                    end
                end
                return Out
            end
            local function UseBloxAbilities(Enemy)
                if not State.BloxUseAbilities or not Enemy then return end
                local ER,Me=GetRoot(Enemy),Root()
                if not ER or not Me then return end
                local Range=math.clamp(tonumber(State.BloxMoveRange) or 90,15,250)
                if (ER.Position-Me.Position).Magnitude>Range then return end

                local Keys=UsableBloxMoveKeys()
                if #Keys==0 then return end
                local Now=os.clock()
                if Now-LastBloxMove < math.clamp(tonumber(State.BloxMoveInterval) or 0.45,0.10,3.0) then return end
                LastBloxMove=Now
                if State.BloxAimMoves then AimBloxTarget(Enemy,true) end

                local Hold=math.clamp(tonumber(State.BloxMoveHold) or 0.05,0.02,0.25)
                if tostring(State.BloxMovePattern)=="Burst" then

                    for _,KeyName in ipairs(Keys) do
                        local Key=Enum.KeyCode[KeyName]
                        if Key then PressKey(Key,Hold); task.wait(0.035) end
                    end
                else
                    BloxMoveIndex=(BloxMoveIndex%#Keys)+1
                    local Key=Enum.KeyCode[Keys[BloxMoveIndex]]
                    if Key then PressKey(Key,Hold) end
                end
            end
            local function BloxToolCategory(Tool)
                if not Tool or not Tool:IsA("Tool") then return "Other" end
                local Tags={}
                local function Push(Value)
                    Value=tostring(Value or "")
                    if Value~="" then table.insert(Tags,string.lower(Value)) end
                end
                pcall(function() Push(Tool.ToolTip) end)
                for _,Attr in ipairs({"ToolTip","Type","WeaponType","Category","Class","ItemType"}) do
                    pcall(function() Push(Tool:GetAttribute(Attr)) end)
                end
                local Joined=table.concat(Tags," ")
                if string.find(Joined,"melee",1,true) or string.find(Joined,"fighting style",1,true) then return "Melee" end
                if string.find(Joined,"sword",1,true) then return "Sword" end
                if string.find(Joined,"gun",1,true) or string.find(Joined,"rifle",1,true) then return "Gun" end
                if string.find(Joined,"blox fruit",1,true) or string.find(Joined,"demon fruit",1,true) or Joined=="fruit" then return "Blox Fruit" end

                if Tool:FindFirstChild("EatRemote") then return "Other" end
                if Tool:FindFirstChild("RemoteFunctionShoot") or Tool:FindFirstChild("RemoteEventShoot") then return "Gun" end
                return "Other"
            end
            local function BloxCombatTool(Tool)
                return Tool and Tool:IsA("Tool") and BloxToolCategory(Tool)~="Other"
            end
            local function BloxToolOptionsForType(TypeName)
                TypeName=tostring(TypeName or State.BloxGrindType or "Melee")
                local First=(TypeName=="Any Tool") and "Any Tool" or ("Auto "..TypeName)
                local Out,Seen={First},{[First]=true}
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Tool in ipairs(Container:GetChildren()) do
                            if BloxCombatTool(Tool) then
                                local Category=BloxToolCategory(Tool)
                                if (TypeName=="Any Tool" or Category==TypeName) and not Seen[Tool.Name] then
                                    Seen[Tool.Name]=true
                                    table.insert(Out,Tool.Name)
                                end
                            end
                        end
                    end
                end
                table.sort(Out,function(A,B)
                    if A==B then return false end
                    if A==First then return true end
                    if B==First then return false end
                    return string.lower(A)<string.lower(B)
                end)
                return Out
            end
            local function AutoBloxToolChoice(Filter)
                Filter=tostring(Filter or "")
                return Filter=="" or Filter=="Any Tool" or string.sub(Filter,1,5)=="Auto "
            end
            local function EquippedBloxTool(Filter,Category)
                Category=tostring(Category or State.BloxGrindType or "Any Tool")
                local C,H,BP=Character(),Humanoid(),Player:FindFirstChildOfClass("Backpack")
                if not C or not H then return nil end
                local IsAuto=AutoBloxToolChoice(Filter)
                local Wanted=string.lower(tostring(Filter or ""))
                local function CategoryMatches(Tool)
                    return BloxCombatTool(Tool) and (Category=="Any Tool" or BloxToolCategory(Tool)==Category)
                end
                local function ExactMatches(Tool)
                    return CategoryMatches(Tool) and string.lower(Tool.Name)==Wanted
                end

                local Current=C:FindFirstChildOfClass("Tool")
                if Current then
                    if IsAuto and CategoryMatches(Current) then return Current end
                    if not IsAuto and ExactMatches(Current) then return Current end
                end
                if BP then
                    if IsAuto then
                        for _,Tool in ipairs(BP:GetChildren()) do
                            if CategoryMatches(Tool) then
                                pcall(function() H:EquipTool(Tool) end)
                                return Tool
                            end
                        end

                        for _,Tool in ipairs(BP:GetChildren()) do
                            if Tool:IsA("Tool") and not Tool:FindFirstChild("EatRemote") then
                                pcall(function() H:EquipTool(Tool) end)
                                return Tool
                            end
                        end
                    else

                        for _,Tool in ipairs(BP:GetChildren()) do
                            if ExactMatches(Tool) then
                                pcall(function() H:EquipTool(Tool) end)
                                return Tool
                            end
                        end
                    end
                end
                return nil
            end

            local function BloxSkillsRoot()
                local PG=Player:FindFirstChildOfClass("PlayerGui")
                local Main=PG and PG:FindFirstChild("Main")
                return Main and (Main:FindFirstChild("Skills") or Main:FindFirstChild("Skills",true)) or nil
            end
            BloxMoveAppearsUnlocked=function(KeyName)
                if not State.BloxOnlyUnlockedMoves then return true end
                local Skills=BloxSkillsRoot()
                if not Skills then return true end
                local KeyLower=string.lower(tostring(KeyName or ""))
                local Found=false
                for _,Obj in ipairs(Skills:GetDescendants()) do
                    local Name=string.lower(tostring(Obj.Name or ""))
                    local Text=""
                    if Obj:IsA("TextLabel") or Obj:IsA("TextButton") then Text=string.lower(tostring(Obj.Text or "")) end
                    if Name==KeyLower or Text==KeyLower or string.find(Text,"["..KeyLower.."]",1,true) then
                        Found=true
                        local Node=Obj
                        while Node and Node~=Skills do
                            if Node:IsA("GuiObject") and Node.Visible==false then return false end
                            Node=Node.Parent
                        end
                        return true
                    end
                end
                return not Found
            end

            local BloxNetCache=nil
            local function BloxNetRemotes()
                if BloxNetCache then
                    local A,H=BloxNetCache.Attack,BloxNetCache.Hit
                    if A and A.Parent and H and H.Parent then return A,H end
                end
                local Modules=ReplicatedStorage:FindFirstChild("Modules")
                local Net=Modules and Modules:FindFirstChild("Net")
                if not Net then return nil,nil end
                local Attack=Net:FindFirstChild("RE/RegisterAttack")
                local Hit=Net:FindFirstChild("RE/RegisterHit")
                if Attack and Hit then
                    BloxNetCache={Attack=Attack,Hit=Hit}
                    return Attack,Hit
                end
                return nil,nil
            end

            local BloxCombatControllerCache=nil
            local function FindCombatController(Value,Depth,Seen)
                if Depth>4 or type(Value)~="table" then return nil end
                Seen=Seen or {}
                if Seen[Value] then return nil end
                Seen[Value]=true
                if type(Value.activeController)=="table" then
                    local C=Value.activeController
                    if type(C.attack)=="function" then return C end
                end
                if type(Value.attack)=="function" and (Value.blades~=nil or Value.timeToNextAttack~=nil or Value.increment~=nil) then
                    return Value
                end
                local Count=0
                for _,Child in pairs(Value) do
                    Count+=1
                    if Count>80 then break end
                    if type(Child)=="table" then
                        local Found=FindCombatController(Child,Depth+1,Seen)
                        if Found then return Found end
                    end
                end
                return nil
            end
            local function ResolveCombatFrameworkController()
                if type(BloxCombatControllerCache)=="table" and type(BloxCombatControllerCache.attack)=="function" then
                    return BloxCombatControllerCache
                end
                local PS=Player:FindFirstChild("PlayerScripts")
                local CF=PS and (PS:FindFirstChild("CombatFramework") or PS:FindFirstChild("CombatFramework",true))
                if not CF or not CF:IsA("ModuleScript") then return nil end
                local Ok,Module=pcall(require,CF)
                if not Ok then return nil end
                local Controller=FindCombatController(Module,0,{})
                if not Controller then
                    local Upvalues=nil
                    if type(getupvalues)=="function" then
                        pcall(function() Upvalues=getupvalues(Module) end)
                    elseif debug and type(debug.getupvalues)=="function" then
                        pcall(function() Upvalues=debug.getupvalues(Module) end)
                    end
                    if type(Upvalues)=="table" then Controller=FindCombatController(Upvalues,0,{}) end
                end
                if Controller then BloxCombatControllerCache=Controller end
                return Controller
            end
            TrackConnection(Player.CharacterAdded:Connect(function()
                BloxCombatControllerCache=nil
                BloxNetCache=nil
            end))

            local function TryCombatFrameworkAttack(Tool)

                local Controller=ResolveCombatFrameworkController()
                if type(Controller)~="table" or type(Controller.attack)~="function" then return false end
                local Did=false
                local Ok=pcall(function()
                    if Controller.timeToNextAttack~=nil then Controller.timeToNextAttack=0 end
                    if Controller.timeToNextBlock~=nil then Controller.timeToNextBlock=0 end
                    if Controller.attacking~=nil then Controller.attacking=false end
                    if Controller.blocking~=nil then Controller.blocking=false end
                    if Controller.increment~=nil then Controller.increment=3 end
                    local Reach=State.BloxFastAttack and math.min(EffectiveBloxM1Reach(),30) or EffectiveBloxM1Reach()
                    Controller.hitboxMagnitude=Reach
                    if Controller.hitboxRadius~=nil then Controller.hitboxRadius=Reach end
                    if Controller.attackRadius~=nil then Controller.attackRadius=Reach end

                    local Rig=ReplicatedStorage:FindFirstChild("RigControllerEvent",true)
                    if Tool and Rig and Rig:IsA("RemoteEvent") then
                        local ToolName=tostring(Tool.Name)
                        local Now=os.clock()
                        if Runtime.BloxLastFrameworkWeapon~=ToolName or Now-(tonumber(Runtime.BloxLastFrameworkWeaponAt) or 0)>=0.75 then
                            Runtime.BloxLastFrameworkWeapon=ToolName
                            Runtime.BloxLastFrameworkWeaponAt=Now
                            pcall(function() Rig:FireServer("weaponChange",ToolName) end)
                        end
                    end
                    Controller:attack()
                    Did=true
                end)
                if not Ok then
                    BloxCombatControllerCache=nil
                    return false
                end
                return Did
            end

            local function BloxMousePointForEnemy(Enemy)
                local Cam=workspace.CurrentCamera
                if not Cam then return Vector2.new(640,360) end
                local Part=Enemy and (Enemy:FindFirstChild("Head") or GetRoot(Enemy))
                if Part then
                    local Screen,Visible=Cam:WorldToViewportPoint(Part.Position)
                    if Visible then return Vector2.new(Screen.X,Screen.Y) end
                end
                local View=Cam.ViewportSize
                return Vector2.new(View.X/2,View.Y/2)
            end

            local function ToolLeftClickAttack(Tool,Enemy)
                if not Tool or not Enemy then return false end
                local Remote=Tool:FindFirstChild("LeftClickRemote")
                local ER=GetRoot(Enemy)
                local Me=Root()
                if not Remote or not ER or not Me then return false end
                local Delta=ER.Position-Me.Position
                if Delta.Magnitude<0.01 then return false end
                return pcall(function()
                    Remote:FireServer(Delta.Unit,1)
                end)
            end

            local function LegacyNetAttack(Enemy)

                if not Enemy or not Enemy.Parent then return false end
                local H=Enemy:FindFirstChildOfClass("Humanoid")
                local BasePart=Enemy:FindFirstChild("Head") or GetRoot(Enemy)
                local Me=Root()
                if not H or H.Health<=0 or not BasePart or not Me then return false end

                local RegisterAttack,RegisterHit=BloxNetRemotes()
                if not RegisterAttack or not RegisterHit then return false end

                local Reach=EffectiveBloxM1Reach()
                if (BasePart.Position-Me.Position).Magnitude>Reach then return false end
                local Hits={{Enemy,BasePart}}

                local AttackOK=pcall(function()
                    RegisterAttack:FireServer(math.clamp(tonumber(State.BloxFastAttackInterval) or 0.075,0,0.25))
                end)
                if not AttackOK then return false end
                local HitOK=pcall(function()
                    RegisterHit:FireServer(BasePart,Hits)
                end)
                return HitOK
            end

            local function NormalBloxM1(Tool,Enemy,HoldTime)
                local Did=false
                local Point=BloxMousePointForEnemy(Enemy)
                local Hold=math.clamp(tonumber(HoldTime) or 0.055,0.012,0.16)

                AimBloxTarget(Enemy,true)

                if Tool then
                    pcall(function()
                        Tool:Activate()
                        Did=true
                    end)
                    if type(firesignal)=="function" then
                        pcall(function()
                            firesignal(Tool.Activated)
                            Did=true
                        end)
                    end
                end

                if ToolLeftClickAttack(Tool,Enemy) then Did=true end

                if State.BloxSimulatedMouseInput and not UserInputService:GetFocusedTextBox() then
                    if type(mousemoveabs)=="function" then pcall(function() mousemoveabs(Point.X,Point.Y) end) end
                    if type(mouse1click)=="function" then
                        if pcall(mouse1click) then Did=true end
                    elseif type(mouse1press)=="function" and type(mouse1release)=="function" then
                        if pcall(function() mouse1press(); task.wait(Hold); mouse1release() end) then Did=true end
                    end
                    local OkVIM,VIM=pcall(function() return game:GetService("VirtualInputManager") end)
                    if OkVIM and VIM then
                        pcall(function()
                            VIM:SendMouseButtonEvent(Point.X,Point.Y,0,true,game,0)
                            task.wait(Hold)
                            VIM:SendMouseButtonEvent(Point.X,Point.Y,0,false,game,0)
                            Did=true
                        end)
                    end
                end

                return Did
            end

            local LastBloxFastAttack=0
            local LastMissingToolNotice=0
            local function AttackBloxTarget(Enemy,ToolFilter,ToolCategory,Force)
                if not Enemy or not Enemy.Parent then return false end
                local H=Enemy:FindFirstChildOfClass("Humanoid")
                local ER=GetRoot(Enemy)
                local Me=Root()
                if not H or H.Health<=0 or not ER or not Me then return false end

                local Tool=EquippedBloxTool(ToolFilter,ToolCategory)
                if not Tool then Tool=EquippedBloxTool("Any Tool","Any Tool") end
                if not Tool then
                    local C=Character()
                    local Current=C and C:FindFirstChildOfClass("Tool")
                    if Current and not Current:FindFirstChild("EatRemote") then Tool=Current end
                end

                if not Tool then
                    if os.clock()-LastMissingToolNotice>4 then
                        LastMissingToolNotice=os.clock()
                        Notify("Blox Fruits","Auto Farm could not find an attack Tool in Backpack/Character.")
                    end
                    return false
                end

                local MyHum=Humanoid()
                if Tool.Parent~=Character() and MyHum then
                    pcall(function() MyHum:EquipTool(Tool) end)
                    task.wait()
                end

                if State.BloxAimBasicAttack then AimBloxTarget(Enemy,true) end

                local Distance=(Me.Position-ER.Position).Magnitude
                local Reach=EffectiveBloxM1Reach()
                if Distance>Reach+2 then return false end

                local Now=os.clock()
                local AutoCombat=(Runtime.BloxAutoLevelActive==true or Runtime.BloxMaterialFarmActive==true or Runtime.BloxRaidCombatActive==true)
                local FastAttack=State.BloxFastAttack==true
                local Interval=FastAttack and math.clamp(tonumber(State.BloxFastAttackInterval) or 0.025,0.020,0.060)
                    or (AutoCombat and 0.070 or math.clamp(tonumber(State.BloxFastAttackInterval) or 0.075,0.045,0.25))
                -- Keep Fast Attack quick on healthy FPS, but back off automatically when the client is
                -- struggling so combat does not turn the whole Roblox client into a stutter loop.
                local LiveFPS=tonumber(LiveTelemetry and LiveTelemetry.FPS) or 60
                if FastAttack and LiveFPS>0 then
                    if LiveFPS<30 then Interval=math.max(Interval,0.045)
                    elseif LiveFPS<42 then Interval=math.max(Interval,0.034)
                    elseif LiveFPS<52 then Interval=math.max(Interval,0.027) end
                end

                -- Never bypass the attack cadence just because a farm loop asked for a forced hit.
                -- The old Force=true path could run once per Heartbeat and then fire several
                -- different M1 implementations in that same tick, which could keep hitting an
                -- NPC while Blox Fruits was already destroying its Humanoid/effect objects.
                if Now-LastBloxFastAttack<Interval then return true end
                LastBloxFastAttack=Now

                local function TargetStillAlive()
                    if not Enemy or not Enemy.Parent then return false end
                    local LiveHum=Enemy:FindFirstChildOfClass("Humanoid")
                    local LiveRoot=GetRoot(Enemy)
                    return LiveHum~=nil and LiveHum.Parent~=nil and LiveHum.Health>0
                        and LiveRoot~=nil and LiveRoot.Parent~=nil
                end

                local Did=false
                if FastAttack then
                    -- Single-target Fast Attack. CombatFramework's controller attack uses a radius
                    -- hitbox and can register a second nearby NPC. Prefer the exact Enemy hit list.
                    Runtime.BloxFastAttackLockedTarget=Enemy
                    if TargetStillAlive() then
                        Runtime.BloxLastLegacyFastAttack=tonumber(Runtime.BloxLastLegacyFastAttack) or 0
                        if Now-Runtime.BloxLastLegacyFastAttack>=Interval then
                            Runtime.BloxLastLegacyFastAttack=Now
                            Did=LegacyNetAttack(Enemy)==true
                        end
                    end
                    -- Only use the targeted left-click remote as a compatibility fallback.
                    -- Do not call CombatFramework/NormalBloxM1 here because those can hit by radius.
                    if not Did and TargetStillAlive() then
                        Did=ToolLeftClickAttack(Tool,Enemy)==true
                    end
                elseif TargetStillAlive() then
                    Runtime.BloxFastAttackLockedTarget=nil
                    Did=NormalBloxM1(Tool,Enemy,0.085)
                end

                Runtime.BloxLastAttackTool=Tool.Name
                Runtime.BloxLastAttackDistance=math.floor(Distance*10+0.5)/10
                return Did
            end

            local function FarmBloxEnemy(Enemy)
                local FarmGeneration=Runtime.BloxFarmGeneration
                if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end
                local Enemies=workspace:FindFirstChild("Enemies")
                if not Enemy or not Enemies or not Enemy:IsDescendantOf(Enemies) or IsPlayerCharacter(Enemy) then return false end
                Runtime.Movement.Guard()
                local H=Enemy:FindFirstChildOfClass("Humanoid")
                local R=GetRoot(Enemy)
                if not H or not R or H.Health<=0 then return false end
                -- Display-only pointer used by the Dynamic Island for live target/boss HP.
                -- It never changes target selection or combat behavior.
                Runtime.BloxCurrentCombatTarget=Enemy
                Runtime.BloxCurrentCombatTargetAt=os.clock()

                -- FarmBloxEnemy is the shared combat path for Auto Farm, materials, raids,
                -- selected enemy/boss farms, and other farming callers. Mark it so every farming
                -- mode receives the same stable hover-lane behavior.
                Runtime.BloxFarmEnemyActive=true
                -- Only Auto Farm and Raid use the no-rise/no-drop kill handoff. A handoff token is
                -- created when the previous enemy dies and consumed by the very next farm target.
                local DirectHandoff=(Runtime.BloxAutoLevelActive==true or Runtime.BloxRaidCombatActive==true)
                    and os.clock()<(tonumber(Runtime.BloxDirectEnemyHandoffUntil) or 0)
                Runtime.BloxDirectEnemyHandoffActive=DirectHandoff
                if not BloxCombatSafetyStep(Enemy) then
                    Runtime.BloxDirectEnemyHandoffActive=false
                    Runtime.BloxFarmEnemyActive=false
                    return true
                end

                ExpandBloxEnemyHitbox(Enemy)
                BringMatchingMobs(Enemy)

                local Me=Root()
                local Hover=BloxHoverCFrame(R)
                if not Hover then
                    Runtime.BloxDirectEnemyHandoffActive=false
                    Runtime.BloxFarmEnemyActive=false
                    return false
                end
                if Hover and Me and (Me.Position-Hover.Position).Magnitude>8 then
                    local Reached
                    if DirectHandoff and type(Runtime.BloxDirectEnemyHandoff)=="function" then
                        -- Consume immediately so retries/combat corrections cannot accidentally
                        -- treat a later movement as another post-kill handoff.
                        Runtime.BloxDirectEnemyHandoffUntil=0
                        Reached=Runtime.BloxDirectEnemyHandoff(Enemy)
                    else
                        Reached=TravelAboveBloxTarget(Enemy)
                    end
                    if not Reached then
                        Runtime.BloxDirectEnemyHandoffActive=false
                        Runtime.BloxFarmEnemyActive=false
                        return false
                    end
                end
                Runtime.BloxDirectEnemyHandoffActive=false
                Runtime.Movement.Guard()

                local StartHealth=H.Health
                local LastHealth=H.Health
                local LastDamageAt=os.clock()
                local HardDeadline=os.clock()+((Runtime.BloxAutoLevelActive or Runtime.BloxMaterialFarmActive or Runtime.BloxRaidCombatActive) and 5.0 or 2.4)

                repeat
                    if not Runtime.BloxFarmRunActive(FarmGeneration) then break end
                    if Runtime.BloxAutoLevelActive and Runtime.BloxFruitInterruptPending then
                        Runtime.BloxCombatLastResult="Fruit detected • yielding Auto Farm movement"
                        break
                    end
                    Runtime.Movement.Guard()
                    if not Enemy:IsDescendantOf(Enemies) or IsPlayerCharacter(Enemy) then break end
                    if Runtime.BloxAutoLevelActive and Runtime.BloxQuestStillActive and not Runtime.BloxQuestStillActive() then break end
                    H=Enemy:FindFirstChildOfClass("Humanoid")
                    R=GetRoot(Enemy)
                    Me=Root()
                    if not H or H.Health<=0 or not R or not Me then break end
                    if not BloxCombatSafetyStep(Enemy) then break end

                    ExpandBloxEnemyHitbox(Enemy)
                    BringMatchingMobs(Enemy)
                    AimBloxTarget(Enemy,false)

                    local HoverNow=BloxHoverCFrame(R)
                    if not HoverNow then break end
                    if HoverNow and (Me.Position-HoverNow.Position).Magnitude>3 then
                        if not ProfileTravelToCFrame(HoverNow) then break end
                    end
                    Runtime.Movement.Guard()
                    if not Runtime.BloxFarmRunActive(FarmGeneration) or not BloxCombatSafetyStep(Enemy) then break end
                    Me=Root()
                    if not Me then break end
                    pcall(function()
                        if HoverNow and (Me.Position-HoverNow.Position).Magnitude<=6 then
                            Me.CFrame=HoverNow
                        end
                        Me.AssemblyLinearVelocity=Vector3.zero
                        Me.AssemblyAngularVelocity=Vector3.zero
                    end)

                    if os.clock()-(Runtime.BloxLastBusoCheck or 0)>1.0 then
                        Runtime.BloxLastBusoCheck=os.clock()
                        local C=Character()
                        if C and not C:FindFirstChild("HasBuso") then
                            pcall(function() QueryRemote(BloxCommF(),"Buso") end)
                        end
                    end

                    local ToolFilter=State.SelectedTool
                    local ToolCategory=State.BloxGrindType or "Melee"
                    local Pct=H.MaxHealth>0 and (H.Health/H.MaxHealth*100) or 100
                    if State.BloxMasteryEnabled and State.BloxMasteryTool and State.BloxMasteryTool~="Any Tool"
                        and Pct<=(tonumber(State.BloxMasterySwitch) or 20) then
                        ToolFilter=State.BloxMasteryTool
                        ToolCategory="Any Tool"
                    end

                    AttackBloxTarget(Enemy,ToolFilter,ToolCategory,true)
                    UseBloxAbilities(Enemy)

                    if H.Health<LastHealth then
                        LastHealth=H.Health
                        LastDamageAt=os.clock()
                        Runtime.BloxCombatConfirmed=true
                        Runtime.BloxCombatLastConfirmedAt=os.clock()

                        if (Runtime.BloxAutoLevelActive or Runtime.BloxRaidCombatActive) and (tonumber(Runtime.BloxAutoContactBias) or 0)<0
                            and os.clock()-(Runtime.BloxAutoLastRaiseAfterHit or 0)>0.75 then
                            Runtime.BloxAutoLastRaiseAfterHit=os.clock()
                            Runtime.BloxAutoContactBias=math.min((tonumber(Runtime.BloxAutoContactBias) or 0)+1,0)
                        end
                        Runtime.BloxCombatLastResult="M1 contact verified • enemy HP dropping"
                    elseif os.clock()-LastDamageAt>0.65 then

                        if Runtime.BloxAutoLevelActive or Runtime.BloxRaidCombatActive then
                            Runtime.BloxCombatConfirmed=false
                            Runtime.BloxAutoContactBias=math.max((tonumber(Runtime.BloxAutoContactBias) or 0)-2,-6)
                            local RetryHover=BloxHoverCFrame(R)
                            local RetryRoot=Root()
                            if RetryHover and RetryRoot and (RetryRoot.Position-RetryHover.Position).Magnitude>1.5 then
                                ProfileTravelToCFrame(RetryHover)
                            end
                        end
                        local Tool=Character() and Character():FindFirstChildOfClass("Tool")
                        if State.BloxFastAttack then
                            -- Preserve the same exact target during recovery; never widen to a second NPC.
                            if not LegacyNetAttack(Enemy) and Tool then ToolLeftClickAttack(Tool,Enemy) end
                            Runtime.BloxCombatLastResult="No HP change • retrying exact fast-attack target"
                        else
                            Runtime.BloxRecoveryAttackMode=((tonumber(Runtime.BloxRecoveryAttackMode) or 0)%3)+1
                            local RecoveryMode=Runtime.BloxRecoveryAttackMode
                            if RecoveryMode==1 and Tool then
                                NormalBloxM1(Tool,Enemy,0.075)
                            elseif RecoveryMode==2 and Tool then
                                TryCombatFrameworkAttack(Tool)
                            else
                                LegacyNetAttack(Enemy)
                            end
                            Runtime.BloxCombatLastResult="No HP change • adjusting hover and cycling one M1 fallback"
                        end
                        LastDamageAt=os.clock()
                    end

                    local CombatWait=(Runtime.BloxAutoLevelActive or Runtime.BloxMaterialFarmActive or Runtime.BloxRaidCombatActive) and (State.BloxFastAttack and 0.024 or 0.070) or math.clamp(tonumber(State.BloxFastAttackInterval) or 0.075,0.055,0.14)
                    local FarmFPS=tonumber(LiveTelemetry and LiveTelemetry.FPS) or 60
                    if FarmFPS>0 and FarmFPS<35 then CombatWait=math.max(CombatWait,0.040) end
                    task.wait(CombatWait)
                until os.clock()>=HardDeadline

                Runtime.BloxLastEnemyHealthStart=StartHealth
                Runtime.BloxLastEnemyHealthEnd=H and H.Health or 0
                if Runtime.BloxFastAttackLockedTarget==Enemy then Runtime.BloxFastAttackLockedTarget=nil end
                if not H or H.Health<=0 or not Enemy.Parent then
                    BloxEnemySnapshotState.At=0
                    -- Freeze the just-finished hover altitude briefly. If the next mob is on the
                    -- same flat ground, BloxHoverCFrame reuses this exact Y and the character slides
                    -- horizontally to it instead of doing the old kill -> rise/drop -> next kill.
                    local HandoffRoot=Root()
                    if HandoffRoot then
                        Runtime.BloxStableHoverY=HandoffRoot.Position.Y
                        Runtime.BloxStableHoverAt=os.clock()
                        local ActiveZone=Runtime.BloxActiveMovementZone
                        if ActiveZone then
                            ActiveZone.HoverY=HandoffRoot.Position.Y
                            ActiveZone.LastSeen=os.clock()
                        end
                        Runtime.BloxHoverHandoffUntil=os.clock()+3.25
                        if Runtime.BloxAutoLevelActive==true or Runtime.BloxRaidCombatActive==true then
                            Runtime.BloxDirectEnemyHandoffUntil=os.clock()+3.25
                        end
                    end
                end
                if Runtime.BloxCurrentCombatTarget==Enemy then Runtime.BloxCurrentCombatTarget=nil end
                Runtime.BloxFarmEnemyActive=false
                return true
            end

            local function GuiActuallyVisible(Object)
                if not Object then return false end
                local Node=Object
                while Node do
                    if Node:IsA("GuiObject") and not Node.Visible then return false end
                    if Node:IsA("ScreenGui") and not Node.Enabled then return false end
                    Node=Node.Parent
                end
                return Object:IsDescendantOf(Player:FindFirstChildOfClass("PlayerGui") or Player)
            end
            local function QuestRoot()
                local PG=Player:FindFirstChildOfClass("PlayerGui")
                local Main=PG and PG:FindFirstChild("Main")
                local Candidates={}

                local Direct=Main and Main:FindFirstChild("Quest")
                if Direct and GuiActuallyVisible(Direct) then return Direct end
                if Main and Main:FindFirstChild("Quest") then table.insert(Candidates,Main.Quest) end
                if PG and PG:FindFirstChild("TrackedQuestFrame") then table.insert(Candidates,PG.TrackedQuestFrame) end
                for _,Candidate in ipairs(Candidates) do
                    if GuiActuallyVisible(Candidate) then
                        for _,Obj in ipairs(Candidate:GetDescendants()) do
                            if (Obj:IsA("TextLabel") or Obj:IsA("TextButton")) and GuiActuallyVisible(Obj) then
                                local Text=tostring(Obj.Text or ""):gsub("<[^>]*>","")
                                if Text:match("%d+%s*/%s*%d+") or Text:lower():match("defeat%s+%d+") then
                                    return Candidate
                                end
                            end
                        end
                    end
                end
                return nil
            end
            local function QuestVisible()
                return QuestRoot()~=nil
            end
            local function QuestText()
                local Quest=QuestRoot()
                if not Quest then return "" end
                local Parts={}
                for _,Obj in ipairs(Quest:GetDescendants()) do
                    if (Obj:IsA("TextLabel") or Obj:IsA("TextButton")) and GuiActuallyVisible(Obj) and Obj.Text and #Obj.Text>1 then
                        table.insert(Parts,tostring(Obj.Text))
                    end
                end
                return table.concat(Parts," ")
            end

            local function QuestTitleText()
                local Quest=QuestRoot()
                local Container=Quest and Quest:FindFirstChild("Container")
                local QuestTitle=Container and Container:FindFirstChild("QuestTitle")
                local Title=QuestTitle and QuestTitle:FindFirstChild("Title")
                if Title and GuiActuallyVisible(Title) and (Title:IsA("TextLabel") or Title:IsA("TextButton")) then
                    return tostring(Title.Text or "")
                end
                if Quest then

                    local Best=""
                    for _,Obj in ipairs(Quest:GetDescendants()) do
                        if (Obj:IsA("TextLabel") or Obj:IsA("TextButton"))
                            and GuiActuallyVisible(Obj) then
                            local Text=tostring(Obj.Text or "")
                            if #Text>#Best and string.find(string.lower(Text),"defeat",1,true) then
                                Best=Text
                            end
                        end
                    end
                    if Best~="" then return Best end
                    for _,Obj in ipairs(Quest:GetDescendants()) do
                        if (Obj:IsA("TextLabel") or Obj:IsA("TextButton"))
                            and GuiActuallyVisible(Obj) and Obj.Name=="Title" and #tostring(Obj.Text or "")>0 then
                            return tostring(Obj.Text or "")
                        end
                    end
                end
                return QuestText()
            end

            local function QuestProgress()
                local Text=QuestTitleText():gsub("<[^>]*>","")
                local A,B=string.match(Text,"(%d+)%s*/%s*(%d+)")
                if A and B then
                    return tonumber(A),tonumber(B),Text
                end

                local All=QuestText():gsub("<[^>]*>","")
                A,B=string.match(All,"(%d+)%s*/%s*(%d+)")
                return tonumber(A),tonumber(B),All
            end
            local function DetectActiveQuest(Expected)
                local Visible=QuestVisible()
                local Title=QuestTitleText()
                local FullText=QuestText()
                local Current,Goal=QuestProgress()
                local CleanTitle=string.lower(Title:gsub("<[^>]*>","")):gsub("[^%w]"," "):gsub("%s+"," ")
                local Search=CompactEnemyName(Title)
                local function TitleNames(Mob)
                    local Name=string.lower(StripEnemyName(Mob)):gsub("[^%w]"," "):gsub("%s+"," ")
                    local Padded=" "..CleanTitle.." "
                    return string.find(Padded," "..Name.." ",1,true)~=nil
                        or string.find(Padded," "..Name.."s ",1,true)~=nil
                end
                local Detected=nil
                local BestLength=0
                if Visible and Search~="" then
                    for _,Entry in ipairs(ReadBloxQuests()) do
                        if QuestLevelBelongsToSea(Entry.LevelReq) then
                            local MobKey=CompactEnemyName(Entry.MobName)
                            if #MobKey>BestLength and TitleNames(Entry.MobName) then
                                Detected=Entry
                                BestLength=#MobKey
                            end
                        end
                    end
                end
                local ExpectedKey=Expected and CompactEnemyName(Expected.MobName) or ""
                local Matched=Visible and ExpectedKey~="" and TitleNames(Expected.MobName)
                    and (not Detected or CompactEnemyName(Detected.MobName)==ExpectedKey)
                if not Goal and Detected and Detected.RequiredAmount then Goal=Detected.RequiredAmount end
                if not Goal and Matched and Expected and Expected.RequiredAmount then Goal=Expected.RequiredAmount end
                local Complete=Visible and Current~=nil and Goal~=nil and Goal>0 and Current>=Goal
                local StateName=not Visible and "none" or (Complete and "complete" or (Matched and "matched" or "different"))
                local Snapshot={
                    Visible=Visible,Title=Title,Text=FullText,Current=Current,Goal=Goal,
                    Detected=Detected,Matched=Matched,Complete=Complete,State=StateName,
                    Source=Visible and "PlayerGui.Main.Quest" or "No active quest UI"
                }
                Runtime.BloxActiveQuestSnapshot=Snapshot
                Runtime.BloxQuestDetectionSource=Snapshot.Source
                Runtime.BloxDetectedQuestMob=Detected and Detected.MobName or nil
                if Visible and Matched and Current~=nil and Goal~=nil then
                    Runtime.BloxLastQuestCurrent=Current
                    Runtime.BloxLastQuestGoal=Goal
                end
                return Snapshot
            end
            Runtime.BloxQuestStillActive=function()
                if not Runtime.ActiveBloxQuest then return true end
                local Q=DetectActiveQuest(Runtime.ActiveBloxQuest)
                return Q.Matched and not Q.Complete
            end
            local function GuideEntryCFrame(Key,Entry)
                local function Convert(Value)
                    if typeof(Value)=="CFrame" then return Value end
                    if typeof(Value)=="Vector3" then return CFrame.new(Value) end
                    if type(Value)=="table" then
                        local P=Value.CFrame or Value.Position or Value.Pos
                        if typeof(P)=="CFrame" then return P end
                        if typeof(P)=="Vector3" then return CFrame.new(P) end
                    end
                    return nil
                end
                return Convert(Key) or Convert(Entry)
            end
            local function ResolveQuestNPC(Q)
                if not Q then return Q end
                local Guide=BloxGuide()
                local List=Guide and Guide.Data and Guide.Data.NPCList
                if type(List)=="table" then
                    local Preferred=Guide.Data.LastClosestNPC
                    local BestKey,BestEntry,BestIndex,BestScore=nil,nil,nil,-math.huge
                    for Key,Entry in pairs(List) do
                        if type(Entry)=="table" and type(Entry.Levels)=="table" then
                            for Index,Req in pairs(Entry.Levels) do
                                if tonumber(Req)==tonumber(Q.LevelReq) then

                                    local Score=(tonumber(Index)==tonumber(Q.QuestIndex) and 20 or 0)
                                    if Preferred and tostring(Entry.NPCName or Entry.Name)==tostring(Preferred) then Score+=40 end
                                    if Score>BestScore then BestKey,BestEntry,BestIndex,BestScore=Key,Entry,Index,Score end
                                    if tonumber(Index)==tonumber(Q.QuestIndex) then break end
                                end
                            end
                        end
                    end
                    if BestEntry then
                        Q.NPCName=BestEntry.NPCName or BestEntry.Name or Q.NPCName
                        Q.NPCPosition=GuideEntryCFrame(BestKey,BestEntry) or Q.NPCPosition
                        Q.GuideQuestIndex=BestIndex
                    end
                end
                return Q
            end
            local function QuestMatchesTarget(TargetName)
                local Snapshot=DetectActiveQuest({MobName=TargetName})
                return Snapshot.Matched==true
            end
            local function AttachKnownQuestRoute(Q)
                if not Q then return nil end
                local Route=BloxKnownQuestRoutes[CompactEnemyName(Q.MobName)]
                if Route and Route.Sea==BloxSeaNumber() then
                    Q.NPCPosition=Q.NPCPosition or Route.QuestCF
                    Q.MobPosition=Route.MobCF
                    Q.EntrancePosition=Route.Entrance
                end
                return Q
            end
            local function KnownQuestForLevel()
                if BloxSeaNumber()~=2 then return nil end
                local Level=BloxLevel()
                for _,Route in pairs(BloxKnownQuestRoutes) do
                    if Level>=Route.Min and Level<=Route.Max then
                        return {
                            QuestName=Route.QuestName,QuestIndex=Route.QuestIndex,LevelReq=Route.Min,
                            MobName=Route.Mob,RawMobName=Route.Mob,DisplayName=Route.Mob,IsBoss=false,
                            NPCPosition=Route.QuestCF,MobPosition=Route.MobCF,EntrancePosition=Route.Entrance
                        }
                    end
                end
                return nil
            end
            local function BloxQuestData()
                local Level=BloxLevel()
                local Best=nil
                local ForceNormal=Runtime.BloxPreferNormalQuestOnce==true
                local SkipBoss=State.BloxEfficiency or ForceNormal
                for _,Q in ipairs(ReadBloxQuests()) do
                    if Q.LevelReq<=Level and QuestLevelBelongsToSea(Q.LevelReq)
                        and (not SkipBoss or not Q.IsBoss) then
                        if not Best or Q.LevelReq>Best.LevelReq then Best=Q end
                    end
                end
                Best=AttachKnownQuestRoute(ResolveQuestNPC(Best))
                if not Best and SkipBoss then Best=KnownQuestForLevel() end
                if ForceNormal and Best and not Best.IsBoss then Runtime.BloxPreferNormalQuestOnce=nil end
                return Best
            end
            local function QuestForEnemy(Name,BossOnly)
                local Level=BloxLevel()
                local Want=CompactEnemyName(Name)
                local Best=nil
                if Want=="" or Want==CompactEnemyName("Nearest Enemy") or Want==CompactEnemyName("Nearest Boss") then return nil end
                for _,Q in ipairs(ReadBloxQuests()) do
                    if Q.LevelReq<=Level and QuestLevelBelongsToSea(Q.LevelReq)
                        and Q.IsBoss==BossOnly and CompactEnemyName(Q.MobName)==Want then
                        if not Best or Q.LevelReq>Best.LevelReq then Best=Q end
                    end
                end
                return AttachKnownQuestRoute(ResolveQuestNPC(Best))
            end
            local function EnsureQuest(Q)
                if not Q then return false end
                local FarmGeneration=Runtime.BloxFarmGeneration
                if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end

                if QuestMatchesTarget(Q.MobName) then return true end

                if QuestVisible() and not QuestMatchesTarget(Q.MobName) then
                    QueryRemote(BloxCommF(),"AbandonQuest")
                    task.wait(0.18)
                    if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end
                end

                if not Q.NPCPosition then
                    local Route=BloxKnownQuestRoutes[CompactEnemyName(Q.MobName)]
                    if Route and Route.Sea==BloxSeaNumber() then
                        Q.NPCPosition=Route.QuestCF
                    end
                end

                if Q.NPCPosition then
                    local R=Root()
                    if not R or (R.Position-Q.NPCPosition.Position).Magnitude>10 then
                        ProfileTravelToCFrame(Q.NPCPosition*CFrame.new(0,3,2))
                        if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end
                    end

                    local Deadline=os.clock()+3
                    repeat
                        R=Root()
                        if R and (R.Position-Q.NPCPosition.Position).Magnitude<=10 then break end
                        task.wait(0.05)
                    until os.clock()>=Deadline
                elseif Q.NPCName then
                    GoBloxNPC(Q.NPCName)
                end

                if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end

                local AtNPC=Root()
                if not Q.NPCPosition or not AtNPC or (AtNPC.Position-Q.NPCPosition.Position).Magnitude>10 then
                    Runtime.BloxQuestLastFailure="Quest giver position could not be confirmed"
                    return false
                end
                if DetectActiveQuest(Q).Matched then return true end
                local Started=QueryRemote(BloxCommF(),"StartQuest",Q.QuestName,Q.QuestIndex)
                if not Started then return false end
                local SentAt=os.clock()
                local ConfirmDeadline=SentAt+2
                local Confirm=DetectActiveQuest(Q)
                repeat
                    if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end
                    if Confirm.Matched or (Confirm.Visible and not Confirm.Matched) then break end
                    task.wait(0.05)
                    Confirm=DetectActiveQuest(Q)
                until os.clock()>=ConfirmDeadline
                if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end
                Confirm=DetectActiveQuest(Q)
                if not Confirm.Matched then
                    Runtime.BloxQuestLastFailure=Confirm.Visible and "Wrong quest appeared" or "Quest UI did not appear"
                    return false
                end
                Runtime.BloxQuestLastFailure=nil

                BloxEnemySnapshotState.At=0
                pcall(function() QueryRemote(BloxCommF(),"SetSpawnPoint") end)
                return true
            end

            local AutoFarmQuest=nil
            Runtime.BloxSpawnPointQuestKey=Runtime.BloxSpawnPointQuestKey or nil
            local AutoFarmNextAcquire=0
            local AutoFarmTarget=nil
            local AutoFarmStatus="Idle"
            local AutoFarmQuestMissingSince=0
            local LastFarmStatusSignature=nil
            Runtime.BloxFailureCode=Runtime.BloxFailureCode or "NONE"
            Runtime.BloxFailureDetail=Runtime.BloxFailureDetail or ""
            local function BloxFail(Code,Detail)
                Runtime.BloxFailureCode=tostring(Code or "UNKNOWN")
                Runtime.BloxFailureDetail=tostring(Detail or "")
                Runtime.BloxFailureAt=os.clock()
                return false
            end
            local function BloxClearFailure()
                Runtime.BloxFailureCode="NONE"; Runtime.BloxFailureDetail=""
            end

            local function SetAutoFarmStatus(Text)
                AutoFarmStatus=tostring(Text or "Idle")
                if Runtime.BloxFarmStatusParagraph and Runtime.BloxFarmStatusParagraph.Set then
                    local QuestName=AutoFarmQuest and AutoFarmQuest.MobName or "None"
                    local TargetName=AutoFarmTarget and AutoFarmTarget.Parent and StripEnemyName(AutoFarmTarget.Name) or "None"
                    local ToolName=tostring(State.SelectedTool or ("Auto "..tostring(State.BloxGrindType)))
                    local QuestSignal=Runtime.BloxActiveQuestSnapshot and Runtime.BloxActiveQuestSnapshot.State or "none"
                    local QuestFailure=tostring(Runtime.BloxQuestLastFailure or "")
                    local EffectiveReach=Runtime.BloxAutoLevelActive and EffectiveBloxM1Reach() or (tonumber(State.BloxM1Reach) or 20)
                    local EffectiveHeight=Runtime.BloxAutoLevelActive and AutoBloxFarmHeight() or (tonumber(State.BloxFarmHeight) or 15)
                    local ContactState=Runtime.BloxCombatConfirmed and "VERIFIED" or "checking"
                    local FailureCode=tostring(Runtime.BloxFailureCode or "NONE")
                    local FailureDetail=tostring(Runtime.BloxFailureDetail or "")
                    local Signature=table.concat({AutoFarmStatus,tostring(QuestName),tostring(TargetName),tostring(State.BloxGrindType),ToolName,QuestSignal,QuestFailure,tostring(EffectiveReach),tostring(EffectiveHeight),ContactState,FailureCode,FailureDetail},"|")
                    if Signature==LastFarmStatusSignature then return end
                    LastFarmStatusSignature=Signature
                    Runtime.BloxFarmStatusParagraph:Set({
                        Title="Live Farm Status",
                        Content="State: "..AutoFarmStatus
                            .."\nQuest enemy: "..tostring(QuestName)
                            .."\nQuest signal: "..tostring(QuestSignal).." • "..tostring(Runtime.BloxQuestDetectionSource or "not checked")
                            ..(QuestFailure~="" and ("\nLast quest retry: "..QuestFailure) or "")
                            ..((FailureCode~="NONE") and ("\nFailure: "..FailureCode..(FailureDetail~="" and (" • "..FailureDetail) or "")) or "")
                            .."\nLive target: "..tostring(TargetName)
                            ..(Runtime.BloxQuestProgress and ("\nProgress: "..tostring(Runtime.BloxQuestProgress)) or "")
                            .."\nGrind: "..tostring(State.BloxGrindType).." • "..ToolName
                            .."\nAuto combat: "..tostring(math.floor(EffectiveReach+0.5)).." reach • "..tostring(math.floor(EffectiveHeight+0.5)).." hover • contact "..ContactState
                            ..(Runtime.BloxLastAttackTool and ("\nAttack: "..tostring(Runtime.BloxLastAttackTool).." @ "..tostring(Runtime.BloxLastAttackDistance or "?").." studs") or "")
                            ..(Runtime.BloxCombatLastResult and ("\nCombat: "..tostring(Runtime.BloxCombatLastResult)) or "")
                    })
                end
            end
            local function ResetAutoFarmProgression()
                Runtime.BloxFarmStage="FindQuest"
                Runtime.ActiveBloxQuest=nil
                Runtime.BloxMobQueue={}
                Runtime.BloxTargetQueueSnapshot={}
                Runtime.BloxTargetQueueCount=0
                Runtime.BloxActiveMovementZone=nil
                AutoFarmQuest=nil
                AutoFarmNextAcquire=0
                AutoFarmTarget=nil
                AutoFarmQuestMissingSince=0
                Runtime.BloxAutoFarmSeaProgressionActive=false
                Runtime.BloxActiveQuestSnapshot=nil
                Runtime.BloxQuestDetectionSource="Not checked"
                Runtime.BloxDetectedQuestMob=nil
                Runtime.BloxQuestLastFailure=nil
                BloxClearFailure()
                Runtime.BloxSafetyRecovering=false
                Runtime.BloxSafetyLastRetreat=nil
                Runtime.BloxAutoLastPlayerHealth=nil
                Runtime.BloxAutoDamageBoostUntil=0
                Runtime.BloxAutoContactBias=0
                Runtime.BloxAutoLastRaiseAfterHit=0
                Runtime.BloxCombatConfirmed=false
                Runtime.BloxCombatLastConfirmedAt=nil
                Runtime.BloxLastQuestCurrent=nil
                Runtime.BloxLastQuestGoal=nil
                Runtime.BloxJustKilledQuestMobAt=nil
                Runtime.BloxAutoFarmSelectedLevel=nil
                Runtime.BloxAutoFarmSelectedQuestReq=nil
                LastFarmStatusSignature=nil
                SetAutoFarmStatus("Idle")
            end
            local function LockedTargetValid(Target,Q)
                local Enemies=workspace:FindFirstChild("Enemies")
                if Target and Runtime.BloxFailedTargets and os.clock()<(Runtime.BloxFailedTargets[Target] or 0) then return false end
                if not Target or not Q or not Enemies or not Target:IsDescendantOf(Enemies)
                    or not Target:IsA("Model") or IsPlayerCharacter(Target) then return false end
                local H=Target:FindFirstChildOfClass("Humanoid")
                if not H or H.Health<=0 or not GetRoot(Target) then return false end
                return NormalName(StripEnemyName(Target.Name))==NormalName(StripEnemyName(Q.MobName))
            end


-- ==================================================================
-- [BH:BLOX] 3-TARGET QUEST QUEUE
-- Current target + two preselected next enemies; same-zone priority.
-- ==================================================================
            local function RefreshQuestTargetQueue(Q,CurrentTarget)
                if not Q then
                    Runtime.BloxMobQueue={}
                    Runtime.BloxTargetQueueSnapshot={}
                    Runtime.BloxTargetQueueCount=0
                    return Runtime.BloxMobQueue
                end

                local Me=Root()
                local CurrentZone=Runtime.BloxActiveMovementZone
                local Candidates={}
                local Seen={}

                local function AddCandidate(NPC)
                    if not NPC or Seen[NPC] or not LockedTargetValid(NPC,Q) then return end
                    Seen[NPC]=true
                    local R=GetRoot(NPC)
                    if not R then return end

                    local Distance=Me and (R.Position-Me.Position).Magnitude or math.huge
                    local SameZone=false
                    if CurrentZone then
                        local Cache=Runtime.BloxEnemyGroundCache[NPC]
                        local GroundY=Cache and (os.clock()-(tonumber(Cache.At) or 0)<0.65) and Cache.Y or nil
                        if GroundY==nil and BloxGroundPoint then
                            local Ground=BloxGroundPoint(R.Position,NPC)
                            GroundY=Ground and Ground.Y or R.Position.Y
                            Runtime.BloxEnemyGroundCache[NPC]={Y=GroundY,At=os.clock()}
                        end
                        local Center=CurrentZone.Center
                        local HD=Center and (Vector3.new(Center.X,0,Center.Z)-Vector3.new(R.Position.X,0,R.Position.Z)).Magnitude or math.huge
                        SameZone=GroundY~=nil
                            and math.abs(GroundY-(tonumber(CurrentZone.GroundY) or GroundY))<=5.5
                            and HD<=math.max(tonumber(CurrentZone.Radius) or 120,80)+45
                    end

                    local Hum=NPC:FindFirstChildOfClass("Humanoid")
                    table.insert(Candidates,{
                        Model=NPC,
                        Distance=Distance,
                        SameZone=SameZone,
                        Health=Hum and Hum.Health or math.huge
                    })
                end

                if CurrentTarget and LockedTargetValid(CurrentTarget,Q) then AddCandidate(CurrentTarget) end
                for _,NPC in ipairs(BloxLiveEnemies()) do AddCandidate(NPC) end

                table.sort(Candidates,function(A,B)
                    if CurrentTarget then
                        if A.Model==CurrentTarget and B.Model~=CurrentTarget then return true end
                        if B.Model==CurrentTarget and A.Model~=CurrentTarget then return false end
                    end
                    if A.SameZone~=B.SameZone then return A.SameZone end
                    if math.abs(A.Distance-B.Distance)>1 then return A.Distance<B.Distance end
                    return A.Health<B.Health
                end)

                local Queue={}
                for _,Entry in ipairs(Candidates) do
                    if #Queue>=3 then break end
                    table.insert(Queue,Entry.Model)
                end
                Runtime.BloxMobQueue=Queue

                local Names={}
                for _,NPC in ipairs(Queue) do table.insert(Names,StripEnemyName(NPC.Name)) end
                Runtime.BloxTargetQueueSnapshot=Names
                Runtime.BloxTargetQueueCount=#Queue
                Runtime.BloxTargetQueueUpdatedAt=os.clock()
                return Queue
            end

            local function FindQuestTarget(Q,CurrentTarget)
                local Queue=RefreshQuestTargetQueue(Q,CurrentTarget)
                if CurrentTarget and LockedTargetValid(CurrentTarget,Q) then return CurrentTarget end
                for _,NPC in ipairs(Queue) do
                    if LockedTargetValid(NPC,Q) then return NPC end
                end
                return nil
            end


-- ==================================================================
-- [BH:BLOX] QUEST COMBAT + DIRECT HANDOFF
-- FarmBloxEnemy is the single combat movement owner.
-- ==================================================================
            local function FightQuestTarget(Q,Target)
                if not Q or not LockedTargetValid(Target,Q) then return false end
                local FarmGeneration=Runtime.BloxFarmGeneration
                if not Runtime.BloxFarmRunActive(FarmGeneration) then return false end

                Runtime.BloxQuestMobAnchor=nil
                Runtime.BloxPrefetchedQuestTarget=nil
                local H=Target:FindFirstChildOfClass("Humanoid")
                local R=GetRoot(Target)
                if not H or not R then return false end
                Runtime.BloxQuestMobAnchor=R.CFrame
                Runtime.BloxCombatConfirmed=false
                Runtime.BloxCombatLastResult="Checking M1 contact"

                local NoProgressSince=os.clock()
                local LastHealth=H.Health
                local NextQueueRefreshAt=0
                RefreshQuestTargetQueue(Q,Target)

                repeat
                    if not Runtime.BloxFarmRunActive(FarmGeneration) then break end
                    if Runtime.BloxAutoLevelActive and Runtime.BloxFruitInterruptPending then
                        Runtime.BloxCombatLastResult="Fruit detected • yielding Auto Farm movement"
                        break
                    end
                    if not LockedTargetValid(Target,Q) then break end

                    local QuestCheck=DetectActiveQuest(Q)
                    if QuestCheck.Complete or not QuestCheck.Matched then break end

                    H=Target:FindFirstChildOfClass("Humanoid")
                    R=GetRoot(Target)
                    if not H or H.Health<=0 or not R then break end

                    Runtime.BloxQuestMobAnchor=R.CFrame
                    if os.clock()>=NextQueueRefreshAt then
                        RefreshQuestTargetQueue(Q,Target)
                        NextQueueRefreshAt=os.clock()+0.45
                    end

                    -- FarmBloxEnemy owns ALL combat movement, hover correction and attacks.
                    -- The previous outer pre-move/safety pass duplicated that work and could call
                    -- ProfileTravelToCFrame first, which uses Blox Fruits' long-distance
                    -- lift -> across -> descend route. That was the source of the visible
                    -- "kill -> go up -> move -> go down" pause between Auto Farm enemies.
                    local Worked=FarmBloxEnemy(Target)
                    if not Worked and LockedTargetValid(Target,Q) then
                        if Runtime.TravelFailure=="stuck" then
                            Runtime.BloxFailedTargets=Runtime.BloxFailedTargets or setmetatable({}, {__mode="k"})
                            Runtime.BloxFailedTargets[Target]=os.clock()+20
                            BloxFail("ROUTE_BLOCKED","Could not reach combat hover position")
                        else
                            BloxFail("TARGET_ROUTE_FAILED",tostring(Runtime.TravelFailure or "combat movement failed"))
                        end
                        break
                    end
                    if not Runtime.BloxFarmRunActive(FarmGeneration) then break end

                    H=Target:FindFirstChildOfClass("Humanoid")
                    if not H or H.Health<=0 then break end

                    if H.Health<LastHealth then
                        LastHealth=H.Health
                        NoProgressSince=os.clock()
                    elseif os.clock()-NoProgressSince>12 then
                        Runtime.BloxFailedTargets=Runtime.BloxFailedTargets or setmetatable({}, {__mode="k"})
                        Runtime.BloxFailedTargets[Target]=os.clock()+20
                        Runtime.BloxCombatLastResult="No damage for 12 seconds • trying another quest enemy"
                        BloxFail("NO_DAMAGE","Target took no damage for 12 seconds")
                        break
                    end

                    local A,B=QuestProgress()
                    Runtime.BloxQuestProgress=(A and B) and (tostring(A).."/"..tostring(B)) or "Fighting"
                    task.wait(0.02)
                until not Target.Parent or not H or H.Health<=0

                if H and H.Health<=0 then
                    Runtime.BloxJustKilledQuestMobAt=os.clock()

                    -- Acquire the next live quest mob immediately. FarmBloxEnemy has already
                    -- frozen the current hover lane and armed BloxDirectEnemyHandoffUntil.
                    -- If the quest is still active, start the next horizontal handoff right now
                    -- instead of returning to AutoFarmStep, stopping, then reacquiring.
                    if not (State.BloxAutoFruitActive and Runtime.BloxFruitInterruptPending) then
                        local PostQuest=DetectActiveQuest(Q)
                        if PostQuest.Matched and not PostQuest.Complete then
                            BloxEnemySnapshotState.At=0
                            local NextTarget=nil
                            local WarmQueue=Runtime.BloxMobQueue or {}
                            for _,Queued in ipairs(WarmQueue) do
                                if Queued~=Target and LockedTargetValid(Queued,Q) then
                                    NextTarget=Queued
                                    break
                                end
                            end
                            if not NextTarget then
                                RefreshQuestTargetQueue(Q,nil)
                                for _,Queued in ipairs(Runtime.BloxMobQueue or {}) do
                                    if Queued~=Target and LockedTargetValid(Queued,Q) then
                                        NextTarget=Queued
                                        break
                                    end
                                end
                            end
                            if NextTarget and NextTarget~=Target and LockedTargetValid(NextTarget,Q) then
                                Runtime.BloxPrefetchedQuestTarget=NextTarget
                                if type(Runtime.BloxDirectEnemyHandoff)=="function"
                                    and os.clock()<(tonumber(Runtime.BloxDirectEnemyHandoffUntil) or 0) then
                                    Runtime.BloxDirectEnemyHandoffActive=true
                                    local Moved=false
                                    local OK,Result=pcall(Runtime.BloxDirectEnemyHandoff,NextTarget)
                                    Moved=OK and Result==true
                                    Runtime.BloxDirectEnemyHandoffActive=false
                                    if Moved then
                                        Runtime.BloxDirectEnemyHandoffUntil=0
                                        Runtime.BloxCombatLastResult="Next quest mob • direct same-lane handoff"
                                    end
                                end
                            end
                        end
                    end
                end
                Runtime.BloxQuestMobAnchor=nil
                return true
            end

            local function AutoFarmStep()
                local Generation=Runtime.BloxFarmGeneration
                if not Runtime.BloxFarmRunActive(Generation) then return end
                Runtime.Movement.Guard()
                if Runtime.BloxFruitInterruptPending and (not Runtime.BloxFruitInterruptPending.Parent or not Runtime.BloxFruitInterruptPending:IsDescendantOf(workspace)) then
                    Runtime.BloxFruitInterruptPending=nil
                end
                if State.BloxAutoFruitActive and Runtime.BloxFruitInterruptPending and Runtime.BloxRunFruitInterrupt then
                    Runtime.BloxRunFruitInterrupt()
                    return
                end
                local Stage=Runtime.BloxFarmStage or "FindQuest"
                local Now=os.clock()
                local CurrentLevel=BloxLevel()
                local CurrentSea=BloxSeaNumber()

                -- Seamless level progression: Sea 2 has no normal quest at Lv.1500+, so Auto Farm
                -- must temporarily become the Third Sea prerequisite runner instead of falling into
                -- QUEST_NOT_FOUND. The same Auto Farm controller remains the movement/combat owner.
                if CurrentSea==2 and CurrentLevel>=1500 then
                    if not Runtime.BloxAutoFarmSeaProgressionActive then
                        Runtime.BloxAutoFarmSeaProgressionActive=true
                        AutoFarmQuest=nil
                        AutoFarmTarget=nil
                        Runtime.ActiveBloxQuest=nil
                        Runtime.BloxMobQueue={}
                        Runtime.BloxQuestMobAnchor=nil
                        if QuestVisible() then pcall(function() QueryRemote(BloxCommF(),"AbandonQuest") end) end
                        SetAutoFarmStatus("Lv. 1500 reached • unlocking Third Sea")
                    end
                    local Step=Runtime.BloxFns and Runtime.BloxFns.ThirdSeaQuestStep
                    if type(Step)=="function" then
                        local Done,Reason=Step()
                        Runtime.BloxQuestLastFailure=Done and nil or Reason
                        if Done then SetAutoFarmStatus("Third Sea travel requested • Auto Farm resume armed") end
                    else
                        Runtime.BloxQuestLastFailure="THIRD_SEA_HANDLER_NOT_READY"
                        SetAutoFarmStatus("Third Sea handler not ready • retrying")
                    end
                    AutoFarmNextAcquire=Now+0.35
                    return
                elseif CurrentSea==3 and Runtime.BloxAutoFarmSeaProgressionActive then
                    Runtime.BloxAutoFarmSeaProgressionActive=false
                    AutoFarmQuest=nil
                    AutoFarmTarget=nil
                    Runtime.ActiveBloxQuest=nil
                    Runtime.BloxMobQueue={}
                    Runtime.BloxFarmStage="FindQuest"
                    ReadBloxQuests(true)
                    SetAutoFarmStatus("Third Sea entered • resuming Auto Farm")
                end

                if Runtime.BloxLevelDirty then
                    Runtime.BloxLevelDirty=false
                    ReadBloxQuests(true)
                    BloxEnemySnapshotState.At=0
                    AutoFarmNextAcquire=0
                end

                if AutoFarmQuest and Runtime.BloxAutoFarmSelectedLevel
                    and CurrentLevel~=Runtime.BloxAutoFarmSelectedLevel then
                    ReadBloxQuests(true)
                    local Upgrade=BloxQuestData()
                    Runtime.BloxAutoFarmSelectedLevel=CurrentLevel
                    if Upgrade and (tonumber(Upgrade.LevelReq) or 0)>(tonumber(AutoFarmQuest.LevelReq) or 0) then
                        if QuestVisible() then pcall(function() QueryRemote(BloxCommF(),"AbandonQuest") end) end
                        AutoFarmQuest=Upgrade
                        Runtime.ActiveBloxQuest=Upgrade
                        Runtime.BloxAutoFarmSelectedQuestReq=Upgrade.LevelReq
                        AutoFarmTarget=nil
                        Runtime.BloxMobQueue={}
                        Runtime.BloxQuestMobAnchor=nil
                        AutoFarmQuestMissingSince=0
                        BloxEnemySnapshotState.At=0
                        Runtime.BloxFarmStage="TravelQuest"
                        AutoFarmNextAcquire=0
                        SetAutoFarmStatus("New island/quest unlocked • moving to "..tostring(Upgrade.MobName))
                        return
                    end
                end

                if Now<AutoFarmNextAcquire then return end
                if Stage=="FindQuest" then
                    ReadBloxQuests(true)
                    AutoFarmQuest=BloxQuestData()
                    AutoFarmTarget=nil; Runtime.BloxPrefetchedQuestTarget=nil; Runtime.BloxMobQueue={}; Runtime.ActiveBloxQuest=nil
                    AutoFarmQuestMissingSince=0
                    if not AutoFarmQuest then BloxFail("QUEST_NOT_FOUND","No supported quest for this level/sea"); SetAutoFarmStatus("No supported quest for this level and sea"); AutoFarmNextAcquire=Now+1; return end
                    BloxClearFailure()
                    Runtime.BloxAutoFarmSelectedLevel=CurrentLevel
                    Runtime.BloxAutoFarmSelectedQuestReq=AutoFarmQuest.LevelReq
                    Runtime.ActiveBloxQuest=AutoFarmQuest
                    Runtime.BloxFarmStage="TravelQuest"
                    return
                end
                local Q=AutoFarmQuest
                if not Q then Runtime.BloxFarmStage="FindQuest"; return end
                local Quest=DetectActiveQuest(Q)
                if Quest.Matched and Quest.Complete then Stage="Complete"; Runtime.BloxFarmStage=Stage end
                if Stage=="TravelQuest" then
                    if Quest.Matched and not Quest.Complete then Runtime.BloxFarmStage="TravelMobs";  return end
                    if Quest.Visible and not Quest.Matched then
                        QueryRemote(BloxCommF(),"AbandonQuest")
                        AutoFarmNextAcquire=Now+0.5
                        return
                    end
                    SetAutoFarmStatus("Travelling to quest giver • "..Q.MobName)

                    if not Q.NPCPosition then
                        ReadBloxQuests(true)
                        AttachKnownQuestRoute(ResolveQuestNPC(Q))
                    end
                    if not Q.NPCPosition and Q.NPCName then
                        local Map=BloxNPCMap()
                        for Name,CF in pairs(Map) do
                            if NormalName(Name)==NormalName(Q.NPCName) then
                                Q.NPCPosition=CF
                                break
                            end
                        end
                    end
                    if not Q.NPCPosition then
                        BloxFail("NPC_MISSING","Quest giver position unavailable for "..tostring(Q.MobName))
                        SetAutoFarmStatus("Refreshing next-island quest giver • "..Q.MobName)
                        AutoFarmNextAcquire=Now+0.35
                        Runtime.BloxFarmStage="FindQuest"
                        return
                    end
                    if ProfileTravelToCFrame(Q.NPCPosition*CFrame.new(0,3,2)) then Runtime.BloxFarmStage="StartQuest" end
                    return
                end
                if Stage=="StartQuest" then
                    if Quest.Matched and not Quest.Complete then  Runtime.BloxFarmStage="TravelMobs"; return end
                    local R=Root()
                    if not R or not Q.NPCPosition or (R.Position-Q.NPCPosition.Position).Magnitude>10 then
                        Runtime.BloxFarmStage="TravelQuest"
                        return
                    end
                    SetAutoFarmStatus("Starting quest • "..Q.MobName)
                    local Started=QueryRemote(BloxCommF(),"StartQuest",Q.QuestName,Q.QuestIndex)
                    if not Started then
                        BloxFail("QUEST_REMOTE_FAILED","StartQuest did not return successfully")
                        Runtime.BloxFarmStage="TravelQuest"
                        AutoFarmNextAcquire=os.clock()+0.35
                        return
                    end
                    Runtime.BloxQuestConfirmUntil=os.clock()+2.5
                    Runtime.BloxFarmStage="ConfirmQuest"
                    return
                end
                if Stage=="ConfirmQuest" then
                    if Quest.Matched and not Quest.Complete then
                        AutoFarmQuestMissingSince=0
                        -- Public Blox farm implementations establish the spawn after starting
                        -- the level quest. BananiHub does it only after exact UI confirmation,
                        -- so a stale/wrong quest cannot accidentally move the spawn point.
                        local SpawnQuestKey=tostring(Q.QuestName)..":"..tostring(Q.QuestIndex)
                        if Runtime.BloxSpawnPointQuestKey~=SpawnQuestKey then
                            local SpawnOK=QueryRemote(BloxCommF(),"SetSpawnPoint")
                            if SpawnOK then Runtime.BloxSpawnPointQuestKey=SpawnQuestKey end
                        end
                        Runtime.BloxFarmStage="TravelMobs"
                    elseif Now>=(Runtime.BloxQuestConfirmUntil or 0) then
                        BloxFail(Quest.Visible and "QUEST_MISMATCH" or "QUEST_NOT_CONFIRMED",Quest.Title or "Quest UI did not match target")
                        SetAutoFarmStatus("Quest not confirmed • retrying giver")
                        Runtime.BloxFarmStage="TravelQuest"; AutoFarmNextAcquire=Now+0.75
                    else SetAutoFarmStatus("Confirming exact visible quest title") end
                    return
                end
                if Stage=="Complete" then
                    AutoFarmTarget=nil; Runtime.BloxPrefetchedQuestTarget=nil; Runtime.BloxMobQueue={}; Runtime.ActiveBloxQuest=nil
                    AutoFarmQuest=nil
                    AutoFarmNextAcquire=0
                    Runtime.BloxFarmStage="FindQuest"
                    SetAutoFarmStatus("Quest complete • getting next quest now")
                    return
                end
                if Quest.Matched then AutoFarmQuestMissingSince=0
                elseif Quest.Visible then
                    AutoFarmTarget=nil; Runtime.BloxFarmStage="TravelQuest"; return
                else
                    if AutoFarmQuestMissingSince==0 then AutoFarmQuestMissingSince=Now end
                    local JustKilled=Now-(Runtime.BloxJustKilledQuestMobAt or -math.huge)<1.0
                    local LastCurrent=tonumber(Runtime.BloxLastQuestCurrent)
                    local LastGoal=tonumber(Runtime.BloxLastQuestGoal)
                    local FinalKillLikely=JustKilled and LastCurrent and LastGoal and LastGoal>0 and (LastCurrent+1)>=LastGoal
                    if FinalKillLikely then
                        AutoFarmTarget=nil
                        Runtime.BloxFarmStage="Complete"
                        AutoFarmQuestMissingSince=0
                        SetAutoFarmStatus("Final mob killed • next quest now")
                    elseif Now-AutoFarmQuestMissingSince>=0.8 then

                        AutoFarmTarget=nil
                        Runtime.BloxFarmStage="TravelQuest"
                        AutoFarmQuestMissingSince=0
                    else
                        SetAutoFarmStatus("Confirming quest completion")
                    end
                    return
                end
                if Quest.Complete then Runtime.BloxFarmStage="Complete"; AutoFarmTarget=nil; return end
                if Stage=="TravelMobs" then
                    -- Prefer the real live quest enemy over a static spawn marker. This avoids
                    -- getting stuck after quest acceptance when the island floor/spawn marker is
                    -- streamed differently from the hard-coded route.
                    AutoFarmTarget=FindQuestTarget(Q)
                    if AutoFarmTarget then
                        Runtime.BloxFarmStage="Fight"
                        SetAutoFarmStatus("Quest confirmed • target acquired • "..Q.MobName)
                        return
                    end
                    SetAutoFarmStatus("Travelling to "..Q.MobName.." spawn")
                    if MoveToBloxTargetArea(Q.MobName,Q.IsBoss,Q) then
                        BloxEnemySnapshotState.At=0
                        AutoFarmTarget=FindQuestTarget(Q)
                        Runtime.BloxFarmStage="Fight"
                    else
                        BloxFail("MOB_ROUTE_FAILED","Could not resolve mob area for "..tostring(Q.MobName))
                        AutoFarmNextAcquire=os.clock()+0.20
                    end
                    return
                end
                if Stage=="Fight" then
                    while Runtime.BloxFarmRunActive(Generation) do
                        if State.BloxAutoFruitActive and Runtime.BloxFruitInterruptPending then
                            SetAutoFarmStatus("Fruit detected • pausing Auto Farm")
                            break
                        end
                        local LiveQuest=DetectActiveQuest(Q)
                        if LiveQuest.Complete then
                            AutoFarmTarget=nil
                            Runtime.BloxFarmStage="Complete"
                            SetAutoFarmStatus("Quest complete • switching now")
                            break
                        end
                        if not LiveQuest.Matched then break end

                        if not LockedTargetValid(AutoFarmTarget,Q) then AutoFarmTarget=FindQuestTarget(Q) end
                        if not AutoFarmTarget then
                            SetAutoFarmStatus("Waiting for "..Q.MobName.." respawn")
                            WaitForBloxSpawn()
                            AutoFarmNextAcquire=os.clock()+0.05
                            break
                        end

                        Runtime.BloxWaitingUnderground=false
                        Runtime.BloxUndergroundWaitCF=nil
                        SetAutoFarmStatus("Fighting • "..Q.MobName)
                        FightQuestTarget(Q,AutoFarmTarget)
                        local Prefetched=Runtime.BloxPrefetchedQuestTarget
                        Runtime.BloxPrefetchedQuestTarget=nil
                        AutoFarmTarget=(Prefetched and LockedTargetValid(Prefetched,Q)) and Prefetched or nil
                        BloxEnemySnapshotState.At=0

                        local After=DetectActiveQuest(Q)
                        if After.Complete then
                            AutoFarmTarget=nil
                            Runtime.BloxFarmStage="Complete"
                            SetAutoFarmStatus("Quest complete • switching now")
                            break
                        end
                        if not After.Matched then AutoFarmTarget=nil; break end

                        if not AutoFarmTarget then AutoFarmTarget=FindQuestTarget(Q) end
                        if AutoFarmTarget then
                            SetAutoFarmStatus("Next mob • same hover lane • "..Q.MobName)
                            task.wait(0.01)
                        else
                            SetAutoFarmStatus("Waiting for "..Q.MobName.." respawn")
                            WaitForBloxSpawn()
                            AutoFarmNextAcquire=os.clock()+0.05
                            break
                        end
                    end
                end
            end

            local ManualEnemyTarget,ManualBossTarget=nil,nil
            local function ManualTargetValid(Target,Filter,BossOnly)
                local Folder=workspace:FindFirstChild("Enemies")
                if not Target or not Folder or not Target:IsDescendantOf(Folder) or IsPlayerCharacter(Target) then return false end
                local H=Target:FindFirstChildOfClass("Humanoid")
                return H and H.Health>0 and GetRoot(Target)~=nil and TargetNameMatches(Target.Name,Filter,BossOnly)
            end
            local function SelectedEnemyFarmStep()
                local Target=State.SelectedEnemy
                local Q=nil
                if State.BloxSelectedUseQuest and Target and NormalName(Target)~="nearest enemy" then
                    Q=QuestForEnemy(Target,false)
                    if Q and not EnsureQuest(Q) then return end
                end
                if not ManualTargetValid(ManualEnemyTarget,Target,false) then
                    ManualEnemyTarget=NearestBloxEnemy(Target,false,true)
                end
                if ManualEnemyTarget then
                    FarmBloxEnemy(ManualEnemyTarget)
                elseif State.BloxMoveToSpawn then
                    MoveToBloxTargetArea(Target,false,Q)
                end
            end
            local function SelectedBossFarmStep()
                local Target=State.SelectedBoss
                local Q=nil
                if State.BloxBossUseQuest and Target and NormalName(Target)~="nearest boss" then
                    Q=QuestForEnemy(Target,true)
                    if Q and not EnsureQuest(Q) then return end
                end
                if not ManualTargetValid(ManualBossTarget,Target,true) then
                    ManualBossTarget=NearestBloxEnemy(Target,true,true)
                end
                if ManualBossTarget then
                    FarmBloxEnemy(ManualBossTarget)
                elseif State.BloxMoveToSpawn then
                    MoveToBloxTargetArea(Target,true,Q)
                end
            end
            local function BloxLocations()
                local Result,Seen={"Select Location"},{["Select Location"]=true}
                local WorldOrigin=workspace:FindFirstChild("_WorldOrigin")
                local Locations=WorldOrigin and WorldOrigin:FindFirstChild("Locations")
                if Locations then
                    for _,Obj in ipairs(Locations:GetChildren()) do if GetRoot(Obj) then AddUnique(Result,Seen,Obj.Name) end end
                end
                table.sort(Result,function(A,B)
                    if A==B then return false end
                    if A=="Select Location" then return true end
                    if B=="Select Location" then return false end
                    return string.lower(A)<string.lower(B)
                end)
                return Result
            end
            local function BloxTeleportLocation(Name)
                if not Name or Name=="Select Location" then return false end
                local WorldOrigin=workspace:FindFirstChild("_WorldOrigin")
                local Locations=WorldOrigin and WorldOrigin:FindFirstChild("Locations")
                local Obj=Locations and Locations:FindFirstChild(Name)
                if not Obj then return false end
                local Target=GetRoot(Obj)
                local Me=Root()

                if Target and Me and (Target.Position-Me.Position).Magnitude>220
                    and type(BloxSmartEntranceTravel)=="function" then
                    pcall(function() BloxSmartEntranceTravel(Target.Position,"Location:"..tostring(Name)) end)
                    WorldOrigin=workspace:FindFirstChild("_WorldOrigin")
                    Locations=WorldOrigin and WorldOrigin:FindFirstChild("Locations")
                    Obj=Locations and Locations:FindFirstChild(Name) or Obj
                end
                local LocationRoot=GetRoot(Obj)
                if LocationRoot and BloxGroundTravelCFrame then
                    return ProfileTravelToCFrame(BloxGroundTravelCFrame(LocationRoot.CFrame),function()
                        local Current=GetRoot(Obj)
                        return Current and BloxGroundTravelCFrame(Current.CFrame) or nil
                    end)
                end
                return MoveTo(Obj,CFrame.new(0,3,2))
            end
            local function BloxFruitTools(OwnedOnly,SpawnedOnly)

                local Fruits,Seen={},{}
                local function IsShopOrNPC(Obj)
                    local Current=Obj
                    for _=1,8 do
                        if not Current or Current==workspace then break end
                        local Lower=string.lower(tostring(Current.Name or ""))
                        if string.find(Lower,"dealer",1,true)
                            or string.find(Lower,"gacha",1,true)
                            or string.find(Lower,"cousin",1,true)
                            or Lower=="zioles" then
                            return true
                        end
                        if Current:IsA("Model") and Current:FindFirstChildOfClass("Humanoid") then return true end
                        Current=Current.Parent
                    end
                    return false
                end
                local function Add(Obj)
                    if Seen[Obj] or not Obj or IsShopOrNPC(Obj) then return end
                    if Obj:IsA("Model") then
                        local Inner=Obj:FindFirstChildWhichIsA("Tool",true)
                        if Inner and not IsShopOrNPC(Inner) then Add(Inner); return end
                        local Detector=Runtime.BloxFruitDetector
                        local Identified=Detector and Detector.Identify and Detector.Identify(Obj) or nil
                        local HasMetadata=Obj:GetAttribute("OriginalName")~=nil or Obj:GetAttribute("FruitName")~=nil or Obj:FindFirstChild("EatRemote",true)~=nil
                        if Identified and HasMetadata and Obj:IsDescendantOf(workspace)
                            and not Obj:FindFirstChildOfClass("Humanoid") and GetRoot(Obj) then
                            Seen[Obj]=true
                            table.insert(Fruits,Obj)
                        end
                        return
                    end
                    if not Obj:IsA("Tool") then return end
                    local Detector=Runtime.BloxFruitDetector
                    local Identified=Detector and Detector.Identify and Detector.Identify(Obj) or nil
                    if not IsShopOrNPC(Obj)
                        and (Identified or Obj:FindFirstChild("EatRemote",true) or Obj:GetAttribute("OriginalName")~=nil or string.find(string.lower(Obj.Name),"fruit",1,true))
                        and GetRoot(Obj) then
                        Seen[Obj]=true
                        table.insert(Fruits,Obj)
                    end
                end
                if not OwnedOnly then
                    if Runtime.BloxFruitDetectorReady and Runtime.BloxFruitDetectorLive then
                        for Fruit in pairs(Runtime.BloxFruitDetectorLive) do
                            if Fruit and Fruit.Parent then Add(Fruit) end
                        end
                    else
                        -- One startup fallback before the event-driven detector has built its live cache.
                        for _,Obj in ipairs(workspace:GetChildren()) do Add(Obj) end
                        for _,Obj in ipairs(workspace:GetDescendants()) do
                            if Obj:IsA("Tool") or Obj:IsA("Model") then Add(Obj) end
                        end
                    end
                end
                if not SpawnedOnly then
                    local Backpack=Player:FindFirstChildOfClass("Backpack")
                    if Backpack then for _,Obj in ipairs(Backpack:GetChildren()) do Add(Obj) end end
                    local C=Character()
                    if C then for _,Obj in ipairs(C:GetChildren()) do Add(Obj) end end
                end
                return Fruits
            end
            Runtime.BloxReadDealer=function()
                local Cache=Runtime.BloxDealerCache
                if Cache and os.clock()-Cache.At<0.5 then return Cache.Ok,Cache.Data end
                if Runtime.BloxDealerReading then return false,nil end
                Runtime.BloxDealerReading=true
                local Protected,Ok,Data=pcall(QueryRemote,BloxCommF(),"GetFruits",false)
                Runtime.BloxDealerReading=false
                if not Protected then
                    if tostring(Ok):find("BANANI_CANCELLED",1,true) then error(Ok,0) end
                    Ok,Data=false,nil
                end
                Runtime.BloxDealerCache={At=os.clock(),Ok=Ok,Data=Data}
                return Ok,Data
            end
            local function BloxFruitCatalog()
                local Out,Seen={"Select Fruit"},{["Select Fruit"]=true}
                local Ok,Fruits=Runtime.BloxReadDealer()
                if Ok and type(Fruits)=="table" then
                    for Key,Info in pairs(Fruits) do
                        if type(Info)=="table" then
                            AddUnique(Out,Seen,Info.Name or Info.FruitName or Info.DisplayName or (type(Key)=="string" and Key))
                        elseif type(Key)=="string" then
                            AddUnique(Out,Seen,Key)
                        end
                    end
                end
                for _,Fruit in ipairs(BloxFruitTools()) do AddUnique(Out,Seen,Fruit:GetAttribute("OriginalName") or Fruit.Name) end
                table.sort(Out,function(A,B)
                    if A==B then return false end
                    if A=="Select Fruit" then return true end
                    if B=="Select Fruit" then return false end
                    return string.lower(A)<string.lower(B)
                end)
                return Out
            end
            local function FruitWanted(Fruit)
                local Targets=State.BloxFruitTargets or {}
                if #Targets==0 then return true end
                local Name=string.lower(tostring(Fruit:GetAttribute("OriginalName") or Fruit.Name))
                for _,Target in ipairs(Targets) do
                    if string.find(Name,string.lower(tostring(Target)),1,true) then return true end
                end
                return false
            end
            local function NearestFruit(Excluded)
                local Me=Root(); if not Me then return nil end
                local Best,Dist=nil,math.huge
                for _,Fruit in ipairs(BloxFruitTools(false,true)) do
                    local R=GetRoot(Fruit)
                    if R and FruitWanted(Fruit) and not (Excluded and Excluded[Fruit]) then
                        local D=(Me.Position-R.Position).Magnitude
                        if D<Dist then Best,Dist=Fruit,D end
                    end
                end
                return Best,Dist
            end
            local function SpawnedFruitCount(Excluded)
                local Count=0
                for _,Fruit in ipairs(BloxFruitTools(false,true)) do
                    if GetRoot(Fruit) and FruitWanted(Fruit) and not (Excluded and Excluded[Fruit]) then Count+=1 end
                end
                return Count
            end

            -- Register-safe fruit collector helpers live on Runtime instead of adding more
            -- outer-scope locals to the already-large Blox Fruits profile.
            Runtime.BloxFruitCollector=Runtime.BloxFruitCollector or {}
            Runtime.BloxFruitCollector.ReturnCF=CFrame.new(-382,48,290)
            Runtime.BloxFruitCollector.SurfaceY=73
            Runtime.BloxFruitCollector.ApproachOffset=Vector3.new(0,0,115)
            Runtime.BloxFruitCollector.NameAliases={
                rocket="Rocket", spin="Spin", spring="Spring", bomb="Bomb", smoke="Smoke", spike="Spike",
                flame="Flame", ice="Ice", sand="Sand", dark="Dark", diamond="Diamond", light="Light",
                rubber="Rubber", ghost="Ghost", magma="Magma", quake="Quake", buddha="Buddha",
                love="Love", spider="Spider", sound="Sound", phoenix="Phoenix", portal="Portal",
                pain="Pain", blizzard="Blizzard", gravity="Gravity", mammoth="Mammoth", trex="T-Rex",
                dough="Dough", shadow="Shadow", venom="Venom", control="Control", gas="Gas",
                spirit="Spirit", yeti="Yeti", magnet="Magnet", kitsune="Kitsune", dragon="Dragon",
                -- Current display names plus legacy aliases still found in older data/scripts.
                blade="Blade", chop="Blade", eagle="Eagle", falcon="Eagle",
                creation="Creation", barrier="Creation", lightning="Lightning", rumble="Lightning",
                tiger="Tiger", leopard="Tiger", revive="Ghost", paw="Pain", door="Portal", soul="Spirit",
                dragonwest="Dragon", dragoneast="Dragon", westdragon="Dragon", eastdragon="Dragon"
            }

            function Runtime.BloxFruitCollector.DisplayName(Fruit)
                if not Fruit then return "Unknown Fruit" end
                if Runtime.BloxFruitDetector and Runtime.BloxFruitDetector.Identify then
                    local Pretty=Runtime.BloxFruitDetector.Identify(Fruit)
                    if Pretty then return Pretty.." Fruit" end
                end
                local Candidates={}
                local function Add(Value)
                    Value=tostring(Value or ""):gsub("^%s+",""):gsub("%s+$","")
                    if Value~="" then table.insert(Candidates,Value) end
                end
                pcall(function() Add(Fruit:GetAttribute("OriginalName")) end)
                pcall(function() Add(Fruit:GetAttribute("FruitName")) end)
                pcall(function() Add(Fruit:GetAttribute("DisplayName")) end)
                pcall(function() if Fruit:IsA("Tool") then Add(Fruit.ToolTip) end end)
                pcall(function()
                    for Key,Value in pairs(Fruit:GetAttributes()) do
                        if type(Value)=="string" then Add(Value) end
                    end
                end)
                for _,Key in ipairs({"OriginalName","FruitName","DisplayName","Name","ItemName"}) do
                    local Value=Fruit:FindFirstChild(Key,true)
                    if Value and Value:IsA("StringValue") then Add(Value.Value) end
                end
                Add(Fruit.Name)

                local function Compact(Value)
                    return string.lower(tostring(Value or "")):gsub("^blox%s+fruit%s*[:%-_]*%s*","")
                        :gsub("^demon%s+fruit%s*[:%-_]*%s*","")
                        :gsub("^fruit%s*[:%-_]*%s*","")
                        :gsub("%s+[Ff]ruit$","")
                        :gsub("[^%w]","")
                end
                -- Exact local metadata/object-name matching only. No dealer query and no icon scan.
                for _,Candidate in ipairs(Candidates) do
                    local Key=Compact(Candidate)
                    local Pretty=Runtime.BloxFruitCollector.NameAliases[Key]
                    if Pretty then return Pretty.." Fruit" end
                    for Alias,AliasPretty in pairs(Runtime.BloxFruitCollector.NameAliases) do
                        if #Alias>=4 and string.find(Key,Alias,1,true) then
                            return AliasPretty.." Fruit"
                        end
                    end
                end

                local Name=tostring(Candidates[1] or Fruit.Name or "Unknown Fruit")
                Name=Name:gsub("^Fruit%s*[:%-_]*%s*","")
                    :gsub("^Blox%s+Fruit%s*[:%-_]*%s*","")
                    :gsub("^Demon%s+Fruit%s*[:%-_]*%s*","")
                    :gsub("[%[%]{}<>]","")
                    :gsub("[_%-]+"," ")
                    :gsub("%s+"," ")
                    :gsub("^%s+",""):gsub("%s+$","")
                local Lower=string.lower(Name)
                if Name=="" or Lower=="fruit" or Lower=="blox fruit" or Lower=="demon fruit" then
                    return "Unknown Fruit"
                end
                if not string.find(Lower,"fruit",1,true) then Name=Name.." Fruit" end
                return Name
            end
            function Runtime.BloxFruitCollector.DistanceStuds(Fruit)
                local Me=Root()
                local R=Fruit and Fruit.Parent and GetRoot(Fruit) or nil
                if not Me or not R then return nil end
                return math.floor((Me.Position-R.Position).Magnitude+0.5)
            end
            function Runtime.BloxFruitCollector.SetStatus(Phase,Fruit,OverrideDistance)
                local Name=Fruit and Runtime.BloxFruitCollector.DisplayName(Fruit) or "None detected"
                local Distance=OverrideDistance
                if Distance==nil and Fruit then Distance=Runtime.BloxFruitCollector.DistanceStuds(Fruit) end
                local DistanceText=Distance and (tostring(math.max(0,math.floor(Distance+0.5))).." studs") or "--"
                local Text=tostring(Phase or "Idle").."\nFruit: "..Name.."\nDistance: "..DistanceText
                Runtime.BloxFruitCollectorStatus=Text
                local P=Runtime.BloxFruitStatusParagraph
                if P and P.Set then pcall(function() P:Set({Title="Fruit Collector",Content=Text}) end) end
            end
            function Runtime.BloxFruitCollector.ReturnCFrame()
                if BloxSeaNumber()~=2 then return nil end
                return Runtime.BloxFruitCollector.ReturnCF
            end
            function Runtime.BloxFruitCollector.SurfaceApproachCFrame()
                local Room=Runtime.BloxFruitCollector.ReturnCFrame()
                if not Room then return nil end
                local P=Room.Position+Runtime.BloxFruitCollector.ApproachOffset
                return CFrame.new(P.X,Runtime.BloxFruitCollector.SurfaceY,P.Z)*Room.Rotation
            end
            function Runtime.BloxFruitCollector.IsParkingSpotClear(CF)
                if typeof(CF)~="CFrame" then return false end
                local Params=OverlapParams.new()
                Params.FilterType=Enum.RaycastFilterType.Exclude
                Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                local Ok,Parts=pcall(function()
                    -- Probe the space occupied by the avatar rather than only testing one point.
                    return workspace:GetPartBoundsInBox(CF*CFrame.new(0,2.6,0),Vector3.new(4.2,5.4,4.2),Params)
                end)
                if not Ok then return false end
                for _,Part in ipairs(Parts or {}) do
                    if Part:IsA("BasePart") and Part.CanCollide and Part.Transparency<0.98 then return false end
                end
                return true
            end
            function Runtime.BloxFruitCollector.SafeRoomCFrame()
                local Base=Runtime.BloxFruitCollector.ReturnCFrame()
                if not Base then return nil end
                -- The old fixed point can stream inside a Café wall. Search nearby underground
                -- pockets and use the nearest collision-free one instead.
                local Rings={0,6,12,18,24,30,36}
                local YOffsets={0,-3,3,-6}
                for _,Radius in ipairs(Rings) do
                    local Offsets=Radius==0 and {{0,0}} or {
                        {Radius,0},{-Radius,0},{0,Radius},{0,-Radius},
                        {Radius,Radius},{Radius,-Radius},{-Radius,Radius},{-Radius,-Radius}
                    }
                    for _,Y in ipairs(YOffsets) do
                        for _,XZ in ipairs(Offsets) do
                            local Candidate=Base*CFrame.new(XZ[1],Y,XZ[2])
                            if Candidate.Position.Y<Runtime.BloxFruitCollector.SurfaceY-8
                                and Runtime.BloxFruitCollector.IsParkingSpotClear(Candidate) then
                                return Candidate
                            end
                        end
                    end
                end
                -- If streaming prevents a reliable overlap result, stay several studs away
                -- from the original wall-prone point instead of parking on the exact old CFrame.
                return Base*CFrame.new(0,-4,18)
            end
            function Runtime.BloxFruitCollector.UndergroundEntryCFrame(Room)
                local Surface=Runtime.BloxFruitCollector.SurfaceApproachCFrame()
                Room=Room or Runtime.BloxFruitCollector.SafeRoomCFrame()
                if not Surface or not Room then return nil end
                return CFrame.new(Surface.Position.X,Room.Position.Y,Surface.Position.Z)*Room.Rotation
            end
            function Runtime.BloxFruitCollector.TravelBack(Fruit)
                if BloxSeaNumber()~=2 then return true end
                local Base=Runtime.BloxFruitCollector.ReturnCFrame()
                local Surface=nil
                for _,Offset in ipairs({Vector3.zero,Vector3.new(12,0,0),Vector3.new(-12,0,0),Vector3.new(0,0,12),Vector3.new(0,0,-12),Vector3.new(24,0,0),Vector3.new(-24,0,0)}) do
                    local Ground=BloxGroundPoint(Base.Position+Offset+Vector3.new(0,55,0),nil)
                    if Ground and Ground.Y>=Runtime.BloxFruitCollector.SurfaceY+2 then
                        local Candidate=CFrame.new(Ground+Vector3.new(0,2,0))
                        if Runtime.BloxFruitCollector.IsParkingSpotClear(Candidate) then Surface=Candidate; break end
                    end
                end
                if not Surface then
                    Runtime.BloxFruitCollector.SetStatus("Café surface not confirmed • staying on safe ground",Fruit,nil)
                    return false
                end
                Runtime.BloxFruitReturningToCafe=true
                local Me=Root()
                if not Me then return false end
                local Sky=CFrame.new(Surface.Position.X,math.max(Me.Position.Y,Surface.Position.Y+40,145),Surface.Position.Z)
                Runtime.BloxFruitStatusPhase="Returning above Café island"
                Runtime.BloxFruitStatusTargetCFrame=Sky
                Runtime.BloxFruitCollector.SetStatus(Runtime.BloxFruitStatusPhase,Fruit,(Me.Position-Sky.Position).Magnitude)
                if not ProfileTravelToCFrame(Sky) then return false end
                Runtime.BloxFruitStatusPhase="Landing on checked Café surface"
                Runtime.BloxFruitStatusTargetCFrame=Surface
                if not Runtime.ProfileRouter.Direct(Surface,"Smooth Tween",nil,"BloxFruitCafeSurface") then return false end
                Me=Root()
                if not Me or not Runtime.BloxFruitCollector.IsParkingSpotClear(Me.CFrame) then return false end
                Me.AssemblyLinearVelocity=Vector3.zero
                Me.AssemblyAngularVelocity=Vector3.zero
                Runtime.BloxFruitStatusTargetCFrame=nil
                Runtime.BloxFruitStatusPhase=nil
                Runtime.BloxFruitCollector.SetStatus("On safe Café ground • collection complete",Fruit,0)
                return true
            end
            local function SpawnedFruitCollected(Fruit)
                if not Fruit or not Fruit.Parent then return true end
                local Backpack=Player:FindFirstChildOfClass("Backpack")
                local C=Character()
                local InvisibleState=Runtime.UniversalInvisibleState
                local RealCharacter=InvisibleState and InvisibleState.Active and InvisibleState.RealCharacter or nil
                if Backpack and Fruit:IsDescendantOf(Backpack) then return true end
                if C and Fruit:IsDescendantOf(C) then return true end
                if RealCharacter and Fruit:IsDescendantOf(RealCharacter) then return true end
                return not Fruit:IsDescendantOf(workspace)
            end
            Runtime.BloxEnsureAutoFarmAfterFruit=function(ForceReacquire)
                if Unloaded or Runtime.BloxAutoLevelActive~=true then return false end
                if Runtime.BloxFruitCollectBusy or Runtime.BloxFruitInterruptActive then return false end

                -- Never leave a stale fruit interrupt latched after the target was collected/despawned.
                local Pending=Runtime.BloxFruitInterruptPending
                if Pending and (not Pending.Parent or SpawnedFruitCollected(Pending) or not FruitWanted(Pending)) then
                    Runtime.BloxFruitInterruptPending=nil
                end

                local Thread=State.LoopThreads and State.LoopThreads["BloxAutoLevel"] or nil
                local Context=Thread and Runtime.Movement and Runtime.Movement.Contexts and Runtime.Movement.Contexts[Thread] or nil
                if Thread and Context and not Context.Cancelled then
                    AutoFarmNextAcquire=0
                    return true
                end

                -- If an older interrupt/cancellation killed the loop, recreate only the Auto Farm
                -- worker without toggling the user's setting or resetting the whole Blox controller.
                AutoFarmTarget=nil
                Runtime.BloxMobQueue={}
                Runtime.BloxPrefetchedQuestTarget=nil
                Runtime.BloxQuestMobAnchor=nil
                BloxEnemySnapshotState.At=0
                AutoFarmNextAcquire=0
                if ForceReacquire==true then
                    local Active=AutoFarmQuest and DetectActiveQuest(AutoFarmQuest) or nil
                    if not (Active and Active.Matched and not Active.Complete) then
                        AutoFarmQuest=nil
                        Runtime.ActiveBloxQuest=nil
                        Runtime.BloxFarmStage="FindQuest"
                    elseif Runtime.BloxFarmStage=="Fight" then
                        Runtime.BloxFarmStage="TravelMobs"
                    end
                end
                StartLoop("BloxAutoLevel",AutoFarmStep,0.05)
                SetAutoFarmStatus("Fruit pickup complete • Auto Farm resumed")
                return true
            end

            local function UnequipCollectedFruit()
                local InvisibleState=Runtime.UniversalInvisibleState
                local Holder=(InvisibleState and InvisibleState.Active and InvisibleState.RealCharacter) or Character()
                local H=Holder and Holder:FindFirstChildOfClass("Humanoid")
                if H then pcall(function() H:UnequipTools() end) end
                local Backpack=Player:FindFirstChildOfClass("Backpack")
                if Holder and Backpack then
                    for _,Tool in ipairs(Holder:GetChildren()) do
                        if Tool:IsA("Tool") and (Tool:FindFirstChild("EatRemote") or string.find(string.lower(Tool.Name),"fruit",1,true)) then
                            pcall(function() Tool.Parent=Backpack end)
                        end
                    end
                end
            end
            local function CollectOneSpawnedFruit(Fruit)
                if not Fruit or not Fruit.Parent or not FruitWanted(Fruit) then return false end
                local InitialRoot=GetRoot(Fruit)
                if not InitialRoot then return false end
                Runtime.BloxFruitActiveTarget=Fruit
                Runtime.BloxFruitCollector.SetStatus("Travelling to spawned fruit",Fruit)
                local Collected=false
                local function LiveFruitCF()
                    local R=Fruit and Fruit.Parent and GetRoot(Fruit)
                    return R and (R.CFrame*CFrame.new(0,1.35,0)) or nil
                end
                local FirstCF=LiveFruitCF()
                if not FirstCF then return false end
                if not ProfileTravelToCFrame(FirstCF,LiveFruitCF) then return false end

                local Deadline=os.clock()+2.75
                repeat
                    if SpawnedFruitCollected(Fruit) then Collected=true; break end
                    local FruitRoot=GetRoot(Fruit)
                    local Me=Root()
                    if not FruitRoot or not Me then break end
                    Runtime.BloxFruitCollector.SetStatus("Collecting spawned fruit",Fruit,(Me.Position-FruitRoot.Position).Magnitude)
                    if (Me.Position-FruitRoot.Position).Magnitude>3.5 then
                        ProfileTravelToCFrame(FruitRoot.CFrame*CFrame.new(0,1.15,0),LiveFruitCF)
                        Me=Root()
                    end
                    if Me and FruitRoot and type(firetouchinterest)=="function" then
                        pcall(function()
                            firetouchinterest(Me,FruitRoot,0)
                            RunService.Heartbeat:Wait()
                            firetouchinterest(Me,FruitRoot,1)
                        end)
                    end
                    local Prompt=Fruit:FindFirstChildWhichIsA("ProximityPrompt",true)
                    if Prompt and type(fireproximityprompt)=="function" then pcall(function() fireproximityprompt(Prompt) end) end
                    task.wait(0.10)
                until os.clock()>=Deadline or Unloaded

                Collected=Collected or SpawnedFruitCollected(Fruit)
                if Collected then
                    Runtime.BloxFruitCollector.SetStatus("Fruit collected • checking for another",Fruit,0)
                    UnequipCollectedFruit()
                    task.wait(0.08)
                else
                    Runtime.BloxFruitCollector.SetStatus("Collection not confirmed • skipping this fruit",Fruit,nil)
                end
                return Collected
            end

            local function CollectSpawnedFruitBatchAndReturnCafe(FirstFruit,Options)
                if Runtime.BloxFruitCollectBusy then return false,0 end
                Options=type(Options)=="table" and Options or {}
                local ReturnToCafe=Options.ReturnToCafe~=false
                local ResumeCFrame=typeof(Options.ResumeCFrame)=="CFrame" and Options.ResumeCFrame or nil
                if FirstFruit and (not FirstFruit.Parent or not FruitWanted(FirstFruit)) then FirstFruit=nil end
                Runtime.BloxFruitCollectBusy=true
                Runtime.BloxFruitReturningToCafe=false
                local CollectedCount=0
                local ReturnSucceeded=nil
                local Failed=setmetatable({}, {__mode="k"})
                local LastFruit=nil

                -- One status worker covers the whole batch instead of spawning one per fruit.
                task.spawn(function()
                    while Runtime.BloxFruitCollectBusy and not Unloaded do
                        local Fruit=Runtime.BloxFruitActiveTarget
                        if Runtime.BloxFruitReturningToCafe and typeof(Runtime.BloxFruitStatusTargetCFrame)=="CFrame" then
                            local Me=Root()
                            local D=Me and (Me.Position-Runtime.BloxFruitStatusTargetCFrame.Position).Magnitude or nil
                            Runtime.BloxFruitCollector.SetStatus(Runtime.BloxFruitStatusPhase or "Returning to Café",Fruit,D)
                        elseif Fruit and Fruit.Parent and not SpawnedFruitCollected(Fruit) then
                            Runtime.BloxFruitCollector.SetStatus("Collecting fruit "..tostring(CollectedCount+1),Fruit)
                        end
                        task.wait(0.20)
                    end
                end)

                local Protected,Err=pcall(function()
                    local Fruit=FirstFruit
                    local EmptySince=nil
                    local SafetyCount=0
                    while not Unloaded and SafetyCount<40 do
                        if not Fruit or not Fruit.Parent or SpawnedFruitCollected(Fruit) or Failed[Fruit] then
                            Fruit=NearestFruit(Failed)
                        end
                        if not Fruit then
                            EmptySince=EmptySince or os.clock()
                            -- Give streaming/newly dropped fruits a short chance to appear before
                            -- committing to the one Café return trip.
                            if os.clock()-EmptySince>=0.55 then break end
                            task.wait(0.10)
                            Fruit=NearestFruit(Failed)
                            continue
                        end
                        EmptySince=nil
                        SafetyCount+=1
                        LastFruit=Fruit
                        local Remaining=SpawnedFruitCount(Failed)
                        Runtime.BloxFruitCollector.SetStatus(
                            "Fruit route • "..tostring(CollectedCount).." collected • "..tostring(Remaining).." detected",
                            Fruit
                        )
                        if CollectOneSpawnedFruit(Fruit) then
                            CollectedCount+=1
                        else
                            -- Do not let one bad fruit trap the whole route. Continue to every
                            -- other fruit and leave this one for the next collector cycle.
                            Failed[Fruit]=true
                        end
                        Fruit=NearestFruit(Failed)
                    end

                    if CollectedCount>0 then
                        Runtime.BloxFruitActiveTarget=nil
                        if ReturnToCafe then
                            Runtime.BloxFruitCollector.SetStatus(
                                "All detected fruits collected • returning to Café once",
                                LastFruit,
                                0
                            )
                            ReturnSucceeded=Runtime.BloxFruitCollector.TravelBack(LastFruit)
                            if not ReturnSucceeded then Runtime.BloxFruitCollector.SetStatus("Collected • safe Café surface unavailable; stayed put",LastFruit,nil) end
                        elseif ResumeCFrame then
                            Runtime.BloxFruitCollector.SetStatus("Fruit route complete • returning to Auto Farm",LastFruit,0)
                            if not ProfileTravelToCFrame(ResumeCFrame) then
                                Runtime.BloxFruitCollector.SetStatus("Fruit route complete • Auto Farm will reacquire route",LastFruit,nil)
                            end
                        else
                            Runtime.BloxFruitCollector.SetStatus("Fruit route complete • resuming Auto Farm",LastFruit,0)
                        end
                    end
                end)

                Runtime.BloxFruitReturningToCafe=false
                Runtime.BloxFruitCollectBusy=false
                Runtime.BloxFruitActiveTarget=nil
                Runtime.BloxFruitStatusTargetCFrame=nil
                Runtime.BloxFruitStatusPhase=nil
                if not Protected and tostring(Err):find("BANANI_CANCELLED",1,true) then return false,CollectedCount end
                if not Protected then warn("BANANIHUB | Fruit batch failed: "..tostring(Err)) end
                return Protected and CollectedCount>0,CollectedCount,ReturnSucceeded
            end
            Runtime.BloxRunFruitInterrupt=function()
                if not State.BloxAutoFruitActive or not Runtime.BloxAutoLevelActive then
                    Runtime.BloxFruitInterruptPending=nil
                    return false
                end
                local Fruit=Runtime.BloxFruitInterruptPending
                if not Fruit or not Fruit.Parent or SpawnedFruitCollected(Fruit) or not FruitWanted(Fruit) then
                    Fruit=NearestFruit()
                end
                Runtime.BloxFruitInterruptPending=nil
                if not Fruit then return false end

                local SavedStage=Runtime.BloxFarmStage or "FindQuest"
                local SavedQuest=AutoFarmQuest
                local SavedRoot=Root()
                local SavedCFrame=SavedRoot and SavedRoot.CFrame or nil
                Runtime.BloxFruitInterruptActive=true
                Runtime.BloxWaitingUnderground=false
                Runtime.BloxUndergroundWaitCF=nil
                SetAutoFarmStatus("Fruit detected • Auto Farm paused")
                Runtime.BloxFruitCollector.SetStatus("Auto Farm paused • collecting spawned fruit",Fruit)

                local OK,Count=CollectSpawnedFruitBatchAndReturnCafe(Fruit,{ReturnToCafe=false,ResumeCFrame=SavedCFrame})
                Runtime.BloxFruitInterruptActive=false
                Runtime.BloxFruitInterruptPending=nil
                AutoFarmTarget=nil
                Runtime.BloxMobQueue={}
                BloxEnemySnapshotState.At=0

                local ResumeQuest=SavedQuest and DetectActiveQuest(SavedQuest) or nil
                if SavedQuest and ResumeQuest and ResumeQuest.Matched and not ResumeQuest.Complete then
                    AutoFarmQuest=SavedQuest
                    Runtime.ActiveBloxQuest=SavedQuest
                    if SavedStage=="Fight" or SavedStage=="TravelMobs" then
                        Runtime.BloxFarmStage="TravelMobs"
                    elseif SavedStage=="ConfirmQuest" or SavedStage=="StartQuest" or SavedStage=="TravelQuest" then
                        Runtime.BloxFarmStage=SavedStage
                    else
                        Runtime.BloxFarmStage="TravelMobs"
                    end
                    SetAutoFarmStatus((OK and ("Collected "..tostring(Count).." fruit(s) • resuming quest") or "Fruit pickup ended • resuming quest"))
                else
                    AutoFarmQuest=nil
                    Runtime.ActiveBloxQuest=nil
                    Runtime.BloxFarmStage="FindQuest"
                    SetAutoFarmStatus((OK and ("Collected "..tostring(Count).." fruit(s) • reacquiring quest") or "Fruit pickup ended • reacquiring quest"))
                end
                AutoFarmNextAcquire=0
                -- Resume is explicit rather than relying on the next passive-loop tick. The deferred
                -- call runs after this AutoFarmStep returns, so movement ownership is already clean.
                task.defer(function()
                    if not Unloaded and Runtime.BloxAutoLevelActive and Runtime.BloxEnsureAutoFarmAfterFruit then
                        Runtime.BloxEnsureAutoFarmAfterFruit(true)
                    end
                end)
                return OK,Count
            end
            Runtime.BloxFruitDetectorCards=Runtime.BloxFruitDetectorCards or setmetatable({}, {__mode="k"})
            Runtime.BloxFruitDetectorRootCards=Runtime.BloxFruitDetectorRootCards or setmetatable({}, {__mode="k"})
            Runtime.BloxFruitDetectorRootClaims=Runtime.BloxFruitDetectorRootClaims or setmetatable({}, {__mode="k"})
            Runtime.BloxFruitDetectorPending=Runtime.BloxFruitDetectorPending or setmetatable({}, {__mode="k"})
            Runtime.BloxFruitDetectorLive=Runtime.BloxFruitDetectorLive or setmetatable({}, {__mode="k"})
            Runtime.BloxFruitDetectorReady=Runtime.BloxFruitDetectorReady==true
            Runtime.BloxFruitVisualCache=Runtime.BloxFruitVisualCache or {}
            Runtime.BloxFruitExactIconCache=Runtime.BloxFruitExactIconCache or {}
            Runtime.BloxFruitPreloadedImages=Runtime.BloxFruitPreloadedImages or {}
            Runtime.BloxFruitIconPrimeGeneration=Runtime.BloxFruitIconPrimeGeneration or 0
            Runtime.BloxFruitDetector=Runtime.BloxFruitDetector or {}
            Runtime.BloxFruitDetector.CurrentRoster={
                "Rocket","Spin","Blade","Spring","Bomb","Smoke","Spike","Flame","Ice","Sand","Dark",
                "Eagle","Diamond","Light","Rubber","Ghost","Magma","Quake","Buddha","Love","Creation",
                "Spider","Sound","Phoenix","Portal","Lightning","Pain","Blizzard","Gravity","Mammoth",
                "T-Rex","Dough","Shadow","Venom","Gas","Spirit","Tiger","Yeti","Magnet","Kitsune","Control","Dragon"
            }
            Runtime.BloxFruitDetector.LegacyAliases={
                chop="Blade", falcon="Eagle", barrier="Creation", rumble="Lightning", leopard="Tiger",
                revive="Ghost", paw="Pain", door="Portal", soul="Spirit",
                dragonwest="Dragon", dragoneast="Dragon", westdragon="Dragon", eastdragon="Dragon"
            }
            Runtime.BloxFruitDetector.CatalogNames=Runtime.BloxFruitDetector.CatalogNames or {}
            Runtime.BloxFruitDetector.CatalogBuiltAt=Runtime.BloxFruitDetector.CatalogBuiltAt or 0
            function Runtime.BloxFruitDetector.NormalizeFruitKey(Value)
                local Raw=string.lower(tostring(Value or ""))
                Raw=Raw:gsub("^%s+",""):gsub("%s+$","")
                    :gsub("^blox%s+fruit%s*[:%-_]*%s*","")
                    :gsub("^demon%s+fruit%s*[:%-_]*%s*","")
                    :gsub("^fruit%s*[:%-_]*%s*","")
                    :gsub("%s+fruit$","")
                return Raw:gsub("[^%w]","")
            end
            function Runtime.BloxFruitDetector.RegisterCatalogValue(Value,Pretty)
                local Key=Runtime.BloxFruitDetector.NormalizeFruitKey(Value)
                if Key=="" or not Pretty then return end
                Runtime.BloxFruitDetector.CatalogNames[Key]=Pretty
                -- Most internal fruit ids use a repeated-name form such as Rocket-Rocket.
                -- Seed that compact key too so short names like Ice-Ice and Gas-Gas still resolve
                -- even if the live GetFruits catalog is temporarily unavailable.
                Runtime.BloxFruitDetector.CatalogNames[Key..Key]=Pretty
                local Raw=tostring(Value or "")
                local Suffix=Raw:match(":%s*(.-)%s*$")
                if Suffix then
                    local SKey=Runtime.BloxFruitDetector.NormalizeFruitKey(Suffix)
                    if SKey~="" then Runtime.BloxFruitDetector.CatalogNames[SKey]=Pretty end
                end
                local Left,Right=Raw:match("^%s*([^%-]+)%-(.-)%s*$")
                if Left and Right then
                    local L=Runtime.BloxFruitDetector.NormalizeFruitKey(Left)
                    local R=Runtime.BloxFruitDetector.NormalizeFruitKey(Right)
                    if L~="" and L==R then Runtime.BloxFruitDetector.CatalogNames[L]=Pretty end
                end
            end
            function Runtime.BloxFruitDetector.ResolveKnownName(Value)
                local Key=Runtime.BloxFruitDetector.NormalizeFruitKey(Value)
                if Key=="" then return nil end
                local Direct=Runtime.BloxFruitDetector.CatalogNames[Key]
                if Direct then return Direct end
                local Alias=Runtime.BloxFruitDetector.LegacyAliases[Key]
                if Alias then return Alias end
                local Best,BestLength=nil,0
                for Known,Pretty in pairs(Runtime.BloxFruitDetector.CatalogNames) do
                    if #Known>=4 and #Known>BestLength and string.find(Key,Known,1,true) then
                        Best,BestLength=Pretty,#Known
                    end
                end
                for Legacy,Pretty in pairs(Runtime.BloxFruitDetector.LegacyAliases) do
                    if #Legacy>=4 and #Legacy>BestLength and string.find(Key,Legacy,1,true) then
                        Best,BestLength=Pretty,#Legacy
                    end
                end
                return Best
            end
            function Runtime.BloxFruitDetector.RefreshCatalog(Force)
                if not Force and os.clock()-(tonumber(Runtime.BloxFruitDetector.CatalogBuiltAt) or 0)<120 then return true end
                Runtime.BloxFruitDetector.CatalogNames={}
                for _,Pretty in ipairs(Runtime.BloxFruitDetector.CurrentRoster) do
                    Runtime.BloxFruitDetector.RegisterCatalogValue(Pretty,Pretty)
                end
                for Legacy,Pretty in pairs(Runtime.BloxFruitDetector.LegacyAliases) do
                    Runtime.BloxFruitDetector.RegisterCatalogValue(Legacy,Pretty)
                end
                local Ok,Fruits=Runtime.BloxReadDealer()
                if Ok and type(Fruits)=="table" then
                    for Key,Info in pairs(Fruits) do
                        local Raw
                        if type(Info)=="table" then Raw=Info.Name or Info.FruitName or Info.DisplayName end
                        if not Raw and type(Key)=="string" then Raw=Key end
                        if Raw then
                            local Pretty=Runtime.BloxFruitDetector.ResolveKnownName(Raw)
                            if not Pretty then
                                local RawText=tostring(Raw)
                                local Suffix=RawText:match(":%s*(.-)%s*$")
                                local Left,Right=RawText:match("^%s*([^%-]+)%-(.-)%s*$")
                                local Base=Suffix
                                if not Base and Left and Right
                                    and Runtime.BloxFruitDetector.NormalizeFruitKey(Left)==Runtime.BloxFruitDetector.NormalizeFruitKey(Right) then
                                    Base=Left
                                end
                                Base=Base or RawText
                                Base=Base:gsub("[_%-]+"," "):gsub("%s+"," "):gsub("^%s+",""):gsub("%s+$","")
                                if Base~="" then Pretty=Base end
                            end
                            if Pretty then Runtime.BloxFruitDetector.RegisterCatalogValue(Raw,Pretty) end
                        end
                    end
                end
                Runtime.BloxFruitDetector.CatalogBuiltAt=os.clock()
                return true
            end
            function Runtime.BloxFruitDetector.Identify(Obj)
                if not Obj then return nil end
                if next(Runtime.BloxFruitDetector.CatalogNames)==nil then pcall(Runtime.BloxFruitDetector.RefreshCatalog,true) end
                local Candidates={}
                local function Add(Value)
                    Value=tostring(Value or "")
                    if Value~="" then table.insert(Candidates,Value) end
                end
                pcall(function() Add(Obj:GetAttribute("OriginalName")) end)
                pcall(function() Add(Obj:GetAttribute("FruitName")) end)
                pcall(function() Add(Obj:GetAttribute("DisplayName")) end)
                pcall(function() if Obj:IsA("Tool") then Add(Obj.ToolTip) end end)
                for _,ChildName in ipairs({"OriginalName","FruitName","DisplayName","ItemName"}) do
                    local V=Obj:FindFirstChild(ChildName,true)
                    if V and V:IsA("StringValue") then Add(V.Value) end
                end
                Add(Obj.Name)
                for _,Value in ipairs(Candidates) do
                    local Pretty=Runtime.BloxFruitDetector.ResolveKnownName(Value)
                    if Pretty then return Pretty end
                end
                return nil
            end
            function Runtime.BloxFruitDetector.FruitLikeName(Name)
                if Runtime.BloxFruitDetector.ResolveKnownName(Name) then return true end
                local Lower=string.lower(tostring(Name or ""))
                return Lower~="" and string.find(Lower,"fruit",1,true)~=nil
            end
            function Runtime.BloxFruitDetector.ExcludedSource(Obj)
                local Current=Obj
                for _=1,9 do
                    if not Current or Current==workspace then break end
                    local Lower=string.lower(tostring(Current.Name or ""))
                    -- Shop/Gacha NPCs contain "Fruit" in their names but are not spawned fruits.
                    if string.find(Lower,"dealer",1,true)
                        or string.find(Lower,"gacha",1,true)
                        or string.find(Lower,"cousin",1,true)
                        or Lower=="zioles" then
                        return true
                    end
                    if Current:IsA("Model") and Current:FindFirstChildOfClass("Humanoid") then
                        return true
                    end
                    Current=Current.Parent
                end
                return false
            end
            function Runtime.BloxFruitDetector.Resolve(Obj)
                if not Obj or Runtime.BloxFruitDetector.ExcludedSource(Obj) then return nil end
                local Current=Obj
                for _=1,8 do
                    if not Current or Current==workspace then break end
                    if Current:IsA("Tool") and Current:IsDescendantOf(workspace) then
                        local Handle=Current:FindFirstChild("Handle")
                        local Physical=Handle and Handle:IsA("BasePart")
                        local Pretty=Runtime.BloxFruitDetector.Identify(Current)
                        local HasFruitSignal=Pretty~=nil
                            or Current:FindFirstChild("EatRemote",true)~=nil
                            or Current:GetAttribute("OriginalName")~=nil
                            or Runtime.BloxFruitDetector.FruitLikeName(Current.Name)
                        if Physical and HasFruitSignal and not Runtime.BloxFruitDetector.ExcludedSource(Current) then return Current end
                    end
                    Current=Current.Parent
                end
                Current=Obj
                for _=1,6 do
                    if not Current or Current==workspace then break end
                    if Current:IsA("Model") and Current:IsDescendantOf(workspace)
                        and not Runtime.BloxFruitDetector.ExcludedSource(Current)
                        and not Current:FindFirstChildOfClass("Humanoid") then
                        local Inner=Current:FindFirstChildWhichIsA("Tool",true)
                        if Inner then
                            local Resolved=Runtime.BloxFruitDetector.Resolve(Inner)
                            if Resolved then return Resolved end
                        end
                        local Pretty=Runtime.BloxFruitDetector.Identify(Current)
                        local HasMetadata=Current:GetAttribute("OriginalName")~=nil
                            or Current:GetAttribute("FruitName")~=nil
                            or Current:FindFirstChild("EatRemote",true)~=nil
                        if Pretty and HasMetadata and GetRoot(Current) then return Current end
                    end
                    Current=Current.Parent
                end
                return nil
            end
            function Runtime.BloxFruitDetector.ScanAll()
                local Out,Seen={},{}
                local function Add(Obj)
                    local Fruit=Runtime.BloxFruitDetector.Resolve(Obj)
                    if Fruit and not Seen[Fruit] then
                        Seen[Fruit]=true
                        table.insert(Out,Fruit)
                    end
                end
                -- Spawned fruits are normally physical Tools directly under workspace. Scan that
                -- cheap path first; only inspect descendant Tools for streaming/wrapper edge cases.
                for _,Obj in ipairs(workspace:GetChildren()) do
                    if Obj:IsA("Tool") or Obj:IsA("Model") then Add(Obj) end
                end
                local Descendants=workspace:GetDescendants()
                for Index,Obj in ipairs(Descendants) do
                    if Obj:IsA("Tool") then Add(Obj) end
                    if Index%600==0 then task.wait() end
                end
                return Out
            end
            local function EnsureBloxFruitDetectorGui()
                local ParentGui=Player:FindFirstChildOfClass("PlayerGui") or CoreGui
                if not ParentGui then return nil,nil end
                local Screen=Runtime.BloxFruitDetectorGui
                if Screen and Screen.Parent then return Screen,Screen:FindFirstChild("Host") end
                Screen=Instance.new("ScreenGui")
                Screen.Name="BananiBloxFruitDetector"
                Screen.ResetOnSpawn=false
                Screen.IgnoreGuiInset=true
                Screen.DisplayOrder=2147482500
                Screen.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
                Screen.Parent=ParentGui
                Runtime.BloxFruitDetectorGui=Screen
                if ParentGui:IsA("PlayerGui") then HubGuiTracker.Owned[Screen]=true end

                local Host=Instance.new("ScrollingFrame")
                Host.Name="Host"
                Host.AnchorPoint=Vector2.new(1,0)
                Host.Position=UDim2.new(1,-18,0,84)
                Host.Size=UDim2.fromOffset(492,520)
                Host.BackgroundTransparency=1
                Host.BorderSizePixel=0
                Host.ScrollBarThickness=3
                Host.ScrollBarImageColor3=Color3.fromRGB(255,210,55)
                Host.ScrollBarImageTransparency=0.28
                Host.CanvasSize=UDim2.fromOffset(0,0)
                Host.ScrollingDirection=Enum.ScrollingDirection.Y
                Host.Parent=Screen
                local List=Instance.new("UIListLayout")
                List.FillDirection=Enum.FillDirection.Vertical
                List.HorizontalAlignment=Enum.HorizontalAlignment.Right
                List.Padding=UDim.new(0,9)
                List.SortOrder=Enum.SortOrder.LayoutOrder
                List.Parent=Host
                TrackConnection(List:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                    if Host.Parent then Host.CanvasSize=UDim2.fromOffset(0,List.AbsoluteContentSize.Y+8) end
                end))
                return Screen,Host
            end
            Runtime.BloxFruitIconCache=Runtime.BloxFruitIconCache or {}
            Runtime.BloxFruitDetector.NormalizeImage=function(Value)
                local S=tostring(Value or "")
                if S=="" then return nil end
                if string.match(S,"^rbxassetid://%d+$") or string.match(S,"^rbxasset://") or string.match(S,"^rbxthumb://") or string.match(S,"^https?://") then return S end
                local Id=string.match(S,"(%d+)")
                if Id then return "rbxassetid://"..Id end
                return nil
            end
            Runtime.BloxFruitDetector.VisualKey=function(Value)
                local Name=tostring(Value or ""):gsub("^Blox%s+Fruit%s*[:%-_]*%s*",""):gsub("%s+[Ff]ruit$","")
                local Left,Right=Name:match("^%s*([^%-]+)%-(.-)%s*$")
                if Left and Right then
                    local A=string.lower(Left):gsub("[^%w]","")
                    local B=string.lower(Right):gsub("[^%w]","")
                    if A~="" and A==B then Name=Left end
                end
                return string.lower(Name):gsub("[^%w]","")
            end
