            Runtime.BloxFruitDetector.DecodeEmbeddedBase64=function(Data)
                local Fast=nil
                pcall(function()
                    if crypt and crypt.base64 and crypt.base64.decode then Fast=crypt.base64.decode
                    elseif syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then Fast=syn.crypt.base64.decode
                    elseif type(base64_decode)=="function" then Fast=base64_decode end
                end)
                if Fast then
                    local Ok,Decoded=pcall(Fast,Data)
                    if Ok and type(Decoded)=="string" and #Decoded>0 then return Decoded end
                end
                local Alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
                Data=tostring(Data or ""):gsub("[^"..Alphabet.."=]","")
                return (Data:gsub(".",function(Char)
                    if Char=="=" then return "" end
                    local Index=Alphabet:find(Char,1,true)
                    if not Index then return "" end
                    Index=Index-1
                    local Bits=""
                    for I=6,1,-1 do Bits=Bits..((Index%(2^I)-Index%(2^(I-1))>0) and "1" or "0") end
                    return Bits
                end):gsub("%d%d%d?%d?%d?%d?%d?%d?",function(Bits)
                    if #Bits~=8 then return "" end
                    local Value=0
                    for I=1,8 do if Bits:sub(I,I)=="1" then Value=Value+2^(8-I) end end
                    return string.char(Value)
                end))
            end
            Runtime.BloxFruitDetector.ResolveStaticSpriteAsset=function()
                if Runtime.BloxFruitDetectorStaticSpriteAsset~=nil then
                    return Runtime.BloxFruitDetectorStaticSpriteAsset or nil
                end
                local Loader=getcustomasset or getsynasset or getcustomassetfunc
                if not Loader or not writefile then
                    Runtime.BloxFruitDetectorStaticSpriteAsset=false
                    return nil
                end
                local Path="BananiHub_FruitSpriteAtlas_Embedded.png"
                local Ready=false
                if isfile then pcall(function() Ready=isfile(Path)==true end) end
                if not Ready then
                    local Bytes=Runtime.BloxFruitDetector.DecodeEmbeddedBase64(Runtime.BloxFruitDetector.EmbeddedSpriteBase64)
                    if type(Bytes)~="string" or #Bytes<1000 then
                        Runtime.BloxFruitDetectorStaticSpriteAsset=false
                        return nil
                    end
                    local OkWrite=pcall(writefile,Path,Bytes)
                    if not OkWrite then
                        Runtime.BloxFruitDetectorStaticSpriteAsset=false
                        return nil
                    end
                end
                local Ok,Asset=pcall(Loader,Path)
                if Ok and Asset then
                    Runtime.BloxFruitDetectorStaticSpriteAsset=Asset
                    return Asset
                end
                Runtime.BloxFruitDetectorStaticSpriteAsset=false
                return nil
            end
            Runtime.BloxFruitDetector.ResolveStaticSheetVisual=function(Display)
                local Key=Runtime.BloxFruitDetector.VisualKey(Display)
                local IconKey=Runtime.BloxFruitDetector.StaticIconAliases[Key] or Key
                local Meta=Runtime.BloxFruitDetector.StaticGridMap[IconKey]
                if not Meta then return nil end
                local Asset=Runtime.BloxFruitDetector.ResolveStaticSpriteAsset()
                if not Asset then
                    return {
                        Image=nil,
                        Rarity=Meta.Rarity,
                        ExactFruitKey=Key,
                        IconKey=IconKey,
                        Source="StaticSheetMissing",
                        Color=Runtime.BloxFruitDetector.RarityColor(Meta.Rarity)
                    }
                end
                local Spec=Runtime.BloxFruitDetector.StaticSheetSpec
                local OffsetX=Spec.Left+((Meta.Col-1)*(Spec.CellWidth+Spec.GapX))
                local OffsetY=Spec.Top+((Meta.Row-1)*(Spec.CellHeight+Spec.GapY))
                return {
                    Image=Asset,
                    ImageRectOffset=Vector2.new(OffsetX,OffsetY),
                    ImageRectSize=Vector2.new(Spec.CellWidth,Spec.CellHeight),
                    ScaleType=Enum.ScaleType.Stretch,
                    Rarity=Meta.Rarity,
                    ExactFruitKey=Key,
                    IconKey=IconKey,
                    Source="StaticSheet",
                    Color=Runtime.BloxFruitDetector.RarityColor(Meta.Rarity)
                }
            end
            Runtime.BloxFruitDetector.RarityColor=function(Rarity,Fallback)
                local R=string.lower(tostring(Rarity or ""))
                if string.find(R,"myth",1,true) then return Color3.fromRGB(219,58,79) end
                if string.find(R,"legend",1,true) then return Color3.fromRGB(157,66,215) end
                if string.find(R,"rare",1,true) then return Color3.fromRGB(69,112,230) end
                if string.find(R,"uncommon",1,true) then return Color3.fromRGB(67,167,101) end
                if string.find(R,"common",1,true) then return Color3.fromRGB(104,108,121) end
                return typeof(Fallback)=="Color3" and Fallback or Color3.fromRGB(57,49,72)
            end
            Runtime.BloxStoredFruitInventory=function(MaxAge)
                local Cached=Runtime.BloxStoredFruitInventoryCache
                if Cached and os.clock()-Cached.At<(tonumber(MaxAge) or 0) then return Cached.Ok,Cached.Data end
                -- Blox Fruits keeps stored fruits behind the fruit-specific inventory call.
                -- Fall back to the broad inventory response only for compatibility with older servers.
                local Ok,Data=QueryRemote(BloxCommF(),"getInventoryFruits")
                if not Ok or type(Data)~="table" then Ok,Data=QueryRemote(BloxCommF(),"getInventory") end
                Runtime.BloxStoredFruitInventoryCache={At=os.clock(),Ok=Ok,Data=Data}
                return Ok,Data
            end
            -- v5.18.16: detector art is embedded and mapped statically; no inventory/dealer icon search is used.
            -- v5.18.4: build the exact fruit->inventory-icon table before a spawn popup needs it.
            -- This avoids a PlayerGui search on the hot path and lets Roblox download the image bytes early.
            Runtime.BloxFruitDetector.CacheExactVisual=function(Display,Visual,Priority)
                local Key=Runtime.BloxFruitDetector.VisualKey(Display)
                if Key=="" or Key=="fruit" or Key=="bloxfruit" or type(Visual)~="table" or not Visual.Image then return false end
                Priority=tonumber(Priority) or 0
                local Existing=Runtime.BloxFruitExactIconCache[Key]
                if Existing and (tonumber(Existing.Priority) or 0)>Priority then return false end
                local Copy={}
                for K,V in pairs(Visual) do Copy[K]=V end
                Copy.Priority=Priority
                Copy.ExactFruitKey=Key
                Copy.At=os.clock()
                Runtime.BloxFruitExactIconCache[Key]=Copy
                Runtime.BloxFruitVisualCache[Key]=Copy
                return true
            end

            Runtime.BloxFruitDetector.PreloadExactIcons=function()
                local Asset=Runtime.BloxFruitDetector.ResolveStaticSpriteAsset()
                if not Asset then return 0 end
                local PG=Player:FindFirstChildOfClass("PlayerGui") or CoreGui
                local Holder=Runtime.BloxFruitIconPreloadGui
                if not Holder or not Holder.Parent then
                    Holder=Instance.new("ScreenGui")
                    Holder.Name="BananiFruitIconPreloader"
                    Holder.ResetOnSpawn=false
                    Holder.IgnoreGuiInset=true
                    Holder.DisplayOrder=-1000
                    Holder.Enabled=true
                    Holder.Parent=PG
                    Runtime.BloxFruitIconPreloadGui=Holder
                end
                local Warm=Runtime.BloxFruitSpriteWarmImage
                if not Warm or not Warm.Parent then
                    Warm=Instance.new("ImageLabel")
                    Warm.Name="FruitAtlasWarm"
                    Warm.BackgroundTransparency=1
                    Warm.ImageTransparency=1
                    Warm.Visible=true
                    Warm.Position=UDim2.fromOffset(-16,-16)
                    Warm.Size=UDim2.fromOffset(2,2)
                    Warm.Parent=Holder
                    Runtime.BloxFruitSpriteWarmImage=Warm
                end
                Warm.Image=Asset
                local Ok=pcall(function() ContentProvider:PreloadAsync({Warm}) end)
                if Ok then Runtime.BloxFruitPreloadedImages[Asset]=true end
                return Ok and 1 or 0
            end

            Runtime.BloxFruitDetector.PrimeExactIcons=function()
                if Runtime.BloxFruitIconPrimeReady and Runtime.BloxFruitDetectorStaticSpriteAsset then return true end
                Runtime.BloxFruitIconPrimeReady=false
                local Asset=Runtime.BloxFruitDetector.ResolveStaticSpriteAsset()
                if not Asset then
                    Runtime.BloxFruitIconPrimeReady=true
                    return false
                end
                Runtime.BloxFruitDetector.PreloadExactIcons()
                -- Build every exact name -> sprite rectangle before detector events are connected.
                -- After this point detection only needs the fruit name key; it never scans UI or waits for art.
                for Key in pairs(Runtime.BloxFruitDetector.StaticGridMap) do
                    local Display=(Runtime.BloxFruitDetector.StaticDisplayNames[Key] or Key).." Fruit"
                    local Visual=Runtime.BloxFruitDetector.ResolveStaticSheetVisual(Display)
                    if Visual and Visual.Image then Runtime.BloxFruitDetector.CacheExactVisual(Display,Visual,300) end
                end
                for Alias in pairs(Runtime.BloxFruitDetector.StaticIconAliases) do
                    local Display=(Runtime.BloxFruitDetector.StaticDisplayNames[Alias] or Alias).." Fruit"
                    local Visual=Runtime.BloxFruitDetector.ResolveStaticSheetVisual(Display)
                    if Visual and Visual.Image then Runtime.BloxFruitDetector.CacheExactVisual(Display,Visual,300) end
                end
                Runtime.BloxFruitIconPrimeReady=true
                return true
            end


            -- One exact fruit -> one exact icon. The resolver never substitutes another fruit,
            -- an all-fruits picture, a generic icon, a 3D model, or a Tool/mesh texture.
            Runtime.BloxFruitDetector.ResolveVisual=function(Fruit,ForceRefresh)
                if not Fruit then return {Image=nil,Rarity=nil,Color=Color3.fromRGB(57,49,72)} end
                local Display=(Runtime.BloxFruitCollector and Runtime.BloxFruitCollector.DisplayName and Runtime.BloxFruitCollector.DisplayName(Fruit)) or Fruit.Name
                local Key=Runtime.BloxFruitDetector.VisualKey(Display)
                if Key=="" or Key=="unknown" or Key=="fruit" or Key=="bloxfruit" then
                    return {Image=nil,Rarity=nil,Color=Color3.fromRGB(57,49,72),ExactFruitKey=Key,Source="StaticNameMap"}
                end
                local Exact=Runtime.BloxFruitExactIconCache[Key]
                if Exact and Exact.Image then return Exact end
                -- Alias/name fallback is still static: no PlayerGui/dealer/treasury search occurs here.
                local Visual=Runtime.BloxFruitDetector.ResolveStaticSheetVisual(Display)
                if not Visual then
                    return {Image=nil,Rarity=nil,Color=Color3.fromRGB(57,49,72),ExactFruitKey=Key,Source="StaticNameMap"}
                end
                Visual.Color=Visual.Color or Runtime.BloxFruitDetector.RarityColor(Visual.Rarity,Visual.Background)
                Visual.At=os.clock()
                if Visual.Image then Runtime.BloxFruitDetector.CacheExactVisual(Display,Visual,300) end
                return Visual
            end

            -- v5.18.2: premium live fruit detector card. The visual remains strict: one exact
            -- fruit-specific inventory icon only. Distance uses the closest physical point on
            -- the fruit part when available and refreshes much faster than the old 0.35s loop.
            Runtime.BloxFruitDetector.DistanceStuds=function(Fruit)
                Fruit=Runtime.BloxFruitDetector.Resolve(Fruit)
                if not Fruit then return nil end
                local Me=Root()
                if not Me or not Me.Parent then return nil end
                local Target
                if Fruit:IsA("BasePart") then
                    Target=Fruit
                elseif Fruit:IsA("Tool") then
                    local Handle=Fruit:FindFirstChild("Handle")
                    if Handle and Handle:IsA("BasePart") then Target=Handle end
                end
                if not Target then Target=GetRoot(Fruit) end
                if not Target or not Target:IsA("BasePart") then return nil end

                -- Center-to-center is the compatibility fallback. GetClosestPointOnSurface makes
                -- the displayed number represent the actual edge of the fruit instead of the
                -- center of a large handle/mesh, which is noticeably more accurate up close.
                local TargetPoint=Target.Position
                pcall(function()
                    local Closest=Target:GetClosestPointOnSurface(Me.Position)
                    if typeof(Closest)=="Vector3" then TargetPoint=Closest end
                end)
                return math.max(0,(TargetPoint-Me.Position).Magnitude)
            end
            Runtime.BloxFruitDetector.DirectionInfo=function(Fruit)
                Fruit=Runtime.BloxFruitDetector.Resolve(Fruit)
                if not Fruit then return 0,"UNKNOWN",false end
                local Cam=workspace.CurrentCamera
                local Target=GetRoot(Fruit)
                if not Target or not Cam then return 0,"UNKNOWN",false end
                local Point,OnScreen=Cam:WorldToViewportPoint(Target.Position)
                local View=Cam.ViewportSize
                local Center=Vector2.new(View.X*.5,View.Y*.5)
                local Delta=Vector2.new(Point.X-Center.X,Point.Y-Center.Y)
                -- WorldToViewportPoint mirrors when the target is behind the camera. Flip the
                -- vector back so the arrow still tells the player which way to turn.
                if Point.Z<0 then Delta=-Delta end
                if Delta.Magnitude<5 then return 0,(OnScreen and Point.Z>0) and "CENTER" or "BEHIND",OnScreen and Point.Z>0 end
                local Angle=math.deg(math.atan2(Delta.Y,Delta.X))+90
                Angle=(Angle%360+360)%360
                local Label
                if OnScreen and Point.Z>0 then
                    Label="ON SCREEN"
                elseif Point.Z<0 then
                    Label="BEHIND"
                elseif Angle<22.5 or Angle>=337.5 then Label="UP"
                elseif Angle<67.5 then Label="UP-RIGHT"
                elseif Angle<112.5 then Label="RIGHT"
                elseif Angle<157.5 then Label="DOWN-RIGHT"
                elseif Angle<202.5 then Label="DOWN"
                elseif Angle<247.5 then Label="DOWN-LEFT"
                elseif Angle<292.5 then Label="LEFT"
                else Label="UP-LEFT" end
                return Angle,Label,OnScreen and Point.Z>0
            end

