                        if not Card.Parent then return end
                        local SettleStroke=Runtime.TrackTween(TweenService:Create(Stroke,TweenInfo.new(.22,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),{Transparency=.20}),"FruitAlert:SettleStroke","FruitAlertTweens")
                        local SettleGlow=Runtime.TrackTween(TweenService:Create(IconGlow,TweenInfo.new(.24,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),{BackgroundTransparency=.84,Size=UDim2.fromOffset(84,84)}),"FruitAlert:SettleGlow","FruitAlertTweens")
                        local SettleDot=Runtime.TrackTween(TweenService:Create(RadarScale,TweenInfo.new(.20,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),{Scale=1}),"FruitAlert:SettleDot","FruitAlertTweens")
                        SettleStroke:Play(); SettleGlow:Play(); SettleDot:Play(); ScanBeam.Visible=false
                    end)
                    -- One restrained edge shimmer on arrival; no constant looping animation.
                    task.spawn(function()
                        if not Card.Parent then return end
                        StrokeGradient.Offset=Vector2.new(-1,0)
                        local Shine=Runtime.TrackTween(TweenService:Create(StrokeGradient,TweenInfo.new(.44,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Offset=Vector2.new(1,0)}),"FruitAlert:Shine","FruitAlertTweens")
                        Shine:Play()
                    end)
                end

                task.spawn(function()
                    local NextVisualRefresh=0
                    while Card.Parent and not Unloaded do
                        if Runtime.BloxFruitDetector.Resolve(Fruit)~=Fruit then break end
                        local D=Runtime.BloxFruitDetector.DistanceStuds(Fruit)
                        local LiveName=Runtime.BloxFruitCollector.DisplayName(Fruit)
                        FruitName.Text=LiveName
                        local ArrowAngle,ArrowText,ArrowOnScreen=Runtime.BloxFruitDetector.DirectionInfo(Fruit)
                        local Turn=((ArrowAngle-ArrowRotation+180)%360)-180
                        ArrowRotation=(ArrowRotation+Turn*.42)%360
                        DirectionArrow.Text="↑"
                        DirectionArrow.Rotation=ArrowRotation
                        DirectionText.Text=ArrowText
                        DirectionBox.BackgroundColor3=ArrowOnScreen and Color3.fromRGB(14,46,35) or Color3.fromRGB(14,18,28)
                        DBS.Color=ArrowOnScreen and Color3.fromRGB(73,211,143) or AccentColor:Lerp(Color3.new(1,1,1),0.22)
                        if D then
                            local DistanceText
                            if D<1000 then DistanceText=string.format("%.1f studs",D) else DistanceText=string.format("%d studs",math.floor(D+0.5)) end
                            Distance.Text=DistanceText
                            Meta.Text=string.upper(tostring(Rarity.Text or "FRUIT")).."  •  "..DistanceText.."  •  "..ArrowText
                            -- Distance pod becomes slightly brighter nearby without changing the fruit rarity color.
                            local Near=math.clamp(1-(D/800),0,1)
                            Distance.BackgroundTransparency=0.10-(Near*0.05)
                            DS.Transparency=0.58-(Near*0.22)
                        else
                            Distance.Text="--.- studs"
                            Meta.Text=string.upper(tostring(Rarity.Text or "FRUIT")).."  •  distance unavailable  •  "..ArrowText
                        end

                        local Now=os.clock()
                        local VisualRetries=tonumber(Card:GetAttribute("VisualRetries")) or 0
                        if VisualRetries<18 and (Icon.Image=="" or Rarity.Text=="FRUIT") and Now>=NextVisualRefresh then
                            NextVisualRefresh=Now+(VisualRetries<8 and 0.15 or 0.75)
                            Card:SetAttribute("VisualRetries",VisualRetries+1)
                            local Updated=Runtime.BloxFruitDetector.ResolveVisual(Fruit,true)
                            if Updated.Image then
                                Icon.Image=Updated.Image
                                Icon.ImageRectOffset=typeof(Updated.ImageRectOffset)=="Vector2" and Updated.ImageRectOffset or Vector2.zero
                                Icon.ImageRectSize=typeof(Updated.ImageRectSize)=="Vector2" and Updated.ImageRectSize or Vector2.zero
                                Icon.ImageColor3=typeof(Updated.ImageColor3)=="Color3" and Updated.ImageColor3 or Color3.new(1,1,1)
                                Icon.ScaleType=Updated.ScaleType or Enum.ScaleType.Fit
                                IconFallback.Visible=false
                            else
                                IconFallback.Visible=true
                            end
                            if Updated.Rarity then
                                Rarity.Text=string.upper(tostring(Updated.Rarity))
                                -- Rarity is rendered in the single Meta line; no duplicate pill.
                            end
                            if Updated.Color then
                                AccentColor=Updated.Color
                                IWS.Color=Updated.Color:Lerp(Color3.new(1,1,1),0.42)
                                Accent.BackgroundColor3=Updated.Color:Lerp(Color3.new(1,1,1),0.18)
                                IconGlow.BackgroundColor3=Updated.Color
                                RadarDot.BackgroundColor3=Updated.Color:Lerp(Color3.new(1,1,1),0.35)
                                Signal.TextColor3=Updated.Color:Lerp(Color3.new(1,1,1),0.62)
                                Rarity.TextColor3=Updated.Color:Lerp(Color3.new(1,1,1),0.68)
                                InfoPill.TextColor3=Updated.Color:Lerp(Color3.new(1,1,1),.56)
                                IPS.Color=Updated.Color
                                DS.Color=Updated.Color:Lerp(Color3.new(1,1,1),0.25)
                            end
                        end
                        local DetectorFPS=tonumber(LiveTelemetry and LiveTelemetry.FPS) or 60
                        local WaitTime=.16
                        if DetectorFPS>0 and DetectorFPS<35 then WaitTime=.28
                        elseif D and D>1200 then WaitTime=.24
                        elseif D and D>600 then WaitTime=.20 end
                        task.wait(WaitTime)
                    end

                    pcall(function() Pulse:Cancel() end)
                    pcall(function() ScanTween:Cancel() end)
                    pcall(function() GlowTween:Cancel() end)
                    pcall(function() DotTween:Cancel() end)
                    Runtime.BloxFruitDetectorCards[Fruit]=nil
                    if Runtime.BloxFruitDetector.Resolve(Fruit)~=Fruit then Runtime.BloxFruitDetectorLive[Fruit]=nil end
                    if FruitRoot and Runtime.BloxFruitDetectorRootCards[FruitRoot]==Card then Runtime.BloxFruitDetectorRootCards[FruitRoot]=nil end
                    if FruitRoot and Runtime.BloxFruitDetectorRootClaims[FruitRoot]==Fruit then Runtime.BloxFruitDetectorRootClaims[FruitRoot]=nil end
                    if Card.Parent then
                        Badge.Text="✓  CLEARED"
                        Badge.BackgroundColor3=Color3.fromRGB(39,44,57)
                        Badge.TextColor3=Color3.fromRGB(205,211,225)
                        Meta.Text="Fruit picked up or no longer on the ground"
                        local CloseScale=Runtime.TrackTween(TweenService:Create(Scale,TweenInfo.new(.19,Enum.EasingStyle.Quint,Enum.EasingDirection.In),{Scale=.97}),"FruitAlert:CloseScale","FruitAlertTweens")
                        local CloseCard=Runtime.TrackTween(TweenService:Create(Card,TweenInfo.new(.25,Enum.EasingStyle.Quint,Enum.EasingDirection.In),{Size=UDim2.fromOffset(468,0),BackgroundTransparency=1}),"FruitAlert:CloseCard","FruitAlertTweens")
                        task.wait(.16)
                        CloseScale:Play(); CloseCard:Play()
                        task.wait(.26)
                        if Card.Parent then Card:Destroy() end
                    end
                end)
            end

-- ==================================================================
-- [BH:BLOX] FRUIT DETECTOR
-- Deduplicated live fruit detection and premium alert card.
-- ==================================================================
            function Runtime.BloxFruitDetector.Register(Obj)
                local Fruit=Runtime.BloxFruitDetector.Resolve(Obj)
                if not Fruit then return end
                local FruitRoot=GetRoot(Fruit)
                if Runtime.BloxFruitDetectorLive[Fruit] then return end
                if FruitRoot then
                    local Claimed=Runtime.BloxFruitDetectorRootClaims[FruitRoot]
                    if Claimed and Claimed~=Fruit and Claimed.Parent then return end
                    local ExistingCard=Runtime.BloxFruitDetectorRootCards[FruitRoot]
                    if ExistingCard and ExistingCard.Parent then return end
                    Runtime.BloxFruitDetectorRootClaims[FruitRoot]=Fruit
                end
                Runtime.BloxFruitDetectorLive[Fruit]=true
                ShowBloxFruitSpawnPopup(Fruit)
                if State.BloxAutoFruitActive and Runtime.BloxAutoLevelActive and not Runtime.BloxFruitCollectBusy and FruitWanted(Fruit) then
                    Runtime.BloxFruitInterruptPending=Fruit
                    Runtime.BloxFruitCollector.SetStatus("Fruit detected • interrupting Auto Farm",Fruit)
                    if Runtime.Movement and Runtime.Movement.CancelMotion then pcall(function() Runtime.Movement.CancelMotion("BloxAutoLevel") end) end
                end
            end
            -- Show every fruit that is already on the ground when BananiHub loads. The old
            -- startup suppression made existing/streamed fruits look "missed".
            -- Preload and map the whole embedded atlas before any detector registration starts.
            -- This makes a spawn a pure name -> cached sprite lookup with no icon wait.
            pcall(Runtime.BloxFruitDetector.RefreshCatalog,true)
            pcall(Runtime.BloxFruitDetector.PrimeExactIcons)
            task.defer(function()
                if Unloaded then return end
                for _,Fruit in ipairs(Runtime.BloxFruitDetector.ScanAll()) do Runtime.BloxFruitDetector.Register(Fruit) end
                Runtime.BloxFruitDetectorReady=true
            end)
            function Runtime.BloxFruitDetector.CandidateAnchor(Obj)
                local Current=Obj
                for _=1,8 do
                    if not Current or Current==workspace then break end
                    if Current:IsA("Tool") and Current:IsDescendantOf(workspace) then return Current end
                    if Current:IsA("Model") and Current:IsDescendantOf(workspace)
                        and (Current:GetAttribute("OriginalName")~=nil or Current:GetAttribute("FruitName")~=nil) then
                        return Current
                    end
                    Current=Current.Parent
                end
                if Obj and (Obj.Name=="EatRemote" or Obj.Name=="OriginalName" or Obj.Name=="FruitName" or Obj.Name=="Handle") then return Obj.Parent end
                return nil
            end
            function Runtime.BloxFruitDetector.QueueCandidate(Obj)
                local Candidate=Runtime.BloxFruitDetector.CandidateAnchor(Obj)
                if not Candidate or Runtime.BloxFruitDetectorPending[Candidate] or Runtime.BloxFruitDetectorLive[Candidate] then return end
                Runtime.BloxFruitDetectorPending[Candidate]=true
                task.spawn(function()
                    for _,Delay in ipairs({0,0.03,0.10,0.25,0.60,1.20}) do
                        if Delay>0 then task.wait(Delay) end
                        if Unloaded or not Candidate.Parent then break end
                        local Fruit=Runtime.BloxFruitDetector.Resolve(Candidate)
                        if Fruit then Runtime.BloxFruitDetector.Register(Fruit); break end
                    end
                    Runtime.BloxFruitDetectorPending[Candidate]=nil
                end)
            end
            Runtime.BloxFruitDetectorLastWorldEvent=os.clock()
            TrackConnection(workspace.DescendantAdded:Connect(function(Obj)
                Runtime.BloxFruitDetectorLastWorldEvent=os.clock()
                Runtime.BloxFruitDetector.QueueCandidate(Obj)
            end))
            TrackConnection(workspace.DescendantRemoving:Connect(function(Obj)
                -- Mark the world as changed so the rare reconciliation pass can clean stale roots.
                if Obj and (Obj:IsA("Tool") or Obj:IsA("Model") or Obj.Name=="EatRemote") then
                    Runtime.BloxFruitDetectorLastWorldEvent=os.clock()
                end
            end))
            -- DescendantAdded handles normal/streamed fruit spawns immediately. Full workspace scans
            -- are intentionally rare because GetDescendants() is one of the most expensive detector paths.
            task.spawn(function()
                while not Unloaded do
                    local FPS=tonumber(LiveTelemetry and LiveTelemetry.FPS) or 60
                    local Interval=(FPS>0 and FPS<35) and 45 or 30
                    task.wait(Interval)
                    if Unloaded then break end
                    for Fruit in pairs(Runtime.BloxFruitDetectorLive) do
                        if Runtime.BloxFruitDetector.Resolve(Fruit)~=Fruit then Runtime.BloxFruitDetectorLive[Fruit]=nil end
                    end
                    -- Let a burst of streaming/reparent events settle before doing the safety scan.
                    if os.clock()-(tonumber(Runtime.BloxFruitDetectorLastWorldEvent) or 0)<0.75 then task.wait(0.85) end
                    if Unloaded then break end
                    pcall(Runtime.BloxFruitDetector.RefreshCatalog,false)
                    for _,Fruit in ipairs(Runtime.BloxFruitDetector.ScanAll()) do Runtime.BloxFruitDetector.Register(Fruit) end
                    Runtime.BloxFruitDetectorReady=true
                end
            end)

            local function StoreHeldFruits()
                local Stored=0
                for _,Container in ipairs({Player:FindFirstChildOfClass("Backpack"),Character()}) do
                    if Container then
                        for _,Tool in ipairs(Container:GetChildren()) do
                            if Tool:IsA("Tool") and (Tool:FindFirstChild("EatRemote") or string.find(string.lower(Tool.Name),"fruit",1,true)) then
                                local H=Humanoid(); if H and Tool.Parent~=Character() then pcall(function() H:EquipTool(Tool) end); task.wait(0.05) end
                                local Original=Tool:GetAttribute("OriginalName") or Tool.Name:gsub(" Fruit$","")
                                local Ok=QueryRemote(BloxCommF(),"StoreFruit",Original,Tool)
                                if Ok then Stored+=1 end
                            end
                        end
                    end
                end
                return Stored
            end
            local function BloxChests()
                local Out={}
                local ChestModels=workspace:FindFirstChild("ChestModels")
                if ChestModels then for _,Obj in ipairs(ChestModels:GetChildren()) do if GetRoot(Obj) then table.insert(Out,Obj) end end end
                for _,Obj in ipairs(workspace:GetChildren()) do
                    if (Obj.Name=="Chest1" or Obj.Name=="Chest2" or Obj.Name=="Chest3" or string.find(string.lower(Obj.Name),"chest",1,true)) and GetRoot(Obj) then table.insert(Out,Obj) end
                end
                return Out
            end
            local function NearestChest()
                local Me=Root(); if not Me then return nil end
                local Best,Dist=nil,math.huge
                for _,Chest in ipairs(BloxChests()) do
                    local R=GetRoot(Chest)
                    if R and not State.BloxVisitedChests[Chest] then
                        local D=(Me.Position-R.Position).Magnitude
                        if D<Dist then Best,Dist=Chest,D end
                    end
                end
                return Best
            end
            State.BloxVisitedChests=State.BloxVisitedChests or setmetatable({}, {__mode="k"})
            Runtime.BloxRaidFruitPrice=function(FruitName)
                local Want=Runtime.BloxFruitDetector.VisualKey(FruitName)
                local Ok,Fruits=Runtime.BloxReadDealer()
                if not Ok or type(Fruits)~="table" then return nil end
                for Key,Info in pairs(Fruits) do
                    local Raw,Price
                    if type(Info)=="table" then
                        Raw=Info.Name or Info.FruitName or Info.DisplayName or (type(Key)=="string" and Key)
                        for _,K in ipairs({"Price","Money","Cost","Value","Beli","BeliPrice"}) do
                            Price=tonumber(Info[K])
                            if Price and Price>0 then break end
                        end
                    elseif type(Key)=="string" then
                        Raw=Key
                    end
                    local Compact=Runtime.BloxFruitDetector.VisualKey(Raw)
                    if Raw and Compact==Want then return Price end
                end
                return nil
            end
            local function RaidFruitKey(Name)
                return Runtime.BloxFruitDetector.VisualKey(Name)
            end
            local function RaidFruitDisplay(Name)
                local Raw=tostring(Name or ""):gsub(" Fruit$","")
                local Left,Right=Raw:match("^([^%-]+)%-(.-)$")
                if Left and Right and RaidFruitKey(Left)==RaidFruitKey(Right) then Raw=Left end
                return Raw~="" and Raw or tostring(Name or "Unknown Fruit")
            end
            Runtime.BloxRaidFruitOptionMap=Runtime.BloxRaidFruitOptionMap or {}
            Runtime.BloxRaidFruitAvailability=Runtime.BloxRaidFruitAvailability or {}
            Runtime.BloxTreasuryFruitSnapshot=Runtime.BloxTreasuryFruitSnapshot or {}

            local function RaidFruitPriceFromEntry(Entry,FallbackName)
                if type(Entry)=="table" then
                    for _,Field in ipairs({"Price","price","Value","value","Money","money","Cost","cost","Beli","BeliPrice"}) do
                        local V=tonumber(Entry[Field])
                        if V and V>0 then return V end
                    end
                end
                return Runtime.BloxRaidFruitPrice(FallbackName)
            end

            local function RaidPhysicalFruitTools()
                local Out={}
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Tool in ipairs(Container:GetChildren()) do
                            if Tool:IsA("Tool") and (Tool:FindFirstChild("EatRemote") or string.find(string.lower(Tool.Name),"fruit",1,true)) then
                                table.insert(Out,Tool)
                            end
                        end
                    end
                end
                return Out
            end

            local function RaidPhysicalFruitSnapshot()
                local Seen={}
                for _,Tool in ipairs(RaidPhysicalFruitTools()) do Seen[Tool]=true end
                return Seen
            end

            local function NewPhysicalFruitSince(Before,PreferredName)
                local PreferredKey=RaidFruitKey(PreferredName)
                local Fallback
                for _,Tool in ipairs(RaidPhysicalFruitTools()) do
                    if not Before[Tool] then
                        local Raw=Tool:GetAttribute("OriginalName") or Tool.Name
                        if RaidFruitKey(Raw)==PreferredKey then return Tool end
                        Fallback=Fallback or Tool
                    end
                end
                return Fallback
            end

            Runtime.BloxScanRaidFruits=function()
                local Records,Order={},{}
                local function Touch(Name,Source,Count,Tool,Price,ExactLoadName)
                    local Display=RaidFruitDisplay(Name)
                    local Key=RaidFruitKey(Display)
                    if Key=="" then return end
                    local R=Records[Key]
                    if not R then
                        R={Name=Display,Backpack=0,Stored=0,Tools={},Price=tonumber(Price) or Runtime.BloxRaidFruitPrice(Display),LoadName=nil,StoredEntries={}}
                        Records[Key]=R
                        table.insert(Order,R)
                    elseif (not R.Price or R.Price<=0) and tonumber(Price) then
                        R.Price=tonumber(Price)
                    end
                    if Source=="Backpack" then
                        R.Backpack+=math.max(1,tonumber(Count) or 1)
                        if Tool then table.insert(R.Tools,Tool) end
                    elseif Source=="Stored" then
                        local N=math.max(1,tonumber(Count) or 1)
                        R.Stored+=N
                        R.LoadName=R.LoadName or tostring(ExactLoadName or Name)
                        table.insert(R.StoredEntries,{Name=tostring(ExactLoadName or Name),Count=N,Price=tonumber(Price)})
                    end
                end

                -- Scan both physical Backpack/equipped fruits and stored Treasury fruits for the two independent raid selectors.
                for _,Tool in ipairs(RaidPhysicalFruitTools()) do
                    Touch(Tool:GetAttribute("OriginalName") or Tool.Name,"Backpack",1,Tool,nil,nil)
                end

                local Ok,Inventory=Runtime.BloxStoredFruitInventory(0.35)
                Runtime.BloxRaidTreasuryReadOK=Ok and type(Inventory)=="table"
                Runtime.BloxTreasuryFruitSnapshot={At=os.clock(),Ok=Runtime.BloxRaidTreasuryReadOK,Raw=Inventory}

                if Ok and type(Inventory)=="table" then
                    local Visited=setmetatable({}, {__mode="k"})
                    local function Visit(Node,Depth,KeyHint)
                        if Depth>8 or type(Node)~="table" or Visited[Node] then return end
                        Visited[Node]=true

                        -- Verified getInventoryFruits responses are normally an array of records with Name + Price.
                        -- Parse a record directly before considering nested compatibility shapes.
                        local DirectName=Node.Name or Node.ItemName or Node.FruitName or Node.name
                        local DirectType=string.lower(tostring(Node.Type or Node.type or Node.Category or Node.category or ""))
                        local DirectPrice=RaidFruitPriceFromEntry(Node,DirectName)
                        local LooksDirectFruit=DirectName and (
                            string.find(DirectType,"fruit",1,true)
                            or DirectPrice~=nil
                            or string.find(string.lower(tostring(DirectName)),"fruit",1,true)
                        )
                        if LooksDirectFruit then
                            local Count=tonumber(Node.Count or Node.Amount or Node.Quantity or Node.count or Node.amount or Node.quantity) or 1
                            Touch(DirectName,"Stored",Count,nil,DirectPrice,DirectName)
                            return
                        end

                        for Key,Entry in pairs(Node) do
                            if type(Entry)=="table" then
                                local Name=Entry.Name or Entry.ItemName or Entry.FruitName or Entry.name
                                local Type=string.lower(tostring(Entry.Type or Entry.type or Entry.Category or Entry.category or ""))
                                local Price=RaidFruitPriceFromEntry(Entry,Name or (type(Key)=="string" and Key or nil))
                                local LooksFruit=Name and (
                                    string.find(Type,"fruit",1,true)
                                    or Price~=nil
                                    or string.find(string.lower(tostring(Name)),"fruit",1,true)
                                )
                                if LooksFruit then
                                    local Count=tonumber(Entry.Count or Entry.Amount or Entry.Quantity or Entry.count or Entry.amount or Entry.quantity) or 1
                                    Touch(Name,"Stored",Count,nil,Price,Name)
                                else
                                    Visit(Entry,Depth+1,Key)
                                end
                            elseif type(Entry)=="string" and type(Key)=="number" then
                                local Price=Runtime.BloxRaidFruitPrice(Entry)
                                if Price then Touch(Entry,"Stored",1,nil,Price,Entry) end
                            elseif type(Key)=="string" and type(Entry)=="number" and Entry>0 then
                                local Price=Runtime.BloxRaidFruitPrice(Key)
                                if Price then Touch(Key,"Stored",Entry,nil,Price,Key) end
                            end
                        end
                    end
                    Visit(Inventory,1,nil)
                end

                table.sort(Order,function(A,B)
                    if (A.Stored>0)~=(B.Stored>0) then return A.Stored>0 end
                    local AP=A.Price or math.huge; local BP=B.Price or math.huge
                    if AP~=BP then return AP<BP end
                    return string.lower(A.Name)<string.lower(B.Name)
                end)
                Runtime.BloxRaidFruitAvailability=Records
                return Records,Order
            end

            Runtime.BloxRaidBackpackFruitOptions=function()
                local _,Order=Runtime.BloxScanRaidFruits()
                local Options={}
                Runtime.BloxRaidBackpackFruitOptionMap={}
                Runtime.BloxRaidBackpackFruitCanonicalToOption={}
                for _,R in ipairs(Order) do
                    if (R.Backpack or 0)>0 then
                        local PriceText=R.Price and ("$"..tostring(math.floor(R.Price))) or "price ?"
                        local Label=R.Name.." Fruit  •  Backpack ×"..tostring(R.Backpack or 0).."  •  "..PriceText
                        table.insert(Options,Label)
                        Runtime.BloxRaidBackpackFruitOptionMap[Label]=R.Name
                        Runtime.BloxRaidBackpackFruitCanonicalToOption[RaidFruitKey(R.Name)]=Label
                    end
                end
                return Options
            end

            Runtime.BloxRaidTreasuryFruitOptions=function()
                local _,Order=Runtime.BloxScanRaidFruits()
                local Options={}
                Runtime.BloxRaidTreasuryFruitOptionMap={}
                Runtime.BloxRaidTreasuryFruitCanonicalToOption={}
                for _,R in ipairs(Order) do
                    if (R.Stored or 0)>0 then
                        local PriceText=R.Price and ("$"..tostring(math.floor(R.Price))) or "price ?"
                        local Label=R.Name.." Fruit  •  Treasury ×"..tostring(R.Stored or 0).."  •  "..PriceText
                        table.insert(Options,Label)
                        Runtime.BloxRaidTreasuryFruitOptionMap[Label]=R.Name
                        Runtime.BloxRaidTreasuryFruitCanonicalToOption[RaidFruitKey(R.Name)]=Label
                    end
                end
                return Options
            end

            -- Compatibility: older internal calls that ask for the generic raid fruit list get Treasury.
            Runtime.BloxRaidFruitOptions=Runtime.BloxRaidTreasuryFruitOptions

            Runtime.BloxRaidBackpackFruitSelectionLabels=function()
                Runtime.BloxRaidBackpackFruitOptions()
                local Out={}
                for _,Name in ipairs(State.BloxRaidBackpackFruits or {}) do
                    local Label=Runtime.BloxRaidBackpackFruitCanonicalToOption[RaidFruitKey(Name)]
                    if Label then table.insert(Out,Label) end
                end
                return Out
            end

            Runtime.BloxRaidTreasuryFruitSelectionLabels=function()
                Runtime.BloxRaidTreasuryFruitOptions()
                local Out={}
                for _,Name in ipairs(State.BloxRaidTreasuryFruits or {}) do
                    local Label=Runtime.BloxRaidTreasuryFruitCanonicalToOption[RaidFruitKey(Name)]
                    if Label then table.insert(Out,Label) end
                end
                return Out
            end
            Runtime.BloxRaidFruitSelectionLabels=Runtime.BloxRaidTreasuryFruitSelectionLabels

            Runtime.BloxRaidBackpackSummary=function()
                local _,Order=Runtime.BloxScanRaidFruits()
                local Lines={"Physical fruits currently in Backpack / equipped:"}
                local Count=0
                for _,R in ipairs(Order) do
                    if R.Backpack>0 then
                        Count+=1
                        if Count<=12 then
                            local PriceText=R.Price and ("$"..tostring(math.floor(R.Price))) or "price ?"
                            table.insert(Lines,"• "..R.Name.." Fruit ×"..tostring(R.Backpack).."  •  "..PriceText)
                        end
                    end
                end
                if Count==0 then return "No physical fruits are currently in your Backpack / equipped slot." end
                if Count>12 then table.insert(Lines,"• +"..tostring(Count-12).." more in the Backpack selector") end
                return table.concat(Lines,"\n")
            end

            Runtime.BloxRaidTreasurySummary=function()
                local _,Order=Runtime.BloxScanRaidFruits()
                if not Runtime.BloxRaidTreasuryReadOK then
                    return "Treasury fruit data is unavailable. BananiHub could not read getInventoryFruits yet."
                end
                local Lines={"Stored fruits detected by Blox Fruits inventory:"}
                local Count=0
                for _,R in ipairs(Order) do
                    if R.Stored>0 then
                        Count+=1
                        if Count<=14 then
                            local PriceText=R.Price and ("$"..tostring(math.floor(R.Price))) or "price ?"
                            table.insert(Lines,"• "..R.Name.." Fruit ×"..tostring(R.Stored).."  •  "..PriceText)
                        end
                    end
                end
                if Count==0 then return "No stored fruits were returned by getInventoryFruits." end
                if Count>14 then table.insert(Lines,"• +"..tostring(Count-14).." more in the Treasury selector") end
                return table.concat(Lines,"\n")
            end

            Runtime.BloxRaidFruitSummary=function()
                local Records=Runtime.BloxRaidFruitAvailability
                if type(Records)~="table" or not next(Records) then Records=select(1,Runtime.BloxScanRaidFruits()) end
                local BP=State.BloxRaidBackpackFruits or {}
                local TR=State.BloxRaidTreasuryFruits or {}
                if #BP==0 and #TR==0 then
                    return "Backpack selected: None\nTreasury selected: None\nPick fruits from either selector. Backpack is used first."
                end
                local Lines={}
                table.insert(Lines,"Backpack selected (used first):")
                if #BP==0 then
                    table.insert(Lines,"• None")
                else
                    for I,Name in ipairs(BP) do
                        local R=Records[RaidFruitKey(Name)]
                        local Count=R and (R.Backpack or 0) or 0
                        local Price=R and R.Price or Runtime.BloxRaidFruitPrice(Name)
                        local PriceText=Price and ("$"..tostring(math.floor(Price))) or "price ?"
                        table.insert(Lines,tostring(I)..". "..RaidFruitDisplay(Name).."  •  Backpack ×"..tostring(Count).."  •  "..PriceText)
                    end
                end
                table.insert(Lines,"Treasury selected (used after Backpack):")
                if #TR==0 then
                    table.insert(Lines,"• None")
                else
                    for I,Name in ipairs(TR) do
                        local R=Records[RaidFruitKey(Name)]
                        local Count=R and (R.Stored or 0) or 0
                        local Price=R and R.Price or Runtime.BloxRaidFruitPrice(Name)
                        local PriceText=Price and ("$"..tostring(math.floor(Price))) or "price ?"
                        table.insert(Lines,tostring(I)..". "..RaidFruitDisplay(Name).."  •  Treasury ×"..tostring(Count).."  •  "..PriceText)
                    end
                end
                return table.concat(Lines,"\n")
            end

            local function FindPhysicalRaidFruit(Name)
                local Want=RaidFruitKey(Name)
                for _,Tool in ipairs(RaidPhysicalFruitTools()) do
                    local Raw=Tool:GetAttribute("OriginalName") or Tool.Name
                    if RaidFruitKey(Raw)==Want then return Tool,RaidFruitDisplay(Raw) end
                end
                return nil,nil
            end

            local function SelectedRaidFruitChoice(MinimumPrice)
                MinimumPrice=tonumber(MinimumPrice) or 0
                Runtime.BloxStoredFruitInventoryCache=nil
                Runtime.BloxScanRaidFruits()
                local AnySelected=false
                local AnyAvailable=false

                -- Backpack always has priority so a stored fruit is never withdrawn while a selected
                -- physical fruit can already pay for the chip.
                for _,Name in ipairs(State.BloxRaidBackpackFruits or {}) do
                    AnySelected=true
                    local R=Runtime.BloxRaidFruitAvailability[RaidFruitKey(Name)]
                    local Price=(R and R.Price) or Runtime.BloxRaidFruitPrice(Name)
                    local Available=R and (R.Backpack or 0)>0
                    if Available then AnyAvailable=true end
                    if Available and ((MinimumPrice<=0) or (Price and Price>=MinimumPrice)) then
                        return {Name=R.Name,Price=tonumber(Price) or 0,Record=R,Source="Backpack"},"READY"
                    end
                end

                for _,Name in ipairs(State.BloxRaidTreasuryFruits or {}) do
                    AnySelected=true
                    local R=Runtime.BloxRaidFruitAvailability[RaidFruitKey(Name)]
                    local Price=(R and R.Price) or Runtime.BloxRaidFruitPrice(Name)
                    local Available=R and (R.Stored or 0)>0
                    if Available then AnyAvailable=true end
                    if Available and ((MinimumPrice<=0) or (Price and Price>=MinimumPrice)) then
                        return {Name=R.Name,Price=tonumber(Price) or 0,Record=R,Source="Treasury"},"READY"
                    end
                end

                if not AnySelected then return nil,"RAID_FRUIT_SELECTION_EMPTY" end
                return nil,(AnyAvailable and "RAID_SELECTED_FRUITS_INELIGIBLE" or "RAID_SELECTED_FRUITS_EMPTY")
            end

            local function PrepareSelectedRaidFruit(MinimumPrice)
                local Choice,ChoiceReason=SelectedRaidFruitChoice(MinimumPrice)
                if not Choice then return nil,ChoiceReason end

                if Choice.Source=="Backpack" then
                    local Tool=FindPhysicalRaidFruit(Choice.Name)
                    if not Tool then
                        Runtime.BloxScanRaidFruits()
                        return nil,"RAID_SELECTED_BACKPACK_FRUIT_MISSING"
                    end
                    Choice.Tool=Tool
                    Runtime.BloxRaidStatus="Using Backpack fruit • "..Choice.Name
                    return Choice,"READY"
                end

                if not Choice.Record or (Choice.Record.Stored or 0)<=0 then return nil,"RAID_SELECTED_TREASURY_FRUIT_MISSING" end
                local LoadName=Choice.Record.LoadName or Choice.Name
                local BeforeStored=Choice.Record.Stored or 0
                local BeforeTools=RaidPhysicalFruitSnapshot()
                Runtime.BloxRaidStatus="Withdrawing from Treasury • "..Choice.Name
                if Runtime.BloxRaidStatusParagraph and Runtime.BloxRaidStatusParagraph.Set then
                    pcall(function() Runtime.BloxRaidStatusParagraph:Set({Title="Raid Status",Content=Runtime.BloxRaidStatus}) end)
                end

                local Sent,Result=QueryRemote(BloxCommF(),"LoadFruit",LoadName)
                if not Sent then return nil,"RAID_TREASURY_WITHDRAW_FAILED" end

                Runtime.BloxStoredFruitInventoryCache=nil
                local Tool=nil
                local WithdrawConfirmed=false
                local Deadline=os.clock()+3.25
                repeat
                    Runtime.Movement.Guard()
                    Tool=NewPhysicalFruitSince(BeforeTools,Choice.Name) or FindPhysicalRaidFruit(Choice.Name)
                    Runtime.BloxStoredFruitInventoryCache=nil
                    local Records=select(1,Runtime.BloxScanRaidFruits())
                    local After=Records[RaidFruitKey(Choice.Name)]
                    local AfterStored=After and (After.Stored or 0) or 0
                    if AfterStored<BeforeStored or (Tool and not BeforeTools[Tool]) then
                        WithdrawConfirmed=true
                        break
                    end
                    task.wait(0.12)
                until os.clock()>=Deadline

                if not WithdrawConfirmed then return nil,"RAID_TREASURY_WITHDRAW_NOT_CONFIRMED" end
                if not Tool then
                    local ToolDeadline=os.clock()+1.25
                    repeat
                        Tool=NewPhysicalFruitSince(BeforeTools,Choice.Name) or FindPhysicalRaidFruit(Choice.Name)
                        if Tool then break end
                        task.wait(0.08)
                    until os.clock()>=ToolDeadline
                end
                if not Tool then return nil,"RAID_WITHDRAWN_FRUIT_NOT_FOUND" end

                Choice.Tool=Tool
                Choice.LoadName=LoadName
                Choice.WithdrawResult=Result
                Choice.StoredBefore=BeforeStored
                Runtime.BloxStoredFruitInventoryCache=nil
                return Choice,"READY"
            end
            local function RaidIsland()
                local WO=workspace:FindFirstChild("_WorldOrigin")
                local Locations=WO and WO:FindFirstChild("Locations")
                if not Locations then return nil end
                for I=5,1,-1 do
                    local Obj=Locations:FindFirstChild("Island "..I)
                    if Obj then return Obj end
                end
                return nil
            end
            Runtime.BloxRaidArrivalProbe=function(Position)
                if typeof(Position)~="Vector3" then return false,nil,math.huge end
                local WO=workspace:FindFirstChild("_WorldOrigin")
                local Locations=WO and WO:FindFirstChild("Locations")
                if not Locations then return false,nil,math.huge end
                local BestName,BestDistance=nil,math.huge
                for I=1,5 do
                    local Obj=Locations:FindFirstChild("Island "..I)
                    local R=Obj and (Obj:IsA("BasePart") and Obj or GetRoot(Obj)) or nil
                    if R and R.Parent then
                        local Delta=Position-R.Position
                        local Horizontal=Vector2.new(Delta.X,Delta.Z).Magnitude
                        local Vertical=math.abs(Delta.Y)
                        -- Raid island markers sit near the center of each active island. Requiring
                        -- both horizontal and vertical proximity prevents a large unrelated teleport
                        -- elsewhere in the sea from arming the farming timer.
                        local Distance=Delta.Magnitude
                        if Distance<BestDistance then BestDistance,BestName=Distance,"Island "..I end
                        if Horizontal<=420 and Vertical<=260 then
                            return true,"Island "..I,Distance
                        end
                    end
                end
                return false,BestName,BestDistance
            end
            Runtime.BloxRaidStatus=Runtime.BloxRaidStatus or "Idle"
            local function SetRaidStatus(Text)
                Text=tostring(Text or "Idle")
                if Runtime.BloxRaidStatus==Text then return end
                Runtime.BloxRaidStatus=Text
                if Runtime.BloxRaidStatusParagraph and Runtime.BloxRaidStatusParagraph.Set then
                    pcall(function() Runtime.BloxRaidStatusParagraph:Set({Title="Raid Status",Content=Runtime.BloxRaidStatus}) end)
                end
            end
            local function RaidSummonModel()
                local Cached=Runtime.BloxRaidSummonCache
                if Cached and Cached.Parent then return Cached end
                if os.clock()-(Runtime.BloxRaidSummonLastScan or -math.huge)<2 then return nil end
                Runtime.BloxRaidSummonLastScan=os.clock()
                local Map=workspace:FindFirstChild("Map")
                if not Map then return nil end
                if game.PlaceId==4442272183 then
                    local Circle=Map:FindFirstChild("CircleIsland")
                    if Circle and Circle:FindFirstChild("RaidSummon2") then Runtime.BloxRaidSummonCache=Circle.RaidSummon2; return Circle.RaidSummon2 end
                elseif game.PlaceId==7449423635 then
                    local Castle=Map:FindFirstChild("Boat Castle") or Map:FindFirstChild("Castle on the Sea")
                    if Castle and Castle:FindFirstChild("RaidSummon2") then Runtime.BloxRaidSummonCache=Castle.RaidSummon2; return Castle.RaidSummon2 end
                end
                for _,Obj in ipairs(Map:GetDescendants()) do
                    if Obj.Name=="RaidSummon2" then Runtime.BloxRaidSummonCache=Obj; return Obj end
                end
                return nil
            end
            local function RaidPodPart(Summon)
                if not Summon then return nil end
                local Cached=Runtime.BloxRaidPodCache
                if Cached and Cached.Parent then return Cached end
                local Me=Root(); local Best,BestScore=nil,math.huge
                local SummonRoot=GetRoot(Summon)
                -- Raid tubes can be siblings of RaidSummon2 in the island model.
                for _,Obj in ipairs((Summon.Parent or Summon):GetDescendants()) do
                    if Obj:IsA("BasePart") then
                        local Lower=string.lower(Obj.Name)
                        local IsButton=string.find(Lower,"button",1,true)
                        if not IsButton then
                            local Score=100
                            if string.find(Lower,"tube",1,true) then Score=0
                            elseif string.find(Lower,"pod",1,true) then Score=10
                            elseif string.find(Lower,"capsule",1,true) then Score=15
                            elseif string.find(Lower,"platform",1,true) then Score=20
                            elseif string.find(Lower,"pad",1,true) then Score=30 end
                            if Score<100 then
                                local FromSummon=SummonRoot and (Obj.Position-SummonRoot.Position).Magnitude or 0
                                if FromSummon>150 then continue end
                                if game.PlaceId==4442272183 then
                                    local C=Obj.Color
                                    if C.B>C.R and C.B>=C.G then Score-=6 end
                                elseif game.PlaceId==7449423635 then
                                    local C=Obj.Color
                                    if C.R>0.55 and C.G>0.45 and C.B<0.45 then Score-=6 end
                                end
                                local D=Me and (Obj.Position-Me.Position).Magnitude or 0
                                Score+=FromSummon*0.03+math.min(D/500,8)
                                if Score<BestScore then Best,BestScore=Obj,Score end
                            end
                        end
                    end
                end
                Runtime.BloxRaidPodCache=Best or GetRoot(Summon)
                return Runtime.BloxRaidPodCache
            end
            local function RaidStartClick(Summon)
                if not Summon or type(fireclickdetector)~="function" then return false end
                local Exact=Summon:FindFirstChild("ClickDetector",true)
                if Exact then
                    local Button=Exact:FindFirstAncestor("Button")
                    if Button or string.find(string.lower(Exact:GetFullName()),"button",1,true) then
                        local Ok=pcall(function() fireclickdetector(Exact) end)
                        if Ok then return true end
                    end
                end
                for _,Obj in ipairs(Summon:GetDescendants()) do
                    if Obj:IsA("ClickDetector") then
                        local Ok=pcall(function() fireclickdetector(Obj) end)
                        if Ok then return true end
                    end
                end
                return false
            end
            local function BuyRaidChipWithSelectedFruit()
                if Runtime.BloxFns.HasRaidChip() then return true,"CHIP_READY" end
                if os.clock()-(Runtime.BloxRaidChipRequestAt or -math.huge)<4 then
                    SetRaidStatus("Waiting for raid chip confirmation")
                    return false,"RAID_CHIP_SETTLING"
                end
                local BackpackSelected=State.BloxRaidBackpackFruits or {}
                local TreasurySelected=State.BloxRaidTreasuryFruits or {}
                if #BackpackSelected==0 and #TreasurySelected==0 then
                    SetRaidStatus("Select at least one Backpack or Treasury fruit first")
                    return false,"RAID_FRUIT_SELECTION_EMPTY"
                end
                local Advanced=(State.BloxRaidChip=="Phoenix" or State.BloxRaidChip=="Dough")
                local MinPrice=Advanced and 1000001 or 0
                local Choice,Reason=PrepareSelectedRaidFruit(MinPrice)
                if not Choice then
                    Runtime.BloxScanRaidFruits()
                    if Runtime.BloxRaidFruitStatusParagraph and Runtime.BloxRaidFruitStatusParagraph.Set then
                        pcall(function() Runtime.BloxRaidFruitStatusParagraph:Set({Title="Raid Fruit Pool",Content=Runtime.BloxRaidFruitSummary()}) end)
                    end
                    if Reason=="RAID_SELECTED_FRUITS_EMPTY" then
                        SetRaidStatus("Selected Backpack + Treasury fruits ran out • Raid stopped")
                    elseif Reason=="RAID_SELECTED_FRUITS_INELIGIBLE" then
                        SetRaidStatus("Selected fruits are available, but none meets this raid's fruit value requirement • Raid stopped")
                    elseif Reason=="RAID_SELECTED_BACKPACK_FRUIT_MISSING" then
                        SetRaidStatus("Selected Backpack fruit disappeared before chip purchase • Raid stopped")
                    elseif Advanced then
                        SetRaidStatus("No selected available fruit meets the advanced raid value requirement • Raid stopped")
                    else
                        SetRaidStatus("Selected raid fruit could not be prepared • Raid stopped")
                    end
                    return false,Reason
                end
                SetRaidStatus("Using "..tostring(Choice.Source or "selected").." fruit • "..Choice.Name.." ($"..tostring(math.floor(Choice.Price or 0))..")")
                local H=Humanoid()
                if H and Choice.Tool and Choice.Tool.Parent~=Character() then pcall(function() H:EquipTool(Choice.Tool) end) end
                task.wait(0.20)
                Runtime.BloxRaidChipRequestAt=os.clock()
                local Sent=select(1,QueryRemote(BloxCommF(),"RaidsNpc","Select",State.BloxRaidChip))
                if not Sent then return false,"RAID_CHIP_REQUEST_FAILED" end
                local Deadline=os.clock()+2.5
                repeat
                    Runtime.Movement.Guard()
                    if Runtime.BloxFns.HasRaidChip() then
                        Runtime.BloxScanRaidFruits()
                        if Runtime.BloxRaidFruitStatusParagraph and Runtime.BloxRaidFruitStatusParagraph.Set then
                            pcall(function() Runtime.BloxRaidFruitStatusParagraph:Set({Title="Raid Fruit Pool",Content=Runtime.BloxRaidFruitSummary()}) end)
                        end
                        SetRaidStatus(State.BloxRaidChip.." chip confirmed • "..Choice.Name.." from "..tostring(Choice.Source or "selection").." consumed/used • entering raid pod")
                        return true,"CHIP_CONFIRMED"
                    end
                    task.wait(0.10)
                until os.clock()>=Deadline
                SetRaidStatus("Chip purchase pending confirmation")
                return false,"RAID_CHIP_NOT_CONFIRMED"
            end
            local function StartRaidOnce()
                if RaidIsland() then return true end
                local ChipOK=Runtime.BloxFns.HasRaidChip()~=nil
                if not ChipOK then ChipOK=select(1,BuyRaidChipWithSelectedFruit()) end
                if not ChipOK then return false end
                local Summon=RaidSummonModel()
                if not Summon and os.clock()-(Runtime.BloxRaidAreaTravelAt or -math.huge)>8 then
                    Runtime.BloxRaidAreaTravelAt=os.clock()
                    local AreaName=(game.PlaceId==4442272183 and "Hot and Cold")
                        or (game.PlaceId==7449423635 and "Castle on the Sea")
                    if AreaName then
                        SetRaidStatus("Locating raid maker area • "..AreaName)
                        if BloxTeleportLocation(AreaName) then
                            Runtime.BloxRaidSummonLastScan=0
                            Summon=RaidSummonModel()
                        end
                    end
                end
                if not Summon then SetRaidStatus("RAID_AREA_MISSING"); return false end
                local SummonRoot=GetRoot(Summon)
                if SummonRoot then
                    SetRaidStatus("Traveling to raid maker area • "..State.BloxRaidChip)
                    ProfileTravelToCFrame(CFrame.new(SummonRoot.Position+Vector3.new(0,3,0)),function()
                        local S=RaidSummonModel(); local R=S and GetRoot(S)
                        return R and CFrame.new(R.Position+Vector3.new(0,3,0)) or nil
                    end)
                end
                Summon=RaidSummonModel()
                local Pod=RaidPodPart(Summon)
                if not Pod then SetRaidStatus("RAID_TUBE_MISSING"); return false end
                SetRaidStatus("Entering raid tube / platform • "..State.BloxRaidChip)
                local Entered=ProfileTravelToCFrame(Pod.CFrame*CFrame.new(0,2,0),function()
                    local S=RaidSummonModel(); local P=RaidPodPart(S)
                    return P and (P.CFrame*CFrame.new(0,2,0)) or nil
                end)
                local Me=Root()
                if not Entered or not Me or (Me.Position-Pod.Position).Magnitude>14 then
                    SetRaidStatus("RAID_TUBE_ENTRY_FAILED")
                    return false
                end
                task.wait(0.30)
                SetRaidStatus("Starting raid • "..State.BloxRaidChip)
                local PreStartRoot=Root()
                local PreStartPosition=PreStartRoot and PreStartRoot.Position or nil
                local LastPosition=PreStartPosition
                Runtime.BloxRaidTeleportDetectedAt=nil
                Runtime.BloxRaidFarmStartsAt=nil
                Runtime.BloxRaidLockedTarget=nil
                if not RaidStartClick(Summon) then SetRaidStatus("RAID_START_CLICK_FAILED"); return false end

                -- Reliable arrival gate: a big position jump alone is NOT enough. First confirm
                -- that the character left the raid tube/start area, then require the root to remain
                -- physically inside a live raid-island marker radius for a short stable window.
                -- The eight-second farming timer starts only after that stable arrival is confirmed.
                local Deadline=os.clock()+18
                local LeftStart=false
                local SawTeleportJump=false
                local ArrivalCandidateAt=nil
                local ArrivalIsland=nil
                local ArrivalConfirmSeconds=0.40
                repeat
                    Runtime.Movement.Guard()
                    local CurrentRoot=Root()
                    local CurrentPosition=CurrentRoot and CurrentRoot.Position or nil
                    local JumpDistance=(CurrentPosition and LastPosition) and (CurrentPosition-LastPosition).Magnitude or 0
                    local TotalDistance=(CurrentPosition and PreStartPosition) and (CurrentPosition-PreStartPosition).Magnitude or 0
                    local PodDistance=(CurrentPosition and Pod and Pod.Parent) and (CurrentPosition-Pod.Position).Magnitude or 0

                    if CurrentPosition and PreStartPosition then
                        if TotalDistance>=90 or PodDistance>=90 then LeftStart=true end
                        if JumpDistance>=45 or TotalDistance>=120 then SawTeleportJump=true end
                    end

                    local InRaidArea,NearIsland,IslandDistance=Runtime.BloxRaidArrivalProbe(CurrentPosition)
                    local ArrivalEligible=LeftStart and InRaidArea and RaidIsland()~=nil
                    if ArrivalEligible then
                        if ArrivalIsland~=NearIsland then
                            ArrivalIsland=NearIsland
                            ArrivalCandidateAt=os.clock()
                        elseif not ArrivalCandidateAt then
                            ArrivalCandidateAt=os.clock()
                        end
                        local StableFor=os.clock()-(ArrivalCandidateAt or os.clock())
                        SetRaidStatus("Reached "..tostring(NearIsland or "raid area").." • confirming arrival")
                        if StableFor>=ArrivalConfirmSeconds then
                            local ArrivedAt=os.clock()
                            Runtime.BloxRaidTeleportDetectedAt=ArrivedAt
                            Runtime.BloxRaidStartedAt=ArrivedAt
                            Runtime.BloxRaidFarmStartsAt=ArrivedAt+8
                            Runtime.BloxRaidArrivalIsland=NearIsland
                            Runtime.BloxRaidArrivalDistance=IslandDistance
                            Runtime.BloxRaidJustClearedAt=nil
                            Runtime.BloxRaidSawFinalIsland=false
                            Runtime.BloxRaidMissingIslandAt=nil
                            Runtime.BloxRaidCombatActive=false
                            Runtime.BloxWasInSmartRaid=true
                            SetRaidStatus("Raid area confirmed • "..tostring(NearIsland or "island").." • waiting 8 seconds before farming")
                            return true
                        end
                    else
                        ArrivalCandidateAt=nil
                        ArrivalIsland=nil
                        if LeftStart and not InRaidArea then
                            if NearIsland and IslandDistance<math.huge then
                                SetRaidStatus((SawTeleportJump and "Teleport detected" or "Left raid tube").." • locating raid area • "..tostring(math.floor(IslandDistance+0.5)).." studs from "..NearIsland)
                            else
                                SetRaidStatus((SawTeleportJump and "Teleport detected" or "Left raid tube").." • waiting for raid area to stream")
                            end
                        elseif RaidIsland() then
                            SetRaidStatus("Raid loading • waiting to reach raid island")
                        else
                            SetRaidStatus("Starting raid • waiting for raid teleport")
                        end
                    end
                    LastPosition=CurrentPosition or LastPosition
                    task.wait(0.08)
                until os.clock()>=Deadline
                SetRaidStatus("RAID_AREA_ARRIVAL_NOT_CONFIRMED")
                return false
            end
            local function RaidStep()
                local E=Runtime.BloxRaidLockedTarget
                local Enemies=workspace:FindFirstChild("Enemies")
                local H=E and E.Parent and E:FindFirstChildOfClass("Humanoid") or nil
                if not E or not Enemies or not E:IsDescendantOf(Enemies) or not H or H.Health<=0 or IsPlayerCharacter(E) then
                    Runtime.BloxRaidLockedTarget=nil
                    -- Force a fresh lightweight enemy snapshot immediately after a kill/disappear
                    -- so Raid hands off to the next mob without waiting on the normal cache age.
                    if BloxEnemySnapshotState then BloxEnemySnapshotState.At=0 end

                    -- Prefer a live enemy that actually belongs to the current raid island area.
                    -- This avoids wasting time on unrelated streamed world mobs when a raid is active.
                    local Me=Root()
                    local ActiveIsland=RaidIsland()
                    local IslandRoot=ActiveIsland and GetRoot(ActiveIsland) or nil
                    local Best,BestScore=nil,math.huge
                    for _,Candidate in ipairs(BloxLiveEnemies(true)) do
                        local CH=Candidate:FindFirstChildOfClass("Humanoid")
                        local CR=GetRoot(Candidate)
                        if CH and CH.Health>0 and CR and not IsPlayerCharacter(Candidate) then
                            local InRaidArea=true
                            if IslandRoot then InRaidArea=(CR.Position-IslandRoot.Position).Magnitude<=2000
                            elseif Me then InRaidArea=(CR.Position-Me.Position).Magnitude<=2000 end
                            if InRaidArea then
                                local PlayerDistance=Me and (CR.Position-Me.Position).Magnitude or 0
                                local IslandDistance=IslandRoot and (CR.Position-IslandRoot.Position).Magnitude or 0
                                local Score=PlayerDistance+(IslandDistance*0.18)
                                if Score<BestScore then Best,BestScore=Candidate,Score end
                            end
                        end
                    end
                    E=Best
                    Runtime.BloxRaidLockedTarget=E
                end
                if E then
                    SetRaidStatus("Farming raid enemy • "..tostring(E.Name).." • 2000-stud scan • locked target")
                    Runtime.BloxRaidCombatActive=true
                    local OK,Err=pcall(FarmBloxEnemy,E)
                    Runtime.BloxRaidCombatActive=false
                    local EH=E and E.Parent and E:FindFirstChildOfClass("Humanoid") or nil
                    if not E or not E.Parent or not EH or EH.Health<=0 then
                        Runtime.BloxRaidLockedTarget=nil
                        if BloxEnemySnapshotState then BloxEnemySnapshotState.At=0 end
                    end
                    if not OK and tostring(Err):find("BANANI_CANCELLED",1,true) then error(Err,0) end
                    return
                end
                Runtime.BloxRaidCombatActive=false
                Runtime.BloxRaidLockedTarget=nil
                local Island=RaidIsland()
                if Island then
                    SetRaidStatus("No enemy loaded • moving above "..tostring(Island.Name))
                    MoveTo(Island,CFrame.new(0,24,0))
                end
            end
            local function AtRaidAscensionPlace()
                if RaidIsland() then return false end
                if Runtime.BloxRaidSawFinalIsland~=true then return false end
                local StartedAt=tonumber(Runtime.BloxRaidStartedAt)
                if not StartedAt or os.clock()-StartedAt<8 then return false end
                local ClearedAt=tonumber(Runtime.BloxRaidJustClearedAt)
                if not ClearedAt or os.clock()-ClearedAt<0.45 or os.clock()-ClearedAt>18 then return false end
                local Me=Root(); if not Me then return false end
                local Summon=RaidSummonModel()
                local SummonRoot=Summon and GetRoot(Summon)
                if SummonRoot and (Me.Position-SummonRoot.Position).Magnitude<150 then return false end
                local BestDistance=math.huge
                for _,Obj in ipairs(Runtime.ProfileObjects()) do
                    if Obj and Obj.Parent then
                        local Lower=string.lower(tostring(Obj.Name or ""))
                        -- Only post-raid awakening-room entities count. Do not match the normal
                        -- Mysterious Scientist or random objects hundreds of studs away.
                        if Lower=="mysterious entity" or string.find(Lower,"église de prophétie",1,true)
                            or string.find(Lower,"eglise de prophetie",1,true) then
                            local R=GetRoot(Obj)
                            if R then BestDistance=math.min(BestDistance,(R.Position-Me.Position).Magnitude) end
                        end
                    end
                end
                return BestDistance<35
            end
            Runtime.BloxLawStatus=Runtime.BloxLawStatus or "Idle"
            local function SetLawStatus(Text)
                Runtime.BloxLawStatus=tostring(Text or "Idle")
                if Runtime.BloxLawStatusParagraph and Runtime.BloxLawStatusParagraph.Set then
                    pcall(function() Runtime.BloxLawStatusParagraph:Set({Title="Order / Law Status",Content=Runtime.BloxLawStatus}) end)
                end
            end
            local function FindOrderBoss()
                local Folder=workspace:FindFirstChild("Enemies")
                if not Folder then return nil end
                for _,Enemy in ipairs(Folder:GetChildren()) do
                    if Enemy:IsA("Model") then
                        local Name=CompactEnemyName(Enemy.Name)
                        local H=Enemy:FindFirstChildOfClass("Humanoid")
                        if H and H.Health>0 and (Name=="order" or Name=="law") then return Enemy end
                    end
                end
                return nil
            end
            local function OrderWaitingInStorage()
                for _,Obj in ipairs(ReplicatedStorage:GetChildren()) do
                    local Name=CompactEnemyName(Obj.Name)
                    if Name=="order" or Name=="law" then return Obj end
                end
                return nil
            end
            local function HasOrderMicrochip()
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Obj in ipairs(Container:GetChildren()) do
                            if Obj:IsA("Tool") and CompactEnemyName(Obj.Name)=="microchip" then return Obj end
                        end
                    end
                end
                return nil
            end
            local function LawSummonModel()
                local Map=workspace:FindFirstChild("Map")
                if not Map then return nil end
                local Circle=Map:FindFirstChild("CircleIsland")
                if Circle then
                    local Exact=Circle:FindFirstChild("RaidSummon")
                    if Exact then return Exact end
                end
                for _,Obj in ipairs(Map:GetDescendants()) do
                    if Obj.Name=="RaidSummon" and Obj:FindFirstChildWhichIsA("ClickDetector",true) then
                        return Obj
                    end
                end
                return nil
            end
            local function LawPodPart(Summon)
                if not Summon then return nil end
                local Me=Root()
                local Best,BestScore,BestDistance=nil,-math.huge,math.huge
                for _,Obj in ipairs(Summon:GetDescendants()) do
                    if Obj:IsA("BasePart") then
                        local Lower=string.lower(Obj.Name)
                        local Full=string.lower(Obj:GetFullName())
                        local IsButton=string.find(Lower,"button",1,true) or string.find(Full,"button.main",1,true)
                        if not IsButton then
                            local Score=0
                            if string.find(Lower,"tube",1,true) or string.find(Lower,"pod",1,true)
                                or string.find(Lower,"chamber",1,true) or string.find(Lower,"platform",1,true) then Score+=50 end
                            local C=Obj.Color
                            if C.B>C.R*1.12 and C.B>C.G*1.05 then Score+=25 end
                            if Obj.Transparency<0.95 then Score+=5 end
                            if Obj.Size.Magnitude>5 then Score+=4 end
                            local D=Me and (Obj.Position-Me.Position).Magnitude or 0
                            if Score>BestScore or (Score==BestScore and D<BestDistance) then
                                Best,BestScore,BestDistance=Obj,Score,D
                            end
                        end
                    end
                end
                return Best or GetRoot(Summon)
            end
            local function LawStartClick(Summon)
                if not Summon or type(fireclickdetector)~="function" then return false end
                local Preferred=nil
                for _,Obj in ipairs(Summon:GetDescendants()) do
                    if Obj:IsA("ClickDetector") then
                        local Full=string.lower(Obj:GetFullName())
                        if string.find(Full,"button.main",1,true) or string.find(Full,"button",1,true) then Preferred=Obj; break end
                        Preferred=Preferred or Obj
                    end
                end
                return Preferred and pcall(function() fireclickdetector(Preferred) end) or false
            end
            local function BloxLawFragments()
                local Data=Player:FindFirstChild("Data")
                local Value=Data and (Data:FindFirstChild("Fragments") or Data:FindFirstChild("Fragment"))
                return Value and tonumber(Value.Value) or nil
            end
            local function BuyOrderMicrochip()
                if HasOrderMicrochip() then return true,"LAW_CHIP_READY" end
                local Fragments=BloxLawFragments()
                if Fragments and Fragments<1000 then
                    SetLawStatus("Need 1,000 Fragments for Order Microchip • have "..tostring(math.floor(Fragments)))
                    return false,"LAW_FRAGMENTS_LOW"
                end
                SetLawStatus("Buying Order Microchip • 1,000 Fragments")
                -- First request mirrors the NPC dialogue/query path; second request performs the purchase.
                pcall(function() QueryRemote(BloxCommF(),"BlackbeardReward","Microchip","1") end)
                local Sent=select(1,QueryRemote(BloxCommF(),"BlackbeardReward","Microchip","2"))
                if not Sent then return false,"LAW_CHIP_REQUEST_FAILED" end
                local Deadline=os.clock()+3.0
                repeat
                    Runtime.Movement.Guard()
                    if HasOrderMicrochip() then
                        SetLawStatus("Order Microchip confirmed • moving to Secret Laboratory")
                        return true,"LAW_CHIP_CONFIRMED"
                    end
                    task.wait(0.10)
                until os.clock()>=Deadline
                SetLawStatus("LAW_CHIP_NOT_CONFIRMED")
                return false,"LAW_CHIP_NOT_CONFIRMED"
            end
            local function StartOrderRaid()
                if FindOrderBoss() then return true end
                local Chip=HasOrderMicrochip()
                if not Chip then
                    local OK=select(1,BuyOrderMicrochip())
                    if not OK then return false end
                    Chip=HasOrderMicrochip()
                end
                local Summon=LawSummonModel()
                if not Summon then
                    SetLawStatus("LAW_SECRET_LAB_MISSING • go to Hot and Cold / Second Sea")
                    return false
                end
                local Pod=LawPodPart(Summon)
                if Pod then
                    SetLawStatus("Entering Order raid chamber")
                    if not ProfileTravelToCFrame(Pod.CFrame*CFrame.new(0,2,0),function()
                        local S=LawSummonModel(); local P=LawPodPart(S)
                        return P and (P.CFrame*CFrame.new(0,2,0)) or nil
                    end) then return false end
                    task.wait(0.25)
                end
                local H=Humanoid()
                if H then pcall(function() H:UnequipTools() end) end
                local Backpack=Player:FindFirstChildOfClass("Backpack")
                Chip=HasOrderMicrochip()
                if Backpack and Chip and Chip.Parent~=Backpack then pcall(function() Chip.Parent=Backpack end) end
                task.wait(0.12)
                SetLawStatus("Starting Order / Law raid")
                if not LawStartClick(Summon) then
                    SetLawStatus("LAW_START_CLICK_FAILED")
                    return false
                end
                local Deadline=os.clock()+7.5
                repeat
                    Runtime.Movement.Guard()
                    local Boss=FindOrderBoss()
                    if Boss then SetLawStatus("Order spawned • farming boss"); return true end
                    if OrderWaitingInStorage() then SetLawStatus("Order is loading into the laboratory...") end
                    task.wait(0.12)
                until os.clock()>=Deadline
                SetLawStatus("LAW_START_NOT_CONFIRMED")
                return false
            end
            Runtime.BloxLawNextActionAt=Runtime.BloxLawNextActionAt or 0
            Runtime.BloxLawStep=function()
                if game.PlaceId~=4442272183 then
                    SetLawStatus("Order / Law requires Second Sea • Hot and Cold")
                    return
                end
                local Boss=FindOrderBoss()
                if Boss then
                    SetLawStatus("Farming Order • "..tostring(math.floor((Boss:FindFirstChildOfClass("Humanoid") and Boss:FindFirstChildOfClass("Humanoid").Health) or 0)).." HP")
                    FarmBloxEnemy(Boss)
                    if not FindOrderBoss() then SetLawStatus("Order defeated • preparing next Microchip") end
                    return
                end
                if OrderWaitingInStorage() then
                    SetLawStatus("Order raid is loading • waiting for boss")
                    return
                end
                local Now=os.clock()
                if Now<(Runtime.BloxLawNextActionAt or 0) then return end
                Runtime.BloxLawNextActionAt=Now+1.0
                if not HasOrderMicrochip() then
                    local OK=select(1,BuyOrderMicrochip())
                    if not OK then Runtime.BloxLawNextActionAt=os.clock()+1.5; return end
                end
                StartOrderRaid()
                Runtime.BloxLawNextActionAt=os.clock()+1.0
            end

            Runtime.BloxFns.TravelSea = function(Sea)
                local Cmd=Sea=="Sea 1" and "TravelMain" or Sea=="Sea 2" and "TravelDressrosa" or "TravelZou"
                local Ok=QueryRemote(BloxCommF(),Cmd)
                if not Ok then Notify("Blox Fruits","Sea travel request failed or is locked on this account.") end
            end
            Runtime.BloxFns.FormatGameMoney = function(Value)
                local N=tonumber(Value)
                if not N then return tostring(Value or "?") end
                local S=tostring(math.floor(N+0.5))
                local Sign=""
                if string.sub(S,1,1)=="-" then Sign="-"; S=string.sub(S,2) end
                local Rev=string.reverse(S)
                Rev=Rev:gsub("(%d%d%d)","%1,")
                local Out=string.reverse(Rev):gsub("^,","")
                return Sign..Out
            end
