            Runtime.BloxFns.StylePurchaseOptions = function()
                local Order={"Dark Step","Electric","Water Kung Fu","Dragon Breath","Superhuman","Death Step","Sharkman Karate","Electric Claw","Dragon Talon","Godhuman","Sanguine Art"}
                local Out={}
                for _,Name in ipairs(Order) do table.insert(Out,Runtime.BloxFns.PurchaseLabel(Name,Runtime.BloxStylePrices[Name])) end
