            Runtime.BloxFns.AbilityPurchaseOptions = function()
                local Order={"Buso Haki","Observation Haki","Sky Jump","Flash Step"}
                local Out={}
                for _,Name in ipairs(Order) do table.insert(Out,Runtime.BloxFns.PurchaseLabel(Name,Runtime.BloxAbilityPrices[Name])) end
