                ["Black Leg"]={Seas={1,2,3},Sellers={"Dark Step Teacher"}},
                ["Electric"]={Seas={1,2,3},Sellers={"Mad Scientist"}},
                ["Water Kung Fu"]={Seas={1,2,3},Sellers={"Water Kung-fu Teacher","Water Kung Fu Teacher"}},
                ["Fishman Karate"]={Seas={1,2,3},Sellers={"Water Kung-fu Teacher","Water Kung Fu Teacher"}},
                ["Dragon Breath"]={Seas={2,3},Sellers={"Sabi"}},
