            Runtime.BloxFns.SeaDisplay = function(Number)
                Number=tonumber(Number)
                return Number and ("Sea "..tostring(Number)) or "Unknown Sea"
            end
            Runtime.BloxFns.SeasDisplay = function(Seas)
                local Out={}
                for _,Number in ipairs(Seas or {}) do table.insert(Out,Runtime.BloxFns.SeaDisplay(Number)) end
                return #Out>0 and table.concat(Out," / ") or "Unknown Sea"
            end
            Runtime.BloxFns.SeaAllowed = function(Seas)
                local Current=tonumber(BloxSeaNumber())
                if not Current then return false end
                for _,Number in ipairs(Seas or {}) do if tonumber(Number)==Current then return true end end
                return false
            end
            Runtime.BloxFns.SameNPCName = function(A,B)
                return CompactEnemyName(tostring(A or ""))==CompactEnemyName(tostring(B or ""))
            end
            Runtime.BloxFns.FindLiveShopNPC = function(Aliases)
                local Folder=workspace:FindFirstChild("NPCs") or workspace:FindFirstChild("Npcs") or workspace:FindFirstChild("QuestNPCs")
                if not Folder then return nil end
                -- Exact alias matching prevents "Blox Fruit Dealer" from accidentally
                -- resolving the Advanced Fruit Dealer / Gacha NPC.
                for _,Alias in ipairs(Aliases or {}) do
                    for _,Obj in ipairs(Folder:GetDescendants()) do
                        if Obj:IsA("Model") and GetRoot(Obj) and Runtime.BloxFns.SameNPCName(Obj.Name,Alias) then return Obj end
                    end
                end
                return nil
            end
            Runtime.BloxFns.FindMappedShopCFrame = function(Aliases)
                local Map=BloxNPCMap()
                for _,Alias in ipairs(Aliases or {}) do
                    for Name,CF in pairs(Map) do
                        if Runtime.BloxFns.SameNPCName(Name,Alias) and typeof(CF)=="CFrame" then return CF,Name end
                    end
                end
                return nil,nil
            end
            Runtime.BloxFns.TravelToBloxShop = function(Sellers,ShopLabel)
                Runtime.Movement.Guard()
                local Live=Runtime.BloxFns.FindLiveShopNPC(Sellers)
                if Live then
                    local RR=GetRoot(Live)
                    if RR then
                        local Me=Root()
                        if Me and (Me.Position-RR.Position).Magnitude<=9 then return true,Live.Name end
                        local OK=MoveTo(Live,CFrame.new(0,2.5,4))
                        if OK then
                            local Now=Root()
                            local Current=GetRoot(Live)
                            if Now and Current and (Now.Position-Current.Position).Magnitude<=12 then return true,Live.Name end
                        end
                    end
                end

                local CF,MapName=Runtime.BloxFns.FindMappedShopCFrame(Sellers)
                if CF then
                    local OK=ProfileTravelToCFrame(CF*CFrame.new(0,2.5,4))
                    if OK then return true,MapName or ShopLabel end
                end

                Notify("Blox Fruits Shop",tostring(ShopLabel or "Seller").." could not be found in "..Runtime.BloxFns.SeaDisplay(BloxSeaNumber())..".")
                return false,nil
            end
            Runtime.BloxFns.StyleTeacherInfo = function(Name)
                local Info=Runtime.BloxStyleShopInfo[Name]
                if not Info then return nil,"No teacher route configured" end
                if not Runtime.BloxFns.SeaAllowed(Info.Seas) then
                    return nil,tostring(Name).." is not in "..Runtime.BloxFns.SeaDisplay(BloxSeaNumber())..". Available: "..Runtime.BloxFns.SeasDisplay(Info.Seas)
                end
                -- Prefer the replicated NPC guide because it provides the teacher's actual
                -- CFrame even when StreamingEnabled has not loaded the NPC model yet.
                local CF,Seller=Runtime.BloxFns.FindMappedShopCFrame(Info.Sellers)
                if CF then return {CFrame=CF,Seller=Seller or Info.Sellers[1],Source="NPC guide"} end
                local Live=Runtime.BloxFns.FindLiveShopNPC(Info.Sellers)
                local RR=Live and GetRoot(Live)
                if RR then return {CFrame=RR.CFrame,Seller=Live.Name,Source="live NPC"} end
                return nil,"Teacher coordinates are not available in the current sea guide/server."
            end
            Runtime.BloxFns.StyleTeacherText = function(Name)
                local Data,Err=Runtime.BloxFns.StyleTeacherInfo(Name)
                if not Data then return Err end
                local P=Data.CFrame.Position
                return tostring(Data.Seller).." • "..Runtime.BloxFns.SeaDisplay(BloxSeaNumber())
                    .." • X "..math.floor(P.X+0.5).."  Y "..math.floor(P.Y+0.5).."  Z "..math.floor(P.Z+0.5)
                    .." • "..tostring(Data.Source)
            end
            Runtime.BloxFns.GoStyleTeacher = function(Name)
                local Data,Err=Runtime.BloxFns.StyleTeacherInfo(Name)
                if not Data then Notify("Fighting Styles",Err); return false end
                local OK=ProfileTravelToCFrame(Data.CFrame*CFrame.new(0,2.5,4))
                if not OK then Notify("Fighting Styles","Could not reach "..tostring(Data.Seller).."."); return false end
                return true
            end

            -- Automatic prerequisite helper. It never fakes completion: it checks owned
            -- styles/mastery first, performs the one movement quest that can be completed
            -- deterministically (Electric Claw), and otherwise configures BananiHub's
            -- existing mastery farm or reports the exact drop/item still required.
            Runtime.BloxFns.AutoStyleTask = function(Name)
                local Data,Err=Runtime.BloxFns.StyleTeacherInfo(Name)
                if not Data then Notify("Fighting Style Task",Err); return false end
                local Alias={
                    ["Dark Step"]="Black Leg",["Electric"]="Electro",["Water Kung Fu"]="Fishman Karate",
                    ["Dragon Breath"]="Dragon Claw"
                }
                local function Tool(N) return Runtime.BloxFns.SimpleOwnedTool(Alias[N] or N) or Runtime.BloxFns.SimpleOwnedTool(N) end
                local function Mastery(N)
                    local T=Tool(N); if not T then return 0 end
                    for _,K in ipairs({"Level","Mastery","Mas"}) do local V=T:FindFirstChild(K); if V and tonumber(V.Value) then return tonumber(V.Value) end end
                    return tonumber(Runtime.ToolMasteryValue and Runtime.ToolMasteryValue(T.Name)) or 0
                end
                local function StartMastery(N,Goal)
                    local T=Tool(N)
                    if not T then return false end
                    State.BloxMasteryTool=T.Name; State.BloxMasteryTarget=Goal; State.BloxMasteryEnabled=true
                    State.SelectedTool=T.Name
                    Notify("Fighting Style Task",tostring(N).." needs mastery "..tostring(Goal)..". Mastery Finisher was configured for "..T.Name.."; turn Auto Farm on to grind it automatically.")
                    return true
                end
                if Tool(Name) then Notify("Fighting Style Task",Name.." is already owned. Going to its teacher to equip/confirm it."); return Runtime.BloxFns.BuyFightingStyle(Name) end

                local Req={
                    ["Superhuman"]={{"Dark Step",300},{"Electric",300},{"Water Kung Fu",300},{"Dragon Breath",300}},
                    ["Death Step"]={{"Dark Step",400}}, ["Sharkman Karate"]={{"Water Kung Fu",400}},
                    ["Electric Claw"]={{"Electric",400}}, ["Dragon Talon"]={{"Dragon Breath",400}},
                    ["Godhuman"]={{"Superhuman",400},{"Death Step",400},{"Sharkman Karate",400},{"Electric Claw",400},{"Dragon Talon",400}}
                }
                for _,R in ipairs(Req[Name] or {}) do
                    if not Tool(R[1]) then
                        Notify("Fighting Style Task","First getting prerequisite style: "..R[1])
                        Runtime.BloxFns.BuyFightingStyle(R[1]); return false
                    end
                    if Mastery(R[1])<R[2] then StartMastery(R[1],R[2]); return false end
                end

                if Name=="Electric Claw" then
                    -- Public game scripts consistently use this server command to start the
                    -- Previous Hero time trial. Use guide/live coordinates instead of a
                    -- hard-coded teacher coordinate, then route to Mansion and back.
                    if not Runtime.BloxFns.GoStyleTeacher(Name) then return false end
                    Runtime.InvokeBloxShop("BuyElectricClaw","Start")
                    task.wait(0.25)
                    local Mansion=CFrame.new(-12550.53,336.23,-7510.42)
                    if not ProfileTravelToCFrame(Mansion) then Notify("Fighting Style Task","Electric Claw trial: Mansion route failed."); return false end
                    if not Runtime.BloxFns.GoStyleTeacher(Name) then return false end
                    return Runtime.BloxFns.BuyFightingStyle(Name)
                end

                if Name=="Death Step" and not Runtime.BloxFns.SimpleOwnedTool("Library Key") then
                    Notify("Fighting Style Task","Death Step mastery is ready. Library Key is still required; defeat Awakened Ice Admiral, then press Auto Task again.")
                    return false
                elseif Name=="Sharkman Karate" and not Runtime.BloxFns.SimpleOwnedTool("Water Key") then
                    Notify("Fighting Style Task","Water Kung Fu mastery is ready. Water Key is still required; defeat Tide Keeper, then press Auto Task again.")
                    return false
                elseif Name=="Dragon Talon" and not Runtime.BloxFns.SimpleOwnedTool("Fire Essence") then
                    Runtime.InvokeBloxShop("Bones","Buy",1,1)
                    Notify("Fighting Style Task","Trying a Bones roll for Fire Essence. Press Auto Task again after Fire Essence is obtained.")
                    return false
                end

                -- For material-gated styles (especially Godhuman/Sanguine Art), the server
                -- remains authoritative. Route to the correct teacher and ask the normal
                -- purchase/status remote; its response tells the player what is still missing.
                return Runtime.BloxFns.BuyFightingStyle(Name)
            end

            Runtime.BloxFns.PrepareStylePurchase = function(Name)
                local Info=Runtime.BloxStyleShopInfo[Name]
                if not Info then
                    Notify("Blox Fruits Shop","No seller route is configured for "..tostring(Name)..".")
                    return false
                end
                if not Runtime.BloxFns.SeaAllowed(Info.Seas) then
                    Notify("Blox Fruits Shop",tostring(Name).." is not sold in "..Runtime.BloxFns.SeaDisplay(BloxSeaNumber())..". Go to "..Runtime.BloxFns.SeasDisplay(Info.Seas).." first.")
                    return false
                end
                -- Availability comes from the sea table above. Use the replicated guide's
                -- teacher position directly; do not wait for a streamed NPC model to appear.
                local CF,Seller=Runtime.BloxFns.FindMappedShopCFrame(Info.Sellers)
                if CF then
                    local Reached=ProfileTravelToCFrame(CF*CFrame.new(0,2.5,4))
                    if not Reached then
                        Notify("Blox Fruits Shop","Could not reach "..tostring(Seller or Name.." teacher")..". Purchase was not sent.")
                        return false
                    end
                    Notify("Blox Fruits Shop","Reached "..tostring(Seller or "teacher").." • buying/equipping "..tostring(Name)..".")
                    task.wait(0.20)
                else
                    Notify("Blox Fruits Shop","The teacher route for "..tostring(Name).." is unavailable in BananiHub's current sea guide. Purchase was not sent.")
                    return false
                end
                return true
            end
            Runtime.BloxFns.PrepareFruitPurchase = function()
                local Info=Runtime.BloxFruitShopInfo
                if not Runtime.BloxFns.SeaAllowed(Info.Seas) then
                    Notify("Blox Fruits Shop","The normal Blox Fruit Dealer is not configured for "..Runtime.BloxFns.SeaDisplay(BloxSeaNumber())..".")
                    return false
                end
                local OK,Seller=Runtime.BloxFns.TravelToBloxShop(Info.Sellers,"Blox Fruit Dealer")
                if not OK then return false end
                Notify("Blox Fruits Shop","Reached "..tostring(Seller or "Blox Fruit Dealer").." • opening purchase request.")
                task.wait(0.20)
                return true
            end

            Runtime.BloxFns.FruitDealerInfo = function(FruitName)
                local Want=CompactEnemyName(FruitName)
                local Ok,Fruits=Runtime.BloxReadDealer()
                if not Ok or type(Fruits)~="table" then return nil end
                for Key,Info in pairs(Fruits) do
                    if type(Info)=="table" then
                        local RawName=Info.Name or Info.FruitName or Info.DisplayName or (type(Key)=="string" and Key)
                        if RawName and CompactEnemyName(RawName)==Want then

                            if not Info.Name then
                                local Copy={}
                                for K,V in pairs(Info) do Copy[K]=V end
                                Copy.Name=tostring(RawName)
                                return Copy
                            end
                            return Info
                        end
                    elseif type(Key)=="string" and CompactEnemyName(Key)==Want then
                        return {Name=Key}
                    end
                end
                return nil
            end
            Runtime.BloxFns.FruitDealerAvailability = function(FruitName)
                local Info=Runtime.BloxFns.FruitDealerInfo(FruitName)
                if not Info then return nil,false end
                for _,Key in ipairs({"OnSale","InStock","Available","IsAvailable","Stock","CurrentStock","Amount"}) do
                    local Value=Info[Key]
                    if type(Value)=="boolean" then return Value,true end
                    if type(Value)=="number" then return Value>0,true end
                end
                return nil,false
            end
            Runtime.BloxFns.BloxFruitPrice = function(FruitName)
                local Info=Runtime.BloxFns.FruitDealerInfo(FruitName)
                if not Info then return nil end
                for _,Key in ipairs({"Price","Money","Cost","Value","Beli","BeliPrice"}) do
                    local Value=tonumber(Info[Key])
                    if Value and Value>0 then return Value end
                end
                return nil
            end
            Runtime.BloxFns.BackpackPhysicalFruits = function(MinimumPrice)
                local Out={}
                local Backpack=Player:FindFirstChildOfClass("Backpack")
                if not Backpack then return Out end
                MinimumPrice=tonumber(MinimumPrice) or 0
                for _,Tool in ipairs(Backpack:GetChildren()) do
                    if Tool:IsA("Tool") and (Tool:FindFirstChild("EatRemote") or string.find(string.lower(Tool.Name),"fruit",1,true)) then
                        local Raw=tostring(Tool:GetAttribute("OriginalName") or Tool.Name:gsub(" Fruit$",""))
                        local Price=Runtime.BloxFns.BloxFruitPrice(Raw)
                        -- Unknown prices are intentionally skipped. Never sacrifice a fruit whose value we cannot verify.
                        if Price and Price>=MinimumPrice then
                            table.insert(Out,{Tool=Tool,Name=Raw,Price=Price})
                        end
                    end
                end
                table.sort(Out,function(A,B)
                    if A.Price==B.Price then return string.lower(A.Name)<string.lower(B.Name) end
                    return A.Price<B.Price
                end)
                return Out
            end
            Runtime.BloxFns.LowestBackpackPhysicalFruit = function(MinimumPrice)
                local List=Runtime.BloxFns.BackpackPhysicalFruits(MinimumPrice)
                return List[1]
            end
            Runtime.BloxFns.HasRaidChip = function()
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Obj in ipairs(Container:GetChildren()) do
                            if Obj:IsA("Tool") then
                                local Lower=string.lower(Obj.Name)
                                if string.find(Lower,"microchip",1,true) then return Obj end
                            end
                        end
                    end
                end
                return nil
            end
            Runtime.BloxFns.BuySelectedFruit = function(FruitName)
                FruitName=tostring(FruitName or "")
                if FruitName=="" or FruitName=="Select Fruit" then return false end
                if Runtime.BloxFruitPurchaseBusy then return false end
                if os.clock()-(Runtime.BloxFruitPurchaseAt or -math.huge)<1.25 then return false end
                if not Runtime.BloxFns.PrepareFruitPurchase() then return false end

                Runtime.BloxFruitPurchaseBusy=true
                local Ok,Confirmed=pcall(function()
                    local Remote=BloxCommF()
                    if not Remote then Notify("Blox Fruits Shop","Dealer is not loaded."); return false end
                    local Info=Runtime.BloxFns.FruitDealerInfo(FruitName)
                    local RawName=tostring((Info and Info.Name) or FruitName)
                    Runtime.BloxFruitPurchaseFailUntil=Runtime.BloxFruitPurchaseFailUntil or {}
                    local Key=CompactEnemyName(RawName)
                    if os.clock()<(Runtime.BloxFruitPurchaseFailUntil[Key] or 0) then return false end
                    local BeforeTools={}
                    for _,Tool in ipairs(BloxFruitTools(true)) do BeforeTools[Tool]=true end
                    local Data=Player:FindFirstChild("Data")
                    local FruitValue=Data and Data:FindFirstChild("DevilFruit")
                    local Previous=FruitValue and FruitValue.Value
                    Runtime.BloxFruitPurchaseAt=os.clock()
                    local Sent,Response=QueryRemote(Remote,"PurchaseRawFruit",RawName)
                    if not Sent then
                        local Clean=RawName:gsub("%s+Fruit$","")
                        local Alternate=Clean
                        if not Clean:find("%-",1,true) and Clean~="" then Alternate=Clean.."-"..Clean end
                        if Alternate~=RawName then Sent,Response=QueryRemote(Remote,"PurchaseRawFruit",Alternate) end
                    end
                    local Deadline=os.clock()+1.75
                    repeat
                        Runtime.Movement.Guard()
                        for _,Tool in ipairs(BloxFruitTools(true)) do
                            local Name=Tool:GetAttribute("OriginalName") or Tool.Name:gsub(" Fruit$","")
                            if not BeforeTools[Tool] and CompactEnemyName(Name)==Key then
                                Notify("Blox Fruits Shop","Confirmed purchase: "..RawName)
                                return true
                            end
                        end
                        if FruitValue and FruitValue.Parent and FruitValue.Value~=Previous
                            and CompactEnemyName(FruitValue.Value)==Key then
                            Notify("Blox Fruits Shop","Confirmed equipped fruit: "..RawName)
                            return true
                        end
                        if not Sent then break end
                        task.wait(0.1)
                    until os.clock()>=Deadline
                    Runtime.BloxFruitPurchaseFailUntil[Key]=os.clock()+8
                    Notify("Blox Fruits Shop","Purchase not confirmed: "..tostring(Response or RawName))
                    return false
                end)
                Runtime.BloxFruitPurchaseBusy=false
                if not Ok then
                    if tostring(Confirmed):find("BANANI_CANCELLED",1,true) then error(Confirmed,0) end
                    Notify("Blox Fruits Shop","Purchase error: "..tostring(Confirmed))
                    return false
                end
                return Confirmed,Confirmed
            end

            Runtime.BloxFns.FruitPurchaseOptions = function()
                local Out={"Select Fruit"}
                local Ok,Fruits=Runtime.BloxReadDealer()
                if Ok and type(Fruits)=="table" then
                    for Key,Info in pairs(Fruits) do
                        if type(Info)=="table" then
                            local RawName=Info.Name or Info.FruitName or Info.DisplayName or (type(Key)=="string" and Key)
                            if RawName then
                                local Price=tonumber(Info.Price or Info.Money or Info.Cost or Info.Value)
                                local Label=tostring(RawName)
                                if Price then Label=Runtime.BloxFns.PurchaseLabel(Label,"$"..Runtime.BloxFns.FormatGameMoney(Price)) end
                                table.insert(Out,Label)
                            end
                        elseif type(Key)=="string" then
                            table.insert(Out,Key)
                        end
                    end
                end
                if #Out==1 then
                    for _,Name in ipairs(BloxFruitCatalog()) do if Name~="Select Fruit" then table.insert(Out,Name) end end
                end
                table.sort(Out,function(A,B)
                    if A==B then return false end
                    if A=="Select Fruit" then return true end
                    if B=="Select Fruit" then return false end
                    return string.lower(A)<string.lower(B)
                end)
                return Out
            end

            Runtime.BloxFns.SimpleOwnedTool = function(Name)
                local Wanted=string.lower(tostring(Name or ""))
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Tool in ipairs(Container:GetChildren()) do
                            if Tool:IsA("Tool") and string.lower(Tool.Name)==Wanted then return Tool end
                        end
                    end
                end
                return nil
            end
            Runtime.InvokeBloxShop=function(...)
                local Remote=BloxCommF()
                if not Remote then return false,"CommF_ missing" end
                local Args=table.pack(...)
                local Ok,Result=pcall(function()
                    return Remote:InvokeServer(table.unpack(Args,1,Args.n))
                end)
                return Ok,Result
            end
            Runtime.BloxFns.BuyAbility = function(Name)
                local Remote=BloxCommF()
                local Ok,Result=false,nil
                if Name=="Observation Haki" then Ok,Result=Runtime.InvokeBloxShop("KenTalk","Buy")
                elseif Name=="Buso Haki" then Ok,Result=Runtime.InvokeBloxShop("BuyHaki","Buso")
                elseif Name=="Sky Jump" then Ok,Result=Runtime.InvokeBloxShop("BuyHaki","Geppo")
                elseif Name=="Flash Step" then Ok,Result=Runtime.InvokeBloxShop("BuyHaki","Soru") end
                Notify("Blox Fruits Shop",Ok and ("Purchase request sent: "..tostring(Name)..(Result~=nil and (" • "..tostring(Result)) or "")) or ("Purchase failed: "..tostring(Name)))
                return Ok,Result
            end
            Runtime.BloxFns.BuyFightingStyle = function(Name)
                if not Runtime.BloxFns.PrepareStylePurchase(Name) then return false end
                local Remote=BloxCommF()
                if not Remote then Notify("Blox Fruits Shop","Shop remote is not loaded."); return false end
                local Ok,Result=false,nil
                if Name=="Dark Step" or Name=="Black Leg" then Ok,Result=Runtime.InvokeBloxShop("BuyBlackLeg")
                elseif Name=="Electric" then Ok,Result=Runtime.InvokeBloxShop("BuyElectro")
                elseif Name=="Water Kung Fu" or Name=="Fishman Karate" then Ok,Result=Runtime.InvokeBloxShop("BuyFishmanKarate")
                elseif Name=="Dragon Breath" or Name=="Dragon Claw" then
                    Runtime.InvokeBloxShop("BlackbeardReward","DragonClaw","1")
                    Ok,Result=Runtime.InvokeBloxShop("BlackbeardReward","DragonClaw","2")
                elseif Name=="Superhuman" then Ok,Result=Runtime.InvokeBloxShop("BuySuperhuman")
                elseif Name=="Death Step" then Ok,Result=Runtime.InvokeBloxShop("BuyDeathStep")
                elseif Name=="Sharkman Karate" then Runtime.InvokeBloxShop("BuySharkmanKarate",true); Ok,Result=Runtime.InvokeBloxShop("BuySharkmanKarate")
                elseif Name=="Electric Claw" then Ok,Result=Runtime.InvokeBloxShop("BuyElectricClaw")
                elseif Name=="Dragon Talon" then Runtime.InvokeBloxShop("BuyDragonTalon",true); Ok,Result=Runtime.InvokeBloxShop("BuyDragonTalon")
                elseif Name=="Godhuman" then Runtime.InvokeBloxShop("BuyGodhuman",true); Ok,Result=Runtime.InvokeBloxShop("BuyGodhuman")
                elseif Name=="Sanguine Art" then Runtime.InvokeBloxShop("BuySanguineArt",true); Ok,Result=Runtime.InvokeBloxShop("BuySanguineArt") end
                local VerifyNames={
                    ["Dark Step"]={"Black Leg","Dark Step"},["Black Leg"]={"Black Leg","Dark Step"},
                    ["Electric"]={"Electro","Electric"},["Water Kung Fu"]={"Fishman Karate","Water Kung Fu"},
                    ["Fishman Karate"]={"Fishman Karate","Water Kung Fu"},["Dragon Breath"]={"Dragon Claw","Dragon Breath"},
                    ["Dragon Claw"]={"Dragon Claw","Dragon Breath"}
                }
                local Names=VerifyNames[Name] or {Name}
                local Confirmed=false
                local Deadline=os.clock()+1.25
                repeat
                    for _,OwnedName in ipairs(Names) do if Runtime.BloxFns.SimpleOwnedTool(OwnedName) then Confirmed=true; break end end
                    if Confirmed then break end
                    task.wait(0.1)
                until os.clock()>=Deadline
                if Confirmed then Notify("Blox Fruits Shop","Confirmed style: "..tostring(Name))
                elseif Ok then Notify("Blox Fruits Shop","Request sent for "..tostring(Name).." • game response: "..tostring(Result or "requirements/ownership checked"))
                else Notify("Blox Fruits Shop","Purchase failed: "..tostring(Name)) end
                return Ok,Result
            end
