            Runtime.BloxFns.FindNamedWorldObject = function(Needles)
                local Best,BestDistance=nil,math.huge
                local Me=Root()
                local NeedleList=type(Needles)=="table" and Needles or {Needles}
                for _,Obj in ipairs(Runtime.ProfileObjects()) do
                    if Obj and Obj.Parent then
                        local Lower=string.lower(tostring(Obj.Name or ""))
                        local Match=false
                        for _,Needle in ipairs(NeedleList) do
                            if string.find(Lower,string.lower(tostring(Needle)),1,true) then Match=true break end
                        end
                        if Match and GetRoot(Obj) then
                            local D=Me and (GetRoot(Obj).Position-Me.Position).Magnitude or 0
                            if D<BestDistance then Best,BestDistance=Obj,D end
                        end
                    end
                end
                return Best
            end
            Runtime.BloxFns.BartiloPlateStep = function()
                local Map=workspace:FindFirstChild("Map")
                local Dressrosa=Map and (Map:FindFirstChild("Dressrosa") or Map:FindFirstChild("Kingdom of Rose"))
                local Plates=Dressrosa and Dressrosa:FindFirstChild("BartiloPlates",true)
                if not Plates then
                    Runtime.BloxFns.SetBloxProgressionStatus("THIRD_SEA_BARTILO_PLATES_MISSING • move near Colosseum")
                    return false
                end

                -- The puzzle is ordered. Prefer Plate1..Plate8 explicitly instead of relying on
                -- lexicographic GetDescendants() order, which can touch the wrong part first.
                local Ordered={}
                for I=1,8 do
                    local Plate=Plates:FindFirstChild("Plate"..tostring(I),true)
                    if Plate and Plate:IsA("BasePart") then table.insert(Ordered,Plate) end
                end
                if #Ordered<8 then
                    -- Layout fallback for renamed containers: preserve numeric suffix ordering and
                    -- deduplicate any numbered plates already found above.
                    local Seen={}
                    for _,Plate in ipairs(Ordered) do Seen[Plate]=true end
                    local Extra={}
                    for _,Obj in ipairs(Plates:GetDescendants()) do
                        if Obj:IsA("BasePart") and not Seen[Obj]
                            and string.find(string.lower(Obj.Name),"plate",1,true) then
                            table.insert(Extra,Obj)
                        end
                    end
                    table.sort(Extra,function(A,B)
                        local AN=tonumber(tostring(A.Name):match("(%d+)$")) or math.huge
                        local BN=tonumber(tostring(B.Name):match("(%d+)$")) or math.huge
                        if AN~=BN then return AN<BN end
                        return tostring(A.Name)<tostring(B.Name)
                    end)
                    for _,Obj in ipairs(Extra) do table.insert(Ordered,Obj) end
                end
                if #Ordered==0 then return false end

                for _,Plate in ipairs(Ordered) do
                    Runtime.Movement.Guard()
                    -- Activated Bartilo plates turn green; do not retouch solved steps on retries.
                    if Plate.Parent and Plate.Color.G<0.98 then
                        Runtime.BloxFns.SetBloxProgressionStatus("Bartilo Colosseum puzzle • "..tostring(Plate.Name))
                        if not TouchObject(Plate) then return false end
                        task.wait(0.12)
                    end
                end
                local Ok,Progress=QueryRemote(BloxCommF(),"BartiloQuestProgress","Bartilo")
                return Ok and tonumber(Progress)~=nil and tonumber(Progress)>=3
            end
            Runtime.BloxFns.BartiloThirdSeaStep = function()
                local Ok,Progress=QueryRemote(BloxCommF(),"BartiloQuestProgress","Bartilo")
                local N=Ok and tonumber(Progress) or nil
                if not N then return false,"BARTILO_PROGRESS_UNAVAILABLE" end
                if N<=0 then
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea prerequisite • Bartilo: defeat 50 Swan Pirates")
                    local Title=string.lower(QuestTitleText() or "")
                    if not string.find(Title,"swan pirate",1,true) then
                        QueryRemote(BloxCommF(),"StartQuest","BartiloQuest",1)
                        task.wait(0.35)
                    end
                    local Enemy=NearestBloxEnemy("Swan Pirate",false,true)
                    if Enemy then FarmBloxEnemy(Enemy)
                    else
                        local Spawn=FindBloxSpawn("Swan Pirate")
                        ProfileTravelToCFrame(Spawn and (Spawn*CFrame.new(0,15,0)) or CFrame.new(932.6,156.1,1180.3))
                    end
                    return false,"BARTILO_SWAN_PIRATES"
                elseif N==1 then
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea prerequisite • Bartilo: defeat Jeremy")
                    local Jeremy=NearestBloxEnemy("Jeremy",true,true) or NearestBloxEnemy("Jeremy",false,true)
                    if Jeremy then FarmBloxEnemy(Jeremy)
                    else
                        local Spawn=FindBloxSpawn("Jeremy")
                        ProfileTravelToCFrame(Spawn and (Spawn*CFrame.new(0,15,0)) or CFrame.new(1958.6,449.0,879.4))
                    end
                    return false,"BARTILO_JEREMY"
                elseif N==2 then
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea prerequisite • Bartilo: Colosseum plate puzzle")
                    if Runtime.BloxFns.BartiloPlateStep() then return true,"BARTILO_COMPLETE" end
                    return false,"BARTILO_PLATES"
                end
                return true,"BARTILO_COMPLETE"
            end
            Runtime.BloxFns.TrevorAccessStep = function()
                local Ok,Unlockables=QueryRemote(BloxCommF(),"GetUnlockables")
                if Ok and type(Unlockables)=="table" and Unlockables.FlamingoAccess then return true,"TREVOR_COMPLETE" end
                Runtime.BloxFns.SetBloxProgressionStatus("Third Sea prerequisite • Trevor needs a physical fruit worth $1,000,000+")
                local Choice=Runtime.BloxFns.LowestBackpackPhysicalFruit(1000000)
                if not Choice then
                    -- Try loading the cheapest known stored fruit worth >= $1M into the backpack.
                    local OkInv,Inventory=QueryRemote(BloxCommF(),"getInventory")
                    local BestName,BestPrice=nil,math.huge
                    if OkInv and type(Inventory)=="table" then
                        for _,Entry in pairs(Inventory) do
                            if type(Entry)=="table" then
                                local Type=string.lower(tostring(Entry.Type or Entry.type or ""))
                                local Name=Entry.Name or Entry.ItemName or Entry.name
                                local Price=Name and Runtime.BloxFns.BloxFruitPrice(Name) or nil
                                if Name and Price and Price>=1000000 and Price<BestPrice
                                    and (Type=="" or string.find(Type,"fruit",1,true)) then
                                    BestName,BestPrice=tostring(Name),Price
                                end
                            end
                        end
                    end
                    if BestName then
                        QueryRemote(BloxCommF(),"LoadFruit",BestName)
                        task.wait(0.45)
                        Choice=Runtime.BloxFns.LowestBackpackPhysicalFruit(1000000)
                    end
                end
                if not Choice then return false,"TREVOR_FRUIT_MISSING" end
                local H=Humanoid()
                if H and Choice.Tool and Choice.Tool.Parent~=Character() then pcall(function() H:EquipTool(Choice.Tool) end) end
                GoBloxNPC("Trevor")
                task.wait(0.2)
                QueryRemote(BloxCommF(),"TalkTrevor","1")
                QueryRemote(BloxCommF(),"TalkTrevor","2")
                QueryRemote(BloxCommF(),"TalkTrevor","3")
                task.wait(0.4)
                local Ok2,U2=QueryRemote(BloxCommF(),"GetUnlockables")
                return Ok2 and type(U2)=="table" and U2.FlamingoAccess==true,
                    (Ok2 and type(U2)=="table" and U2.FlamingoAccess and "TREVOR_COMPLETE" or "TREVOR_NOT_CONFIRMED")
            end
            -- A Roblox place teleport destroys the current Lua VM. If the executor exposes a
            -- queue-on-teleport API, preserve BananiHub itself so Sea 3 can restore without relying
            -- on executor auto-execute. Prefer a small filesystem bootstrap; only fall back to a
            -- direct queued source string when local file APIs are unavailable.
            Runtime.BloxFns.QueueBananiHubAfterTeleport = function()
                if Runtime.BloxTeleportReloadQueued then return true,"ALREADY_QUEUED" end
                local Env=(getgenv and getgenv()) or _G
                local Source=Env and Env.__BANANIHUB_SELF_SOURCE
                if type(Source)~="string" or #Source<1024 then return false,"SELF_SOURCE_UNAVAILABLE" end

                local Queue=nil
                pcall(function()
                    if type(Env.queue_on_teleport)=="function" then
                        Queue=Env.queue_on_teleport
                    elseif type(Env.queueonteleport)=="function" then
                        Queue=Env.queueonteleport
                    elseif type(Env.syn)=="table" and type(Env.syn.queue_on_teleport)=="function" then
                        Queue=Env.syn.queue_on_teleport
                    elseif type(Env.fluxus)=="table" and type(Env.fluxus.queue_on_teleport)=="function" then
                        Queue=Env.fluxus.queue_on_teleport
                    end
                end)
                if type(Queue)~="function" then return false,"QUEUE_ON_TELEPORT_UNSUPPORTED" end

                local Bootstrap=nil
                local UsedFileBootstrap=false
                local PersistPath="BANANIHUB/TeleportResume_v5.18.33.lua"
                if type(Env.writefile)=="function" and type(Env.readfile)=="function" then
                    pcall(function()
                        if type(Env.makefolder)=="function" then
                            local NeedFolder=true
                            if type(Env.isfolder)=="function" then
                                local OK,Exists=pcall(Env.isfolder,"BANANIHUB")
                                NeedFolder=not (OK and Exists)
                            end
                            if NeedFolder then pcall(Env.makefolder,"BANANIHUB") end
                        end
                    end)
                    local Wrote=pcall(Env.writefile,PersistPath,Source)
                    if Wrote then
                        UsedFileBootstrap=true
                        Bootstrap=[=[
repeat task.wait(0.1) until game:IsLoaded()
if game.PlaceId~=7449423635 then return end
local Players=game:GetService("Players")
repeat task.wait(0.1) until Players.LocalPlayer
local Env=(getgenv and getgenv()) or _G
Env.__BANANIHUB_TELEPORT_RESUME_AUTO_FARM=true
task.wait(1.25)
if type(Env.__BANANIHUB_INSTANCE)=="table" or Env.__BANANIHUB_BOOTING==true then return end
local ReadFile=Env.readfile or readfile
if type(ReadFile)~="function" then
    warn("BANANIHUB | teleport fallback readfile API disappeared after teleport")
    return
end
local OK,Source=pcall(ReadFile,"BANANIHUB/TeleportResume_v5.18.33.lua")
if not OK or type(Source)~="string" or #Source<1024 then
    warn("BANANIHUB | teleport fallback could not read saved source")
    return
end
Env.__BANANIHUB_SELF_SOURCE=Source
local Loader,LoadError=loadstring(Source)
if not Loader then
    warn("BANANIHUB | teleport fallback compile failed: "..tostring(LoadError))
    return
end
Env.__BANANIHUB_BOOTING=true
local Ran,RunError=pcall(Loader)
Env.__BANANIHUB_BOOTING=nil
if not Ran then warn("BANANIHUB | teleport fallback startup failed: "..tostring(RunError)) end
]=]
                    end
                end

                if not Bootstrap then
                    local OK,Quoted=pcall(string.format,"%q",Source)
                    if not OK or type(Quoted)~="string" then return false,"DIRECT_SOURCE_ENCODE_FAILED" end
                    Bootstrap=
                        'repeat task.wait(0.1) until game:IsLoaded()\n'
                        ..'if game.PlaceId~=7449423635 then return end\n'
                        ..'local Players=game:GetService("Players")\n'
                        ..'repeat task.wait(0.1) until Players.LocalPlayer\n'
                        ..'local Env=(getgenv and getgenv()) or _G\n'
                        ..'Env.__BANANIHUB_TELEPORT_RESUME_AUTO_FARM=true\n'
                        ..'task.wait(1.25)\n'
                        ..'if type(Env.__BANANIHUB_INSTANCE)=="table" or Env.__BANANIHUB_BOOTING==true then return end\n'
                        ..'local Source='..Quoted..'\n'
                        ..'Env.__BANANIHUB_SELF_SOURCE=Source\n'
                        ..'local Loader,LoadError=loadstring(Source)\n'
                        ..'if not Loader then warn("BANANIHUB | teleport fallback compile failed: "..tostring(LoadError)); return end\n'
                        ..'Env.__BANANIHUB_BOOTING=true\n'
                        ..'local Ran,RunError=pcall(Loader)\n'
                        ..'Env.__BANANIHUB_BOOTING=nil\n'
                        ..'if not Ran then warn("BANANIHUB | teleport fallback startup failed: "..tostring(RunError)) end'
                end

                local Queued,QueueError=pcall(Queue,Bootstrap)
                if not Queued then return false,"QUEUE_FAILED: "..tostring(QueueError) end
                Runtime.BloxTeleportReloadQueued=true
                Runtime.BloxTeleportReloadMethod=UsedFileBootstrap and "Saved source + queued loader" or "Direct queued source"
                return true,Runtime.BloxTeleportReloadMethod
            end

            Runtime.BloxFns.PrepareThirdSeaAutoFarmResume = function()
                local Saved=false
                pcall(function()
                    TeleportService:SetTeleportSetting("BananiHubResumeAutoFarm",Runtime.BloxAutoLevelActive==true)
                    Saved=true
                end)
                local Queued,QueueReason=Runtime.BloxFns.QueueBananiHubAfterTeleport()
                Runtime.BloxThirdSeaTeleportFallbackStatus=Queued and ("Ready • "..tostring(QueueReason)) or ("Unavailable • "..tostring(QueueReason))
                return Saved or Queued,Queued,QueueReason
            end
            Runtime.BloxFns.ThirdSeaQuestStep = function()
                if Runtime.BloxFns.CurrentSeaName()~="Sea 2" then return false,"NOT_SECOND_SEA" end
                if BloxLevel()<1500 then
                    Runtime.BloxFns.SetBloxProgressionStatus("Reach level 1500 first • current level "..tostring(BloxLevel()))
                    return false,"LEVEL_1500_REQUIRED"
                end
                local BartiloOK,BartiloReason=Runtime.BloxFns.BartiloThirdSeaStep()
                if not BartiloOK then return false,BartiloReason end
                local TrevorOK,TrevorReason=Runtime.BloxFns.TrevorAccessStep()
                if not TrevorOK then return false,TrevorReason end

                -- ZQuestProgress is the authoritative story state. Check==1 means the story fight
                -- is complete and TravelZou can be attempted; General==0 means King Red Head can
                -- begin the rip_indra encounter. A missing/negative General state still needs Don Swan.
                local CheckOK,Check=QueryRemote(BloxCommF(),"ZQuestProgress","Check")
                local GeneralOK,General=QueryRemote(BloxCommF(),"ZQuestProgress","General")
                local CheckN=CheckOK and tonumber(Check) or nil
                local GeneralN=GeneralOK and tonumber(General) or nil

                if CheckN==1 then
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea quest complete • traveling through Mr. Captain")
                    Runtime.BloxFns.PrepareThirdSeaAutoFarmResume()
                    local TravelOK=select(1,QueryRemote(BloxCommF(),"TravelZou"))
                    if not TravelOK and GoBloxNPC("Mr. Captain") then
                        task.wait(0.25)
                        Runtime.BloxFns.PrepareThirdSeaAutoFarmResume()
                        TravelOK=select(1,QueryRemote(BloxCommF(),"TravelZou"))
                    end
                    return TravelOK,TravelOK and "THIRD_SEA_TRAVEL_SENT" or "TRAVEL_ZOU_NOT_READY"
                end

                -- If the story boss is already live, fight it before deciding an earlier prerequisite
                -- is missing. This prevents a transient progress read from sending us back to Don Swan.
                local Indra=NearestBloxEnemy("rip_indra",true,true) or NearestBloxEnemy("rip_indra",false,true)
                if Indra then
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea quest • defeating rip_indra")
                    FarmBloxEnemy(Indra)
                    return false,"RIP_INDRA"
                end

                if GeneralN==nil or GeneralN<0 then
                    local DonSwan=NearestBloxEnemy("Don Swan",true,true) or NearestBloxEnemy("Don Swan",false,true)
                    if DonSwan then
                        Runtime.BloxFns.SetBloxProgressionStatus("Third Sea quest • defeating Don Swan")
                        FarmBloxEnemy(DonSwan)
                        return false,"DON_SWAN"
                    end
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea quest • waiting at Don Swan spawn")
                    local SwanSpawn=FindBloxSpawn("Don Swan")
                    local SwanCF=SwanSpawn and (SwanSpawn*CFrame.new(0,12,0)) or (BloxBossFallbackCFrames["Don Swan"]*CFrame.new(0,12,0))
                    ProfileTravelToCFrame(SwanCF)
                    return false,"DON_SWAN_WAIT"
                end

                if GeneralN==0 then
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea quest • King Red Head → rip_indra")
                    local King=Runtime.BloxFns.FindNamedWorldObject({"king red head","kingredhead"})
                    if King then MoveTo(King,CFrame.new(0,0,4))
                    else ProfileTravelToCFrame(CFrame.new(-1928.5,12.2,1738.3)) end
                    local Now=os.clock()
                    if Now-(Runtime.BloxThirdSeaLastBeginAt or 0)>=1.5 then
                        QueryRemote(BloxCommF(),"ZQuestProgress","Begin")
                        Runtime.BloxThirdSeaLastBeginAt=Now
                    end
                    return false,"RIP_INDRA_SPAWNING"
                end

                -- Positive non-complete states are uncommon; try the server-authoritative travel
                -- call instead of replaying earlier prerequisites. It will refuse safely if not ready.
                if GeneralN and GeneralN>0 then
                    Runtime.BloxFns.PrepareThirdSeaAutoFarmResume()
                    local TravelOK=select(1,QueryRemote(BloxCommF(),"TravelZou"))
                    return TravelOK,TravelOK and "THIRD_SEA_TRAVEL_SENT" or "ZQUEST_PROGRESS_WAIT"
                end

                Runtime.BloxFns.SetBloxProgressionStatus("Third Sea quest state unavailable • retrying")
                return false,"ZQUEST_PROGRESS_UNAVAILABLE"
            end
            Runtime.BloxFns.AutoNextSeaStep = function()
                local Sea,Level=Runtime.BloxFns.CurrentSeaName(),BloxLevel()
                if Sea=="Sea 1" and Level>=700 then
                    Runtime.BloxFns.SetBloxProgressionStatus("Second Sea unlock • Military Detective / Ice Admiral / Experienced Captain")
                    local Ok=select(1,QueryRemote(BloxCommF(),"TravelDressrosa"))
                    if not Ok then Runtime.BloxFns.GoNextProgressionNPC() end
                elseif Sea=="Sea 2" and Level>=1500 then
                    local Done,Reason=Runtime.BloxFns.ThirdSeaQuestStep()
                    Runtime.BloxQuestLastFailure=Done and nil or Reason
                elseif Sea=="Sea 3" then
                    Runtime.BloxFns.SetBloxProgressionStatus("Third Sea unlocked ✓")
                    Runtime.SetFlagValue("GameProfile_Blox_AutoNextSea",false)
                else
                    Runtime.BloxFns.SetBloxProgressionStatus("Reach the required level for the next sea")
                end
            end

            -- Targeted Blox Fruits PvP: one selected player, shared movement, melee only.
            Runtime.BloxPvPStep=function()
                local Target=State.BloxPvPTarget and FindPlayerByDisplayName(State.BloxPvPTarget) or nil
                local CharacterTarget=Target and Target.Character
                local TH=CharacterTarget and CharacterTarget:FindFirstChildOfClass("Humanoid")
                local TR=CharacterTarget and CharacterTarget:FindFirstChild("HumanoidRootPart")
                local Me=Root()
                local MyHum=Humanoid()
                if not Target or not CharacterTarget or not TH or TH.Health<=0 or not TR or not Me or not MyHum or MyHum.Health<=0 then
                    Runtime.BloxPvPStatus="NO_LIVE_TARGET"
                    Runtime.BloxPvPRetreating=false
                    if Target and TH and TH.Health<=0 then Runtime.SetFlagValue("GameProfile_Blox_SelectedPvP",false) end
                    return
                end

                local HPPct=MyHum.MaxHealth>0 and (MyHum.Health/MyHum.MaxHealth*100) or 100
                if HPPct<=45 then Runtime.BloxPvPRetreating=true
                elseif HPPct>=72 then Runtime.BloxPvPRetreating=false end

                -- Water is never a valid combat position. Lift immediately and let the next
                -- pass establish the safer hover/retreat route above the target.
                if MyHum.FloorMaterial==Enum.Material.Water then
                    pcall(function()
                        Me.CFrame=Me.CFrame+Vector3.new(0,34,0)
                        Me.AssemblyLinearVelocity=Vector3.zero
                        Me.AssemblyAngularVelocity=Vector3.zero
                    end)
                    Runtime.BloxPvPStatus="WATER_ESCAPE • repositioning"
                    return
                end

                local function LiveTargetCF(Retreat)
                    local C=Target.Character
                    local H=C and C:FindFirstChildOfClass("Humanoid")
                    local R=C and C:FindFirstChild("HumanoidRootPart")
                    local LR=Root()
                    if not H or H.Health<=0 or not R or not LR then return nil end
                    if Retreat then
                        local Away=LR.Position-R.Position
                        local Flat=Vector3.new(Away.X,0,Away.Z)
                        if Flat.Magnitude<0.1 then Flat=-R.CFrame.LookVector end
                        local P=R.Position+Flat.Unit*48+Vector3.new(0,22,0)
                        return CFrame.lookAt(P,R.Position+Vector3.new(0,3,0))
                    end
                    local P=(R.CFrame*CFrame.new(0,10,8)).Position
                    return CFrame.lookAt(P,R.Position+Vector3.new(0,2.5,0))
                end

                if Runtime.BloxPvPRetreating then
                    Runtime.BloxPvPStatus="RETREATING • HP "..tostring(math.floor(HPPct+0.5)).."% • "..Target.DisplayName
                    local SafeCF=LiveTargetCF(true)
                    if SafeCF and (Me.Position-SafeCF.Position).Magnitude>6 then ProfileTravelToCFrame(SafeCF,function() return LiveTargetCF(true) end) end
                    return
                end

                local Reach=math.max(tonumber(State.BloxM1Reach) or 20,18)
                local Desired=LiveTargetCF(false)
                Runtime.BloxPvPStatus="SAFE HOVER • "..Target.DisplayName.." • "..math.floor((TR.Position-Me.Position).Magnitude).." studs • HP "..math.floor(HPPct+0.5).."%"
                if Desired and (Me.Position-Desired.Position).Magnitude>5 then
                    ProfileTravelToCFrame(Desired,function() return LiveTargetCF(false) end)
                end

                CharacterTarget=Target.Character
                TH=CharacterTarget and CharacterTarget:FindFirstChildOfClass("Humanoid")
                TR=CharacterTarget and CharacterTarget:FindFirstChild("HumanoidRootPart")
                local LR=Root()
                if TH and TH.Health>0 and TR and LR and (TR.Position-LR.Position).Magnitude<=math.max(Reach+3,23) then
                    State.BloxAimBasicAttack=true
                    AttackBloxTarget(CharacterTarget,"Auto Melee","Melee",true)
                end
            end

            Runtime.BloxFlowerESPRecords=Runtime.BloxFlowerESPRecords or setmetatable({}, {__mode="k"})
            Runtime.BloxFlowerCache=Runtime.BloxFlowerCache or {[1]=setmetatable({}, {__mode="k"}),[2]=setmetatable({}, {__mode="k"}),[3]=setmetatable({}, {__mode="k"}),[4]=setmetatable({}, {__mode="k"})}
            Runtime.BloxFns.IndexFlowerObject=function(Obj)
                if not Obj or not Obj.Parent then return end
                if Obj:IsDescendantOf(workspace) and (Obj:IsA("BasePart") or Obj:IsA("Tool") or Obj:IsA("Model")) then
                    local Compact=string.lower(tostring(Obj.Name)):gsub("[%s_%-]","")
                    local Index=tonumber(Compact:match("^flower([123])$"))
                    if not Index then Index=({blueflower=1,redflower=2,yellowflower=3})[Compact] end
                    if Index then Runtime.BloxFlowerCache[Index][Obj]=true; return end
                end
                local Lower=string.lower(tostring(Obj.Name or "")):gsub("[%s_%-]","")
                if string.find(Lower,"fireflower",1,true) then Runtime.BloxFlowerCache[4][Obj]=true end
            end
            for _,Obj in ipairs(workspace:GetDescendants()) do Runtime.BloxFns.IndexFlowerObject(Obj) end
            TrackConnection(workspace.DescendantAdded:Connect(function(Obj) Runtime.BloxFns.IndexFlowerObject(Obj) end))
            Runtime.BloxFns.BloxHasFlower = function(Index)
                local Want="flower"..tostring(Index)
                local Alias=({[1]="blueflower",[2]="redflower",[3]="yellowflower"})[Index]
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Obj in ipairs(Container:GetChildren()) do
                            local Key=string.lower(Obj.Name):gsub("[%s_%-]","")
                            if Obj:IsA("Tool") and (Key==Want or Key==Alias) then return true end
                        end
                    end
                end
                return false
            end
            Runtime.BloxFns.BloxFindFlower = function(Index)
                local Best,BestDist=nil,math.huge
                local Me=Root()
                for Obj in pairs(Runtime.BloxFlowerCache[Index] or {}) do
                    local Part=Obj and Obj.Parent and GetRoot(Obj) or nil
                    if Part and Part.Transparency<0.98 then
                        local D=Me and (Part.Position-Me.Position).Magnitude or 0
                        if D<BestDist then Best,BestDist=Obj,D end
                    elseif Obj then
                        Runtime.BloxFlowerCache[Index][Obj]=nil
                    end
                end
                return Best
            end
            Runtime.BloxFns.BloxFindFireFlower = function()
                local Me=Root(); local Best,BestDistance=nil,math.huge
                for Obj in pairs(Runtime.BloxFlowerCache[4] or {}) do
                    local R=Obj and Obj.Parent and GetRoot(Obj) or nil
                    if R then
                        local D=Me and (R.Position-Me.Position).Magnitude or 0
                        if D<BestDistance then Best,BestDistance=Obj,D end
                    end
                end
                return Best
            end
            Runtime.BloxFindFireFlower=Runtime.BloxFns.BloxFindFireFlower
            Runtime.BloxFns.ClearBloxFlowerESP = function()
                for Obj,Record in pairs(Runtime.BloxFlowerESPRecords) do
                    if Record then
                        if Record.Highlight then pcall(function() Record.Highlight:Destroy() end) end
                        if Record.Gui then pcall(function() Record.Gui:Destroy() end) end
                    end
                    Runtime.BloxFlowerESPRecords[Obj]=nil
                end
            end
            Runtime.BloxFns.UpdateBloxFlowerESP = function()
                if not State.BloxFlowerESP then Runtime.BloxFns.ClearBloxFlowerESP(); return end
                local Live={}
                local Colors={[1]=Color3.fromRGB(70,150,255),[2]=Color3.fromRGB(255,75,85),[3]=Color3.fromRGB(255,221,55),[4]=Color3.fromRGB(255,115,40)}
                local Labels={[1]="BLUE FLOWER • V2",[2]="RED FLOWER • V2",[3]="YELLOW FLOWER • V2",[4]="FIRE FLOWER • DRACO V2"}
                local RaceLower=string.lower(Runtime.BloxFns.BloxCurrentRace())
                local Indices=string.find(RaceLower,"draco",1,true) and {1,2,4} or {1,2,3}
                for _,I in ipairs(Indices) do
                    local Obj=(I==4) and Runtime.BloxFns.BloxFindFireFlower() or Runtime.BloxFns.BloxFindFlower(I)
                    local IsYellowFarmTarget=false
                    if I==3 and not Obj and not Runtime.BloxFns.BloxHasFlower(3) then
                        Obj=NearestBloxEnemy("Swan Pirate",false,false)
                        IsYellowFarmTarget=Obj~=nil
                    end
                    if Obj then
                        local Part=GetRoot(Obj)
                        if not Part then continue end
                        Live[Obj]=true
                        local Record=Runtime.BloxFlowerESPRecords[Obj]
                        if not Record then
                            local HL=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
                            HL.Name="BananiBloxFlowerESP"
                            HL.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                            HL.FillTransparency=0.48
                            HL.OutlineTransparency=0
                            HL.FillColor=Colors[I]
                            HL.OutlineColor=Color3.new(1,1,1)
                            HL.Adornee=Obj
                            HL.Parent=Obj
                            local Gui=Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
                            Gui.Name="BananiBloxFlowerLabel"
                            Gui.AlwaysOnTop=true
                            Gui.Size=UDim2.fromOffset(150,24)
                            Gui.StudsOffsetWorldSpace=Vector3.new(0,2.2,0)
                            Gui.Adornee=Part
                            Gui.Parent=Obj
                            local L=Instance.new("TextLabel")
                            L.BackgroundColor3=Color3.fromRGB(14,14,17)
                            L.BackgroundTransparency=0.12
                            L.BorderSizePixel=0
                            L.Size=UDim2.fromScale(1,1)
                            L.Font=Enum.Font.GothamBold
                            L.TextSize=11
                            L.TextColor3=Colors[I]
                            L.Text=IsYellowFarmTarget and "YELLOW FLOWER • FARM NPC" or Labels[I]
                            L.Parent=Gui
                            local Corner=Instance.new("UICorner"); Corner.CornerRadius=UDim.new(0,6); Corner.Parent=L
                            Record={Highlight=HL,Gui=Gui,Label=L}
                            Runtime.BloxFlowerESPRecords[Obj]=Record
                        end
                        local Me=Root()
                        if Record.Label and Me then
                            local Prefix=IsYellowFarmTarget and "YELLOW FLOWER • FARM NPC" or Labels[I]
                            Record.Label.Text=Prefix.." • "..math.floor((Part.Position-Me.Position).Magnitude).." studs"
                        end
                    end
                end
                for Obj,Record in pairs(Runtime.BloxFlowerESPRecords) do
                    if not Live[Obj] or not Obj.Parent then
                        if Record.Highlight then pcall(function() Record.Highlight:Destroy() end) end
                        if Record.Gui then pcall(function() Record.Gui:Destroy() end) end
                        Runtime.BloxFlowerESPRecords[Obj]=nil
                    end
                end
            end
            Runtime.ClearBloxFlowerESP=Runtime.BloxFns.ClearBloxFlowerESP
            Runtime.UpdateBloxFlowerESP=Runtime.BloxFns.UpdateBloxFlowerESP

            Runtime.BloxRaceV2Status=Runtime.BloxRaceV2Status or "Idle"
            Runtime.BloxFns.SetRaceV2Status = function(Text)
                Runtime.BloxRaceV2Status=tostring(Text or "Idle")
                if Runtime.BloxRaceV2Paragraph and Runtime.BloxRaceV2Paragraph.Set then
                    pcall(function() Runtime.BloxRaceV2Paragraph:Set({Title="V2 Quest",Content=Runtime.BloxRaceV2Status}) end)
                end
            end

            -- Every normal race uses the Alchemist's flower quest. Draco uses its own
            -- Third Sea Dragon Wizard / Fire Flower progression.
            Runtime.BloxFns.BloxInventoryItemCount = function(WantedName)
                local Wanted=string.lower(tostring(WantedName or ""))
                if Wanted=="" then return 0 end
                local Ok,Inventory=QueryRemote(BloxCommF(),"getInventory")
                if not Ok or type(Inventory)~="table" then return 0 end
                local Total=0
                local Seen={}
                local function Scan(Node,Depth,KeyHint)
                    if Depth>7 then return end
                    if type(Node)~="table" then
                        if type(KeyHint)=="string" and string.lower(KeyHint)==Wanted and tonumber(Node) then
                            Total=math.max(Total,tonumber(Node) or 0)
                        end
                        return
                    end
                    if Seen[Node] then return end
                    Seen[Node]=true
                    local Nested=Node.ItemData or Node.Data or Node.Info
                    local Name=Node.Name or Node.name or Node.ItemName or Node.itemName or Node.DisplayName or Node.Item
                    if not Name and type(Nested)=="table" then Name=Nested.Name or Nested.name or Nested.ItemName end
                    local Count=tonumber(Node.Count or Node.Amount or Node.Quantity or Node.Owned or Node.Stack or Node.Value)
                    if not Count and type(Nested)=="table" then
                        Count=tonumber(Nested.Count or Nested.Amount or Nested.Quantity or Nested.Owned or Nested.Stack or Nested.Value)
                    end
                    if Name and string.lower(tostring(Name))==Wanted then
                        Total=math.max(Total,math.max(1,math.floor(Count or 1)))
                    end
                    for K,V in pairs(Node) do
                        if type(K)=="string" and string.lower(K)==Wanted and tonumber(V) then
                            Total=math.max(Total,tonumber(V) or 0)
                        end
                        if type(V)=="table" then Scan(V,Depth+1,K) end
                    end
                end
                Scan(Inventory,0,nil)
                return math.floor(Total)
            end

            Runtime.BloxFns.DracoV2Step = function()
                if BloxLevel()<2000 then
                    Runtime.BloxFns.SetRaceV2Status("Draco V2 • reach level 2000 first")
                    return
                end
                if Runtime.BloxFns.CurrentSeaName()~="Sea 3" then
                    Runtime.BloxFns.SetRaceV2Status("Draco V2 • requires Third Sea")
                    return
                end
                local DragonRemote=ReplicatedStorage:FindFirstChild("RF/InteractDragonQuest",true)
                if not DragonRemote or not DragonRemote:IsA("RemoteFunction") then
                    Runtime.BloxFns.SetRaceV2Status("DRACO_V2_REMOTE_MISSING • Dragon Wizard quest is not replicated")
                    return
                end

                local FireCount=Runtime.BloxFns.BloxInventoryItemCount("Fire Flower")
                if FireCount>=5 then
                    Runtime.BloxFns.SetRaceV2Status("Draco V2 • 5/5 Fire Flowers • returning to Dragon Wizard")
                    if not GoBloxNPC("Dragon Wizard") then
                        ProfileTravelToCFrame(CFrame.new(5814.43,1208.33,884.58))
                    end
                    task.wait(0.20)
                    local Ok,Result=pcall(function()
                        return DragonRemote:InvokeServer({NPC="Dragon Wizard",Command="Upgrade"})
                    end)
                    if Ok and Result~=false then
                        Runtime.BloxFns.SetRaceV2Status("Draco V2 turn-in sent ✓")
                        Runtime.SetFlagValue("GameProfile_Blox_RaceV2Quest",false)
                    else
                        Runtime.BloxFns.SetRaceV2Status("Draco V2 • turn-in not confirmed • need $1,000,000 or quest completion")
                    end
                    return
                end

                pcall(function() DragonRemote:InvokeServer({NPC="Dragon Wizard",Command="Upgrade"}) end)
                local Flower=Runtime.BloxFns.BloxFindFireFlower()
                if Flower then
                    Runtime.BloxFns.SetRaceV2Status("Draco V2 • Fire Flowers "..FireCount.."/5 • collecting spawned Fire Flower")
                    TouchObject(Flower)
                    return
                end

                Runtime.BloxFns.SetRaceV2Status("Draco V2 • Fire Flowers "..FireCount.."/5 • farming Third Sea NPCs")
                local Enemy=NearestBloxEnemy("Nearest Enemy",false,true)
                if Enemy then
                    FarmBloxEnemy(Enemy)
                else
                    local Spawn=FindBloxSpawn("Forest Pirate")
                    ProfileTravelToCFrame(Spawn and (Spawn*CFrame.new(0,14,0)) or CFrame.new(-13274,332,-7626))
                end
            end

            Runtime.BloxRaceV2Step=function()
                local Race=string.lower(Runtime.BloxFns.BloxCurrentRace())
                if string.find(Race,"draco",1,true) then
                    Runtime.BloxFns.DracoV2Step()
                    return
                end

                if BloxLevel()<850 then
                    Runtime.BloxFns.SetRaceV2Status("V2 Quest • reach level 850 first")
                    return
                end
                if Runtime.BloxFns.CurrentSeaName()~="Sea 2" then
                    Runtime.BloxFns.SetRaceV2Status("V2 Quest • normal races require Second Sea")
                    return
                end
                if (tonumber(Runtime.BloxFns.BloxDataValue("RaceLevel",0)) or 0)>=2 then
                    Runtime.BloxFns.SetRaceV2Status("V2 already owned • "..Runtime.BloxFns.BloxCurrentRace())
                    Runtime.SetFlagValue("GameProfile_Blox_RaceV2Quest",false)
                    return
                end

                -- Complete the Colosseum/Bartilo prerequisite automatically first.
                local ProgressCache=Runtime.BloxV2ProgressCache
                if not ProgressCache or os.clock()-ProgressCache.At>1.5 then
                    local BartiloOK,BartiloProgress=QueryRemote(BloxCommF(),"BartiloQuestProgress","Bartilo")
                    local AlchemistOK,AlchemistProgress=QueryRemote(BloxCommF(),"Alchemist","1")
                    ProgressCache={At=os.clock(),BartiloOK=BartiloOK,Bartilo=BartiloProgress,AlchemistOK=AlchemistOK,Alchemist=AlchemistProgress}
                    Runtime.BloxV2ProgressCache=ProgressCache
                end
                local BartiloOK,BartiloProgress=ProgressCache.BartiloOK,ProgressCache.Bartilo
                local BartiloStage=BartiloOK and tonumber(BartiloProgress) or nil
                if BartiloStage and BartiloStage<3 then
                    Runtime.BloxRaceV2Standby=false
                    Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                    Runtime.BloxFns.SetRaceV2Status("V2 prerequisite • completing Bartilo / Colosseum quest")
                    Runtime.BloxFns.BartiloThirdSeaStep()
                    return
                end

                local Ok,Progress=ProgressCache.AlchemistOK,ProgressCache.Alchemist
                local Stage=Ok and tonumber(Progress) or nil
                if Stage==2 then
                    Runtime.BloxRaceV2Standby=false
                    Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                    Runtime.BloxFns.SetRaceV2Status("All flowers collected • returning to Alchemist")
                    GoBloxNPC("Alchemist")
                    local FinishOK,FinishResult=QueryRemote(BloxCommF(),"Alchemist","3")
                    task.wait(0.35)
                    local CheckOK,CheckProgress=QueryRemote(BloxCommF(),"Alchemist","1")
                    Runtime.BloxV2ProgressCache=nil
                    local CheckedStage=tonumber(CheckProgress)
                    local RaceLevel=tonumber(Runtime.BloxFns.BloxDataValue("RaceLevel",0)) or 0
                    local Completed=RaceLevel>=2 or (CheckOK and ((CheckedStage and CheckedStage>2)
                        or string.find(string.lower(tostring(CheckProgress or "")),"complete",1,true)))
                    if FinishOK and FinishResult~=false and Completed then
                        Runtime.BloxFns.SetRaceV2Status("V2 quest completed ✓ • "..Runtime.BloxFns.BloxCurrentRace())
                        Runtime.SetFlagValue("GameProfile_Blox_RaceV2Quest",false)
                    else
                        Runtime.BloxFns.SetRaceV2Status("V2 turn-in not confirmed • need $500,000")
                    end
                    return
                elseif Stage==0 then
                    Runtime.BloxRaceV2Standby=false
                    Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                    Runtime.BloxFns.SetRaceV2Status("Accepting Alchemist flower quest")
                    GoBloxNPC("Alchemist")
                    QueryRemote(BloxCommF(),"Alchemist","2")
                    Runtime.BloxV2ProgressCache=nil
                    task.wait(0.35)
                    return
                elseif not Stage then
                    Runtime.BloxRaceV2Standby=false
                    Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                    Runtime.BloxFns.SetRaceV2Status("V2 progress unavailable • moving to Alchemist")
                    GoBloxNPC("Alchemist")
                    return
                end

                if not Runtime.BloxFns.BloxHasFlower(1) then
                    local F=Runtime.BloxFns.BloxFindFlower(1)
                    if F then
                        Runtime.BloxRaceV2Standby=false
                        Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                        Runtime.BloxFns.SetRaceV2Status("Collecting Blue Flower")
                        TouchObject(F)
                    else
                        Runtime.BloxRaceV2Standby=true
                        Runtime.BloxFns.SetRaceV2Status("Standby • Blue Flower not spawned yet • other features can run")
                        Runtime.BloxControllerAPI.Release("GameProfile_Blox_RaceV2Quest")
                    end
                    return
                end
                if not Runtime.BloxFns.BloxHasFlower(2) then
                    local F=Runtime.BloxFns.BloxFindFlower(2)
                    if F then
                        Runtime.BloxRaceV2Standby=false
                        Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                        Runtime.BloxFns.SetRaceV2Status("Collecting Red Flower")
                        TouchObject(F)
                    else
                        Runtime.BloxRaceV2Standby=true
                        Runtime.BloxFns.SetRaceV2Status("Standby • Red Flower not spawned yet • other features can run")
                        Runtime.BloxControllerAPI.Release("GameProfile_Blox_RaceV2Quest")
                    end
                    return
                end
                if not Runtime.BloxFns.BloxHasFlower(3) then
                    local GroundYellow=Runtime.BloxFns.BloxFindFlower(3)
                    Runtime.BloxRaceV2Standby=false
                    Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                    if GroundYellow then
                        Runtime.BloxFns.SetRaceV2Status("Collecting Yellow Flower")
                        TouchObject(GroundYellow)
                    else
                        -- Yellow Flower is an NPC drop, so unlike Blue/Red it must be farmed when
                        -- no physical Flower3 is already on the ground.
                        Runtime.BloxFns.SetRaceV2Status("Farming Yellow Flower • Second Sea NPC drop")
                        local E=NearestBloxEnemy("Swan Pirate",false,true)
                        if E then FarmBloxEnemy(E)
                        else
                            local Spawn=FindBloxSpawn("Swan Pirate")
                            ProfileTravelToCFrame(Spawn and (Spawn*CFrame.new(0,14,0)) or CFrame.new(932.6,156.1,1180.3))
                        end
                    end
                    return
                end
                Runtime.BloxRaceV2Standby=false
                Runtime.BloxControllerAPI.Claim("GameProfile_Blox_RaceV2Quest")
                Runtime.BloxFns.SetRaceV2Status("Three flowers collected • returning to Alchemist")
                GoBloxNPC("Alchemist")
                QueryRemote(BloxCommF(),"Alchemist","3")
                Runtime.BloxV2ProgressCache=nil
            end

