            Runtime.BloxFns.BloxMaterialRoute = function(Material)
                local SeaRoutes=Runtime.BloxFns.BloxMaterialRoutes[BloxSeaNumber()] or {}
                if SeaRoutes[Material] then return SeaRoutes[Material] end

                local Wanted=CompactEnemyName(Material)
                for Name,Route in pairs(SeaRoutes) do
                    if CompactEnemyName(Name)==Wanted then
                        State.BloxMaterial=Name
                        return Route
                    end
                end
                return nil
            end
            Runtime.BloxFns.BloxMaterialNames = function()
                local O={}
                for Name in pairs(Runtime.BloxFns.BloxMaterialRoutes[BloxSeaNumber()] or {}) do table.insert(O,Name) end
                table.sort(O)
                return O
            end
            Runtime.BloxFns.EnsureValidMaterialSelection = function()
                local Route=Runtime.BloxFns.BloxMaterialRoute(State.BloxMaterial)
                if Route then return Route end
                local Names=Runtime.BloxFns.BloxMaterialNames()
                if #Names>0 then State.BloxMaterial=Names[1] end
                return Runtime.BloxFns.BloxMaterialRoute(State.BloxMaterial)
            end
            Runtime.BloxFns.MaterialSourceText = function(Name)
                local Route=Runtime.BloxFns.BloxMaterialRoute(Name)
                local L=Route and Route.Enemies or {}
                return #L>0 and table.concat(L,", ") or "Not available in this sea"
            end
            function Runtime.BloxMaterialEnemyNameMatches(ModelName,WantedName)
                if TargetNameMatches(ModelName,WantedName,false) or TargetNameMatches(ModelName,WantedName,true) then return true end
                local Actual=CompactEnemyName(ModelName)
                local Wanted=CompactEnemyName(WantedName)
                if Actual=="posessedmummy" then Actual="possessedmummy" end
                if Wanted=="posessedmummy" then Wanted="possessedmummy" end

                if #Actual>=6 and #Wanted>=6 and (string.find(Actual,Wanted,1,true) or string.find(Wanted,Actual,1,true)) then return true end
                return false
            end
            Runtime.BloxFns.BestLiveMaterialEnemy = function(Material,Force)
                local Route=Runtime.BloxFns.BloxMaterialRoute(Material)
                if not Route then return nil end
                local Me=Root()
                local Best,BestDist=nil,math.huge
                for _,E in ipairs(BloxLiveEnemies(Force)) do
                    local H=E:FindFirstChildOfClass("Humanoid")
                    local R=GetRoot(E)
                    if H and H.Health>0 and R then
                        local Matches=false
                        for _,EnemyName in ipairs(Route.Enemies or {}) do
                            if Runtime.BloxMaterialEnemyNameMatches(E.Name,EnemyName) then Matches=true; break end
                        end
                        if Matches then
                            local D=Me and (R.Position-Me.Position).Magnitude or 0
                            if D<BestDist then Best,BestDist=E,D end
                        end
                    end
                end
                return Best
            end
            Runtime.BloxFns.BloxMaterialDirectTravel = function(CF)
                if typeof(CF)~="CFrame" then return false end
                local Me=Root()
                if not Me then return false end
                if (Me.Position-CF.Position).Magnitude<=5 then return true end

                local Mode="Smooth Tween"
                local Distance=(Me.Position-CF.Position).Magnitude
                if Distance>90 then
                    local CruiseY=math.max(Me.Position.Y,CF.Position.Y,85)
                    local Lift=CFrame.new(Me.Position.X,CruiseY,Me.Position.Z)*Me.CFrame.Rotation
                    local Across=CFrame.new(CF.Position.X,CruiseY,CF.Position.Z)*CF.Rotation
                    if Me.Position.Y<CruiseY-3 and not Runtime.ProfileRouter.Direct(Lift,Mode,nil,"BloxMaterialFarm") then return false end
                    if not Runtime.ProfileRouter.Direct(Across,Mode,nil,"BloxMaterialFarm") then return false end
                end
                return Runtime.ProfileRouter.Direct(CF,Mode,nil,"BloxMaterialFarm")
            end

            Runtime.BloxFns.GoMaterialSource = function(Material)
                local Route=Runtime.BloxFns.BloxMaterialRoute(Material)
                if not Route then
                    Runtime.BloxCombatLastResult="Material not available in this sea"
                    return false
                end

                local Me=Root()
                if not Me then return false end

                if Route.Entrance and (Me.Position-Route.Position.Position).Magnitude>(Route.EntranceThreshold or 2500) then
                    Runtime.BloxCombatLastResult="Material farm • entering shortcut for "..tostring(Material)
                    RequestBloxEntrance(Route.Entrance,"Material:"..tostring(Material))
                    task.wait(0.25)
                    BloxEnemySnapshotState.At=0
                    Me=Root() or Me
                end

                if Material=="Ectoplasm" and BloxSeaNumber()==2 then
                    Me=Root()
                    local Inside=Me and Runtime.IsBloxCursedShipInteriorPosition(Me.Position)
                    if not Inside then
                        RequestBloxEntrance(Runtime.BloxCursedShipEntrance,"Ectoplasm:CursedShip")
                        task.wait(0.30)
                        BloxEnemySnapshotState.At=0
                        Me=Root()
                        Inside=Me and Runtime.IsBloxCursedShipInteriorPosition(Me.Position)
                    end
                    if not Inside then
                        Runtime.BloxCombatLastResult="Material farm • waiting for Cursed Ship entrance"
                        return false
                    end
                    local Live=Runtime.BloxFns.BestLiveMaterialEnemy(Material,true)
                    if Live and GetRoot(Live) then
                        local Hover=BloxHoverCFrame(GetRoot(Live))
                        if Hover then return Runtime.BloxFns.BloxMaterialDirectTravel(Hover) end
                    end
                    return Runtime.BloxFns.BloxMaterialDirectTravel(Runtime.BloxCursedShipDeckhand*CFrame.new(0,18,0))
                end

                Me=Root()
                if Me and (Me.Position-Route.Position.Position).Magnitude>700 then
                    Runtime.BloxCombatLastResult="Material farm • traveling to "..tostring(Material).." area"
                    local Reached=Runtime.BloxFns.BloxMaterialDirectTravel(Route.Position*CFrame.new(0,20,0))
                    BloxEnemySnapshotState.At=0
                    if Reached then task.wait(0.15) end
                end

                local E=Runtime.BloxFns.BestLiveMaterialEnemy(Material,true)
                if E and GetRoot(E) then
                    local Hover=BloxHoverCFrame(GetRoot(E))
                    if Hover then return Runtime.BloxFns.BloxMaterialDirectTravel(Hover) end
                end

                for _,EnemyName in ipairs(Route.Enemies or {}) do
                    local Spawn=FindBloxSpawn(EnemyName)
                    local SR=Spawn and GetRoot(Spawn)
                    if SR then return Runtime.BloxFns.BloxMaterialDirectTravel(SR.CFrame*CFrame.new(0,20,0)) end
                    local Q=QuestForEnemy(EnemyName,false)
                    if Q and Q.MobPosition then return Runtime.BloxFns.BloxMaterialDirectTravel(Q.MobPosition*CFrame.new(0,20,0)) end
                    local Known=StaticBloxTargetCFrame(EnemyName,false) or ReplicatedBloxTargetCFrame(EnemyName,false)
                    if Known then return Runtime.BloxFns.BloxMaterialDirectTravel(Known*CFrame.new(0,20,0)) end
                end
                return Runtime.BloxFns.BloxMaterialDirectTravel(Route.Position*CFrame.new(0,20,0))
            end
            Runtime.BloxFns.MaterialFarmStep = function()
                local Route=Runtime.BloxFns.EnsureValidMaterialSelection()
                if not Route then return end
                local E=Runtime.BloxFns.BestLiveMaterialEnemy(State.BloxMaterial,true)
                if E then
                    Runtime.BloxCombatLastResult="Material farm • "..tostring(State.BloxMaterial).." • fighting "..StripEnemyName(E.Name)
                    FarmBloxEnemy(E)
                    BloxEnemySnapshotState.At=0
                    return
                end
                Runtime.BloxCombatLastResult="Material farm • locating "..tostring(State.BloxMaterial).." source"
                Runtime.BloxFns.GoMaterialSource(State.BloxMaterial)

                BloxEnemySnapshotState.At=0
                local ArrivedEnemy=Runtime.BloxFns.BestLiveMaterialEnemy(State.BloxMaterial,true)
                if ArrivedEnemy then FarmBloxEnemy(ArrivedEnemy) end
            end

