            Runtime.BloxBaitCatalog={
                ["Basic Bait"]={Money=1000,Yield=10,Sea=0,Trust=0,Seller="Fisherman",Location="current sea Fisherman"},
                ["Kelp Bait"]={Money=12000,Yield=10,Sea=1,Trust=3,Seller="Angler",Location="Skylands lower docks"},
