            function Runtime.BloxBaitInfo(Name)
                return Runtime.BloxBaitCatalog[tostring(Name or "")] or Runtime.BloxBaitCatalog["Basic Bait"]
            end
            Runtime.BloxBestBaitOrder={
                "Carnivore Bait","Epic Bait","Frozen Bait","Abyssal Bait","Good Bait","Kelp Bait","Basic Bait"
            }
            function Runtime.BloxFishingBaitCounts()
                local R=Runtime.BloxFns.BloxFishingRemotes()
                if not R.Jobs then return {},false end
                local Ok,Inventory=pcall(function() return R.Jobs:InvokeServer("getInventory") end)
                if not Ok or type(Inventory)~="table" then return {},false end
                local Counts={}
                local Lookup={}
                for _,Bait in ipairs(Runtime.BloxBestBaitOrder) do
                    Counts[Bait]=0
                    Lookup[string.lower(Bait)]=Bait
                end
                local Seen={}
                local function Record(Name,Count)
                    local Canon=Lookup[string.lower(tostring(Name or ""))]
                    if not Canon then return end
                    local N=tonumber(Count) or 1
                    Counts[Canon]=math.max(Counts[Canon] or 0,math.max(0,math.floor(N)))
                end
                local function Scan(Node,Depth,KeyHint)
                    if Depth>6 then return end
                    if type(Node)~="table" then
                        if type(KeyHint)=="string" and tonumber(Node) then Record(KeyHint,Node) end
                        return
                    end
                    if Seen[Node] then return end
                    Seen[Node]=true
                    local Name=Node.Name or Node.name or Node.ItemName or Node.itemName or Node.DisplayName or Node.Item
                    local Nested=Node.ItemData or Node.Data or Node.Info
                    if not Name and type(Nested)=="table" then Name=Nested.Name or Nested.name or Nested.ItemName end
                    local Count=tonumber(Node.Count or Node.Amount or Node.Quantity or Node.Owned or Node.Stack or Node.Value)
                    if not Count and type(Nested)=="table" then
                        Count=tonumber(Nested.Count or Nested.Amount or Nested.Quantity or Nested.Owned or Nested.Stack or Nested.Value)
                    end
                    if Name then Record(Name,Count or 1) end
                    for K,V in pairs(Node) do
                        if type(K)=="string" and tonumber(V) then Record(K,V) end
                        if type(V)=="table" then Scan(V,Depth+1,K) end
                    end
                end
                Scan(Inventory,0,nil)
                return Counts,true
            end
            function Runtime.BloxSelectBestOwnedBait(Force)
                local Now=os.clock()
                if not Force and Now-(Runtime.BloxBestBaitCheckAt or -math.huge)<2.5 then
                    return tostring(State.BloxFishingBait or "Basic Bait"),true
                end
                Runtime.BloxBestBaitCheckAt=Now
                local Counts,Readable=Runtime.BloxFishingBaitCounts()
                if not Readable then return tostring(State.BloxFishingBait or "Basic Bait"),false end
                local Best=nil
                local BestCount=0
                for _,Bait in ipairs(Runtime.BloxBestBaitOrder) do
                    local Count=tonumber(Counts[Bait]) or 0
                    if Count>0 then Best=Bait; BestCount=Count; break end
                end
                if not Best then
                    Runtime.BloxFishingStatus="No bait found - use Buy / Restock Bait"
                    return nil,true
                end
                local Changed=tostring(State.BloxFishingBait or "")~=Best
                State.BloxFishingBait=Best
                if Changed then
                    Runtime.BloxFishingSetupAt=0
                    Runtime.BloxFishingSetupBait=nil
                    Runtime.BloxFishingLastCast=-math.huge
                end
                local R=Runtime.BloxFns.BloxFishingRemotes()
                if R.Jobs then pcall(function() R.Jobs:InvokeServer("LoadItem",Best,{"Usables"}) end) end
                Runtime.BloxBestBaitName=Best
                Runtime.BloxBestBaitCount=BestCount
                if Changed or Force then Runtime.BloxFishingStatus="Best bait equipped • "..Best.." x"..tostring(BestCount) end
                return Best,true
            end
            function Runtime.BloxFishingInventoryCount(ItemName)
                local R=Runtime.BloxFns.BloxFishingRemotes()
                if not R.Jobs then return 0,false end
                local Ok,Inventory=pcall(function() return R.Jobs:InvokeServer("getInventory") end)
                if not Ok or type(Inventory)~="table" then return 0,false end
                local Wanted=string.lower(tostring(ItemName or ""))
                local Seen={}
                local Best=0
                local function Scan(Node,Depth,KeyHint)
                    if Depth>5 then return end
                    if type(Node)~="table" then
                        if type(KeyHint)=="string" and string.lower(KeyHint)==Wanted and tonumber(Node) then
                            Best=math.max(Best,tonumber(Node) or 0)
                        end
                        return
                    end
                    if Seen[Node] then return end
                    Seen[Node]=true
                    local Name=Node.Name or Node.name or Node.ItemName or Node.itemName or Node.DisplayName or Node.Item
                    local Nested=Node.ItemData or Node.Data or Node.Info
                    if not Name and type(Nested)=="table" then Name=Nested.Name or Nested.name or Nested.ItemName end
                    if Name and string.lower(tostring(Name))==Wanted then
                        local Count=tonumber(Node.Count or Node.Amount or Node.Quantity or Node.Owned or Node.Stack or Node.Value)
                        if not Count and type(Nested)=="table" then
                            Count=tonumber(Nested.Count or Nested.Amount or Nested.Quantity or Nested.Owned or Nested.Stack or Nested.Value)
                        end
                        Best=math.max(Best,Count or 1)
                    end
                    for K,V in pairs(Node) do
                        if type(K)=="string" and string.lower(K)==Wanted and tonumber(V) then Best=math.max(Best,tonumber(V) or 0) end
                        if type(V)=="table" then Scan(V,Depth+1,K) end
                    end
                end
                Scan(Inventory,0,nil)
                return math.max(0,math.floor(Best)),true
            end
            function Runtime.BloxBaitCostText(Name,Target,Current)
                local Info=Runtime.BloxBaitInfo(Name)
                Target=math.clamp(math.floor(tonumber(Target) or 50),1,99)
                Current=math.max(0,math.floor(tonumber(Current) or 0))
                local Need=math.max(0,Target-Current)
                local Bundles=math.ceil(Need/(Info.Yield or 10))
                local Final=math.min(99,Current+Bundles*(Info.Yield or 10))
                local TotalMoney=Bundles*(Info.Money or 0)
                local Extra=""
                if Info.Material then Extra=" + "..tostring(Bundles*(Info.MaterialCount or 1)).." "..Info.Material end
                local SeaText=Info.Sea==0 and "all seas" or ("Sea "..tostring(Info.Sea))
                return string.format("%s • %s • 10 per bundle • $%s each • have %d / target %d • buy %d bundle%s = $%s%s • trust %d • %s",
                    tostring(Info.Seller or "Seller"),tostring(Info.Location or SeaText),tostring(Info.Money or 0),Current,Target,Bundles,Bundles==1 and "" or "s",tostring(TotalMoney),Extra,Info.Trust or 0,SeaText)
            end

