            function Runtime.BloxFishingSellerAnchor(SellerName,Sea)
                local Fixed={
                    Fisherman={
                        [1]=CFrame.new(1347.8068,104.6681,-1319.7371),
                        [2]=CFrame.new(-11.3114,29.2762,2762.5220),
                        [3]=CFrame.new(-300.5775,43.7557,5442.0830),
                    },
                    Angler={
                        [1]=CFrame.new(-4607.8228,872.5425,-1667.5569),
                        [2]=CFrame.new(-2273.1682,72.9919,-2722.4536),
                        [3]=CFrame.new(5229.9956,603.9166,345.1540),
                    }
                }
                local G=Fixed[tostring(SellerName or "Fisherman")]
                return G and G[tonumber(Sea) or BloxSeaNumber()] or nil
            end
            function Runtime.BloxFindExactFishingSeller(SellerName,Anchor)
                SellerName=tostring(SellerName or "Fisherman")
                local Wanted=NormalName(SellerName)
                local BestModel,BestCF,BestDist=nil,nil,math.huge
                local function Consider(Obj,CF)
                    if not CF then return end
                    local D=Anchor and (CF.Position-Anchor.Position).Magnitude or 0
                    if D<BestDist then BestModel,BestCF,BestDist=Obj,CF,D end
                end

                for _,FolderName in ipairs({"NPCs","Npcs","QuestNPCs"}) do
                    local Folder=workspace:FindFirstChild(FolderName)
                    if Folder then
                        for _,Obj in ipairs(Folder:GetDescendants()) do
                            if Obj:IsA("Model") and NormalName(Obj.Name)==Wanted then
                                local RR=GetRoot(Obj)
                                if RR then Consider(Obj,RR.CFrame) end
                            end
                        end
                    end
                end

                if not BestCF then
                    for _,Obj in ipairs(Runtime.ProfileTargets()) do
                        if Obj:IsA("Model") and NormalName(Obj.Name)==Wanted then
                            local RR=GetRoot(Obj)
                            if RR then Consider(Obj,RR.CFrame) end
                        end
                    end
                end

                if not BestCF then
                    local Guide=BloxGuide()
                    local List=Guide and Guide.Data and Guide.Data.NPCList
                    if type(List)=="table" then
                        for _,Entry in pairs(List) do
                            if type(Entry)=="table" then
                                local Name=tostring(Entry.NPCName or Entry.Name or "")
                                local Pos=Entry.CFrame or Entry.Position
                                if typeof(Pos)=="Vector3" then Pos=CFrame.new(Pos) end
                                if NormalName(Name)==Wanted and typeof(Pos)=="CFrame" then Consider(nil,Pos) end
                            end
                        end
                    end
                end

                if Anchor and BestCF and BestDist>2200 then return nil,nil end
                return BestModel,BestCF
            end
            function Runtime.BloxOpenFishingSeller(Model)
                if not Model then return false end
                local Prompt=nil
                for _,Obj in ipairs(Model:GetDescendants()) do
                    if Obj:IsA("ProximityPrompt") and Obj.Enabled then Prompt=Obj break end
                end
                if Prompt and type(fireproximityprompt)=="function" then
                    pcall(function() fireproximityprompt(Prompt) end)
                    task.wait(0.25)
                    return true
                end
                return false
            end
            function Runtime.BloxGoBaitSeller()
                local Bait=tostring(State.BloxFishingRestockBait or State.BloxFishingBait or "Basic Bait")
                local Spec=Runtime.BloxBaitSellerSpec(Bait)
                local Sea=BloxSeaNumber()
                if Spec.Sea~=0 and Spec.Sea~=Sea then
                    Runtime.BloxFishingStatus=Bait.." is sold by the Sea "..tostring(Spec.Sea).." Angler"
                    BloxFail("BAIT_WRONG_SEA",Runtime.BloxFishingStatus)
                    return false
                end
                local Anchor=Runtime.BloxFishingSellerAnchor(Spec.Seller,Sea)
                if not Anchor then
                    Runtime.BloxFishingStatus="No seller area for "..Bait
                    BloxFail("BAIT_SELLER_ROUTE_MISSING",Runtime.BloxFishingStatus)
                    return false
                end
                local Place=(Spec.Location and Spec.Location[Sea]) or Spec.Seller
                Runtime.BloxFishingStatus="Going to "..Spec.Seller.." • "..tostring(Place)
                local Me=Root()
                if not Me or (Me.Position-Anchor.Position).Magnitude>850 then
                    ProfileTravelToCFrame(Anchor*CFrame.new(0,4,0))
                    task.wait(0.55)
                end
                local Model,ExactCF=Runtime.BloxFindExactFishingSeller(Spec.Seller,Anchor)
                if not ExactCF then
                    Runtime.BloxFishingStatus="Could not resolve exact "..Spec.Seller.." at "..tostring(Place)
                    BloxFail("BAIT_SELLER_MISSING",Runtime.BloxFishingStatus)
                    return false
                end
                Runtime.BloxFishingStatus="Found exact "..Spec.Seller.." • moving to NPC"
                local Arrived=ProfileTravelToCFrame(ExactCF*CFrame.new(0,2,4))
                task.wait(0.25)
                if Model then Runtime.BloxOpenFishingSeller(Model) end
                Runtime.BloxLastBaitSeller={Bait=Bait,Seller=Spec.Seller,Sea=Sea,At=os.clock(),Model=Model,CFrame=ExactCF}
                Runtime.BloxFishingStatus="At exact "..Spec.Seller.." • "..tostring(Place).." • "..Bait
                if Arrived~=false then BloxClearFailure() else BloxFail("BAIT_SELLER_ROUTE_FAILED",Runtime.BloxFishingStatus) end
                return Arrived~=false
            end
            function Runtime.BloxBuyBaitToTarget(Target)
                local R=Runtime.BloxFns.BloxFishingRemotes()
                if not R.Jobs then
                    Runtime.BloxFishingStatus="Fishing jobs remote not loaded"
                    BloxFail("FISHING_REMOTE_MISSING",Runtime.BloxFishingStatus)
                    return false
                end
                if not R.Craft then
                    Runtime.BloxFishingStatus="Bait craft remote not loaded"
                    BloxFail("BAIT_REMOTE_MISSING",Runtime.BloxFishingStatus)
                    return false
                end
                local Bait=tostring(State.BloxFishingRestockBait or State.BloxFishingBait or "Basic Bait")
                local Info=Runtime.BloxBaitInfo(Bait)
                local Sea=BloxSeaNumber()
                if Info.Sea~=0 and Info.Sea~=Sea then
                    Runtime.BloxFishingStatus=Bait.." requires the Sea "..tostring(Info.Sea).." Angler"
                    BloxFail("BAIT_WRONG_SEA",Runtime.BloxFishingStatus)
                    return false
                end
                Target=math.clamp(math.floor(tonumber(Target) or 50),1,99)
                local Before,Readable=Runtime.BloxFishingInventoryCount(Bait)
                if Readable and Before>=Target then
                    pcall(function() R.Jobs:InvokeServer("LoadItem",Bait,{"Usables"}) end)
                    Runtime.BloxFishingStatus=Bait.." already has "..tostring(Before)
                    BloxClearFailure()
                    return true
                end

                local Need=math.max(0,Target-(Readable and Before or 0))
                local Bundles=math.max(1,math.ceil(Need/(Info.Yield or 10)))
                local TotalCost=Bundles*(Info.Money or 0)
                local Data=Player:FindFirstChild("Data")
                local Beli=Data and (Data:FindFirstChild("Beli") or Data:FindFirstChild("Money"))
                if Beli and tonumber(Beli.Value) and tonumber(Beli.Value)<TotalCost then
                    Runtime.BloxFishingStatus="Need $"..tostring(TotalCost).." for "..tostring(Bundles).." bundle(s) of "..Bait
                    BloxFail("BAIT_FUNDS",Runtime.BloxFishingStatus)
                    return false
                end

                local Recent=Runtime.BloxLastBaitSeller
                if not Recent or Recent.Bait~=Bait or Recent.Sea~=Sea or os.clock()-(Recent.At or 0)>15 then
                    if not Runtime.BloxGoBaitSeller() then return false end
                else
                    local Me=Root()
                    if not Me or not Recent.CFrame or (Me.Position-Recent.CFrame.Position).Magnitude>35 then
                        if not Runtime.BloxGoBaitSeller() then return false end
                    end
                end

                pcall(function() R.Jobs:InvokeServer("FishingNPC","FirstTimeFreeRod") end)
                if Runtime.BloxLastBaitSeller and Runtime.BloxLastBaitSeller.Model then
                    Runtime.BloxOpenFishingSeller(Runtime.BloxLastBaitSeller.Model)
                end
                task.wait(0.35)
                local StartCount=Readable and Before or 0
                Runtime.BloxFishingStatus="Buying "..Bait.." • "..tostring(Bundles).." bundle(s) • $"..tostring(TotalCost)
                local Sent=0
                local LastResult=nil
                for Index=1,Bundles do
                    local Ok,Result=pcall(function() return R.Craft:InvokeServer("Craft",Bait) end)
                    LastResult=Result
                    if Ok then Sent=Sent+1 end
                    task.wait(2.05)
                    local Count,CanRead=Runtime.BloxFishingInventoryCount(Bait)
                    if CanRead then
                        Runtime.BloxFishingStatus="Buying "..Bait.." • "..tostring(Count).."/"..tostring(Target).." • $"..tostring(Info.Money).." per 10"
                        if Count>=Target then break end
                        if Count<=StartCount and Index==1 and Runtime.BloxLastBaitSeller and Runtime.BloxLastBaitSeller.Model then
                            Runtime.BloxOpenFishingSeller(Runtime.BloxLastBaitSeller.Model)
                        end
                    end
                end
                local After,CanRead=Runtime.BloxFishingInventoryCount(Bait)
                pcall(function() R.Jobs:InvokeServer("LoadItem",Bait,{"Usables"}) end)
                task.wait(0.2)
                Runtime.BloxFishingSetupAt=0
                Runtime.BloxFishingSetupBait=nil
                Runtime.BloxBestBaitCheckAt=0
                task.defer(function() pcall(function() Runtime.BloxSelectBestOwnedBait(true) end) end)
                if CanRead and After>StartCount then
                    Runtime.BloxFishingStatus="Bought + loaded "..Bait.." • "..tostring(After).." bait"
                    BloxClearFailure()
                    return true
                end
                if CanRead and After>=Target then
                    Runtime.BloxFishingStatus="Bait ready • "..Bait.." x"..tostring(After)
                    BloxClearFailure()
                    return true
                end
                if not CanRead and Sent>0 then
                    Runtime.BloxFishingStatus="Purchase sent at exact "..tostring(Info.Seller).." • inventory unreadable"
                    BloxClearFailure()
                    return true
                end
                Runtime.BloxFishingStatus="Purchase failed at "..tostring(Info.Seller).." • check trust/material requirements"..(LastResult~=nil and (" • "..tostring(LastResult)) or "")
                BloxFail("BAIT_PURCHASE_FAILED",Runtime.BloxFishingStatus)
                return false
            end -- v5.14.17: keep late Blox helpers on Runtime instead of branch-scope locals.
            -- Luau has a hard local-register ceiling; the old monolithic Blox branch
            -- reached it at PlayerOwnsNamedItem before the UI could finish compiling.
            Runtime.BloxFindFishingRod = function()
                local Wanted=tostring(State.BloxFishingRod or "Fishing Rod")
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        local Exact=Container:FindFirstChild(Wanted)
                        if Exact and Exact:IsA("Tool") then return Exact end
                        for _,Tool in ipairs(Container:GetChildren()) do
                            if Tool:IsA("Tool") and string.find(string.lower(Tool.Name),"rod",1,true) then return Tool end
                        end
                    end
                end
                return nil
            end
            Runtime.BloxEnsureFishingSetup = function(Force)
                local R=Runtime.BloxFns.BloxFishingRemotes()
                if not R.Jobs then
                    Runtime.BloxFishingStatus="Fishing jobs remote not loaded"
                    BloxFail("FISHING_REMOTE_MISSING",Runtime.BloxFishingStatus)
                    return false
                end

                if Runtime.BloxAutoFishActive or Force then Runtime.BloxSelectBestOwnedBait(Force) end
                local WantedBait=tostring(State.BloxFishingBait or "Basic Bait")
                local WantedRod=tostring(State.BloxFishingRod or "Fishing Rod")
                local Rod=Runtime.BloxFindFishingRod()
                local Data=Player:FindFirstChild("Data")
                local FishingData=Data and Data:FindFirstChild("FishingData")
                local Selected=FishingData and FishingData:GetAttribute("SelectedBait")

                if not Force and Rod
                    and Runtime.BloxFishingSetupBait==WantedBait
                    and Runtime.BloxFishingSetupRod==WantedRod then
                    return true
                end

                Runtime.BloxFishingSetupAt=os.clock()
                pcall(function() R.Jobs:InvokeServer("FishingNPC","FirstTimeFreeRod") end)
                pcall(function() R.Jobs:InvokeServer("LoadItem",State.BloxFishingRod,{"Gear"}) end)
                task.wait(0.5)

                Data=Player:FindFirstChild("Data")
                FishingData=Data and Data:FindFirstChild("FishingData")
                Selected=FishingData and FishingData:GetAttribute("SelectedBait")
                if string.lower(tostring(Selected or ""))~=string.lower(WantedBait) then
                    local HasSelected=false
                    local OkInv,Inventory=pcall(function() return R.Jobs:InvokeServer("getInventory") end)
                    if OkInv and type(Inventory)=="table" then
                        for Key,Entry in pairs(Inventory) do
                            if type(Entry)=="table" then
                                local EntryType=string.lower(tostring(Entry.Type or Entry.type or Entry.Category or Entry.ItemType or ""))
                                local EntryName=string.lower(tostring(Entry.Name or Entry.name or Entry.ItemName or Key or ""))
                                local Count=tonumber(Entry.Count or Entry.Amount or Entry.Quantity or Entry.Owned or 1) or 0
                                if (EntryType=="bait" or EntryType=="usables" or EntryType=="usable")
                                    and EntryName==string.lower(WantedBait) and Count>0 then
                                    HasSelected=true
                                    break
                                end
                            elseif type(Key)=="string" and string.lower(Key)==string.lower(WantedBait) then
                                HasSelected=true
                                break
                            end
                        end
                    end
                    if not HasSelected then
                        Runtime.BloxFishingStatus="No "..WantedBait.." loaded - use Restock Bait"
                        BloxFail("BAIT_EMPTY",Runtime.BloxFishingStatus)
                        return false
                    end
                end

                pcall(function() R.Jobs:InvokeServer("LoadItem",WantedBait,{"Usables"}) end)
                task.wait(0.15)
                Rod=Runtime.BloxFindFishingRod()
                local H=Humanoid()
                if Rod and H and Rod.Parent~=Character() then
                    pcall(function() H:EquipTool(Rod) end)
                    task.wait(0.15)
                end
                Rod=Runtime.BloxFindFishingRod()
                if Rod then
                    Runtime.BloxFishingSetupBait=WantedBait
                    Runtime.BloxFishingSetupRod=WantedRod
                    Runtime.BloxFishingStatus="Ready - "..Rod.Name.." - "..WantedBait
                    BloxClearFailure()
                    return true
                end
                Runtime.BloxFishingSetupBait=nil
                Runtime.BloxFishingSetupRod=nil
                Runtime.BloxFishingStatus="Fishing Rod not found after setup"
                BloxFail("FISHING_ROD_MISSING",Runtime.BloxFishingStatus)
                return false
            end
            Runtime.BloxFishingInvoke = function(Request,...)
                if not Request then return false,nil end
                local Args=table.pack(...)
                local Ok,Result=pcall(function()
                    if Request:IsA("RemoteFunction") then
                        return Request:InvokeServer(table.unpack(Args,1,Args.n))
                    elseif Request:IsA("RemoteEvent") then
                        Request:FireServer(table.unpack(Args,1,Args.n))
                        return true
                    end
                    return nil
                end)
                return Ok,Result
            end

            Runtime.BloxFishingCastPosition = function()
                local Me=Root()
                if not Me then return nil end
                local Distance=math.clamp(tonumber(State.BloxFishingCastDistance) or 55,20,100)
                local Origin=Me.Position+Vector3.new(0,2.5,0)
                local Params=RaycastParams.new()
                Params.FilterType=Enum.RaycastFilterType.Exclude
                local Ignore={Character()}
                local EnemyFolder=workspace:FindFirstChild("Enemies")
                if EnemyFolder then table.insert(Ignore,EnemyFolder) end
                Params.FilterDescendantsInstances=Ignore
                Params.IgnoreWater=false

                local WaterY=nil
                local Util=ReplicatedStorage:FindFirstChild("Util")
                local WaterModule=Util and Util:FindFirstChild("GetWaterHeightAtLocation")
                if WaterModule and WaterModule:IsA("ModuleScript") then
                    local Ok,GetWater=pcall(require,WaterModule)
                    if Ok and type(GetWater)=="function" then
                        local OkY,Y=pcall(GetWater,Me.Position)
                        if OkY and tonumber(Y) then WaterY=tonumber(Y) end
                    end
                end

                local Base=Me.CFrame.LookVector
                Base=Vector3.new(Base.X,0,Base.Z)
                if Base.Magnitude<0.01 then Base=Vector3.new(0,0,-1) else Base=Base.Unit end
                local Angles={0,30,-30,60,-60,90,-90,135,-135,180}
                local Fallback=nil
                for _,Deg in ipairs(Angles) do
                    local Direction=CFrame.fromAxisAngle(Vector3.yAxis,math.rad(Deg)):VectorToWorldSpace(Base)
                    local Horizontal=workspace:Raycast(Origin,Direction*Distance,Params)
                    local Candidate=Horizontal and Horizontal.Position or (Origin+Direction*Distance)
                    Fallback=Fallback or Candidate

                    local DownOrigin=Vector3.new(Candidate.X,Candidate.Y+120,Candidate.Z)
                    local Down=workspace:Raycast(DownOrigin,Vector3.new(0,-320,0),Params)
                    if Down and Down.Material==Enum.Material.Water then
                        return Down.Position+Vector3.new(0,0.15,0)
                    end
                    if WaterY and Down and Down.Position.Y<WaterY-0.5 then
                        return Vector3.new(Candidate.X,WaterY,Candidate.Z)
                    end
                end
                if WaterY and Fallback then return Vector3.new(Fallback.X,WaterY,Fallback.Z) end
                return Fallback and (Fallback-Vector3.new(0,8,0)) or nil
            end
            Runtime.BloxFishingState = function(Rod)
                if not Rod then return "Idle" end
                for _,Obj in ipairs({Rod,table.unpack(Rod:GetDescendants())}) do
                    if Obj then
                        for _,Key in ipairs({"ServerState","State","FishingState"}) do
                            local Attr=Obj:GetAttribute(Key)
                            if Attr~=nil then return tostring(Attr) end
                            local Value=Obj:FindFirstChild(Key)
                            if Value and Value:IsA("ValueBase") then return tostring(Value.Value) end
                        end
                    end
                end
                return "Idle"
            end
            Runtime.BloxFaceFishingPoint = function(Pos)
                local Me=Root()
                if not Me or not Pos then return end
                local Flat=Vector3.new(Pos.X,Me.Position.Y,Pos.Z)
                if (Flat-Me.Position).Magnitude>1 then
                    pcall(function()
                        Me.CFrame=CFrame.lookAt(Me.Position,Flat)
                        Me.AssemblyLinearVelocity=Vector3.zero
                        Me.AssemblyAngularVelocity=Vector3.zero
                    end)
                end
            end
            Runtime.BloxCastFishingLine = function()
                local R=Runtime.BloxFns.BloxFishingRemotes()
                if not R.Request then
                    Runtime.BloxFishingStatus="FishingRequest not loaded"
                    BloxFail("FISHING_REQUEST_MISSING",Runtime.BloxFishingStatus)
                    return false
                end
                local Pos=Runtime.BloxFishingCastPosition()
                if not Pos then
                    Runtime.BloxFishingStatus="Could not find a cast point"
                    BloxFail("FISHING_NO_WATER",Runtime.BloxFishingStatus)
                    return false
                end
                Runtime.BloxFaceFishingPoint(Pos)
                local OkStart=select(1,Runtime.BloxFishingInvoke(R.Request,"StartCasting"))
                if not OkStart then
                    Runtime.BloxFishingStatus="StartCasting failed"
                    BloxFail("FISHING_START_FAILED",Runtime.BloxFishingStatus)
                    return false
                end
                task.wait(0.70)
                local OkCast,Result=Runtime.BloxFishingInvoke(R.Request,"CastLineAtLocation",Pos,100,true)
                if OkCast then
                    Runtime.BloxFishingLastCast=os.clock()
                    Runtime.BloxFishingLastCastPos=Pos
                    Runtime.BloxFishingStatus="Cast sent • waiting for bite"
                    BloxClearFailure()
                else
                    Runtime.BloxFishingStatus="CastLineAtLocation failed • move near water"
                    BloxFail("FISHING_CAST_FAILED",Runtime.BloxFishingStatus)
                end
                return OkCast,Result
            end
            Runtime.BloxCatchFishingFish = function()
                local R=Runtime.BloxFns.BloxFishingRemotes()
                if not R.Request then
                    BloxFail("FISHING_REQUEST_MISSING","FishingRequest not loaded")
                    return false
                end
                local Ok1=select(1,Runtime.BloxFishingInvoke(R.Request,"Catching",1))
                task.wait(0.25)
                local Ok2=select(1,Runtime.BloxFishingInvoke(R.Request,"Catch",1))
                if Ok1 and Ok2 then
                    Runtime.BloxFishingStatus="Catch sent • recasting"
                    Runtime.BloxFishingLastCatch=os.clock()
                    Runtime.BloxFishingLastCast=-math.huge
                    Runtime.BloxBestBaitCheckAt=0
                    BloxClearFailure()
                    return true
                end
                Runtime.BloxFishingStatus="Catch request failed"
                BloxFail("FISHING_CATCH_FAILED",Runtime.BloxFishingStatus)
                return false
            end
            Runtime.BloxAutoFishStep = function()

                if not Runtime.BloxEnsureFishingSetup(false) then return end
                local Rod=Runtime.BloxFindFishingRod()
                if not Rod then
                    Runtime.BloxFishingStatus="Rod missing"
                    BloxFail("FISHING_ROD_MISSING",Runtime.BloxFishingStatus)
                    return
                end
                local H=Humanoid()
                if H and Rod.Parent~=Character() then pcall(function() H:EquipTool(Rod) end); task.wait(0.12) end
                Rod=Runtime.BloxFindFishingRod()
                if not Rod then return end

                local StateName=Runtime.BloxFishingState(Rod)
                local Lower=string.lower(StateName)
                if string.find(Lower,"bit",1,true) then
                    Runtime.BloxCatchFishingFish()
                    task.wait(0.35)
                    return
                end
                if Lower=="idle" or Lower=="reeledin" or Lower=="reeled in" or Lower=="ready" or Lower=="none" or Lower=="nil" then
                    if os.clock()-(Runtime.BloxFishingLastCast or -math.huge)>0.9 then Runtime.BloxCastFishingLine() end
                    return
                end

                local SinceCast=os.clock()-(Runtime.BloxFishingLastCast or os.clock())
                if SinceCast>16 then
                    Runtime.BloxFishingStatus="Fishing state stuck ("..StateName..") • recasting"
                    Runtime.BloxCastFishingLine()
                else
                    Runtime.BloxFishingStatus="Fishing • "..StateName.." • "..tostring(math.floor(SinceCast*10)/10).."s"
                end
            end

            Runtime.FindOwnedToolByName = function(Name)
                local Wanted=string.lower(tostring(Name or ""))
                for _,Container in ipairs({Character(),Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Obj in ipairs(Container:GetChildren()) do
                            if Obj:IsA("Tool") and string.lower(Obj.Name)==Wanted then return Obj end
                        end
                    end
                end
                return nil
            end
            Runtime.PlayerOwnsNamedItem = function(Name)
                if Runtime.FindOwnedToolByName(Name) then return true end
                local Ok,Inventory=QueryRemote(BloxCommF(),"getInventory")
                if Ok and type(Inventory)=="table" then
                    local Wanted=string.lower(tostring(Name or ""))
                    for _,Entry in pairs(Inventory) do
                        if type(Entry)=="table" then
                            local N=Entry.Name or Entry.ItemName or Entry.name
                            if N and string.lower(tostring(N))==Wanted then return true end
                        end
                    end
                end
                return false
            end
            Runtime.ToolMasteryValue = function(Name)
                local Tool=Runtime.FindOwnedToolByName(Name)
                if not Tool then return nil end
                for _,Key in ipairs({"Mastery","Level","Mas"}) do
                    local Attr=Tool:GetAttribute(Key)
                    if tonumber(Attr) then return tonumber(Attr) end
                    local Obj=Tool:FindFirstChild(Key)
                    if Obj and Obj.Value~=nil and tonumber(Obj.Value) then return tonumber(Obj.Value) end
                end
                return nil
            end

            Runtime.BloxLastSmartRaidStart=0
            Runtime.BloxWasInSmartRaid=false
            Runtime.SmartRaidStep = function()
                local Island=RaidIsland()
                if Island then
                    local Now=os.clock()
                    Runtime.BloxRaidCurrentIsland=tostring(Island.Name or "Raid")
                    Runtime.BloxWasInSmartRaid=true
                    Runtime.BloxRaidMissingIslandAt=nil
                    if Island.Name=="Island 5" then Runtime.BloxRaidSawFinalIsland=true end

                    -- The countdown is armed only by StartRaidOnce after a real character teleport.
                    -- Island streaming by itself must never start combat early.
                    local TeleportAt=tonumber(Runtime.BloxRaidTeleportDetectedAt)
                    local FarmStartsAt=tonumber(Runtime.BloxRaidFarmStartsAt)
                    if not TeleportAt or not FarmStartsAt then
                        Runtime.BloxRaidCombatActive=false
                        SetRaidStatus("Raid island detected • waiting for character to reach raid area")
                        return
                    end
                    if Now<FarmStartsAt then
                        Runtime.BloxRaidCombatActive=false
                        local Remaining=math.max(0,FarmStartsAt-Now)
                        SetRaidStatus("Teleported into raid • farming begins in "..tostring(math.max(1,math.ceil(Remaining))).."s")
                        return
                    end
                    RaidStep()
                    return
                end
                if Runtime.BloxWasInSmartRaid then
                    local TeleportAt=tonumber(Runtime.BloxRaidTeleportDetectedAt)
                    if TeleportAt and os.clock()-TeleportAt<12 then
                        Runtime.BloxRaidCombatActive=false
                        SetRaidStatus("Raid arrival confirmed • waiting for raid island to stream")
                        return
                    end
                    if not Runtime.BloxRaidSawFinalIsland then
                        Runtime.BloxRaidMissingIslandAt=Runtime.BloxRaidMissingIslandAt or os.clock()
                        if os.clock()-Runtime.BloxRaidMissingIslandAt<7 then
                            SetRaidStatus("Waiting for raid islands to stream back")
                            return
                        end
                    end
                    Runtime.BloxWasInSmartRaid=false
                    Runtime.BloxRaidCurrentIsland=nil
                    Runtime.BloxRaidFarmStartsAt=nil
                    Runtime.BloxRaidTeleportDetectedAt=nil
                    Runtime.BloxRaidArrivalIsland=nil
                    Runtime.BloxRaidArrivalDistance=nil
                    Runtime.BloxRaidLockedTarget=nil
                    Runtime.BloxRaidCombatActive=false
                    if Runtime.BloxRaidSawFinalIsland then
                        Runtime.BloxRaidJustClearedAt=os.clock()
                        SetRaidStatus("Final island cleared • waiting for awakening room")
                    else
                        Runtime.BloxRaidJustClearedAt=nil
                        SetRaidStatus("Raid islands lost before final island • preparing another raid")
                    end
                end
                if AtRaidAscensionPlace() then
                    SetRaidStatus("Ascension / awakening place reached ✓ • Raid stopped")
                    Runtime.SetFlagValue("GameProfile_Blox_SmartRaid",false)
                    return
                end
                if Runtime.BloxRaidJustClearedAt and os.clock()-Runtime.BloxRaidJustClearedAt<10 then return end
                local Now=os.clock()
                if Now-Runtime.BloxLastSmartRaidStart>=1.5 then
                    Runtime.BloxLastSmartRaidStart=Now
                    if not Runtime.BloxFns.HasRaidChip() then
                        local OK,Reason=BuyRaidChipWithSelectedFruit()
                        if not OK then
                            if Reason=="RAID_SELECTED_FRUITS_EMPTY" or Reason=="RAID_SELECTED_FRUITS_INELIGIBLE" or Reason=="RAID_FRUIT_SELECTION_EMPTY" or Reason=="RAID_SELECTED_BACKPACK_FRUIT_MISSING" or Reason=="RAID_SELECTED_TREASURY_FRUIT_MISSING" or Reason=="RAID_TREASURY_WITHDRAW_FAILED" or Reason=="RAID_TREASURY_WITHDRAW_NOT_CONFIRMED" or Reason=="RAID_WITHDRAWN_FRUIT_NOT_FOUND" then
                                Runtime.SetFlagValue("GameProfile_Blox_SmartRaid",false)
                            elseif Reason~="RAID_CHIP_SETTLING" and Reason~="RAID_CHIP_NOT_CONFIRMED" then
                                SetRaidStatus(Reason)
                            end
                            return
                        end
                    end
                    StartRaidOnce()
                end
            end

            Runtime.BloxSeaAPI=(function()
                local API={}
                local Map={
                    ["Terrorshark"]={Kind="Enemy",Names={"Terrorshark"}},
                    ["Shark"]={Kind="Enemy",Names={"Shark"}},
                    ["Piranha"]={Kind="Enemy",Names={"Piranha"}},
                    ["Fish Crew"]={Kind="Enemy",Names={"Fish Crew Member"}},
                    ["Mirage Island"]={Kind="World",Names={"Mirage Island","MirageIsland"},Offset=CFrame.new(0,120,0)},
                    ["Kitsune Island"]={Kind="World",Names={"Kitsune Island","KitsuneIsland"},Offset=CFrame.new(0,18,0)},
                    ["Blue Gear"]={Kind="Collect",Names={"Blue Gear","BlueGear"}},
                    ["Azure Ember"]={Kind="Collect",Names={"Azure Ember","AzureEmber","AttachedAzureEmber"}}
                }
                local RState={
                    Running=false,Status="Idle",LastScan=0,LastFallback=0,
                    LastDangerScan=0,LastDanger="Unknown",Detected={},Cache={}
                }

                local function compact(Value)
                    return string.lower(tostring(Value or "")):gsub("[^%w]","")
                end

                local Aliases={}
                for Event,Info in pairs(Map) do
                    for _,Alias in ipairs(Info.Names or {}) do
                        Aliases[compact(Alias)]=Event
                    end
                end

                local function nameMatches(Name,Keywords)
                    local N=compact(Name)
                    if N=="" then return false end
                    for _,K in ipairs(Keywords or {}) do
                        if N==compact(K) then return true end
                    end
                    return false
                end

                local function usable(Object,Info)
                    if not Object or not Object.Parent then return false end
                    local R=GetRoot(Object)
                    if not R then return false end
                    if Info and Info.Kind=="Enemy" then
                        local H=Object:IsA("Model") and Object:FindFirstChildOfClass("Humanoid") or nil
                        if H then return H.Health>0 end
                        local Health=Object:FindFirstChild("Health")
                        if Health and Health.Value~=nil then return tonumber(Health.Value or 0)>0 end
                    end
                    return true
                end

                local function findEnemy(Info)
                    local Enemies=workspace:FindFirstChild("Enemies")
                    if not Enemies then return nil end
                    local Me=Root()
                    local Best,BestDist=nil,math.huge
                    for _,Obj in ipairs(Enemies:GetChildren()) do
                        if Obj:IsA("Model") and nameMatches(Obj.Name,Info.Names) then
                            local H=Obj:FindFirstChildOfClass("Humanoid")
                            local R=GetRoot(Obj)
                            if H and H.Health>0 and R then
                                local D=Me and (R.Position-Me.Position).Magnitude or 0
                                if D<BestDist then Best,BestDist=Obj,D end
                            end
                        end
                    end
                    return Best
                end

                local function findWorld(Event)
                    if Event=="Mirage Island" then
                        local WO=workspace:FindFirstChild("_WorldOrigin")
                        local Locations=WO and WO:FindFirstChild("Locations")
                        if Locations then
                            local Obj=Locations:FindFirstChild("Mirage Island") or Locations:FindFirstChild("MirageIsland")
                            if Obj and GetRoot(Obj) then return Obj end
                        end
                    elseif Event=="Kitsune Island" then
                        local MapFolder=workspace:FindFirstChild("Map")
                        if MapFolder then
                            local Obj=MapFolder:FindFirstChild("KitsuneIsland") or MapFolder:FindFirstChild("Kitsune Island")
                            if Obj and GetRoot(Obj) then return Obj end
                        end
                    elseif Event=="Azure Ember" then
                        local Obj=workspace:FindFirstChild("AttachedAzureEmber")
                        if Obj and GetRoot(Obj) then return Obj end
                    elseif Event=="Blue Gear" then
                        local WO=workspace:FindFirstChild("_WorldOrigin")
                        local MapFolder=workspace:FindFirstChild("Map")
                        for _,Container in ipairs({WO,MapFolder}) do
                            if Container then
                                local Obj=Container:FindFirstChild("Blue Gear",true) or Container:FindFirstChild("BlueGear",true)
                                if Obj and GetRoot(Obj) then return Obj end
                            end
                        end
                    end
                    return nil
                end

                local function refresh(AllowFallback)
                    local Found={}
                    for Event,Info in pairs(Map) do
                        local Obj=nil
                        if Info.Kind=="Enemy" then Obj=findEnemy(Info) end
                        Obj=Obj or findWorld(Event)
                        if usable(Obj,Info) then Found[Event]=Obj end
                    end

                    for Event,Obj in pairs(RState.Cache) do
                        local Info=Map[Event]
                        if not Found[Event] and Info and usable(Obj,Info) then Found[Event]=Obj end
                    end

                    local Now=os.clock()
                    if AllowFallback and Now-RState.LastFallback>=3.0 then
                        RState.LastFallback=Now
                        local Missing=false
                        for Event in pairs(Map) do
                            if not Found[Event] then Missing=true; break end
                        end
                        if Missing then
                            local Scanned=0
                            for _,Obj in ipairs(Runtime.ProfileObjects()) do
                                Scanned+=1
                                if Scanned>12000 then break end
                                local Event=Aliases[compact(Obj.Name)]
                                if Event and not Found[Event] then
                                    local Info=Map[Event]
                                    if not IsPlayerCharacter(Obj) and usable(Obj,Info) then Found[Event]=Obj end
                                end
                            end
                        end
                    end

                    RState.Cache=Found
                    local Names={}
                    for Event in pairs(Found) do table.insert(Names,Event) end
                    table.sort(Names)
                    RState.Detected=Names
                    return Found
                end

                local function find(Event,AllowFallback)
                    local Info=Map[Event]
                    if not Info then return nil end
                    local Cached=RState.Cache[Event]
                    if usable(Cached,Info) then return Cached end

                    local Obj=Info.Kind=="Enemy" and findEnemy(Info) or findWorld(Event)
                    if usable(Obj,Info) then
                        RState.Cache[Event]=Obj
                        return Obj
                    end

                    if AllowFallback then
                        Obj=refresh(true)[Event]
                        if usable(Obj,Info) then return Obj end
                    end
                    return nil
                end

                local function boatInfo()
                    local H=Humanoid()
                    local Seat=H and H.SeatPart
                    if not Seat or (not Seat:IsA("VehicleSeat") and not Seat:IsA("Seat")) then return nil,"Not seated" end
                    local Boat=Seat:FindFirstAncestorOfClass("Model") or Seat.Parent
                    if not Boat then return nil,"Unknown boat" end

                    local HP,MaxHP=nil,nil
                    local BoatHumanoid=Boat:FindFirstChildOfClass("Humanoid")
                    if BoatHumanoid then HP,MaxHP=BoatHumanoid.Health,BoatHumanoid.MaxHealth end

                    for _,Key in ipairs({"Health","HP"}) do
                        local Obj=Boat:FindFirstChild(Key,true)
                        if Obj and (Obj:IsA("NumberValue") or Obj:IsA("IntValue")) then HP=tonumber(Obj.Value) or HP end
                        HP=tonumber(Boat:GetAttribute(Key)) or HP
                    end
                    for _,Key in ipairs({"MaxHealth","MaxHP"}) do
                        local Obj=Boat:FindFirstChild(Key,true)
                        if Obj and (Obj:IsA("NumberValue") or Obj:IsA("IntValue")) then MaxHP=tonumber(Obj.Value) or MaxHP end
                        MaxHP=tonumber(Boat:GetAttribute(Key)) or MaxHP
                    end

                    if HP and MaxHP and MaxHP>0 then
                        return Boat,string.format("%s • %d/%d (%.0f%%)",Boat.Name,HP,MaxHP,math.clamp((HP/MaxHP)*100,0,100))
                    elseif HP then
                        return Boat,string.format("%s • %d HP",Boat.Name,HP)
                    end
                    return Boat,Boat.Name.." • HP unavailable"
                end

                local function readDanger()
                    local Candidates={Player,Character(),workspace}
                    local Boat=select(1,boatInfo())
                    if Boat then table.insert(Candidates,Boat) end

                    for _,Obj in ipairs(Candidates) do
                        if Obj then
                            for _,Key in ipairs({"DangerLevel","SeaDanger","Danger","SeaLevel"}) do
                                local V=Obj:GetAttribute(Key)
                                if V~=nil then return tostring(V) end
                                local Child=Obj:FindFirstChild(Key)
                                if Child and Child.Value~=nil then return tostring(Child.Value) end
                            end
                        end
                    end

                    local PG=Player:FindFirstChildOfClass("PlayerGui")
                    if PG then
                        for _,Obj in ipairs(PG:GetDescendants()) do
                            if Obj:IsA("TextLabel") or Obj:IsA("TextButton") then
                                local T=tostring(Obj.Text or "")
                                if string.find(string.lower(T),"danger",1,true) then
                                    local N=string.match(T,"[0-6]")
                                    if N then return N end
                                end
                            end
                        end
                    end
                    return "Unknown"
                end

                local function danger()
                    local Now=os.clock()
                    if Now-RState.LastDangerScan>=0.9 then
                        RState.LastDangerScan=Now
                        RState.LastDanger=readDanger()
                    end
                    return RState.LastDanger
                end

                local function step()
                    local Event=State.BloxSeaEvent
                    local Info=Map[Event]
                    if not Info then RState.Status="Select an event"; return end
                    if Runtime.BloxFns.CurrentSeaName()~="Sea 3" then
                        RState.Status="Sea Events require Sea 3"
                        return
                    end

                    local Found=find(Event,false)
                    if not Found then
                        local Now=os.clock()
                        if Now-RState.LastScan>=2.0 then
                            RState.LastScan=Now
                            refresh(true)
                            Found=find(Event,false)
                        end
                    end

                    if not Found then
                        RState.Status="Searching for "..Event
                        return
                    end

                    if Info.Kind=="Enemy" then
                        RState.Status="Fighting "..Event
                        FarmBloxEnemy(Found)
                    elseif Info.Kind=="Collect" then
                        RState.Status="Collecting "..Event
                        TouchObject(Found)
                    else
                        RState.Status="Event detected • traveling"
                        MoveTo(Found,Info.Offset or CFrame.new(0,8,0))
                    end
                end

                local function go()
                    local Event=State.BloxSeaEvent
                    local Info=Map[Event]
                    if not Info or Runtime.BloxFns.CurrentSeaName()~="Sea 3" then return false end
                    local Obj=find(Event,true)
                    if not Obj then return false end
                    if Info.Kind=="Collect" then return TouchObject(Obj) end
                    return MoveTo(Obj,Info.Offset or CFrame.new(0,8,0))
                end

                API.Map=Map
                API.Runtime=RState
                API.Names=function()
                    local O={}
                    for Name in pairs(Map) do table.insert(O,Name) end
                    table.sort(O)
                    return O
                end
                API.Refresh=refresh
                API.Find=find
                API.BoatInfo=boatInfo
                API.Danger=danger
                API.Step=step
                API.Go=go
                return API
            end)()

            Runtime.BloxControllerAPI=(function()
                local API={}
                local Paragraph=nil
                local CState={ActiveFlag=nil,ActiveLabel="Idle"}
                local Map={
                    ["GameProfile_Blox_AutoLevel"]={Loop="BloxAutoLevel",Label="Auto Farm"},
                    ["GameProfile_Blox_AutoFarm"]={Loop="BloxFarm",Label="Selected Enemy"},
                    ["GameProfile_Blox_AutoBoss"]={Loop="BloxBoss",Label="Selected Boss"},
                    ["GameProfile_Blox_MaterialFarm"]={Loop="BloxMaterialFarm",Label="Material Farm"},
                    ["GameProfile_Blox_AutoFish"]={Loop="BloxAutoFish",Label="Auto Fish"},
                    ["GameProfile_Blox_AutoFruit"]={Loop="BloxFruit",Label="Fruit Collection"},
                    ["GameProfile_Blox_AutoChest"]={Loop="BloxChest",Label="Chest Route"},
                    ["GameProfile_Blox_AutoNextSea"]={Loop="BloxNextSea",Label="Next Sea Quest"},
                    ["GameProfile_Blox_SelectedPvP"]={Loop="BloxSelectedPvP",Label="PvP Target"},
                    ["GameProfile_Blox_RaceV2Quest"]={Loop="BloxRaceV2",Label="Race V2 Quest"},
                    ["GameProfile_Blox_SmartRaid"]={Loop="BloxSmartRaid",Label="Raid"},
                    ["GameProfile_Blox_Law"]={Loop="BloxLaw",Label="Order / Law"},
                    ["GameProfile_Blox_Factory"]={Loop="BloxFactory",Label="Factory Core"},
                    ["GameProfile_Blox_Elite"]={Loop="BloxElite",Label="Elite Hunter"},
                    ["GameProfile_Blox_CakePrince"]={Loop="BloxCakePrince",Label="Cake Prince"},
                    ["GameProfile_Blox_DoughKing"]={Loop="BloxDoughKing",Label="Dough King"},
                    ["GameProfile_Blox_BossDrop"]={Loop="BloxBossDrop",Label="Boss Drop"},
                    ["GameProfile_Blox_SeaEvent"]={Loop="BloxSeaEvent",Label="Sea Event"}
                }

                local function update()
                    if Paragraph and Paragraph.Set then
                        local Companion=State.BloxAutoFruitActive and " + Fruit Watch" or ""
                        Paragraph:Set({Title="Smart Controller",Content="Active: "..tostring(CState.ActiveLabel or "Idle")..Companion})
                    end
                end

                function API.SetParagraph(Value)
                    Paragraph=Value
                    update()
                end

                function API.Claim(FlagName)
                    if CState.ActiveFlag==FlagName and Runtime.BloxFarmControllerActive then return end
                    for OtherFlag,Info in pairs(Map) do
                        local KeepPassiveV2=(OtherFlag=="GameProfile_Blox_RaceV2Quest" and Runtime.BloxRaceV2Standby==true)
                        if OtherFlag~=FlagName and OtherFlag~="GameProfile_Blox_AutoFruit" and not KeepPassiveV2 then
                            Runtime.SetFlagValue(OtherFlag,false)
                            if Info.Loop then StopLoop(Info.Loop) end
                        end
                    end
                    Runtime.CancelBloxFarmTravel()
                    Runtime.BloxFarmGeneration=(tonumber(Runtime.BloxFarmGeneration) or 0)+1
                    Runtime.BloxFarmControllerActive=true
                    Runtime.BloxAutoLevelActive=(FlagName=="GameProfile_Blox_AutoLevel")
                    Runtime.BloxMaterialFarmActive=(FlagName=="GameProfile_Blox_MaterialFarm")
                    local Info=Map[FlagName]
                    CState.ActiveFlag=FlagName
                    CState.ActiveLabel=Info and Info.Label or tostring(FlagName)
                    update()
                end

                function API.Release(FlagName)
                    if CState.ActiveFlag==FlagName then
                        Runtime.BloxFarmControllerActive=false
                        if FlagName=="GameProfile_Blox_AutoLevel" then Runtime.BloxAutoLevelActive=false end
                        if FlagName=="GameProfile_Blox_MaterialFarm" then Runtime.BloxMaterialFarmActive=false end
                        Runtime.BloxFarmGeneration=(tonumber(Runtime.BloxFarmGeneration) or 0)+1
                        Runtime.CancelBloxFarmTravel()
                        State.BloxAimBasicAttack=false
                        State.BloxSelectedUseQuest=false
                        State.BloxBossUseQuest=false
                        State.BloxMoveToSpawn=false
                        CState.ActiveFlag=nil
                        CState.ActiveLabel="Idle"
                        update()
                    end
                end

                function API.StopAll()
                    for FlagName,Info in pairs(Map) do
                        Runtime.SetFlagValue(FlagName,false)
                        if Info.Loop then StopLoop(Info.Loop) end
                    end
                    Runtime.BloxFarmControllerActive=false
                    Runtime.BloxAutoLevelActive=false
                    Runtime.BloxMaterialFarmActive=false
                    Runtime.BloxFruitInterruptPending=nil
                    Runtime.BloxFruitInterruptActive=false
                    Runtime.BloxWaitingUnderground=false
                    Runtime.BloxUndergroundWaitCF=nil
                    Runtime.BloxFarmGeneration=(tonumber(Runtime.BloxFarmGeneration) or 0)+1
                    Runtime.CancelBloxFarmTravel()
                    State.BloxAimBasicAttack=false
                    State.BloxSelectedUseQuest=false
                    State.BloxBossUseQuest=false
                    State.BloxMoveToSpawn=false
                    CState.ActiveFlag=nil
                    CState.ActiveLabel="Idle"
                    update()
                end

                function API.Refresh() update() end
                function API.ActiveFlag() return CState.ActiveFlag end

                function API.OnRespawn()
                    if not CState.ActiveFlag then return end
                    local Previous=CState.ActiveLabel
                    CState.ActiveLabel="Recovering • "..tostring(Previous)
                    update()
                    task.delay(1.1,function()
                        if not Unloaded and CState.ActiveFlag then
                            local Info=Map[CState.ActiveFlag]
                            CState.ActiveLabel=Info and Info.Label or Previous
                            update()
                        end
                    end)
                end

                return API
            end)()

