                DetectedTab:CreateParagraph({Title="Blox Fruits UI Error",Content=tostring(Runtime._BloxUIBuildResult[2])})
            end
            Runtime._BloxUIBuildResult=nil

            -- Sea travel creates a new Roblox place session. Prefer TeleportSettings when they
            -- survive, but also accept the marker planted by the queued fallback bootstrap. This
            -- makes the resume path independent from executor auto-execute when queue-on-teleport
            -- support is available.
            Runtime.BloxFns.ResumeAutoFarmAfterThirdSeaTeleport = function()
                local Env=(getgenv and getgenv()) or _G
                local ResumeFromQueue=Env and Env.__BANANIHUB_TELEPORT_RESUME_AUTO_FARM==true
                local ResumeFromSetting=false
                pcall(function() ResumeFromSetting=TeleportService:GetTeleportSetting("BananiHubResumeAutoFarm")==true end)
                local Resume=ResumeFromQueue or ResumeFromSetting
                if not Resume or BloxSeaNumber()~=3 then return false end
                if Env then Env.__BANANIHUB_TELEPORT_RESUME_AUTO_FARM=nil end
                pcall(function() TeleportService:SetTeleportSetting("BananiHubResumeAutoFarm",false) end)
                task.defer(function()
                    task.wait(1.0)
                    if not Unloaded and BloxSeaNumber()==3 then
                        Runtime.SetFlagValue("GameProfile_Blox_AutoLevel",true)
                        Runtime.BloxFns.SetBloxProgressionStatus("Third Sea unlocked ✓ • Auto Farm resumed")
                    end
                end)
                return true
            end
            Runtime.BloxFns.ResumeAutoFarmAfterThirdSeaTeleport()


