        elseif Kind == "MVS" then

            local Roster = DetectedTab:CreateParagraph({Title="Player Roster",Content="Enable the roster to read replicated teams and health."})
            local Session = DetectedTab:CreateParagraph({Title="Session Snapshot",Content="Press Refresh Session Stats."})
            local SessionStart = os.clock()
            local WarningRadius, HealthThreshold = 35, 30
            local LastProximity = -math.huge
            local HealthLatched = false
            local function Relation(P)
                if Player.Neutral or P.Neutral or not Player.Team or not P.Team then return "Unknown team" end
                return P.Team == Player.Team and "Teammate" or "Other team"
            end
            local function RefreshRoster()
                local Rows = {}
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    if P ~= Player then
                        local C = P.Character
                        local H = C and C:FindFirstChildOfClass("Humanoid")
                        Rows[#Rows+1] = P.Name.." • "..Relation(P).." • "..(H and (tostring(math.floor(H.Health)).." HP") or "Not spawned")
                    end
                end
                table.sort(Rows)
                Roster:Set({Title="Player Roster",Content=#Rows>0 and table.concat(Rows,"\n") or "No other players."})
            end
            DetectedTab:CreateSection("INFORMATION")
            DetectedTab:CreateToggle({Name="Live Team + Health Roster",Flag="GameProfile_MVS_Roster",CurrentValue=false,Callback=function(V)
                if V then StartLoop("MVSRoster",RefreshRoster,0.5)
                else StopLoop("MVSRoster"); Roster:Set({Title="Player Roster",Content="Roster off."}) end
            end})
            DetectedTab:CreateButton({Name="Refresh Session Stats",Callback=function()
                local Rows = {"Session: "..tostring(math.floor((os.clock()-SessionStart)/60)).." minutes"}
                local Stats = Player:FindFirstChild("leaderstats")
                if Stats then
                    for _,Value in ipairs(Stats:GetChildren()) do
                        if Value:IsA("IntValue") or Value:IsA("NumberValue") or Value:IsA("StringValue") then
                            Rows[#Rows+1] = Value.Name..": "..tostring(Value.Value)
                        end
                    end
                else Rows[#Rows+1] = "This server exposes no leaderstats." end
                Session:Set({Title="Session Snapshot",Content=table.concat(Rows,"\n")})
            end})
            DetectedTab:CreateSection("WARNINGS")
            DetectedTab:CreateSlider({Name="Nearby Warning Distance",Range={10,100},Increment=5,Suffix=" studs",CurrentValue=35,Callback=function(V) WarningRadius=V end})
            DetectedTab:CreateToggle({Name="Nearby Non-Teammate Warning",Flag="GameProfile_MVS_Proximity",CurrentValue=false,Callback=function(V)
                if V then
                    LastProximity=-math.huge
                    StartLoop("MVSProximity",function()
                        local R=Root()
                        if not R or os.clock()-LastProximity<8 then return end
                        local Best,Distance=nil,WarningRadius
                        for _,P in ipairs(Runtime.CachedPlayers()) do
                            local C=P.Character
                            local H=C and C:FindFirstChildOfClass("Humanoid")
                            local PR=C and C:FindFirstChild("HumanoidRootPart")
                            if P~=Player and Relation(P)~="Teammate" and H and H.Health>0 and PR then
                                local D=(R.Position-PR.Position).Magnitude
                                if D<Distance then Best,Distance=P,D end
                            end
                        end
                        if Best then
                            LastProximity=os.clock()
                            Notify("Nearby Player",Best.Name.." • "..Relation(Best).." • "..math.floor(Distance).." studs")
                        end
                    end,0.5)
                else StopLoop("MVSProximity") end
            end})
            DetectedTab:CreateSlider({Name="Low Health Threshold",Range={10,70},Increment=5,Suffix=" %",CurrentValue=30,Callback=function(V) HealthThreshold=V end})
            DetectedTab:CreateToggle({Name="Low Health Warning",Flag="GameProfile_MVS_Health",CurrentValue=false,Callback=function(V)
                if V then
                    HealthLatched=false
                    local LastCharacter=nil
                    StartLoop("MVSHealth",function()
                        local C=Character()
                        if C~=LastCharacter then LastCharacter=C; HealthLatched=false end
                        local H=Humanoid()
                        if not H or H.MaxHealth<=0 then return end
                        local Percent=100*H.Health/H.MaxHealth
                        if Percent<=HealthThreshold and not HealthLatched then
                            HealthLatched=true
                            Notify("Low Health",tostring(math.floor(Percent)).."% health remaining.")
                        elseif Percent>HealthThreshold+10 then HealthLatched=false end
                    end,0.5)
                else StopLoop("MVSHealth"); HealthLatched=false end
            end})
            do
            DetectedTab:CreateSection("MVS ACTIONS")
            local MVSAimCache={Player=nil,Part=nil,Until=0,FOV=nil,VisibleOnly=nil}
            local function MVSVisible(Part)
                if not State.MVSVisibleOnly then return true end
                local Cam=workspace.CurrentCamera
                if not Cam or not Part then return false end
                local Params=RaycastParams.new()
                Params.FilterType=Enum.RaycastFilterType.Exclude
                Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                local Hit=workspace:Raycast(Cam.CFrame.Position,Part.Position-Cam.CFrame.Position,Params)
                return not Hit or Hit.Instance:IsDescendantOf(Part.Parent)
            end
            local function MVSAimTarget()
                local Cam=workspace.CurrentCamera
                if not Cam then return nil,nil end
                local Now=os.clock()
                if Now<(MVSAimCache.Until or 0)
                    and MVSAimCache.FOV==State.MVSFOV
                    and MVSAimCache.VisibleOnly==State.MVSVisibleOnly
                    and MVSAimCache.Player and Relation(MVSAimCache.Player)~="Teammate" then
                    local C=MVSAimCache.Player.Character
                    local H=C and C:FindFirstChildOfClass("Humanoid")
                    local Part=C and (C:FindFirstChild("Head") or C:FindFirstChild("HumanoidRootPart"))
                    if H and H.Health>0 and Part and MVSVisible(Part) then return MVSAimCache.Player,Part end
                end

                local Center=Cam.ViewportSize/2
                local Best,BestPart=nil,nil
                local BestPixels=tonumber(State.MVSFOV) or 280
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    local C=P.Character
                    local H=C and C:FindFirstChildOfClass("Humanoid")
                    local Part=C and (C:FindFirstChild("Head") or C:FindFirstChild("HumanoidRootPart"))
                    if P~=Player and Relation(P)~="Teammate" and H and H.Health>0 and Part then
                        local V,On=Cam:WorldToViewportPoint(Part.Position)
                        if On and V.Z>0 then
                            local Pixels=(Vector2.new(V.X,V.Y)-Center).Magnitude
                            if Pixels<BestPixels and MVSVisible(Part) then
                                Best,BestPart,BestPixels=P,Part,Pixels
                            end
                        end
                    end
                end
                MVSAimCache.Player=Best
                MVSAimCache.Part=BestPart
                MVSAimCache.Until=Now+0.08
                MVSAimCache.FOV=State.MVSFOV
                MVSAimCache.VisibleOnly=State.MVSVisibleOnly
                return Best,BestPart
            end
            local function MVSAimStep()
                local _,Part=MVSAimTarget()
                local Cam=workspace.CurrentCamera
                if not Part or not Cam then return end
                local Goal=CFrame.lookAt(Cam.CFrame.Position,Part.Position)
                Cam.CFrame=Cam.CFrame:Lerp(Goal,1/math.max(tonumber(State.MVSAimSmooth) or 7,1))
            end
            DetectedTab:CreateSlider({Name="Aim Smoothness",Range={1,20},Increment=1,CurrentValue=State.MVSAimSmooth,Callback=function(V) State.MVSAimSmooth=V end})
            DetectedTab:CreateSlider({Name="Aim FOV",Range={40,900},Increment=10,Suffix=" px",CurrentValue=State.MVSFOV,Callback=function(V) State.MVSFOV=V; MVSAimCache.Until=0 end})
            DetectedTab:CreateToggle({Name="Visible Targets Only",Flag="GameProfile_MVS_VisibleOnly",CurrentValue=State.MVSVisibleOnly,Callback=function(V) State.MVSVisibleOnly=V; MVSAimCache.Until=0 end})
            DetectedTab:CreateToggle({Name="Aim At Best Opponent",Flag="GameProfile_MVS_Aim",CurrentValue=false,Callback=function(V)
                if V then StartLoop("MVSAim",MVSAimStep,0.03) else StopLoop("MVSAim") end
            end})
            end
            DetectedTab:CreateParagraph({Title="Compatibility",Content="MVS aiming now uses team checks, screen-space FOV, optional wall visibility and smooth camera tracking. It deliberately does not import silent-aim hooks, hitbox abuse, anti-cheat bypasses or round-result claims from public scripts."})

        elseif Kind == "MM2" then
            local RoleParagraph, PlayerDrop, KnifeDrop, GunToolDrop
            Runtime.MM2FarmGeneration=tonumber(Runtime.MM2FarmGeneration) or 0
            Runtime.MM2FarmActive=false
            Runtime.MM2StopGeneration=(tonumber(Runtime.MM2StopGeneration) or 0)+1
            State.MM2ESPMurderer=false
            State.MM2ESPSheriff=false
            State.MM2ESPInnocent=false
            State.MM2ESPHealth=false
            State.MM2ESPDistance=false
            State.MM2ESPChams=false
            State.MM2ESPDisplayName=false
            State.MM2ESPUsername=false
            State.MM2ESPWeapon=false
            State.MM2ESPFloatingText=false
            State.MM2ESPPulse=false
            State.MM2ESPMaxDistance=tonumber(State.MM2ESPMaxDistance) or 1500
            State.MM2ESPTextSize=tonumber(State.MM2ESPTextSize) or 14
            State.MM2ESPGlowOpacity=tonumber(State.MM2ESPGlowOpacity) or 62

            State.MM2ESPBoxes=false
            State.MM2ESPTracers=false
            State.MM2ESPOffscreen=false
            State.MM2ESPDangerWarning=false
            State.MM2ESPDangerDistance=tonumber(State.MM2ESPDangerDistance) or 65
            State.MM2ESPGunArrow=false
            State.MM2ESPTracerThickness=tonumber(State.MM2ESPTracerThickness) or 2
            State.MM2ESPRadar=false
            State.MM2ESPRadarRange=tonumber(State.MM2ESPRadarRange) or 140
            State.MM2ESPTopHUD=false
            State.MM2ESPThreatVignette=false
            State.MM2ESPDistanceScale=false
            State.MM2ESPThreatAura=false
            State.MM2ESPLowLag=false
            State.MM2ESPMurdererColor=typeof(State.MM2ESPMurdererColor)=="Color3" and State.MM2ESPMurdererColor or Color3.fromRGB(255,35,65)
            State.MM2ESPSheriffColor=typeof(State.MM2ESPSheriffColor)=="Color3" and State.MM2ESPSheriffColor or Color3.fromRGB(20,185,255)
            State.MM2ESPInnocentColor=typeof(State.MM2ESPInnocentColor)=="Color3" and State.MM2ESPInnocentColor or Color3.fromRGB(80,255,145)
            State.MM2RoleESPEnabled=false
            local function ActionValid(Token,Owner)
                return not Unloaded and Token==Runtime.MM2StopGeneration
                    and Character()==Owner and Owner~=nil and Owner.Parent~=nil
            end
            Runtime.MM2Session=Runtime.MM2Session or {
                CoinsCollected=0,
                RoundsSeen=0,
                StartedAt=os.clock(),
                LastBag=nil,
                LastMap=nil,
                LastRole=nil,
                GunWasDropped=false
            }

            Runtime.CancelMM2Travel=function()
                Runtime.TravelRequestId=(Runtime.TravelRequestId or 0)+1
                Runtime.ActiveTravelTargetProvider=nil
                if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                local H,R=Humanoid(),Root()
                if H and R then
                    pcall(function() H:MoveTo(R.Position) end)
                    pcall(function()
                        R.AssemblyLinearVelocity=Vector3.zero
                        R.AssemblyAngularVelocity=Vector3.zero
                    end)
                end
                if Runtime.ClearMM2CoinPath then Runtime.ClearMM2CoinPath() end
            end

            Runtime.MM2FarmRunActive=function(Generation)
                return not Unloaded and Runtime.MM2FarmActive==true
                    and Runtime.MM2FarmGeneration==Generation
            end

            Runtime.BeginMM2Farm=function()
                Runtime.CancelMM2Travel()
                Runtime.MM2FarmGeneration=(tonumber(Runtime.MM2FarmGeneration) or 0)+1
                Runtime.MM2FarmActive=true
                local R=Root()
                Runtime.MM2FarmStartCFrame=R and R.CFrame or nil
                Runtime.MM2Session.StartedAt=os.clock()
                Runtime.MM2Session.CoinsCollected=0
                Runtime.MM2Session.LastBag=nil
                Runtime.MM2FailedCoins={}
                Runtime.MM2CoinCacheAt=0
                return Runtime.MM2FarmGeneration
            end

            Runtime.StopMM2Farm=function(ReturnHome)
                Runtime.MM2FarmActive=false
                Runtime.MM2FarmGeneration=(tonumber(Runtime.MM2FarmGeneration) or 0)+1
                Runtime.CancelMM2Travel()
                local Token,Owner=Runtime.MM2StopGeneration,Character()
                local FarmToken=Runtime.MM2FarmGeneration
                local Home=Runtime.MM2FarmStartCFrame
                Runtime.MM2FarmStartCFrame=nil
                if ReturnHome and typeof(Home)=="CFrame" then
                    task.defer(function()
                        if ActionValid(Token,Owner) and Runtime.MM2FarmGeneration==FarmToken and not Runtime.MM2FarmActive then
                            Runtime.ProfileSmartTravel(Home,nil,{Mode=State.MM2FarmMode,Speed=State.MM2FarmSpeed,Source="MM2ReturnHome"})
                        end
                    end)
                end
            end

            Runtime.MM2InvisibleState=Runtime.MM2InvisibleState or {}

            Runtime.MM2DisconnectList=function(List)
                if type(List)~="table" then return end
                for I=#List,1,-1 do
                    local C=List[I]
                    if C then pcall(function() C:Disconnect() end) end
                    List[I]=nil
                end
            end

            Runtime.MM2SetClientCharacter=function(Model)
                local S=Runtime.MM2InvisibleState
                if not Model or not Model.Parent then return false end
                S.CharacterSwapGuard=true
                local Ok=pcall(function() Player.Character=Model end)
                S.CharacterSwapGuard=false
                if Ok then
                    S.CharacterSwappedToProxy=(Model==S.ProxyCharacter)
                end
                return Ok and Player.Character==Model
            end

            Runtime.MM2TargetPosition=function(Target)
                if not Target then return nil end
                if typeof(Target)=="Vector3" then return Target end
                if typeof(Target)=="CFrame" then return Target.Position end
                if typeof(Target)~="Instance" then return nil end
                if Target:IsA("BasePart") then return Target.Position end
                if Target:IsA("Attachment") then return Target.WorldPosition end
                if Target:IsA("ProximityPrompt") or Target:IsA("ClickDetector") then
                    return Runtime.MM2TargetPosition(Target.Parent)
                end
                if Target:IsA("Model") then
                    local Ok,CF=pcall(function() return Target:GetPivot() end)
                    if Ok and typeof(CF)=="CFrame" then return CF.Position end
                end
                local Part=Target:FindFirstChildWhichIsA("BasePart",true)
                return Part and Part.Position or nil
            end

            Runtime.MM2ApplyHiddenRealPart=function(Part)
                local S=Runtime.MM2InvisibleState
                local Char=S.Character
                if not Char or not Part or not Part:IsA("BasePart") or not Part:IsDescendantOf(Char) then return end
                S.PartBackups=S.PartBackups or setmetatable({}, {__mode="k"})
                local Backup=S.PartBackups[Char]
                if not Backup then Backup={}; S.PartBackups[Char]=Backup end
                if Backup[Part]==nil then
                    Backup[Part]={
                        CanCollide=Part.CanCollide, CanTouch=Part.CanTouch, CanQuery=Part.CanQuery,
                        Transparency=Part.Transparency, LocalTransparencyModifier=Part.LocalTransparencyModifier,
                        CastShadow=Part.CastShadow,
                    }
                end
                if S.BlinkInvisibility then

                    pcall(function()
                        Part.CastShadow=false
                        Part.LocalTransparencyModifier=1
                    end)
                    return
                end
                pcall(function()
                    Part.CanCollide=false
                    Part.CanTouch=false
                    Part.CanQuery=false
                    Part.CastShadow=false
                    Part.LocalTransparencyModifier=1
                end)
            end

            Runtime.MM2SetBlinkPhysicsMuted=function(Char,Muted)
                local S=Runtime.MM2InvisibleState
                if not Char then return end
                if Muted then
                    if S.BlinkPhysicsMuted then return end
                    local Backups={}
                    for _,Part in ipairs(Char:GetDescendants()) do
                        if Part:IsA("BasePart") then
                            Backups[Part]={
                                CanCollide=Part.CanCollide,
                                CanTouch=Part.CanTouch,
                                CanQuery=Part.CanQuery,
                            }
                            pcall(function()
                                Part.CanCollide=false
                                Part.CanTouch=false
                                Part.CanQuery=false
                            end)
                        end
                    end
                    S.BlinkPhysicsBackups=Backups
                    S.BlinkPhysicsMuted=true
                else
                    local Backups=S.BlinkPhysicsBackups
                    if type(Backups)=="table" then
                        for Part,B in pairs(Backups) do
                            if Part and Part.Parent and type(B)=="table" then
                                pcall(function()
                                    Part.CanCollide=B.CanCollide
                                    Part.CanTouch=B.CanTouch
                                    Part.CanQuery=B.CanQuery
                                end)
                            end
                        end
                    end
                    S.BlinkPhysicsBackups=nil
                    S.BlinkPhysicsMuted=false
                end
            end

            Runtime.MM2RestoreBlinkSurface=function(Char,Humanoid,Root,SurfaceCF)
                local S=Runtime.MM2InvisibleState
                if not Char or not Char.Parent or not Root or not Root.Parent then return false end
                SurfaceCF=typeof(SurfaceCF)=="CFrame" and SurfaceCF or S.BlinkSurfaceCFrame or S.SurfaceCFrame or Root.CFrame
                local Linear=S.BlinkSavedLinearVelocity
                local Angular=S.BlinkSavedAngularVelocity
                local Ok=pcall(function() Char:PivotTo(SurfaceCF) end)
                if Linear then pcall(function() Root.AssemblyLinearVelocity=Linear end) end
                if Angular then pcall(function() Root.AssemblyAngularVelocity=Angular end) end
                Runtime.MM2SetBlinkPhysicsMuted(Char,false)
                if Humanoid and Humanoid.Parent then
                    pcall(function() Humanoid.CameraOffset=S.BlinkBaseCameraOffset or Vector3.zero end)
                end
                S.BlinkHidden=false
                S.BlinkSavedLinearVelocity=nil
                S.BlinkSavedAngularVelocity=nil
                return Ok
            end

            Runtime.MM2RestoreCamera=function(FallbackHumanoid)
                local S=Runtime.MM2InvisibleState
                local Cam=workspace.CurrentCamera or Camera
                if not Cam then return end
                local Backup=S.CameraBackup
                local Subject=Backup and Backup.Subject or nil
                if typeof(Subject)=="Instance" and Subject.Parent then
                    pcall(function()
                        Cam.CameraType=Backup.Type or Enum.CameraType.Custom
                        Cam.CameraSubject=Subject
                    end)
                elseif FallbackHumanoid and FallbackHumanoid.Parent then
                    pcall(function()
                        Cam.CameraType=Enum.CameraType.Custom
                        Cam.CameraSubject=FallbackHumanoid
                    end)
                end
            end

            Runtime.MM2SynchronizeInteraction=function(Target,MaxDistance,Callback,Options)
                if type(Callback)~="function" then return false,"callback" end
                if not State.MM2Invisible then
                    local Packed=table.pack(pcall(Callback))
                    return table.unpack(Packed,1,Packed.n)
                end
                local S=Runtime.MM2InvisibleState
                if not S.ProxyActive or S.InteractionSynchronizerBusy then return false,"busy" end
                local ProxyPos=Runtime.MM2SurfacePosition and Runtime.MM2SurfacePosition() or nil
                local TargetPos=Runtime.MM2TargetPosition(Target)
                local Range=math.max(1,tonumber(MaxDistance) or 14)
                if not ProxyPos or (TargetPos and (TargetPos-ProxyPos).Magnitude>Range) then return false,"range" end
                Options=type(Options)=="table" and Options or {}
                if Options.RequireActiveMap~=false and Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then
                    return false,"lobby"
                end
                if typeof(Target)=="Instance" and Options.RequireActiveMap~=false and Runtime.MM2ObjectInActiveMap then
                    local MapTarget=Target
                    if Target:IsA("ProximityPrompt") or Target:IsA("ClickDetector") or Target:IsA("Attachment") then MapTarget=Target.Parent end
                    if MapTarget and not Runtime.MM2ObjectInActiveMap(MapTarget,math.max(20,Range+12)) then return false,"map" end
                end
                S.InteractionSynchronizerBusy=true
                S.InteractionSynchronizerName=tostring(Options.Name or "interaction")
                S.InteractionSynchronizerTarget=Target
                local Packed=table.pack(pcall(function()
                    return Runtime.MM2WithSurfaceShell(Callback,Options.HoldSeconds or 0.08,Options.WarmupFrames or 2)
                end))
                S.InteractionSynchronizerBusy=false
                S.InteractionSynchronizerName=nil
                S.InteractionSynchronizerTarget=nil
                if not Packed[1] then return false,"error" end
                return table.unpack(Packed,2,Packed.n)
            end

            Runtime.MM2DestroyInvisibleDecoy=function()
                local S=Runtime.MM2InvisibleState
                if S.ProxyCharacter and Player.Character==S.ProxyCharacter and S.Character and S.Character.Parent then
                    Runtime.MM2SetClientCharacter(S.Character)
                end
                Runtime.MM2DisconnectList(S.DecoyConnections); S.DecoyConnections={}
                Runtime.MM2DisconnectList(S.ProxySignalConnections); S.ProxySignalConnections={}
                Runtime.MM2DisconnectList(S.WeaponWatchConnections); S.WeaponWatchConnections={}
                if S.RenderConnection then pcall(function() S.RenderConnection:Disconnect() end); S.RenderConnection=nil end
                if S.BlinkHeartbeatConnection then pcall(function() S.BlinkHeartbeatConnection:Disconnect() end); S.BlinkHeartbeatConnection=nil end
                if S.BlinkPhysicsConnection then pcall(function() S.BlinkPhysicsConnection:Disconnect() end); S.BlinkPhysicsConnection=nil end
                if S.SurfaceInputConnection then pcall(function() S.SurfaceInputConnection:Disconnect() end); S.SurfaceInputConnection=nil end
                if S.ProxyAnimationTracks then
                    for _,Track in pairs(S.ProxyAnimationTracks) do
                        if typeof(Track)=="Instance" and Track:IsA("AnimationTrack") then
                            pcall(function() Track:Stop(0.05) end); pcall(function() Track:Destroy() end)
                        end
                    end
                end
                if S.ProxyActionTracks then
                    for _,Track in pairs(S.ProxyActionTracks) do
                        if typeof(Track)=="Instance" and Track:IsA("AnimationTrack") then
                            pcall(function() Track:Stop(0.03) end); pcall(function() Track:Destroy() end)
                        end
                    end
                end
                S.ProxyAnimationTracks={}; S.ProxyAnimationIds={}; S.ProxyAnimationState=nil
                S.ProxyActionTracks={}; S.ProxyRepairQueued=false
                S.WeaponPickupDebounce=setmetatable({}, {__mode="k"}); S.WeaponPickupBusy=false
                S.ProxyCoinDebounce=setmetatable({}, {__mode="k"}); S.ProxyCoinBusy=false
                S.GenericPickupDebounce=setmetatable({}, {__mode="k"})
                S.SurfaceActionActive=false; S.SurfaceWeaponBusy=false; S.InteractionSynchronizerBusy=false
                S.InteractionSynchronizerName=nil; S.InteractionSynchronizerTarget=nil
                S.LastProxyWeaponActionAt=nil
                S.KnownWeaponTools=setmetatable({}, {__mode="k"})
                if Runtime.MM2ClearProxyToolVisual then Runtime.MM2ClearProxyToolVisual() end
                if S.ProxyCharacter then pcall(function() S.ProxyCharacter:Destroy() end) end
                S.ProxyCharacter=nil; S.ProxyHumanoid=nil; S.ProxyRoot=nil; S.Decoy=nil
                S.ProxyToolVisual=nil; S.ProxyToolSource=nil; S.ProxyToolHandle=nil; S.ProxyToolWeld=nil
                S.ProxyToolManualActivationBackup=nil; S.ProxyWeaponKind=nil
                S.SurfaceRelayDepth=0; S.LastForcedShellCFrame=nil; S.LastShellWriteAt=nil
                S.SuppressServerTeleportUntil=nil; S.ServerTeleportIgnoreUntil=nil; S.LastServerTeleportAt=nil
                S.PendingServerTeleportCFrame=nil; S.PendingServerTeleportSince=nil; S.PendingServerTeleportSamples=0
                S.RecentShellWrites={}; S.PartPairs={}; S.SurfaceCFrame=nil; S.LastSurfaceInteract=nil
                S.Controls=nil; S.ControlsResolved=nil; S.ProxyActive=false
                S.CharacterSwappedToProxy=false; S.NativeAnimateActive=false; S.CharacterSwapGuard=false
                if S.Character and Runtime.MM2SetBlinkPhysicsMuted then Runtime.MM2SetBlinkPhysicsMuted(S.Character,false) end
                S.BlinkInvisibility=false; S.BlinkHidden=false; S.BlinkSurfaceCFrame=nil; S.BlinkSuspendUntil=0
                S.BlinkSavedLinearVelocity=nil; S.BlinkSavedAngularVelocity=nil; S.BlinkPhysicsBackups=nil; S.BlinkPhysicsMuted=false
                S.DirectMotorMirror=false; S.ProxyMotorPairs={}
            end

            Runtime.MM2RestoreInvisibleCharacter=function(Char,MoveToSurface)
                local S=Runtime.MM2InvisibleState
                if not Char then return end
                if S.ProxyCharacter and Player.Character==S.ProxyCharacter and Char.Parent then
                    Runtime.MM2SetClientCharacter(Char)
                end
                local H=Char:FindFirstChildOfClass("Humanoid")
                local R=Char:FindFirstChild("HumanoidRootPart")
                local SurfaceCF=S.RestoreCFrame or (S.ProxyRoot and S.ProxyRoot.Parent and S.ProxyRoot.CFrame) or S.BlinkSurfaceCFrame or S.SurfaceCFrame
                if R and S.BlinkHidden and Runtime.MM2RestoreBlinkSurface then
                    Runtime.MM2RestoreBlinkSurface(Char,H,R,SurfaceCF)
                elseif Runtime.MM2SetBlinkPhysicsMuted then
                    Runtime.MM2SetBlinkPhysicsMuted(Char,false)
                end
                if H and S.HumanoidStateBackups and S.HumanoidStateBackups[Char] then
                    local B=S.HumanoidStateBackups[Char]
                    pcall(function() H.CameraOffset=B.CameraOffset or Vector3.zero end)
                    pcall(function() H.AutoRotate=B.AutoRotate~=false end)
                    pcall(function() H.WalkSpeed=B.WalkSpeed or 16 end)
                    pcall(function()
                        if B.UseJumpPower~=nil then H.UseJumpPower=B.UseJumpPower end
                        if B.JumpPower~=nil then H.JumpPower=B.JumpPower end
                        if B.JumpHeight~=nil then H.JumpHeight=B.JumpHeight end
                    end)
                    pcall(function() H:SetStateEnabled(Enum.HumanoidStateType.Jumping,B.Jumping~=false) end)
                    pcall(function() H:SetStateEnabled(Enum.HumanoidStateType.Freefall,B.Freefall~=false) end)
                    pcall(function() H:SetStateEnabled(Enum.HumanoidStateType.FallingDown,B.FallingDown~=false) end)
                    pcall(function() H:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,B.Ragdoll~=false) end)
                    pcall(function() H.PlatformStand=false; H.Sit=false; H.Jump=false end)
                    S.HumanoidStateBackups[Char]=nil
                end
                if S.PartBackups and S.PartBackups[Char] then
                    for Part,B in pairs(S.PartBackups[Char]) do
                        if Part and Part.Parent then
                            pcall(function()
                                Part.CanCollide=B.CanCollide; Part.CanTouch=B.CanTouch; Part.CanQuery=B.CanQuery
                                Part.Transparency=B.Transparency; Part.LocalTransparencyModifier=B.LocalTransparencyModifier
                                Part.CastShadow=B.CastShadow
                            end)
                        end
                    end
                    S.PartBackups[Char]=nil
                end
                if MoveToSurface and R and typeof(SurfaceCF)=="CFrame" and Char.Parent then
                    pcall(function()
                        Char:PivotTo(SurfaceCF)
                        R.AssemblyLinearVelocity=Vector3.zero; R.AssemblyAngularVelocity=Vector3.zero
                    end)
                end
                Runtime.MM2RestoreCamera(H)
                S.RestoreCFrame=nil
            end

            Runtime.MM2BuildInvisibleDecoy=function(Char)
                local S=Runtime.MM2InvisibleState
                if S.ProxyCharacter then pcall(function() S.ProxyCharacter:Destroy() end) end
                S.ProxyCharacter=nil; S.ProxyHumanoid=nil; S.ProxyRoot=nil; S.Decoy=nil
                if not Char or not Char.Parent then return false end

                local OldArchivable=Char.Archivable
                pcall(function() Char.Archivable=true end)
                local Ok,Clone=pcall(function() return Char:Clone() end)
                pcall(function() Char.Archivable=OldArchivable end)
                if not Ok or not Clone then return false end

                Clone.Name="__BananiMM2SurfaceProxy"
                local GhostAlpha=0.50
                for _,Obj in ipairs(Clone:GetDescendants()) do
                    if Obj:IsA("Tool") then
                        pcall(function() Obj:Destroy() end)
                    elseif Obj:IsA("BaseScript") then

                        pcall(function() Obj:Destroy() end)
                    elseif Obj:IsA("BasePart") then
                        Obj.Anchored=(Obj.Name=="HumanoidRootPart")
                        Obj.CanCollide=false
                        Obj.CanTouch=false
                        Obj.CanQuery=false
                        Obj.Massless=true
                        Obj.CastShadow=false
                        Obj.LocalTransparencyModifier=0
                        if Obj.Name=="HumanoidRootPart" or Obj.Transparency>=0.95 then
                            Obj.Transparency=1
                        else
                            Obj.Transparency=GhostAlpha
                        end
                    elseif Obj:IsA("Decal") or Obj:IsA("Texture") then
                        Obj.Transparency=Obj.Transparency>=0.95 and 1 or GhostAlpha
                    elseif Obj:IsA("ProximityPrompt") or Obj:IsA("ClickDetector") or Obj:IsA("TouchTransmitter") then
                        pcall(function() Obj:Destroy() end)
                    end
                end

                local PH=Clone:FindFirstChildOfClass("Humanoid")
                local PR=Clone:FindFirstChild("HumanoidRootPart")
                if not PH or not PR then pcall(function() Clone:Destroy() end); return false end
                pcall(function()
                    PH.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None
                    PH.HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff
                    PH.AutoRotate=true
                    PH.PlatformStand=false
                    PH.Sit=false
                end)

                local SurfaceCF=S.SurfaceCFrame or Char:GetPivot()
                Clone.Parent=workspace
                pcall(function() Clone:PivotTo(SurfaceCF) end)
                PR.AssemblyLinearVelocity=Vector3.zero
                PR.AssemblyAngularVelocity=Vector3.zero

                S.ProxyCharacter=Clone
                S.ProxyHumanoid=PH
                S.ProxyRoot=PR
                S.Decoy=Clone
                S.ProxyActive=true
                S.ProxyTransparency=GhostAlpha
                S.LastSafeProxyCFrame=PR.CFrame
                S.ProxyAnimationTracks={}
                S.ProxyAnimationIds={}
                S.ProxyAnimationState=nil
                S.ProxyActionTracks={}
                S.LastProxyAnimationRefreshAt=0
                S.LastProxyActionSyncAt=0
                S.LastProxyHumanoidSyncAt=0
                S.ProxyRepairQueued=false
                S.BlinkInvisibility=true
                S.DirectMotorMirror=true
                S.CharacterSwappedToProxy=false
                S.NativeAnimateActive=false

                S.ProxyMotorPairs={}
                local ProxyMotors={}
                for _,Motor in ipairs(Clone:GetDescendants()) do
                    if Motor:IsA("Motor6D") then
                        local P0=Motor.Part0 and Motor.Part0.Name or ""
                        local P1=Motor.Part1 and Motor.Part1.Name or ""
                        ProxyMotors[Motor.Name.."|"..P0.."|"..P1]=Motor
                    end
                end
                for _,Motor in ipairs(Char:GetDescendants()) do
                    if Motor:IsA("Motor6D") then
                        local P0=Motor.Part0 and Motor.Part0.Name or ""
                        local P1=Motor.Part1 and Motor.Part1.Name or ""
                        local PM=ProxyMotors[Motor.Name.."|"..P0.."|"..P1]
                        if PM then table.insert(S.ProxyMotorPairs,{Real=Motor,Proxy=PM}) end
                    end
                end
                return true
            end

            Runtime.MM2ProxyAnimationSourceId=function(Key)
                local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                local Animate=RealChar and RealChar:FindFirstChild("Animate")
                Key=string.lower(tostring(Key or ""))
                local Keywords={
                    idle={"idle"}, walk={"walk"}, run={"run"}, jump={"jump"},
                    fall={"fall"}, climb={"climb"}, swim={"swim"}, swimidle={"swimidle"},
                }
                local Wanted=Keywords[Key] or {Key}
                local Best=nil
                if Animate then
                    for _,Obj in ipairs(Animate:GetDescendants()) do
                        if Obj:IsA("Animation") and Obj.AnimationId and Obj.AnimationId~="" then
                            local Name=string.lower((Obj.Parent and Obj.Parent.Name or "").." "..Obj.Name)
                            for _,Word in ipairs(Wanted) do
                                if string.find(Name,Word,1,true) then
                                    Best=Obj.AnimationId
                                    break
                                end
                            end
                            if Best then break end
                        end
                    end
                end

                if not Best and RealChar then
                    local RH=RealChar:FindFirstChildOfClass("Humanoid")
                    local Animator=RH and RH:FindFirstChildOfClass("Animator")
                    if Animator then
                        local Ok,Playing=pcall(function() return Animator:GetPlayingAnimationTracks() end)
                        if Ok then
                            for _,Track in ipairs(Playing or {}) do
                                local Anim=Track.Animation
                                local Name=string.lower((Track.Name or "").." "..(Anim and Anim.Name or ""))
                                for _,Word in ipairs(Wanted) do
                                    if string.find(Name,Word,1,true) and Anim and Anim.AnimationId and Anim.AnimationId~="" then
                                        Best=Anim.AnimationId
                                        break
                                    end
                                end
                                if Best then break end
                            end
                        end
                    end
                end
                return Best
            end

            Runtime.MM2RefreshProxyAnimations=function(Force)
                local S=Runtime.MM2InvisibleState
                local H=S.ProxyHumanoid
                if not State.MM2Invisible or not S.ProxyActive or not H or not H.Parent then return end
                if S.DirectMotorMirror or S.NativeAnimateActive then return end
                local Animator=H:FindFirstChildOfClass("Animator")
                if not Animator then
                    Animator=Instance.new("Animator")
                    Animator.Parent=H
                end
                S.ProxyAnimationTracks=S.ProxyAnimationTracks or {}
                S.ProxyAnimationIds=S.ProxyAnimationIds or {}
                local Specs={
                    idle={Priority=Enum.AnimationPriority.Idle,Looped=true},
                    walk={Priority=Enum.AnimationPriority.Movement,Looped=true},
                    run={Priority=Enum.AnimationPriority.Movement,Looped=true},
                    jump={Priority=Enum.AnimationPriority.Action,Looped=false},
                    fall={Priority=Enum.AnimationPriority.Movement,Looped=true},
                    climb={Priority=Enum.AnimationPriority.Movement,Looped=true},
                    swim={Priority=Enum.AnimationPriority.Movement,Looped=true},
                    swimidle={Priority=Enum.AnimationPriority.Idle,Looped=true},
                }
                for Key,Spec in pairs(Specs) do
                    local Id=Runtime.MM2ProxyAnimationSourceId(Key)
                    if Id and (Force or S.ProxyAnimationIds[Key]~=Id or not S.ProxyAnimationTracks[Key]) then
                        local Old=S.ProxyAnimationTracks[Key]
                        if Old then
                            pcall(function() Old:Stop(0.08) end)
                            pcall(function() Old:Destroy() end)
                        end
                        local Anim=Instance.new("Animation")
                        Anim.Name="__BananiProxyAnim_"..Key
                        Anim.AnimationId=Id
                        local Ok,Track=pcall(function() return Animator:LoadAnimation(Anim) end)
                        pcall(function() Anim:Destroy() end)
                        if Ok and Track then
                            pcall(function()
                                Track.Priority=Spec.Priority
                                Track.Looped=Spec.Looped
                            end)
                            S.ProxyAnimationTracks[Key]=Track
                            S.ProxyAnimationIds[Key]=Id
                        end
                    end
                end
            end

            Runtime.MM2UpdateProxyAnimation=function()
                local S=Runtime.MM2InvisibleState
                local H=S.ProxyHumanoid
                if not State.MM2Invisible or not S.ProxyActive or not H or not H.Parent then return end
                if S.DirectMotorMirror or S.NativeAnimateActive then return end
                local Tracks=S.ProxyAnimationTracks or {}
                local HumanoidState=H:GetState()
                local Speed=H.MoveDirection.Magnitude*math.max(tonumber(H.WalkSpeed) or 16,1)
                local Next="idle"
                if HumanoidState==Enum.HumanoidStateType.Jumping then Next="jump"
                elseif HumanoidState==Enum.HumanoidStateType.Freefall or HumanoidState==Enum.HumanoidStateType.FallingDown then Next="fall"
                elseif HumanoidState==Enum.HumanoidStateType.Climbing then Next="climb"
                elseif HumanoidState==Enum.HumanoidStateType.Swimming then Next=Speed>0.8 and "swim" or "swimidle"
                elseif Speed>0.8 then Next=(Speed>=math.max(18,(tonumber(H.WalkSpeed) or 16)*0.82) and Tracks.run) and "run" or "walk" end
                local Current=S.ProxyAnimationState
                if Current~=Next then
                    local Old=Current and Tracks[Current]
                    if Old then pcall(function() Old:Stop(0.10) end) end
                    local Track=Tracks[Next]
                    if Track and not Track.IsPlaying then pcall(function() Track:Play(0.10,1,1) end) end
                    S.ProxyAnimationState=Next
                end
                local Active=Tracks[Next]
                if Active and Active.IsPlaying then
                    local Rate=1
                    if Next=="walk" or Next=="run" then Rate=math.clamp(Speed/16,0.55,2.0)
                    elseif Next=="climb" then Rate=math.clamp(Speed/8,0.6,1.8) end
                    pcall(function() Active:AdjustSpeed(Rate) end)
                end
            end

            Runtime.MM2MirrorActionAnimations=function()
                local S=Runtime.MM2InvisibleState
                if S.DirectMotorMirror then return end
                if not State.MM2Invisible or not S.ProxyActive then return end
                local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                local RH=RealChar and RealChar:FindFirstChildOfClass("Humanoid")
                local RA=RH and RH:FindFirstChildOfClass("Animator")
                local PH=S.ProxyHumanoid
                local PA=PH and PH:FindFirstChildOfClass("Animator")
                if not RA or not PA then return end
                S.ProxyActionTracks=S.ProxyActionTracks or {}
                local Seen={}
                local Ok,Playing=pcall(function() return RA:GetPlayingAnimationTracks() end)
                if Ok then
                    for _,RealTrack in ipairs(Playing or {}) do
                        local Priority=RealTrack.Priority
                        local IsAction=Priority==Enum.AnimationPriority.Action or Priority==Enum.AnimationPriority.Action2
                            or Priority==Enum.AnimationPriority.Action3 or Priority==Enum.AnimationPriority.Action4
                        local Anim=RealTrack.Animation
                        local Id=Anim and Anim.AnimationId
                        if IsAction and Id and Id~="" then
                            Seen[Id]=true
                            local Track=S.ProxyActionTracks[Id]
                            if not Track then
                                local A=Instance.new("Animation"); A.AnimationId=Id
                                local LoadedOk,Loaded=pcall(function() return PA:LoadAnimation(A) end)
                                pcall(function() A:Destroy() end)
                                if LoadedOk and Loaded then
                                    Track=Loaded; S.ProxyActionTracks[Id]=Track
                                    pcall(function() Track.Priority=Priority; Track.Looped=RealTrack.Looped end)
                                end
                            end
                            if Track then
                                if not Track.IsPlaying then pcall(function() Track:Play(0.03,1,math.max(RealTrack.Speed,0.05)) end) end
                                pcall(function() Track.TimePosition=RealTrack.TimePosition end)
                                pcall(function() Track:AdjustSpeed(math.max(RealTrack.Speed,0.05)) end)
                            end
                        end
                    end
                end
                for Id,Track in pairs(S.ProxyActionTracks) do
                    if not Seen[Id] then
                        if Track then
                            pcall(function() Track:Stop(0.05) end)
                            pcall(function() Track:Destroy() end)
                        end
                        S.ProxyActionTracks[Id]=nil
                    end
                end
            end

            Runtime.MM2BindProxySignals=function()
                local S=Runtime.MM2InvisibleState
                Runtime.MM2DisconnectList(S.ProxySignalConnections)
                S.ProxySignalConnections={}
                local function Bind(Signal,Fn)
                    if not Signal then return nil end
                    local Ok,C=pcall(function() return Signal:Connect(Fn) end)
                    if Ok and C then table.insert(S.ProxySignalConnections,C); return C end
                end
                local ProxyH=S.ProxyHumanoid
                local ProxyChar=S.ProxyCharacter
                local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                local RealH=RealChar and RealChar:FindFirstChildOfClass("Humanoid")
                if not ProxyH or not ProxyChar or not RealH or RealChar~=S.Character then return end

                Bind(ProxyH.Running,function() Runtime.MM2UpdateProxyAnimation() end)
                Bind(ProxyH.StateChanged,function() Runtime.MM2UpdateProxyAnimation() end)
                Bind(ProxyH.Climbing,function() Runtime.MM2UpdateProxyAnimation() end)
                Bind(ProxyH.Swimming,function() Runtime.MM2UpdateProxyAnimation() end)
                Bind(ProxyH.Died,function()
                    task.defer(function()
                        local RC=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                        local RH=RC and RC:FindFirstChildOfClass("Humanoid")
                        if State.MM2Invisible and RH and RH.Health>0 and Runtime.MM2RepairProxy then Runtime.MM2RepairProxy(true) end
                    end)
                end)
                Bind(RealH.HealthChanged,function(Health)
                    local PH=S.ProxyHumanoid
                    if PH and PH.Parent then pcall(function() PH.MaxHealth=RealH.MaxHealth; PH.Health=math.clamp(Health,0,RealH.MaxHealth) end) end
                end)
                Bind(RealH.Died,function()
                    task.defer(function()
                        if not State.MM2Invisible or S.Character~=RealChar then return end
                        S.SurfaceCFrame=(S.ProxyRoot and S.ProxyRoot.Parent and S.ProxyRoot.CFrame) or S.SurfaceCFrame
                        S.ProxyActive=false
                        Runtime.MM2DestroyInvisibleDecoy()
                        Runtime.MM2RestoreCamera(RealH)
                    end)
                end)
                Bind(RealChar.DescendantAdded,function(Obj)
                    if not State.MM2Invisible or S.Character~=RealChar then return end
                    if Obj:IsA("BasePart") then Runtime.MM2ApplyHiddenRealPart(Obj)
                    elseif Obj:IsA("Tool") then task.defer(function() if State.MM2Invisible then Runtime.MM2SyncProxyTool(true) end end) end
                end)
                Bind(RealChar.DescendantRemoving,function(Obj)
                    if Obj:IsA("Tool") then task.defer(function() if State.MM2Invisible then Runtime.MM2SyncProxyTool(true) end end) end
                end)
                local Backpack=Player:FindFirstChildOfClass("Backpack")
                if Backpack then
                    Bind(Backpack.ChildAdded,function(Obj)
                        if Obj:IsA("Tool") then task.defer(function() if State.MM2Invisible then Runtime.MM2SyncProxyTool(true) end end) end
                    end)
                    Bind(Backpack.ChildRemoved,function(Obj)
                        if Obj:IsA("Tool") then task.defer(function() if State.MM2Invisible then Runtime.MM2SyncProxyTool(true) end end) end
                    end)
                end
                local RA=RealH:FindFirstChildOfClass("Animator")
                if RA then Bind(RA.AnimationPlayed,function() task.defer(function() if State.MM2Invisible then Runtime.MM2MirrorActionAnimations() end end) end) end
                local Animate=RealChar:FindFirstChild("Animate")
                if Animate then
                    Bind(Animate.DescendantAdded,function() task.defer(function() if State.MM2Invisible then Runtime.MM2RefreshProxyAnimations(false) end end) end)
                    Bind(Animate.DescendantRemoving,function() task.defer(function() if State.MM2Invisible then Runtime.MM2RefreshProxyAnimations(false) end end) end)
                end
            end

            Runtime.MM2ClearProxyToolVisual=function()
                local S=Runtime.MM2InvisibleState
                if S.ProxyToolSource and S.ProxyToolSource.Parent and S.ProxyToolManualActivationBackup~=nil then
                    pcall(function() S.ProxyToolSource.ManualActivationOnly=S.ProxyToolManualActivationBackup end)
                end
                if S.ProxyToolVisual then pcall(function() S.ProxyToolVisual:Destroy() end) end
                S.ProxyToolVisual=nil
                S.ProxyToolSource=nil
                S.ProxyToolHandle=nil
                S.ProxyToolWeld=nil
                S.ProxyToolManualActivationBackup=nil
            end

            Runtime.MM2ProxyHand=function(Char)
                if not Char then return nil end
                return Char:FindFirstChild("RightHand")
                    or Char:FindFirstChild("Right Arm")
                    or Char:FindFirstChild("RightLowerArm")
                    or Char:FindFirstChild("RightUpperArm")
            end

            Runtime.MM2ApplyProxyTransparency=function(Container)
                if not Container then return end
                local Alpha=tonumber(Runtime.MM2InvisibleState.ProxyTransparency) or 0.50
                for _,Obj in ipairs(Container:GetDescendants()) do
                    if Obj:IsA("BasePart") then
                        Obj.CastShadow=false
                        Obj.LocalTransparencyModifier=0
                        if Obj.Name=="HumanoidRootPart" or Obj.Transparency>=0.95 then
                            Obj.Transparency=1
                        else
                            Obj.Transparency=Alpha
                        end
                    elseif Obj:IsA("Decal") or Obj:IsA("Texture") then
                        Obj.Transparency=Obj.Transparency>=0.95 and 1 or Alpha
                    end
                end
            end

            Runtime.MM2SyncProxyTool=function(Force)
                local S=Runtime.MM2InvisibleState
                local ProxyChar=S.ProxyCharacter
                local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                if not State.MM2Invisible or not S.ProxyActive or not ProxyChar or not ProxyChar.Parent or not RealChar then
                    Runtime.MM2ClearProxyToolVisual()
                    return nil
                end

                local Tool=RealChar:FindFirstChildOfClass("Tool")
                if not Tool then
                    Runtime.MM2ClearProxyToolVisual()
                    return nil
                end

                if not Force and S.ProxyToolSource==Tool and S.ProxyToolVisual and S.ProxyToolVisual.Parent==ProxyChar then
                    return S.ProxyToolVisual
                end

                Runtime.MM2ClearProxyToolVisual()

                local OldArchivable=Tool.Archivable
                pcall(function() Tool.Archivable=true end)
                local Ok,Visual=pcall(function() return Tool:Clone() end)
                pcall(function() Tool.Archivable=OldArchivable end)
                if not Ok or not Visual then return nil end

                Visual.Name="__BananiProxyTool_"..Tool.Name
                pcall(function()
                    Visual.ManualActivationOnly=true
                    Visual.CanBeDropped=false
                end)

                for _,Obj in ipairs(Visual:GetDescendants()) do
                    if Obj:IsA("BaseScript") or Obj:IsA("RemoteEvent") or Obj:IsA("RemoteFunction")
                        or Obj:IsA("ProximityPrompt") or Obj:IsA("ClickDetector") or Obj:IsA("TouchTransmitter") then
                        pcall(function() Obj:Destroy() end)
                    elseif Obj:IsA("BasePart") then
                        Obj.Anchored=false
                        Obj.CanCollide=false
                        Obj.CanTouch=false
                        Obj.CanQuery=false
                        Obj.Massless=true
                        Obj.CastShadow=false
                    end
                end

                local ProxyHand=Runtime.MM2ProxyHand(ProxyChar)
                local RealHand=Runtime.MM2ProxyHand(RealChar)
                local ProxyHandle=Visual:FindFirstChild("Handle",true)
                local RealHandle=Tool:FindFirstChild("Handle",true)
                if not ProxyHand or not ProxyHandle or not ProxyHandle:IsA("BasePart") then
                    pcall(function() Visual:Destroy() end)
                    return nil
                end

                Visual.Parent=ProxyChar
                Runtime.MM2ApplyProxyTransparency(Visual)

                local Offset=CFrame.new()
                if RealHand and RealHandle and RealHandle:IsA("BasePart") then
                    pcall(function() Offset=RealHand.CFrame:ToObjectSpace(RealHandle.CFrame) end)
                else
                    pcall(function() Offset=Tool.Grip end)
                end
                pcall(function() ProxyHandle.CFrame=ProxyHand.CFrame*Offset end)

                local ExistingGrip=ProxyHand:FindFirstChild("RightGrip")
                if ExistingGrip and (ExistingGrip:IsA("Motor6D") or ExistingGrip:IsA("Weld")) then
                    pcall(function() ExistingGrip:Destroy() end)
                end
                local Weld=Instance.new("WeldConstraint")
                Weld.Name="__BananiProxyRightGrip"
                Weld.Part0=ProxyHand
                Weld.Part1=ProxyHandle
                Weld.Parent=ProxyHandle

                S.ProxyToolManualActivationBackup=Tool.ManualActivationOnly
                pcall(function() Tool.ManualActivationOnly=true end)
                S.ProxyToolSource=Tool
                S.ProxyToolVisual=Visual
                S.ProxyToolHandle=ProxyHandle
                S.ProxyToolWeld=Weld
                return Visual
            end

            Runtime.MM2RealHumanoid=function()
                local C=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                return C and C:FindFirstChildOfClass("Humanoid") or nil
            end

            Runtime.MM2WeaponKind=function(Tool)
                if not Tool or not Tool:IsA("Tool") then return nil end
                local Lower=string.lower(Tool.Name)
                if string.find(Lower,"gun",1,true) or string.find(Lower,"revolver",1,true)
                    or string.find(Lower,"pistol",1,true) or string.find(Lower,"sheriff",1,true) then
                    return "gun"
                end
                if string.find(Lower,"knife",1,true) or string.find(Lower,"blade",1,true) then
                    return "knife"
                end
                for _,Obj in ipairs(Tool:GetDescendants()) do
                    if Obj:IsA("RemoteEvent") or Obj:IsA("RemoteFunction") then
                        local N=string.lower(Obj.Name)
                        if string.find(N,"shoot",1,true) or string.find(N,"gun",1,true) or string.find(N,"fire",1,true) then
                            return "gun"
                        elseif string.find(N,"throw",1,true) or string.find(N,"stab",1,true) or string.find(N,"slash",1,true) then
                            return "knife"
                        end
                    end
                end
                return nil
            end

            Runtime.MM2EquipRealTool=function(Tool)
                if not Tool or not Tool:IsA("Tool") then return false end
                local H=Runtime.MM2RealHumanoid()
                local C=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                if not H or not C then return false end
                local Ok=pcall(function() H:EquipTool(Tool) end)
                if Ok then
                    local S=Runtime.MM2InvisibleState
                    S.ProxyWeaponKind=Runtime.MM2WeaponKind(Tool) or S.ProxyWeaponKind
                    task.defer(function()
                        if State.MM2Invisible and not Unloaded then Runtime.MM2SyncProxyTool(true) end
                    end)
                end
                return Ok
            end

            Runtime.MM2EquippedRealTool=function()
                local C=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                return C and C:FindFirstChildOfClass("Tool") or nil
            end

            Runtime.MM2OwnedWeapon=function(Kind)
                Kind=string.lower(tostring(Kind or ""))
                if Kind~="gun" and Kind~="knife" then return nil end
                local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                local Backpack=Player:FindFirstChildOfClass("Backpack")
                for _,Container in ipairs({RealChar,Backpack}) do
                    if Container then
                        for _,Obj in ipairs(Container:GetChildren()) do
                            if Obj:IsA("Tool") and Runtime.MM2WeaponKind(Obj)==Kind then
                                return Obj
                            end
                        end
                    end
                end
                return nil
            end

            Runtime.MM2EquipOwnedWeapon=function(Kind,Timeout)
                Kind=string.lower(tostring(Kind or ""))
                if Kind~="gun" and Kind~="knife" then return nil end
                local Deadline=os.clock()+math.max(0,tonumber(Timeout) or 0)
                repeat
                    local Tool=Runtime.MM2OwnedWeapon(Kind)
                    if Tool then
                        local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                        local Equipped=(Tool.Parent==RealChar)
                        if not Equipped then
                            Runtime.MM2EquipRealTool(Tool)
                            task.wait()
                        end
                        local Current=Runtime.MM2OwnedWeapon(Kind) or Tool
                        local S=Runtime.MM2InvisibleState
                        S.ProxyWeaponKind=Kind
                        if State.MM2Invisible then Runtime.MM2SyncProxyTool(true) end
                        return Current
                    end
                    if os.clock()>=Deadline then break end
                    task.wait(0.03)
                until not State.MM2Invisible or Unloaded
                return nil
            end

            Runtime.MM2PickupWeaponFromProxy=function(Object,Kind)
                if not State.MM2Invisible or not Object or not Object.Parent then return false,nil end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then return false,nil end
                Kind=string.lower(tostring(Kind or ""))
                if Kind~="gun" and Kind~="knife" then return false,nil end
                local S=Runtime.MM2InvisibleState
                if S.WeaponPickupBusy or S.ProxyCoinBusy or S.SurfaceActionActive then return false,nil end
                if Runtime.MM2ObjectInActiveMap and not Runtime.MM2ObjectInActiveMap(Object,45) then return false,nil end
                S.WeaponPickupDebounce=S.WeaponPickupDebounce or setmetatable({}, {__mode="k"})

                local Existing=Runtime.MM2OwnedWeapon(Kind)
                if Existing then
                    local Equipped=Runtime.MM2EquipOwnedWeapon(Kind,0)
                    return Equipped~=nil,Equipped
                end

                local Now=os.clock()
                local Last=tonumber(S.WeaponPickupDebounce[Object]) or 0
                if Now-Last<0.55 or S.WeaponPickupBusy then return false,nil end
                S.WeaponPickupDebounce[Object]=Now
                S.WeaponPickupBusy=true

                local Success,PickedTool=false,nil
                local Worked=pcall(function()
                    local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                    local RealRoot=RealChar and RealChar:FindFirstChild("HumanoidRootPart")
                    local ProxyRoot=S.ProxyRoot
                    if not RealChar or not RealRoot or not ProxyRoot or not ProxyRoot.Parent then return end

                    local TouchParts={}
                    local SeenParts={}
                    local function AddPart(Part,First)
                        if Part and Part:IsA("BasePart") and Part.Parent and not SeenParts[Part] then
                            SeenParts[Part]=true
                            if First then table.insert(TouchParts,1,Part) else table.insert(TouchParts,Part) end
                        end
                    end

                    if Object:IsA("BasePart") then AddPart(Object,Object:FindFirstChildOfClass("TouchTransmitter")~=nil) end
                    for _,Obj in ipairs(Object:GetDescendants()) do
                        if Obj:IsA("BasePart") then
                            local L=string.lower(Obj.Name)
                            local Trigger=Obj:FindFirstChildOfClass("TouchTransmitter")~=nil
                                or string.find(L,"pickup",1,true)~=nil
                                or string.find(L,"drop",1,true)~=nil
                                or string.find(L,"hitbox",1,true)~=nil
                                or string.find(L,"trigger",1,true)~=nil
                            AddPart(Obj,Trigger)
                            if #TouchParts>=20 then break end
                        end
                    end
                    local ObjectRoot=nil
                    pcall(function() ObjectRoot=GetRoot(Object) end)
                    AddPart(ObjectRoot,false)
                    if #TouchParts==0 then return end

                    local function TriggerNearbyInteraction()
                        local Nodes={Object}
                        for _,Node in ipairs(Object:GetDescendants()) do table.insert(Nodes,Node) end
                        for _,Node in ipairs(Nodes) do
                            if Node:IsA("ProximityPrompt") and Node.Enabled and type(fireproximityprompt)=="function" then
                                pcall(function() fireproximityprompt(Node) end)
                            elseif Node:IsA("ClickDetector") and type(fireclickdetector)=="function" then
                                pcall(function() fireclickdetector(Node) end)
                            end
                        end
                    end

                    Runtime.MM2WithSurfaceShell(function()
                        local TargetPart=TouchParts[1]
                        if not TargetPart or not TargetPart.Parent then return end
                        local TargetBackup={}
                        for _,Part in ipairs(TouchParts) do
                            if Part and Part.Parent then
                                TargetBackup[Part]={CanTouch=Part.CanTouch,CanQuery=Part.CanQuery}
                                pcall(function() Part.CanTouch=true; Part.CanQuery=true end)
                            end
                        end

                        local Sources={}
                        for _,Name in ipairs({"HumanoidRootPart","UpperTorso","Torso","LowerTorso","Head","RightFoot","LeftFoot","RightHand","LeftHand"}) do
                            local P=RealChar:FindFirstChild(Name)
                            if P and P:IsA("BasePart") and not table.find(Sources,P) then table.insert(Sources,P) end
                        end
                        if #Sources==0 then table.insert(Sources,RealRoot) end

                        local Rotation=ProxyRoot.CFrame.Rotation

                        local Sweep={
                            Vector3.new(0,2.4,0),
                            Vector3.new(0,1.0,0),
                            Vector3.new(0,0.15,0),
                            Vector3.new(0,-0.85,0),
                            Vector3.new(0,0.10,0),
                            Vector3.new(0,1.0,0),
                        }
                        for _,Offset in ipairs(Sweep) do
                            if not Object.Parent or not TargetPart.Parent then break end
                            pcall(function()
                                RealChar:PivotTo(CFrame.new(TargetPart.Position+Offset)*Rotation)
                                RealRoot.AssemblyLinearVelocity=Vector3.zero
                                RealRoot.AssemblyAngularVelocity=Vector3.zero
                            end)
                            RunService.Stepped:Wait()
                            if type(firetouchinterest)=="function" then
                                for _,Source in ipairs(Sources) do
                                    for _,Part in ipairs(TouchParts) do
                                        if Source.Parent and Part.Parent then
                                            pcall(function() firetouchinterest(Source,Part,0) end)
                                        end
                                    end
                                end
                            end
                            TriggerNearbyInteraction()
                            RunService.Heartbeat:Wait()
                            if Runtime.MM2OwnedWeapon(Kind) then break end
                        end

                        if type(firetouchinterest)=="function" then
                            for _,Source in ipairs(Sources) do
                                for _,Part in ipairs(TouchParts) do
                                    if Source.Parent and Part.Parent then
                                        pcall(function() firetouchinterest(Source,Part,1) end)
                                    end
                                end
                            end
                        end
                        for _=1,5 do
                            if Runtime.MM2OwnedWeapon(Kind) then break end
                            RunService.Heartbeat:Wait()
                        end
                        for Part,Backup in pairs(TargetBackup) do
                            if Part and Part.Parent then
                                pcall(function()
                                    Part.CanTouch=Backup.CanTouch
                                    Part.CanQuery=Backup.CanQuery
                                end)
                            end
                        end
                    end,0.20,5)

                    local Deadline=os.clock()+2.75
                    local Tool=nil
                    repeat
                        Tool=Runtime.MM2OwnedWeapon(Kind)
                        if Tool then break end
                        task.wait(0.04)
                    until os.clock()>=Deadline or not State.MM2Invisible or Unloaded

                    if not Tool then return end
                    Tool=Runtime.MM2EquipOwnedWeapon(Kind,0.35) or Tool
                    S.ProxyWeaponKind=Kind
                    Runtime.MM2SyncProxyTool(true)
                    Success=true
                    PickedTool=Tool
                end)
                S.WeaponPickupBusy=false
                if not Worked then return false,nil end
                return Success,PickedTool
            end

            Runtime.MM2FindNearbyWeaponPickup=function(PreferredKind,Radius)
                if not State.MM2Invisible then return nil,nil end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then return nil,nil end
                local Pos=Runtime.MM2SurfacePosition()
                if not Pos then return nil,nil end
                PreferredKind=PreferredKind and string.lower(tostring(PreferredKind)) or nil
                Radius=math.clamp(tonumber(Radius) or 5.5,2,10)
                local Params=OverlapParams.new()
                Params.FilterType=Enum.RaycastFilterType.Exclude
                Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                local Ok,Parts=pcall(function() return workspace:GetPartBoundsInRadius(Pos,Radius,Params) end)
                if not Ok then return nil,nil end

                local BestObject,BestKind,BestDistance=nil,nil,math.huge
                local Seen={}
                local function LowerName(Obj)
                    return Obj and string.lower(tostring(Obj.Name or "")) or ""
                end
                local function HasPickupWord(Text)
                    return string.find(Text,"drop",1,true) or string.find(Text,"pickup",1,true)
                        or string.find(Text,"throwingknife",1,true) or string.find(Text,"sheriffgun",1,true)
                end
                for _,Part in ipairs(Parts or {}) do
                    if Part and Part.Parent then
                        local ToolAncestor=Part:FindFirstAncestorWhichIsA("Tool")
                        local Parent=Part.Parent
                        local ModelAncestor=Part:FindFirstAncestorOfClass("Model")
                        local PartName=LowerName(Part)
                        local ParentName=LowerName(Parent)
                        local ModelName=LowerName(ModelAncestor)
                        local Text=PartName.." "..ParentName.." "..ModelName
                        local LooksDropped=ToolAncestor~=nil or HasPickupWord(Text)
                        local Kind=nil
                        if LooksDropped and (string.find(Text,"gun",1,true) or string.find(Text,"sheriff",1,true)
                            or string.find(Text,"revolver",1,true) or string.find(Text,"pistol",1,true)) then
                            Kind="gun"
                        elseif LooksDropped and (string.find(Text,"knife",1,true) or string.find(Text,"blade",1,true)) then
                            Kind="knife"
                        end
                        if Kind and (not PreferredKind or PreferredKind==Kind) then
                            local Candidate=ToolAncestor
                            if not Candidate then
                                if HasPickupWord(ParentName) or string.find(ParentName,Kind,1,true) then
                                    Candidate=Parent
                                elseif HasPickupWord(PartName) or string.find(PartName,Kind,1,true) then
                                    Candidate=Part
                                elseif ModelAncestor and (HasPickupWord(ModelName) or string.find(ModelName,Kind,1,true)) then
                                    Candidate=ModelAncestor
                                end
                            end
                            if Candidate and not Seen[Candidate]
                                and (not Runtime.MM2ObjectInActiveMap or Runtime.MM2ObjectInActiveMap(Candidate,45)) then
                                Seen[Candidate]=true
                                local Dist=(Part.Position-Pos).Magnitude
                                if Dist<BestDistance then
                                    BestObject,BestKind,BestDistance=Candidate,Kind,Dist
                                end
                            end
                        end
                    end
                end
                return BestObject,BestKind
            end

            Runtime.MM2RealCharacter=function()
                local S=Runtime.MM2InvisibleState
                if S and S.Character and S.Character.Parent then return S.Character end
                local Current=Player.Character
                if Current and (not S or Current~=S.ProxyCharacter) then return Current end
                return nil
            end

            Runtime.MM2WithSurfaceShell=function(Callback,HoldSeconds,WarmupFrames,RelayCFrame)
                if type(Callback)~="function" then return false end
                local S=Runtime.MM2InvisibleState
                local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                local RealRoot=RealChar and RealChar:FindFirstChild("HumanoidRootPart")
                local RealHumanoid=RealChar and RealChar:FindFirstChildOfClass("Humanoid")
                local ProxyRoot=S.ProxyRoot
                local ProxyHumanoid=S.ProxyHumanoid
                if not State.MM2Invisible or not S.ProxyActive or not RealChar or not RealRoot
                    or not ProxyRoot or not ProxyRoot.Parent then
                    return pcall(Callback)
                end

                if S.BlinkInvisibility then
                    local SurfaceCF=S.SurfaceCFrame or S.BlinkSurfaceCFrame or RealRoot.CFrame
                    local RelayCF=typeof(RelayCFrame)=="CFrame" and RelayCFrame or SurfaceCF
                    S.SurfaceRelayDepth=(tonumber(S.SurfaceRelayDepth) or 0)+1
                    S.SurfaceActionActive=true
                    S.BlinkSuspendUntil=math.max(tonumber(S.BlinkSuspendUntil) or 0,os.clock()+math.max(0.18,tonumber(HoldSeconds) or 0)+0.35)
                    if S.BlinkHidden and Runtime.MM2RestoreBlinkSurface then
                        Runtime.MM2RestoreBlinkSurface(RealChar,RealHumanoid,RealRoot,SurfaceCF)
                    else
                        Runtime.MM2SetBlinkPhysicsMuted(RealChar,false)
                    end
                    local ActionLinear=RealRoot.AssemblyLinearVelocity
                    local ActionAngular=RealRoot.AssemblyAngularVelocity
                    pcall(function()
                        RealChar:PivotTo(RelayCF)
                        RealRoot.AssemblyLinearVelocity=ActionLinear
                        RealRoot.AssemblyAngularVelocity=ActionAngular
                        if RealHumanoid and S.BlinkBaseCameraOffset then RealHumanoid.CameraOffset=S.BlinkBaseCameraOffset end
                    end)
                    local Frames=math.clamp(math.floor(tonumber(WarmupFrames) or 0),0,10)
                    for _=1,Frames do
                        if not State.MM2Invisible then break end
                        RunService.Stepped:Wait(); RunService.Heartbeat:Wait()
                    end
                    local Packed=table.pack(pcall(Callback))
                    local Hold=math.clamp(tonumber(HoldSeconds) or 0,0,0.75)
                    local Until=os.clock()+Hold
                    while Hold>0 and os.clock()<Until and State.MM2Invisible do RunService.Heartbeat:Wait() end
                    if State.MM2Invisible and RealChar.Parent then
                        pcall(function()
                            RealChar:PivotTo(SurfaceCF)
                            RealRoot.AssemblyLinearVelocity=ActionLinear
                            RealRoot.AssemblyAngularVelocity=ActionAngular
                        end)
                    end
                    Runtime.MM2SetBlinkPhysicsMuted(RealChar,false)
                    S.BlinkSurfaceCFrame=SurfaceCF; S.SurfaceCFrame=SurfaceCF; S.BlinkHidden=false
                    S.SurfaceRelayDepth=math.max(0,(tonumber(S.SurfaceRelayDepth) or 1)-1)
                    if S.SurfaceRelayDepth<=0 then S.SurfaceActionActive=false end
                    return table.unpack(Packed,1,Packed.n)
                end

                local OldLinear=RealRoot.AssemblyLinearVelocity
                local OldAngular=RealRoot.AssemblyAngularVelocity
                local HumanoidBackup=nil
                if RealHumanoid then
                    HumanoidBackup={
                        AutoRotate=RealHumanoid.AutoRotate,
                        WalkSpeed=RealHumanoid.WalkSpeed,
                        UseJumpPower=RealHumanoid.UseJumpPower,
                        JumpPower=RealHumanoid.JumpPower,
                        JumpHeight=RealHumanoid.JumpHeight,
                        PlatformStand=RealHumanoid.PlatformStand,
                        Sit=RealHumanoid.Sit,
                    }
                end

                local RelayNow=os.clock()
                S.SurfaceRelayDepth=(tonumber(S.SurfaceRelayDepth) or 0)+1
                S.SurfaceActionActive=true
                S.SuppressServerTeleportUntil=math.max(tonumber(S.SuppressServerTeleportUntil) or 0,RelayNow+1.35)
                S.ServerTeleportIgnoreUntil=math.max(tonumber(S.ServerTeleportIgnoreUntil) or 0,RelayNow+1.40)
                S.PendingServerTeleportCFrame=nil
                S.PendingServerTeleportSince=nil
                S.PendingServerTeleportSamples=0

                if RealHumanoid then
                    pcall(function()
                        RealHumanoid.PlatformStand=false
                        RealHumanoid.Sit=false
                        RealHumanoid.AutoRotate=true
                        RealHumanoid.WalkSpeed=math.max(16,tonumber(ProxyHumanoid and ProxyHumanoid.WalkSpeed) or 16)
                        if RealHumanoid.UseJumpPower~=false then
                            RealHumanoid.JumpPower=math.max(50,tonumber(ProxyHumanoid and ProxyHumanoid.JumpPower) or 50)
                        else
                            RealHumanoid.JumpHeight=math.max(7.2,tonumber(ProxyHumanoid and ProxyHumanoid.JumpHeight) or 7.2)
                        end
                    end)
                end

                local PartRelayBackup={}
                for _,Part in ipairs(RealChar:GetDescendants()) do
                    if Part:IsA("BasePart") then
                        PartRelayBackup[Part]={
                            CanTouch=Part.CanTouch,
                            CanQuery=Part.CanQuery,
                            CanCollide=Part.CanCollide,
                        }
                        pcall(function()
                            Part.CanTouch=true
                            Part.CanQuery=true
                            Part.CanCollide=false
                        end)
                    end
                end

                local function ResolveRelayCFrame()
                    if typeof(RelayCFrame)=="CFrame" then return RelayCFrame,true end
                    return ProxyRoot.CFrame,false
                end

                local function PutShellAtRelay()
                    if not ProxyRoot or not ProxyRoot.Parent or not RealChar or not RealChar.Parent then return end
                    local CF,Fixed=ResolveRelayCFrame()
                    pcall(function()
                        RealChar:PivotTo(CF)
                        if Fixed then
                            RealRoot.AssemblyLinearVelocity=Vector3.zero
                            RealRoot.AssemblyAngularVelocity=Vector3.zero
                        else
                            RealRoot.AssemblyLinearVelocity=ProxyRoot.AssemblyLinearVelocity
                            RealRoot.AssemblyAngularVelocity=ProxyRoot.AssemblyAngularVelocity
                        end
                    end)
                end

                PutShellAtRelay()

                local Frames=math.clamp(math.floor(tonumber(WarmupFrames) or 0),0,12)
                for _=1,Frames do
                    if not State.MM2Invisible or not S.ProxyActive then break end
                    PutShellAtRelay()
                    RunService.Stepped:Wait()
                    RunService.Heartbeat:Wait()
                end

                local Packed=table.pack(pcall(Callback))

                local Hold=math.clamp(tonumber(HoldSeconds) or 0,0,0.60)
                local HoldUntil=os.clock()+Hold
                while Hold>0 and os.clock()<HoldUntil and State.MM2Invisible and S.ProxyActive do
                    PutShellAtRelay()
                    RunService.Heartbeat:Wait()
                end

                for Part,Backup in pairs(PartRelayBackup) do
                    if Part and Part.Parent then
                        pcall(function()
                            Part.CanTouch=Backup.CanTouch
                            Part.CanQuery=Backup.CanQuery
                            Part.CanCollide=Backup.CanCollide
                        end)
                    end
                end
                if RealHumanoid and HumanoidBackup then
                    pcall(function()
                        RealHumanoid.AutoRotate=HumanoidBackup.AutoRotate
                        RealHumanoid.WalkSpeed=HumanoidBackup.WalkSpeed
                        RealHumanoid.PlatformStand=HumanoidBackup.PlatformStand
                        RealHumanoid.Sit=HumanoidBackup.Sit
                        if HumanoidBackup.UseJumpPower~=false then
                            RealHumanoid.JumpPower=HumanoidBackup.JumpPower
                        else
                            RealHumanoid.JumpHeight=HumanoidBackup.JumpHeight
                        end
                    end)
                end

                S.SurfaceRelayDepth=math.max(0,(tonumber(S.SurfaceRelayDepth) or 1)-1)
                if S.SurfaceRelayDepth<=0 then S.SurfaceActionActive=false end

                if S.SurfaceRelayDepth==0 and State.MM2Invisible and S.ProxyActive and ProxyRoot.Parent and RealChar.Parent then
                    local Hidden=CFrame.new(ProxyRoot.Position-Vector3.new(0,tonumber(S.Depth) or 25,0))*ProxyRoot.CFrame.Rotation
                    local WriteNow=os.clock()
                    S.LastForcedShellCFrame=Hidden
                    S.LastShellWriteAt=WriteNow
                    S.SuppressServerTeleportUntil=math.max(tonumber(S.SuppressServerTeleportUntil) or 0,WriteNow+0.70)
                    S.ServerTeleportIgnoreUntil=math.max(tonumber(S.ServerTeleportIgnoreUntil) or 0,WriteNow+0.80)
                    S.RecentShellWrites=S.RecentShellWrites or {}
                    table.insert(S.RecentShellWrites,{Position=Hidden.Position,At=WriteNow})
                    while #S.RecentShellWrites>18 do table.remove(S.RecentShellWrites,1) end
                    pcall(function()
                        RealChar:PivotTo(Hidden)
                        RealRoot.AssemblyLinearVelocity=Vector3.zero
                        RealRoot.AssemblyAngularVelocity=Vector3.zero
                    end)
                else
                    pcall(function()
                        RealRoot.AssemblyLinearVelocity=OldLinear
                        RealRoot.AssemblyAngularVelocity=OldAngular
                    end)
                end
                return table.unpack(Packed,1,Packed.n)
            end

            Runtime.MM2SurfaceCFrame=function()
                local S=Runtime.MM2InvisibleState
                if State.MM2Invisible then
                    if S.ProxyActive and S.ProxyRoot and S.ProxyRoot.Parent then
                        S.SurfaceCFrame=S.ProxyRoot.CFrame
                        return S.SurfaceCFrame
                    end

                    if typeof(S.SurfaceCFrame)=="CFrame" then return S.SurfaceCFrame end
                    local C=Player.Character
                    local R=C and C:FindFirstChild("HumanoidRootPart")
                    if R then
                        local Depth=tonumber(S.Depth) or tonumber(State.MM2InvisibleDepth) or 25
                        return CFrame.new(R.Position+Vector3.new(0,Depth,0))*R.CFrame.Rotation
                    end
                    return nil
                end
                local C=Player.Character
                local R=C and C:FindFirstChild("HumanoidRootPart")
                return R and R.CFrame or nil
            end

            Runtime.MM2SurfacePosition=function()
                local CF=Runtime.MM2SurfaceCFrame()
                return CF and CF.Position or nil
            end

            Runtime.MM2SurfaceAimPosition=function(MaxDistance)
                local Cam=workspace.CurrentCamera or Camera
                if not Cam then return nil end
                local P=UserInputService:GetMouseLocation()
                local Ray=Cam:ViewportPointToRay(P.X,P.Y)
                local Params=RaycastParams.new()
                Params.FilterType=Enum.RaycastFilterType.Exclude
                Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                Params.IgnoreWater=true
                local Distance=tonumber(MaxDistance) or 1200
                local Hit=workspace:Raycast(Ray.Origin,Ray.Direction*Distance,Params)
                return Hit and Hit.Position or (Ray.Origin+Ray.Direction*Distance)
            end

            Runtime.MM2SurfaceInteract=function()
                if not State.MM2Invisible then return false end
                local S=Runtime.MM2InvisibleState
                if S.SurfaceActionActive or S.SurfaceWeaponBusy or S.WeaponPickupBusy or S.ProxyCoinBusy or S.InteractionSynchronizerBusy then return false end
                local Pos=Runtime.MM2SurfacePosition(); if not Pos then return false end
                if os.clock()-(tonumber(S.LastSurfaceInteract) or 0)<0.18 then return false end
                local Params=OverlapParams.new(); Params.FilterType=Enum.RaycastFilterType.Exclude
                Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                local Ok,Parts=pcall(function() return workspace:GetPartBoundsInRadius(Pos,14,Params) end)
                if not Ok then Parts={} end
                local Seen={} local Best,BestDist=nil,math.huge
                local function Consider(Node,Dist)
                    if not Node or Seen[Node] then return end; Seen[Node]=true
                    local Valid=false
                    if Node:IsA("ProximityPrompt") and Node.Enabled and type(fireproximityprompt)=="function" then
                        Valid=Dist<=math.max(2,tonumber(Node.MaxActivationDistance) or 10)+1
                    elseif Node:IsA("ClickDetector") and type(fireclickdetector)=="function" then
                        Valid=Dist<=math.max(2,tonumber(Node.MaxActivationDistance) or 10)+1
                    end
                    if Valid and Dist<BestDist then Best,BestDist=Node,Dist end
                end
                for _,Part in ipairs(Parts or {}) do
                    if Part and Part.Parent then
                        local Dist=(Part.Position-Pos).Magnitude
                        local Nodes={Part,Part.Parent,Part.Parent and Part.Parent.Parent}
                        for _,Node in ipairs(Nodes) do
                            if Node then
                                Consider(Node,Dist)
                                for _,Child in ipairs(Node:GetChildren()) do
                                    Consider(Child,Dist)
                                    if Child:IsA("Attachment") then for _,Grand in ipairs(Child:GetChildren()) do Consider(Grand,Dist) end end
                                end
                            end
                        end
                    end
                end
                if not Best then return false end
                local Fired=Runtime.MM2SynchronizeInteraction(Best,14,function()
                    if Best:IsA("ProximityPrompt") then fireproximityprompt(Best) else fireclickdetector(Best) end
                    return true
                end,{Name="interact",HoldSeconds=0.05,WarmupFrames=1})
                if Fired then S.LastSurfaceInteract=os.clock(); return true end
                return false
            end

            Runtime.MM2SurfaceTouchStep=function()
                if not State.MM2Invisible then return end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then return end
                local S=Runtime.MM2InvisibleState
                if S.SurfaceActionActive or S.SurfaceWeaponBusy or S.WeaponPickupBusy or S.ProxyCoinBusy or S.InteractionSynchronizerBusy then return end
                if os.clock()-(tonumber(S.LastSurfaceTouchAt) or 0)<0.12 then return end
                S.LastSurfaceTouchAt=os.clock()

                if Runtime.MM2FindNearbyWeaponPickup and Runtime.MM2PickupWeaponFromProxy then
                    local Object,Kind=Runtime.MM2FindNearbyWeaponPickup(nil,7.0)
                    if Object and Kind and not Runtime.MM2OwnedWeapon(Kind) then
                        local Picked=Runtime.MM2PickupWeaponFromProxy(Object,Kind)
                        if Picked then return end
                    end
                end
                if Runtime.MM2TryProxyCoinPickup and Runtime.MM2TryProxyCoinPickup(6.0) then return end
                if type(firetouchinterest)~="function" then return end

                local Pos=Runtime.MM2SurfacePosition(); local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                local RealRoot=RealChar and RealChar:FindFirstChild("HumanoidRootPart")
                if not Pos or not RealRoot then return end
                local Params=OverlapParams.new(); Params.FilterType=Enum.RaycastFilterType.Exclude
                Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                local Ok,Parts=pcall(function() return workspace:GetPartBoundsInRadius(Pos,4.5,Params) end)
                if not Ok then return end
                S.GenericPickupDebounce=S.GenericPickupDebounce or setmetatable({}, {__mode="k"})
                local Best,BestDist=nil,4.5
                for _,Part in ipairs(Parts or {}) do
                    if Part and Part.Parent then
                        local L=string.lower(Part.Name.." "..tostring(Part.Parent.Name))
                        local Weapon=string.find(L,"gun",1,true) or string.find(L,"knife",1,true) or string.find(L,"blade",1,true) or string.find(L,"sheriff",1,true)
                        local Coin=string.find(L,"coin",1,true) or string.find(L,"token",1,true)
                        local Pickup=(not Weapon) and (not Coin) and (Part:FindFirstAncestorWhichIsA("Tool")~=nil or string.find(L,"pickup",1,true) or string.find(L,"drop",1,true))
                        local Last=tonumber(S.GenericPickupDebounce[Part]) or 0
                        local D=(Part.Position-Pos).Magnitude
                        if Pickup and D<=BestDist and os.clock()-Last>=0.75 and (not Runtime.MM2ObjectInActiveMap or Runtime.MM2ObjectInActiveMap(Part,45)) then
                            Best,BestDist=Part,D
                        end
                    end
                end
                if not Best then return end
                S.GenericPickupDebounce[Best]=os.clock()
                Runtime.MM2SynchronizeInteraction(Best,5,function()
                    if not Best.Parent or not RealRoot.Parent then return false end
                    pcall(function() firetouchinterest(RealRoot,Best,0) end)
                    RunService.Heartbeat:Wait()
                    pcall(function() firetouchinterest(RealRoot,Best,1) end)
                    return true
                end,{Name="pickup",HoldSeconds=0.05,WarmupFrames=2})
            end

            Runtime.MM2SurfaceToolProxy=function(ForcedTarget,Action)
                if not State.MM2Invisible then return false end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then return false end
                local C=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character; if not C then return false end
                local S=Runtime.MM2InvisibleState
                local Tool=Runtime.MM2EquippedRealTool and Runtime.MM2EquippedRealTool() or C:FindFirstChildOfClass("Tool")

                if not Tool and Runtime.MM2EquipOwnedWeapon then
                    if S.ProxyWeaponKind then Tool=Runtime.MM2EquipOwnedWeapon(S.ProxyWeaponKind,0.05) end
                    if not Tool then Tool=Runtime.MM2EquipOwnedWeapon("gun",0.05) end
                    if not Tool then Tool=Runtime.MM2EquipOwnedWeapon("knife",0.05) end
                end

                if not Tool and Runtime.MM2FindNearbyWeaponPickup and Runtime.MM2PickupWeaponFromProxy then
                    local Object,PickupKind=Runtime.MM2FindNearbyWeaponPickup(nil,7.0)
                    if Object and PickupKind then
                        local Picked,PickedTool=Runtime.MM2PickupWeaponFromProxy(Object,PickupKind)
                        if Picked then Tool=PickedTool or Runtime.MM2EquippedRealTool() end
                    end
                end
                if not Tool then return false end
                Runtime.MM2SyncProxyTool(false)

                local Kind=(Runtime.MM2WeaponKind and Runtime.MM2WeaponKind(Tool)) or nil
                local Target=typeof(ForcedTarget)=="Vector3" and ForcedTarget or Runtime.MM2SurfaceAimPosition(1200)
                if not Target then return false end
                Action=tostring(Action or ((typeof(ForcedTarget)=="Vector3" and Kind=="knife") and "throw" or "primary"))

                local function Relay(Fn,Hold,WarmupFrames)
                    if S.SurfaceWeaponBusy or S.ProxyCoinBusy or S.WeaponPickupBusy or S.SurfaceActionActive then
                        return false,nil
                    end
                    S.SurfaceWeaponBusy=true
                    local ManualBefore=nil
                    pcall(function() ManualBefore=Tool.ManualActivationOnly end)

                    pcall(function()
                        if S.ProxyToolManualActivationBackup~=nil then
                            Tool.ManualActivationOnly=S.ProxyToolManualActivationBackup
                        else
                            Tool.ManualActivationOnly=false
                        end
                    end)
                    local Packed=table.pack(Runtime.MM2WithSurfaceShell(Fn,Hold,WarmupFrames or 4))
                    pcall(function() Tool.ManualActivationOnly=(ManualBefore~=nil and ManualBefore or true) end)
                    S.SurfaceWeaponBusy=false
                    S.LastProxyWeaponActionAt=os.clock()
                    if not Packed[1] then return false,nil end
                    return true,Packed[2]
                end

                if Kind=="gun" then

                    local KnifeLocal=Tool:FindFirstChild("KnifeLocal",true)
                    local CreateBeam=KnifeLocal and KnifeLocal:FindFirstChild("CreateBeam",true)
                    local RF=CreateBeam and (CreateBeam:FindFirstChild("RemoteFunction",true) or CreateBeam:FindFirstChildWhichIsA("RemoteFunction",true))
                    if RF and RF:IsA("RemoteFunction") then
                        local Ok,Result=Relay(function()
                            return RF:InvokeServer(1,Target,"AH2")
                        end,0.24,7)
                        if Ok and Result~=false then return true end
                    end
                    for _,Remote in ipairs(Tool:GetDescendants()) do
                        if Remote:IsA("RemoteEvent") and MatchKeywords(Remote.Name,{"shootgun","gunfired","shoot","fire"}) then
                            local Ok=Relay(function() Remote:FireServer(Target) end,0.22,7)
                            if Ok then return true end
                        elseif Remote:IsA("RemoteFunction") and MatchKeywords(Remote.Name,{"shootgun","gunfired","shoot","fire"}) then
                            local Ok,Result=Relay(function() return Remote:InvokeServer(Target) end,0.22,7)
                            if Ok and Result~=false then return true end
                        end
                    end

                    return select(1,Relay(function() Tool:Activate() end,0.30,7))
                elseif Kind=="knife" then
                    if Action=="throw" then
                        local Events=Tool:FindFirstChild("Events",true)
                        local KnifeThrown=Events and Events:FindFirstChild("KnifeThrown",true)
                        if KnifeThrown and KnifeThrown:IsA("RemoteEvent") then
                            local Origin=Runtime.MM2SurfaceCFrame() or CFrame.new()
                            local To=CFrame.new(Target)
                            local Ok=select(1,Relay(function()
                                KnifeThrown:FireServer(Origin,To)
                                if Runtime.MM2MirrorActionAnimations then Runtime.MM2MirrorActionAnimations() end
                            end,0.20,6))
                            if Ok then return true end
                        end
                        local Throw=Tool:FindFirstChild("Throw",true) or Tool:FindFirstChild("ThrowKnife",true)
                        if Throw then
                            local Origin=Runtime.MM2SurfaceCFrame() or CFrame.new()
                            local Ok,Result=false,nil
                            if Throw:IsA("RemoteEvent") then
                                Ok=select(1,Relay(function() Throw:FireServer(Origin,Target) end,0.18,6))
                            elseif Throw:IsA("RemoteFunction") then
                                Ok,Result=Relay(function() return Throw:InvokeServer(Origin,Target) end,0.18,6)
                            end
                            if Ok and Result~=false then return true end
                        end
                        return select(1,Relay(function() Tool:Activate() end,0.20,6))
                    end

                    local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                    if Tool.Parent~=RealChar and Runtime.MM2EquipRealTool then
                        Runtime.MM2EquipRealTool(Tool)
                        for _=1,3 do
                            RunService.Heartbeat:Wait()
                            if Tool.Parent==RealChar then break end
                        end
                    end
                    local Stab=Tool:FindFirstChild("Stab") or Tool:FindFirstChild("Stab",true)
                    if Stab and (Stab:IsA("RemoteEvent") or Stab:IsA("RemoteFunction")) then
                        local Ok,Result=Relay(function()
                            if Stab:IsA("RemoteEvent") then
                                Stab:FireServer("Down")
                            else
                                return Stab:InvokeServer("Down")
                            end
                            pcall(function() Tool:Activate() end)
                            if Runtime.MM2MirrorActionAnimations then Runtime.MM2MirrorActionAnimations() end
                        end,0.28,7)
                        if Ok and Result~=false then return true end
                    end

                    local Slash=Tool:FindFirstChild("Slash",true)
                    if Slash and (Slash:IsA("RemoteEvent") or Slash:IsA("RemoteFunction")) then
                        local Ok,Result=Relay(function()
                            if Slash:IsA("RemoteEvent") then Slash:FireServer("Slash")
                            else return Slash:InvokeServer("Slash") end
                        end,0.24,6)
                        if Ok and Result~=false then return true end
                    end
                    return select(1,Relay(function() Tool:Activate() end,0.24,6))
                end

                return select(1,Relay(function() Tool:Activate() end,0.18,5))
            end

            Runtime.MM2PointerOverHubUI=function()
                local P=UserInputService:GetMouseLocation()
                local Ok,Objects=pcall(function() return GuiService:GetGuiObjectsAtPosition(P.X,P.Y) end)
                if not Ok or type(Objects)~="table" then return false end
                for _,Object in ipairs(Objects) do
                    local Current=Object
                    for _=1,32 do
                        if not Current then break end
                        if HubGuiTracker.Owned[Current] then return true end
                        if Current:IsA("LayerCollector") then
                            local Name=string.lower(tostring(Current.Name))
                            if string.find(Name,"banani",1,true) or string.find(Name,"rayfield",1,true) then return true end
                            break
                        end
                        Current=Current.Parent
                    end
                end
                return false
            end

            Runtime.MM2AttachSurfaceProxyInputs=function()
                local S=Runtime.MM2InvisibleState
                if S.SurfaceInputConnection then pcall(function() S.SurfaceInputConnection:Disconnect() end) end
                S.SurfaceInputConnection=UserInputService.InputBegan:Connect(function(Input,GameProcessed)
                    if GameProcessed or not State.MM2Invisible or Unloaded or UserInputService:GetFocusedTextBox() then return end
                    if Input.UserInputType==Enum.UserInputType.MouseButton1 then
                        if Runtime.MM2PointerOverHubUI and Runtime.MM2PointerOverHubUI() then return end
                        task.defer(function()
                            if State.MM2Invisible and not Unloaded then Runtime.MM2SurfaceToolProxy(nil,"primary") end
                        end)
                    elseif Input.KeyCode==Enum.KeyCode.E then
                        if Runtime.MM2PointerOverHubUI and Runtime.MM2PointerOverHubUI() then return end
                        task.defer(function()
                            if not State.MM2Invisible or Unloaded then return end
                            local Tool=Runtime.MM2EquippedRealTool and Runtime.MM2EquippedRealTool() or nil
                            if (not Tool or (Runtime.MM2WeaponKind and Runtime.MM2WeaponKind(Tool)~="knife"))
                                and Runtime.MM2EquipOwnedWeapon then
                                Tool=Runtime.MM2EquipOwnedWeapon("knife",0.08)
                            end
                            if Tool and Runtime.MM2WeaponKind and Runtime.MM2WeaponKind(Tool)=="knife" then
                                local Target=Runtime.MM2SurfaceAimPosition(1200)
                                if Target and Runtime.MM2SurfaceToolProxy(Target,"throw") then return end
                            end
                            Runtime.MM2SurfaceInteract()
                        end)
                    end
                end)
            end

            Runtime.MM2RepairProxy=function(Silent)
                local S=Runtime.MM2InvisibleState
                if not State.MM2Invisible or Unloaded then return false end
                if S.ProxyRepairQueued then return false end
                if S.SurfaceActionActive or S.SurfaceWeaponBusy or S.WeaponPickupBusy or S.ProxyCoinBusy or (tonumber(S.SurfaceRelayDepth) or 0)>0 then return false end
                local Char=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                local RH=Char and Char:FindFirstChildOfClass("Humanoid")
                local RR=Char and Char:FindFirstChild("HumanoidRootPart")
                if not Char or not RH or RH.Health<=0 or not RR then return false end
                S.ProxyRepairQueued=true
                local OldPH=S.ProxyHumanoid
                local SavedWalk=OldPH and OldPH.WalkSpeed or nil
                local SavedUseJump=OldPH and OldPH.UseJumpPower or nil
                local SavedJumpPower=OldPH and OldPH.JumpPower or nil
                local SavedJumpHeight=OldPH and OldPH.JumpHeight or nil
                local Saved=(S.ProxyRoot and S.ProxyRoot.Parent and S.ProxyRoot.CFrame) or S.SurfaceCFrame or S.LastSafeProxyCFrame or (RR.CFrame*CFrame.new(0,S.Depth or 25,0))
                if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                if S.SurfaceInputConnection then pcall(function() S.SurfaceInputConnection:Disconnect() end); S.SurfaceInputConnection=nil end
                Runtime.MM2ClearProxyToolVisual()
                if S.ProxyAnimationTracks then for _,T in pairs(S.ProxyAnimationTracks) do if T then pcall(function() T:Stop(0.03) end); pcall(function() T:Destroy() end) end end end
                if S.ProxyActionTracks then for _,T in pairs(S.ProxyActionTracks) do if T then pcall(function() T:Stop(0.03) end); pcall(function() T:Destroy() end) end end end
                if S.ProxyCharacter and Player.Character==S.ProxyCharacter and Char and Char.Parent then
                    Runtime.MM2SetClientCharacter(Char)
                end
                if S.ProxyCharacter then pcall(function() S.ProxyCharacter:Destroy() end) end
                S.ProxyCharacter=nil; S.ProxyHumanoid=nil; S.ProxyRoot=nil; S.Decoy=nil; S.ProxyActive=false
                S.CharacterSwappedToProxy=false; S.NativeAnimateActive=false
                S.SurfaceCFrame=Saved
                local Ok=Runtime.MM2BuildInvisibleDecoy(Char)
                if Ok then
                    local PH=S.ProxyHumanoid
                    local B=S.HumanoidStateBackups and S.HumanoidStateBackups[Char]
                    pcall(function()
                        PH.WalkSpeed=SavedWalk or (B and B.WalkSpeed) or 16
                        if SavedUseJump~=nil then PH.UseJumpPower=SavedUseJump elseif B and B.UseJumpPower~=nil then PH.UseJumpPower=B.UseJumpPower end
                        if PH.UseJumpPower~=false then PH.JumpPower=SavedJumpPower or (B and B.JumpPower) or 50 else PH.JumpHeight=SavedJumpHeight or (B and B.JumpHeight) or 7.2 end
                        PH.HipHeight=RH.HipHeight; PH.CameraOffset=RH.CameraOffset; PH.MaxSlopeAngle=RH.MaxSlopeAngle; PH.AutoJumpEnabled=RH.AutoJumpEnabled
                        PH.MaxHealth=RH.MaxHealth; PH.Health=math.clamp(RH.Health,0,RH.MaxHealth)
                    end)
                    Runtime.MM2AttachSurfaceProxyInputs()
                    Runtime.MM2RefreshProxyAnimations(true)
                    Runtime.MM2BindProxySignals()
                    Runtime.MM2UpdateProxyAnimation()
                    Runtime.MM2SyncProxyTool(true)
                    pcall(function()
                        local Cam=workspace.CurrentCamera or Camera
                        Cam.CameraType=Enum.CameraType.Custom
                        Cam.CameraSubject=PH
                    end)
                end
                S.ProxyRepairQueued=false
                if not Silent then Notify("MM2 Invisible",Ok and "Proxy repaired without resetting the real character." or "Proxy repair failed.") end
                return Ok
            end

            Runtime.MM2ApplyInvisibleCharacter=function(Char)
                local S=Runtime.MM2InvisibleState
                if not State.MM2Invisible or not Char or not Char.Parent then return false end
                if S.Character and S.Character~=Char then Runtime.MM2RestoreInvisibleCharacter(S.Character,false) end
                Runtime.MM2DestroyInvisibleDecoy()
                local H=Char:FindFirstChildOfClass("Humanoid") or Char:WaitForChild("Humanoid",4)
                local R=Char:FindFirstChild("HumanoidRootPart") or Char:WaitForChild("HumanoidRootPart",4)
                if not H or not R or H.Health<=0 then return false end

                S.Depth=math.clamp(tonumber(State.MM2InvisibleDepth) or 25,5,50)
                S.Character=Char; S.SurfaceCFrame=R.CFrame; S.BlinkSurfaceCFrame=R.CFrame; S.RealCharacterDead=false
                S.BlinkInvisibility=true; S.DirectMotorMirror=true; S.BlinkHidden=false; S.BlinkSuspendUntil=0
                S.HumanoidStateBackups=S.HumanoidStateBackups or setmetatable({}, {__mode="k"})
                S.PartBackups=S.PartBackups or setmetatable({}, {__mode="k"})
                S.HumanoidStateBackups[Char]={
                    CameraOffset=H.CameraOffset, AutoRotate=H.AutoRotate, WalkSpeed=H.WalkSpeed,
                    UseJumpPower=H.UseJumpPower, JumpPower=H.JumpPower, JumpHeight=H.JumpHeight,
                    Jumping=H:GetStateEnabled(Enum.HumanoidStateType.Jumping),
                    Freefall=H:GetStateEnabled(Enum.HumanoidStateType.Freefall),
                    FallingDown=H:GetStateEnabled(Enum.HumanoidStateType.FallingDown),
                    Ragdoll=H:GetStateEnabled(Enum.HumanoidStateType.Ragdoll),
                }
                S.BlinkBaseCameraOffset=H.CameraOffset

                if not Runtime.MM2BuildInvisibleDecoy(Char) then return false end
                local PH,PR=S.ProxyHumanoid,S.ProxyRoot
                if not PH or not PR then Runtime.MM2DestroyInvisibleDecoy(); return false end
                pcall(function()
                    PH.AutoRotate=false; PH.PlatformStand=true; PH.Sit=false
                    PH.MaxHealth=H.MaxHealth; PH.Health=math.clamp(H.Health,0,H.MaxHealth)
                end)

                S.PartBackups[Char]={}
                for _,Part in ipairs(Char:GetDescendants()) do if Part:IsA("BasePart") then Runtime.MM2ApplyHiddenRealPart(Part) end end

                pcall(function()
                    local Cam=workspace.CurrentCamera or Camera
                    Cam.CameraType=Enum.CameraType.Custom
                    Cam.CameraSubject=H
                end)
                Runtime.MM2BindProxySignals()
                Runtime.MM2SyncProxyTool(true)

                if S.BlinkHeartbeatConnection then pcall(function() S.BlinkHeartbeatConnection:Disconnect() end); S.BlinkHeartbeatConnection=nil end
                if S.BlinkPhysicsConnection then pcall(function() S.BlinkPhysicsConnection:Disconnect() end); S.BlinkPhysicsConnection=nil end
                if S.RenderConnection then pcall(function() S.RenderConnection:Disconnect() end); S.RenderConnection=nil end

                local HideSignal=RunService.Heartbeat
                pcall(function()
                    if RunService.PostSimulation then HideSignal=RunService.PostSimulation end
                end)
                S.BlinkPhysicsConnection=HideSignal:Connect(function()
                    if not State.MM2Invisible or Unloaded or not S.ProxyActive or not S.BlinkInvisibility then return end
                    if S.BlinkHidden then return end
                    if (tonumber(S.SurfaceRelayDepth) or 0)>0 or S.SurfaceActionActive or S.InteractionSynchronizerBusy then return end
                    if os.clock()<(tonumber(S.BlinkSuspendUntil) or 0) then return end
                    if not Char.Parent or not H.Parent or H.Health<=0 or not R.Parent then return end

                    local Surface=R.CFrame
                    local MovementOwner=Runtime.Movement and Runtime.Movement.Owner or nil
                    if S.ProxyRoot and S.ProxyRoot.Parent and (Runtime.TweenActive or (MovementOwner and (S.ProxyRoot.Position-R.Position).Magnitude>2.5)) then
                        Surface=S.ProxyRoot.CFrame
                        local L=R.AssemblyLinearVelocity
                        local A=R.AssemblyAngularVelocity
                        pcall(function()
                            Char:PivotTo(Surface)
                            R.AssemblyLinearVelocity=L
                            R.AssemblyAngularVelocity=A
                        end)
                    end
                    S.SurfaceCFrame=Surface
                    S.BlinkSurfaceCFrame=Surface
                    S.BlinkSavedLinearVelocity=R.AssemblyLinearVelocity
                    S.BlinkSavedAngularVelocity=R.AssemblyAngularVelocity

                    local Hidden=Surface*CFrame.new(0,-S.Depth,0)
                    S.LastForcedShellCFrame=Hidden
                    S.LastShellWriteAt=os.clock()
                    Runtime.MM2SetBlinkPhysicsMuted(Char,true)
                    local Ok=pcall(function()
                        Char:PivotTo(Hidden)
                        R.AssemblyLinearVelocity=S.BlinkSavedLinearVelocity or Vector3.zero
                        R.AssemblyAngularVelocity=S.BlinkSavedAngularVelocity or Vector3.zero
                        local Lift=Hidden:ToObjectSpace(CFrame.new(Surface.Position)).Position
                        H.CameraOffset=(S.BlinkBaseCameraOffset or Vector3.zero)+Lift
                    end)
                    if Ok then
                        S.BlinkHidden=true
                    else
                        Runtime.MM2SetBlinkPhysicsMuted(Char,false)
                        S.BlinkSavedLinearVelocity=nil
                        S.BlinkSavedAngularVelocity=nil
                    end
                end)

                S.RenderConnection=Runtime.TrackCleanup(RunService.RenderStepped:Connect(function()
                    if not State.MM2Invisible or Unloaded or not S.ProxyActive or not S.BlinkInvisibility then return end
                    if not Char.Parent or not H.Parent or H.Health<=0 or not R.Parent then return end
                    local PC,PRoot=S.ProxyCharacter,S.ProxyRoot
                    if not PC or not PC.Parent or not PRoot or not PRoot.Parent then
                        if S.BlinkHidden then Runtime.MM2RestoreBlinkSurface(Char,H,R,S.BlinkSurfaceCFrame or S.SurfaceCFrame) end
                        if not S.ProxyRepairQueued then
                            S.ProxyRepairQueued=true
                            task.defer(function()
                                S.ProxyRepairQueued=false
                                if State.MM2Invisible and Runtime.MM2RepairProxy then Runtime.MM2RepairProxy(true) end
                            end)
                        end
                        return
                    end

                    local Surface=S.BlinkSurfaceCFrame or S.SurfaceCFrame or R.CFrame
                    if S.BlinkHidden then
                        Runtime.MM2RestoreBlinkSurface(Char,H,R,Surface)
                    else
                        Runtime.MM2SetBlinkPhysicsMuted(Char,false)
                    end

                    local MovementOwner=Runtime.Movement and Runtime.Movement.Owner or nil
                    local ProxyMoved=(PRoot.Position-R.Position).Magnitude>2.5
                    if Runtime.TweenActive or (MovementOwner and ProxyMoved) then
                        Surface=PRoot.CFrame
                        local L=R.AssemblyLinearVelocity
                        local A=R.AssemblyAngularVelocity
                        pcall(function()
                            Char:PivotTo(Surface)
                            R.AssemblyLinearVelocity=L
                            R.AssemblyAngularVelocity=A
                        end)
                    else
                        Surface=R.CFrame
                        pcall(function() PC:PivotTo(Surface) end)
                    end
                    S.SurfaceCFrame=Surface
                    S.BlinkSurfaceCFrame=Surface

                    for _,Pair in ipairs(S.ProxyMotorPairs or {}) do
                        local RM,PM=Pair.Real,Pair.Proxy
                        if RM and RM.Parent and PM and PM.Parent then
                            pcall(function() PM.Transform=RM.Transform; PM.Enabled=RM.Enabled end)
                        end
                    end

                    local T=os.clock()
                    if T-(tonumber(S.LastProxyToolSyncAt) or 0)>=0.12 then S.LastProxyToolSyncAt=T; Runtime.MM2SyncProxyTool(false) end
                    if T-(tonumber(S.LastProxyVisualRefreshAt) or 0)>=1.5 then S.LastProxyVisualRefreshAt=T; Runtime.MM2ApplyProxyTransparency(PC) end
                    pcall(function()
                        local Cam=workspace.CurrentCamera or Camera
                        if Cam then
                            Cam.CameraType=Enum.CameraType.Custom
                            if Cam.CameraSubject~=H then Cam.CameraSubject=H end
                        end
                    end)
                end),"Disconnect","MM2InvisibleRender","Connections")
                return true
            end

            Runtime.MM2LegacySetInvisible=function(Enabled,Silent)
                local S=Runtime.MM2InvisibleState
                Enabled=Enabled==true
                if not Enabled then
                    State.MM2Invisible=false
                    if S.CharacterConnection then pcall(function() S.CharacterConnection:Disconnect() end); S.CharacterConnection=nil end
                    if S.JumpConnection then pcall(function() S.JumpConnection:Disconnect() end); S.JumpConnection=nil end
                    S.RestoreCFrame=S.BlinkSurfaceCFrame or (S.ProxyRoot and S.ProxyRoot.Parent and S.ProxyRoot.CFrame) or S.SurfaceCFrame
                    S.ProxyActive=false
                    local Applied=S.Character
                    if Applied then Runtime.MM2RestoreInvisibleCharacter(Applied,true) end
                    Runtime.MM2DestroyInvisibleDecoy()
                    S.Character=nil
                    Runtime.MM2RestoreCamera(Applied and Applied:FindFirstChildOfClass("Humanoid") or nil)
                    S.CameraBackup=nil
                    if not Silent then Notify("MM2 Invisible","OFF • real character, camera, tools and controls restored at the decoy's last position.") end
                    return true
                end

                if State.MM2Invisible and S.ProxyActive and S.ProxyCharacter and S.ProxyCharacter.Parent then return true end
                local Cam=workspace.CurrentCamera or Camera
                if not S.CameraBackup and Cam then S.CameraBackup={Type=Cam.CameraType,Subject=Cam.CameraSubject} end
                State.MM2Invisible=true
                if S.CharacterConnection then pcall(function() S.CharacterConnection:Disconnect() end) end
                if S.JumpConnection then pcall(function() S.JumpConnection:Disconnect() end) end
                S.JumpConnection=UserInputService.JumpRequest:Connect(function()
                    if not State.MM2Invisible or Unloaded then return end
                    if S.BlinkInvisibility then return end
                    local PH=S.ProxyHumanoid
                    if PH and PH.Parent and PH.Health>0 then
                        pcall(function() PH.Jump=true; if PH.FloorMaterial~=Enum.Material.Air then PH:ChangeState(Enum.HumanoidStateType.Jumping) end end)
                    end
                end)
                S.CharacterConnection=Player.CharacterAdded:Connect(function(NewCharacter)
                    if S.CharacterSwapGuard or NewCharacter==S.ProxyCharacter then return end
                    if not State.MM2Invisible or Unloaded then return end
                    S.ProxyActive=false
                    Runtime.MM2DestroyInvisibleDecoy()
                    S.Character=nil
                    task.spawn(function()
                        local NH=NewCharacter:WaitForChild("Humanoid",4)
                        local NR=NewCharacter:WaitForChild("HumanoidRootPart",4)
                        if not State.MM2Invisible or Unloaded or not NH or not NR or NH.Health<=0 then return end
                        task.wait(0.12)
                        if State.MM2Invisible and not Unloaded then Runtime.MM2ApplyInvisibleCharacter(NewCharacter) end
                    end)
                end)
                local InitialReal=Player.Character
                local Ok=Runtime.MM2ApplyInvisibleCharacter(InitialReal)
                if not Ok then
                    State.MM2Invisible=false; S.ProxyActive=false
                    if S.CharacterConnection then pcall(function() S.CharacterConnection:Disconnect() end); S.CharacterConnection=nil end
                    if S.JumpConnection then pcall(function() S.JumpConnection:Disconnect() end); S.JumpConnection=nil end
                    Runtime.MM2DestroyInvisibleDecoy(); Runtime.MM2RestoreCamera(InitialReal and InitialReal:FindFirstChildOfClass("Humanoid") or nil)
                    S.CameraBackup=nil
                    if not Silent then Notify("MM2 Invisible","Could not create the decoy avatar safely.") end
                    return false
                end
                if not Silent then Notify("MM2 Invisible","ON • anti-fling blink moves the full real assembly "..tostring(math.floor(S.Depth or 25)).." studs underground after physics, then restores it before rendering.") end
                return true
            end

            -- v5.14.68: embedded Infinite Yield-style invisibility.
            -- v5.14.69: hardened MM2 fling return + direct dropped-gun ESP discovery.
            -- v5.14.71: park the real avatar far away while the 50% clone moves; restore it to the clone on OFF.
            -- v5.14.74: sticky verified fling targets multiple body parts, removes conflicting constant BodyVelocity, retries internally, and holds contact after sustained launch detection.
            -- Adapted from EdgeIY/infiniteyield's public MIT-licensed `invisible` command.
            -- BananiHub keeps only the character clone/swap invis logic and routes all
            -- existing Invisible buttons/keybind/Favorites through this one backend.
            Runtime.MM2IYInvisibleState=Runtime.MM2IYInvisibleState or {}

            Runtime.MM2IYDisconnect=function(S)
                if not S then return end
                for _,Key in ipairs({"InvisFix","CloneDied","RealDied","CloneDescendantAdded","CloneHumanoidChild"}) do
                    local C=S[Key]
                    if C then pcall(function() C:Disconnect() end) end
                    S[Key]=nil
                end
            end

            Runtime.MM2IYRestartAnimate=function(Char)
                if not Char then return end
                local Animate=Char:FindFirstChild("Animate")
                if Animate and Animate:IsA("LocalScript") then
                    pcall(function()
                        Animate.Disabled=true
                        task.wait()
                        Animate.Disabled=false
                    end)
                end
            end

            Runtime.MM2IYApplyCloneTransparency=function(Clone)
                if not Clone then return end
                for _,Obj in ipairs(Clone:GetDescendants()) do
                    if Obj:IsA("BasePart") then
                        pcall(function()
                            Obj.Transparency=(Obj.Name=="HumanoidRootPart") and 1 or 0.5
                            Obj.LocalTransparencyModifier=0
                        end)
                    elseif Obj:IsA("Decal") or Obj:IsA("Texture") then
                        pcall(function() Obj.Transparency=0.5 end)
                    end
                end
            end

            Runtime.MM2RestoreOriginalInvisible=function(Silent)
                local S=Runtime.MM2IYInvisibleState or {}
                Runtime.MM2IYInvisibleState=S
                if S.Restoring then return true end
                if not S.Active and not S.RealCharacter and not S.InvisibleCharacter then
                    State.MM2Invisible=false
                    State.MM2OriginalInvisible=false
                    return true
                end

                local Real=S.RealCharacter
                local Clone=S.InvisibleCharacter
                if not Real then
                    Runtime.LastInvisibleError="original character no longer exists"
                    if not Silent then Notify("Invisible",Runtime.LastInvisibleError) end
                    return false
                end

                S.Restoring=true
                Runtime.MM2IYDisconnect(S)

                local Current=Player.Character
                local CurrentRoot=Current and Current:FindFirstChild("HumanoidRootPart")
                local CloneRoot=Clone and Clone:FindFirstChild("HumanoidRootPart")
                local TargetCF=(Current==Clone and CurrentRoot and CurrentRoot.CFrame)
                    or (CloneRoot and CloneRoot.CFrame)
                    or S.LastSafeCFrame or S.StartCFrame
                local Camera=workspace.CurrentCamera or Camera
                local CameraCF=Camera and Camera.CFrame or S.CameraCFrame

                local Ok,Err=pcall(function()
                    if not Real.Parent then Real.Parent=workspace end
                    if Real.Parent~=workspace then Real.Parent=workspace end
                    local RH=Real:FindFirstChildOfClass("Humanoid")
                    local RR=Real:FindFirstChild("HumanoidRootPart") or (RH and RH.RootPart)
                    assert(RH and RR,"original humanoid/root missing")
                    RR.Anchored=true
                    if TargetCF then
                        Real:PivotTo(TargetCF)
                        RR.CFrame=TargetCF
                    end
                    RR.AssemblyLinearVelocity=Vector3.zero
                    RR.AssemblyAngularVelocity=Vector3.zero
                    Player.Character=Real
                    if Camera then
                        Camera.CameraType=Enum.CameraType.Custom
                        Camera.CameraSubject=RH
                        if CameraCF then Camera.CFrame=CameraCF end
                    end
                    for Obj,OldState in pairs(S.RealPartStates or {}) do
                        if Obj and Obj.Parent then
                            pcall(function()
                                Obj.CanCollide=OldState.CanCollide
                                Obj.LocalTransparencyModifier=OldState.LocalTransparencyModifier
                            end)
                        end
                    end
                    RR.Anchored=S.RealRootAnchored==true
                    Runtime.MM2IYRestartAnimate(Real)
                    if Clone and Clone~=Real then pcall(function() Clone:Destroy() end) end
                    if S.RealArchivable~=nil then Real.Archivable=S.RealArchivable end
                end)

                if not Ok then
                    S.Restoring=false
                    Runtime.LastInvisibleError="visible restore failed: "..tostring(Err)
                    if not Silent then Notify("Invisible",Runtime.LastInvisibleError) end
                    return false
                end

                S.Active=false
                S.RealCharacter=nil
                S.InvisibleCharacter=nil
                S.StartCFrame=nil
                S.RealLockedCFrame=nil
                S.RealParkCFrame=nil
                S.RealRootAnchored=nil
                S.RealPartStates=nil
                S.LastSafeCFrame=nil
                S.CameraCFrame=nil
                S.RealArchivable=nil
                S.Restoring=false
                State.MM2Invisible=false
                State.MM2OriginalInvisible=false
                Runtime.LastInvisibleError=nil
                if not Silent then Notify("Invisible","OFF") end
                return true
            end

            Runtime.MM2SetInvisible=function(Enabled,Silent)
                Enabled=Enabled==true
                if not Silent then State.MM2InvisibleWanted=Enabled end
                local S=Runtime.MM2IYInvisibleState or {}
                Runtime.MM2IYInvisibleState=S

                if not Enabled then
                    if State.MM2Invisible and Runtime.MM2LegacySetInvisible then
                        pcall(function() Runtime.MM2LegacySetInvisible(false,true) end)
                    end
                    return Runtime.MM2RestoreOriginalInvisible(Silent)
                end

                if S.Active and State.MM2OriginalInvisible and S.InvisibleCharacter and S.InvisibleCharacter.Parent then
                    return true
                end

                if State.MM2Invisible and Runtime.MM2LegacySetInvisible then
                    pcall(function() Runtime.MM2LegacySetInvisible(false,true) end)
                end
                local UState=Runtime.UniversalInvisibleState
                if UState and UState.Active and UState.Restore then pcall(function() UState.Restore(true,true) end) end
                State.MM2Invisible=false

                local Real=Player.Character
                local RH=Real and Real:FindFirstChildOfClass("Humanoid")
                local RR=Real and (Real:FindFirstChild("HumanoidRootPart") or (RH and RH.RootPart))
                if not Real or not RH or not RR or RH.Health<=0 then
                    Runtime.LastInvisibleError="character is not ready"
                    if not Silent then Notify("Invisible",Runtime.LastInvisibleError) end
                    return false
                end

                local OldArchivable=Real.Archivable
                Real.Archivable=true
                local Clone
                local CloneOK,CloneErr=pcall(function() Clone=Real:Clone() end)
                if not CloneOK or not Clone then
                    Real.Archivable=OldArchivable
                    Runtime.LastInvisibleError="character clone failed: "..tostring(CloneErr)
                    if not Silent then Notify("Invisible",Runtime.LastInvisibleError) end
                    return false
                end

                Clone.Name=""
                Clone.Parent=Lighting
                local CH=Clone:FindFirstChildOfClass("Humanoid")
                local CR=Clone:FindFirstChild("HumanoidRootPart") or (CH and CH.RootPart)
                if not CH or not CR then
                    pcall(function() Clone:Destroy() end)
                    Real.Archivable=OldArchivable
                    Runtime.LastInvisibleError="invisible clone has no humanoid/root"
                    if not Silent then Notify("Invisible",Runtime.LastInvisibleError) end
                    return false
                end

                Runtime.MM2IYApplyCloneTransparency(Clone)
                pcall(function() CH.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None end)

                Runtime.MM2IYDisconnect(S)
                S.Active=true
                S.Restoring=false
                S.RealCharacter=Real
                S.InvisibleCharacter=Clone
                S.RealArchivable=OldArchivable
                S.StartCFrame=RR.CFrame
                S.RealLockedCFrame=nil
                -- Move the REAL networked avatar physically far away first.
                -- After a couple of physics frames it is parked outside Workspace in Lighting.
                S.RealParkCFrame=CFrame.new(0,math.pi*1000000,0)
                S.RealRootAnchored=RR.Anchored
                S.RealPartStates=setmetatable({}, {__mode="k"})
                for _,Obj in ipairs(Real:GetDescendants()) do
                    if Obj:IsA("BasePart") then
                        S.RealPartStates[Obj]={
                            CanCollide=Obj.CanCollide,
                            LocalTransparencyModifier=Obj.LocalTransparencyModifier,
                        }
                        pcall(function()
                            Obj.CanCollide=false
                            Obj.LocalTransparencyModifier=1
                        end)
                    end
                end
                S.LastSafeCFrame=RR.CFrame
                local Cam=workspace.CurrentCamera or Camera
                S.CameraCFrame=Cam and Cam.CFrame or nil

                local StartCF=S.StartCFrame
                local SwapOK,SwapErr=pcall(function()
                    -- Popup/clone invis behavior:
                    -- every ON starts fresh by teleporting the real avatar far away,
                    -- then the 50%-transparent clone stays at the activation position
                    -- and becomes the character the player controls.
                    local ParkCF=S.RealParkCFrame or CFrame.new(0,math.pi*1000000,0)
                    S.RealParkCFrame=ParkCF
                    -- Hard-disappear behavior: move the real avatar far away first, then
                    -- remove the real model from Workspace locally by parking it in Lighting.
                    -- Only the 50% clone remains in Workspace while Invisible is ON.
                    if Real.Parent~=workspace then Real.Parent=workspace end
                    -- Temporarily unanchor the real root while the client still owns its
                    -- character physics, move it far away, and yield two physics frames so
                    -- the position has a chance to replicate before the model is hidden.
                    RR.Anchored=false
                    Real:PivotTo(ParkCF)
                    RR.CFrame=ParkCF
                    RR.AssemblyLinearVelocity=Vector3.zero
                    RR.AssemblyAngularVelocity=Vector3.zero
                    RunService.Heartbeat:Wait()
                    RunService.Heartbeat:Wait()
                    RR.Anchored=true
                    Real.Parent=Lighting
                    Clone.Parent=workspace
                    CR.CFrame=StartCF
                    CR.AssemblyLinearVelocity=Vector3.zero
                    CR.AssemblyAngularVelocity=Vector3.zero
                    Player.Character=Clone
                    if Cam then
                        Cam.CameraType=Enum.CameraType.Custom
                        Cam.CameraSubject=CH
                        if S.CameraCFrame then Cam.CFrame=S.CameraCFrame end
                    end
                    Runtime.MM2IYRestartAnimate(Clone)
                end)

                if not SwapOK or Player.Character~=Clone then
                    local FailureReason="character swap failed: "..tostring(SwapErr or "blocked")
                    Runtime.MM2RestoreOriginalInvisible(true)
                    Runtime.LastInvisibleError=FailureReason
                    if not Silent then Notify("Invisible",FailureReason) end
                    return false
                end

                S.InvisFix=Runtime.TrackCleanup(RunService.Stepped:Connect(function()
                    if not S.Active or S.Restoring or Player.Character~=Clone then return end

                    -- Keep the real avatar parked far away for the whole invisible session.
                    -- Only the clone is allowed to move/teleport while Invisible is ON.
                    if Real and Real.Parent~=Lighting then
                        pcall(function() Real.Parent=Lighting end)
                    end
                    local ParkedRoot=Real and (Real:FindFirstChild("HumanoidRootPart") or RH.RootPart)
                    if ParkedRoot and typeof(S.RealParkCFrame)=="CFrame" then
                        pcall(function()
                            ParkedRoot.Anchored=true
                            if (ParkedRoot.Position-S.RealParkCFrame.Position).Magnitude>0.5 then
                                Real:PivotTo(S.RealParkCFrame)
                                ParkedRoot.CFrame=S.RealParkCFrame
                            end
                            ParkedRoot.AssemblyLinearVelocity=Vector3.zero
                            ParkedRoot.AssemblyAngularVelocity=Vector3.zero
                            if Real.Parent~=Lighting then Real.Parent=Lighting end
                        end)
                    end

                    local LiveRoot=Clone:FindFirstChild("HumanoidRootPart") or CH.RootPart
                    if not LiveRoot then return end
                    local Void=workspace.FallenPartsDestroyHeight
                    local Y=LiveRoot.Position.Y
                    local Crossed=(Void<0 and Y<=Void) or (Void>=0 and Y>=Void)
                    if Crossed then
                        local Safe=S.LastSafeCFrame or S.StartCFrame
                        if Safe then
                            pcall(function()
                                LiveRoot.CFrame=Safe
                                LiveRoot.AssemblyLinearVelocity=Vector3.zero
                                LiveRoot.AssemblyAngularVelocity=Vector3.zero
                            end)
                        end
                    else
                        S.LastSafeCFrame=LiveRoot.CFrame
                    end
                end),"Disconnect","MM2InvisibleStepped","Connections")

                S.CloneDescendantAdded=Clone.DescendantAdded:Connect(function(Obj)
                    if not S.Active or S.Restoring then return end
                    task.defer(function()
                        if not S.Active or not Obj or not Obj.Parent then return end
                        if Obj:IsA("BasePart") then
                            pcall(function()
                                Obj.Transparency=(Obj.Name=="HumanoidRootPart") and 1 or 0.5
                                Obj.LocalTransparencyModifier=0
                            end)
                        elseif Obj:IsA("Decal") or Obj:IsA("Texture") then
                            pcall(function() Obj.Transparency=0.5 end)
                        elseif Obj.Name=="Animate" and Obj:IsA("LocalScript") then
                            Runtime.MM2IYRestartAnimate(Clone)
                        elseif Obj:IsA("Tool") then
                            -- Tool equips can replace animation tracks on the clone. Rebind once
                            -- after the equip so the 50% decoy keeps normal tool/character motion.
                            Runtime.MM2IYRestartAnimate(Clone)
                        end
                    end)
                end)

                -- Rebind animation whenever Roblox replaces the Animator during map/character refreshes.
                S.CloneHumanoidChild=CH.ChildAdded:Connect(function(Obj)
                    if S.Active and not S.Restoring and (Obj:IsA("Animator") or Obj.Name=="Animator") then
                        task.defer(function() Runtime.MM2IYRestartAnimate(Clone) end)
                    end
                end)

                S.CloneDied=CH.Died:Connect(function()
                    if not S.Active or S.Restoring then return end
                    task.defer(function()
                        if not S.Active then return end
                        Runtime.MM2RestoreOriginalInvisible(true)
                        local Live=Player.Character
                        local H=Live and Live:FindFirstChildOfClass("Humanoid")
                        if H and H.Health>0 then pcall(function() H.Health=0 end) end
                    end)
                end)
                S.RealDied=RH.Died:Connect(function()
                    if not S.Active or S.Restoring then return end
                    task.defer(function() Runtime.MM2RestoreOriginalInvisible(true) end)
                end)

                State.MM2Invisible=false
                State.MM2OriginalInvisible=true
                Runtime.LastInvisibleError=nil
                if not Silent then Notify("Invisible","ON • 50% clone • real avatar parked far away") end
                return true
            end

            -- Invisible intent survives genuine server respawns. Temporary silent disables used by
            -- fling do not change the user's wanted state, so the mode comes back only when intended.
            State.MM2InvisibleWanted=State.MM2InvisibleWanted==true
            TrackConnection(Player.CharacterAdded:Connect(function(NewCharacter)
                if not State.MM2InvisibleWanted or Unloaded then return end
                task.defer(function()
                    local Deadline=os.clock()+4
                    repeat
                        if Unloaded or not State.MM2InvisibleWanted then return end
                        local H=NewCharacter and NewCharacter:FindFirstChildOfClass("Humanoid")
                        local R=NewCharacter and NewCharacter:FindFirstChild("HumanoidRootPart")
                        if NewCharacter==Player.Character and H and H.Health>0 and R then break end
                        task.wait(0.08)
                    until os.clock()>=Deadline
                    if not Unloaded and State.MM2InvisibleWanted then
                        local S=Runtime.MM2IYInvisibleState
                        if not (S and S.Active and S.InvisibleCharacter==Player.Character) then
                            pcall(function() Runtime.MM2SetInvisible(true,true) end)
                        end
                    end
                end)
            end))

            local function HasTool(P,Needle)
                if not P then return false end
                local N=string.lower(tostring(Needle or ""))
                for _,Container in pairs({P.Character,P:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Obj in ipairs(Container:GetDescendants()) do
                            if Obj:IsA("Tool") and string.find(string.lower(Obj.Name),N,1,true) then
                                return true,Obj
                            end
                        end
                    end
                end
                return false,nil
            end
            local function NormalRole(Value)
                local Text=string.lower(tostring(Value or ""))
                if string.find(Text,"murder",1,true) or Text=="killer" then return "Murderer" end
                if string.find(Text,"sheriff",1,true) or string.find(Text,"hero",1,true) or Text=="detective" then return "Sheriff / Hero" end
                if string.find(Text,"innocent",1,true) or Text=="civilian" then return "Innocent / Unknown" end
                return nil
            end
            local function ExplicitRole(P)
                for _,Owner in ipairs({P,P and P.Character}) do
                    if Owner then
                        for Key,Value in pairs(Owner:GetAttributes()) do
                            local Lower=string.lower(tostring(Key))
                            if string.find(Lower,"role",1,true) then
                                local Role=NormalRole(Value); if Role then return Role end
                            elseif Value==true then
                                local Role=NormalRole(Key); if Role then return Role end
                            end
                        end
                        for _,Value in ipairs(Owner:GetDescendants()) do
                            if Value:IsA("StringValue") and string.find(string.lower(Value.Name),"role",1,true) then
                                local Role=NormalRole(Value.Value); if Role then return Role end
                            elseif Value:IsA("BoolValue") and Value.Value==true then
                                local Role=NormalRole(Value.Name); if Role then return Role end
                            end
                        end
                    end
                end
                return nil
            end
            if Runtime.MM2RoleDirty==nil then Runtime.MM2RoleDirty=true end
            local function RefreshRoleData()
                Runtime.MM2RoleData=Runtime.MM2RoleData or {}
                local Now=os.clock()
                local Last=tonumber(Runtime.MM2RoleDataAt) or -math.huge

                -- YARHM-style lifecycle: ordinary reads use the cache. Map, tool,
                -- character and role-value events mark it dirty immediately.
                if Runtime.MM2RoleDirty~=true and Now-Last<1.0 then
                    return Runtime.MM2RoleData
                end

                Runtime.MM2RoleDataAt=Now
                Runtime.MM2RoleDirty=false
                local Remote=ReplicatedStorage:FindFirstChild("GetPlayerData",true)
                if not Remote or not Remote:IsA("RemoteFunction") then
                    return Runtime.MM2RoleData
                end
                local Ok,Data=pcall(function() return Remote:InvokeServer() end)
                if not Ok or type(Data)~="table" then
                    return Runtime.MM2RoleData
                end
                local Fresh={}
                for Key,Info in pairs(Data) do
                    if type(Info)=="table" then
                        local Role=NormalRole(Info.Role or Info.role or Info.Status or Info.status)
                        if Role then Fresh[tostring(Key)]=Role end
                    else
                        local Role=NormalRole(Info)
                        if Role then Fresh[tostring(Key)]=Role end
                    end
                end
                Runtime.MM2RoleData=Fresh
                return Fresh
            end
            local function InvalidateMM2Roles()
                Runtime.MM2RoleDataAt=-math.huge
                Runtime.MM2RoleDirty=true
            end
            local function WatchMM2RolePlayer(P)
                if not P then return end
                local function WatchCharacter(C)
                    if not C then return end
                    TrackConnection(C.ChildAdded:Connect(function(Obj) if Obj:IsA("Tool") or Obj:IsA("ValueBase") then InvalidateMM2Roles() end end))
                    TrackConnection(C.ChildRemoved:Connect(function(Obj) if Obj:IsA("Tool") or Obj:IsA("ValueBase") then InvalidateMM2Roles() end end))
                    TrackConnection(C.AttributeChanged:Connect(InvalidateMM2Roles))
                end
                WatchCharacter(P.Character)
                TrackConnection(P.CharacterAdded:Connect(function(C) InvalidateMM2Roles(); WatchCharacter(C) end))
                local Backpack=P:FindFirstChildOfClass("Backpack")
                if Backpack then
                    TrackConnection(Backpack.ChildAdded:Connect(function(Obj) if Obj:IsA("Tool") then InvalidateMM2Roles() end end))
                    TrackConnection(Backpack.ChildRemoved:Connect(function(Obj) if Obj:IsA("Tool") then InvalidateMM2Roles() end end))
                end
            end
            for _,P in ipairs(Runtime.CachedPlayers()) do WatchMM2RolePlayer(P) end
            TrackConnection(Players.PlayerAdded:Connect(function(P) InvalidateMM2Roles(); task.defer(function() WatchMM2RolePlayer(P) end) end))
            TrackConnection(Players.PlayerRemoving:Connect(InvalidateMM2Roles))

            local function RoleOf(P)
                if not P then return "Innocent / Unknown" end
                local RoleData=RefreshRoleData()
                local Cached=RoleData[tostring(P)] or RoleData[P.Name] or RoleData[tostring(P.UserId)]
                if Cached then return Cached end
                local Explicit=ExplicitRole(P)
                if Explicit then return Explicit end
                if HasTool(P,"knife") then return "Murderer" end
                if HasTool(P,"gun") then
                    return "Sheriff / Hero"
                end
                return "Innocent / Unknown"
            end
            local function RoleColor(Role)
                if Role=="Murderer" then return State.MM2ESPMurdererColor end
                if Role=="Sheriff / Hero" then return State.MM2ESPSheriffColor end
                return State.MM2ESPInnocentColor
            end
            Runtime.MM2RoleForPlayer=RoleOf
            Runtime.MM2RoleColorForPlayer=function(P)
                return RoleColor(RoleOf(P))
            end
            local function IsAlive(P)
                local C=P and P.Character
                local H=C and C:FindFirstChildOfClass("Humanoid")
                local R=C and C:FindFirstChild("HumanoidRootPart")
                return H and R and H.Health>0
            end
            local function IsProtected(P)
                if not P or P==Player then return true end
                if not State.MM2IgnoreFriends then return false end
                local Ok,Friends=pcall(function() return Player:IsFriendsWith(P.UserId) end)
                return Ok and Friends or false
            end
            local function FindRolePlayer(RoleNeedle)
                RoleNeedle=string.lower(tostring(RoleNeedle or ""))
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    if P~=Player and IsAlive(P) and string.find(string.lower(RoleOf(P)),RoleNeedle,1,true) then
                        return P
                    end
                end
                return nil
            end
            Runtime.MM2FlingGeneration=tonumber(Runtime.MM2FlingGeneration) or 0
            Runtime.MM2FlingActive=false
            Runtime.MM2FlingPlayer=function(Target,Label)
                if not Target or Target==Player or not IsAlive(Target) then
                    Notify("MM2 Fling",tostring(Label or "Target").." is not available right now.")
                    return false
                end
                Runtime.MM2FlingGeneration=(tonumber(Runtime.MM2FlingGeneration) or 0)+1
                local Generation=Runtime.MM2FlingGeneration
                Runtime.MM2FlingActive=true
                Runtime.CancelMM2Travel()
                local FlingMovementOwner="MM2Fling"
                if Runtime.Movement and Runtime.Movement.Claim then
                    Runtime.Movement.Claim(FlingMovementOwner)
                    Runtime.Movement.SetState("Target","Holding verified target contact",tostring(Label or Target.Name))
                end
                local function ReleaseFlingMovement()
                    if Runtime.Movement and Runtime.Movement.Release then
                        Runtime.Movement.Release(FlingMovementOwner)
                    end
                end

                local WasOriginalInvisible=State.MM2OriginalInvisible==true
                local WasLegacyInvisible=State.MM2Invisible==true
                local WasUniversalInvisible=Runtime.UniversalInvisibleState and Runtime.UniversalInvisibleState.Active==true
                if WasOriginalInvisible and Runtime.MM2SetInvisible then pcall(function() Runtime.MM2SetInvisible(false,true) end); task.wait(0.10)
                elseif WasUniversalInvisible and Runtime.SetUniversalInvisible then pcall(function() Runtime.SetUniversalInvisible(false,true) end); task.wait(0.10)
                elseif WasLegacyInvisible and Runtime.MM2LegacySetInvisible then pcall(function() Runtime.MM2LegacySetInvisible(false,true) end); task.wait(0.10) end

                local function ResumePriorInvisible()
                    task.defer(function()
                        task.wait(0.08)
                        if Unloaded then return end
                        if WasOriginalInvisible and Runtime.MM2SetInvisible then pcall(function() Runtime.MM2SetInvisible(true,true) end)
                        elseif WasUniversalInvisible and Runtime.SetUniversalInvisible then pcall(function() Runtime.SetUniversalInvisible(true,true) end)
                        elseif WasLegacyInvisible and Runtime.MM2LegacySetInvisible then pcall(function() Runtime.MM2LegacySetInvisible(true,true) end) end
                    end)
                end

                local function GetTargetRig()
                    local TC=Target and Target.Character
                    local TH=TC and TC:FindFirstChildOfClass("Humanoid")
                    local TR=TC and (TC:FindFirstChild("HumanoidRootPart") or TC:FindFirstChild("UpperTorso") or TC:FindFirstChild("Torso") or TC:FindFirstChild("Head"))
                    return TC,TH,TR
                end

                local function BuildContactParts(TC,TR)
                    local Result={}
                    local Seen={}
                    local function Push(Part)
                        if Part and Part:IsA("BasePart") and Part.Parent and not Seen[Part] and not Part.Anchored then
                            Seen[Part]=true
                            table.insert(Result,Part)
                        end
                    end
                    -- Prefer body pieces that can actually transfer physics, but never require
                    -- CanCollide because some MM2 rigs change collision locally during rounds.
                    for _,Name in ipairs({"UpperTorso","Torso","LowerTorso","HumanoidRootPart","Head"}) do
                        local P=TC and TC:FindFirstChild(Name)
                        if P and P:IsA("BasePart") and P.CanCollide then Push(P) end
                    end
                    for _,Name in ipairs({"UpperTorso","Torso","LowerTorso","HumanoidRootPart","Head","LeftUpperLeg","RightUpperLeg","Left Leg","Right Leg"}) do
                        Push(TC and TC:FindFirstChild(Name))
                    end
                    if #Result==0 then Push(TR) end
                    return Result
                end

                local Char,H,R=Character(),Humanoid(),Root()
                local TC,TH,TR=GetTargetRig()
                if not Char or not H or not R or not TC or not TH or not TR then
                    Runtime.MM2FlingActive=false; ResumePriorInvisible(); ReleaseFlingMovement()
                    Notify("MM2 Fling","Could not lock onto "..tostring(Label or Target.Name)..".")
                    return false
                end

                local Start=R.CFrame
                Runtime.MM2LastFlingOrigin=Start
                local OldAutoRotate,OldPlatformStand,OldSit=H.AutoRotate,H.PlatformStand,H.Sit
                local OldSeated=true
                pcall(function() OldSeated=H:GetStateEnabled(Enum.HumanoidStateType.Seated) end)
                pcall(function() H:SetStateEnabled(Enum.HumanoidStateType.Seated,false) end)
                H.AutoRotate=false
                H.PlatformStand=false
                H.Sit=false

                -- Angular force keeps the entire local rig sweeping through the target.  v5.14.73
                -- also used a permanent BodyVelocity; that fought the target-lock CFrame and made
                -- contact inconsistent.  This version keeps only the spin force and applies linear
                -- velocity directly on each contact heartbeat.
                local Spin=Instance.new("BodyAngularVelocity")
                Spin.Name="BananiHub_MM2FlingSpin"
                Spin.AngularVelocity=Vector3.new(120000,120000,120000)
                Spin.MaxTorque=Vector3.new(math.huge,math.huge,math.huge)
                Spin.P=math.huge
                Spin.Parent=R

                local FlingDetected=false
                local DetectionReason=nil
                local HadContact=false
                local OK,Err=pcall(function()
                    local OverallStarted=os.clock()
                    local HardStopAfter=8.5
                    local MaxAttempts=4
                    local ContactOffsets={
                        Vector3.new(0,0,0),
                        Vector3.new(0.18,0,0),Vector3.new(-0.18,0,0),
                        Vector3.new(0,0,0.18),Vector3.new(0,0,-0.18),
                        Vector3.new(0,0.20,0),Vector3.new(0,-0.16,0),
                        Vector3.new(0.30,0.12,0.30),Vector3.new(-0.30,0.12,-0.30)
                    }

                    for Attempt=1,MaxAttempts do
                        if FlingDetected or Unloaded or Runtime.MM2FlingGeneration~=Generation then break end
                        TC,TH,TR=GetTargetRig()
                        if not TC or not TH or TH.Health<=0 or not TR or not TR.Parent then break end

                        local AttemptStarted=os.clock()
                        local AttemptDuration=(Attempt==1 and 2.45) or 1.75
                        local TargetStart=TR.Position
                        local BaselineVelocity=TR.AssemblyLinearVelocity
                        local BaselineSpeed=BaselineVelocity.Magnitude
                        local BaselineVertical=math.abs(BaselineVelocity.Y)
                        local ConfirmSamples=0
                        local LaunchConfirmedAt=nil
                        local StepIndex=0
                        local ContactParts=BuildContactParts(TC,TR)
                        local LastPartsRefresh=os.clock()

                        while not Unloaded
                            and Runtime.MM2FlingGeneration==Generation
                            and not FlingDetected
                            and os.clock()-OverallStarted<HardStopAfter
                            and os.clock()-AttemptStarted<AttemptDuration do

                            TC,TH,TR=GetTargetRig()
                            if not TC or not TH or TH.Health<=0 or not TR or not TR.Parent then break end
                            R=Root(); Char=Character()
                            if not R or not Char then break end

                            if os.clock()-LastPartsRefresh>0.22 then
                                ContactParts=BuildContactParts(TC,TR)
                                LastPartsRefresh=os.clock()
                            end
                            if #ContactParts==0 then ContactParts={TR} end

                            StepIndex+=1
                            local ContactPart=ContactParts[((math.floor((StepIndex-1)/3))%#ContactParts)+1] or TR
                            if not ContactPart or not ContactPart.Parent then ContactPart=TR end
                            local Offset=ContactOffsets[((StepIndex-1)%#ContactOffsets)+1]
                            local TV=TR.AssemblyLinearVelocity
                            local Lead=Vector3.new(TV.X,0,TV.Z)*math.clamp(0.008+(Attempt-1)*0.002,0.008,0.016)
                            local A=math.rad((StepIndex*67)%360)
                            local InsideCF=CFrame.new(ContactPart.Position+Lead+Offset)*CFrame.Angles(A,A*0.73,A*1.19)

                            pcall(function()
                                Char:PivotTo(InsideCF)
                                R.CFrame=InsideCF
                                -- Strong but finite impulses: target-lock contact does the work instead
                                -- of 9e8 velocity spam fighting replication every heartbeat.
                                R.AssemblyLinearVelocity=Vector3.new(1800,7200,1800)
                                R.AssemblyAngularVelocity=Vector3.new(120000,120000,120000)
                                R.Velocity=Vector3.new(1800,7200,1800)
                                R.RotVelocity=Vector3.new(120000,120000,120000)
                            end)
                            local ContactDistance=(R.Position-ContactPart.Position).Magnitude
                            if ContactDistance<=math.max(3.5,ContactPart.Size.Magnitude*0.65) then HadContact=true end

                            local TargetVelocity=TR.AssemblyLinearVelocity
                            local TargetSpeed=TargetVelocity.Magnitude
                            local TargetVertical=math.abs(TargetVelocity.Y)
                            local TargetTravel=(TR.Position-TargetStart).Magnitude
                            local SpeedThreshold=math.max(115,BaselineSpeed+55)
                            local VerticalThreshold=math.max(90,BaselineVertical+55)
                            local StateNow=TH:GetState()
                            local AirState=(StateNow==Enum.HumanoidStateType.Freefall)
                                or (StateNow==Enum.HumanoidStateType.FallingDown)
                                or (StateNow==Enum.HumanoidStateType.Physics)

                            local StrongLaunch=(TargetSpeed>=SpeedThreshold)
                                or (TargetVertical>=VerticalThreshold)
                                or (TargetTravel>=24 and TargetSpeed>=60)
                                or (AirState and TargetTravel>=15 and TargetSpeed>=75)

                            if os.clock()-AttemptStarted>=0.18 and StrongLaunch then
                                ConfirmSamples+=1
                            else
                                ConfirmSamples=math.max(0,ConfirmSamples-1)
                                if ConfirmSamples==0 then LaunchConfirmedAt=nil end
                            end

                            -- Require several consecutive samples, then keep contact a little longer.
                            -- This avoids returning because of one normal jump/run velocity spike.
                            if ConfirmSamples>=3 and not LaunchConfirmedAt then
                                LaunchConfirmedAt=os.clock()
                            end
                            if LaunchConfirmedAt and os.clock()-LaunchConfirmedAt>=0.20 then
                                local FinalSpeed=TR.AssemblyLinearVelocity.Magnitude
                                local FinalTravel=(TR.Position-TargetStart).Magnitude
                                if FinalSpeed>=70 or FinalTravel>=24 then
                                    FlingDetected=true
                                    DetectionReason="sustained launch confirmed"
                                    break
                                else
                                    ConfirmSamples=0
                                    LaunchConfirmedAt=nil
                                end
                            end

                            RunService.Heartbeat:Wait()
                        end

                        if not FlingDetected and Attempt<MaxAttempts and os.clock()-OverallStarted<HardStopAfter then
                            -- Do not return between retries.  Refresh target/body-part selection and
                            -- immediately make another sticky-contact pass under the same button press.
                            task.wait(0.04)
                        end
                    end
                end)

                pcall(function() Spin:Destroy() end)

                local LiveChar=Character() or Char
                local LiveR=Root() or R
                local LiveH=Humanoid() or H
                local function ZeroFlingVelocity(CharacterModel)
                    if not CharacterModel then return end
                    for _,Part in ipairs(CharacterModel:GetDescendants()) do
                        if Part:IsA("BasePart") then
                            pcall(function()
                                Part.AssemblyLinearVelocity=Vector3.zero
                                Part.AssemblyAngularVelocity=Vector3.zero
                                Part.Velocity=Vector3.zero
                                Part.RotVelocity=Vector3.zero
                            end)
                        end
                    end
                end

                ZeroFlingVelocity(LiveChar)
                if LiveH then
                    LiveH.AutoRotate=OldAutoRotate
                    LiveH.PlatformStand=false
                    LiveH.Sit=false
                    pcall(function() LiveH:SetStateEnabled(Enum.HumanoidStateType.Seated,OldSeated) end)
                end

                -- Return only after a confirmed launch, an explicit stop/cancel, or the hard safety
                -- timeout.  The timeout exists so a target that cannot receive client physics does
                -- not leave the local player spinning forever.
                local Returned=false
                if LiveChar and typeof(Start)=="CFrame" then
                    local ReturnStarted=os.clock()
                    repeat
                        LiveR=Root() or LiveR
                        ZeroFlingVelocity(LiveChar)
                        pcall(function() LiveChar:PivotTo(Start) end)
                        if LiveR then
                            pcall(function()
                                LiveR.CFrame=Start
                                LiveR.AssemblyLinearVelocity=Vector3.zero
                                LiveR.AssemblyAngularVelocity=Vector3.zero
                                LiveR.Velocity=Vector3.zero
                                LiveR.RotVelocity=Vector3.zero
                            end)
                            Returned=(LiveR.Position-Start.Position).Magnitude<=2.0
                        end
                        RunService.Heartbeat:Wait()
                    until Returned or os.clock()-ReturnStarted>=0.65 or Unloaded

                    if not Unloaded then
                        task.wait(0.06)
                        LiveR=Root() or LiveR
                        ZeroFlingVelocity(LiveChar)
                        if LiveR and (LiveR.Position-Start.Position).Magnitude>2.0 then
                            pcall(function() LiveChar:PivotTo(Start) end)
                            pcall(function() LiveR.CFrame=Start end)
                            ZeroFlingVelocity(LiveChar)
                        end
                    end
                end

                if LiveH then
                    LiveH.AutoRotate=OldAutoRotate
                    LiveH.PlatformStand=OldPlatformStand
                    LiveH.Sit=OldSit
                    pcall(function() LiveH:SetStateEnabled(Enum.HumanoidStateType.Seated,OldSeated) end)
                    pcall(function() LiveH:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                end

                Runtime.MM2FlingActive=false
                ReleaseFlingMovement()
                ResumePriorInvisible()
                if OK then
                    if FlingDetected then
                        Notify("MM2 Fling",tostring(Label or Target.Name).." launch confirmed • returned to your exact saved spot.")
                    elseif HadContact then
                        Notify("MM2 Fling",tostring(Label or Target.Name).." stayed in contact but Roblox did not confirm a launch • safety return used.")
                    else
                        Notify("MM2 Fling",tostring(Label or Target.Name).." could not be physically contacted • safety return used.")
                    end
                else
                    Notify("MM2 Fling","Fling stopped safely: "..tostring(Err))
                end
                return OK and FlingDetected
            end
            Runtime.MM2FlingRole=function(RoleNeedle,Label)
                local Target=FindRolePlayer(RoleNeedle)
                if not Target and string.find(string.lower(tostring(RoleNeedle)),"sheriff",1,true) then
                    Target=FindRolePlayer("hero")
                end
                if not Target then
                    Notify("MM2 Fling",tostring(Label or RoleNeedle).." has not been detected.")
                    return false
                end
                return Runtime.MM2FlingPlayer(Target,Label or Target.Name)
            end
            Runtime.MM2StopFling=function(ReturnToOrigin)
                Runtime.MM2FlingGeneration=(tonumber(Runtime.MM2FlingGeneration) or 0)+1
                Runtime.MM2FlingActive=false
                local R=Root()
                if R then
                    local Spinner=R:FindFirstChild("BananiHub_MM2FlingSpin")
                    if Spinner then pcall(function() Spinner:Destroy() end) end
                    pcall(function()
                        R.AssemblyLinearVelocity=Vector3.zero
                        R.AssemblyAngularVelocity=Vector3.zero
                    end)
                end
                if ReturnToOrigin and typeof(Runtime.MM2LastFlingOrigin)=="CFrame" then
                    local C=Character()
                    if C then
                        pcall(function() C:PivotTo(Runtime.MM2LastFlingOrigin) end)
                        task.wait(0.03)
                        pcall(function() C:PivotTo(Runtime.MM2LastFlingOrigin) end)
                    end
                end
                return true
            end

            local function CurrentMap()
                for _,Obj in ipairs(workspace:GetChildren()) do
                    if Obj:IsA("Model") and Obj.Name~="Lobby" and Obj:FindFirstChild("Spawns") then
                        return Obj
                    end
                end
                for _,Obj in ipairs(workspace:GetChildren()) do
                    if Obj:IsA("Model") and Obj.Name~="Lobby" and Obj:FindFirstChild("CoinContainer",true) then
                        return Obj
                    end
                end
                return nil
            end
            local function LobbyObject()
                return workspace:FindFirstChild("Lobby")
            end
            local function MM2ModelContainsPosition(Model,Position,Padding)
                if not Model or typeof(Position)~="Vector3" then return false end
                local Ok,CF,Size=pcall(function()
                    local BoxCF,BoxSize=Model:GetBoundingBox()
                    return BoxCF,BoxSize
                end)
                if not Ok or typeof(CF)~="CFrame" or typeof(Size)~="Vector3" then return false end
                local Local=CF:PointToObjectSpace(Position)
                local Pad=math.max(0,tonumber(Padding) or 0)
                return math.abs(Local.X)<=Size.X*0.5+Pad
                    and math.abs(Local.Y)<=Size.Y*0.5+Pad
                    and math.abs(Local.Z)<=Size.Z*0.5+Pad
            end
            local function MM2PlayerSurfacePosition(P)
                if not P then return nil end
                if P==Player and State.MM2Invisible and Runtime.MM2SurfacePosition then
                    local Pos=Runtime.MM2SurfacePosition()
                    if typeof(Pos)=="Vector3" then return Pos end
                end
                local C=P.Character
                local R=C and (C:FindFirstChild("HumanoidRootPart") or C:FindFirstChild("UpperTorso") or C:FindFirstChild("Torso"))
                return R and R.Position or nil
            end
            local function MM2PlayerInLobby(P)
                local Pos=MM2PlayerSurfacePosition(P)
                local Lobby=LobbyObject()
                return Pos~=nil and Lobby~=nil and MM2ModelContainsPosition(Lobby,Pos,18)
            end
            local function MM2PlayerInActiveMap(P)
                local Map=CurrentMap()
                local Pos=MM2PlayerSurfacePosition(P)
                if not Map or not Pos or MM2PlayerInLobby(P) then return false end
                return MM2ModelContainsPosition(Map,Pos,35)
            end
            Runtime.MM2PlayerInLobby=MM2PlayerInLobby
            Runtime.MM2PlayerInActiveMap=MM2PlayerInActiveMap
            local function MM2ObjectInActiveMap(Object,Padding)
                local Map=CurrentMap()
                if not Map or not Object or not Object.Parent then return false end
                local Part=nil
                pcall(function() Part=GetRoot(Object) end)
                if not Part or not Part:IsA("BasePart") then
                    if Object:IsA("BasePart") then Part=Object end
                end
                if not Part then return false end
                local Lobby=LobbyObject()
                if Lobby and MM2ModelContainsPosition(Lobby,Part.Position,18) then return false end
                return MM2ModelContainsPosition(Map,Part.Position,tonumber(Padding) or 40)
            end
            Runtime.MM2ObjectInActiveMap=MM2ObjectInActiveMap
            local function CoinContainer()
                local Map=CurrentMap()
                if not Map then return nil end
                local Direct=Map:FindFirstChild("CoinContainer",true)
                if Direct then return Direct end

                for _,Container in ipairs(Runtime.ProfileObjects()) do
                    if Container.Name=="CoinContainer" or Container.Name=="Coins" then
                        for _,Object in ipairs(Container:GetDescendants()) do
                            local R=GetRoot(Object)
                            if R and MM2ObjectInActiveMap(Object,45) then return Container end
                        end
                    end
                end
                return nil
            end
            local function CoinNameMatch(Obj)
                if not Obj then return false end
                local Name=string.lower(tostring(Obj.Name or "")):gsub("[^%w]","")
                if Name=="coin" or Name=="coinserver" or Name=="coinvisual" or Name=="currencycoin" then return true end
                if Name=="beachtoken" or Name=="snowtoken" or Name=="candytoken" or Name=="eventcoin" then return true end
                if string.find(Name,"currencycoin",1,true) or string.find(Name,"eventcoin",1,true) then return true end
                return false
            end
            local function ResolveCoinObject(Object)
                if not Object or not Object.Parent then return nil end
                if string.lower(tostring(Object.Name or "")):gsub("[^%w]","")=="coinvisual" then
                    local Parent=Object.Parent
                    if Parent and Parent.Parent then return Parent end
                    return Object
                end
                if CoinNameMatch(Object) then return Object end
                local Parent=Object.Parent
                if Parent and CoinNameMatch(Parent) then return Parent end

                local Direct=Object:FindFirstChild("CoinVisual")
                if Direct and Direct:IsA("BasePart") then return Object end
                return nil
            end
            local function CoinRoot(Coin)
                Coin=ResolveCoinObject(Coin) or Coin
                if not Coin then return nil end
                if Coin:IsA("BasePart") then return Coin end
                local Visual=Coin:FindFirstChild("CoinVisual",true)
                if Visual and Visual:IsA("BasePart") then return Visual end
                for _,Part in ipairs(Coin:GetDescendants()) do
                    if Part:IsA("BasePart") and (CoinNameMatch(Part) or Part:FindFirstChildOfClass("TouchTransmitter")) then
                        return Part
                    end
                end
                return GetRoot(Coin)
            end
            local function CoinTouchParts(Coin)
                Coin=ResolveCoinObject(Coin) or Coin
                if not Coin then return {} end
                local Priority,Secondary,Seen={},{},{}
                local function Add(Part,High)
                    if Part and Part:IsA("BasePart") and Part.Parent and not Seen[Part] then
                        Seen[Part]=true
                        if High then table.insert(Priority,Part) else table.insert(Secondary,Part) end
                    end
                end
                local function IsTriggerPart(Part)
                    if not Part or not Part:IsA("BasePart") then return false end
                    local N=string.lower(tostring(Part.Name or "")):gsub("[^%w]","")
                    return Part:FindFirstChildOfClass("TouchTransmitter")~=nil
                        or N=="coinserver" or N=="coinhitbox" or N=="touch" or N=="trigger"
                        or string.find(N,"coinserver",1,true)~=nil
                        or string.find(N,"hitbox",1,true)~=nil
                        or string.find(N,"trigger",1,true)~=nil
                end
                if Coin:IsA("BasePart") then Add(Coin,IsTriggerPart(Coin)) end
                for _,Part in ipairs(Coin:GetDescendants()) do
                    if Part:IsA("BasePart") then Add(Part,IsTriggerPart(Part)) end
                end

                local Visual=Coin:IsA("BasePart") and Coin or Coin:FindFirstChild("CoinVisual",true)
                if Visual and Visual:IsA("BasePart") then Add(Visual,false) end
                local RootPart=CoinRoot(Coin)
                if RootPart then Add(RootPart,false) end
                local Out={}
                for _,Part in ipairs(Priority) do table.insert(Out,Part) end
                for _,Part in ipairs(Secondary) do table.insert(Out,Part) end
                return Out
            end

            local function CoinMarkedCollected(Coin)
                if not Coin or not Coin.Parent then return true end
                local function Marked(Obj)
                    if not Obj then return false end
                    local Ok,Value=pcall(function() return Obj:GetAttribute("Collected") end)
                    return Ok and Value==true
                end
                if Marked(Coin) then return true end
                if not Coin:IsA("BasePart") then
                    local Visual=Coin:FindFirstChild("CoinVisual",true)
                    if Marked(Visual) then return true end
                end
                return false
            end

            local function CoinAvailable(Coin)
                if not Coin or not Coin.Parent or CoinMarkedCollected(Coin) then return false end
                for _,Part in ipairs(CoinTouchParts(Coin)) do
                    if Part and Part.Parent and (Part:FindFirstChildOfClass("TouchTransmitter") or string.find(string.lower(Part.Name),"coin_server",1,true) or string.find(string.lower(Part.Name),"coinserver",1,true)) then return true end
                end
                local RootPart=CoinRoot(Coin)
                if RootPart and RootPart.Parent and RootPart.Transparency<0.985 then return true end
                if not Coin:IsA("BasePart") then
                    for _,Part in ipairs(Coin:GetDescendants()) do
                        if Part:IsA("BasePart") and Part.Transparency<0.985 then return true end
                    end
                end
                return false
            end
            local function CoinCandidates()
                local Now=os.clock()
                if Runtime.MM2CoinCache and Now-(Runtime.MM2CoinCacheAt or 0)<0.25 then
                    local Live={}
                    for _,Coin in ipairs(Runtime.MM2CoinCache) do
                        if Coin and Coin.Parent and CoinRoot(Coin) and CoinAvailable(Coin) then Live[#Live+1]=Coin end
                    end
                    Runtime.MM2CoinCache=Live
                    return Live
                end
                local Out,Seen={},{}
                local Lobby=LobbyObject()
                local function InLobby(Object)
                    return Lobby and Object and Object:IsDescendantOf(Lobby)
                end
                local function Add(Object)
                    local Coin=ResolveCoinObject(Object)
                    if not Coin and Object then
                        if Object:IsA("Model") or Object:IsA("Folder") then
                            local Server=Object:FindFirstChild("Coin_Server",true)
                            local Visual=Object:FindFirstChild("CoinVisual",true)
                            if Server or Visual then Coin=Object end
                        end
                    end
                    if Coin and Coin.Parent and not Seen[Coin] and not InLobby(Coin) then
                        local Part=CoinRoot(Coin)
                        if Part and Part.Parent and CoinAvailable(Coin) then
                            Seen[Coin]=true; Out[#Out+1]=Coin
                        end
                    end
                end

                -- Public MM2 scripts still discover active coins through CoinContainer.
                -- Prefer cached profile objects, then do one workspace fallback scan only when needed.
                local Containers={}
                for _,Object in ipairs(Runtime.ProfileObjects()) do
                    if Object.Name=="CoinContainer" then Containers[#Containers+1]=Object end
                end
                if #Containers==0 or Now-(Runtime.MM2LastCoinContainerFallback or 0)>2.0 then
                    Runtime.MM2LastCoinContainerFallback=Now
                    if #Containers==0 then
                        for _,Object in ipairs(workspace:GetDescendants()) do
                            if Object.Name=="CoinContainer" then Containers[#Containers+1]=Object end
                        end
                    end
                end
                for _,Container in ipairs(Containers) do
                    if Container and Container.Parent and not InLobby(Container) then
                        for _,Object in ipairs(Container:GetDescendants()) do Add(Object) end
                        for _,Object in ipairs(Container:GetChildren()) do Add(Object) end
                    end
                end
                for _,Tag in ipairs({"Coin","Coin_Server","CoinVisual","BeachToken","SnowToken","CandyToken","EventCoin"}) do
                    local Ok,Tagged=pcall(function() return CollectionService:GetTagged(Tag) end)
                    if Ok then for _,Object in ipairs(Tagged) do Add(Object) end end
                end
                Runtime.MM2CoinCache=Out
                Runtime.MM2CoinCacheAt=Now
                Runtime.MM2CoinCacheMap=CurrentMap()
                return Out
            end

            Runtime.MM2TryProxyCoinPickup=function(Radius,PreferredCoin)
                if not State.MM2Invisible then return false end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then return false end
                local S=Runtime.MM2InvisibleState
                if S.ProxyCoinBusy or S.WeaponPickupBusy or S.SurfaceActionActive or S.SurfaceWeaponBusy then return false end
                local Pos=Runtime.MM2SurfacePosition()
                if not Pos then return false end
                Radius=math.clamp(tonumber(Radius) or 6,3,12)
                S.ProxyCoinDebounce=S.ProxyCoinDebounce or setmetatable({}, {__mode="k"})

                local Exact=PreferredCoin and ResolveCoinObject(PreferredCoin) or nil
                local Best,BestPart,BestDistance=nil,nil,Radius
                for _,Coin in ipairs(Exact and {Exact} or CoinCandidates()) do
                    local ServerPart=nil
                    if Coin and Coin:IsA("BasePart") then
                        ServerPart=Coin
                    elseif Coin then

                        for _,Part in ipairs(CoinTouchParts(Coin)) do
                            if Part:FindFirstChildOfClass("TouchTransmitter") or Part:FindFirstChild("TouchInterest") then
                                ServerPart=Part
                                break
                            end
                        end
                        ServerPart=ServerPart or CoinRoot(Coin)
                    end
                    if ServerPart and CoinAvailable(Coin) and MM2ObjectInActiveMap(Coin,45) then
                        local D=(ServerPart.Position-Pos).Magnitude
                        local Last=tonumber(S.ProxyCoinDebounce[Coin]) or 0
                        if D<=BestDistance and os.clock()-Last>=0.24 then
                            Best,BestPart,BestDistance=Coin,ServerPart,D
                        end
                    end
                end
                if Exact and Best~=Exact then return false end
                if not Best or not BestPart then return false end

                S.ProxyCoinDebounce[Best]=os.clock()
                S.ProxyCoinBusy=true
                task.spawn(function()
                    local function Finish()
                        S.ProxyCoinBusy=false
                    end
                    local Ok=pcall(function()
                        local RealChar=(Runtime.MM2RealCharacter and Runtime.MM2RealCharacter()) or Player.Character
                        local RealRoot=RealChar and RealChar:FindFirstChild("HumanoidRootPart")
                        local ProxyRoot=S.ProxyRoot
                        if not RealChar or not RealRoot or not ProxyRoot or not ProxyRoot.Parent or not Best.Parent or not BestPart.Parent then return end

                        local Rotation=ProxyRoot.CFrame.Rotation
                        local function RelayAt(YOffset,Frames,Hold)
                            if not BestPart or not BestPart.Parent or not CoinAvailable(Best) then return end
                            local CF=CFrame.new(BestPart.Position+Vector3.new(0,YOffset or 0,0))*Rotation
                            Runtime.MM2WithSurfaceShell(function()

                                pcall(function() RealRoot.CanTouch=true end)
                                if type(firetouchinterest)=="function" then
                                    pcall(function() firetouchinterest(RealRoot,BestPart,0) end)
                                end
                                for _=1,2 do RunService.Heartbeat:Wait() end
                                if type(firetouchinterest)=="function" and BestPart.Parent then
                                    pcall(function() firetouchinterest(RealRoot,BestPart,1) end)
                                end
                            end,Hold or 0.18,Frames or 6,CF)
                        end

                        RelayAt(0.15,6,0.20)

                        local Deadline=os.clock()+0.55
                        repeat
                            if not CoinAvailable(Best) then break end
                            task.wait(0.03)
                        until os.clock()>=Deadline or not State.MM2Invisible or Unloaded

                        if CoinAvailable(Best) and State.MM2Invisible and not Unloaded then
                            RelayAt(0.9,3,0.08)
                            RelayAt(-0.25,4,0.14)
                        end

                        local FinalDeadline=os.clock()+0.55
                        repeat
                            if not CoinAvailable(Best) then break end
                            task.wait(0.03)
                        until os.clock()>=FinalDeadline or not State.MM2Invisible or Unloaded

                        if not CoinAvailable(Best) then
                            Runtime.MM2CoinCacheAt=0
                            Runtime.MM2FailedCoins[Best]=nil
                            local Route=Runtime.MM2RollingRoute or {}
                            local Index=table.find(Route,Best)
                            if Index then table.remove(Route,Index) end
                        else
                            Runtime.MM2FailedCoins=Runtime.MM2FailedCoins or {}
                            Runtime.MM2FailedCoins[Best]=os.clock()
                        end
                    end)
                    Finish()
                end)
                return true
            end

            local function OrderedCoinRoute(Maximum)
                local Me=Root()
                if not Me then return {} end
                Maximum=math.clamp(tonumber(Maximum) or 6,1,8)
                Runtime.MM2FailedCoins=Runtime.MM2FailedCoins or {}
                local Candidates={}
                for _,Coin in ipairs(CoinCandidates()) do
                    local Part=CoinRoot(Coin)
                    if Part and CoinAvailable(Coin)
                        and os.clock()-(Runtime.MM2FailedCoins[Coin] or -math.huge)>=3
                        and Part.Position.Y>workspace.FallenPartsDestroyHeight+8 then
                        Candidates[#Candidates+1]={Coin=Coin,Part=Part,Distance=(Part.Position-Me.Position).Magnitude}
                    end
                end
                table.sort(Candidates,function(A,B) return A.Distance<B.Distance end)
                local Route={}
                local Position=Me.Position
                local Used={}
                while #Route<Maximum do
                    local Best,BestDistance=nil,math.huge
                    for _,Item in ipairs(Candidates) do
                        if not Used[Item.Coin] and Item.Part and Item.Part.Parent then
                            local D=(Item.Part.Position-Position).Magnitude
                            if D<BestDistance then Best,BestDistance=Item,D end
                        end
                    end
                    if not Best then break end
                    Used[Best.Coin]=true; Route[#Route+1]=Best.Coin; Position=Best.Part.Position
                end
                Runtime.MM2RollingRoute=Route
                return Route
            end
            local function ClearMM2CoinPath()
                if Runtime.MM2CoinPathFolder then pcall(function() Runtime.MM2CoinPathFolder:Destroy() end) end
                Runtime.MM2CoinPathFolder=nil
                Runtime.MM2CoinPathParts={}
            end
            Runtime.ClearMM2CoinPath=ClearMM2CoinPath
            local function UpdateMM2CoinPath()
                if not State.MM2CoinPath then ClearMM2CoinPath(); return end
                local Me=Root()
                if not Me then ClearMM2CoinPath(); return end
                local Folder=Runtime.MM2CoinPathFolder
                if not Folder or not Folder.Parent then
                    Folder=Instance.new("Folder")
                    Folder.Name="__BananiMM2CoinRoute"
                    Folder.Parent=workspace
                    Runtime.MM2CoinPathFolder=Folder
                    Runtime.MM2CoinPathParts={}
                end
                local Parts=Runtime.MM2CoinPathParts or {}
                Runtime.MM2CoinPathParts=Parts
                for _,Line in ipairs(Parts) do Line.Transparency=1 end
                local Previous=Me.Position
                local Route=Runtime.MM2RollingRoute or {}
                local Points={}
                for Index,Coin in ipairs(Route) do
                    local Part=CoinRoot(Coin)
                    if not Part then continue end
                    local Goal=Part.Position+Vector3.new(0,1.25,0)
                    if State.MM2FarmMode=="Underground Tween" then
                        if Index==1 and Runtime.ActiveTravelWaypoints then
                            for I=Runtime.ActiveTravelWaypointIndex or 1,#Runtime.ActiveTravelWaypoints do table.insert(Points,Runtime.ActiveTravelWaypoints[I]) end
                        else
                            local Start=Points[#Points] or Me.Position
                            local Y=math.min(Start.Y,Goal.Y)-5.5
                            table.insert(Points,Vector3.new(Start.X,Y,Start.Z))
                            table.insert(Points,Vector3.new(Goal.X,Y,Goal.Z))
                            table.insert(Points,Goal)
                        end
                    else table.insert(Points,Goal) end
                end
                for Index,Position in ipairs(Points) do
                    local Delta=Position-Previous
                    if Delta.Magnitude>0.25 then
                        local Line=Parts[Index]
                        if not Line then
                            Line=Runtime.TrackTransient(Instance.new("Part"),"TransientParts")
                            Line.Name="CoinRoute_"..Index
                            Line.Anchored=true; Line.CanCollide=false; Line.CanTouch=false; Line.CanQuery=false
                            Line.CastShadow=false; Line.Material=Enum.Material.Neon
                            Line.Color=Color3.fromRGB(255,215,45)
                            Line.Parent=Folder
                            Parts[Index]=Line
                        end
                        Line.Transparency=0.12
                        Line.Size=Vector3.new(0.16,0.16,Delta.Magnitude)
                        Line.CFrame=CFrame.lookAt(Previous:Lerp(Position,0.5),Position)
                    end
                    Previous=Position
                end
                local Used=#Points
                for Index=Used+1,#Parts do Parts[Index].Transparency=1 end
            end
            local function NextCoin()
                local Route=OrderedCoinRoute(6)
                return Route[1]
            end
            local function GunDrop()
                local Cached=Runtime.MM2CachedGunDrop
                if Cached and Cached.Parent and GetRoot(Cached) then return Cached end
                local Map=CurrentMap()
                local Best,BestDistance=nil,math.huge
                local LocalPos=MM2PlayerSurfacePosition(Player)
                local Seen={}
                local function Normalize(Name)
                    return string.lower(tostring(Name or "")):gsub("[^%w]","")
                end
                local function IsDroppedGunName(Object)
                    if not Object then return false end
                    local N=Normalize(Object.Name)
                    if N=="gundrop" or N=="droppedgun" or N=="sheriffgun" or N=="gunpickup" then return true end
                    if N=="gun" then
                        -- A bare Gun is only accepted when it belongs to the live map, never a
                        -- player's Character/Backpack tool.
                        local Model=Object:FindFirstAncestorOfClass("Model")
                        if Model and IsPlayerCharacter(Model) then return false end
                        local Tool=Object:FindFirstAncestorOfClass("Tool")
                        if Tool and Tool.Parent and (Tool.Parent:IsA("Backpack") or IsPlayerCharacter(Tool.Parent)) then return false end
                        return Map and Object:IsDescendantOf(Map) or false
                    end
                    return string.find(N,"gundrop",1,true)~=nil or string.find(N,"droppedgun",1,true)~=nil
                end
                local function Canonical(Object)
                    if not Object then return nil end
                    local Node=Object
                    for _=1,4 do
                        if not Node or (Map and Node==Map) then break end
                        if IsDroppedGunName(Node) and GetRoot(Node) then return Node end
                        Node=Node.Parent
                    end
                    return IsDroppedGunName(Object) and Object or nil
                end
                local function Consider(Object)
                    Object=Canonical(Object)
                    if not Object or not Object.Parent or Seen[Object] then return end
                    Seen[Object]=true
                    local Model=Object:FindFirstAncestorOfClass("Model")
                    if Model and IsPlayerCharacter(Model) then return end
                    local R=GetRoot(Object)
                    if not R then return end
                    if Map and not Object:IsDescendantOf(Map) then return end
                    -- Do not require the old map-bounding-box test here. Some MM2 maps contain
                    -- detached/rotated geometry that made a valid GunDrop fail that test.
                    local D=LocalPos and (R.Position-LocalPos).Magnitude or 0
                    if D<BestDistance then Best,BestDistance=Object,D end
                end

                -- Fast exact-name checks cover the normal MM2 GunDrop layout immediately.
                if Map then
                    for _,Name in ipairs({"GunDrop","DroppedGun","Gun_Drop","SheriffGun","GunPickup"}) do
                        local Direct=Map:FindFirstChild(Name,true)
                        if Direct then Consider(Direct) end
                    end
                end

                -- ProfileObjects can be stale during a round transition, so use it as an additional source.
                for _,Obj in ipairs(Runtime.ProfileObjects()) do
                    if Obj and Obj.Parent and (not Map or Obj:IsDescendantOf(Map)) and IsDroppedGunName(Obj) then Consider(Obj) end
                end

                if Map then
                    for _,Obj in ipairs(Map:GetDescendants()) do
                        if IsDroppedGunName(Obj) then Consider(Obj) end
                    end
                end

                -- Some current MM2 maps place GunDrop beside/outside the detected map Model.
                -- Throttle a workspace fallback instead of failing Gun ESP when CurrentMap is stale.
                Runtime.MM2GunGlobalScanAt=tonumber(Runtime.MM2GunGlobalScanAt) or -math.huge
                if not Best and os.clock()-Runtime.MM2GunGlobalScanAt>=4.0 then
                    Runtime.MM2GunGlobalScanAt=os.clock()
                    for _,Obj in ipairs(workspace:GetDescendants()) do
                        if IsDroppedGunName(Obj) then
                            local Model=Obj:FindFirstAncestorOfClass("Model")
                            local Tool=Obj:FindFirstAncestorOfClass("Tool")
                            if not (Model and IsPlayerCharacter(Model))
                                and not (Tool and Tool.Parent and (Tool.Parent:IsA("Backpack") or IsPlayerCharacter(Tool.Parent))) then
                                local OldMap=Map
                                Map=nil
                                Consider(Obj)
                                Map=OldMap
                            end
                        end
                    end
                end
                if Best then Runtime.MM2CachedGunDrop=Best end
                return Best
            end
            -- Event-driven GunDrop cache. Public MM2 hubs such as YARHM react to
            -- GunDrop add/remove events rather than relying on a permanent polling scan.
            local function MM2EventGunCandidate(Object)
                local Node=Object
                for _=1,5 do
                    if not Node then break end
                    local N=string.lower(tostring(Node.Name or "")):gsub("[^%w]","")
                    local Match=N=="gundrop" or N=="droppedgun" or N=="sheriffgun" or N=="gunpickup"
                        or string.find(N,"gundrop",1,true)~=nil or string.find(N,"droppedgun",1,true)~=nil
                    if Match and GetRoot(Node) then
                        local Model=Node:FindFirstAncestorOfClass("Model")
                        local Tool=Node:FindFirstAncestorOfClass("Tool")
                        if not (Model and IsPlayerCharacter(Model))
                            and not (Tool and Tool.Parent and (Tool.Parent:IsA("Backpack") or IsPlayerCharacter(Tool.Parent))) then
                            return Node
                        end
                    end
                    Node=Node.Parent
                end
                return nil
            end
            local function MM2CacheGunEvent(Object)
                local Candidate=MM2EventGunCandidate(Object)
                if not Candidate then return end
                Runtime.MM2CachedGunDrop=Candidate
                Runtime.MM2GunGlobalScanAt=-math.huge
            end
            TrackConnection(workspace.DescendantAdded:Connect(function(Object)
                if Unloaded then return end
                MM2CacheGunEvent(Object)
            end))
            TrackConnection(workspace.DescendantRemoving:Connect(function(Object)
                local Cached=Runtime.MM2CachedGunDrop
                if Cached and (Object==Cached or (Cached.Parent and Cached:IsDescendantOf(Object))) then
                    Runtime.MM2CachedGunDrop=nil
                    Runtime.MM2GunGlobalScanAt=-math.huge
                end
            end))
            task.defer(function()
                local Map=CurrentMap()
                Runtime.MM2CurrentMap=Map
                if Map then
                    for _,Object in ipairs(Map:GetDescendants()) do
                        local Candidate=MM2EventGunCandidate(Object)
                        if Candidate then Runtime.MM2CachedGunDrop=Candidate; break end
                    end
                end
            end)

            -- YARHM reacts when the round map is added/removed. Use the same lifecycle
            -- idea to invalidate role/gun/coin state rather than polling the whole game.
            local function MM2MapCandidate(Object)
                if not Object or not Object:IsA("Model") or Object.Name=="Lobby" then return false end
                return Object:FindFirstChild("Spawns")~=nil
                    or Object:FindFirstChild("CoinContainer",true)~=nil
            end
            local function ResetMM2RoundCache(MapLoaded)
                InvalidateMM2Roles()
                Runtime.MM2CachedGunDrop=nil
                Runtime.MM2GunGlobalScanAt=-math.huge
                Runtime.MM2CoinCacheAt=-math.huge
                Runtime.MM2CoinCacheMap=nil
                Runtime.MM2ESPWaitingForRound=true
                if not MapLoaded then
                    Runtime.MM2RoleData={}
                    Runtime.MM2RoleDataAt=-math.huge
                end
            end
            TrackConnection(workspace.ChildAdded:Connect(function(Object)
                if Unloaded or not MM2MapCandidate(Object) then return end
                Runtime.MM2CurrentMap=Object
                ResetMM2RoundCache(true)
                task.delay(0.35,function()
                    if Unloaded or Runtime.MM2CurrentMap~=Object or not Object.Parent then return end
                    for _,Descendant in ipairs(Object:GetDescendants()) do
                        local Candidate=MM2EventGunCandidate(Descendant)
                        if Candidate then Runtime.MM2CachedGunDrop=Candidate; break end
                    end
                    InvalidateMM2Roles()
                end)
            end))
            TrackConnection(workspace.ChildRemoved:Connect(function(Object)
                if Object~=Runtime.MM2CurrentMap and not MM2MapCandidate(Object) then return end
                Runtime.MM2CurrentMap=nil
                ResetMM2RoundCache(false)
            end))

            local function DroppedKnife()
                local Map=CurrentMap()
                if not Map then return nil end
                local Best,BestDistance=nil,math.huge
                local LocalPos=MM2PlayerSurfacePosition(Player)
                local Seen={}
                for _,Object in ipairs(Runtime.ProfileObjects()) do
                    local Name=string.lower(tostring(Object.Name or ""))
                    local LooksDropped=Name=="knifedrop" or Name=="droppedknife" or Name=="throwingknife"
                        or string.find(Name,"knife drop",1,true)~=nil
                    local Model=Object:FindFirstAncestorOfClass("Model")
                    if LooksDropped and not (Model and IsPlayerCharacter(Model)) and not Seen[Object]
                        and GetRoot(Object) and MM2ObjectInActiveMap(Object,45) then
                        Seen[Object]=true
                        local R=GetRoot(Object)
                        local D=LocalPos and (R.Position-LocalPos).Magnitude or 0
                        if D<BestDistance then Best,BestDistance=Object,D end
                    end
                end
                return Best
            end
            local function BagText()
                local PG=Player:FindFirstChildOfClass("PlayerGui")
                local Main=PG and PG:FindFirstChild("MainGUI")
                if not Main then return "?" end
                local Candidates={
                    {"Game","CoinBags","Container","Candy","CurrencyFrame","Icon","Coins"},
                    {"Game","CoinBags","Container","CurrencyFrame","Icon","Coins"}
                }
                for _,Path in ipairs(Candidates) do
                    local O=Main
                    for _,Name in ipairs(Path) do O=O and O:FindFirstChild(Name) end
                    if O and O:IsA("TextLabel") then return O.Text end
                end
                for _,O in ipairs(Main:GetDescendants()) do
                    if O:IsA("TextLabel") and string.find(string.lower(O.Name),"coin",1,true) and string.match(O.Text,"%d+") then
                        return O.Text
                    end
                end
                return "?"
            end
            local function MapName()
                local Map=CurrentMap()
                return Map and Map.Name or "Lobby / Loading"
            end
            local function BagNumbers()
                local Text=BagText()
                local A,B=string.match(Text,"(%d+)%s*/%s*(%d+)")
                return tonumber(A),tonumber(B),Text
            end
            local function BagFull()
                local T=BagText()
                local A,B=string.match(T,"(%d+)%s*/%s*(%d+)")
                if A and B then return tonumber(A)>=tonumber(B) end
                local N=tonumber(string.match(T,"(%d+)"))
                return N and N>=40 or false
            end

            local MM2ESPPlus=(function()
                local API={Records={},Boxes={},Auras={},ClosestThreat=math.huge,Counts={Murderer=0,Sheriff=0,Innocent=0}}
                local Gui,Danger,Radar,TopHUD,Vignette,VignetteStroke
                local function EnsureGui()
                    local PG=Player:FindFirstChildOfClass("PlayerGui")
                    if not PG then return nil end
                    if Gui and Gui.Parent==PG then return Gui end
                    local Old=PG:FindFirstChild("BananiMM2ESPPlus")
                    if Old then Old:Destroy() end
                    Gui=Instance.new("ScreenGui")
                    Gui.Name="BananiMM2ESPPlus"
                    Gui.IgnoreGuiInset=true
                    Gui.ResetOnSpawn=false
                    Gui.DisplayOrder=90
                    Gui.Parent=PG
                    Danger=Instance.new("TextLabel")
                    Danger.Name="DangerWarning"
                    Danger.AnchorPoint=Vector2.new(0.5,0)
                    Danger.Position=UDim2.new(0.5,0,0,84)
                    Danger.Size=UDim2.fromOffset(390,42)
