                local function NewRecord(Key)
                    local Parent=EnsureGui()
                    if not Parent then return nil end
                    local Holder=Instance.new("Frame")
                    Holder.Name="Target_"..tostring(Key)
                    Holder.Size=UDim2.fromScale(1,1)
                    Holder.BackgroundTransparency=1
                    Holder.Parent=Parent
                    local Line=Instance.new("Frame")
                    Line.Name="Tracer"
                    Line.AnchorPoint=Vector2.new(0.5,0.5)
                    Line.BorderSizePixel=0
                    Line.Visible=false
                    Line.Parent=Holder
                    local Arrow=Instance.new("TextLabel")
                    Arrow.Name="Arrow"
                    Arrow.AnchorPoint=Vector2.new(0.5,0.5)
                    Arrow.Size=UDim2.fromOffset(34,34)
                    Arrow.BackgroundColor3=Color3.fromRGB(8,8,12)
                    Arrow.BackgroundTransparency=0.18
                    Arrow.BorderSizePixel=0
                    Arrow.Font=Enum.Font.GothamBold
                    Arrow.Text="▲"
                    Arrow.TextSize=23
                    Arrow.TextStrokeColor3=Color3.new(0,0,0)
                    Arrow.TextStrokeTransparency=0
                    Arrow.Visible=false
                    Arrow.Parent=Holder
                    local Corner=Instance.new("UICorner")
                    Corner.CornerRadius=UDim.new(1,0)
                    Corner.Parent=Arrow
                    local Stroke=Instance.new("UIStroke")
                    Stroke.Name="ArrowStroke"
                    Stroke.Thickness=2
                    Stroke.Parent=Arrow
                    local RadarDot=Instance.new("TextLabel")
                    RadarDot.Name="RadarDot"
                    RadarDot.AnchorPoint=Vector2.new(0.5,0.5)
                    RadarDot.Size=UDim2.fromOffset(12,12)
                    RadarDot.BackgroundColor3=Color3.fromRGB(255,255,255)
                    RadarDot.BackgroundTransparency=0
                    RadarDot.BorderSizePixel=0
                    RadarDot.Font=Enum.Font.GothamBold
                    RadarDot.Text=""
                    RadarDot.TextSize=8
                    RadarDot.TextColor3=Color3.new(0,0,0)
                    RadarDot.TextStrokeTransparency=1
                    RadarDot.Visible=false
                    RadarDot.ZIndex=5
                    RadarDot.Parent=Radar
                    local DotCorner=Instance.new("UICorner")
                    DotCorner.CornerRadius=UDim.new(1,0)
                    DotCorner.Parent=RadarDot
                    local DotStroke=Instance.new("UIStroke")
                    DotStroke.Thickness=1
                    DotStroke.Color=Color3.new(1,1,1)
                    DotStroke.Parent=RadarDot
                    local Record={Holder=Holder,Line=Line,Arrow=Arrow,RadarDot=RadarDot}
                    API.Records[Key]=Record
                    return Record
                end
                local function DestroyRecord(Record)
                    if not Record then return end
                    pcall(function() Record.Holder:Destroy() end)
                    pcall(function() Record.RadarDot:Destroy() end)
                end
                local function SetLine(Line,A,B,Color)
                    local Delta=B-A
                    local Length=Delta.Magnitude
                    Line.Position=UDim2.fromOffset((A.X+B.X)/2,(A.Y+B.Y)/2)
                    Line.Size=UDim2.fromOffset(Length,math.clamp(tonumber(State.MM2ESPTracerThickness) or 2,1,5))
                    Line.Rotation=math.deg(math.atan2(Delta.Y,Delta.X))
                    Line.BackgroundColor3=Color
                end
                local function UpdateScreen(Key,WorldPosition,Color,Tracer,Offscreen,Marker)
                    local Cam=workspace.CurrentCamera
                    if not Cam or not WorldPosition then return end
                    local Record=API.Records[Key]
                    if not Record or not Record.Holder or not Record.Holder.Parent or not Record.RadarDot or not Record.RadarDot.Parent then
                        DestroyRecord(Record)
                        API.Records[Key]=nil
                        Record=NewRecord(Key)
                    end
                    if not Record then return end
                    local Point,OnScreen=Cam:WorldToViewportPoint(WorldPosition)
                    local View=Cam.ViewportSize
                    local Screen=Vector2.new(Point.X,Point.Y)
                    local Center=View/2
                    local InFront=Point.Z>0
                    Record.Line.Visible=Tracer and OnScreen and InFront
                    if Record.Line.Visible then
                        SetLine(Record.Line,Vector2.new(View.X/2,View.Y-18),Screen,Color)
                    end
                    Record.Arrow.Visible=Offscreen and (not OnScreen or not InFront)
                    if Record.Arrow.Visible then
                        local Direction=Screen-Center
                        if not InFront then Direction=-Direction end
                        if Direction.Magnitude<1 then Direction=Vector2.new(0,-1) end
                        Direction=Direction.Unit
                        local Radius=math.min(View.X,View.Y)*0.39
                        local Position=Center+Direction*Radius
                        Position=Vector2.new(math.clamp(Position.X,32,View.X-32),math.clamp(Position.Y,45,View.Y-32))
                        Record.Arrow.Position=UDim2.fromOffset(Position.X,Position.Y)
                        Record.Arrow.Rotation=math.deg(math.atan2(Direction.Y,Direction.X))+90
                        Record.Arrow.TextColor3=Color
                        local Stroke=Record.Arrow:FindFirstChild("ArrowStroke")
                        if Stroke then Stroke.Color=Color end
                    end
                    if Record.RadarDot then
                        local MyRoot=Root()
                        local Range=math.max(tonumber(State.MM2ESPRadarRange) or 140,25)
                        local Relative=MyRoot and MyRoot.CFrame:PointToObjectSpace(WorldPosition) or Vector3.zero
                        local Flat=Vector2.new(Relative.X,Relative.Z)
                        local Scale=math.min(Flat.Magnitude/Range,1)
                        local Direction=Flat.Magnitude>0.01 and Flat.Unit or Vector2.zero
                        local RadarPosition=Vector2.new(77,77)+Direction*(Scale*64)
                        Record.RadarDot.Position=UDim2.fromOffset(RadarPosition.X,RadarPosition.Y)
                        Record.RadarDot.BackgroundColor3=Color
                        Record.RadarDot.Text=tostring(Marker or "")
                        Record.RadarDot.Size=UDim2.fromOffset(Marker=="M" and 15 or 12,Marker=="M" and 15 or 12)
                        Record.RadarDot.Visible=State.MM2ESPRadar==true
                    end
                end
                function API.BeginFrame()
                    API.Seen={}
                    API.ClosestThreat=math.huge
                    API.Counts={Murderer=0,Sheriff=0,Innocent=0}
                end
                function API.TrackRole(Role,Distance)
                    if Role=="Murderer" then
                        API.Counts.Murderer+=1
                        API.ClosestThreat=math.min(API.ClosestThreat,tonumber(Distance) or math.huge)
                    elseif Role=="Sheriff / Hero" then API.Counts.Sheriff+=1
                    else API.Counts.Innocent+=1 end
                end
                function API.UpdatePlayer(P,Role,Color,Part,Distance)
                    local Key="P_"..tostring(P.UserId)
                    API.Seen[Key]=true
                    local Marker=Role=="Murderer" and "M" or (Role=="Sheriff / Hero" and "S" or "I")
                    UpdateScreen(Key,Part.Position,Color,State.MM2ESPTracers,State.MM2ESPOffscreen,Marker)
                    if State.MM2ESPBoxes then
                        local Box=API.Boxes[P]
                        if not Box or not Box.Parent then
                            Box=Instance.new("BoxHandleAdornment")
                            Box.Name="BananiMM2RoleBox"
                            Box.Adornee=Part
                            Box.AlwaysOnTop=true
                            Box.ZIndex=8
                            Box.Size=Vector3.new(math.max(Part.Size.X,4.2),math.max(Part.Size.Y,6.1),math.max(Part.Size.Z,2.7))
                            Box.Parent=Part
                            API.Boxes[P]=Box
                        end
                        Box.Adornee=Part
                        Box.Color3=Color
                        Box.Transparency=0.58
                        Box.Visible=true
                    end
                    if Role=="Murderer" and State.MM2ESPThreatAura then
                        local Aura=API.Auras[P]
                        if not Aura or not Aura.Parent then
                            Aura=Instance.new("SphereHandleAdornment")
                            Aura.Name="BananiMM2ThreatAura"
                            Aura.Adornee=Part
                            Aura.AlwaysOnTop=true
                            Aura.ZIndex=7
                            Aura.Parent=Part
                            API.Auras[P]=Aura
                        end
                        local Pulse=(math.sin(os.clock()*4.8)+1)/2
                        Aura.Adornee=Part
                        Aura.Color3=Color
                        Aura.Radius=4.2+Pulse*0.65
                        Aura.Transparency=0.78+Pulse*0.10
                        Aura.Visible=true
                    elseif API.Auras[P] then
                        pcall(function() API.Auras[P]:Destroy() end)
                        API.Auras[P]=nil
                    end
                end
                function API.EndFrame()
                    for Key,Record in pairs(API.Records) do
                        if string.sub(tostring(Key),1,2)=="P_" and not API.Seen[Key] then
                            DestroyRecord(Record)
                            API.Records[Key]=nil
                        end
                    end
                    for P,Box in pairs(API.Boxes) do
                        local Key=P and ("P_"..tostring(P.UserId)) or ""
                        if not API.Seen[Key] or not State.MM2ESPBoxes then
                            pcall(function() Box:Destroy() end)
                            API.Boxes[P]=nil
                        end
                    end
                    for P,Aura in pairs(API.Auras) do
                        local Key=P and ("P_"..tostring(P.UserId)) or ""
                        if not API.Seen[Key] or not State.MM2ESPThreatAura then
                            pcall(function() Aura:Destroy() end)
                            API.Auras[P]=nil
                        end
                    end
                    EnsureGui()
                    if Radar then
                        Radar.Visible=State.MM2ESPRadar==true
                        local Title=Radar:FindFirstChild("Title")
                        if Title then Title.Text="ROLE RADAR • "..math.floor(tonumber(State.MM2ESPRadarRange) or 140).." STUDS" end
                    end
                    if TopHUD then
                        TopHUD.Visible=State.MM2ESPTopHUD==true
                        TopHUD.Text="🔴 MURDERER  "..API.Counts.Murderer
                            .."     🔵 SHERIFF  "..API.Counts.Sheriff
                            .."     🟢 OTHER  "..API.Counts.Innocent
                    end
                    if Danger then
                        local Limit=tonumber(State.MM2ESPDangerDistance) or 65
                        Danger.Visible=State.MM2ESPDangerWarning and API.ClosestThreat<=Limit
                        if Danger.Visible then
                            local Level=API.ClosestThreat<=20 and "CRITICAL" or (API.ClosestThreat<=40 and "DANGER" or "WARNING")
                            Danger.Text="⚠  "..Level.." • MURDERER "..math.floor(API.ClosestThreat).." STUDS AWAY"
                            local Pulse=(math.sin(os.clock()*7)+1)/2
                            Danger.BackgroundTransparency=0.08+Pulse*0.12
                        end
                    end
                    if Vignette then
                        local Limit=tonumber(State.MM2ESPDangerDistance) or 65
                        Vignette.Visible=State.MM2ESPThreatVignette and API.ClosestThreat<=Limit
                        if Vignette.Visible and VignetteStroke then
                            VignetteStroke.Transparency=0.12+((math.sin(os.clock()*7)+1)/2)*0.32
                        end
                    end
                end
                function API.UpdateGun(Gun,Distance)
                    if not Gun or not State.MM2ESPGunArrow then return API.ClearGun() end
                    local Part=GetRoot(Gun)
                    if not Part then return API.ClearGun() end
                    UpdateScreen("Gun",Part.Position,Color3.fromRGB(255,220,45),false,true,"G")
                end
                function API.ClearGun()
                    local Record=API.Records.Gun
                    if Record then DestroyRecord(Record); API.Records.Gun=nil end
                end
                function API.ClearRoles()
                    for Key,Record in pairs(API.Records) do
                        if string.sub(tostring(Key),1,2)=="P_" then
                            DestroyRecord(Record)
                            API.Records[Key]=nil
                        end
                    end
                    for P,Box in pairs(API.Boxes) do pcall(function() Box:Destroy() end); API.Boxes[P]=nil end
                    for P,Aura in pairs(API.Auras) do pcall(function() Aura:Destroy() end); API.Auras[P]=nil end
                    if Danger then Danger.Visible=false end
                    if TopHUD then TopHUD.Visible=false end
                    if Radar then Radar.Visible=false end
                    if Vignette then Vignette.Visible=false end
                end
                function API.ClearAll()
                    State.MM2RoleESPEnabled=false
                    API.ClearRoles()
                    API.ClearGun()
                    if Gui then pcall(function() Gui:Destroy() end) end
                    Gui,Danger=nil,nil
                end
                return API
            end)()
            Runtime.MM2ESPPlusCleanup=MM2ESPPlus.ClearAll
            local function ClearRoleTags()
                for P,Gui in pairs(State.MM2Tags or {}) do
                    pcall(function() Gui:Destroy() end)
                    State.MM2Tags[P]=nil
                end
                for Key,Glow in pairs(State.MM2ObjectHighlights or {}) do
                    if string.sub(tostring(Key),1,9)=="RoleGlow_" then
                        pcall(function() Glow:Destroy() end)
                        State.MM2ObjectHighlights[Key]=nil
                    end
                end
                if State.MM2HPTweens then
                    for Fill,Tween in pairs(State.MM2HPTweens) do
                        if Tween then pcall(function() Tween:Cancel() end) end
                        State.MM2HPTweens[Fill]=nil
                    end
                end
                MM2ESPPlus.ClearRoles()
            end
            local function MakeObjectTag(Key,Object,Text,Color)
                if not Object then return end
                local Part=GetRoot(Object)
                if not Part then return end
                local Old=State.MM2ObjectHighlights[Key]
                if Old and Old.Parent then
                    Old.Adornee=Part
                    Old.Parent=Part
                    local T=Old:FindFirstChild("Label")
                    if T then T.Text=Text; T.TextColor3=Color end
                    return
                end
                local Gui=Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
                Gui.Name="BananiMM2Object"
                Gui.AlwaysOnTop=true
                Gui.Size=UDim2.fromOffset(130,24)
                Gui.StudsOffset=Vector3.new(0,2.4,0)
                Gui.Adornee=Part
                Gui.Parent=Part
                local T=Instance.new("TextLabel")
                T.Name="Label"
                T.Size=UDim2.fromScale(1,1)
                T.BackgroundTransparency=1
                T.Font=Enum.Font.Code
                T.TextSize=12
                T.TextStrokeTransparency=0.45
                T.Text=Text
                T.TextColor3=Color
                T.Parent=Gui
                State.MM2ObjectHighlights[Key]=Gui
            end
            local MM2ESPTweenService=game:GetService("TweenService")
            local function UpdateRoleTags()

                local ActiveMap=CurrentMap()
                if not ActiveMap or (Runtime.MM2PlayerInLobby and Runtime.MM2PlayerInLobby(Player)) then
                    if not Runtime.MM2ESPWaitingForRound then ClearRoleTags(); Runtime.MM2ESPWaitingForRound=true end
                    return
                end
                Runtime.MM2ESPWaitingForRound=false
                local Seen,SeenGlow={},{}
                local Me=Root()
                local UseExtraRoleUI=State.MM2ESPTracers or State.MM2ESPOffscreen or State.MM2ESPRadar
                    or State.MM2ESPBoxes or State.MM2ESPThreatAura or State.MM2ESPTopHUD
                    or State.MM2ESPDangerWarning or State.MM2ESPThreatVignette
                if UseExtraRoleUI then MM2ESPPlus.BeginFrame() end
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    local C=P.Character
                    if P~=Player and C and IsAlive(P) then
                        local Role=RoleOf(P)
                        local Show=(Role=="Murderer" and State.MM2ESPMurderer)
                            or (Role=="Sheriff / Hero" and State.MM2ESPSheriff)
                            or (Role=="Innocent / Unknown" and State.MM2ESPInnocent)
                        local Head=C:FindFirstChild("Head") or C:FindFirstChild("HumanoidRootPart")
                        local PR=C:FindFirstChild("HumanoidRootPart")
                        local Distance=Me and PR and (Me.Position-PR.Position).Magnitude or math.huge
                        if UseExtraRoleUI then MM2ESPPlus.TrackRole(Role,Distance) end
                        if Show and Head and Distance<=(tonumber(State.MM2ESPMaxDistance) or 1500) then
                            Seen[P]=true
                            if UseExtraRoleUI then
                                MM2ESPPlus.UpdatePlayer(P,Role,RoleColor(Role),PR or Head,Distance)
                            end
                            local Gui=State.MM2Tags[P]
                            if not State.MM2ESPFloatingText then
                                if Gui then pcall(function() Gui:Destroy() end); State.MM2Tags[P]=nil end
                            else
                            if not Gui or not Gui.Parent then
                                Gui=Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
                                Gui.Name="BananiMM2Role"
                                Gui.AlwaysOnTop=true
                                Gui.LightInfluence=0
                                Gui.Size=UDim2.fromOffset(270,82)
                                Gui.StudsOffset=Vector3.new(0,3.55,0)

                                local Card=Instance.new("Frame")
