                                RoleLabel.BackgroundTransparency=1
                                RoleLabel.Position=UDim2.fromOffset(13,5)
                                RoleLabel.Size=UDim2.new(1,-24,0,19)
                                RoleLabel.Font=Enum.Font.GothamBold
                                RoleLabel.TextSize=13
                                RoleLabel.TextXAlignment=Enum.TextXAlignment.Left
                                RoleLabel.TextStrokeTransparency=0.55
                                RoleLabel.Parent=Card

                                local NameLabel=Instance.new("TextLabel")
                                NameLabel.Name="PlayerName"
                                NameLabel.BackgroundTransparency=1
                                NameLabel.Position=UDim2.fromOffset(13,24)
                                NameLabel.Size=UDim2.new(1,-24,0,19)
                                NameLabel.Font=Enum.Font.GothamMedium
                                NameLabel.TextSize=12
                                NameLabel.TextColor3=Color3.fromRGB(246,246,249)
                                NameLabel.TextXAlignment=Enum.TextXAlignment.Left
                                NameLabel.TextStrokeTransparency=0.65
                                NameLabel.Parent=Card

                                local Meta=Instance.new("TextLabel")
                                Meta.Name="Meta"
                                Meta.BackgroundTransparency=1
                                Meta.Position=UDim2.fromOffset(13,43)
                                Meta.Size=UDim2.new(1,-24,0,16)
                                Meta.Font=Enum.Font.Gotham
                                Meta.TextSize=10
                                Meta.TextColor3=Color3.fromRGB(190,190,200)
