                                HPFillCorner.Parent=HPFill
                                State.MM2Tags[P]=Gui
                            end
                            Gui.Adornee=Head
                            Gui.Parent=Head
                            local LabelScale=1
                            if State.MM2ESPDistanceScale then
                                local MaxDistance=math.max(tonumber(State.MM2ESPMaxDistance) or 1500,100)
                                LabelScale=math.clamp(1.12-(Distance/MaxDistance)*0.38,0.78,1.12)
                            end
                            Gui.Size=UDim2.fromOffset(math.floor(270*LabelScale),math.floor(82*LabelScale))
                            Gui.StudsOffset=Vector3.new(0,3.45+LabelScale*0.25,0)
                            local RoleTitle=Role=="Murderer" and "🔪 MURDERER"
                                or (Role=="Sheriff / Hero" and "🔫 SHERIFF / HERO" or "🟢 INNOCENT / UNKNOWN")
                            local H=C:FindFirstChildOfClass("Humanoid")
                            local Card=Gui:FindFirstChild("Card")
                            if Card then
                                local Color=RoleColor(Role)
                                local RoleLabel=Card:FindFirstChild("Role")
                                local NameLabel=Card:FindFirstChild("PlayerName")
                                local Meta=Card:FindFirstChild("Meta")
                                local Stroke=Card:FindFirstChild("RoleStroke")
                                local Accent=Card:FindFirstChild("Accent")
                                local HPBack=Card:FindFirstChild("HPBack")
                                local HPFill=HPBack and HPBack:FindFirstChild("HPFill")
                                if RoleLabel then
                                    RoleLabel.Text=RoleTitle
                                    RoleLabel.TextColor3=Color
                                    RoleLabel.TextSize=math.clamp(math.floor(13*LabelScale+0.5),10,18)
                                end
                                if NameLabel then
                                    local Display=State.MM2ESPDisplayName and tostring(P.DisplayName) or "Player"
                                    local User=State.MM2ESPUsername and ("  @"..tostring(P.Name)) or ""
                                    NameLabel.Text=Display..User
                                    NameLabel.TextSize=math.clamp(math.floor(12*LabelScale+0.5),10,17)
                                end
                                local Details={}
                                if State.MM2ESPDistance and Me and PR then table.insert(Details,math.floor(Distance).." studs") end
                                if State.MM2ESPHealth and H then table.insert(Details,math.ceil(H.Health).."/"..math.ceil(H.MaxHealth).." HP") end
                                if State.MM2ESPWeapon then
                                    local HasKnife,Knife=HasTool(P,"knife")
                                    local HasGun,Gun=HasTool(P,"gun")
                                    if HasKnife then table.insert(Details,"🔪 "..tostring(Knife and Knife.Name or "Knife"))
                                    elseif HasGun then table.insert(Details,"🔫 "..tostring(Gun and Gun.Name or "Gun"))
                                    else table.insert(Details,"✋ Unarmed") end
                                end
                                if Meta then
                                    Meta.Text=table.concat(Details,"  •  ")
                                    Meta.TextSize=math.clamp(math.floor(10*LabelScale+0.5),9,14)
                                end
                                local MaxDistance=math.max(tonumber(State.MM2ESPMaxDistance) or 1500,100)
                                local Fade=math.clamp((Distance/MaxDistance-0.45)/0.55,0,1)
                                Card.BackgroundTransparency=0.16+Fade*0.34
                                if RoleLabel then RoleLabel.TextTransparency=Fade*0.36 end
                                if NameLabel then NameLabel.TextTransparency=Fade*0.42 end
                                if Meta then Meta.TextTransparency=Fade*0.50 end
                                if Stroke then Stroke.Color=Color; Stroke.Transparency=0.08+Fade*0.42 end
                                if Accent then Accent.BackgroundColor3=Color; Accent.BackgroundTransparency=Fade*0.38 end
                                if HPBack then HPBack.Visible=State.MM2ESPHealth==true; HPBack.BackgroundTransparency=Fade*0.28 end
                                if HPFill and H and H.MaxHealth>0 then
                                    local Ratio=math.clamp(H.Health/H.MaxHealth,0,1)
                                    local Previous=tonumber(HPFill:GetAttribute("BananiRatio"))
                                    if Previous==nil or math.abs(Previous-Ratio)>0.006 then
                                        HPFill:SetAttribute("BananiRatio",Ratio)
                                        State.MM2HPTweens=State.MM2HPTweens or setmetatable({}, {__mode="k"})
                                        local OldTween=State.MM2HPTweens[HPFill]
                                        if OldTween then pcall(function() OldTween:Cancel() end) end
                                        local NewTween=Runtime.TrackTween(MM2ESPTweenService:Create(HPFill,TweenInfo.new(0.16,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Size=UDim2.new(Ratio,0,1,0)}),nil,"MM2ESPTweens")
                                        State.MM2HPTweens[HPFill]=NewTween
                                        NewTween:Play()
                                    end
                                    HPFill.BackgroundColor3=(Ratio>0.60 and Color3.fromRGB(80,230,125)) or (Ratio>0.30 and Color3.fromRGB(240,190,65)) or Color3.fromRGB(255,75,90)
                                    HPFill.BackgroundTransparency=Fade*0.18
                                end
                            end
                            end
                            if State.MM2ESPChams then
                                local Key="RoleGlow_"..tostring(P.UserId)
                                SeenGlow[Key]=true
                                local Glow=State.MM2ObjectHighlights[Key]
                                if not Glow or not Glow.Parent then
                                    Glow=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
                                    Glow.Name="BananiMM2RoleGlow"
                                    Glow.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                                    State.MM2ObjectHighlights[Key]=Glow
                                end
                                Glow.Parent=C
                                Glow.Adornee=C
                                local Pulse=State.MM2ESPPulse and (math.sin(os.clock()*3.8)+1)*0.055 or 0
                                local BaseColor=RoleColor(Role)
                                Glow.FillColor=BaseColor:Lerp(Color3.new(1,1,1),Pulse)
                                Glow.OutlineColor=BaseColor:Lerp(Color3.new(1,1,1),0.22)
                                local MaxDistance=math.max(tonumber(State.MM2ESPMaxDistance) or 1500,100)
                                local DistanceFade=math.clamp((Distance/MaxDistance-0.45)/0.55,0,1)
                                local BaseTransparency=1-math.clamp((tonumber(State.MM2ESPGlowOpacity) or 62)/100,0.15,0.9)
                                Glow.FillTransparency=math.clamp(BaseTransparency+DistanceFade*0.22,0,0.95)
                                Glow.OutlineTransparency=DistanceFade*0.38
                            end
                        end
                    end
                end
                for P,Gui in pairs(State.MM2Tags) do
                    if not Seen[P] then
                        pcall(function() Gui:Destroy() end)
                        State.MM2Tags[P]=nil
                    end
                end
                for Key,Glow in pairs(State.MM2ObjectHighlights) do
                    if type(Key)=="string" and string.sub(Key,1,9)=="RoleGlow_" and not SeenGlow[Key] then
                        pcall(function() Glow:Destroy() end)
                        State.MM2ObjectHighlights[Key]=nil
                    end
                end
                if UseExtraRoleUI then MM2ESPPlus.EndFrame() end
            end
            local function MM2RoleAllowedForSharedESP(P)
                if not State.MM2RoleESPEnabled or not P or P==Player or not IsAlive(P) then return false end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(P) then return false end
                local Role=RoleOf(P)
                return (Role=="Murderer" and State.MM2ESPMurderer)
                    or (Role=="Sheriff / Hero" and State.MM2ESPSheriff)
                    or (Role=="Innocent / Unknown" and State.MM2ESPInnocent)
