                    local HasKnife,Knife=HasTool(P,"knife")
                    local HasGun,Gun=HasTool(P,"gun")
                    if HasKnife then table.insert(Details,"Knife: "..tostring(Knife and Knife.Name or "Knife"))
                    elseif HasGun then table.insert(Details,"Gun: "..tostring(Gun and Gun.Name or "Gun"))
