            local function UpdateGunESP()
                local Gun=GunDrop()
                if Gun then
                    local GunRoot=GetRoot(Gun)
                    local Me=Root()
                    local Distance=GunRoot and Me and (Me.Position-GunRoot.Position).Magnitude or 0
                    MakeObjectTag("GunDrop",Gun,"DROPPED GUN • "..math.floor(Distance).." studs",Color3.fromRGB(255,225,65))
                    MM2ESPPlus.UpdateGun(Gun,Distance)
                    local Glow=State.MM2ObjectHighlights.GunGlow
                    local GunAdornee=Gun:IsA("Model") and Gun or GunRoot
                    if not GunAdornee then return end
                    if not Glow or not Glow.Parent then
                        Glow=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
                        Glow.Name="BananiMM2GunGlow"
                        Glow.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                        Glow.FillTransparency=0.62
                        Glow.OutlineTransparency=0
                        Glow.Parent=GunRoot or Gun
                        State.MM2ObjectHighlights.GunGlow=Glow
                    end
                    Glow.Parent=GunRoot or Gun
                    Glow.Adornee=GunAdornee
                    Glow.FillColor=Color3.fromRGB(255,205,55)
                    Glow.OutlineColor=Color3.fromRGB(255,245,180)
                else
                    MM2ESPPlus.ClearGun()
                    local Old=State.MM2ObjectHighlights.GunDrop
                    if Old then pcall(function() Old:Destroy() end); State.MM2ObjectHighlights.GunDrop=nil end
                    local Glow=State.MM2ObjectHighlights.GunGlow
                    if Glow then pcall(function() Glow:Destroy() end); State.MM2ObjectHighlights.GunGlow=nil end
                end
            end
