                    local Distance=Part and Me and (Me.Position-Part.Position).Magnitude or 0
                    MakeObjectTag("KnifeDrop",Knife,"DROPPED KNIFE • "..math.floor(Distance).." studs",Color3.fromRGB(255,75,105))
                    local Glow=State.MM2ObjectHighlights.KnifeGlow
