            local function ClearCoinESP()
                Runtime.MM2CoinESPRecords=Runtime.MM2CoinESPRecords or setmetatable({}, {__mode="k"})
                for Coin,Record in pairs(Runtime.MM2CoinESPRecords) do
                    if Record then
                        if Record.Gui then pcall(function() Record.Gui:Destroy() end) end
                        if Record.Glow then pcall(function() Record.Glow:Destroy() end) end
                    end
                    Runtime.MM2CoinESPRecords[Coin]=nil
                end
            end
            Runtime.MM2CoinESPCleanup=ClearCoinESP
            local function UpdateCoinESP()
                local Me=Root()
                if not Me then ClearCoinESP(); return end
                Runtime.MM2CoinESPRecords=Runtime.MM2CoinESPRecords or setmetatable({}, {__mode="k"})
                local Records=Runtime.MM2CoinESPRecords
                local Seen={}
                local Candidates={}
                local MaxRange=math.clamp(tonumber(State.MM2CoinESPRange) or 350,40,1500)
                for _,Coin in ipairs(CoinCandidates()) do
                    local R=CoinRoot(Coin)
                    local Distance=R and (Me.Position-R.Position).Magnitude or math.huge
                    if R and CoinAvailable(Coin) and Distance<=MaxRange then
                        table.insert(Candidates,{Coin=Coin,Part=R,Distance=Distance})
                    end
                end
                table.sort(Candidates,function(A,B) return A.Distance<B.Distance end)
                for I=1,math.min(48,#Candidates) do
                    local Item=Candidates[I]
                    local Coin,Part=Item.Coin,Item.Part
                    Seen[Coin]=true
                    local Record=Records[Coin]
                    if not Record then
                        Record={}
                        local Gui=Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
                        Gui.Name="BananiMM2CoinESP"
                        Gui.AlwaysOnTop=true
                        Gui.LightInfluence=0
                        Gui.Size=UDim2.fromOffset(116,26)
                        Gui.StudsOffset=Vector3.new(0,1.9,0)
                        local Label=Instance.new("TextLabel")
                        Label.Name="Label"
                        Label.Size=UDim2.fromScale(1,1)
                        Label.BackgroundTransparency=1
                        Label.BorderSizePixel=0
                        Label.Font=Enum.Font.GothamBold
                        Label.TextSize=12
                        Label.TextStrokeTransparency=0.25
                        Label.TextColor3=Color3.fromRGB(255,220,65)
                        Label.Parent=Gui
                        Record.Gui=Gui
                        local Glow=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
                        Glow.Name="BananiMM2CoinGlow"
                        Glow.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                        Glow.FillColor=Color3.fromRGB(255,205,35)
                        Glow.OutlineColor=Color3.fromRGB(255,245,165)
                        Glow.FillTransparency=0.72
                        Glow.OutlineTransparency=0.05
                        Record.Glow=Glow
                        Records[Coin]=Record
                    end
                    if Record.Gui then
                        Record.Gui.Adornee=Part
                        if Record.Gui.Parent~=Part then Record.Gui.Parent=Part end
                        local Label=Record.Gui:FindFirstChild("Label")
                        if Label then Label.Text="COIN • "..math.floor(Item.Distance).." studs" end
                    end
                    if Record.Glow then
                        Record.Glow.Adornee=Coin:IsA("Model") and Coin or Part
                        local Parent=Coin:IsA("Model") and Coin or Part
                        if Record.Glow.Parent~=Parent then Record.Glow.Parent=Parent end
                    end
                end
                for Coin,Record in pairs(Records) do
                    if not Seen[Coin] or not Coin or not Coin.Parent or not CoinAvailable(Coin) then
                        if Record then
                            if Record.Gui then pcall(function() Record.Gui:Destroy() end) end
                            if Record.Glow then pcall(function() Record.Glow:Destroy() end) end
                        end
                        Records[Coin]=nil
                    end
                end
            end
            local function MM2TargetPart(P)
                local C=P and P.Character
                if not C then return nil end
                local Preferred=tostring(State.MM2TargetPart or "Smart")
                if Preferred=="Smart" then
                    return C:FindFirstChild("UpperTorso")
                        or C:FindFirstChild("HumanoidRootPart")
                        or C:FindFirstChild("Torso")
                        or C:FindFirstChild("Head")
                end
                return C:FindFirstChild(Preferred)
                    or C:FindFirstChild("HumanoidRootPart")
                    or C:FindFirstChild("UpperTorso")
                    or C:FindFirstChild("Head")
            end
            local function MM2AimReferencePosition(Cam)
                Cam=Cam or workspace.CurrentCamera or Camera
                if not Cam then return Vector2.zero end
                if tostring(State.MM2AimReference or "Screen Center")=="Mouse Cursor" then
                    local Mouse=UserInputService:GetMouseLocation()
                    local Inset=Vector2.zero
                    pcall(function()
                        local TopLeft=GuiService:GetGuiInset()
                        if typeof(TopLeft)=="Vector2" then Inset=TopLeft end
                    end)
                    return Mouse-Inset
                end
                local View=Cam.ViewportSize
                return Vector2.new(View.X*0.5,View.Y*0.5)
            end
            local function MM2PingSeconds()
                local Ping=0.08
                pcall(function()
                    local Item=Stats.Network.ServerStatsItem["Data Ping"]
                    local Raw=Item and Item:GetValue()
                    Ping=math.clamp((tonumber(Raw) or 80)/1000,0.02,0.25)
                end)
                local Previous=tonumber(Runtime.MM2SmoothedPing) or Ping
                Runtime.MM2SmoothedPing=Previous+(Ping-Previous)*0.18
                return Runtime.MM2SmoothedPing
            end
            local function MM2StableMotion(Part)
                Runtime.MM2AimMotion=Runtime.MM2AimMotion or setmetatable({}, {__mode="k"})
                local Now=os.clock()
                local Entry=Runtime.MM2AimMotion[Part]
                local Assembly=Part.AssemblyLinearVelocity or Vector3.zero
                if Assembly.Magnitude>140 then Assembly=Assembly.Unit*140 end
                if not Entry then
                    Entry={Position=Part.Position,At=Now,Velocity=Assembly,Acceleration=Vector3.zero}
                    Runtime.MM2AimMotion[Part]=Entry
                    return Assembly,Vector3.zero
                end
                local Dt=Now-(tonumber(Entry.At) or Now)
                local Measured=Assembly
                if Dt>=0.012 and Dt<=0.22 then
                    local Delta=Part.Position-(Entry.Position or Part.Position)
                    local Candidate=Delta/Dt

                    if Candidate.Magnitude<=160 then Measured=Candidate:Lerp(Assembly,0.35) end
                end
                local Previous=Entry.Velocity or Assembly
                local Smoothed=Previous:Lerp(Measured,0.34)
                if Smoothed.Magnitude>125 then Smoothed=Smoothed.Unit*125 end

                local Acceleration=Entry.Acceleration or Vector3.zero
                if Dt>=0.012 and Dt<=0.22 then
                    local RawAccel=(Smoothed-Previous)/Dt
                    if RawAccel.Magnitude>260 then RawAccel=RawAccel.Unit*260 end
                    Acceleration=Acceleration:Lerp(RawAccel,0.16)
                    if Acceleration.Magnitude>180 then Acceleration=Acceleration.Unit*180 end
                else
                    Acceleration=Acceleration*0.8
                end

                Entry.Position=Part.Position
                Entry.At=Now
                Entry.Velocity=Smoothed
                Entry.Acceleration=Acceleration
                return Smoothed,Acceleration
            end
            local function PredictedPosition(Part,Mode)
                if not Part then return nil end
                local Scale=math.clamp(tonumber(State.MM2PredictionScale) or 1.10,0,2.5)
                if Scale<=0 then return Part.Position end
                local Velocity,Acceleration=MM2StableMotion(Part)
                if Velocity.Magnitude<0.55 then return Part.Position end

                local Ping=MM2PingSeconds()
                local Lead=(Ping*0.52+0.018)*Scale
                if Mode=="knife" then
                    local Origin=Runtime.MM2SurfacePosition() or ((workspace.CurrentCamera or Camera) and (workspace.CurrentCamera or Camera).CFrame.Position)
                    local Distance=Origin and (Part.Position-Origin).Magnitude or 0
                    local Speed=math.clamp(tonumber(State.MM2KnifePredictionSpeed) or 240,120,420)
                    Lead=Lead+math.clamp(Distance/Speed,0,0.45)*Scale
                end
                Lead=math.clamp(Lead,0,Mode=="knife" and 0.62 or 0.28)

                local AccelScale=math.clamp(tonumber(State.MM2PredictionAccel) or 0.22,0,0.60)
                local Predicted=Part.Position+Velocity*Lead+Acceleration*(0.5*Lead*Lead*AccelScale)

                local Model=Part.Parent
                local H=Model and Model:FindFirstChildOfClass("Humanoid")
                if H and H.FloorMaterial~=Enum.Material.Air and math.abs(Velocity.Y)<10 then
                    Predicted=Vector3.new(Predicted.X,Part.Position.Y,Predicted.Z)
                end

                local Offset=Predicted-Part.Position
                local MaxOffset=Mode=="knife" and 80 or 24
                if Offset.Magnitude>MaxOffset then Predicted=Part.Position+Offset.Unit*MaxOffset end
                return Predicted
            end
            local function EquipNamed(Needle)
                local C=Character()
                if not C then return nil end
                local Choice=Needle=="gun" and State.MM2GunChoice or State.MM2KnifeChoice
                if Choice and string.sub(Choice,1,5)~="Auto " then
                    local BP=Player:FindFirstChildOfClass("Backpack")
                    local Selected=C:FindFirstChild(Choice) or (BP and BP:FindFirstChild(Choice))
                    if Selected and Selected:IsA("Tool") then
                        if State.MM2Invisible and Runtime.MM2InvisibleState then Runtime.MM2InvisibleState.ProxyWeaponKind=Needle end
                        if Selected.Parent~=C then
                            if State.MM2Invisible and Runtime.MM2EquipRealTool then
                                Runtime.MM2EquipRealTool(Selected)
                            else
                                local H=Humanoid()
                                if H then pcall(function() H:EquipTool(Selected) end) end
                            end
                        end
                        return Selected
                    end
                    return nil
                end
                local Found,Tool=HasTool(Player,Needle)
                if Found and Tool and Tool.Parent==C then return Tool end
                local BP=Player:FindFirstChildOfClass("Backpack")
                if BP then
                    for _,Obj in ipairs(BP:GetChildren()) do
                        if Obj:IsA("Tool") and string.find(string.lower(Obj.Name),string.lower(Needle),1,true) then
                            if State.MM2Invisible and Runtime.MM2InvisibleState then Runtime.MM2InvisibleState.ProxyWeaponKind=Needle end
                            if State.MM2Invisible and Runtime.MM2EquipRealTool then
                                Runtime.MM2EquipRealTool(Obj)
                            else
                                local H=Humanoid()
                                if H then pcall(function() H:EquipTool(Obj) end) end
                            end
                            return Obj
                        end
                    end
                end
                local _,Equipped=HasTool(Player,Needle)
                return Equipped
            end
            local function ShootPart(Part)
                if not Part then return false end
                local Gun=EquipNamed("gun")
                if not Gun then return false end
                local Target=PredictedPosition(Part,"gun") or Part.Position
                if State.MM2Invisible then
                    if not Runtime.MM2SurfaceToolProxy then return false end
                    local Fired=Runtime.MM2SurfaceToolProxy(Target,"primary")
                    if Fired then Runtime.MM2LastShot=os.clock() end
                    return Fired
                end
                local KnifeLocal=Gun:FindFirstChild("KnifeLocal",true)
                local CreateBeam=KnifeLocal and KnifeLocal:FindFirstChild("CreateBeam",true)
                local Remote=CreateBeam and (CreateBeam:FindFirstChild("RemoteFunction",true) or CreateBeam:FindFirstChildWhichIsA("RemoteFunction",true))
                if Remote and Remote:IsA("RemoteFunction") then
                    local Ok,Result=pcall(function() return Remote:InvokeServer(1,Target,"AH2") end)
                    if Ok and Result~=false then Runtime.MM2LastShot=os.clock(); return true end
                end
                for _,Candidate in ipairs(Gun:GetDescendants()) do
                    if Candidate:IsA("RemoteEvent") and MatchKeywords(Candidate.Name,{"shootgun","gunfired","shoot","fire"}) then
                        local Ok=pcall(function() Candidate:FireServer(Target) end)
                        if Ok then Runtime.MM2LastShot=os.clock(); return true end
                    elseif Candidate:IsA("RemoteFunction") and MatchKeywords(Candidate.Name,{"shootgun","gunfired","shoot","fire"}) then
                        local Ok,Result=pcall(function() return Candidate:InvokeServer(Target) end)
                        if Ok and Result~=false then Runtime.MM2LastShot=os.clock(); return true end
                    end
                end
                local Cam=workspace.CurrentCamera or Camera
                if Cam then pcall(function() Cam.CFrame=CFrame.new(Cam.CFrame.Position,Target) end) end
                local Ok=pcall(function() Gun:Activate() end)
                if Ok then Runtime.MM2LastShot=os.clock() end
                return Ok
            end
            local function KnifeAttack(P,PreferThrow)
                if not P or IsProtected(P) or not IsAlive(P) then return false end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(P) then return false end
                local Knife=EquipNamed("knife")
                if not Knife then return false end
                local Part=MM2TargetPart(P)
                if not Part then return false end
                local Target=(PreferThrow and PredictedPosition(Part,"knife")) or Part.Position

                if State.MM2Invisible then
                    if not Runtime.MM2SurfaceToolProxy then return false end
                    local Used=Runtime.MM2SurfaceToolProxy(Target,PreferThrow and "throw" or "primary")
                    if Used then Runtime.MM2LastKnife=os.clock() end
                    return Used
                end

                local Handle=Knife:FindFirstChild("Handle",true)
                local Throw=Knife:FindFirstChild("Throw",true) or Knife:FindFirstChild("ThrowKnife",true)
                local Stab=Knife:FindFirstChild("Stab",true) or Knife:FindFirstChild("Slash",true)
                if PreferThrow and Throw then
                    local Origin=(Handle and Handle.CFrame) or (Root() and Root().CFrame)
                    local Ok,Result=false,nil
                    if Throw:IsA("RemoteEvent") then Ok=pcall(function() Throw:FireServer(Origin,Target) end)
                    elseif Throw:IsA("RemoteFunction") then Ok,Result=pcall(function() return Throw:InvokeServer(Origin,Target) end) end
                    if Ok and Result~=false then Runtime.MM2LastKnife=os.clock(); return true end
                end
                if Stab then
                    local Arg=(Stab.Name=="Stab") and "Down" or "Slash"
                    local Ok,Result=false,nil
                    if Stab:IsA("RemoteEvent") then Ok=pcall(function() Stab:FireServer(Arg) end)
                    elseif Stab:IsA("RemoteFunction") then Ok,Result=pcall(function() return Stab:InvokeServer(Arg) end) end
                    if Ok and Result~=false then Runtime.MM2LastKnife=os.clock() end
                end
                local Activated=pcall(function() Knife:Activate() end)
                local Me=Root()
                local InReach=Me and (Me.Position-Part.Position).Magnitude<=math.max(tonumber(State.MM2KillAuraRadius) or 12,16)
                if InReach and Handle and type(firetouchinterest)=="function" then
                    pcall(function()
                        firetouchinterest(Handle,Part,0)
                        task.wait()
                        firetouchinterest(Handle,Part,1)
                    end)
                end
                if Activated then Runtime.MM2LastKnife=os.clock() end
                return Activated or InReach
            end
            local function MM2AimPart(P,AimMode,Cam)
                local C=P and P.Character
                if not C then return nil end
                local Preferred=tostring(State.MM2TargetPart or "Smart")
                if Preferred~="Smart" then return MM2TargetPart(P) end

                if AimMode=="gun" then
                    return C:FindFirstChild("UpperTorso") or C:FindFirstChild("HumanoidRootPart") or C:FindFirstChild("Torso") or C:FindFirstChild("Head")
                end
                return C:FindFirstChild("HumanoidRootPart") or C:FindFirstChild("UpperTorso") or C:FindFirstChild("Torso") or C:FindFirstChild("Head")
            end
            local function MM2AimTarget()
                local Cam=workspace.CurrentCamera or Camera
                if not Cam then return nil,nil,nil,nil end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then
                    Runtime.MM2AimLockedPlayer=nil
                    Runtime.MM2AimLockedAt=nil
                    return nil,nil,nil,nil
                end
                local LocalRole=RoleOf(Player)
                if LocalRole~="Murderer" and not string.find(LocalRole,"Sheriff",1,true) then
                    Runtime.MM2AimLockedPlayer=nil
                    Runtime.MM2AimLockedAt=nil
                    return nil,nil,nil,nil
                end
                local Reference=MM2AimReferencePosition(Cam)
                local FOV=math.max(tonumber(State.MM2AimFOV) or 420,20)
                local AimMode=LocalRole=="Murderer" and "knife" or "gun"
                local function AllowedTarget(P)
                    if not P or P==Player or not IsAlive(P) or IsProtected(P) then return false end
                    if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(P) then return false end
                    local Role=RoleOf(P)
                    return (string.find(LocalRole,"Sheriff",1,true) and Role=="Murderer")
                        or (LocalRole=="Murderer" and Role~="Murderer")
                end
                local function Visible(P,Part)
                    if not State.MM2AimVisibleOnly then return true end
                    local Origin=Cam.CFrame.Position
                    local Delta=Part.Position-Origin
                    if Delta.Magnitude<0.5 then return true end
                    local Params=RaycastParams.new()
                    Params.FilterType=Enum.RaycastFilterType.Exclude
                    Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                    Params.IgnoreWater=true
                    local Hit=workspace:Raycast(Origin,Delta,Params)
                    return not Hit or (P.Character and Hit.Instance and Hit.Instance:IsDescendantOf(P.Character))
                end
                local function Candidate(P,Grace)
                    if not AllowedTarget(P) then return nil end
                    local Part=MM2AimPart(P,AimMode,Cam)
                    if not Part or not Visible(P,Part) then return nil end
                    local AimPoint=PredictedPosition(Part,AimMode) or Part.Position
                    local Screen,OnScreen=Cam:WorldToViewportPoint(AimPoint)
                    if not OnScreen or Screen.Z<=0 then return nil end
                    local D=(Vector2.new(Screen.X,Screen.Y)-Reference).Magnitude
                    if D>FOV*(Grace or 1) then return nil end
                    local WorldDistance=(Part.Position-Cam.CFrame.Position).Magnitude

                    local Score=D+math.min(WorldDistance,300)*0.018
                    return Part,AimPoint,D,Score
                end

                local Locked=Runtime.MM2AimLockedPlayer
                local LockPart,LockPoint,LockDist,LockScore=nil,nil,nil,nil
                if Locked then
                    LockPart,LockPoint,LockDist,LockScore=Candidate(Locked,math.clamp(tonumber(State.MM2AimLockGrace) or 1.32,1.05,1.75))
                    if not LockPart then
                        Runtime.MM2AimLockedPlayer=nil
                        Runtime.MM2AimLockedAt=nil
                        Locked=nil
                    end
                end

                local BestP,BestPart,BestPoint,BestDist,BestScore=nil,nil,nil,nil,math.huge
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    local Part,AimPoint,D,Score=Candidate(P,1)
                    if Part and Score<BestScore then
                        BestP,BestPart,BestPoint,BestDist,BestScore=P,Part,AimPoint,D,Score
                    end
                end

                if Locked and LockPart then
                    local HeldFor=os.clock()-(tonumber(Runtime.MM2AimLockedAt) or os.clock())
                    local MinLock=math.clamp(tonumber(State.MM2AimMinLockTime) or 0.07,0,0.30)
                    if HeldFor<MinLock or not BestP or BestP==Locked then
                        return Locked,LockPart,LockPoint,LockDist
                    end
                    local Stick=math.clamp(tonumber(State.MM2AimStickiness) or 0.78,0,0.95)
                    local SwitchFactor=1-(Stick*0.45)

                    if BestScore>=LockScore*SwitchFactor then
                        return Locked,LockPart,LockPoint,LockDist
                    end
                end

                if BestP~=Runtime.MM2AimLockedPlayer then
                    Runtime.MM2AimLockedPlayer=BestP
                    Runtime.MM2AimLockedAt=BestP and os.clock() or nil
                end
                return BestP,BestPart,BestPoint,BestDist
            end
            local function NearestThreat()
                local Me=Root()
                local Murderer=FindRolePlayer("Murderer")
                local R=Murderer and Murderer.Character and Murderer.Character:FindFirstChild("HumanoidRootPart")
                if Me and R then return Murderer,(Me.Position-R.Position).Magnitude end
                return nil,math.huge
            end
            local function UpdateMM2Session()
                local Session=Runtime.MM2Session
                local CurrentMapName=MapName()
                if CurrentMapName~="Lobby / Loading" and Session.LastMap~=CurrentMapName then
                    Session.RoundsSeen=(tonumber(Session.RoundsSeen) or 0)+1
                end
                Session.LastMap=CurrentMapName

                local BagNow,BagMax,BagRaw=BagNumbers()
                if BagNow and Session.LastBag and BagNow>Session.LastBag then
                    Session.CoinsCollected=(tonumber(Session.CoinsCollected) or 0)+(BagNow-Session.LastBag)
                end
                Session.LastBag=BagNow

                local MyRole=RoleOf(Player)
                if State.MM2RoleAlerts and Session.LastRole and Session.LastRole~=MyRole then
                    Notify("MM2 Role","You are now: "..MyRole)
                end
                Session.LastRole=MyRole

                local Dropped=GunDrop()~=nil
                if State.MM2GunAlerts and Dropped and not Session.GunWasDropped then
                    Notify("MM2","The sheriff's gun was dropped.")
                end
                Session.GunWasDropped=Dropped

                local _,ThreatDistance=NearestThreat()
                local ThreatText=ThreatDistance<math.huge and (math.floor(ThreatDistance).." studs") or "Not detected"
                local Elapsed=math.max(0,math.floor(os.clock()-(Session.StartedAt or os.clock())))
                local TimeText=string.format("%02d:%02d",math.floor(Elapsed/60),Elapsed%60)
                return "Role: "..MyRole
                    .."\nMap: "..CurrentMapName
                    .."\nBag: "..tostring(BagRaw).."  •  Gun: "..(Dropped and "Dropped" or (HasTool(Player,"gun") and "Owned" or "Not detected"))
                    .."\nMurderer distance: "..ThreatText
                    .."\nSession: "..tostring(Session.CoinsCollected or 0).." coins • "..tostring(Session.RoundsSeen or 0).." rounds • "..TimeText
            end
            local function KillAllOnce()
                local Token,Owner=Runtime.MM2StopGeneration,Character()
                local LoopToken=State.Loops.MM2KillAll
                local function Running()
                    return ActionValid(Token,Owner) and State.Loops.MM2KillAll==LoopToken
                end
                if RoleOf(Player)~="Murderer" then return false end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then return false end
                local Did=false
                local Start=Root() and Root().CFrame
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    if not Running() then return Did end
                    if P~=Player and IsAlive(P) and not IsProtected(P) and RoleOf(P)~="Murderer"
                        and (not Runtime.MM2PlayerInActiveMap or Runtime.MM2PlayerInActiveMap(P)) then
                        local PR=MM2TargetPart(P)
                        if PR then
                            local Me=Root()
                            if Me and (Me.Position-PR.Position).Magnitude>14 then
                                pcall(function() ProfileTravelToCFrame(PR.CFrame*CFrame.new(0,0,3)) end)
                            end
                            if not Running() then return Did end
                            local TargetHumanoid=P.Character and P.Character:FindFirstChildOfClass("Humanoid")
                            local Before=TargetHumanoid and TargetHumanoid.Health or 0
                            local Deadline=os.clock()+0.75
                            repeat
                                KnifeAttack(P,false)
                                task.wait(math.max(tonumber(State.MM2AttackDelay) or 0.14,0.05))
                                TargetHumanoid=P.Character and P.Character:FindFirstChildOfClass("Humanoid")
                            until not Running() or not TargetHumanoid or TargetHumanoid.Health<=0 or TargetHumanoid.Health<Before or os.clock()>=Deadline
                            Did=true
                        end
                    end
                end
                if Running() and Did and State.MM2ReturnAfterKill and typeof(Start)=="CFrame" then
                    Runtime.ProfileSmartTravel(Start,nil,{Mode=State.MM2FarmMode,Speed=State.MM2FarmSpeed,Source="MM2ReturnKill"})
                end
                return Did
            end
            local function TeleportToMap()
                local Map=CurrentMap()
                if not Map then return false end
                local Spawn=Map:FindFirstChild("Spawns")
                local Target=Spawn and Spawn:FindFirstChildWhichIsA("BasePart",true) or GetRoot(Map)
                if not Target then return false end

                local Destination=Target.CFrame*CFrame.new(0,4,0)
                local S=Runtime.MM2InvisibleState
                if State.MM2Invisible and S and S.ProxyActive and S.ProxyCharacter and S.ProxyRoot then
                    if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                    pcall(function()
                        S.ProxyCharacter:PivotTo(Destination)
                        S.ProxyRoot.AssemblyLinearVelocity=Vector3.zero
                        S.ProxyRoot.AssemblyAngularVelocity=Vector3.zero
                    end)
                    S.SurfaceCFrame=S.ProxyRoot.CFrame
                    S.LastSafeProxyCFrame=S.ProxyRoot.CFrame
                    local TeleportNow=os.clock()
                    S.SuppressServerTeleportUntil=TeleportNow+1.00
                    S.ServerTeleportIgnoreUntil=TeleportNow+1.00
                    S.PendingServerTeleportCFrame=nil
                    S.PendingServerTeleportSince=nil
                    S.PendingServerTeleportSamples=0
                    local RealChar=Player.Character
                    local RealRoot=RealChar and RealChar:FindFirstChild("HumanoidRootPart")
                    if RealChar and RealRoot then
                        local Hidden=CFrame.new(S.ProxyRoot.Position-Vector3.new(0,tonumber(S.Depth) or 25,0))*S.ProxyRoot.CFrame.Rotation
                        S.LastForcedShellCFrame=Hidden
                        S.LastShellWriteAt=TeleportNow
                        S.RecentShellWrites=S.RecentShellWrites or {}
                        table.insert(S.RecentShellWrites,{Position=Hidden.Position,At=TeleportNow})
                        while #S.RecentShellWrites>18 do table.remove(S.RecentShellWrites,1) end
                        pcall(function()
                            RealChar:PivotTo(Hidden)
                            RealRoot.AssemblyLinearVelocity=Vector3.zero
                            RealRoot.AssemblyAngularVelocity=Vector3.zero
                        end)
                    end
                    return true
                end

                ProfileTravelToCFrame(Destination)
                return true
            end
            local function TeleportToLobby()
                local Lobby=LobbyObject()
                local Target=Lobby and (Lobby:FindFirstChildWhichIsA("SpawnLocation",true) or Lobby:FindFirstChildWhichIsA("BasePart",true))
                if Target then ProfileTravelToCFrame(Target.CFrame*CFrame.new(0,4,0)); return true end
                return false
            end
            local function TeleportToVoting()
                local Lobby=LobbyObject() or workspace
                local Best=nil
                for _,Obj in ipairs(Lobby:GetDescendants()) do
                    local Name=string.lower(Obj.Name)
                    if (string.find(Name,"voting",1,true) or string.find(Name,"vote",1,true)) and GetRoot(Obj) then
                        Best=Obj
                        break
                    end
                end
                if Best then return MoveTo(Best,CFrame.new(0,3,0)) end
                return false
            end
            local function TeleportToHighSpot()
                local Map=CurrentMap()
                if not Map then return false end
                local Highest=nil
                for _,Obj in ipairs(Map:GetDescendants()) do
                    if Obj:IsA("BasePart") and Obj.CanCollide and Obj.Transparency<0.98
                        and (not Highest or Obj.Position.Y>Highest.Position.Y) then
                        Highest=Obj
                    end
                end
                if Highest then
                    return ProfileTravelToCFrame(Highest.CFrame*CFrame.new(0,5,0))
                end
                return false
            end
            local function MM2MoveToObject(Object,Offset,Mode,Generation)
                local Target=GetRoot(Object)
                if not Target then return false end
                if Generation and not Runtime.MM2FarmRunActive(Generation) then return false end

                local TravelMode=tostring(Mode or State.MM2FarmMode or "Smooth Tween")
                local Goal=Target.CFrame*(Offset or CFrame.new(0,1.5,0))
                Runtime.TweenSpeed=math.clamp(tonumber(State.MM2FarmSpeed) or 115,35,300)
                local OldEase=Runtime.TweenEaseArrival
                Runtime.TweenEaseArrival=TravelMode=="Smooth Tween" or TravelMode=="Underground Tween"
                local Reached=Runtime.ProfileSmartTravel(Goal,function()
                    local Part=GetRoot(Object)
                    if not Part or (Generation and not Runtime.MM2FarmRunActive(Generation)) then return nil end
                    return Part.CFrame*(Offset or CFrame.new(0,1.5,0))
                end,{Mode=TravelMode,Speed=State.MM2FarmSpeed,Source="MM2Farm"})
                Runtime.TweenEaseArrival=OldEase
                if Generation and not Runtime.MM2FarmRunActive(Generation) then return false end
                return Reached~=false
            end
            local function TouchMM2Object(Object,Mode,Generation,StillRunning)
                local Token,Owner=Runtime.MM2StopGeneration,Character()
                local function Running()
                    return ActionValid(Token,Owner)
                        and (not Generation or Runtime.MM2FarmRunActive(Generation))
                        and (not StillRunning or StillRunning())
                end
                if not Running() then return false end
                local Target=GetRoot(Object)
                local Me=Root()
                if not Target or not Me then return false end
                if not MM2MoveToObject(Object,CFrame.new(0,1.25,0),Mode,Generation) then return false end
                if not Running() then return false end
                Runtime.Movement.Guard()
                Me=Root()
                Target=GetRoot(Object)
                if not Me or not Target then return false end

                local ExactCoin=ResolveCoinObject(Object)
                if State.MM2Invisible and ExactCoin and Runtime.MM2TryProxyCoinPickup then

                    return Runtime.MM2TryProxyCoinPickup(10.0,ExactCoin)
                end

                if type(firetouchinterest)=="function" then
                    local TouchParts={Target}
                    if not Object:IsA("BasePart") then
                        for _,Part in ipairs(Object:GetDescendants()) do
                            if Part:IsA("BasePart") and not table.find(TouchParts,Part) then
                                table.insert(TouchParts,Part)
                                if #TouchParts>=12 then break end
                            end
                        end
                    end
                    for _,Part in ipairs(TouchParts) do
                        if State.MM2Invisible and Runtime.MM2WithSurfaceShell then
                            local RealChar=Player.Character
                            local RealRoot=RealChar and RealChar:FindFirstChild("HumanoidRootPart")
                            if RealRoot then
                                Runtime.MM2WithSurfaceShell(function()
                                    pcall(function() RealRoot.CanTouch=true end)
                                    firetouchinterest(RealRoot,Part,0)
                                    RunService.Heartbeat:Wait()
                                    firetouchinterest(RealRoot,Part,1)
                                end,0.10,2)
                            end
                        else
                            pcall(function()
                                firetouchinterest(Me,Part,0)
                                task.wait()
                                firetouchinterest(Me,Part,1)
                            end)
                        end
                    end
                else
                    pcall(function() Me.CFrame=Target.CFrame end)
                end
                if not Running() or not Object.Parent then return false end
                local Prompt=Object:FindFirstChildWhichIsA("ProximityPrompt",true)
                if Prompt and type(fireproximityprompt)=="function" then pcall(function() fireproximityprompt(Prompt) end) end
                return true
            end
            local function CollectMM2Coin(Coin,Mode,Generation)
                if not Coin or not Coin.Parent then return false end
                Runtime.MM2FailedCoins=Runtime.MM2FailedCoins or {}
                local Before=select(1,BagNumbers())
                local function Running()
                    return Runtime.Movement.Valid() and (not Generation or Runtime.MM2FarmRunActive(Generation))
                end
                local function Collected()
                    local Now=select(1,BagNumbers())
                    return not CoinAvailable(Coin) or (Before and Now and Now>Before)
                end
                for Attempt=1,2 do
                    if not Running() then return false end
                    TouchMM2Object(Coin,Mode,Generation,Running)
                    local Deadline=os.clock()+0.8
                    repeat
                        if not Running() then return false end
                        if Collected() then
                            Runtime.MM2FailedCoins[Coin]=nil
                            Runtime.MM2CoinCacheAt=0
                            local Route=Runtime.MM2RollingRoute or {}
                            local Index=table.find(Route,Coin)
                            if Index then table.remove(Route,Index) end
                            OrderedCoinRoute(6)
                            return true
                        end
                        task.wait(0.1)
                    until os.clock()>=Deadline
                end
                Runtime.MM2FailedCoins[Coin]=os.clock()
                OrderedCoinRoute(6)
                return false
            end
            local function SafeGunPickup(Automatic)
                local Token,Owner=Runtime.MM2StopGeneration,Character()
                local LoopToken=State.Loops.MM2Gun
                local function Running()
                    return ActionValid(Token,Owner) and (not Automatic or State.Loops.MM2Gun==LoopToken)
                end
                if not Running() then return false,"cancelled" end
                if Runtime.MM2PlayerInActiveMap and not Runtime.MM2PlayerInActiveMap(Player) then
                    if not Automatic then Notify("MM2","Gun pickup only runs while you are inside the active round map.") end
                    return false,"lobby"
                end
                if RoleOf(Player)=="Murderer" or HasTool(Player,"gun") then
                    if not Automatic then Notify("MM2","Gun pickup is not needed for your current role.") end
                    return false,"not needed"
                end
                local Gun=GunDrop()
                if not Gun then return false,"missing" end
                local Murderer=FindRolePlayer("Murderer")
                local MurdererRoot=Murderer and MM2TargetPart(Murderer)
                local GunRoot=GetRoot(Gun)
                local Distance=(MurdererRoot and GunRoot) and (MurdererRoot.Position-GunRoot.Position).Magnitude or math.huge
                if State.MM2SafeGunPickup and Distance<=(tonumber(State.MM2GunSafeDistance) or 45) then
                    if not Automatic or os.clock()-(Runtime.MM2LastUnsafeGunNotice or 0)>4 then
                        Runtime.MM2LastUnsafeGunNotice=os.clock()
                        Notify("MM2 Safe Gun","Waiting—the murderer is too close to the gun.")
                    end
                    return false,"unsafe"
                end

                local StartRoot=Root()
                local Start=StartRoot and StartRoot.CFrame or nil
                Runtime.MM2LastGunPickupOrigin=Start
                local Touched=false
                local Collected,GunTool=false,nil
                if State.MM2Invisible and Runtime.MM2PickupWeaponFromProxy then
                    local Reached=MM2MoveToObject(Gun,CFrame.new(0,1.25,0),"Teleport",nil)
                    if Reached and Running() then
                        Collected,GunTool=Runtime.MM2PickupWeaponFromProxy(Gun,"gun")
                        Touched=Collected
                    end
                else
                    for Attempt=1,2 do
                        if not Running() then break end
                        Gun=GunDrop() or Gun
                        if not Gun or not Gun.Parent then break end
                        Touched=TouchMM2Object(Gun,"Teleport",nil,Running) or Touched
                        local Deadline=os.clock()+0.85
                        repeat
                            task.wait(0.04)
                            Collected,GunTool=HasTool(Player,"gun")
                            if Collected then break end
                            local LiveDrop=GunDrop()
                            if not LiveDrop and Touched then
                                task.wait(0.06)
                                Collected,GunTool=HasTool(Player,"gun")
                                if Collected then break end
                            end
                        until not Running() or os.clock()>=Deadline
                        if Collected then break end
                        Runtime.MM2CoinCacheAt=0
                    end
                end
                if not Running() then return false,"cancelled" end
                if not Collected then
                    Collected,GunTool=HasTool(Player,"gun")
                end

                if Collected and GunTool then

                    if State.MM2Invisible and Runtime.MM2EquipRealTool then
                        Runtime.MM2InvisibleState.ProxyWeaponKind="gun"
                        Runtime.MM2EquipRealTool(GunTool)
                        Runtime.MM2SyncProxyTool(true)
                    elseif State.MM2AutoEquipGun and GunTool.Parent~=Character() then
                        local H=Humanoid()
                        if H then pcall(function() H:EquipTool(GunTool) end) end
                    end
                end

                if Collected and typeof(Start)=="CFrame" then
                    Runtime.CancelMM2Travel()
                    local Returned=Runtime.ProfileSmartTravel(Start,nil,{Mode="Teleport",Speed=State.MM2FarmSpeed,Source="MM2ReturnGunExact"})
                    if not Returned then
                        local C=Character()
                        if C and C.Parent then pcall(function() C:PivotTo(Start) end) end
                    end
                    local R=Root()
                    if R then
                        pcall(function()
                            R.AssemblyLinearVelocity=Vector3.zero
                            R.AssemblyAngularVelocity=Vector3.zero
                        end)
                    end
                end
                return Collected,Collected and "picked up + returned" or "failed"
            end
            local function SmartEscape()
                if RoleOf(Player)=="Murderer" then return false end
                local Threat,Distance=NearestThreat()
                local Me=Root()
                local ThreatRoot=Threat and MM2TargetPart(Threat)
                if not Me or not ThreatRoot then return false end
                local Limit=tonumber(State.MM2ThreatDistance) or 70
                if Distance>Limit then return false end

                if os.clock()-(Runtime.MM2LastEscapeAt or 0)<0.55 then return true end
                local Away=Me.Position-ThreatRoot.Position
                Away=Vector3.new(Away.X,0,Away.Z)
                if Away.Magnitude<1 then Away=Vector3.new(1,0,0) end
                local RunDistance=math.clamp(tonumber(State.MM2EscapeDistance) or 60,25,120)
                local Params=RaycastParams.new()
                Params.FilterType=Enum.RaycastFilterType.Exclude
                Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore(Threat.Character)
                Params.IgnoreWater=true
                local Best,BestScore=nil,-math.huge
                for Offset=-3,3 do
                    local Angle=math.rad(Offset*18)
                    local Direction=CFrame.fromAxisAngle(Vector3.yAxis,Angle):VectorToWorldSpace(Away.Unit)
                    local Candidate=Me.Position+Direction*RunDistance
                    local Hit=workspace:Raycast(Candidate+Vector3.new(0,45,0),Vector3.new(0,-130,0),Params)
                    if Hit and Hit.Instance and Hit.Instance.CanCollide and Hit.Normal.Y>0.65
                        and Hit.Position.Y>workspace.FallenPartsDestroyHeight+20 then
                        local Goal=Hit.Position+Vector3.new(0,3.25,0)
                        local ThreatGap=(Goal-ThreatRoot.Position).Magnitude
                        local VerticalPenalty=math.abs(Goal.Y-Me.Position.Y)*0.25
                        local Score=ThreatGap-VerticalPenalty
                        if Score>BestScore then Best,BestScore=Goal,Score end
                    end
                end
                if not Best then return false end
                Runtime.MM2LastEscapeAt=os.clock()
                return Runtime.ProfileSmartTravel(CFrame.lookAt(Best,Best+Away.Unit),nil,{Mode="Smooth Tween",Speed=State.MM2FarmSpeed,Source="MM2Escape"})
            end
            local function TravelToMM2Player(TargetPlayer,Mode)
                if not TargetPlayer or not IsAlive(TargetPlayer) then return false end
                local Offset=CFrame.new(0,2,4)
                local Part=MM2TargetPart(TargetPlayer)
                if not Part then return false end
                local function Provider()
                    if not TargetPlayer.Parent or not IsAlive(TargetPlayer) then return nil end
                    local Live=MM2TargetPart(TargetPlayer)
                    return Live and (Live.CFrame*Offset) or nil
                end
                return Runtime.ProfileSmartTravel(Part.CFrame*Offset,Provider,{
                    Mode=tostring(Mode or "Teleport"),
                    Speed=math.clamp(tonumber(State.MM2FarmSpeed) or 115,35,300),
                    Source="MM2PlayerTravel"
                })
            end
            local function SelectedMM2Player()
                return State.MM2PlayerTarget and FindPlayerByDisplayName(State.MM2PlayerTarget)
            end
            local function OwnedMM2Tools(Needle,AutoLabel)
                local Out,Seen={AutoLabel},{[string.lower(AutoLabel)]=true}
                for _,Container in pairs({Player.Character,Player:FindFirstChildOfClass("Backpack")}) do
                    if Container then
                        for _,Tool in ipairs(Container:GetChildren()) do
                            if Tool:IsA("Tool") and string.find(string.lower(Tool.Name),string.lower(Needle),1,true)
                                and not Seen[string.lower(Tool.Name)] then
                                Seen[string.lower(Tool.Name)]=true
                                table.insert(Out,Tool.Name)
                            end
                        end
                    end
                end
                table.sort(Out,function(A,B)
                    if A==B then return false end
                    if A==AutoLabel then return true end
                    if B==AutoLabel then return false end
                    return string.lower(A)<string.lower(B)
                end)
                return Out
            end
            local function EquipExactMM2Tool(Name,Needle)
                if not Name or string.sub(Name,1,5)=="Auto " then return EquipNamed(Needle) end
                local C=Player.Character
                local BP=Player:FindFirstChildOfClass("Backpack")
                local Tool=(C and C:FindFirstChild(Name)) or (BP and BP:FindFirstChild(Name))
                local H=State.MM2Invisible and Runtime.MM2RealHumanoid and Runtime.MM2RealHumanoid() or Humanoid()
                if Tool and Tool:IsA("Tool") and H then
                    if State.MM2Invisible and Runtime.MM2InvisibleState then Runtime.MM2InvisibleState.ProxyWeaponKind=Needle end
                    if State.MM2Invisible and Runtime.MM2EquipRealTool then
                        Runtime.MM2EquipRealTool(Tool)
                    else
                        pcall(function() H:EquipTool(Tool) end)
                    end
                    return Tool
                end
                return nil
            end
            local function SetMM2FOVCircle(Enabled)
                StopLoop("MM2FOVCircle")
                if Runtime.MM2FOVCircle then
                    pcall(function() Runtime.MM2FOVCircle:Remove() end)
                    Runtime.MM2FOVCircle=nil
                end
                if not Enabled then return true end
                if type(Drawing)~="table" or type(Drawing.new)~="function" then
                    Notify("MM2","FOV circle needs Drawing API support in your executor.")
                    return false
                end
                local Ok,Circle=pcall(function()
                    local C=Drawing.new("Circle")
                    C.Visible=true
                    C.Filled=false
                    C.Thickness=1.5
                    C.Transparency=0.82
                    C.Color=Color3.fromRGB(232,199,48)
                    C.NumSides=72
                    return C
                end)
                if not Ok or not Circle then return false end
                Runtime.MM2FOVCircle=Circle
                StartLoop("MM2FOVCircle",function()
                    if Runtime.MM2FOVCircle~=Circle then return end
                    Circle.Position=MM2AimReferencePosition(workspace.CurrentCamera or Camera)
                    Circle.Radius=math.clamp(tonumber(State.MM2AimFOV) or 420,40,900)
                    Circle.Visible=true
                end,0.02)
                return true
            end
            local function MM2Compatibility()
                local Map=CurrentMap(); local Coins=CoinContainer(); local Gun=GunDrop()
                local CoinCount=#CoinCandidates()
                local HasKnife=HasTool(Player,"knife"); local HasGun=HasTool(Player,"gun")
                local Role=RoleOf(Player)
                return "Role detection: "..Role
                    .."\nRole data source: "..((ReplicatedStorage:FindFirstChild("GetPlayerData",true) and "Ready") or "tool fallback")
                    .."\nMap: "..(Map and Map.Name or "Lobby / not loaded")
                    .."\nCoin sources: "..(CoinCount>0 and (CoinCount.." loaded") or (Coins and "container ready" or "not loaded"))
                    .."\nDropped gun: "..(Gun and "Detected" or "Not currently dropped")
                    .."\nRound tools: "..(HasKnife and "Knife" or (HasGun and "Gun" or "None yet"))
                    .."\nDrawing overlays: "..((type(Drawing)=="table" and type(Drawing.new)=="function") and "Ready" or "FOV circle unavailable")
            end
