            end})
            AimCard:CreateToggle({Name="Role-Smart Aim Assist",Flag="GameProfile_MM2_Aim",CurrentValue=false,Callback=function(V)
                if V then
                    Runtime.MM2AimLockedPlayer=nil
                    Runtime.MM2AimLockedAt=nil
                    Runtime.MM2AimLastStep=os.clock()
                    StartLoop("MM2Aim",function()
                        local _,Part,AimPoint,AimError=MM2AimTarget()
                        local Cam=workspace.CurrentCamera or Camera
                        local Now=os.clock()
                        local Dt=math.clamp(Now-(tonumber(Runtime.MM2AimLastStep) or Now),0.005,0.05)
                        Runtime.MM2AimLastStep=Now
                        if Part and Cam and AimPoint then
                            local Error=tonumber(AimError) or 0
                            local Deadzone=math.clamp(tonumber(State.MM2AimDeadzone) or 1.5,0,8)
                            if Error>Deadzone then
                                local Desired=CFrame.new(Cam.CFrame.Position,AimPoint)
                                local Smooth=math.clamp(tonumber(State.MM2AimSmooth) or 6,1,18)

                                local FOV=math.max(tonumber(State.MM2AimFOV) or 420,20)
                                local ErrorBoost=1+math.clamp(Error/FOV,0,1)*1.65
                                local Response=(96/Smooth)*ErrorBoost
                                local Alpha=math.clamp(1-math.exp(-Response*Dt),0.02,1)
                                Cam.CFrame=Cam.CFrame:Lerp(Desired,Alpha)
                            end
                        end
                    end,0.008)
                else
                    StopLoop("MM2Aim")
                    Runtime.MM2AimLockedPlayer=nil
                    Runtime.MM2AimLockedAt=nil
                end
            end})
