                    local Accuracy=math.clamp(tonumber(State.MM2TriggerRadius) or 28,6,100)
                    local LockedLongEnough=P and (os.clock()-(tonumber(Runtime.MM2AimLockedAt) or 0))>=math.clamp(tonumber(State.MM2AimMinLockTime) or 0.07,0,0.30)
                    if P and Part and AimError and AimError<=Accuracy and LockedLongEnough then
