                            Runtime.MM2SuppressFarmReturn=Action~="Stop Farming"
                            Runtime.SetFlagValue("GameProfile_MM2_Coins",false)
                            local Token,Owner=Runtime.MM2StopGeneration,Character()
                            local FarmToken=Runtime.MM2FarmGeneration
                            task.defer(function()
