                    H.Name="BananiHub_AdoptTaskTarget"; H.Adornee=Target; H.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                    H.FillColor=Color3.fromRGB(255,220,35); H.OutlineColor=Color3.fromRGB(255,255,255)
                    H.FillTransparency=0.32; H.OutlineTransparency=0; H.Parent=Target
                    State.AdoptTaskHighlight=H
                end
                local function UseOwnedItem(Name)
                    local Keys=ItemKeys[Name]; if not State.AdoptAutoUseItems or not Keys then return false end
                    if os.clock()-State.AdoptItemUseAt<2.25 then return false end
                    local Label,Record=Inventory.Find(Keys)
                    if not Label then Inventory.Names(true); Label,Record=Inventory.Find(Keys) end
                    if not Label then return false end
                    if Name=="hungry" or Name=="thirsty" then
                        if not Record or (Record.Category~="food" and Record.Category~="foods" and Record.Category~="drinks") then
                            Label,Record=nil,nil
                            for Candidate,Item in pairs(State.AdoptInventoryRecords or {}) do
                                if (Item.Category=="food" or Item.Category=="foods" or Item.Category=="drinks")
                                    and MatchKeywords(Item.Name,Keys) then Label,Record=Candidate,Item; break end
                            end
                            if not Label then return false end
                        end
                    end
                    local Ok=false
                    local NeedRecord=State.AdoptAilmentRecords and State.AdoptAilmentRecords[Name]
                    local PetNeed=NeedRecord and NeedRecord.Target=="pet"
                    if (Name=="hungry" or Name=="thirsty") and Record and PetNeed then
                        if not Inventory.Equip(Label) then return false end
                        task.wait(0.12)
                        Runtime.Movement.Guard()
                        local PetUnique=Inventory.EquippedPet()
                        if not PetUnique or (NeedRecord.PetUnique and tostring(PetUnique)~=tostring(NeedRecord.PetUnique)) then return false end
                        Ok=TryRemote({"PetAPI/ConsumeFoodItem","PetAPI/ConsumeFood","AilmentsAPI/ConsumeFoodItem"},
                            {{Record.Unique,PetUnique},{PetUnique,Record.Unique},{Record.Unique},{Record.Raw,PetUnique}})
                    end
                    if not Ok and not PetNeed then Ok=Inventory.Use(Label) end
                    if Ok then State.AdoptItemUseAt=os.clock() end
                    return Ok==true
                end
                local function EnsureCarePet()
                    local Mode=tostring(State.AdoptFarmMode or "Pet + Baby")
                    if Mode=="Baby Only" then return nil end
                    local Unique=Inventory.EquippedPet()
                    if Unique then
                        local Data=Inventory.Read(false)
                        local Pets=Data and Data.inventory and Data.inventory.pets
                        if type(Pets)=="table" then
                            for Key,Pet in pairs(Pets) do
                                if type(Pet)=="table" and (tostring(Key)==tostring(Unique)
                                    or tostring(Pet.unique or Pet.unique_id or Pet.uuid)==tostring(Unique)) then return Unique end
                            end
                        end
                        return nil
                    end
                    local Label=Inventory.FirstCarePet(Mode=="Hatch Equipped Egg")
                    if not Label then return nil end
                    local Equipped=Inventory.Equip(Label)
                    if Equipped then
                        task.wait(0.18)
                        Unique=Inventory.EquippedPet()
                        return Unique
                    end
                    return nil
                end
                local function FurnitureOwner(Target)
                    local Node=Target
                    while Node and Node~=workspace do
                        for _,Key in ipairs({"furniture_unique","furniture_id","unique_id","furniture_type"}) do
                            if Node:GetAttribute(Key)~=nil then return Node end
                        end
                        if Node:IsA("Model") and MatchKeywords(Node.Name,{"bed","crib","shower","bath","bowl","piano","toilet","food","water"}) then return Node end
                        Node=Node.Parent
                    end
                    return Target
                end
                local function FurnitureIdentifier(Furniture)
                    if not Furniture then return nil end
                    for _,Key in ipairs({"furniture_unique","furniture_id","unique_id","furniture_type","id"}) do
                        local Value=Furniture:GetAttribute(Key)
                        if Value~=nil and tostring(Value)~="" then return Value end
                        local Object=Furniture:FindFirstChild(Key,true)
                        if Object and Object:IsA("ValueBase") and tostring(Object.Value)~="" then return Object.Value end
                    end
                    return Furniture.Name
                end
                local AdoptSourceFurnitureNames={
                    sleepy={generic_crib=true},
                    dirty={generic_shower=true},
                }
                local function AdoptSourceFurnitureTarget(Name)
                    local Wanted=AdoptSourceFurnitureNames[Name]
                    if not Wanted then return nil end
                    for _,Object in ipairs(Runtime.ProfileTargets()) do
                        if (Object:IsA("Model") or Object:IsA("BasePart")) then
                            local Normal=string.lower(tostring(Object.Name or "")):gsub("[%s%-]+","_")
                            if Wanted[Normal] then
                                return FurnitureOwner(Object)
                            end
                            for _,Key in ipairs({"furniture_type","furniture_id","use_id"}) do
                                local Value=Object:GetAttribute(Key)
                                if Value~=nil then
                                    local V=string.lower(tostring(Value)):gsub("[%s%-]+","_")
                                    if Wanted[V] then return FurnitureOwner(Object) end
                                end
                            end
                        end
                    end
                    return nil
                end

                local function EquippedPetCharacter(Unique)
                    local Cached=State.AdoptCarePetModel
                    if Cached and Cached.Parent and tostring(State.AdoptCarePetUnique)==tostring(Unique) then return Cached end
                    local Best=nil
                    local Count=0
                    for _,Model in ipairs(Runtime.ProfileTargets()) do
                        Count+=1; if Count>12000 then break end
                        if Model:IsA("Model") and not IsPlayerCharacter(Model) then
                            local Matches=false
                            local PetLike=string.find(string.lower(Model:GetFullName()),"pet",1,true)~=nil
                                or Model:GetAttribute("pet_type")~=nil or Model:GetAttribute("pet_unique")~=nil
                            for _,Key in ipairs({"pet_unique","unique_id","uuid"}) do
                                local Value=Model:GetAttribute(Key)
                                if Value~=nil and tostring(Value)==tostring(Unique) then
                                    Matches=true; break
                                end
                            end
                            if not Matches and PetLike then
                                for _,Key in ipairs({"owner","owner_name","owner_user_id"}) do
                                    local Value=Model:GetAttribute(Key)
                                    if Value~=nil and (tostring(Value)==Player.Name or tostring(Value)==tostring(Player.UserId)) then Matches=true; break end
                                end
                            end
                            if Matches and GetRoot(Model) then Best=Model; break end
                        end
                    end
                    if Best then State.AdoptCarePetModel=Best; State.AdoptCarePetUnique=Unique end
                    return Best or Unique
                end
                local function UseCareAction(Name,Target)
                    if Name=="sick" then
                        local Healed=TryRemote({"MonitorAPI/HealWithDoctor","HospitalAPI/Heal","AilmentsAPI/Heal"},{{},{Player}})
                        if Healed then return true end
                    end
                    if not Target or not Target.Parent then return false end
                    local Furniture=FurnitureOwner(Target)
                    local FurnitureId=FurnitureIdentifier(Furniture)
                    local Part=GetRoot(Furniture) or GetRoot(Target)
                    local NeedRecord=State.AdoptAilmentRecords and State.AdoptAilmentRecords[Name]
                    local IsBaby=NeedRecord and NeedRecord.Target=="baby"
                    local Pet=not IsBaby and EnsureCarePet() or nil
                    local PetTarget=Pet and EquippedPetCharacter(Pet)
                    local UseData={cframe=Part and Part.CFrame or (Root() and Root().CFrame or CFrame.new())}
                    local Variants={}
                    if Pet then
                        table.insert(Variants,{Player,FurnitureId,"UseBlock",UseData,PetTarget})
                        table.insert(Variants,{Player,FurnitureId,"use_block",UseData,PetTarget})
                        table.insert(Variants,{FurnitureId,"UseBlock",UseData,PetTarget})
                        table.insert(Variants,{Player,Furniture,"UseBlock",UseData,PetTarget})
                        table.insert(Variants,{PetTarget,FurnitureId,"UseBlock"})
                    end
                    local Mode=tostring(State.AdoptFarmMode or "Pet + Baby")
                    if IsBaby then
                        local BabyTarget=Character() or Player
                        table.insert(Variants,{Player,FurnitureId,"UseBlock",UseData,BabyTarget})
                        table.insert(Variants,{Player,FurnitureId,"use_block",UseData,BabyTarget})
                        table.insert(Variants,{FurnitureId,"UseBlock",UseData,BabyTarget})
                        table.insert(Variants,{Player,Furniture,"UseBlock",UseData,BabyTarget})
                    end
                    if #Variants==0 then
                        table.insert(Variants,{Player,FurnitureId,"UseBlock",UseData})
                        table.insert(Variants,{FurnitureId,"UseBlock",UseData})
                    end
                    return TryRemote({"HousingAPI/ActivateFurniture","HousingAPI/ActivateInteriorFurniture","FurnitureAPI/ActivateFurniture","FurnitureAPI/UseFurniture"},Variants)
                end
                local function MovementNeed(Name)
                    local H,R=Humanoid(),Root(); if not H or not R then return false end
                    if Name=="ride" then UseOwnedItem("ride") end
                    return Runtime.ProfileSmartTravel(CFrame.new(R.Position+R.CFrame.LookVector*32+R.CFrame.RightVector*8),nil,{Mode="Walk",Source="AdoptCare"})
                end
                local function RefreshTaskQueue(Active)
                    local ActiveSet={}; for _,Name in ipairs(Active) do ActiveSet[Name]=true end
                    local Queue,Queued={},{}
                    local Current=State.AdoptLockedTask
                    if Current and ActiveSet[Current] then table.insert(Queue,Current); Queued[Current]=true end
                    for _,Name in ipairs(State.AdoptTaskQueue or {}) do
                        if ActiveSet[Name] and not Queued[Name] then table.insert(Queue,Name); Queued[Name]=true end
                    end
                    for _,Name in ipairs(Active) do
                        if not Queued[Name] then table.insert(Queue,Name); Queued[Name]=true end
                    end
                    State.AdoptTaskQueue=Queue
                    return Queue,ActiveSet
                end
                local function BeginQueuedTask(Name)
                    State.AdoptLockedTask=Name
                    State.AdoptLockedTaskSince=os.clock()
                    State.AdoptTaskLastProgressAt=os.clock()
                    State.AdoptTaskNextActionAt=0
                    local Record=State.AdoptAilmentRecords and State.AdoptAilmentRecords[Name]
                    State.AdoptTaskProgress=Record and Record.Progress or nil
                end
                local function FinishQueuedTask()
                    local Finished=State.AdoptLockedTask
                    local Queue={}
                    for _,Name in ipairs(State.AdoptTaskQueue or {}) do if Name~=Finished then table.insert(Queue,Name) end end
                    State.AdoptTaskQueue=Queue
                    State.AdoptLockedTask=nil
                    State.AdoptLockedTaskSince=0
                    State.AdoptTaskProgress=nil
                    State.AdoptTaskNextActionAt=0
                    State.AdoptLastTaskAction=0
                    if Finished and Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                    ClearTaskHighlight()
                end
                function API.TaskStep(ForceScan)
                    Runtime.Movement.Guard()

                    if State.AdoptFarmMode=="Baby Only" then
                        if os.clock()<(State.AdoptNextRoleCheck or 0) then return false end
                        if not API.Team("Babies") then
                            State.AdoptNextRoleCheck=os.clock()+3
                            SetStatus("Waiting for confirmed Baby role")
                            return false
                        end
                    end
                    if State.AdoptFarmMode~="Baby Only" and not Inventory.EquippedPet()
                        and os.clock()>=(State.AdoptNextPetEquipAt or 0) then
                        State.AdoptNextPetEquipAt=os.clock()+3
                        EnsureCarePet()
                    end
                    local PetBefore=State.AdoptObservedPet
                    local PetNow=Inventory.EquippedPet()
                    if PetBefore~=PetNow then
                        State.AdoptObservedPet=PetNow
                        State.AdoptPreviousTasks={}
                        State.AdoptTaskScanReady=false
                        State.AdoptLastTaskScanAt=-math.huge
                        FinishQueuedTask()
                    end
                    local Active=API.ActiveTasks(false,ForceScan==true)
                    if not State.AdoptTaskSourceReady then SetStatus(State.AdoptTaskSource); return false end
                    UpdateCompletions(Active)
                    local Queue,ActiveSet=RefreshTaskQueue(Active)
                    if State.AdoptLockedTask and not ActiveSet[State.AdoptLockedTask] then
                        local MissingName=State.AdoptLockedTask
                        local Candidate=State.AdoptCompletionCandidate
                        if Candidate~=MissingName then
                            State.AdoptCompletionCandidate=MissingName
                            State.AdoptCompletionCandidateAt=os.clock()
                            State.AdoptTaskDirty=true
                            SetStatus("Confirming "..MissingName.." completed")
                            return true
                        end
                        if os.clock()-(tonumber(State.AdoptCompletionCandidateAt) or 0)<0.12 then return true end
                        local Confirm=API.ActiveTasks(true,true)
                        if table.find(Confirm,MissingName) then
                            State.AdoptCompletionCandidate=nil
                            return true
                        end
                        State.AdoptCompletionCandidate=nil
                        SetStatus("Finished "..MissingName.." • choosing the next need")
                        FinishQueuedTask()
                        Queue=State.AdoptTaskQueue
                    else
                        State.AdoptCompletionCandidate=nil
                    end
                    if #Active==0 then
                        FinishQueuedTask()
                        SetStatus("All care tasks finished • waiting for the next one")
                        return false
                    end
                    local Name=State.AdoptLockedTask
                    if not Name then
                        for _,Candidate in ipairs(Queue) do
                            if os.clock()>=(State.AdoptDeferredTasks and State.AdoptDeferredTasks[Candidate] or 0) then Name=Candidate; break end
                        end
                        if Name then BeginQueuedTask(Name); State.AdoptTaskRetried=false end
                    end
                    if not Name then SetStatus("Waiting for the next supported care task"); return false end
                    local Record=State.AdoptAilmentRecords and State.AdoptAilmentRecords[Name]
                    local OwnerKey=Record and (Record.Target..":"..tostring(Record.PetUnique or "")) or ""
                    if State.AdoptTaskOwnerKey~=OwnerKey then
                        State.AdoptTaskOwnerKey=OwnerKey; State.AdoptTaskNextActionAt=0
                        State.AdoptTaskRetried=false; State.AdoptTaskLastProgressAt=os.clock()
                    end
                    local Progress=Record and Record.Progress or nil
                    if Progress~=nil and Progress~=(State.AdoptTaskProgress) then
                        State.AdoptTaskProgress=Progress
                        State.AdoptTaskLastProgressAt=os.clock()
                    end
                    if Record and Record.Target=="baby" then
                        if os.clock()<(State.AdoptNextRoleCheck or 0) then return false end
                        if not API.Team("Babies") then State.AdoptNextRoleCheck=os.clock()+3; return false end
                    elseif not EnsureCarePet() then
                        SetStatus("Waiting for a confirmed equipped owned pet"); return false
                    end
                    if os.clock()-(tonumber(State.AdoptTaskLastProgressAt) or os.clock())>=16 then
                        if not State.AdoptTaskRetried then
                            State.AdoptTaskRetried=true
                            State.AdoptTaskLastProgressAt=os.clock()
                            State.AdoptTaskNextActionAt=0
                            State.AdoptDoorCache={}; State.AdoptGatewayCache=nil; State.AdoptConfirmedInterior=nil
                            State.AdoptTaskScanReady=false; State.AdoptLastTaskScanAt=-math.huge; State.AdoptCachedAilmentRecords={}
                            if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                            SetStatus(Name.." stalled • rescanning the live need and route")
                        else
                            State.AdoptDeferredTasks=State.AdoptDeferredTasks or {}
                            State.AdoptDeferredTasks[Name]=os.clock()+30
                            FinishQueuedTask()
                            SetStatus(Name.." stalled twice • checking other needs")
                            return false
                        end
                    end
                    if os.clock()<(tonumber(State.AdoptTaskNextActionAt) or 0) then
                        local Percent=Progress and (" • "..math.floor(math.clamp(Progress,0,1)*100).."%") or ""
                        SetStatus("Working on "..Name..Percent.." • next: "..tostring(Queue[2] or "wait"))
                        return true
                    end
                    State.AdoptLastTaskAction=os.clock()

                    State.AdoptTaskNextActionAt=os.clock()+3

                    if UseOwnedItem(Name) then
                        State.AdoptTaskNextActionAt=os.clock()+15
                        SetStatus("Working on "..Name.." with an owned item"); return true
                    end
                    if Name=="walk" or Name=="ride" then
                        State.AdoptTaskNextActionAt=os.clock()+1
                        SetStatus("Working on "..Name.." movement"); return MovementNeed(Name)
                    end
                    if Name=="choose" and ActivateVisibleGui({"choose","pick","select"}) then
                        SetStatus("Waiting for the choice need to complete"); return true
                    end
                    local Location=NeedLocations[Name]
                    if Location then
                        if not API.Location(Location,true) then
                            State.AdoptTaskNextActionAt=os.clock()+3
                            return false
                        end
                        Runtime.Movement.Guard()
                    end
                    -- The readable pet-farm source uses exact generic_shower /
                    -- generic_crib furniture IDs. Prefer those when they are actually loaded,
                    -- then fall back to BananiHub's live prompt/keyword discovery.
                    local SourceFurniture=AdoptSourceFurnitureTarget(Name)
                    if SourceFurniture then
                        ShowTaskHighlight(SourceFurniture)
                        SetStatus("Working on "..Name.." with verified furniture")
                        if not MoveTo(SourceFurniture,CFrame.new(0,2,3)) then
                            State.AdoptTaskNextActionAt=os.clock()+1
                            return false
                        end
                        Runtime.Movement.Guard()
                        if UseCareAction(Name,SourceFurniture) then
                            State.AdoptTaskNextActionAt=os.clock()+15
                            return true
                        end
                    end

                    local Prompt=FindPromptByKeywords(Tasks[Name])
                    if Prompt then
                        local Target=Prompt:FindFirstAncestorOfClass("Model") or Prompt.Parent
                        ShowTaskHighlight(Target); SetStatus("Working on "..Name.." at its station")
                        if not UsePrompt(Prompt,true) then State.AdoptTaskNextActionAt=os.clock()+1; return false end
                        Runtime.Movement.Guard()
                        if UseCareAction(Name,Target) then State.AdoptTaskNextActionAt=os.clock()+15 end
                        return true
                    end
                    local Target=FindWorldTarget(Tasks[Name])
                    if Target then
                        ShowTaskHighlight(Target); SetStatus("Working on "..Name.." at its station")
                        if not MoveTo(Target,CFrame.new(0,2,3)) then State.AdoptTaskNextActionAt=os.clock()+1; return false end
                        Runtime.Movement.Guard()
                        task.wait(0.08)
                        Runtime.Movement.Guard()
                        if UseCareAction(Name,Target) then State.AdoptTaskNextActionAt=os.clock()+15 end
                        return true
                    end
                    if Location then
                        State.AdoptTaskNextActionAt=os.clock()+3
                        SetStatus("At "..Location.." • watching local "..Name.." progress")
                        return true
                    end
                    State.AdoptTaskNextActionAt=os.clock()+3
                    SetStatus(Name.." is active • waiting for its station to load")
                    return false
                end
                function API.Team(Team)
                    local Wanted=Team=="Babies" and "Babies" or "Parents"
                    local function CorrectRole()
                        local Terms=Wanted=="Babies" and {"baby","babies"} or {"parent","parents"}
                        local CharacterNow=Character()
                        local Values=table.pack(Player.Team and Player.Team.Name,Player:GetAttribute("Role"),Player:GetAttribute("Team"),Player:GetAttribute("team"),
                            Player:GetAttribute("IsBaby"),Player:GetAttribute("is_baby"),
                            CharacterNow and CharacterNow:GetAttribute("Role"),CharacterNow and CharacterNow:GetAttribute("Team"),
                            CharacterNow and CharacterNow:GetAttribute("IsBaby"),CharacterNow and CharacterNow:GetAttribute("is_baby"))
                        for Index=1,Values.n do
                            local Value=Values[Index]
                            if type(Value)=="boolean" then
                                if (Wanted=="Babies" and Value) or (Wanted=="Parents" and not Value) then return true end
                            end
                            local Text=string.lower(tostring(Value or ""))
                            for _,Term in ipairs(Terms) do if string.find(Text,Term,1,true) then return true end end
                        end
                        local ForceRead=os.clock()-(State.AdoptRoleReadAt or 0)>=0.30
                        if ForceRead then State.AdoptRoleReadAt=os.clock() end
                        local Data=Inventory.Read(ForceRead)
                        if type(Data)=="table" then
                            for _,Key in ipairs({"team","role","player_role","player_type","is_baby"}) do
                                local Value=Data[Key]
                                if Key=="is_baby" and (type(Value)=="boolean" or tonumber(Value)~=nil) then
                                    local IsBaby=(type(Value)=="boolean" and Value) or tonumber(Value)==1
                                    if (Wanted=="Babies" and IsBaby) or (Wanted=="Parents" and not IsBaby) then return true end
                                else
                                    local Text=string.lower(tostring(Value or ""))
                                    for _,Term in ipairs(Terms) do if string.find(Text,Term,1,true) then return true end end
                                end
                            end
                        end
                        return false
                    end
                    local function ClickRoleButton()
                        local PG=Player:FindFirstChildOfClass("PlayerGui")
                        if not PG then return false end
                        local Terms=Wanted=="Babies"
                            and {"switch to baby","play as baby","become baby","baby","babies"}
                            or {"switch to parent","play as parent","become parent","parent","parents"}
                        local Candidates={}
                        local function VisibleInTree(Gui)
                            local Node=Gui
                            while Node and Node~=PG do
                                if Node:IsA("GuiObject") and not Node.Visible then return false end
                                if Node:IsA("ScreenGui") and not Node.Enabled then return false end
                                Node=Node.Parent
                            end
                            return Node==PG
                        end
                        for _,Gui in ipairs(PG:GetDescendants()) do
                            if Gui:IsA("GuiButton") and VisibleInTree(Gui) then
                                local Text=TextOfGui(Gui)
                                local Path=string.lower(Gui:GetFullName())
                                local Match=false; local Score=0
                                for Index,Term in ipairs(Terms) do
                                    if string.find(Text,string.lower(Term),1,true) then
                                        Match=true; Score=Score+(#Terms-Index+1)*2
                                        if Text==string.lower(Term) or Text==string.lower(Term).." role" then Score+=40 end
                                    end
                                end
                                if Match and (string.find(Path,"role",1,true) or string.find(Path,"dress",1,true)
                                    or string.find(Path,"avatar",1,true) or Score>=40) then
                                    if string.find(Path,"role",1,true) or string.find(Path,"dress",1,true)
                                        or string.find(Path,"avatar",1,true) then Score+=25 end
                                    table.insert(Candidates,{Gui=Gui,Score=Score})
                                end
                            end
                        end
                        table.sort(Candidates,function(A,B) return A.Score>B.Score end)
                        for _,Candidate in ipairs(Candidates) do
                            local Gui=Candidate.Gui
                            local Fired=false
                            if type(firesignal)=="function" then
                                Fired=pcall(function() firesignal(Gui.Activated) end)
                                if not Fired and Gui:IsA("TextButton") then Fired=pcall(function() firesignal(Gui.MouseButton1Click) end) end
                            end
                            if not Fired then
                                local Ok,VIM=pcall(function() return game:GetService("VirtualInputManager") end)
                                if Ok and VIM then
                                    local P=Gui.AbsolutePosition+Gui.AbsoluteSize/2
                                    Fired=pcall(function()
                                        VIM:SendMouseButtonEvent(P.X,P.Y,0,true,game,0)
                                        task.wait(0.03)
                                        VIM:SendMouseButtonEvent(P.X,P.Y,0,false,game,0)
                                    end)
                                end
                            end
                            if Fired then return true end
                        end
                        return false
                    end
                    if CorrectRole() then SetStatus("Already playing as "..Wanted); return true end

                    ActivateVisibleGui({"dress up"})
                    task.wait(0.2)
                    if ClickRoleButton() then
                        local Deadline=os.clock()+2
                        repeat
                            if CorrectRole() then SetStatus("Role changed to "..Wanted); return true end
                            task.wait(0.1)
                        until os.clock()>=Deadline
                    end
                    local Singular=Wanted=="Babies" and "Baby" or "Parent"
                    local Ok=false
                    for _,RemoteName in ipairs({"TeamAPI/ChooseTeam","TeamAPI/SetTeam","AvatarAPI/SetTeam"}) do
                        local Remotes=FindRemotes({RemoteName})
                        for _,Remote in ipairs(Remotes) do
                            for _,Args in ipairs({{Wanted,true},{Wanted},{Singular,true},{Singular},{string.lower(Wanted)}}) do
                                CallRemote(Remote,table.unpack(Args))
                                local Deadline=os.clock()+0.50
                                repeat task.wait(0.05) until CorrectRole() or os.clock()>=Deadline
                                if CorrectRole() then Ok=true break end
                            end
                            if Ok then break end
                        end
                        if Ok then break end
                    end
                    if not Ok then

                        ActivateVisibleGui({"dress up","avatar","edit avatar","customize"})
                        task.wait(0.25)
                        ActivateVisibleGui({"switch role","choose role","change role","role"})
                        task.wait(0.20)
                        ClickRoleButton()
                        local Deadline=os.clock()+1.25
                        repeat task.wait(0.05) until CorrectRole() or os.clock()>=Deadline
                        Ok=CorrectRole()
                    end
                    if not Ok then

                        local Prompt=FindPromptByKeywords({"age-o-matic","ageomatic"})
                        if Prompt and UsePrompt(Prompt,true) then
                            task.wait(0.35)
                            ClickRoleButton()
                            local Deadline=os.clock()+1.25
                            repeat task.wait(0.05) until CorrectRole() or os.clock()>=Deadline
                            Ok=CorrectRole()
                        end
                    end
                    SetStatus(Ok and ("Role changed to "..Wanted) or ("Could not change role • open the role picker once"))
                    return Ok
                end
                local MainMapLocations={["Pool Party"]=true,Nursery=true,School=true,Hospital=true,["Hot Springs"]=true,["Pizza Place"]=true,Salon=true,["Ice Cream Shop"]=true,Supermarket=true,Playground=true,Camping=true,["Pet Shop"]=true,["Toy Shop"]=true,["Baby Shop"]=true,["Vehicle Dealership"]=true,["Safety Hub"]=true,["Trading License"]=true,["Sky Castle"]=true,Beach=true,["Pet Pen"]=true}
                local function AdoptGroundPoint(Position,Extra)
                    if typeof(Position)~="Vector3" then return nil end
                    local Params=RaycastParams.new()
                    Params.FilterType=Enum.RaycastFilterType.Exclude
                    local Filters={}
                    local C=Character()
                    if C then table.insert(Filters,C) end
                    if Extra then table.insert(Filters,Extra) end
                    Params.FilterDescendantsInstances=Filters
                    Params.IgnoreWater=true
                    Params.RespectCanCollide=true
                    local Hit=workspace:Raycast(Position+Vector3.new(0,4,0),Vector3.new(0,-40,0),Params)
                    local Fallen=tonumber(workspace.FallenPartsDestroyHeight) or -500
                    if Hit and Hit.Instance and Hit.Instance.CanCollide and Hit.Normal.Y>0.65 and Hit.Position.Y>Fallen+20 then
                        return Hit.Position+Vector3.new(0,3.1,0)
                    end
                    return nil
                end
                local function FrontCFrame(Object,Distance)
                    local Part=GetRoot(Object)
                    if not Part then return nil end
                    local Offset=tonumber(Distance) or 6

                    local Normal
                    if Part.Size.X>=Part.Size.Z then Normal=Part.CFrame.LookVector else Normal=Part.CFrame.RightVector end
                    local Flat=Vector3.new(Normal.X,0,Normal.Z)
                    if Flat.Magnitude<0.05 then Flat=Vector3.new(0,0,-1) end
                    Flat=Flat.Unit
                    local A=Part.Position+Flat*Offset
                    local B=Part.Position-Flat*Offset
                    local Me=Root()
                    local Position=(Me and (Me.Position-A).Magnitude<=(Me.Position-B).Magnitude) and A or B
                    Position=AdoptGroundPoint(Position,Part)
                    if not Position then return nil end
                    return CFrame.lookAt(Position,Part.Position+Vector3.new(0,2,0))
                end
                local function FindLocationDoor(Name,Info)
                    State.AdoptDoorCache=State.AdoptDoorCache or {}
                    local Cached=State.AdoptDoorCache[Name]
                    if Cached and Cached.Object and Cached.Object.Parent and os.clock()-Cached.At<0.50 then return Cached.Object end
                    local Me=Root(); local Best,BestScore,BestDistance=nil,-math.huge,math.huge
                    local Terms=Info.World or {Name}
                    local function Anchor(Object)
                        if not Object or not Object.Parent then return nil,0 end
                        if Object:IsA("BasePart") then
                            if MatchKeywords(Object.Name,{"door","entrance","entry","teleport"}) then return Object,30 end
                            return nil,0
                        end
                        local Prompt=Object:FindFirstChildWhichIsA("ProximityPrompt",true)
                        if Prompt and Prompt.Parent then
                            local PromptPart=GetRoot(Prompt.Parent)
                            if PromptPart and PromptPart:IsA("BasePart") then return PromptPart,31 end
                        end
                        for _,PartName in ipairs({"MainDoor","FrontDoor","Entrance","Entry","Door","Teleport","TeleportPart"}) do
                            local Part=Object:FindFirstChild(PartName,true)
                            if Part and Part:IsA("BasePart") then return Part,30 end
                        end
                        return GetRoot(Object),4
                    end
                    local Scanned=0
                    for _,Object in ipairs(Runtime.ProfileTargets()) do
                        Scanned+=1; if Scanned>30000 then break end
                        if Object:IsA("Model") or Object:IsA("BasePart") then
                            local Path=string.lower(Object:GetFullName())
                            local ObjectName=string.lower(Object.Name)
                            local LocationMatch=false
                            for _,Term in ipairs(Terms) do
                                if string.find(Path,string.lower(Term),1,true) then LocationMatch=true; break end
                            end
                            if LocationMatch then
                                local Candidate,AnchorScore=Anchor(Object)
                                local R=Candidate and GetRoot(Candidate)
                                if R then
                                    local IsDoor=string.find(ObjectName,"maindoor",1,true) or string.find(ObjectName,"frontdoor",1,true)
                                        or string.find(ObjectName,"entrance",1,true) or ObjectName=="door"
                                    local Score=AnchorScore+(IsDoor and 12 or 0)
                                    if string.find(Path,"interior",1,true) or string.find(Path,"inside",1,true) then Score-=18 end
                                    if string.find(Path,"mainmap",1,true) or string.find(Path,"neighborhood",1,true) then Score+=4 end
                                    local Distance=Me and R and (Me.Position-R.Position).Magnitude or 0
                                    if Score>BestScore or (Score==BestScore and Distance<BestDistance) then
                                        Best,BestScore,BestDistance=Candidate,Score,Distance
                                    end
                                end
                            end
                        end
                    end
                    State.AdoptDoorCache[Name]={Object=Best,At=os.clock()}
                    return Best
                end
                local function FindMainMapGateway()
                    local Cached=State.AdoptGatewayCache
                    if Cached and Cached.Object and Cached.Object.Parent and os.clock()-Cached.At<0.50 then return Cached.Object end
                    local function GatewayPart(Object)
                        if not Object or not Object.Parent then return nil end
                        if Object:IsA("BasePart") then return Object end
                        for _,Name in ipairs({"Entrance","Entry","Trigger","BridgeEntrance","TunnelEntrance","MainDoor","Door","Teleport","TeleportPart","Exit"}) do
                            local Part=Object:FindFirstChild(Name,true)
                            if Part and Part:IsA("BasePart") then return Part end
                        end
                        local Prompt=Object:FindFirstChildWhichIsA("ProximityPrompt",true)
                        if Prompt and Prompt.Parent then
                            local Part=GetRoot(Prompt.Parent)
                            if Part and Part:IsA("BasePart") then return Part end
                        end

                        if Object:IsA("Model") then
                            local Ok,BoxCF,BoxSize=pcall(function() return Object:GetBoundingBox() end)
                            if Ok and BoxCF and BoxSize then
                                local Axis=(BoxSize.X>=BoxSize.Z) and BoxCF.RightVector or BoxCF.LookVector
                                local Half=(BoxSize.X>=BoxSize.Z) and BoxSize.X/2 or BoxSize.Z/2
                                local Me=Root(); local Sign=1
                                if Me and (Me.Position-BoxCF.Position):Dot(Axis)<0 then Sign=-1 end
                                local Endpoint=BoxCF.Position+Axis*Sign*math.max(0,Half-3)
                                local Best,Distance=nil,math.huge
                                for _,Part in ipairs(Object:GetDescendants()) do
                                    if Part:IsA("BasePart") then
                                        local D=(Part.Position-Endpoint).Magnitude
                                        if D<Distance then Best,Distance=Part,D end
                                    end
                                end
                                if Best then return Best end
                            end
                        end
                        return GetRoot(Object)
                    end
                    local Me=Root(); local Best,BestScore,BestDistance=nil,-math.huge,math.huge
                    local Scanned=0
                    for _,Object in ipairs(Runtime.ProfileTargets()) do
                        Scanned+=1; if Scanned>30000 then break end
                        if Object:IsA("Model") or Object:IsA("BasePart") then
                            local Name=string.lower(Object.Name); local Path=string.lower(Object:GetFullName())
                            local Score=0
                            if string.find(Name,"bridge",1,true) then Score=30
                            elseif string.find(Name,"tunnel",1,true) then Score=25
                            elseif string.find(Path,"neighborhood",1,true) and string.find(Name,"maindoor",1,true) then Score=22
                            elseif string.find(Name,"mainmap",1,true) or string.find(Name,"neighborhoodexit",1,true) then Score=20 end
                            local Candidate=Score>0 and GatewayPart(Object)
                            local R=Candidate and GetRoot(Candidate)
                            if R then
                                local Distance=Me and (Me.Position-R.Position).Magnitude or 0
                                if Score>BestScore or (Score==BestScore and Distance<BestDistance) then Best,BestScore,BestDistance=Candidate,Score,Distance end
                            end
                        end
                    end
                    State.AdoptGatewayCache={Object=Best,At=os.clock()}
                    return Best
                end
                local function CrossPhysicalGateway(Gateway)
                    if not Gateway or not Gateway.Parent then return false end
                    local Model=Gateway:FindFirstAncestorOfClass("Model")
                    while Model and Model~=workspace and not MatchKeywords(Model.Name,{"bridge","tunnel","gateway","main map"}) do
                        Model=Model:FindFirstAncestorOfClass("Model")
                    end
                    if not Model or Model==workspace then return false end
                    if Gateway:FindFirstChildWhichIsA("ProximityPrompt",true) then return false end
                    local Ok,BoxCF,BoxSize=pcall(function() return Model:GetBoundingBox() end)
                    if not Ok or not BoxCF or not BoxSize then return false end
                    local Axis=(BoxSize.X>=BoxSize.Z) and BoxCF.RightVector or BoxCF.LookVector
                    local Half=(BoxSize.X>=BoxSize.Z) and BoxSize.X/2 or BoxSize.Z/2
                    if Half<10 then return false end
                    local Me=Root(); if not Me then return false end
                    local Sign=((Me.Position-BoxCF.Position):Dot(Axis)>=0) and 1 or -1
                    local Entry=BoxCF.Position+Axis*Sign*math.max(2,Half-5)
                    local Exit=BoxCF.Position-Axis*Sign*math.max(2,Half-5)

                    local GroundEntry=AdoptGroundPoint(Entry,Gateway)
                    local GroundExit=AdoptGroundPoint(Exit,Gateway)
                    local GroundMid=AdoptGroundPoint(BoxCF.Position,Gateway)
                    if not GroundEntry or not GroundExit or not GroundMid then return false end
                    Entry=GroundEntry
                    Exit=GroundExit
                    local Mid=GroundMid
                    if not Runtime.ProfileSmartTravel(CFrame.lookAt(Entry,Mid),nil,{Mode="Walk",Source="AdoptGateway"}) then return false end
                    local Current=Root()
                    if not Current then return false end
                    if (Current.Position-Mid).Magnitude>4 and not Runtime.ProfileSmartTravel(CFrame.lookAt(Mid,Exit),nil,{Mode="Walk",Source="AdoptGateway"}) then return false end
                    if not Runtime.ProfileSmartTravel(CFrame.lookAt(Exit,Mid),nil,{Mode="Walk",Source="AdoptGateway"}) then return false end
                    task.wait(0.5)
                    Runtime.Movement.Guard()
                    local After=Root()
                    if not After then return false end

                    return (After.Position-Exit).Magnitude<=6
                        and (After.Position-BoxCF.Position):Dot(Axis)*Sign<0
                end
                local function RemoteLocation(Name,Info)
                    local Variants={}
                    if Name=="Home" then
                        table.insert(Variants,{"housing","MainDoor",{house_owner=Player}})
                        table.insert(Variants,{"housing","MainDoor",{house_owner=Player.Name}})
                    end
                    for _,RemoteName in ipairs(Info.Remote or {Name}) do
                        table.insert(Variants,{RemoteName,"MainDoor",{}})
                        table.insert(Variants,{RemoteName,"MainDoor"})
                        table.insert(Variants,{RemoteName})
                    end
                    return TryRemote({"LocationAPI/SetLocation","LocationAPI/Teleport","InteriorsAPI/EnterInterior"},Variants)
                end
                function API.Location(Name,EnterInterior)
                    Runtime.Movement.Guard()
                    local Info=LocationInfo[Name] or {World={Name},Remote={Name}}
                    local Me=Root()
                    local Last=State.AdoptConfirmedInterior
                    if EnterInterior and Last and Last.Name==Name and Last.Character==Character()
                        and Me and (Me.Position-Last.Position).Magnitude<80 then return true end
                    local Door=FindLocationDoor(Name,Info)
                    local DoorRoot=Door and GetRoot(Door)
                    local NeedMainMapCross=MainMapLocations[Name] and not DoorRoot
                    if NeedMainMapCross and os.clock()-(Runtime.AdoptGatewayLastCross or -math.huge)<6 then
                        SetStatus("Waiting for the main-map gateway cooldown")
                        return false
                    end
                    if NeedMainMapCross then
                        local Gateway=FindMainMapGateway()
                        if Gateway then
                            SetStatus("Entering Main Map")
                            local Crossed=CrossPhysicalGateway(Gateway)
                            if not Crossed then
                                Crossed=Runtime.EnterThrough("AdoptMainMap",Gateway,FrontCFrame(Gateway,6))
                            end
                            if Crossed then
                                Runtime.AdoptGatewayLastCross=os.clock()
                                State.AdoptDoorCache={}; State.AdoptGatewayCache=nil
                                Door=FindLocationDoor(Name,Info)
                            else
                                SetStatus("Main Map crossing was not confirmed")
                                return false
                            end
                        else
                            SetStatus("Main Map bridge/tunnel is not loaded")
                            return false
                        end
                    end
                    local FixedGoal=FixedLocationEntrances[Name]
                    if not Door and FixedGoal then
                        SetStatus("Traveling to the saved center of "..Name.." entrance")
                        if not ProfileTravelToCFrame(FixedGoal) then return false end
                        if not EnterInterior then return true end
                        if RemoteLocation(Name,Info) then
                            task.wait(0.55)
                            local Here=Root()
                            State.AdoptConfirmedInterior={Name=Name,Character=Character(),Position=Here and Here.Position or Vector3.zero}
                            State.AdoptDoorCache={}; State.AdoptGatewayCache=nil
                            return true
                        end
                        SetStatus(Name.." entrance is not loaded")
                        return false
                    end
                    if not Door then SetStatus(Name.." entrance is not loaded"); return false end
                    local Goal=FrontCFrame(Door,6)

                    if Name=="Pizza Place" and FixedGoal then
                        local DR=GetRoot(Door)
                        if not DR or (DR.Position-FixedGoal.Position).Magnitude<120 then
                            Goal=CFrame.lookAt(FixedGoal.Position,(DR and DR.Position or FixedGoal.Position+Vector3.new(0,0,-1))+Vector3.new(0,2,0))
                        end
                    end
                    if not EnterInterior then return Goal and ProfileTravelToCFrame(Goal) or false end

                    local Outdoor={["Pool Party"]=true,Camping=true,Playground=true,["Hot Springs"]=true,Beach=true,["Pet Pen"]=true}
                    if Outdoor[Name] then
                        local Reached=Goal and ProfileTravelToCFrame(Goal) or false
                        Me=Root()
                        if Reached and Me then
                            State.AdoptConfirmedInterior={Name=Name,Character=Character(),Position=Me.Position}
                        end
                        return Reached
                    end
                    SetStatus("Entering "..Name)
                    local Ok=Runtime.EnterThrough("Adopt:"..Name,Door,Goal,function() RemoteLocation(Name,Info) end)
                    if not Ok then SetStatus(Name.." entrance transition was not confirmed"); return false end
                    State.AdoptDoorCache={}; State.AdoptGatewayCache=nil
                    Me=Root()
                    State.AdoptConfirmedInterior={Name=Name,Character=Character(),Position=Me and Me.Position or Vector3.zero}
                    local Need=State.AdoptLockedTask
                    local Target=Need and FindWorldTarget(Tasks[Need])
                    if Target then return MoveTo(Target,CFrame.new(0,2,3)) end
                    return true
                end
                function API.ClaimAutomation(Selected)

                    local Controllers={
                        AdoptSmartFarm="GameProfile_Adopt_SmartFarm", AdoptWork="GameProfile_Adopt_Work",
                        AdoptPetPen="GameProfile_Adopt_PetPen", AdoptLures="GameProfile_Adopt_Lures",
                        AdoptActivity="GameProfile_Adopt_Activity", AdoptEvent="GameProfile_Adopt_Event",
                    }
                    for Loop,Flag in pairs(Controllers) do
                        if Loop~=Selected then
                            StopLoop(Loop)
                            Runtime.SetFlagValue(Flag,false)
                        end
                    end
                    State.AdoptActiveJob=nil
                    if Runtime.CancelTravel then Runtime.CancelTravel() end
                end
                function API.StartSmartFarm()
                    API.ClaimAutomation("AdoptSmartFarm")
                    StopLoop("AdoptSmartFarm")
                    if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                    Inventory.Names(true)
                    State.AdoptLockedTask=nil; State.AdoptLockedTaskSince=0; State.AdoptLastTaskAction=0
                    State.AdoptTaskQueue={}; State.AdoptTaskProgress=nil; State.AdoptTaskNextActionAt=0
                    State.AdoptTaskLastProgressAt=os.clock()
                    State.AdoptTaskScanReady=false
                    State.AdoptTaskDirty=true
                    State.AdoptLastTaskScanAt=-math.huge
                    State.AdoptCachedAilmentRecords={}
                    State.AdoptPreviousTasks={}
                    EnsureCarePet()
                    if State.AdoptFarmMode=="Baby Only" or State.AdoptFarmMode=="Pet + Baby" then API.Team("Babies") else API.Team("Parents") end
                    SetStatus("Smart Care started • scanning needs")
                    StartLoop("AdoptSmartFarm",API.TaskStep,function() return math.max(0.5,State.AdoptTaskDelay) end)
                end
                function API.ClaimRewards()
                    -- Source-backed paycheck path. Do not assume it exists: current game
                    -- builds can move/replace APIs, so visible reward UI remains the fallback.
                    local CashOut=TryRemote({"PayAPI/CashOut"},{{}})
                    local Visible=ActivateVisibleGui({"claim","daily reward","star reward","achievement","delivery","handout","reward","paycheck"})
                    return CashOut or Visible
                end
                function API.CollectEvent()
                    local Me=Root(); if not Me then return false end
                    local Best,Dist=nil,math.huge
                    for _,Obj in ipairs(Runtime.ProfileTargets()) do
                        if (Obj:IsA("BasePart") or Obj:IsA("Model")) and MatchKeywords(Obj.Name,{"gingerbread","candy","eventcurrency","token","collectible","firefly"}) then
                            local M=Obj:IsA("Model") and Obj or Obj:FindFirstAncestorOfClass("Model")
                            local R=GetRoot(Obj)
                            if R and not (M and IsPlayerCharacter(M)) then
                                local D=(Me.Position-R.Position).Magnitude
                                if D<Dist and D<=(tonumber(State.AdoptCollectRadius) or 250) then Best,Dist=Obj,D end
                            end
                        end
                    end
                    if Best then TouchObject(Best); SetStatus("Collecting nearby event item"); return true end
                    return false
                end
                function API.WorkStep()
                    Runtime.Movement.Guard()
                    local Keys=JobKeys[State.AdoptWorkJob] or {string.lower(tostring(State.AdoptWorkJob or "work"))}
                    if State.AdoptActiveJob~=State.AdoptWorkJob then
                        local WaitingForVerify=(os.clock()-(tonumber(State.AdoptJobStartRequestedAt) or -math.huge))<2.5
                        if not WaitingForVerify then
                            local Location=JobLocations[State.AdoptWorkJob] or State.AdoptWorkJob
                            if not API.Location(Location,true) then
                                SetStatus("Waiting at the real "..tostring(Location).." entrance")
                                return false
                            end
                            Runtime.Movement.Guard()
                            local Variants={}
                            for _,Id in ipairs(JobIds[State.AdoptWorkJob] or {State.AdoptWorkJob}) do
                                table.insert(Variants,{Id}); table.insert(Variants,{Id,true})
                            end
                            local Started=TryRemote({"JobAPI/StartJob","JobsAPI/StartJob","JobAPI/SetJob","JobAPI/SetCurrentJob","JobAPI/ChooseJob","JobAPI/StartShift","JobAPI/StartWorking","WorkAPI/StartJob"},Variants)
                            if not Started then
                                ActivateVisibleGui({"start shift","start job","work here"})
                            end
                            -- Do not mark the job active from a remote return alone. A live work
                            -- prompt/target below confirms the state change.
                            State.AdoptJobStartRequestedAt=os.clock()
                        else
                            SetStatus("Verifying "..tostring(State.AdoptWorkJob).." job state")
                        end
                    end
                    local P=FindPromptByKeywords(Keys)
                    if P then
                        State.AdoptJobStallCount=0; State.AdoptActiveJob=State.AdoptWorkJob
                        SetStatus("Working at "..tostring(State.AdoptWorkJob)); UsePrompt(P,true); return true
                    end
                    local T=FindWorldTarget(Keys)
                    if T then
                        State.AdoptJobStallCount=0
                        MoveTo(T,CFrame.new(0,2,3))
                    else
                        State.AdoptJobStallCount=(tonumber(State.AdoptJobStallCount) or 0)+1
                    end
                    Runtime.Movement.Guard()
                    local Clicked=ActivateVisibleGui({"start shift","work here","next order","serve","done","complete"})
                    if Clicked then State.AdoptJobStallCount=0 end
                    if not Clicked and State.AdoptJobStallCount>=4 then
                        State.AdoptJobStallCount=0
                        State.AdoptActiveJob=nil
                        State.AdoptDoorCache={}; State.AdoptGatewayCache=nil; State.AdoptConfirmedInterior=nil
                        if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                        SetStatus("Job station was not found • re-entering "..tostring(State.AdoptWorkJob))
                        return false
                    end
                    SetStatus(Clicked and ("Working at "..tostring(State.AdoptWorkJob)) or ("Waiting for a "..tostring(State.AdoptWorkJob).." work prompt"))
                    return Clicked
                end
                function API.SafeSpot(On)
                    if not On then
                        if State.AdoptSafePlatform then pcall(function() State.AdoptSafePlatform:Destroy() end) end
                        State.AdoptSafePlatform=nil; return
                    end
                    local R=Root(); if not R then return end
                    if not State.AdoptSafePlatform or not State.AdoptSafePlatform.Parent then
                        local P=Runtime.TrackTransient(Instance.new("Part"),"TransientParts")
                        P.Name="BananiHub_AdoptSafeSpot"; P.Anchored=true; P.CanCollide=true; P.Transparency=0.35
                        P.Color=Color3.fromRGB(255,220,35); P.Size=Vector3.new(28,1,28)
                        P.CFrame=CFrame.new(R.Position+Vector3.new(0,90,0)); P.Parent=workspace; State.AdoptSafePlatform=P
                    end
                    ProfileTravelToCFrame(State.AdoptSafePlatform.CFrame*CFrame.new(0,3,0))
                end
                function API.PromptStep(Keys,Label)
                    local P=FindPromptByKeywords(Keys)
                    if P then SetStatus(Label); UsePrompt(P,true); return true end
                    local T=FindWorldTarget(Keys)
                    if T then ShowTaskHighlight(T); SetStatus("Traveling: "..Label); MoveTo(T,CFrame.new(0,2,3)); return true end
                    return false
                end
                local function IsPet(Model)
                    if not Model:IsA("Model") or IsPlayerCharacter(Model) then return false end
                    local ParentName=Model.Parent and string.lower(Model.Parent.Name) or ""
                    if string.find(ParentName,"pet",1,true) then return GetRoot(Model)~=nil end
                    for _,Key in ipairs({"pet_unique","pet_type","pet_id","owner","age","rarity"}) do
                        if Model:GetAttribute(Key)~=nil then return GetRoot(Model)~=nil end
                    end
                    return false
                end
                local function PetValue(Model,Keys,Fallback)
                    for _,Key in ipairs(Keys) do
                        local A=Model:GetAttribute(Key); if A~=nil and tostring(A)~="" then return tostring(A) end
                        local V=Model:FindFirstChild(Key,true)
                        if V and V:IsA("ValueBase") and tostring(V.Value)~="" then return tostring(V.Value) end
                    end
                    return Fallback
                end
                local function RemovePetRecord(Model)
                    local Rec=State.AdoptPetESPRecords[Model]
                    if Rec then for _,Obj in pairs(Rec) do pcall(function() Obj:Destroy() end) end end
                    State.AdoptPetESPRecords[Model]=nil
                end
                function API.ClearPetESP()
                    for Model in pairs(State.AdoptPetESPRecords or {}) do RemovePetRecord(Model) end
                    ClearTaskHighlight()
                end
                function API.UpdatePetESP()
                    if not State.AdoptPetESPEnabled then API.ClearPetESP(); return end
                    local Me=Root(); local Seen={}; if not Me then return end
                    for _,Model in ipairs(Runtime.ProfileTargets()) do
                        if IsPet(Model) then
                            local R=GetRoot(Model); local D=R and (Me.Position-R.Position).Magnitude or math.huge
                            if D<=(tonumber(State.AdoptPetESPRange) or 350) then
                                Seen[Model]=true
                                local Rec=State.AdoptPetESPRecords[Model]
                                if not Rec then
                                    local H=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
                                    H.Name="BananiHub_PetESP"; H.Adornee=Model; H.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                                    H.FillColor=Color3.fromRGB(255,205,25); H.OutlineColor=Color3.fromRGB(255,255,255)
                                    H.FillTransparency=0.18; H.OutlineTransparency=0; H.Parent=Model
                                    local B=Runtime.TrackTransient(Instance.new("BillboardGui"),"BillboardGuis")
                                    B.Name="BananiHub_PetLabel"; B.AlwaysOnTop=true; B.LightInfluence=0
                                    B.MaxDistance=tonumber(State.AdoptPetESPRange) or 350; B.Size=UDim2.fromOffset(220,54); B.StudsOffset=Vector3.new(0,3.5,0); B.Adornee=R; B.Parent=R
                                    local L=Instance.new("TextLabel")
                                    L.BackgroundColor3=Color3.fromRGB(12,12,14); L.BackgroundTransparency=0.12; L.BorderSizePixel=0
                                    L.Size=UDim2.fromScale(1,1); L.Font=Enum.Font.GothamBold; L.TextColor3=Color3.fromRGB(255,230,70)
                                    L.TextStrokeColor3=Color3.new(0,0,0); L.TextStrokeTransparency=0; L.TextScaled=false; L.TextSize=14; L.TextWrapped=true; L.Parent=B
                                    local C=Instance.new("UICorner"); C.CornerRadius=UDim.new(0,6); C.Parent=L
                                    Rec={Highlight=H,Billboard=B,Label=L}; State.AdoptPetESPRecords[Model]=Rec
                                end
                                Rec.Billboard.Adornee=R; Rec.Billboard.MaxDistance=tonumber(State.AdoptPetESPRange) or 350
                                local Age=PetValue(Model,{"age","Age","level","Level"},"?")
                                local Rarity=PetValue(Model,{"rarity","Rarity"},"Pet")
                                local Owner=PetValue(Model,{"owner","Owner","owner_name"},"")
                                Rec.Label.Text=string.format("✦ %s  [%s]\nAge %s%s  •  %dm",Model.Name,Rarity,Age,Owner~="" and "  •  "..Owner or "",math.floor(D+0.5))
                            end
                        end
                    end
                    for Model in pairs(State.AdoptPetESPRecords) do if not Seen[Model] or not Model.Parent then RemovePetRecord(Model) end end
                end
                function API.TradeAlertStep()
                    if not State.AdoptTradeAlerts then return end
                    local PG=Player:FindFirstChildOfClass("PlayerGui"); if not PG then return end
                    local Parts={}
                    for _,G in ipairs(PG:GetDescendants()) do
                        if (G:IsA("TextLabel") or G:IsA("TextButton")) and G.Visible then
                            local Screen=G:FindFirstAncestorOfClass("ScreenGui")
                            if Screen and string.find(string.lower(Screen.Name),"banani",1,true) then continue end
                            local Path=string.lower(G:GetFullName()); local Text=string.lower(tostring(G.Text or ""))
                            if string.find(Path,"trade",1,true) and Text~="" then table.insert(Parts,Text) end
                        end
                    end
                    table.sort(Parts); local Fingerprint=table.concat(Parts,"|")
                    if Fingerprint~="" and State.AdoptTradeFingerprint~="" and Fingerprint~=State.AdoptTradeFingerprint then
                        Notify("Adopt Me Trade","The visible trade offer changed. Recheck every item before accepting.")
                    end
                    State.AdoptTradeFingerprint=Fingerprint
                end
                function API.Stats(ForceScan)
                    local Active=API.ActiveTasks(true,ForceScan==true); local Minutes=math.floor((os.clock()-(tonumber(State.AdoptSessionStarted) or os.clock()))/60)
                    local Mode=tostring(State.AdoptFarmMode); local Action=tostring(State.AdoptCurrentAction or "Idle")
                    local Queue=State.AdoptTaskQueue or {}
                    local Progress=State.AdoptTaskProgress and (math.floor(math.clamp(State.AdoptTaskProgress,0,1)*100).."%") or "watching completion"
                    return "Mode: "..Mode
                        .."\nDetected: "..(#Active>0 and table.concat(Active," • ") or "None")
                        .."\nCurrent: "..tostring(State.AdoptLockedTask or "Waiting").." • "..Progress
                        .."\nQueue: "..(#Queue>0 and table.concat(Queue," → ") or "Empty")
                        .."\nSource: "..tostring(State.AdoptTaskSource or "Waiting")
                        .."\nAction: "..Action
                        .."\nInventory: "..tostring(State.AdoptInventoryStatus or "Not scanned")
                        .."\nSession: "..tostring(State.AdoptSessionNeeds or 0).." needs • "..Minutes.." min"
                end
                function API.Check()
                    local HasData=Inventory.Read(true)~=nil
                    local Names=Inventory.Names(false)
                    local PetUnique=Inventory.EquippedPet()
                    local HasTeam=FindRemote({"TeamAPI/ChooseTeam","TeamAPI/SetTeam","AvatarAPI/SetTeam"})~=nil
                    local HasLocation=FindRemote({"LocationAPI/SetLocation","LocationAPI/Teleport","InteriorsAPI/EnterInterior"})~=nil
                    local HasFurniture=FindRemote({"HousingAPI/ActivateFurniture","HousingAPI/ActivateInteriorFurniture","FurnitureAPI/ActivateFurniture"})~=nil
                    local HasJob=FindRemote({"JobAPI/StartJob","JobsAPI/StartJob","JobAPI/SetJob","JobAPI/SetCurrentJob","JobAPI/ChooseJob","JobAPI/StartShift","JobAPI/StartWorking","WorkAPI/StartJob"})~=nil
                    return "ClientData: "..(HasData and "Ready" or "Using UI fallback")
                        .."\nOwned entries: "..math.max(#Names-1,0)
                        .."\nEquipped care pet: "..(PetUnique and "Ready" or "None detected")
                        .."\nTeam action: "..(HasTeam and "Ready" or "UI fallback")
                        .."\nLocation action: "..(HasLocation and "Ready" or "world-object fallback")
                        .."\nFurniture care: "..(HasFurniture and "Ready" or "prompt fallback")
                        .."\nJob action: "..(HasJob and "Ready" or "prompt fallback")
                end
                function API.StopAll()
                    for _,Flag in ipairs({"GameProfile_Adopt_SmartFarm","GameProfile_Adopt_Work","GameProfile_Adopt_Rewards","GameProfile_Adopt_Event","GameProfile_Adopt_Gifts","GameProfile_Adopt_PetPen","GameProfile_Adopt_Lures","GameProfile_Adopt_Activity","GameProfile_Adopt_PetESP","GameProfile_Adopt_ItemESP","GameProfile_Adopt_TradeAlerts","GameProfile_Adopt_SafeSpot","GameProfile_Adopt_NearbyCare","GameProfile_Adopt_KeepSelected"}) do Runtime.SetFlagValue(Flag,false) end
                    for _,Loop in ipairs({"AdoptSmartFarm","AdoptWork","AdoptRewards","AdoptEvent","AdoptGifts","AdoptPetPen","AdoptLures","AdoptActivity","AdoptPetESP","AdoptTradeAlerts","AdoptNearbyCare","AdoptKeepSelected"}) do StopLoop(Loop) end
                    if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                    State.AdoptActiveJob=nil
                    State.AdoptLockedTask=nil; State.AdoptLockedTaskSince=0; State.AdoptLastTaskAction=0
                    State.AdoptTaskQueue={}; State.AdoptTaskProgress=nil; State.AdoptTaskNextActionAt=0
                    API.SafeSpot(false); API.ClearPetESP(); SetStatus("Stopped")
                end
                API.Locations=Locations; API.Tasks=Tasks; API.JobLocations=JobLocations
                API.InventoryNames=Inventory.Names; API.EquipInventory=Inventory.Equip; API.UseInventory=Inventory.Use; API.FindInventory=Inventory.Find
                API.EquippedPet=Inventory.EquippedPet; API.FirstCarePet=Inventory.FirstCarePet
                return API
            end)()
