-- [BH:BOAT] BUILD A BOAT PROFILE
-- Stage traversal, gold farm, treasure path and stage visuals.
-- ==================================================================
        elseif Kind == "BuildABoat" then
            -- Build A Boat For Treasure (root place 537413528 / universe 210851291).
            -- Public/current script references consistently expose workspace.BoatStages.NormalStages,
            -- CaveStage1..10/DarknessPart and TheEnd/GoldenChest/Trigger. Every lookup remains live and guarded.
            local function BoatNormalStages()
                local BoatStages=workspace:FindFirstChild("BoatStages")
                return BoatStages and BoatStages:FindFirstChild("NormalStages") or nil
            end
            local function BoatStagePart(Index)
                local Stages=BoatNormalStages()
                local Stage=Stages and Stages:FindFirstChild("CaveStage"..tostring(Index))
                if not Stage then return nil end
                return Stage:FindFirstChild("DarknessPart") or Stage:FindFirstChildWhichIsA("BasePart",true)
            end
            local function BoatEndTrigger()
                local Stages=BoatNormalStages()
                local TheEnd=Stages and Stages:FindFirstChild("TheEnd")
                local Chest=TheEnd and TheEnd:FindFirstChild("GoldenChest")
                return Chest and (Chest:FindFirstChild("Trigger") or Chest:FindFirstChildWhichIsA("BasePart",true)) or nil
            end
            local function BoatTravel(CF,Source)
                if typeof(CF)~="CFrame" then return false end
                return Runtime.ProfileSmartTravel(CF,nil,{
                    Mode=State.BuildABoatTravelMode,
                    Speed=math.max(tonumber(State.ProfileTweenSpeed) or 140,180),
                    Source=Source or "BuildABoat"
                })
            end
            local function BoatTryClaimRiverGold()
                if not State.BuildABoatClaimRiverGold then return false end
                local Remote=workspace:FindFirstChild("ClaimRiverResultsGold") or ReplicatedStorage:FindFirstChild("ClaimRiverResultsGold",true)
                if not Remote then return false end
                local Ok=false
                if Remote:IsA("RemoteEvent") then Ok=pcall(function() Remote:FireServer() end)
                elseif Remote:IsA("RemoteFunction") then Ok=pcall(function() Remote:InvokeServer() end) end
                return Ok
            end
            local function BoatTouch(Part)
                local R=Root()
                if not R or not Part or not Part:IsA("BasePart") then return false end
                if type(firetouchinterest)=="function" then
                    local Ok=pcall(function()
                        firetouchinterest(R,Part,0)
                        RunService.Heartbeat:Wait()
                        firetouchinterest(R,Part,1)
                    end)
                    if Ok then return true end
                end
                return false
            end
            local function BoatStageValue(Index)
                local OtherData=Player:FindFirstChild("OtherData")
                local Value=OtherData and OtherData:FindFirstChild("Stage"..tostring(math.max(0,(tonumber(Index) or 1)-1)))
                if Value and Value:IsA("ValueBase") then return Value,tostring(Value.Value or "") end
                return nil,nil
            end
            local function BoatWaitForStageReset(MaxWait)
                local HasReplicatedValues=false
                local function IsReset()
                    local AllReset=true
                    for I=1,10 do
                        local Value,Text=BoatStageValue(I)
                        if Value then
                            HasReplicatedValues=true
                            if Text and Text~="" then AllReset=false end
                        end
                    end
                    return AllReset
                end
                if IsReset() or not HasReplicatedValues then return true end
                local Deadline=os.clock()+math.max(tonumber(MaxWait) or 4,0.5)
                repeat
                    Runtime.Movement.Guard()
                    task.wait(0.10)
                    if IsReset() then return true end
                until os.clock()>=Deadline
                return false
            end
            local function BoatTriggerStage(Part,Index)
                if not Part or not Part.Parent then return false,"stage part missing" end
                local Value,Before=BoatStageValue(Index)
                local StageEvent=Part:FindFirstChild("Event")
                if StageEvent and StageEvent:IsA("BindableEvent") then pcall(function() StageEvent:Fire() end) end
                BoatTouch(Part)
                if not Value then
                    task.wait(State.BuildABoatStageDelay)
                    return true,"no replicated stage value"
                end
                local Deadline=os.clock()+math.max(State.BuildABoatStageDelay,0.45)
                repeat
                    Runtime.Movement.Guard()
                    local _,Current=BoatStageValue(Index)
                    if Current and Current~="" and (Before=="" or Current~=Before) then return true,"verified" end
                    if Current and Current~="" and Before~="" then return true,"already credited" end
                    task.wait(0.08)
                until os.clock()>=Deadline
                local _,Current=BoatStageValue(Index)
                return Current~=nil and Current~="","credit not confirmed"
            end
            local function BoatLaunch()
                -- Prefer the visible game button so this survives remote renames.
                if ActivateVisibleGui({"launch","launch boat","set sail"}) then return true end
                local Prompt=FindPromptByKeywords({"launch","set sail"})
                if Prompt then return UsePrompt(Prompt,false) end
                return false
            end
            local function BoatGoldAmount()
                local Containers={Player:FindFirstChild("leaderstats"),Player:FindFirstChild("Data"),Player:FindFirstChild("OtherData")}
                for _,Container in ipairs(Containers) do
                    if Container then
                        for _,Name in ipairs({"Gold","gold","Coins","coins","Money","money"}) do
                            local V=Container:FindFirstChild(Name)
                            if V and V:IsA("ValueBase") and tonumber(V.Value) then return tonumber(V.Value) end
                        end
                    end
                end
                return nil
            end
            local function BoatRecoverCharacter(Reason)
                if Runtime.Movement and Runtime.Movement.RecoverCharacter then
                    return Runtime.Movement.RecoverCharacter(Reason or "Build A Boat recovery",Runtime.Movement.Serial)
                end
                local Deadline=os.clock()+4
                repeat
                    local H,R=Humanoid(),Root()
                    if H and H.Health>0 and R then return true end
                    task.wait(0.1)
                until os.clock()>=Deadline
                return false
            end
            local function BoatStageStatus()
                local Stages=BoatNormalStages()
                local Found=0
                if Stages then for I=1,10 do if BoatStagePart(I) then Found+=1 end end end
                local EndReady=BoatEndTrigger()~=nil
                local Claim=workspace:FindFirstChild("ClaimRiverResultsGold") or ReplicatedStorage:FindFirstChild("ClaimRiverResultsGold",true)
                return "Stages detected: "..tostring(Found).." / 10"
                    .."\nGolden chest trigger: "..(EndReady and "Ready" or "Not loaded")
                    .."\nRiver gold remote: "..(Claim and Claim.ClassName or "Not detected")
                    .."\nStage credit values: "..((Player:FindFirstChild("OtherData") and "Available") or "Not exposed")
                    .."\nRuns this session: "..tostring(State.BuildABoatRuns or 0)
                    .." • retries: "..tostring(State.BuildABoatRetries or 0).." • failed stages: "..tostring(State.BuildABoatFailedStages or 0)
                    .."\nCurrent stage: "..tostring(State.BuildABoatCurrentStage or "Idle")
                    .."\nGold gained: "..tostring(State.BuildABoatGoldEarned or 0)
                    ..((State.BuildABoatRunStartedAt and State.BuildABoatRunStartedAt>0) and (" • run time: "..string.format("%.1fs",os.clock()-State.BuildABoatRunStartedAt)) or "")
                    .."\nStatus: "..tostring(State.BuildABoatLastStatus or "Ready")
            end
            local function BoatClearStageESP()
                for Obj,Highlight in pairs(State.BuildABoatStageHighlights or {}) do
                    if Highlight then pcall(function() Highlight:Destroy() end) end
                    State.BuildABoatStageHighlights[Obj]=nil
                end
            end
            local function BoatUpdateStageESP()
                if not State.BuildABoatStageESP then BoatClearStageESP(); return end
                local Seen={}
                local function Mark(Part,Color)
                    if not Part or not Part.Parent then return end
                    Seen[Part]=true
                    local H=State.BuildABoatStageHighlights[Part]
                    if not H or not H.Parent then
                        H=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights")
                        H.Name="BananiHub_BuildABoatStage"
                        local Adornee=Part:FindFirstAncestorOfClass("Model") or Part
                        H.Adornee=Adornee
                        H.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
                        H.FillTransparency=0.72
                        H.OutlineTransparency=0.05
                        H.Parent=Adornee
                        State.BuildABoatStageHighlights[Part]=H
                    end
                    H.FillColor=Color
                    H.OutlineColor=Color
                end
                for I=1,10 do Mark(BoatStagePart(I),Color3.fromRGB(255,193,63)) end
                Mark(BoatEndTrigger(),Color3.fromRGB(80,220,130))
                for Obj,H in pairs(State.BuildABoatStageHighlights) do
                    if not Seen[Obj] or not Obj.Parent then
                        if H then pcall(function() H:Destroy() end) end
                        State.BuildABoatStageHighlights[Obj]=nil
                    end
                end
            end
            local function BoatGoSelectedStage()
                local Text=tostring(State.BuildABoatSelectedStage or "Stage 1")
                if Text=="Treasure / End" then
                    local P=BoatEndTrigger()
                    if not P then Notify("Build A Boat","Golden chest trigger is not loaded."); return false end
                    return BoatTravel(P.CFrame*CFrame.new(0,3,0),"BuildABoatEnd")
                end
                local I=tonumber(string.match(Text,"%d+"))
                local P=I and BoatStagePart(I) or nil
                if not P then Notify("Build A Boat","That stage is not loaded."); return false end
                return BoatTravel(P.CFrame*CFrame.new(0,3,0),"BuildABoatStage")
            end
            local function BoatFindNearestSeat()
                local Me=Root(); if not Me then return nil end
                local Best,Dist=nil,math.huge
                for _,Obj in ipairs(Runtime.ProfileObjects()) do
                    if (Obj:IsA("VehicleSeat") or Obj:IsA("Seat")) and not Obj.Occupant then
                        local D=(Obj.Position-Me.Position).Magnitude
                        if D<Dist and D<220 then Best,Dist=Obj,D end
                    end
                end
                return Best
            end
            local function BoatSitNearest()
                local Seat=BoatFindNearestSeat()
                if not Seat then Notify("Build A Boat","No empty nearby seat was detected."); return false end
                if not BoatTravel(Seat.CFrame*CFrame.new(0,2,0),"BuildABoatSeat") then return false end
                local H=Humanoid(); if H then pcall(function() Seat:Sit(H) end) end
                return true
            end
            local function BoatFarmCycle()
                Runtime.Movement.Guard()
                State.BuildABoatRunStartedAt=os.clock()
                local RunGoldStart=BoatGoldAmount()
                local Stages=BoatNormalStages()
                if not Stages then
                    State.BuildABoatLastStatus="Waiting for BoatStages.NormalStages"
                    return false
                end
                if not BoatWaitForStageReset(4) then
                    State.BuildABoatLastStatus="Waiting for previous stage credits to reset"
                    return false
                end
                if State.BuildABoatAutoLaunch then BoatLaunch(); task.wait(0.20) end
                for I=1,10 do
                    Runtime.Movement.Guard()
                    State.BuildABoatCurrentStage=I
                    local Part=BoatStagePart(I)
                    local HNow=Humanoid()
                    if not HNow or HNow.Health<=0 or not Root() then
                        if not BoatRecoverCharacter("Respawn before stage "..I) then return false end
                        if State.BuildABoatAutoReseat then pcall(BoatSitNearest) end
                    end
                    if not Part then
                        State.BuildABoatLastStatus="Stage "..I.." is not loaded"
                        return false
                    end
                    local Credited=false
                    for Attempt=1,2 do
                        Runtime.Movement.Guard()
                        if Attempt>1 then State.BuildABoatRetries=(tonumber(State.BuildABoatRetries) or 0)+1 end
                        State.BuildABoatLastStatus="Crossing stage "..I.." / 10"..(Attempt>1 and " • retry" or "")
                        if not BoatTravel(Part.CFrame*CFrame.new(0,3,0),"BuildABoatStage"..I) then
                            State.BuildABoatLastStatus="Travel failed at stage "..I
                        else
                            local LiveRoot=Root()
                            local Knocked=not LiveRoot or (LiveRoot.Position-Part.Position).Magnitude>55
                            if LiveRoot and (LiveRoot.AssemblyLinearVelocity.Magnitude>180 or LiveRoot.AssemblyAngularVelocity.Magnitude>220) then
                                Knocked=true
                            end
                            if Knocked then
                                State.BuildABoatLastStatus="Knocked away at stage "..I.." • recovering"
                                if BoatRecoverCharacter("Knocked away at stage "..I) then
                                    LiveRoot=Root()
                                    if LiveRoot then
                                        pcall(function()
                                            LiveRoot.AssemblyLinearVelocity=Vector3.zero
                                            LiveRoot.AssemblyAngularVelocity=Vector3.zero
                                        end)
                                    end
                                end
                            end
                            local Ok=not Knocked and BoatTriggerStage(Part,I)
                            if Knocked then
                                Ok=BoatTravel(Part.CFrame*CFrame.new(0,3,0),"BuildABoatStage"..I.."Recover") and BoatTriggerStage(Part,I)
                            end
                            BoatTryClaimRiverGold()
                            if Ok then Credited=true; break end
                        end
                        task.wait(0.12)
                        Part=BoatStagePart(I) or Part
                    end
                    if not Credited then
                        State.BuildABoatFailedStages=(tonumber(State.BuildABoatFailedStages) or 0)+1
                        State.BuildABoatLastStatus="Stage "..I.." credit was not confirmed"
                        return false
                    end
                end
                Runtime.Movement.Guard()
                local EndPart=BoatEndTrigger()
                if not EndPart then
                    State.BuildABoatLastStatus="Golden chest trigger not loaded"
                    return false
                end
                State.BuildABoatLastStatus="Collecting treasure"
                if not BoatTravel(EndPart.CFrame*CFrame.new(0,2.5,0),"BuildABoatTreasure") then return false end
                local BeforeCharacter=Player.Character
                local BeforeHumanoid=BeforeCharacter and BeforeCharacter:FindFirstChildOfClass("Humanoid")
                local Started=os.clock()
                local Completed=false
                repeat
                    Runtime.Movement.Guard()
                    EndPart=BoatEndTrigger() or EndPart
                    if EndPart and EndPart.Parent then BoatTouch(EndPart) end
                    local Current=Player.Character
                    local CurrentHumanoid=Current and Current:FindFirstChildOfClass("Humanoid")
                    local CurrentGold=BoatGoldAmount()
                    local GoldChanged=RunGoldStart and CurrentGold and CurrentGold>RunGoldStart
                    if Current~=BeforeCharacter or (BeforeHumanoid and BeforeHumanoid.Health<=0)
                        or (CurrentHumanoid and CurrentHumanoid.Health<=0) or GoldChanged then
                        Completed=true
                        break
                    end
                    task.wait(0.12)
                until os.clock()-Started>=State.BuildABoatTreasureWait or not EndPart or not EndPart.Parent

                -- Current public BABFT layouts award/settle river results around the end transition.
                -- Only call the exact live-named remote when it actually exists; otherwise rely on the chest trigger.
                BoatTryClaimRiverGold()
                if Completed then
                    local Deadline=os.clock()+4
                    repeat
                        task.wait(0.10)
                        local C=Player.Character
                        local H=C and C:FindFirstChildOfClass("Humanoid")
                        local R=C and C:FindFirstChild("HumanoidRootPart")
                        if C and C~=BeforeCharacter and H and H.Health>0 and R then break end
                    until os.clock()>=Deadline
                end
                if not Completed then
                    State.BuildABoatLastStatus="Treasure trigger was not confirmed • retrying next cycle"
                    return false
                end
                local RunGoldEnd=BoatGoldAmount()
                if RunGoldStart and RunGoldEnd and RunGoldEnd>RunGoldStart then
                    State.BuildABoatGoldEarned=(tonumber(State.BuildABoatGoldEarned) or 0)+(RunGoldEnd-RunGoldStart)
                end
                State.BuildABoatRuns=(tonumber(State.BuildABoatRuns) or 0)+1
                State.BuildABoatLastRunDuration=os.clock()-(tonumber(State.BuildABoatRunStartedAt) or os.clock())
                State.BuildABoatRunStartedAt=0
                State.BuildABoatCurrentStage="Treasure ✓"
                State.BuildABoatLastStatus="Treasure confirmed • cycle "..State.BuildABoatRuns
                return true
            end
            Runtime.BuildABoatCleanup=function()
                State.BuildABoatStageESP=false
                StopLoop("BuildABoatStageESP")
                StopLoop("BuildABoatGoldFarm")
                StopLoop("BuildABoatSingleRun")
                BoatClearStageESP()
            end
            Runtime.BuildABoatReferenceLayout="workspace.BoatStages.NormalStages.CaveStage1-10.DarknessPart + TheEnd.GoldenChest.Trigger"
            Runtime.GameProfileCheck=BoatStageStatus

            local FarmCard=DetectedTab:DashboardSection(1,"Gold Farm + Stages")
            local BoatStatus=FarmCard:CreateParagraph({Title="Build A Boat Live Scan",Content=BoatStageStatus()})
            FarmCard:CreateButton({Name="Refresh Stage Scan",Callback=function() if BoatStatus and BoatStatus.Set then BoatStatus:Set({Title="Build A Boat Live Scan",Content=BoatStageStatus()}) end end})
            FarmCard:CreateDropdown({Name="Farm Travel",Options={"Teleport","Smooth Tween"},CurrentOption={State.BuildABoatTravelMode},Callback=function(O) State.BuildABoatTravelMode=type(O)=="table" and O[1] or O end})
            FarmCard:CreateSlider({Name="Stage Hold Time",Range={0.15,2.5},Increment=0.05,Suffix=" s",CurrentValue=State.BuildABoatStageDelay,Callback=function(V) State.BuildABoatStageDelay=V end})
            FarmCard:CreateSlider({Name="Cycle Delay",Range={0.5,12},Increment=0.5,Suffix=" s",CurrentValue=State.BuildABoatCycleDelay,Callback=function(V) State.BuildABoatCycleDelay=V end})
            FarmCard:CreateSlider({Name="Treasure Confirm Wait",Range={1,8},Increment=0.25,Suffix=" s",CurrentValue=State.BuildABoatTreasureWait,Callback=function(V) State.BuildABoatTreasureWait=V end})
            FarmCard:CreateToggle({Name="Claim River Gold When Available",Flag="GameProfile_BuildABoat_ClaimGold",CurrentValue=State.BuildABoatClaimRiverGold,Callback=function(V) State.BuildABoatClaimRiverGold=V end})
            FarmCard:CreateToggle({Name="Auto Launch Before Run",Flag="GameProfile_BuildABoat_AutoLaunch",CurrentValue=false,Callback=function(V) State.BuildABoatAutoLaunch=V end})
            FarmCard:CreateToggle({Name="Auto Reseat During Farm",Flag="GameProfile_BuildABoat_AutoReseat",CurrentValue=State.BuildABoatAutoReseat,Callback=function(V) State.BuildABoatAutoReseat=V end})
            FarmCard:CreateToggle({Name="Auto Gold + Treasure Farm",Flag="GameProfile_BuildABoat_AutoFarm",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BuildABoatGoldFarm",BoatFarmCycle,function() return State.BuildABoatCycleDelay end) else StopLoop("BuildABoatGoldFarm"); State.BuildABoatLastStatus="Stopped" end
            end})
            FarmCard:CreateButton({Name="Run One Gold Cycle",Callback=function()
                StartLoop("BuildABoatSingleRun",function()
                    local Ok,Err=pcall(BoatFarmCycle)
                    if not Ok and not string.find(tostring(Err),"BANANI_CANCELLED",1,true) then Notify("Build A Boat","Cycle failed: "..tostring(Err)) end
                    if BoatStatus and BoatStatus.Set then BoatStatus:Set({Title="Build A Boat Live Scan",Content=BoatStageStatus()}) end
                    StopLoop("BuildABoatSingleRun")
                end,999)
            end})

            local TravelCard=DetectedTab:DashboardSection(2,"Stage Travel + Boat")
            local StageOptions={}; for I=1,10 do StageOptions[#StageOptions+1]="Stage "..I end; StageOptions[#StageOptions+1]="Treasure / End"
            TravelCard:CreateDropdown({Name="Stage",Options=StageOptions,CurrentOption={State.BuildABoatSelectedStage},Callback=function(O) State.BuildABoatSelectedStage=type(O)=="table" and O[1] or O end})
            TravelCard:CreateButton({Name="Go To Selected Stage",Callback=BoatGoSelectedStage})
            TravelCard:CreateButton({Name="Go To Treasure",Callback=function() State.BuildABoatSelectedStage="Treasure / End"; BoatGoSelectedStage() end})
            TravelCard:CreateButton({Name="Launch Boat",Callback=function() if not BoatLaunch() then Notify("Build A Boat","No visible Launch control/prompt was detected.") end end})
            TravelCard:CreateButton({Name="Sit In Nearest Empty Seat",Callback=BoatSitNearest})
            TravelCard:CreateToggle({Name="Stage + Treasure ESP",Flag="GameProfile_BuildABoat_StageESP",CurrentValue=false,Callback=function(V)
                State.BuildABoatStageESP=V
                if V then StartLoop("BuildABoatStageESP",BoatUpdateStageESP,0.75) else StopLoop("BuildABoatStageESP"); BoatClearStageESP() end
            end})
            TravelCard:CreateButton({Name="Open Item / Treasure Scanner",Callback=function() Window:SelectTab("Visuals") end})
            TravelCard:CreateToggle({Name="Anti AFK",Flag="GameProfile_BuildABoat_AntiAFK",CurrentValue=false,Callback=function(V) Runtime.SetFlagValue("Player_AntiAFK",V) end})
            TravelCard:CreateButton({Name="Stop Build A Boat Automation",Callback=function() Runtime.BuildABoatCleanup(); Notify("Build A Boat","Farm, launch loop and stage ESP stopped.") end})
            TravelCard:CreateParagraph({Title="Build A Boat Profile",Content="Uses the live BoatStages/NormalStages layout and exact CaveStage1-10 DarknessPart + GoldenChest Trigger when present. It does not assume one fixed end coordinate, so map shifts are less likely to break the farm."})


-- ==================================================================
-- [BH:BLOXBURG] BLOXBURG PROFILE
-- Jobs, seller workflow, needs, skills, plots and performance helpers.
-- ==================================================================
        elseif Kind == "Bloxburg" then
            local Jobs={"Pizza Delivery","Pizza Baker","Cashier","Fast Food Worker","Fisherman","Hairdresser","Janitor","Mechanic","Miner","Seller","Woodcutter","Stocker","Teacher"}
            local Skills={"Athletic","Cooking","Gaming","Gardening","Intelligence","Music","Painting","Writing"}
            local JobKeywords={
                ["Pizza Delivery"]={"delivery","moped","pizza planet"}, ["Pizza Baker"]={"baker","pizza","dough"},
                Cashier={"cashier","register"}, ["Fast Food Worker"]={"fast food","burger","bloxy burger"},
                Fisherman={"fish","fishing"}, Hairdresser={"hairdresser","salon"}, Janitor={"janitor","clean"},
                Mechanic={"mechanic","wheel","oil"}, Miner={"mine","mining","ore"}, Seller={"seller","ice cream"},
                Woodcutter={"wood","tree","lumber"}, Stocker={"stocker","crate","stock"}, Teacher={"teacher","school"}
            }
            local SkillKeywords={
                Athletic={"treadmill","punch","athletic","gym"}, Cooking={"cook","oven","stove","counter"},
                Gaming={"computer","game"}, Gardening={"garden","plant","water"}, Intelligence={"book","read","study"},
                Music={"piano","guitar","music"}, Painting={"paint","easel"}, Writing={"write","computer"}
            }
            local function BloxburgDataEvent()
                local R=ReplicatedStorage:FindFirstChild("DataEvent")
                if R and (R:IsA("RemoteEvent") or R:IsA("RemoteFunction")) then return R end
                return nil
            end
            local function FireBloxburgData(Packet)
                local R=BloxburgDataEvent()
                if not R or type(Packet)~="table" then return false end
                if R:IsA("RemoteEvent") then return pcall(function() R:FireServer(Packet) end) end
                return pcall(function() R:InvokeServer(Packet) end)
            end
            local function BloxburgIceCreamStation()
                local Shop=workspace:FindFirstChild("BensIceCream")
                local Targets=Shop and Shop:FindFirstChild("CustomerTargets")
                if not Targets then return nil end
                for _,Station in ipairs(Targets:GetChildren()) do
                    local Occupied=Station:FindFirstChild("Occupied")
                    local Customer=Occupied and Occupied.Value
                    if Customer and Customer.Parent and Customer:FindFirstChild("Order") then
                        return Station,Customer,Customer.Order
                    end
                end
                return nil
            end
            local IceCreamFlavor={
                vanilla="Vanilla",
                chocolate="Chocolate",
                strawberry="Strawberry",
            }
            local IceCreamTopping={
                sprinkles="Sprinkles",
                nuts="Nuts",
                caramel="Caramel",
            }
            State.BloxburgIceCreamDirty=true
            State.BloxburgIceCreamLastAttempt=tonumber(State.BloxburgIceCreamLastAttempt) or -math.huge
            local BloxburgIceCreamWatchers=setmetatable({}, {__mode="k"})
            local BloxburgIceCreamTargetsWatched=nil

            local function MarkBloxburgIceCreamDirty()
                State.BloxburgIceCreamDirty=true
            end
            local function BindBloxburgIceCreamStation(Station)
                if not Station then return end
                local Occupied=Station:FindFirstChild("Occupied")
                if not Occupied or BloxburgIceCreamWatchers[Occupied] then return end
                BloxburgIceCreamWatchers[Occupied]=TrackConnection(
                    Occupied:GetPropertyChangedSignal("Value"):Connect(MarkBloxburgIceCreamDirty),
                    nil,
                    "BloxburgIceCream"
                )
            end
            local function BindBloxburgIceCreamTargets()
                local Shop=workspace:FindFirstChild("BensIceCream")
                local Targets=Shop and Shop:FindFirstChild("CustomerTargets")
                if not Targets then return nil end

                for _,Station in ipairs(Targets:GetChildren()) do
                    BindBloxburgIceCreamStation(Station)
                end
                if BloxburgIceCreamTargetsWatched~=Targets then
                    BloxburgIceCreamTargetsWatched=Targets
                    TrackConnection(Targets.ChildAdded:Connect(function(Station)
                        BindBloxburgIceCreamStation(Station)
                        MarkBloxburgIceCreamDirty()
                    end),nil,"BloxburgIceCream")
                    TrackConnection(Targets.ChildRemoved:Connect(MarkBloxburgIceCreamDirty),nil,"BloxburgIceCream")
                end
                return Targets
            end
            BindBloxburgIceCreamTargets()

            local function BloxburgIceCreamStep()
                if tostring(State.BloxburgJob)~="Seller" then return false end
                if not BloxburgDataEvent() then return false end
                BindBloxburgIceCreamTargets()

                local Station,Customer,Order=BloxburgIceCreamStation()
                if not Station or not Order then return false end

                local CharacterNow=Character()
                if not CharacterNow then return false end
                local Cup=CharacterNow:FindFirstChild("Ice Cream Cup")
                if not Cup then
                    FireBloxburgData({Type="TakeIceCreamCup"})
                    task.wait(0.10)
                    Cup=CharacterNow:FindFirstChild("Ice Cream Cup")
                    if not Cup then return false end
                end

                -- The public implementation reads every order VALUE and classifies the
                -- taste, instead of relying on the ValueObject's own name.
                local Ordered={}
                for _,ValueObject in ipairs(Order:GetChildren()) do
                    if ValueObject:IsA("ValueBase") then
                        local Taste=tostring(ValueObject.Value or "")
                        if Taste~="" then table.insert(Ordered,Taste) end
                    end
                end

                -- Its ball() helper selects the next transparent scoop slot.
                local Balls={}
                for _,Name in ipairs({"Ball1","Ball2"}) do
                    local Ball=Cup:FindFirstChild(Name)
                    if Ball and Ball:IsA("BasePart") and Ball.Transparency>=0.95 then
                        table.insert(Balls,Ball)
                    end
                end
                if #Balls==0 then
                    for _,Name in ipairs({"Ball1","Ball2"}) do
                        local Ball=Cup:FindFirstChild(Name)
                        if Ball and Ball:IsA("BasePart") then table.insert(Balls,Ball) end
                    end
                end

                local BallIndex=1
                for _,RawTaste in ipairs(Ordered) do
                    local Key=string.lower(RawTaste)
                    local Flavor=IceCreamFlavor[Key]
                    local Topping=IceCreamTopping[Key]
                    if Flavor and Balls[BallIndex] then
                        FireBloxburgData({Type="AddIceCreamScoop",Taste=RawTaste,Ball=Balls[BallIndex]})
                        BallIndex+=1
                        task.wait(0.04)
                    elseif Topping then
                        FireBloxburgData({Type="AddIceCreamTopping",Taste=Topping})
                        task.wait(0.04)
                    end
                end

                local Finished=FireBloxburgData({Type="FinishOrder",Workstation=Station})
                return Finished==true
            end

            local function BloxburgGoJob()
                local Keys=JobKeywords[State.BloxburgJob] or {State.BloxburgJob}
                local T=FindWorldTarget(Keys); if T then return MoveTo(T,CFrame.new(0,3,4)) end
                return false
            end
            State.BloxburgAutoBreak=false
            Runtime.BloxburgBreakStep=function(Now)
                if not State.BloxburgAutoBreak then
                    State.BloxburgBreakUntil=nil; State.BloxburgWorkSince=nil
                    return false
                end
                if State.BloxburgBreakUntil then
                    if Now<State.BloxburgBreakUntil then return true end
                    State.BloxburgBreakUntil=nil; State.BloxburgWorkSince=Now
                end
                State.BloxburgWorkSince=State.BloxburgWorkSince or Now
                local Interval=math.clamp(tonumber(State.BloxburgBreakHours) or 2,0.5,8)*3600
                if Now-State.BloxburgWorkSince>=Interval then
                    State.BloxburgBreakUntil=Now+math.clamp(tonumber(State.BloxburgBreakMinutes) or 15,1,60)*60
                    return true
                end
                return false
            end
            local function BloxburgJobStep()
                if Runtime.BloxburgBreakStep(os.clock()) then return end

                -- The readable public Bloxburg implementation exposes a concrete
                -- Ben's Ice Cream DataEvent workflow. Use it only if that exact
                -- live hierarchy still exists; otherwise fall back to prompts/UI.
                if State.BloxburgJob=="Seller" then
                    local Now=os.clock()
                    if State.BloxburgIceCreamDirty
                        or Now-(tonumber(State.BloxburgIceCreamLastAttempt) or -math.huge)>=0.8 then
                        State.BloxburgIceCreamDirty=false
                        State.BloxburgIceCreamLastAttempt=Now
                        if BloxburgIceCreamStep() then return end
                    end
                end

                local Keys=JobKeywords[State.BloxburgJob] or {State.BloxburgJob}
                local P=FindPromptByKeywords(Keys)
                if P then UsePrompt(P,true); return end
                BloxburgGoJob()
                ActivateVisibleGui({"work","start shift","next","done","take","deliver","serve","clean","restock"})
            end
            local function MoodStep()
                local P=FindPromptByKeywords({"sleep","shower","bath","eat","drink","fun","tv","toilet"})
                if P then UsePrompt(P,true) end
            end
            local function SkillStep()
                local Keys=SkillKeywords[State.BloxburgSkill] or {State.BloxburgSkill}
                local P=FindPromptByKeywords(Keys)
                if P then UsePrompt(P,true) else local T=FindWorldTarget(Keys); if T then MoveTo(T,CFrame.new(0,2,3)) end end
            end
            local function PlotForPlayer(Display)
                local P=Display and FindPlayerByDisplayName(Display)
                if not P then return nil end
                for _,Obj in ipairs(Runtime.ProfileTargets()) do
                    if (Obj:IsA("Model") or Obj:IsA("BasePart")) then
                        local N=string.lower(Obj.Name)
                        if string.find(N,string.lower(P.Name),1,true) and (string.find(N,"plot",1,true) or string.find(N,"house",1,true)) then return Obj end
                    end
                end
                return nil
            end
            local function VehicleSeat()
                local H=Humanoid(); local S=H and H.SeatPart
                return S and S:IsA("VehicleSeat") and S or nil
            end
            local function ApplyVehicle()
                local S=VehicleSeat(); if not S then return false end
                pcall(function() S.MaxSpeed=tonumber(State.BloxburgVehicleSpeed) or S.MaxSpeed end)
                pcall(function() S.TurnSpeed=tonumber(State.BloxburgTurnSpeed) or S.TurnSpeed end)
                return true
            end
            local function StatsText()
                local LS=Player:FindFirstChild("leaderstats"); local Out={}
                if LS then for _,V in ipairs(LS:GetChildren()) do if V:IsA("ValueBase") then table.insert(Out,V.Name..": "..tostring(V.Value)) end end end
                return #Out>0 and table.concat(Out," | ") or "No public leaderstats are exposed in this server."
            end

            DetectedTab:CreateSection("JOBS")
            DetectedTab:CreateDropdown({Name="Job",Options=Jobs,CurrentOption={State.BloxburgJob},SearchBarEnabled=true,Callback=function(O)
                State.BloxburgJob=type(O)=="table" and O[1] or O
                State.BloxburgIceCreamDirty=true
            end})
            DetectedTab:CreateSlider({Name="Job Action Delay",Range={0.2,2},Increment=0.05,Suffix=" s",CurrentValue=State.BloxburgPromptDelay,Callback=function(V) State.BloxburgPromptDelay=V end})
            DetectedTab:CreateButton({Name="Go To Selected Job",Callback=function() if not BloxburgGoJob() then Notify("Bloxburg","The selected job station was not found yet.") end end})
            DetectedTab:CreateToggle({Name="Auto Work Selected Job",Flag="GameProfile_Bloxburg_Job",CurrentValue=false,Callback=function(V)
                State.BloxburgWorkSince=nil; State.BloxburgBreakUntil=nil
                if V then StartLoop("BloxburgJob",BloxburgJobStep,function() return State.BloxburgPromptDelay end) else StopLoop("BloxburgJob") end
            end})
            DetectedTab:CreateToggle({Name="Scheduled Work Breaks",Flag="GameProfile_Bloxburg_Breaks",CurrentValue=false,Callback=function(V) State.BloxburgAutoBreak=V; State.BloxburgWorkSince=nil; State.BloxburgBreakUntil=nil end})
            DetectedTab:CreateSlider({Name="Work Before Break",Flag="GameProfile_Bloxburg_BreakHours",Range={0.5,8},Increment=0.5,Suffix=" hours",CurrentValue=2,Callback=function(V) State.BloxburgBreakHours=V end})
            DetectedTab:CreateSlider({Name="Break Length",Flag="GameProfile_Bloxburg_BreakMinutes",Range={1,60},Increment=1,Suffix=" min",CurrentValue=15,Callback=function(V) State.BloxburgBreakMinutes=V end})
            DetectedTab:CreateToggle({Name="Auto Mood + Return",Flag="GameProfile_Bloxburg_Mood",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BloxburgMood",function() if Runtime.BloxburgBreakStep(os.clock()) then return end; MoodStep(); task.wait(0.25); BloxburgGoJob() end,8) else StopLoop("BloxburgMood") end
            end})

            DetectedTab:CreateSection("HOUSE + LIFE")
            DetectedTab:CreateToggle({Name="Auto Pay Bills / Close Paycheck",Flag="GameProfile_Bloxburg_Bills",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BloxburgBills",function() ActivateVisibleGui({"pay bill","pay bills","paycheck","close"}) end,2.0) else StopLoop("BloxburgBills") end
            end})
            DetectedTab:CreateToggle({Name="Auto Cook Prompts",Flag="GameProfile_Bloxburg_Cook",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BloxburgCook",function() local P=FindPromptByKeywords({"cook","bake","mix","chop","fry","stir"}); if P then UsePrompt(P,true) end end,0.7) else StopLoop("BloxburgCook") end
            end})
            DetectedTab:CreateToggle({Name="Auto Garden Prompts",Flag="GameProfile_Bloxburg_Garden",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BloxburgGarden",function() local P=FindPromptByKeywords({"water","harvest","plant","fertilize"}); if P then UsePrompt(P,true) end end,0.8) else StopLoop("BloxburgGarden") end
            end})
            DetectedTab:CreateToggle({Name="Auto Clean / Repair Prompts",Flag="GameProfile_Bloxburg_Clean",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BloxburgClean",function() local P=FindPromptByKeywords({"clean","wash","mop","repair","fix","trash","garbage"}); if P then UsePrompt(P,true) end end,0.75) else StopLoop("BloxburgClean") end
            end})
            DetectedTab:CreateToggle({Name="Auto Open Nearby Doors",Flag="GameProfile_Bloxburg_Doors",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BloxburgDoors",function() local P=FindPromptByKeywords({"open door","open","door"}); if P and not string.find(string.lower(tostring(P.ActionText)),"close",1,true) then local R=GetRoot(P.Parent); local Me=Root(); if R and Me and (R.Position-Me.Position).Magnitude<=12 then UsePrompt(P,false) end end end,0.35) else StopLoop("BloxburgDoors") end
            end})
            DetectedTab:CreateDropdown({Name="Skill",Options=Skills,CurrentOption={State.BloxburgSkill},Callback=function(O) State.BloxburgSkill=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateToggle({Name="Auto Train Selected Skill",Flag="GameProfile_Bloxburg_Skill",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BloxburgSkill",SkillStep,0.8) else StopLoop("BloxburgSkill") end
            end})

            DetectedTab:CreateSection("VEHICLE")
            DetectedTab:CreateSlider({Name="Vehicle Max Speed",Range={20,180},Increment=5,CurrentValue=State.BloxburgVehicleSpeed,Callback=function(V) State.BloxburgVehicleSpeed=V; ApplyVehicle() end})
            DetectedTab:CreateSlider({Name="Vehicle Turn Speed",Range={0.5,8},Increment=0.25,CurrentValue=State.BloxburgTurnSpeed,Callback=function(V) State.BloxburgTurnSpeed=V; ApplyVehicle() end})
            DetectedTab:CreateButton({Name="Apply To Current Vehicle",Callback=function() if not ApplyVehicle() then Notify("Bloxburg","Sit in a VehicleSeat first.") end end})

            DetectedTab:CreateSection("PLOTS + INFO")
            DetectedTab:CreateDropdown({Name="Player Plot",Options=GetDisplayNames(),CurrentOption={},SearchBarEnabled=true,DynamicOptions=GetDisplayNames,Callback=function(O) State.BloxburgPlotPlayer=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateButton({Name="Go To Selected Player Plot",Callback=function() local T=PlotForPlayer(State.BloxburgPlotPlayer); if T then MoveTo(T,CFrame.new(0,4,5)) else Notify("Bloxburg","That player's plot was not detected in workspace.") end end})
            DetectedTab:CreateButton({Name="Show My Public Stats",Callback=function() Notify("Bloxburg",StatsText()) end})
            DetectedTab:CreateToggle({Name="Fullbright",Flag="GameProfile_Bloxburg_Fullbright",CurrentValue=false,Callback=function(V) Runtime.SetFlagValue("Visuals_Fullbright",V) end})
            DetectedTab:CreateToggle({Name="Performance Mode",Flag="GameProfile_Bloxburg_Performance",CurrentValue=false,Callback=function(V) Runtime.SetFlagValue("Visuals_LowGraphics",V) end})
            DetectedTab:CreateParagraph({Title="Bloxburg Profile",Content="Uses live prompts/objects by default. If the verified DataEvent + BensIceCream/CustomerTargets layout is present, Seller uses the source-backed cup/scoop/topping/FinishOrder flow. Other jobs stay on fail-safe live prompts instead of guessed money/job remotes."})


-- ==================================================================
-- [BH:BASKET] BASKETBALL LEGENDS PROFILE
-- Auto Green, guard prediction, possession, ball pickup and basketball actions.
-- ==================================================================
        elseif Kind == "BasketballLegends" then
            local function IsOpponent(P)
                if Runtime.ProfilePlayerIgnored(P) then return false end
                if not P or P==Player or not P.Character then return false end
                local H=P.Character:FindFirstChildOfClass("Humanoid")
                if not H or H.Health<=0 then return false end
                if Player.Team and P.Team and Player.Team==P.Team then return false end
                return P.Character:FindFirstChild("HumanoidRootPart")~=nil
            end
            local function OpponentNames()
                local O={}
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    if IsOpponent(P) then table.insert(O,P.DisplayName.." (@"..P.Name..")") end
                end
                table.sort(O)
                return O
            end

            -- 2026 public Basketball Legends source-backed references.
            local function BasketRefs()
                local Shooting=nil
                local Shoot=nil
                pcall(function()
                    local PG=Player:FindFirstChildOfClass("PlayerGui")
                    local Visual=PG and PG:FindFirstChild("Visual")
                    Shooting=Visual and Visual:FindFirstChild("Shooting")
                end)
                pcall(function()
                    local Packages=ReplicatedStorage:FindFirstChild("Packages")
                    local Knit=Packages and Packages:FindFirstChild("Knit")
                    local Services=Knit and Knit:FindFirstChild("Services")
                    local Control=Services and Services:FindFirstChild("ControlService")
                    local RE=Control and Control:FindFirstChild("RE")
                    local Candidate=RE and RE:FindFirstChild("Shoot")
                    if Candidate and Candidate:IsA("RemoteEvent") then Shoot=Candidate end
                end)
                return Shooting,Shoot
            end
            local function HoldsBall(P)
                if not P or not P.Character then return false end
                local Exact=P.Character:FindFirstChild("Basketball")
                if Exact and Exact:IsA("Tool") then return true end
                -- Compatibility fallback for renamed/custom court variants.
                for _,O in ipairs(P.Character:GetChildren()) do
                    if O:IsA("Tool") and MatchKeywords(O.Name,{"basketball","ball"}) then return true end
                end
                return false
            end
            local function FindBall()
                local R=Root()
                local Direct=workspace:FindFirstChild("Basketball")
                if Direct and Direct:IsA("BasePart") then return Direct end
                local Best,Dist=nil,math.huge
                for _,O in ipairs(Runtime.ProfileTargets()) do
                    if O:IsA("BasePart") and O.Name=="Basketball" then
                        local M=O:FindFirstAncestorOfClass("Model")
                        if not (M and IsPlayerCharacter(M)) then
                            local D=R and (R.Position-O.Position).Magnitude or 0
                            if D<Dist then Best,Dist=O,D end
                        end
                    end
                end
                if Best then return Best end
                -- Last-resort name compatibility only; exact Basketball gets priority.
                for _,O in ipairs(Runtime.ProfileTargets()) do
                    if O:IsA("BasePart") and MatchKeywords(O.Name,{"basketball","ball"}) then
                        local M=O:FindFirstAncestorOfClass("Model")
                        if not (M and IsPlayerCharacter(M)) then
                            local D=R and (R.Position-O.Position).Magnitude or 0
                            if D<Dist then Best,Dist=O,D end
                        end
                    end
                end
                return Best
            end
            local function NearestOpponent(PreferHolder)
                local R=Root(); if not R then return nil,math.huge end
                local Best,Dist=nil,math.huge
                if PreferHolder then
                    for _,P in ipairs(Runtime.CachedPlayers()) do
                        if IsOpponent(P) and HoldsBall(P) then
                            local PR=P.Character.HumanoidRootPart
                            local D=(R.Position-PR.Position).Magnitude
                            if D<Dist then Best,Dist=P,D end
                        end
                    end
                end
                if Best then return Best,Dist end
                for _,P in ipairs(Runtime.CachedPlayers()) do
                    if IsOpponent(P) then
                        local PR=P.Character.HumanoidRootPart
                        local D=(R.Position-PR.Position).Magnitude
                        if D<Dist then Best,Dist=P,D end
                    end
                end
                return Best,Dist
            end
            local function TriggerBasketAction(Name,Key,Hold)
                if ActivateVisibleGui({string.lower(Name)}) then return true end
                return PressKey(Key,Hold)
            end
            local function LocalHasBall() return HoldsBall(Player) end

            local BasketGuardHeld=false
            local function SetBasketGuardKey(Down)
                Down=Down==true
                if BasketGuardHeld==Down then return true end
                local OK,VIM=pcall(function() return game:GetService("VirtualInputManager") end)
                if not OK or not VIM then return false end
                local Sent=pcall(function() VIM:SendKeyEvent(Down,Enum.KeyCode.F,false,game) end)
                if Sent then BasketGuardHeld=Down end
                return Sent
            end
            local function GuardStep()
                if LocalHasBall() then SetBasketGuardKey(false); return end
                local P,D=NearestOpponent(true)
                local PR=P and P.Character and P.Character:FindFirstChild("HumanoidRootPart")
                local H=Humanoid()
                local R=Root()
                if not PR or not H or not R then SetBasketGuardKey(false); return end

                local Prediction=math.clamp(tonumber(State.BasketGuardPrediction) or 0.30,0,0.60)
                local Predicted=PR.Position+(PR.AssemblyLinearVelocity*Prediction)
                local Delta=Predicted-R.Position
                local Flat=Vector3.new(Delta.X,0,Delta.Z)
                local Dir=Flat.Magnitude>0.05 and Flat.Unit or Vector3.new(0,0,-1)
                local Dist=tonumber(State.BasketGuardDistance) or 7
                local GuardPos=Predicted-Dir*Dist
                H:MoveTo(Vector3.new(GuardPos.X,R.Position.Y,GuardPos.Z))
                SetBasketGuardKey(D<=math.max(Dist+3,10))
            end

            local function FireBasketShot()
                if not LocalHasBall() then return false end
                local Shooting,Shoot=BasketRefs()
                if Shoot then
                    return pcall(function() Shoot:FireServer(math.clamp(tonumber(State.BasketShootPower) or 0.80,0.50,1.00)) end)
                end
                return TriggerBasketAction("shoot",State.BasketShootKey,State.BasketGreenHold)
            end
            local function ShootStep()
                if not LocalHasBall() then return false end
                local _,D=NearestOpponent(false)
                if D < (tonumber(State.BasketDefenderDistance) or 10) then return false end
                local Shooting=BasketRefs()
                if Shooting and Shooting:IsA("GuiObject") and not Shooting.Visible then return false end
                return FireBasketShot()
            end

            local BasketShootConnection=nil
            local BasketShootElement=nil
            State.BasketAutoShootEnabled=State.BasketAutoShootEnabled==true

            local function DisconnectBasketShootBinding()
                if BasketShootConnection then
                    pcall(function() BasketShootConnection:Disconnect() end)
                    Runtime.ReleaseCleanup(BasketShootConnection)
                    BasketShootConnection=nil
                end
                BasketShootElement=nil
            end

            local function BindBasketShootElement()
                if not State.BasketAutoShootEnabled then return false end
                local Shooting=BasketRefs()
                if not Shooting or not Shooting:IsA("GuiObject") then return false end
                if BasketShootElement==Shooting and BasketShootConnection and BasketShootConnection.Connected then
                    return true
                end

                DisconnectBasketShootBinding()
                BasketShootElement=Shooting
                BasketShootConnection=TrackConnection(
                    Shooting:GetPropertyChangedSignal("Visible"):Connect(function()
                        if Unloaded or not State.BasketAutoShootEnabled or not Shooting.Visible then return end
                        task.delay(0.25,function()
                            if Unloaded or not State.BasketAutoShootEnabled
                                or BasketShootElement~=Shooting or not Shooting.Parent or not Shooting.Visible then return end
                            local _,D=NearestOpponent(false)
                            if LocalHasBall() and D>=(tonumber(State.BasketDefenderDistance) or 10) then
                                FireBasketShot()
                            end
                        end)
                    end),
                    "BasketAutoGreenVisible",
                    "BasketballConnections"
                )
                StopLoop("BasketShoot")
                return true
            end

            local function SetBasketAutoShoot(Value)
                State.BasketAutoShootEnabled=Value==true
                DisconnectBasketShootBinding()
                StopLoop("BasketShoot")
                if not State.BasketAutoShootEnabled then return end

                if not BindBasketShootElement() then
                    -- Fallback for variants where Visual.Shooting is absent/renamed.
                    StartLoop("BasketShoot",ShootStep,0.16)
                end
            end

            -- PlayerGui elements can be recreated after respawn/round transitions.
            -- Rebind the exact Shooting element automatically instead of leaving
            -- Auto Green connected to a destroyed GUI instance.
            local BasketPlayerGui=Player:FindFirstChildOfClass("PlayerGui")
            if BasketPlayerGui then
                TrackConnection(BasketPlayerGui.DescendantAdded:Connect(function(Object)
                    if not State.BasketAutoShootEnabled or Object.Name~="Shooting" then return end
                    task.defer(function()
                        if not Unloaded and State.BasketAutoShootEnabled then BindBasketShootElement() end
                    end)
                end),nil,"BasketballConnections")
            end

            local function PassStep()
                if not LocalHasBall() then return end
                local _,D=NearestOpponent(false)
                if D <= (tonumber(State.BasketPassDistance) or 6) then TriggerBasketAction("pass",State.BasketPassKey,0.035) end
            end
            local function DunkStep()
                if not LocalHasBall() then return end
                local Hoop=FindWorldTarget({"hoop","rim","basket"}); local R=Root(); local HR=GetRoot(Hoop)
                if R and HR and (R.Position-HR.Position).Magnitude<=11 then TriggerBasketAction("dunk","Space",0.04) end
            end
            local function BallMagnetStep()
                local B=FindBall(); local R=Root()
                if not B or not R or LocalHasBall() then return end
                if (B.Position-R.Position).Magnitude > (tonumber(State.BasketBallMagnet) or 12) then return end
                if type(firetouchinterest)=="function" then
                    pcall(function()
                        firetouchinterest(R,B,0)
                        RunService.Heartbeat:Wait()
                        firetouchinterest(R,B,1)
                    end)
                else
                    TouchObject(B)
                end
            end
            local function ShootingAidStep()
                local _,D=NearestOpponent(false); local Safe=D >= (tonumber(State.BasketDefenderDistance) or 10)
                local C=Character(); if not C then return end
                local H=State.BasketAidHighlight
                if not H or not H.Parent then H=Runtime.TrackTransient(Instance.new("Highlight"),"Highlights"); H.Name="BananiHub_ShootingAid"; H.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop; H.Parent=C; State.BasketAidHighlight=H end
                H.FillTransparency=0.78; H.OutlineTransparency=0.1
                H.FillColor=Safe and Color3.fromRGB(70,190,95) or Color3.fromRGB(220,70,70)
                H.OutlineColor=H.FillColor
            end
            local Keys={"Q","E","R","F","G","T","X","C","V","B","H","J"}

            DetectedTab:CreateSection("SHOOTING")
            DetectedTab:CreateDropdown({Name="Shoot Key",Options=Keys,CurrentOption={State.BasketShootKey},Callback=function(O) State.BasketShootKey=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateSlider({Name="Shot Timing Power",Range={50,100},Increment=1,Suffix="%",CurrentValue=math.floor(State.BasketShootPower*100+0.5),Callback=function(V) State.BasketShootPower=math.clamp(V/100,0.50,1.00) end})
            DetectedTab:CreateSlider({Name="Min Defender Distance",Range={5,30},Increment=1,Suffix=" studs",CurrentValue=State.BasketDefenderDistance,Callback=function(V) State.BasketDefenderDistance=V end})
            DetectedTab:CreateToggle({Name="Auto Green When Open",Flag="GameProfile_Basket_AutoShoot",CurrentValue=false,Callback=SetBasketAutoShoot})
            DetectedTab:CreateToggle({Name="Shooting Aid",Flag="GameProfile_Basket_Aid",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketAid",ShootingAidStep,0.12) else StopLoop("BasketAid"); if State.BasketAidHighlight then pcall(function() State.BasketAidHighlight:Destroy() end); State.BasketAidHighlight=nil end end
            end})
            DetectedTab:CreateButton({Name="Shoot / Green Test",Callback=function() if not FireBasketShot() then Notify("Basketball Legends","Shoot remote/UI was not ready; fallback input was attempted.") end end})
            DetectedTab:CreateButton({Name="Dunk",Callback=function() TriggerBasketAction("dunk","Space",0.04) end})
            DetectedTab:CreateToggle({Name="Auto Dunk Near Hoop",Flag="GameProfile_Basket_Dunk",CurrentValue=false,Callback=function(V) if V then StartLoop("BasketDunk",DunkStep,0.12) else StopLoop("BasketDunk") end end})

            DetectedTab:CreateSection("DEFENSE")
            DetectedTab:CreateInput({Name="Ignore Opponent Usernames",Flag="GameProfile_Basket_Ignored",PlaceholderText="username1, username2",RemoveTextAfterFocusLost=false,Callback=Runtime.ProfileSetIgnoredPlayers})
            DetectedTab:CreateSlider({Name="Steal Distance",Flag="GameProfile_Basket_StealDistance",Range={1,15},Increment=1,Suffix=" studs",CurrentValue=7,Callback=function(V) State.BasketStealDistance=V end})
            DetectedTab:CreateSlider({Name="Block Distance",Flag="GameProfile_Basket_BlockDistance",Range={1,20},Increment=1,Suffix=" studs",CurrentValue=10,Callback=function(V) State.BasketBlockDistance=V end})
            DetectedTab:CreateDropdown({Name="Opponent",Options=OpponentNames(),CurrentOption={},SearchBarEnabled=true,DynamicOptions=OpponentNames,Callback=function(O) State.BasketOpponent=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateSlider({Name="Guard Distance",Range={3,20},Increment=1,Suffix=" studs",CurrentValue=State.BasketGuardDistance,Callback=function(V) State.BasketGuardDistance=V end})
            DetectedTab:CreateSlider({Name="Guard Prediction",Range={0,0.6},Increment=0.05,Suffix=" s",CurrentValue=State.BasketGuardPrediction,Callback=function(V) State.BasketGuardPrediction=V end})
            DetectedTab:CreateToggle({Name="Auto Guard Ball Holder",Flag="GameProfile_Basket_Guard",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketGuard",GuardStep,0.06)
                else StopLoop("BasketGuard"); SetBasketGuardKey(false) end
            end})
            DetectedTab:CreateDropdown({Name="Steal Key",Options=Keys,CurrentOption={State.BasketStealKey},Callback=function(O) State.BasketStealKey=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateDropdown({Name="Block Key",Options=Keys,CurrentOption={State.BasketBlockKey},Callback=function(O) State.BasketBlockKey=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateToggle({Name="Auto Steal Nearby",Flag="GameProfile_Basket_Steal",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketSteal",function() local _,D=NearestOpponent(true); if D<=(tonumber(State.BasketStealDistance) or 7) then TriggerBasketAction("steal",State.BasketStealKey,0.035) end end,0.18) else StopLoop("BasketSteal") end
            end})
            DetectedTab:CreateToggle({Name="Auto Block Nearby",Flag="GameProfile_Basket_Block",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketBlock",function() local _,D=NearestOpponent(true); if D<=(tonumber(State.BasketBlockDistance) or 10) then TriggerBasketAction("block",State.BasketBlockKey,0.035) end end,0.18) else StopLoop("BasketBlock") end
            end})

            DetectedTab:CreateSection("BALL")
            DetectedTab:CreateDropdown({Name="Pass Key",Options=Keys,CurrentOption={State.BasketPassKey},Callback=function(O) State.BasketPassKey=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateSlider({Name="Auto Pass Threat Distance",Range={3,20},Increment=1,Suffix=" studs",CurrentValue=State.BasketPassDistance,Callback=function(V) State.BasketPassDistance=V end})
            DetectedTab:CreateToggle({Name="Auto Pass Under Pressure",Flag="GameProfile_Basket_Pass",CurrentValue=false,Callback=function(V) if V then StartLoop("BasketPass",PassStep,0.2) else StopLoop("BasketPass") end end})
            DetectedTab:CreateSlider({Name="Ball Magnet Distance",Range={5,25},Increment=1,Suffix=" studs",CurrentValue=State.BasketBallMagnet,Callback=function(V) State.BasketBallMagnet=V end})
            DetectedTab:CreateToggle({Name="Ball Magnet",Flag="GameProfile_Basket_Magnet",CurrentValue=false,Callback=function(V) if V then StartLoop("BasketMagnet",BallMagnetStep,0.05) else StopLoop("BasketMagnet") end end})
            DetectedTab:CreateToggle({Name="Auto Rebound / Loose Ball",Flag="GameProfile_Basket_Rebound",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketRebound",function() local B=FindBall(); if B then ProfileTravelToCFrame(B.CFrame*CFrame.new(0,2,0)) end end,0.18) else StopLoop("BasketRebound") end
            end})
            DetectedTab:CreateButton({Name="Go To Loose Ball",Callback=function() local B=FindBall(); if B then ProfileTravelToCFrame(B.CFrame*CFrame.new(0,2,0)) else Notify("Basketball Legends","No loose ball was detected.") end end})
            DetectedTab:CreateToggle({Name="Auto Face Ball Holder",Flag="GameProfile_Basket_FaceHolder",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketFaceHolder",function() local P=NearestOpponent(true); local PR=P and P.Character and P.Character:FindFirstChild("HumanoidRootPart"); local R=Root(); if PR and R then local Pos=R.Position; R.CFrame=CFrame.lookAt(Pos,Vector3.new(PR.Position.X,Pos.Y,PR.Position.Z)) end end,0.05) else StopLoop("BasketFaceHolder") end
            end})
            DetectedTab:CreateToggle({Name="Auto Drive To Hoop With Ball",Flag="GameProfile_Basket_Drive",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketDrive",function() if not LocalHasBall() then return end; local Hoop=FindWorldTarget({"hoop","rim","basket"}); local HR=GetRoot(Hoop); if HR then ProfileTravelToCFrame(HR.CFrame*CFrame.new(0,0,7)) end end,0.18) else StopLoop("BasketDrive") end
            end})

            DetectedTab:CreateSection("ANTI EFFECTS + MACROS")
            DetectedTab:CreateToggle({Name="Anti Fall / Freeze",Flag="GameProfile_Basket_AntiFall",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketAntiFall",function() local H=Humanoid(); if H then H.PlatformStand=false; if H.WalkSpeed<8 then H.WalkSpeed=16 end end end,0.08) else StopLoop("BasketAntiFall") end
            end})
            DetectedTab:CreateToggle({Name="Anti Push / Screen",Flag="GameProfile_Basket_AntiPush",CurrentValue=false,Callback=function(V)
                if V then StartLoop("BasketAntiPush",function() local R=Root(); if R and R.AssemblyLinearVelocity.Magnitude>75 then R.AssemblyLinearVelocity=Vector3.new(R.AssemblyLinearVelocity.X*0.15,math.min(R.AssemblyLinearVelocity.Y,25),R.AssemblyLinearVelocity.Z*0.15) end end,0.04) else StopLoop("BasketAntiPush") end
            end})
            for _,Macro in ipairs({{"Cross","Q"},{"Stepback","X"},{"Hesi","C"},{"Spin","V"},{"Behind Back","B"},{"Pump Fake","G"},{"Eurostep","H"},{"Self Lob","J"}}) do
                DetectedTab:CreateButton({Name=Macro[1].." ["..Macro[2].."]",Callback=function() TriggerBasketAction(Macro[1],Macro[2],0.035) end})
            end
            DetectedTab:CreateButton({Name="Open Player ESP Settings",Callback=function() Window:SelectTab("Visuals") end})
            DetectedTab:CreateToggle({Name="Fast Walk",Flag="GameProfile_Basket_Speed",CurrentValue=FastWalkEnabled,Callback=function(V) Runtime.SetFlagValue("Player_FastWalk",V) end})
            DetectedTab:CreateParagraph({Title="Basketball Legends Profile",Content="Uses the verified Visual.Shooting + Knit ControlService.RE.Shoot path when present. Auto Green is event-driven, ball ownership prioritizes the exact Basketball Tool, guarding predicts the carrier with Humanoid:MoveTo, and Ball Magnet uses touch pickup instead of moving the ball part. Fallback inputs remain for renamed variants."})


-- ==================================================================
-- [BH:ARSENAL] ARSENAL PROFILE
-- FOV/visibility aim, ESP, weapon helpers and movement.
-- ==================================================================
        elseif Kind == "Arsenal" then
            -- Arsenal has frequent character/camera changes, so use a slightly calmer visual cadence.
            -- v5.18.46 revalidated this profile against public Arsenal/universal aim implementations:
            -- screen-space FOV, team/liveness checks, raycast visibility, target caching and CFrame:Lerp
            -- are already the preferred path, so no silent-aim/metamethod hook was imported.
            if Runtime.VisualEngine and Runtime.VisualEngine.Settings then
                local VS=Runtime.VisualEngine.Settings
                VS.PlayerUpdateInterval=math.max(tonumber(VS.PlayerUpdateInterval) or 0.12,0.18)
                VS.UpdateInterval=math.max(tonumber(VS.UpdateInterval) or 0.15,0.18)
                VS.OcclusionCheckInterval=math.max(tonumber(VS.OcclusionCheckInterval) or 0.18,0.28)
            end
            local function ArsenalEnemy(P)
                if Runtime.ProfilePlayerIgnored(P) then return false end
                if not P or P==Player or not P.Character then return false end
                local H=P.Character:FindFirstChildOfClass("Humanoid")
                if not H or H.Health<=0 then return false end
                if State.ArsenalTeamCheck and Player.Team and P.Team and Player.Team==P.Team then return false end
                return P.Character:FindFirstChild("HumanoidRootPart")~=nil
            end
            local function ArsenalNames()
                local O={}; for _,P in ipairs(Runtime.CachedPlayers()) do if ArsenalEnemy(P) then table.insert(O,P.DisplayName.." (@"..P.Name..")") end end; table.sort(O); return O
            end
            local function VisiblePart(Part)
                if not State.ArsenalVisibleOnly then return true end
                local Cam=workspace.CurrentCamera; local R=Root(); if not Cam or not R or not Part then return false end
                local Params=RaycastParams.new(); Params.FilterType=Enum.RaycastFilterType.Exclude; Params.FilterDescendantsInstances={Character()}
                local Res=workspace:Raycast(Cam.CFrame.Position,Part.Position-Cam.CFrame.Position,Params)
                return not Res or Res.Instance:IsDescendantOf(Part.Parent)
            end
            local ArsenalAimCache={Player=nil,Part=nil,Expires=0,FOV=nil,AimPart=nil,Locked=nil}
            local function ArsenalTarget()
                local Cam=workspace.CurrentCamera; if not Cam then return nil,nil end
                local Now=os.clock()
                local CacheValid=Now<(ArsenalAimCache.Expires or 0)
                    and ArsenalAimCache.FOV==State.ArsenalFOV
                    and ArsenalAimCache.AimPart==State.ArsenalAimPart
                    and ArsenalAimCache.Locked==State.ArsenalTargetPlayer
                    and ArsenalEnemy(ArsenalAimCache.Player)
                    and ArsenalAimCache.Part and ArsenalAimCache.Part.Parent
                if CacheValid and VisiblePart(ArsenalAimCache.Part) then
                    return ArsenalAimCache.Player,ArsenalAimCache.Part
                end
                local Best,BestPart=nil,nil
                if State.ArsenalLockSelected and State.ArsenalTargetPlayer then
                    local Locked=FindPlayerByDisplayName(State.ArsenalTargetPlayer)
                    if ArsenalEnemy(Locked) then
                        local LockedPart=Locked.Character:FindFirstChild(State.ArsenalAimPart) or Locked.Character:FindFirstChild("HeadHB") or Locked.Character:FindFirstChild("Head") or Locked.Character:FindFirstChild("HumanoidRootPart")
                        if LockedPart and VisiblePart(LockedPart) then Best,BestPart=Locked,LockedPart end
                    end
                end
                if not Best then
                    local Center=Cam.ViewportSize/2; local Dist=tonumber(State.ArsenalFOV) or 220
                    for _,P in ipairs(Runtime.CachedPlayers()) do if ArsenalEnemy(P) then
                        local Part=P.Character:FindFirstChild(State.ArsenalAimPart) or P.Character:FindFirstChild("HeadHB") or P.Character:FindFirstChild("Head") or P.Character:FindFirstChild("HumanoidRootPart")
                        if Part then
                            local V,On=Cam:WorldToViewportPoint(Part.Position)
                            if On and V.Z>0 then
                                local D=(Vector2.new(V.X,V.Y)-Center).Magnitude
                                if D<Dist and VisiblePart(Part) then Best,BestPart,Dist=P,Part,D end
                            end
                        end
                    end end
                end
                ArsenalAimCache.Player=Best; ArsenalAimCache.Part=BestPart
                ArsenalAimCache.Expires=Now+(State.ArsenalVisibleOnly and 0.085 or 0.11); ArsenalAimCache.FOV=State.ArsenalFOV
                ArsenalAimCache.AimPart=State.ArsenalAimPart; ArsenalAimCache.Locked=State.ArsenalTargetPlayer
                return Best,BestPart
            end
            local function AimStep()
                if not Runtime.ProfileAimAllowed("Arsenal") then return end
                local _,Part=ArsenalTarget(); local Cam=workspace.CurrentCamera
                if Part and Cam then
                    local Goal=CFrame.lookAt(Cam.CFrame.Position,Runtime.ProfileAimPosition("Arsenal",Part))
                    Cam.CFrame=Cam.CFrame:Lerp(Goal,1/math.max(tonumber(State.ArsenalSmooth) or 7,1))
                end
            end
            local function TriggerStep()
                local _,Part=ArsenalTarget(); local Cam=workspace.CurrentCamera
                if not Part or not Cam then return end
                local V,On=Cam:WorldToViewportPoint(Part.Position); if not On or V.Z<=0 then return end
                local D=(Vector2.new(V.X,V.Y)-Cam.ViewportSize/2).Magnitude
                if D<=10 then UseTool("Any Tool") end
            end
            local function ApplyHitboxes()
                for _,P in ipairs(Runtime.CachedPlayers()) do if ArsenalEnemy(P) then
                    local Part=P.Character:FindFirstChild(State.ArsenalAimPart) or P.Character:FindFirstChild("Head") or P.Character:FindFirstChild("HumanoidRootPart")
                    if Part and Part:IsA("BasePart") then
                        if not State.ArsenalHitboxBackup[Part] then State.ArsenalHitboxBackup[Part]={Size=Part.Size,Transparency=Part.Transparency,CanCollide=Part.CanCollide} end
                        pcall(function() Part.Size=Vector3.new(State.ArsenalHitboxSize,State.ArsenalHitboxSize,State.ArsenalHitboxSize); Part.Transparency=0.65; Part.CanCollide=false end)
                    end
                end end
            end
            local function RestoreHitboxes()
                for Part,Old in pairs(State.ArsenalHitboxBackup) do if Part and Part.Parent then pcall(function() Part.Size=Old.Size; Part.Transparency=Old.Transparency; Part.CanCollide=Old.CanCollide end) end end
                State.ArsenalHitboxBackup={}
            end
            local function ArsenalDisconnectModConnections()
                for _,Connection in ipairs(State.ArsenalModConnections or {}) do
                    if Connection then pcall(function() Connection:Disconnect() end) end
                end
                State.ArsenalModConnections={}
            end
            local function ArsenalDisconnectWeaponWatch()
                for _,Connection in ipairs(State.ArsenalWeaponWatchConnections or {}) do
                    if Connection then pcall(function() Connection:Disconnect() end) end
                end
                State.ArsenalWeaponWatchConnections={}
            end
            Runtime.ArsenalDisconnectWeaponWatch=ArsenalDisconnectWeaponWatch
            local function ArsenalCurrentTool()
                local C=Character()
                local Tool=C and C:FindFirstChildOfClass("Tool")
                if Tool then return Tool end
                local Backpack=Player:FindFirstChildOfClass("Backpack")
                if Backpack and State.ArsenalLastWeaponName then
                    local Last=Backpack:FindFirstChild(State.ArsenalLastWeaponName)
                    if Last and Last:IsA("Tool") then return Last end
                end
                return nil
            end
            local function ArsenalNormalizedName(Value)
                return string.lower(tostring(Value or "")):gsub("[^%w]","")
            end
            local function ArsenalAddCandidateTable(Data,T)
                if type(T)~="table" or Data.TableSeen[T] then return end
                local Hits=0
                for K in pairs(T) do
                    local L=string.lower(tostring(K))
                    if MatchKeywords(L,{"recoil","kick","spread","bloom","ammo","clip","magazine","firerate","shotdelay","cooldown","reload","automatic","range"}) then Hits+=1 end
                end
                if Hits>0 then Data.TableSeen[T]=true; table.insert(Data.Tables,T) end
            end
            local function ArsenalAddValue(Data,Obj)
                if not Obj or Data.ValueSeen[Obj] then return end
                if not (Obj:IsA("NumberValue") or Obj:IsA("IntValue") or Obj:IsA("BoolValue")) then return end
                local L=string.lower(Obj.Name)
                if MatchKeywords(L,{"recoil","kick","camshake","viewkick","spread","bloom","deviation","inaccuracy","firerate","shotdelay","cooldown","reload","ammo","magazine","clip","reserve","automatic","range"}) then
                    Data.ValueSeen[Obj]=true; table.insert(Data.Values,Obj)
                end
            end
            local function ArsenalBuildCurrentModData(Force)
                local Tool=ArsenalCurrentTool()
                local WeaponName=Tool and Tool.Name or ""
                local Existing=State.ArsenalCurrentModData or {}
                if not Force and Existing.WeaponName==WeaponName and os.clock()-(tonumber(Existing.At) or 0)<8
                    and type(Existing.Tables)=="table" and type(Existing.Values)=="table" then
                    local Valid=false
                    for _,T in ipairs(Existing.Tables) do if type(T)=="table" then Valid=true break end end
                    if not Valid then for _,V in ipairs(Existing.Values) do if V and V.Parent then Valid=true break end end end
                    if Valid then return Existing end
                end
                local CacheKey=ArsenalNormalizedName(WeaponName)
                local Cached=CacheKey~="" and State.ArsenalWeaponDataCache[CacheKey] or nil
                if not Force and Cached and os.clock()-(tonumber(Cached.At) or 0)<60 then
                    local Valid=false
                    for _,V in ipairs(Cached.Values or {}) do if V and V.Parent then Valid=true break end end
                    if Valid or #(Cached.Tables or {})>0 then
                        State.ArsenalCurrentModData=Cached
                        return Cached
                    end
                end
                local Data={WeaponName=WeaponName,Tables={},Values={},Nodes={},At=os.clock(),TableSeen={},ValueSeen={}}
                if Tool then
                    for _,Obj in ipairs(Tool:GetDescendants()) do ArsenalAddValue(Data,Obj) end
                end
                local Weapons=ReplicatedStorage:FindFirstChild("Weapons")
                if Weapons and WeaponName~="" then
                    local Exact=Weapons:FindFirstChild(WeaponName,true)
                    if not Exact then
                        local Wanted=ArsenalNormalizedName(WeaponName)
                        for _,Child in ipairs(Weapons:GetChildren()) do
                            if ArsenalNormalizedName(Child.Name)==Wanted then Exact=Child break end
                        end
                    end
                    if Exact then
                        table.insert(Data.Nodes,Exact)
                        if Exact:IsA("ModuleScript") then
                            local Ok,T=pcall(require,Exact); if Ok then ArsenalAddCandidateTable(Data,T) end
                        end
                        local Desc=Exact:GetDescendants()
                        local Modules=0
                        for _,Obj in ipairs(Desc) do
                            ArsenalAddValue(Data,Obj)
                            if Obj:IsA("ModuleScript") and Modules<12 then
                                Modules+=1
                                local Ok,T=pcall(require,Obj); if Ok then ArsenalAddCandidateTable(Data,T) end
                            end
                        end
                    end
                end
                State.ArsenalCurrentModData=Data
                if CacheKey~="" then State.ArsenalWeaponDataCache[CacheKey]=Data end
                return Data
            end
            local function ArsenalDesiredValue(Name,V)
                local L=string.lower(tostring(Name)); local New=nil
                if State.ArsenalNoRecoil and MatchKeywords(L,{"recoil","kick","camshake","viewkick"}) and type(V)=="number" then New=0 end
                if State.ArsenalNoSpread and MatchKeywords(L,{"spread","bloom","deviation","inaccuracy"}) and type(V)=="number" then New=0 end
                if State.ArsenalRapidFire and MatchKeywords(L,{"firerate","shotdelay","cooldown","delay"}) and type(V)=="number" then New=(V>10 and math.max(V,1000) or 0.02) end
                if State.ArsenalInfiniteAmmo and MatchKeywords(L,{"ammo","magazine","clip","reserve"}) and type(V)=="number" then New=math.max(V,999) end
                if State.ArsenalInstantReload and string.find(L,"reload",1,true) and type(V)=="number" then New=0 end
                if State.ArsenalAlwaysAuto and (string.find(L,"automatic",1,true) or L=="auto") and type(V)=="boolean" then New=true end
                if State.ArsenalInfiniteRange and string.find(L,"range",1,true) and type(V)=="number" then New=math.max(V,100000) end
                return New
            end
            local ArsenalApplyingValues=false
            local function PatchWeapons(ForceDiscover)
                local Data=ArsenalBuildCurrentModData(ForceDiscover==true)
                local Count=0
                for _,T in ipairs(Data.Tables or {}) do
                    State.ArsenalWeaponBackup[T]=State.ArsenalWeaponBackup[T] or {}
                    local B=State.ArsenalWeaponBackup[T]
                    for K,V in pairs(T) do
                        local New=ArsenalDesiredValue(K,V)
                        if New~=nil and New~=V then
                            if B[K]==nil then B[K]=V end
                            pcall(function() T[K]=New end); Count+=1
                        end
                    end
                end
                ArsenalApplyingValues=true
                for _,Obj in ipairs(Data.Values or {}) do
                    if Obj and Obj.Parent then
                        local V=Obj.Value; local New=ArsenalDesiredValue(Obj.Name,V)
                        if New~=nil and New~=V then
                            if State.ArsenalValueBackup[Obj]==nil then State.ArsenalValueBackup[Obj]=V end
                            pcall(function() Obj.Value=New end); Count+=1
                        end
                    end
                end
                ArsenalApplyingValues=false
                return Count
            end
            local function RestoreWeapons()
                ArsenalDisconnectModConnections()
                for T,B in pairs(State.ArsenalWeaponBackup or {}) do
                    if type(T)=="table" then for K,V in pairs(B) do pcall(function() T[K]=V end) end end
                end
                State.ArsenalWeaponBackup={}
                for Obj,Old in pairs(State.ArsenalValueBackup or {}) do
                    if Obj and Obj.Parent then pcall(function() Obj.Value=Old end) end
                end
                State.ArsenalValueBackup={}
            end
            local function ArsenalModsEnabled()
                return State.ArsenalNoRecoil or State.ArsenalNoSpread or State.ArsenalRapidFire or State.ArsenalInfiniteAmmo or State.ArsenalInstantReload or State.ArsenalAlwaysAuto or State.ArsenalInfiniteRange
            end
            local function ArsenalBindCurrentWeaponSignals()
                ArsenalDisconnectModConnections()
                if not ArsenalModsEnabled() then return end
                local Data=State.ArsenalCurrentModData or {}
                for _,Obj in ipairs(Data.Values or {}) do
                    if Obj and Obj.Parent then
                        local Ok,Connection=pcall(function()
                            return Obj:GetPropertyChangedSignal("Value"):Connect(function()
                                if ArsenalApplyingValues or not ArsenalModsEnabled() then return end
                                State.ArsenalValuePatchQueued=State.ArsenalValuePatchQueued or setmetatable({}, {__mode="k"})
                                if State.ArsenalValuePatchQueued[Obj] then return end
                                State.ArsenalValuePatchQueued[Obj]=true
                                task.delay(0.03,function()
                                    State.ArsenalValuePatchQueued[Obj]=nil
                                    if Obj and Obj.Parent and ArsenalModsEnabled() then PatchWeapons(false) end
                                end)
                            end)
                        end)
                        if Ok and Connection then table.insert(State.ArsenalModConnections,Connection) end
                    end
                end
            end
            local ArsenalRefreshQueued=false
            local function ArsenalRefreshCurrentWeapon(ForceDiscover)
                if ArsenalRefreshQueued or not ArsenalModsEnabled() then return end
                ArsenalRefreshQueued=true
                task.defer(function()
                    ArsenalRefreshQueued=false
                    if Unloaded or not ArsenalModsEnabled() then return end
                    local Before=State.ArsenalCurrentModData and State.ArsenalCurrentModData.WeaponName or ""
                    local Tool=ArsenalCurrentTool(); local Name=Tool and Tool.Name or ""
                    local Force=(ForceDiscover==true) or Name~=tostring(Before or "")
                    if Force then RestoreWeapons() end
                    if Force then State.ArsenalCurrentModData={WeaponName="",Tables={},Values={},Nodes={},At=0} end
                    PatchWeapons(Force)
                    ArsenalBindCurrentWeaponSignals()
                end)
            end
            local function ArsenalBindWeaponWatch()
                ArsenalDisconnectWeaponWatch()
                if not ArsenalModsEnabled() then return end
                local function Add(Connection)
                    if Connection then table.insert(State.ArsenalWeaponWatchConnections,Connection) end
                end
                local function Watch(Container)
                    if not Container then return end
                    Add(Container.ChildAdded:Connect(function(Obj)
                        if Obj:IsA("Tool") then
                            if Container==Character() then State.ArsenalLastWeaponName=Obj.Name end
                            task.delay(0.05,function() ArsenalRefreshCurrentWeapon(true) end)
                        end
                    end))
                    Add(Container.ChildRemoved:Connect(function(Obj)
                        if Obj:IsA("Tool") then task.delay(0.05,function() ArsenalRefreshCurrentWeapon(true) end) end
                    end))
                end
                Watch(Character())
                Watch(Player:FindFirstChildOfClass("Backpack"))
                Add(Player.CharacterAdded:Connect(function()
                    task.delay(0.20,function()
                        if ArsenalModsEnabled() and not Unloaded then
                            State.ArsenalWeaponDataCache={}
                            State.ArsenalLastWeaponName=nil
                            ArsenalBindWeaponWatch()
                            ArsenalRefreshCurrentWeapon(true)
                        end
                    end)
                end))
            end
            local function ArsenalRebuildWeaponMods(ForceDiscover)
                StopLoop("ArsenalWeaponMods")
                RestoreWeapons()
                ArsenalDisconnectWeaponWatch()
                if not ArsenalModsEnabled() then return end
                if ForceDiscover then State.ArsenalCurrentModData={WeaponName="",Tables={},Values={},Nodes={},At=0} end
                local C=PatchWeapons(ForceDiscover==true)
                ArsenalBindCurrentWeaponSignals()
                ArsenalBindWeaponWatch()
                if C==0 then
                    task.defer(function() Notify("Arsenal","Waiting for the current weapon data. Switch/equip a gun and BananiHub will apply the mods automatically.") end)
                end
                -- Sparse watchdog only. Normal weapon changes are handled by ChildAdded/ChildRemoved events.
                StartLoop("ArsenalWeaponMods",function()
                    local Tool=ArsenalCurrentTool(); local Name=Tool and Tool.Name or ""
                    local Current=State.ArsenalCurrentModData or {}
                    if Name~=tostring(Current.WeaponName or "") then ArsenalRefreshCurrentWeapon(true) end
                end,12.0)
            end
            local function SyncArsenalWeaponMods(ForceScan)
                ArsenalRebuildWeaponMods(ForceScan==true)
            end

            DetectedTab:CreateSection("AIM")
            DetectedTab:CreateDropdown({Name="Aim Part",Options={"Head","HeadHB","HumanoidRootPart","UpperTorso"},CurrentOption={State.ArsenalAimPart},Callback=function(O) State.ArsenalAimPart=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateSlider({Name="Aim FOV",Range={20,800},Increment=10,Suffix=" px",CurrentValue=State.ArsenalFOV,Callback=function(V) State.ArsenalFOV=V end})
            DetectedTab:CreateSlider({Name="Aim Smoothness",Range={1,30},Increment=1,CurrentValue=State.ArsenalSmooth,Callback=function(V) State.ArsenalSmooth=V end})
            DetectedTab:CreateToggle({Name="Team Check",Flag="GameProfile_Arsenal_Team",CurrentValue=State.ArsenalTeamCheck,Callback=function(V) State.ArsenalTeamCheck=V end})
            DetectedTab:CreateToggle({Name="Visible Only",Flag="GameProfile_Arsenal_Visible",CurrentValue=State.ArsenalVisibleOnly,Callback=function(V) State.ArsenalVisibleOnly=V end})
            DetectedTab:CreateToggle({Name="Aim Assist",Flag="GameProfile_Arsenal_Aim",CurrentValue=false,Callback=function(V) if V then StartLoop("ArsenalAim",AimStep,0.04) else StopLoop("ArsenalAim") end end})
            DetectedTab:CreateSlider({Name="Trigger Delay",Range={0.01,0.5},Increment=0.01,Suffix=" s",CurrentValue=State.ArsenalTriggerDelay,Callback=function(V) State.ArsenalTriggerDelay=V end})
            DetectedTab:CreateToggle({Name="Triggerbot",Flag="GameProfile_Arsenal_Trigger",CurrentValue=false,Callback=function(V) if V then StartLoop("ArsenalTrigger",TriggerStep,function() return math.max(tonumber(State.ArsenalTriggerDelay) or 0.05,0.04) end) else StopLoop("ArsenalTrigger") end end})

            DetectedTab:CreateSection("AIM DISPLAY + FILTERS")
            Runtime.ProfileAimOptions(DetectedTab,"Arsenal",function() local _,Part=ArsenalTarget(); return Part end,function(Cam) return Cam.ViewportSize/2 end)
            DetectedTab:CreateSection("HITBOX + ESP")
            DetectedTab:CreateSlider({Name="Hitbox Size",Range={1,20},Increment=0.5,Suffix=" studs",CurrentValue=State.ArsenalHitboxSize,Callback=function(V) State.ArsenalHitboxSize=V end})
            DetectedTab:CreateToggle({Name="Hitbox Expander",Flag="GameProfile_Arsenal_Hitbox",CurrentValue=false,Callback=function(V) if V then StartLoop("ArsenalHitbox",ApplyHitboxes,0.55) else StopLoop("ArsenalHitbox"); RestoreHitboxes() end end})
            DetectedTab:CreateButton({Name="Open Enemy Player ESP Settings",Callback=function() Window:SelectTab("Visuals") end})
            DetectedTab:CreateDropdown({Name="Target Player",Options=ArsenalNames(),CurrentOption={},SearchBarEnabled=true,DynamicOptions=ArsenalNames,Callback=function(O) State.ArsenalTargetPlayer=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateButton({Name="Go To Target Player",Callback=function() local P=State.ArsenalTargetPlayer and FindPlayerByDisplayName(State.ArsenalTargetPlayer); if P and ArsenalEnemy(P) then MoveTo(P.Character,CFrame.new(0,2,5)) else Notify("Arsenal","Select a live enemy player.") end end})

            DetectedTab:CreateSection("WEAPON RUNTIME MODS")
            DetectedTab:CreateToggle({Name="No Recoil",Flag="GameProfile_Arsenal_NoRecoil",CurrentValue=false,Callback=function(V) State.ArsenalNoRecoil=V; SyncArsenalWeaponMods(false) end})
            DetectedTab:CreateToggle({Name="No Spread",Flag="GameProfile_Arsenal_NoSpread",CurrentValue=false,Callback=function(V) State.ArsenalNoSpread=V; SyncArsenalWeaponMods(false) end})
            DetectedTab:CreateToggle({Name="Rapid Fire",Flag="GameProfile_Arsenal_Rapid",CurrentValue=false,Callback=function(V) State.ArsenalRapidFire=V; SyncArsenalWeaponMods(false) end})
            DetectedTab:CreateToggle({Name="Infinite Ammo",Flag="GameProfile_Arsenal_Ammo",CurrentValue=false,Callback=function(V) State.ArsenalInfiniteAmmo=V; SyncArsenalWeaponMods(false) end})
            DetectedTab:CreateToggle({Name="Instant Reload",Flag="GameProfile_Arsenal_Reload",CurrentValue=false,Callback=function(V) State.ArsenalInstantReload=V; SyncArsenalWeaponMods(false) end})
            DetectedTab:CreateToggle({Name="Always Auto",Flag="GameProfile_Arsenal_Auto",CurrentValue=false,Callback=function(V) State.ArsenalAlwaysAuto=V; SyncArsenalWeaponMods(false) end})
            DetectedTab:CreateToggle({Name="Infinite Range",Flag="GameProfile_Arsenal_Range",CurrentValue=false,Callback=function(V) State.ArsenalInfiniteRange=V; SyncArsenalWeaponMods(false) end})
            DetectedTab:CreateButton({Name="Refresh Current Weapon Mods",Callback=function()
                task.spawn(function()
                    SyncArsenalWeaponMods(true)
                    Notify("Arsenal","Current weapon configuration refreshed without a full-game scan.")
                end)
            end})
            DetectedTab:CreateButton({Name="Restore Weapon Tables",Callback=function()
                StopLoop("ArsenalWeaponMods")
                State.ArsenalNoRecoil=false; State.ArsenalNoSpread=false; State.ArsenalRapidFire=false; State.ArsenalInfiniteAmmo=false; State.ArsenalInstantReload=false; State.ArsenalAlwaysAuto=false; State.ArsenalInfiniteRange=false
                for _,F in ipairs({"GameProfile_Arsenal_NoRecoil","GameProfile_Arsenal_NoSpread","GameProfile_Arsenal_Rapid","GameProfile_Arsenal_Ammo","GameProfile_Arsenal_Reload","GameProfile_Arsenal_Auto","GameProfile_Arsenal_Range"}) do pcall(function() Runtime.SetFlagValue(F,false) end) end
                RestoreWeapons()
            end})

            DetectedTab:CreateSection("MOVEMENT + WORLD")
            DetectedTab:CreateToggle({Name="Fly",Flag="GameProfile_Arsenal_Fly",CurrentValue=FlyEnabled,Callback=function(V) Runtime.SetFlagValue("Player_Fly",V) end})
            DetectedTab:CreateToggle({Name="No Clip",Flag="GameProfile_Arsenal_Noclip",CurrentValue=NoclipEnabled,Callback=function(V) Runtime.SetFlagValue("Player_Noclip",V) end})
            DetectedTab:CreateToggle({Name="Infinite Jump",Flag="GameProfile_Arsenal_InfJump",CurrentValue=InfiniteJumpEnabled,Callback=function(V) Runtime.SetFlagValue("Player_InfiniteJump",V) end})
            DetectedTab:CreateToggle({Name="Fast Walk",Flag="GameProfile_Arsenal_Speed",CurrentValue=FastWalkEnabled,Callback=function(V) Runtime.SetFlagValue("Player_FastWalk",V) end})
            DetectedTab:CreateToggle({Name="Fullbright",Flag="GameProfile_Arsenal_Fullbright",CurrentValue=false,Callback=function(V) Runtime.SetFlagValue("Visuals_Fullbright",V) end})
            DetectedTab:CreateToggle({Name="Performance Mode",Flag="GameProfile_Arsenal_Performance",CurrentValue=false,Callback=function(V) Runtime.SetFlagValue("Visuals_LowGraphics",V) end})
            DetectedTab:CreateToggle({Name="Bunny Hop",Flag="GameProfile_Arsenal_Bhop",CurrentValue=false,Callback=function(V)
                if V then StartLoop("ArsenalBhop",function() local H=Humanoid(); if H and H.FloorMaterial~=Enum.Material.Air then H.Jump=true end end,0.08) else StopLoop("ArsenalBhop") end
            end})
            DetectedTab:CreateToggle({Name="Auto Pickup Health / Ammo",Flag="GameProfile_Arsenal_Pickups",CurrentValue=false,Callback=function(V)
                if V then StartLoop("ArsenalPickups",function()
                    local R=Root(); if not R then return end
                    local Params=OverlapParams.new(); Params.FilterType=Enum.RaycastFilterType.Exclude; Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
                    local Ok,Parts=pcall(function() return workspace:GetPartBoundsInRadius(R.Position,90,Params) end)
                    if not Ok then return end
                    local Best,Dist=nil,math.huge; local Seen={}
                    for _,Part in ipairs(Parts or {}) do
                        local Candidate=Part
                        local Parent=Part.Parent
                        local Label=string.lower(tostring(Part.Name).." "..tostring(Parent and Parent.Name or ""))
                        if MatchKeywords(Label,{"ammo","health","medkit","pickup"}) then
                            local Key=Parent or Part
                            if not Seen[Key] then
                                Seen[Key]=true; local D=(R.Position-Part.Position).Magnitude
                                if D<Dist then Best,Dist=Candidate,D end
                            end
                        end
                    end
                    if Best then TouchObject(Best) end
                end,1.0) else StopLoop("ArsenalPickups") end
            end})
            DetectedTab:CreateParagraph({Title="Arsenal Profile",Content="Low-lag profile: gun mods patch only the equipped weapon/config instead of rescanning every weapon, aim scans are cached, ESP is throttled, and nearby pickups use spatial queries."})

            do
                Runtime.ArsenalESPCleanup=function()
                    for P,R in pairs(State.ArsenalESPRecords or {}) do
                        if type(R)=="table" then
                            if R.Highlight then pcall(function() R.Highlight:Destroy() end) end
                            if R.Tag then pcall(function() R.Tag:Destroy() end) end
                        end
                        State.ArsenalESPRecords[P]=nil
                    end
                end
                -- Removed legacy custom Arsenal ESP renderer; the profile uses the shared,
                -- throttled Runtime.ApplyProfilePlayerESP implementation.
                Runtime.ArsenalRestoreValueMods=function()
                    for Obj,Old in pairs(State.ArsenalValueBackup or {}) do
                        if Obj and Obj.Parent then pcall(function() Obj.Value=Old end) end
                    end
                    State.ArsenalValueBackup={}
                end
                DetectedTab:CreateSection("ADVANCED ARSENAL")
                DetectedTab:CreateSlider({Name="Enemy ESP Range",Range={100,5000},Increment=100,Suffix=" studs",CurrentValue=State.ArsenalESPRange,Callback=function(V) State.ArsenalESPRange=V end})
                DetectedTab:CreateToggle({Name="Enemy ESP + Health + Distance",Flag="GameProfile_Arsenal_ESP",CurrentValue=false,Callback=function(V)
                    StopLoop("ArsenalESP"); Runtime.ArsenalESPCleanup()
                    if Runtime.ApplyProfilePlayerESP then Runtime.ApplyProfilePlayerESP(V,ArsenalEnemy) end
                end})
                DetectedTab:CreateToggle({Name="Lock Aim To Selected Player",Flag="GameProfile_Arsenal_LockSelected",CurrentValue=false,Callback=function(V) State.ArsenalLockSelected=V end})
                DetectedTab:CreateButton({Name="Tween To Selected Player",Callback=function()
                    local P=State.ArsenalTargetPlayer and FindPlayerByDisplayName(State.ArsenalTargetPlayer)
                    if P and ArsenalEnemy(P) then MoveTo(P.Character,CFrame.new(0,2,5)) else Notify("Arsenal","Select a live enemy player.") end
                end})
                DetectedTab:CreateSlider({Name="Strafe Radius",Range={5,20},Increment=1,Suffix=" studs",CurrentValue=8,Callback=function(V) State.ArsenalStrafeRadius=V end})
                DetectedTab:CreateToggle({Name="Auto Strafe Selected Target",Flag="GameProfile_Arsenal_Strafe",CurrentValue=false,Callback=function(V)
                    if V then StartLoop("ArsenalStrafe",function() local P=State.ArsenalTargetPlayer and FindPlayerByDisplayName(State.ArsenalTargetPlayer); local PR=P and ArsenalEnemy(P) and P.Character:FindFirstChild("HumanoidRootPart"); if not PR then return end; local A=os.clock()*2.2; local Radius=tonumber(State.ArsenalStrafeRadius) or 8; local Pos=PR.Position+Vector3.new(math.cos(A)*Radius,1.5,math.sin(A)*Radius); ProfileTravelToCFrame(CFrame.lookAt(Pos,PR.Position)) end,0.16) else StopLoop("ArsenalStrafe") end
                end})
                DetectedTab:CreateToggle({Name="Auto Knife / Melee Close Enemy",Flag="GameProfile_Arsenal_CloseMelee",CurrentValue=false,Callback=function(V)
                    if V then StartLoop("ArsenalCloseMelee",function() local R0=Root(); if not R0 then return end; local Best,D=nil,12; for _,P in ipairs(Runtime.CachedPlayers()) do if ArsenalEnemy(P) then local PR=P.Character:FindFirstChild("HumanoidRootPart"); local X=PR and (R0.Position-PR.Position).Magnitude or math.huge; if X<D then Best,D=P,X end end end; if Best then local T=EquipTool("Knife",false) or EquipTool("Melee",false) or EquipTool("Any Tool",false); if T then pcall(function() T:Activate() end) end end end,0.12) else StopLoop("ArsenalCloseMelee") end
                end})
                DetectedTab:CreateButton({Name="Arsenal Runtime Status",Callback=function()
                    local Events=ReplicatedStorage:FindFirstChild("Events")
                    local HitPart=Events and Events:FindFirstChild("HitPart")
                    local Weapons=ReplicatedStorage:FindFirstChild("Weapons")
                    Notify("Arsenal","HitPart event: "..tostring(HitPart~=nil).." • Weapons folder: "..tostring(Weapons~=nil).." • value backups: "..tostring((function() local n=0; for _ in pairs(State.ArsenalValueBackup) do n+=1 end; return n end)()))
                end})
            end


-- ==================================================================
-- [BH:PRISON] PRISON LIFE PROFILE
-- Items, GunStates, teams, doors, combat helpers and movement.
-- ==================================================================
        elseif Kind == "PrisonLife" then

            do
                local function Remote(Name)
                    local F=workspace:FindFirstChild("Remote")
                    return F and F:FindFirstChild(Name)
                end
                local function Names()
                    local O={}
                    for _,P in ipairs(Runtime.CachedPlayers()) do if P~=Player and P.Character then table.insert(O,P.DisplayName.." (@"..P.Name..")") end end
                    table.sort(O); return O
                end
                local function Selected()
                    return State.PrisonTargetPlayer and FindPlayerByDisplayName(State.PrisonTargetPlayer) or nil
                end
                local function CallItemHandler(Pickup)
                    if not Pickup then return false end
                    local R=Remote("ItemHandler")
                    if not R then return false end
                    if R:IsA("RemoteFunction") then return pcall(function() R:InvokeServer(Pickup) end) end
                    if R:IsA("RemoteEvent") then return pcall(function() R:FireServer(Pickup) end) end
                    return false
                end

                local PrisonWeaponAnchors={
                    ["M9"]=CFrame.new(820.2584838867188,102.8799819946289,2229.033447265625),
                    ["Remington 870"]=CFrame.new(820.2584838867188,102.8799819946289,2229.033447265625),
                    ["AK-47"]=CFrame.new(-931.7821044921875,96.368408203125,2039.4932861328125),
                    ["M4A1"]=CFrame.new(847.034912109375,102.88017272949219,2228.777587890625),
                }
                State.PrisonArmoryWeapons=State.PrisonArmoryWeapons or {"M9","Remington 870","AK-47"}
                State.PrisonArmoryTravelMode=State.PrisonArmoryTravelMode or "Smooth Tween"
                local function ExactGunPickup(Name)
                    local Items=workspace:FindFirstChild("Prison_ITEMS")
                    local G=Items and Items:FindFirstChild("giver")
                    local Node=G and G:FindFirstChild(tostring(Name))
                    return Node and Node:FindFirstChild("ITEMPICKUP") or nil
                end
                local function PrisonWeaponGoal(Name)
                    local Pickup=ExactGunPickup(Name)
                    if Pickup and Pickup:IsA("BasePart") then return Pickup.CFrame*CFrame.new(0,2.4,0),Pickup end
                    local CF=PrisonWeaponAnchors[tostring(Name)]
                    return CF and (CF*CFrame.new(0,2.4,0)) or nil,Pickup
                end
                local function HasGunTool(Name)
                    local Wanted=string.lower(tostring(Name or ""))
                    for _,Container in ipairs({Player.Character,Player:FindFirstChildOfClass("Backpack")}) do
                        if Container then
                            for _,Obj in ipairs(Container:GetChildren()) do
                                if Obj:IsA("Tool") then
                                    local N=string.lower(Obj.Name)
                                    if N==Wanted or string.find(N,Wanted,1,true) or string.find(Wanted,N,1,true) then return true,Obj end
                                end
                            end
                        end
                    end
                    return false,nil
                end
                local function PrisonArmoryTravel(CF)
                    if not CF then return false end
                    Runtime.Movement.Guard()
                    local Mode=tostring(State.PrisonArmoryTravelMode or "Smooth Tween")
                    return Runtime.ProfileSmartTravel(CF,nil,{Mode=Mode,Source="PrisonArmory"})==true
                end
                local function CollectPrisonGunAt(Name,ReturnAfter,ReturnCF)
                    if HasGunTool(Name) then return true end
                    local Goal,Pickup=PrisonWeaponGoal(Name)
                    if not Goal then return false end
                    if not ReturnCF then local R0=Root(); ReturnCF=R0 and R0.CFrame or nil end
                    if Runtime.SetAutomationState then Runtime.SetAutomationState("PrisonGunPickup","Traveling","Going to "..tostring(Name)) end
                    if not PrisonArmoryTravel(Goal) then
                        if Runtime.SetAutomationState then Runtime.SetAutomationState("PrisonGunPickup","Recovering","Could not reach "..tostring(Name)) end
                        return false
                    end
                    Runtime.Movement.Guard()
                    Pickup=ExactGunPickup(Name) or Pickup
                    if Runtime.SetAutomationState then Runtime.SetAutomationState("PrisonGunPickup","Working","Collecting "..tostring(Name)) end
                    local Deadline=os.clock()+2.8
                    local Got=HasGunTool(Name)
                    while not Got and os.clock()<Deadline and not Unloaded do
                        Pickup=ExactGunPickup(Name) or Pickup
                        if Pickup then CallItemHandler(Pickup) end
                        task.wait(0.16)
                        Got=HasGunTool(Name)
                    end
                    if ReturnAfter and ReturnCF and Root() then
                        if Runtime.SetAutomationState then Runtime.SetAutomationState("PrisonGunPickup","Traveling","Returning to saved position") end
                        PrisonArmoryTravel(ReturnCF)
                    end
                    if Runtime.SetAutomationState then Runtime.SetAutomationState("PrisonGunPickup",Got and "Idle" or "Recovering",Got and "" or (tostring(Name).." was not added to Backpack")) end
                    return Got==true
                end
                local function GetGun(Name)
                    local R0=Root(); local ReturnCF=R0 and R0.CFrame or nil
                    return CollectPrisonGunAt(Name,true,ReturnCF)
                end
                local function SmartArmoryRun(Weapons)
                    local R0=Root(); if not R0 then return false end
                    local ReturnCF=R0.CFrame
                    local Pending={}
                    for _,Name in ipairs(type(Weapons)=="table" and Weapons or {}) do
                        if PrisonWeaponAnchors[Name] and not HasGunTool(Name) then table.insert(Pending,Name) end
                    end
                    if #Pending==0 then Notify("Prison Life","Selected armory weapons are already owned."); return true end
                    local Ordered={}
                    local CurrentPos=R0.Position
                    while #Pending>0 do
                        local BestIndex,BestDistance=1,math.huge
                        for I,Name in ipairs(Pending) do
                            local Goal=PrisonWeaponGoal(Name)
                            local D=Goal and (CurrentPos-Goal.Position).Magnitude or math.huge
                            if D<BestDistance then BestIndex,BestDistance=I,D end
                        end
                        local Name=table.remove(Pending,BestIndex)
                        table.insert(Ordered,Name)
                        local Goal=PrisonWeaponGoal(Name); if Goal then CurrentPos=Goal.Position end
                    end
                    local GotCount=0
                    for _,Name in ipairs(Ordered) do
                        if Unloaded then break end
                        if CollectPrisonGunAt(Name,false,ReturnCF) then GotCount+=1 end
                    end
                    if ReturnCF and Root() then
                        if Runtime.SetAutomationState then Runtime.SetAutomationState("PrisonArmoryRun","Traveling","Returning to saved position") end
                        PrisonArmoryTravel(ReturnCF)
                    end
                    if Runtime.SetAutomationState then Runtime.SetAutomationState("PrisonArmoryRun","Idle","") end
                    Notify("Prison Life","Smart Armory Run finished • "..tostring(GotCount).."/"..tostring(#Ordered).." collected.")
                    return GotCount==#Ordered
                end
                Runtime.PrisonSmartArmoryRun=SmartArmoryRun
                local function SetTeam(ColorName)
                    local R=Remote("TeamEvent")
                    if not R then return false end
                    if R:IsA("RemoteEvent") then return pcall(function() R:FireServer(ColorName) end) end
                    if R:IsA("RemoteFunction") then return pcall(function() R:InvokeServer(ColorName) end) end
                    return false
                end
                local function TargetPart(P)
                    local C=P and P.Character
                    return C and (C:FindFirstChild("Head") or C:FindFirstChild("HumanoidRootPart") or C:FindFirstChild("Torso") or C:FindFirstChild("UpperTorso")) or nil
                end
                local function GunStateTables(Force)
                    local Cache=State.PrisonGunStateCache or {At=0,Tables={}}
                    State.PrisonGunStateCache=Cache
                    if not Force and os.clock()-(tonumber(Cache.At) or 0)<1.5 and type(Cache.Tables)=="table" and #Cache.Tables>0 then return Cache.Tables end
                    local Out={}; local Seen={}
                    for _,Container in ipairs({Player.Character,Player:FindFirstChildOfClass("Backpack")}) do
                        if Container then
                            for _,Tool in ipairs(Container:GetChildren()) do
                                if Tool:IsA("Tool") then
                                    local M=Tool:FindFirstChild("GunStates",true)
                                    if M and M:IsA("ModuleScript") and not Seen[M] then
                                        local Ok,T=pcall(require,M)
                                        if Ok and type(T)=="table" then Seen[M]=true; table.insert(Out,T) end
                                    end
                                end
                            end
                        end
                    end
                    Cache.At=os.clock(); Cache.Tables=Out
                    return Out
                end
                local function PrisonGunValueObjects()
                    local Out={}
                    for _,Container in ipairs({Player.Character,Player:FindFirstChildOfClass("Backpack")}) do
                        if Container then
                            for _,Obj in ipairs(Container:GetDescendants()) do
                                if Obj:IsA("NumberValue") or Obj:IsA("IntValue") or Obj:IsA("BoolValue") then
                                    local L=string.lower(Obj.Name)
                                    if MatchKeywords(L,{"recoil","kick","spread","accuracy","firerate","fire rate","reload","ammo","clip","magazine","autofire","automatic","range"}) then table.insert(Out,Obj) end
                                end
                            end
                        end
                    end
                    return Out
                end
                local function RestoreGunMods()
                    for T,B in pairs(State.PrisonGunBackup or {}) do
                        if type(T)=="table" and type(B)=="table" then for K,V in pairs(B) do pcall(function() T[K]=V end) end end
                    end
                    for Obj,V in pairs(State.PrisonValueBackup or {}) do if Obj and Obj.Parent then pcall(function() Obj.Value=V end) end end
                    State.PrisonGunBackup={}; State.PrisonValueBackup={}
                end
                Runtime.PrisonRestoreGunMods=RestoreGunMods
                local function PrisonPatchedValue(Key,V)
                    local Raw=tostring(Key)
                    local L=string.lower(Raw); local New=nil

                    -- Common Prison Life GunStates fields used by public implementations:
                    -- MaxAmmo, CurrentAmmo, StoredAmmo, FireRate, Spread, Range,
                    -- Bullets, ReloadTime, AutoFire. "Bullets" is recognized but not
                    -- modified because BananiHub has no pellet-count toggle.
                    if type(V)=="number" then
                        if State.PrisonInfiniteAmmo and (Raw=="MaxAmmo" or Raw=="CurrentAmmo" or Raw=="StoredAmmo") then return math.max(V,999) end
                        if State.PrisonRapidFire and Raw=="FireRate" then return (V>10 and math.max(V,1000) or 0.02) end
                        if State.PrisonNoSpread and Raw=="Spread" then return 0 end
                        if State.PrisonInstantReload and Raw=="ReloadTime" then return 0 end
                        if State.PrisonLongRange and Raw=="Range" then return math.max(V,10000) end
                    elseif type(V)=="boolean" and State.PrisonAutoFire and Raw=="AutoFire" then
                        return true
                    end
                    if State.PrisonNoRecoil and MatchKeywords(L,{"recoil","kick","camshake","viewkick"}) and type(V)=="number" then New=0 end
                    if State.PrisonNoSpread and MatchKeywords(L,{"spread","bloom","deviation","inaccuracy"}) and type(V)=="number" then New=0 end
                    if State.PrisonRapidFire and MatchKeywords(L,{"firerate","fire rate","shotdelay","cooldown","delay"}) and type(V)=="number" then New=(V>10 and math.max(V,1000) or 0.02) end
                    if State.PrisonInfiniteAmmo and MatchKeywords(L,{"maxammo","currentammo","storedammo","ammo","clip","magazine","reserve"}) and type(V)=="number" then New=math.max(V,999) end
                    if State.PrisonInstantReload and string.find(L,"reload",1,true) and type(V)=="number" then New=0 end
                    if State.PrisonAutoFire and (string.find(L,"autofire",1,true) or string.find(L,"automatic",1,true) or L=="auto") and type(V)=="boolean" then New=true end
                    if State.PrisonLongRange and string.find(L,"range",1,true) and type(V)=="number" then New=math.max(V,10000) end
                    return New
                end
                local function PatchGunMods(Force)
                    local Count=0
                    for _,T in ipairs(GunStateTables(Force)) do
                        State.PrisonGunBackup[T]=State.PrisonGunBackup[T] or {}
                        local B=State.PrisonGunBackup[T]
                        for K,V in pairs(T) do
                            local New=PrisonPatchedValue(K,V)
                            if New~=nil and New~=V then
                                if B[K]==nil then B[K]=V end
                                pcall(function() T[K]=New end); Count+=1
                            end
                        end
                    end
                    for _,Obj in ipairs(PrisonGunValueObjects()) do
                        local V=Obj.Value; local New=PrisonPatchedValue(Obj.Name,V)
                        if New~=nil and New~=V then
                            if State.PrisonValueBackup[Obj]==nil then State.PrisonValueBackup[Obj]=V end
                            pcall(function() Obj.Value=New end); Count+=1
                        end
                    end
                    return Count
                end
                local function SyncGunModLoop(Force)
                    local On=State.PrisonNoRecoil or State.PrisonNoSpread or State.PrisonRapidFire or State.PrisonInfiniteAmmo or State.PrisonInstantReload or State.PrisonAutoFire or State.PrisonLongRange
                    if On then
                        if Force then State.PrisonGunStateCache={At=0,Tables={}} end
                        PatchGunMods(Force==true)
                        StartLoop("PrisonGunMods",function() PatchGunMods(false) end,1.0)
                    else
                        StopLoop("PrisonGunMods"); RestoreGunMods()
                    end
                end
                local function Arrest(P)
                    local Part=TargetPart(P); local R=Remote("arrest")
                    if not Part or not R then return false end
                    if R:IsA("RemoteFunction") then return pcall(function() R:InvokeServer(Part) end) end
                    if R:IsA("RemoteEvent") then return pcall(function() R:FireServer(Part) end) end
                    return false
                end
                local function Melee(P)
                    local R=ReplicatedStorage:FindFirstChild("meleeEvent")
                    if not P or not R then return false end
                    if R:IsA("RemoteEvent") then return pcall(function() R:FireServer(P) end) end
                    if R:IsA("RemoteFunction") then return pcall(function() R:InvokeServer(P) end) end
                    return false
                end

                Runtime.PrisonESPCleanup=function()
                    for P,Rec in pairs(State.PrisonESPRecords or {}) do
                        if type(Rec)=="table" then
                            if Rec.Highlight then pcall(function() Rec.Highlight:Destroy() end) end
                            if Rec.Tag then pcall(function() Rec.Tag:Destroy() end) end
                        end
                        State.PrisonESPRecords[P]=nil
                    end
                end
                -- Removed legacy custom Prison ESP renderer; the profile uses the shared
                -- profile-player ESP path and cleanup API.
                DetectedTab:CreateSection("PRISON LIFE • TEAM + ARMORY")
                DetectedTab:CreateDropdown({Name="Team",Options={"Inmates","Guards","Neutral"},CurrentOption={State.PrisonTeam},Callback=function(O) State.PrisonTeam=type(O)=="table" and O[1] or O end})
                DetectedTab:CreateButton({Name="Switch To Selected Team",Callback=function()
                    local Map={Inmates="Bright orange",Guards="Bright blue",Neutral="Medium stone grey"}
                    if not SetTeam(Map[State.PrisonTeam] or "Bright orange") then Notify("Prison Life","TeamEvent was not available.") end
                end})
                DetectedTab:CreateDropdown({Name="Gun",Options={"M9","Remington 870","AK-47","M4A1"},CurrentOption={State.PrisonGun},Callback=function(O) State.PrisonGun=type(O)=="table" and O[1] or O end})
                DetectedTab:CreateDropdown({Name="Armory Route Weapons",Options={"M9","Remington 870","AK-47","M4A1"},CurrentOption=State.PrisonArmoryWeapons,MultipleOptions=true,Callback=function(O) State.PrisonArmoryWeapons=type(O)=="table" and O or {} end})
                DetectedTab:CreateDropdown({Name="Armory Travel",Options={"Smooth Tween","Teleport"},CurrentOption={State.PrisonArmoryTravelMode},Callback=function(O) State.PrisonArmoryTravelMode=type(O)=="table" and O[1] or O end})
                DetectedTab:CreateButton({Name="Get Selected Gun + Return",Callback=function() if not GetGun(State.PrisonGun) then Notify("Prison Life","Could not collect "..tostring(State.PrisonGun).." from its exact giver path.") end end})
                DetectedTab:CreateButton({Name="Run Smart Armory Route",Callback=function() task.spawn(function() SmartArmoryRun(State.PrisonArmoryWeapons) end) end})
                DetectedTab:CreateButton({Name="Get Standard Guns + Return Once",Callback=function() task.spawn(function() SmartArmoryRun({"M9","Remington 870","AK-47"}) end) end})

                DetectedTab:CreateSection("PRISON LIFE • LOOSE ITEMS")
                DetectedTab:CreateButton({Name="Pick Up Loose Items",Callback=function()
                    local I=workspace:FindFirstChild("Prison_ITEMS"); local S=I and I:FindFirstChild("single"); local N=0
                    if S then for _,O in ipairs(S:GetChildren()) do local P=O:FindFirstChild("ITEMPICKUP"); if P and CallItemHandler(P) then N+=1; task.wait(0.04) end end end
                    Notify("Prison Life","Requested "..N.." loose item(s).")
                end})
                DetectedTab:CreateToggle({Name="Auto Pick Up Loose Items",Flag="GameProfile_Prison_AutoLoose",CurrentValue=false,Callback=function(V)
                    if V then StartLoop("PrisonAutoLoose",function() local I=workspace:FindFirstChild("Prison_ITEMS"); local S=I and I:FindFirstChild("single"); if S then for _,O in ipairs(S:GetChildren()) do local P=O:FindFirstChild("ITEMPICKUP"); if P then CallItemHandler(P) end end end end,1.0) else StopLoop("PrisonAutoLoose") end
                end})

                DetectedTab:CreateSection("PRISON LIFE • PLAYERS")
                DetectedTab:CreateDropdown({Name="Target Player",Options=Names(),CurrentOption={},SearchBarEnabled=true,DynamicOptions=Names,Callback=function(O) State.PrisonTargetPlayer=type(O)=="table" and O[1] or O end})
                DetectedTab:CreateButton({Name="Teleport To Target",Callback=function() local P=Selected(); if P and P.Character then MoveTo(P.Character,CFrame.new(0,2,4)) else Notify("Prison Life","Select a live player.") end end})
                DetectedTab:CreateButton({Name="Arrest Selected",Callback=function() if not Arrest(Selected()) then Notify("Prison Life","Arrest remote/target was unavailable or rejected.") end end})
                DetectedTab:CreateButton({Name="Melee Selected",Callback=function() if not Melee(Selected()) then Notify("Prison Life","meleeEvent/target was unavailable.") end end})
                DetectedTab:CreateSlider({Name="Auto Arrest Range",Range={5,40},Increment=1,Suffix=" studs",CurrentValue=State.PrisonArrestRange,Callback=function(V) State.PrisonArrestRange=V end})
                DetectedTab:CreateToggle({Name="Auto Arrest Nearby",Flag="GameProfile_Prison_AutoArrest",CurrentValue=false,Callback=function(V)
                    if V then StartLoop("PrisonAutoArrest",function() local R0=Root(); if not R0 then return end; for _,P in ipairs(Runtime.CachedPlayers()) do if P~=Player then local PP=TargetPart(P); local H=P.Character and P.Character:FindFirstChildOfClass("Humanoid"); if PP and H and H.Health>0 and (R0.Position-PP.Position).Magnitude<=State.PrisonArrestRange then Arrest(P) end end end end,0.35) else StopLoop("PrisonAutoArrest") end
                end})
                DetectedTab:CreateSlider({Name="Melee Aura Range",Range={4,25},Increment=1,Suffix=" studs",CurrentValue=State.PrisonMeleeRange,Callback=function(V) State.PrisonMeleeRange=V end})
                DetectedTab:CreateToggle({Name="Melee Aura",Flag="GameProfile_Prison_MeleeAura",CurrentValue=false,Callback=function(V)
                    if V then StartLoop("PrisonMeleeAura",function() local R0=Root(); if not R0 then return end; for _,P in ipairs(Runtime.CachedPlayers()) do if P~=Player then local PP=TargetPart(P); local H=P.Character and P.Character:FindFirstChildOfClass("Humanoid"); if PP and H and H.Health>0 and (R0.Position-PP.Position).Magnitude<=State.PrisonMeleeRange then Melee(P) end end end end,0.18) else StopLoop("PrisonMeleeAura") end
                end})

                DetectedTab:CreateSection("PRISON LIFE • GUN RUNTIME MODS")
                DetectedTab:CreateToggle({Name="No Recoil",Flag="GameProfile_Prison_NoRecoil",CurrentValue=false,Callback=function(V) State.PrisonNoRecoil=V; SyncGunModLoop(true) end})
                DetectedTab:CreateToggle({Name="No Spread",Flag="GameProfile_Prison_NoSpread",CurrentValue=false,Callback=function(V) State.PrisonNoSpread=V; SyncGunModLoop(true) end})
                DetectedTab:CreateToggle({Name="Rapid Fire",Flag="GameProfile_Prison_Rapid",CurrentValue=false,Callback=function(V) State.PrisonRapidFire=V; SyncGunModLoop(true) end})
                DetectedTab:CreateToggle({Name="Infinite Ammo",Flag="GameProfile_Prison_Ammo",CurrentValue=false,Callback=function(V) State.PrisonInfiniteAmmo=V; SyncGunModLoop(true) end})
                DetectedTab:CreateToggle({Name="Instant Reload",Flag="GameProfile_Prison_Reload",CurrentValue=false,Callback=function(V) State.PrisonInstantReload=V; SyncGunModLoop(true) end})
                DetectedTab:CreateToggle({Name="Auto Fire",Flag="GameProfile_Prison_AutoFire",CurrentValue=false,Callback=function(V) State.PrisonAutoFire=V; SyncGunModLoop(true) end})
                DetectedTab:CreateToggle({Name="Long Range",Flag="GameProfile_Prison_Range",CurrentValue=false,Callback=function(V) State.PrisonLongRange=V; SyncGunModLoop(true) end})
                DetectedTab:CreateButton({Name="Re-scan Current Gun",Callback=function() SyncGunModLoop(true) end})
                DetectedTab:CreateButton({Name="Restore Gun State",Callback=function()
                    StopLoop("PrisonGunMods")
                    State.PrisonNoRecoil=false; State.PrisonNoSpread=false; State.PrisonRapidFire=false; State.PrisonInfiniteAmmo=false; State.PrisonInstantReload=false; State.PrisonAutoFire=false; State.PrisonLongRange=false
                    for _,F in ipairs({"GameProfile_Prison_NoRecoil","GameProfile_Prison_NoSpread","GameProfile_Prison_Rapid","GameProfile_Prison_Ammo","GameProfile_Prison_Reload","GameProfile_Prison_AutoFire","GameProfile_Prison_Range"}) do pcall(function() Runtime.SetFlagValue(F,false) end) end
                    RestoreGunMods()
                end})

                DetectedTab:CreateSection("PRISON LIFE • ESP")
                DetectedTab:CreateSlider({Name="Player ESP Range",Flag="GameProfile_Prison_ESPRange",Range={100,5000},Increment=100,Suffix=" studs",CurrentValue=State.PrisonESPRange,Callback=function(V) State.PrisonESPRange=V end})
                DetectedTab:CreateToggle({Name="Prison ESP + Health + Distance",Flag="GameProfile_Prison_ESP",CurrentValue=false,Callback=function(V)
                    StopLoop("PrisonESP"); Runtime.PrisonESPCleanup()
                    if Runtime.ApplyProfilePlayerESP then Runtime.ApplyProfilePlayerESP(V,function(P)
                        local C=P and P.Character; local H=C and C:FindFirstChildOfClass("Humanoid")
                        return P~=Player and H and H.Health>0 and C:FindFirstChild("HumanoidRootPart")~=nil
                    end) end
                end})

                DetectedTab:CreateSection("PRISON LIFE • MOVEMENT")
                DetectedTab:CreateToggle({Name="Fly",Flag="GameProfile_Prison_Fly",CurrentValue=FlyEnabled,Callback=function(V) Runtime.SetFlagValue("Player_Fly",V) end})
                DetectedTab:CreateToggle({Name="No Clip",Flag="GameProfile_Prison_Noclip",CurrentValue=NoclipEnabled,Callback=function(V) Runtime.SetFlagValue("Player_Noclip",V) end})
                DetectedTab:CreateToggle({Name="Infinite Jump",Flag="GameProfile_Prison_InfJump",CurrentValue=InfiniteJumpEnabled,Callback=function(V) Runtime.SetFlagValue("Player_InfiniteJump",V) end})
                DetectedTab:CreateToggle({Name="Fast Walk",Flag="GameProfile_Prison_Speed",CurrentValue=FastWalkEnabled,Callback=function(V) Runtime.SetFlagValue("Player_FastWalk",V) end})
                DetectedTab:CreateButton({Name="Reload Character",Callback=function()
                    local R=Remote("loadchar")
                    if R and R:IsA("RemoteFunction") then pcall(function() R:InvokeServer(nil,Player.TeamColor.Name) end) else Notify("Prison Life","loadchar is not available as a RemoteFunction.") end
                end})
                DetectedTab:CreateParagraph({Title="Prison Life Profile",Content="Uses live ItemHandler/TeamEvent/arrest/meleeEvent/GunStates objects only when they exist. Prison Life has received security changes over time, so server-rejected actions fail safely instead of assuming an old remote still works."})
            end

        else
            local EnemyDrop,ToolDrop
            DetectedTab:CreateSection("🎮 ADAPTIVE COMBAT")
            EnemyDrop=DetectedTab:CreateDropdown({Name="NPC / Enemy",Options=EnemyNames(false),CurrentOption={State.SelectedEnemy},SearchBarEnabled=true,DynamicOptions=function() return EnemyNames(false) end,Callback=function(O) State.SelectedEnemy=type(O)=="table" and O[1] or O end})
            ToolDrop=DetectedTab:CreateDropdown({Name="Tool",Options=ToolNames(false),CurrentOption={State.SelectedTool},SearchBarEnabled=true,DynamicOptions=function() return ToolNames(false) end,Callback=function(O) State.SelectedTool=type(O)=="table" and O[1] or O end})
            DetectedTab:CreateButton({Name="Refresh NPCs + Tools",Callback=function()
                if EnemyDrop and EnemyDrop.Refresh then EnemyDrop:Refresh(EnemyNames(false)) end
                if ToolDrop and ToolDrop.Refresh then ToolDrop:Refresh(ToolNames(false)) end
            end})
            DetectedTab:CreateButton({Name="Go To Selected NPC",Callback=function() local E=NearestEnemy(State.SelectedEnemy,false); if E then MoveTo(E,CFrame.new(0,4,5)) else Notify("Game Profile","No matching NPC is alive.") end end})
            DetectedTab:CreateToggle({Name="Auto Use Selected Tool",Flag="GameProfile_Adaptive_Attack",CurrentValue=false,Callback=function(V)
                if V then StartLoop("AdaptiveAttack",function() UseTool(State.SelectedTool) end,0.12) else StopLoop("AdaptiveAttack") end
            end})
            DetectedTab:CreateToggle({Name="Auto Farm Selected NPC",Flag="GameProfile_Adaptive_Farm",CurrentValue=false,Callback=function(V)
                if V then StartLoop("AdaptiveFarm",function() FarmEnemy(NearestEnemy(State.SelectedEnemy,false),State.SelectedTool,5,4) end,0.18) else StopLoop("AdaptiveFarm") end
            end})
            DetectedTab:CreateSection("💎 ADAPTIVE UTILITY")
            DetectedTab:CreateButton({Name="Refresh Item Scanner",Callback=function() if Runtime.VisualEngine and Runtime.VisualEngine.RequestItemRescan then Runtime.VisualEngine.RequestItemRescan(0) end end})
            DetectedTab:CreateButton({Name="Pick Up Detected Items",Callback=function() if Runtime.VisualEngine and Runtime.VisualEngine.PickUpAllItems then Runtime.VisualEngine.PickUpAllItems() end end})
            DetectedTab:CreateToggle({Name="Auto Pick Up Detected Items",Flag="GameProfile_Adaptive_AutoPickup",CurrentValue=false,Callback=function(V)
                if V then StartLoop("AdaptiveAutoPickup",function() if Runtime.VisualEngine and Runtime.VisualEngine.PickUpAllItems then Runtime.VisualEngine.PickUpAllItems() end end,0.8) else StopLoop("AdaptiveAutoPickup") end
            end})
            DetectedTab:CreateToggle({Name="Auto Interact Nearby Prompts",Flag="GameProfile_Adaptive_AutoPrompts",CurrentValue=false,Callback=function(V)
                if V then StartLoop("AdaptiveAutoPrompts",function() local R=Root(); if not R then return end; local Best,Dist=nil,14; for _,O in ipairs(Runtime.ProfilePrompts()) do if O:IsA("ProximityPrompt") and O.Enabled then local T=string.lower(tostring(O.ActionText).." "..tostring(O.ObjectText)); local Unsafe=MatchKeywords(T,{"buy","purchase","pay","trade","accept","sell","delete"}); local PR=GetRoot(O.Parent); local D=PR and (R.Position-PR.Position).Magnitude or math.huge; if not Unsafe and D<Dist then Best,Dist=O,D end end end; if Best then UsePrompt(Best,false) end end,0.5) else StopLoop("AdaptiveAutoPrompts") end
            end})
            DetectedTab:CreateButton({Name="Open Visual Scanner",Callback=function() Window:SelectTab("Visuals") end})
            DetectedTab:CreateParagraph({Title="Adaptive Profile",Content="BananiHub does not invent private remotes for unknown games. It detects live humanoid NPCs, equipped tools and collectible items, then uses the universal movement/visual systems already in the hub."})
        end

        do
            local function HealthText()
                local Err=(State.LastLoopErrors and State.LastLoopErrors[tostring(Runtime.Movement and Runtime.Movement.Owner or "")]) or nil
                if not Err and State.LastLoopErrors then
                    for Name,Message in pairs(State.LastLoopErrors) do Err=tostring(Name)..": "..tostring(Message); break end
                end
                local Owner=Runtime.Movement and Runtime.Movement.Owner or "none"
                local Travel=Runtime.TravelFailure and tostring(Runtime.TravelFailure) or "none"
                return "Profile: "..tostring(Label or Kind or "Adaptive")
                    .."\nMovement owner: "..tostring(Owner)
                    .."\nLast travel failure: "..tostring(Travel)
                    .."\nRecorded loop error: "..tostring(Err or "none")
            end
            local Host=DetectedTab
            local Card=nil
            if Host._Dashboard and Host._DashboardColumns and #Host._DashboardColumns>0 then
                local BestIndex,BestCount=1,math.huge
                for Index,Column in ipairs(Host._DashboardColumns) do
                    local Count=0
                    for _,Child in ipairs(Column:GetChildren()) do if Child:IsA("Frame") then Count+=1 end end
                    if Count<BestCount then BestIndex,BestCount=Index,Count end
                end
                Card=Host:DashboardSection(BestIndex,"Profile Health + Recovery")
            else
                Host:CreateSection("PROFILE HEALTH + RECOVERY")
                Card=Host
            end
            local Status=Card:CreateParagraph({Title="Live Profile Health",Content=HealthText()})
            Card:CreateButton({Name="Refresh Profile Health",Callback=function()
                if Status and Status.Set then Status:Set({Title="Live Profile Health",Content=HealthText()}) end
            end})
            Card:CreateButton({Name="Recover Character + Release Movement",Callback=function()
                if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
                if Runtime.Movement then
                    Runtime.Movement.Owner=nil
                    Runtime.Movement.OwnerContext=nil
                end
                local H,R=Humanoid(),Root()
                if H then
                    pcall(function()
                        H.PlatformStand=false
                        H.Sit=false
                        if H.Health>0 then H:ChangeState(Enum.HumanoidStateType.GettingUp) end
                    end)
                end
                if R then pcall(function() R.AssemblyLinearVelocity=Vector3.zero; R.AssemblyAngularVelocity=Vector3.zero end) end
                Runtime.TravelFailure=nil
                Notify(tostring(Label or "Game Profile"),"Character state and movement lock were recovered.")
                if Status and Status.Set then Status:Set({Title="Live Profile Health",Content=HealthText()}) end
            end})
        end

        end)

        if BuildOk and ActiveModule then
            ActiveModule.API.ProfileCheck=Runtime.GameProfileCheck
            ActiveModule.API.Travel=Runtime.ProfileSmartTravel
            ActiveModule.API.Stop=function()
                local Names={}
                for LoopName in pairs(ActiveModule.Loops or {}) do Names[#Names+1]=LoopName end
                for _,LoopName in ipairs(Names) do StopLoop(LoopName) end
            end
            ActiveModule.BuiltAt=os.clock()
            ActiveModule.Ready=true
        end
        if not BuildOk then
            Runtime.DetectedGameProfileBuilt = false
            warn("BANANIHUB | detected-game tab build failed: "..tostring(BuildErr))
            pcall(function()
                DetectedTab:CreateParagraph({
                    Title="⚠️ Game Profile Safe Mode",
                    Content="The game-specific controls hit an error, but BananiHub kept loading.\n"..tostring(BuildErr)
                })
            end)
            return false
        end
        return true
    end

end

do
    Runtime.CoreActionLoops=Runtime.CoreActionLoops or {}
    Runtime.CoreActionThreads=Runtime.CoreActionThreads or {}
    Runtime.CoreStopLoop=function(Name)
        local Old=Runtime.CoreActionThreads[Name]
        Runtime.CoreActionThreads[Name]=nil
        Runtime.CoreActionLoops[Name]=(tonumber(Runtime.CoreActionLoops[Name]) or 0)+1
        if Runtime.Movement then
            Runtime.Movement.Stop(Name)
            if Old then Runtime.Movement.Contexts[Old]=nil end
        end
        if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Idle","") end
        if Old and Old~=coroutine.running() and task.cancel then pcall(task.cancel,Old) end
    end
    Runtime.CoreStartLoop=function(Name,Step,Delay)
        Runtime.CoreStopLoop(Name)
        local Token=Runtime.CoreActionLoops[Name]
        task.spawn(function()
            local This=coroutine.running()
            Runtime.CoreActionThreads[Name]=This
            local LastWorkingStatusAt=-math.huge
            while not Unloaded and Runtime.CoreActionLoops[Name]==Token do
                local M=Runtime.Movement
                local Context={Name=Name,Valid=function()
                    return not Unloaded and Runtime.CoreActionLoops[Name]==Token
                end}
                if M then M.Contexts[This]=Context end
                if Runtime.SetAutomationState and os.clock()-LastWorkingStatusAt>=0.75 then
                    local Existing=Runtime.AutomationStatus and Runtime.AutomationStatus[Name]
                    if not Existing or tostring(Existing.State or "")~="Working" or tostring(Existing.Reason or "")~="" then
                        Runtime.SetAutomationState(Name,"Working","")
                    else
                        Existing.UpdatedAt=os.clock()
                        if Runtime.ActiveAutomationName==Name then Runtime.ActiveAutomationUpdatedAt=Existing.UpdatedAt end
                    end
                    LastWorkingStatusAt=os.clock()
                end
                local StepStarted=os.clock()
                local Ok,Err=pcall(function() if M then M.Guard() end; Step() end)
                local StepSeconds=os.clock()-StepStarted
                if Runtime.RecordAutomationStep then Runtime.RecordAutomationStep(Name,Ok,StepSeconds,Err) end
                if M then
                    if M.Owner==Name and M.OwnerContext==Context then M.Release(Name) end
                    M.Contexts[This]=nil
                end
                if Unloaded or Runtime.CoreActionLoops[Name]~=Token then break end
                if not Ok then
                    local Message=tostring(Err)
                    Runtime.CoreActionErrors=Runtime.CoreActionErrors or {}
                    Runtime.CoreActionErrors[Name]=Message
                    local Health=Runtime.AutomationHealth and Runtime.AutomationHealth[Name]
                    local Consecutive=Health and tonumber(Health.ConsecutiveErrors) or 1
                    if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Recovering",Message) end
                    Runtime.CoreErrorNoticeAt=Runtime.CoreErrorNoticeAt or {}
                    if not string.find(Message,"BANANI_MOVEMENT_BUSY",1,true)
                        and not string.find(Message,"BANANI_CANCELLED",1,true)
                        and os.clock()-(Runtime.CoreErrorNoticeAt[Name] or -math.huge)>=6 then
                        Runtime.CoreErrorNoticeAt[Name]=os.clock()
                        Notify("Automation",Name..": "..string.sub(Message,1,150))
                    end
                    if not string.find(Message,"BANANI_MOVEMENT_BUSY",1,true)
                        and not string.find(Message,"BANANI_CANCELLED",1,true)
                        and Consecutive>=3 then
                        if Runtime.SetAutomationState then
                            Runtime.SetAutomationState(Name,"Recovering","Cooling down after repeated errors")
                        end
                        task.wait(math.min(0.35+(Consecutive-3)*0.25,2.0))
                    end
                end
                local DelayOK,WaitTime=pcall(function() return type(Delay)=="function" and Delay() or Delay end)
                if not DelayOK then
                    Runtime.CoreActionErrors=Runtime.CoreActionErrors or {}
                    Runtime.CoreActionErrors[Name]="Delay: "..tostring(WaitTime)
                    WaitTime=0.1
                end
                task.wait(math.max(tonumber(WaitTime) or 0.1,0.01))
            end
            if Runtime.CoreActionThreads[Name]==coroutine.running() then
                Runtime.CoreActionThreads[Name]=nil
                if Runtime.SetAutomationState then Runtime.SetAutomationState(Name,"Idle","") end
            end
        end)
    end
    Runtime.CoreStopAllLoops=function()
        local Names={}
        for Name in pairs(Runtime.CoreActionLoops) do Names[#Names+1]=Name end
        for _,Name in ipairs(Names) do Runtime.CoreStopLoop(Name) end
    end
    Runtime.GeneralToolNames=function()
        local Out={"Any Tool"}; local Seen={ ["Any Tool"]=true }
        for _,Container in ipairs({Player.Character,Player:FindFirstChildOfClass("Backpack")}) do
            if Container then
                for _,Obj in ipairs(Container:GetChildren()) do
                    if Obj:IsA("Tool") and not Seen[Obj.Name] then Seen[Obj.Name]=true; table.insert(Out,Obj.Name) end
                end
            end
        end
        table.sort(Out,function(A,B) if A=="Any Tool" then return true elseif B=="Any Tool" then return false else return string.lower(A)<string.lower(B) end end)
        return Out
    end
    Runtime.GeneralFindTool=function(Filter)
        Filter=tostring(Filter or "Any Tool")
        local Wanted=string.lower(Filter)
        local Any=Wanted=="any tool" or Wanted==""
        local Best=nil
        for _,Container in ipairs({Player.Character,Player:FindFirstChildOfClass("Backpack")}) do
            if Container then
                for _,Obj in ipairs(Container:GetDescendants()) do
                    if Obj:IsA("Tool") then
                        if Any then
                            if Obj.Parent==Player.Character then return Obj end
                            Best=Best or Obj
                        elseif string.lower(Obj.Name)==Wanted then
                            return Obj
                        end
                    end
                end
            end
        end
        return Best
    end
    Runtime.GeneralEquipTool=function(Filter)
        if Runtime.UniversalInvisibleState and Runtime.UniversalInvisibleState.Active then
            -- Popup Invisible intentionally parks the real/networked character far away.
            -- Do not fake an equip by moving or relaying that real character back to the clone.
            return nil
        end
        local Tool=Runtime.GeneralFindTool(Filter); if not Tool then return nil end
        if Tool.Parent==Player.Character then return Tool end
        if Runtime.GameProfileState and Runtime.GameProfileState.MM2Invisible and Runtime.MM2EquipRealTool then
            return Runtime.MM2EquipRealTool(Tool) and Tool or nil
        end
        local RealChar=Player.Character; local H=RealChar and RealChar:FindFirstChildOfClass("Humanoid")
        if H then pcall(function() H:EquipTool(Tool) end) end
        return Tool.Parent==RealChar and Tool or nil
    end
    Runtime.GeneralUseTool=function(Filter)
        if Runtime.UniversalInvisibleState and Runtime.UniversalInvisibleState.Active then return false end
        local Tool=Runtime.GeneralFindTool(Filter)
        if not Tool or Tool.Parent~=Player.Character then Tool=Runtime.GeneralEquipTool(Filter) end
        if not Tool then return false end
        if Runtime.GameProfileState and Runtime.GameProfileState.MM2Invisible and Runtime.MM2SurfaceToolProxy then
            return Runtime.MM2SurfaceToolProxy(nil,"primary")
        end
        local Ok=pcall(function() Tool:Activate() end)
        return Ok
    end
    local function UnsafePromptText(Text)
        Text=string.lower(tostring(Text or ""))
        for _,Word in ipairs({"buy","purchase","pay","trade","accept","sell","delete","remove","kick","ban"}) do
            if string.find(Text,Word,1,true) then return true end
        end
        return false
    end
    Runtime.GeneralNearbyPromptStep=function()
        if Runtime.UniversalInvisibleState and Runtime.UniversalInvisibleState.Active then
            -- Normal Invisible is pure Popup Invis: no server interaction relay while hidden.
            return
        end
        local R=Root(); if not R then return end
        local Radius=tonumber(Runtime.GameProfileState and Runtime.GameProfileState.ProfileExtraInteractRadius) or 12
        local Params=OverlapParams.new(); Params.FilterType=Enum.RaycastFilterType.Exclude; Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
        local Ok,Parts=pcall(function() return workspace:GetPartBoundsInRadius(R.Position,Radius,Params) end)
        if not Ok then return end
        local Best,BestDist=nil,math.huge; local Seen={}
        local function Consider(Obj)
            if not Obj or Seen[Obj] then return end; Seen[Obj]=true
            if not Obj:IsA("ProximityPrompt") or not Obj.Enabled or type(fireproximityprompt)~="function" then return end
            local Model=Obj:FindFirstAncestorOfClass("Model")
            if Model and Players:GetPlayerFromCharacter(Model) then return end
            if UnsafePromptText(tostring(Obj.ActionText).." "..tostring(Obj.ObjectText).." "..Obj.Name) then return end
            local Parent=Obj.Parent; local P=Parent and (Parent:IsA("BasePart") and Parent or Parent:FindFirstChildWhichIsA("BasePart",true))
            local D=P and (R.Position-P.Position).Magnitude or math.huge
            if D<BestDist and D<=Radius then Best,BestDist=Obj,D end
        end
        for _,Part in ipairs(Parts or {}) do
            if Part and Part.Parent then
                for _,Obj in ipairs(Part:GetDescendants()) do Consider(Obj) end
                local Parent=Part.Parent
                if Parent then for _,Obj in ipairs(Parent:GetDescendants()) do Consider(Obj) end end
            end
        end
        if Best then pcall(function() fireproximityprompt(Best) end) end
    end
    Runtime.GeneralNearbyPickupStep=function()
        if Runtime.UniversalInvisibleState and Runtime.UniversalInvisibleState.Active then
            -- Do not move the parked real avatar back for pickups while normal Invisible is ON.
            return
        end
        if Runtime.GameProfileState and Runtime.GameProfileState.MM2Invisible and Runtime.MM2SurfaceTouchStep then
            Runtime.MM2SurfaceTouchStep(); return
        end
        if type(firetouchinterest)~="function" then return end
        local R=Root(); if not R then return end
        local Radius=tonumber(Runtime.GameProfileState and Runtime.GameProfileState.ProfileExtraPickupRadius) or 10
        local Params=OverlapParams.new(); Params.FilterType=Enum.RaycastFilterType.Exclude; Params.FilterDescendantsInstances=Runtime.CharacterRaycastIgnore()
        local Ok,Parts=pcall(function() return workspace:GetPartBoundsInRadius(R.Position,Radius,Params) end)
        if not Ok then return end
        for _,Part in ipairs(Parts or {}) do
            if Part:IsA("BasePart") and Part.Parent then
                local Model=Part:FindFirstAncestorOfClass("Model")
                if not (Model and Players:GetPlayerFromCharacter(Model)) then
                    local Name=string.lower(Part.Name.." "..tostring(Part.Parent.Name))
                    local IsCandidate=Part:FindFirstChildOfClass("TouchTransmitter")~=nil or Part:FindFirstAncestorOfClass("Tool")~=nil
                        or string.find(Name,"coin",1,true) or string.find(Name,"pickup",1,true) or string.find(Name,"drop",1,true)
                        or string.find(Name,"ammo",1,true) or string.find(Name,"health",1,true) or string.find(Name,"token",1,true)
                    if IsCandidate then
                        pcall(function() firetouchinterest(R,Part,0); RunService.Heartbeat:Wait(); firetouchinterest(R,Part,1) end)
                        return
                    end
                end
            end
        end
    end
end

do
    -- Universal Invisible: internal version of the old working FE clone-swap method.
    -- Requested working architecture: real character is hidden and parked once,
    -- local decoy becomes controlled/visible, camera follows decoy, and the real
    -- character is restored to the decoy's final position when disabled.
    Runtime.UniversalInvisibleState = Runtime.UniversalInvisibleState or {
        Active=false, RealCharacter=nil, FakeCharacter=nil, Platform=nil,
        Connections={}, RealScriptStates={}, Profile=nil, Switching=false,
        TouchCooldowns=setmetatable({}, {__mode="k"}), VisiblePrompt=nil,
        ParkCFrame=nil, RelayBusy=false, RelayDepth=0, LastVisibleCFrame=nil
    }
    local U = Runtime.UniversalInvisibleState
    local State = Runtime.GameProfileState
    -- Register-safe module layout: helpers live on U instead of occupying dozens of
    -- locals in one Luau scope. This avoids the VM/compiler 200-register ceiling.

    U.Profiles = U.Profiles or {
        -- Park the real server character well outside the normal Roblox nameplate range.
        -- The real body stays here during normal movement, pickups and gun use.
        MM2={Label="Murder Mystery 2",Depth=160,Transparency=0.42},
        BloxFruits={Label="Blox Fruits",Depth=180,Transparency=0.42},
        AdoptMe={Label="Adopt Me",Depth=150,Transparency=0.42},
        BuildABoat={Label="Build A Boat For Treasure",Depth=160,Transparency=0.42},
        Bloxburg={Label="Bloxburg",Depth=150,Transparency=0.42},
        BasketballLegends={Label="Basketball Legends",Depth=150,Transparency=0.42},
        Arsenal={Label="Arsenal",Depth=160,Transparency=0.42},
        PrisonLife={Label="Prison Life",Depth=160,Transparency=0.42},
        MurderersVSSheriffs={Label="Murderers VS Sheriffs",Depth=160,Transparency=0.42},
        Adaptive={Label="Universal",Depth=150,Transparency=0.42}
    }

    function U.DisconnectAll()
        for _,C in ipairs(U.Connections or {}) do
            if C then pcall(function() C:Disconnect() end) end
        end
        U.Connections={}
    end

    function U.GetProfile()
        local Kind=tostring((Runtime and Runtime.DetectedGameProfileKind) or "Adaptive")
        local Lower=string.lower(Kind)
        if string.find(Lower,"murder",1,true) and string.find(Lower,"sheriff",1,true) then Kind="MurderersVSSheriffs"
        elseif string.find(Lower,"mm2",1,true) or string.find(Lower,"murder mystery",1,true) then Kind="MM2"
        elseif string.find(Lower,"blox",1,true) and string.find(Lower,"fruit",1,true) then Kind="BloxFruits"
        elseif string.find(Lower,"adopt",1,true) then Kind="AdoptMe"
        elseif string.find(Lower,"buildaboat",1,true) or string.find(Lower,"build a boat",1,true) then Kind="BuildABoat"
        elseif string.find(Lower,"bloxburg",1,true) then Kind="Bloxburg"
        elseif string.find(Lower,"basketball",1,true) then Kind="BasketballLegends"
        elseif string.find(Lower,"arsenal",1,true) then Kind="Arsenal"
        elseif string.find(Lower,"prison",1,true) then Kind="PrisonLife" end
        if tostring(game.PlaceId)=="155615604" then Kind="PrisonLife" end
        return U.Profiles[Kind] or U.Profiles.Adaptive,Kind
    end

    function U.DestroyInstance(Obj)
        if Obj then pcall(function() Obj:Destroy() end) end
    end

    function U.SafeCFrame(Profile,VisibleCF)
        -- Match the working Popup Invis architecture: park the real networked
        -- character at one fixed safe zone instead of underneath the decoy.
        return CFrame.new(0,math.pi*1000000,0)
    end

    function U.PrepareRealCharacter(Real)
        U.RealPartStates=setmetatable({}, {__mode="k"})
        U.RealHumanoidState=nil
        if not Real then return end
        local RH=Real:FindFirstChildOfClass("Humanoid")
        if RH then
            U.RealHumanoidState={AutoRotate=RH.AutoRotate,PlatformStand=RH.PlatformStand}
            pcall(function() RH.AutoRotate=false; RH.PlatformStand=false end)
        end
        for _,Obj in ipairs(Real:GetDescendants()) do
            if Obj:IsA("BasePart") then
                U.RealPartStates[Obj]={
                    CanCollide=Obj.CanCollide,
                    LocalTransparencyModifier=Obj.LocalTransparencyModifier,
                    Anchored=Obj.Anchored,
                }
                pcall(function()
                    Obj.CanCollide=false
                    Obj.LocalTransparencyModifier=1
                end)
            end
        end
    end

    function U.RestoreRealCharacterPhysics()
        for Obj,State in pairs(U.RealPartStates or {}) do
            if Obj and Obj.Parent then
                pcall(function()
                    Obj.CanCollide=State.CanCollide
                    Obj.LocalTransparencyModifier=State.LocalTransparencyModifier
                    Obj.Anchored=State.Anchored==true
                end)
            end
        end
        local Real=U.RealCharacter
        local RH=Real and Real.Parent and Real:FindFirstChildOfClass("Humanoid") or nil
        local State=U.RealHumanoidState
        if RH and State then pcall(function() RH.AutoRotate=State.AutoRotate; RH.PlatformStand=State.PlatformStand end) end
        U.RealPartStates=setmetatable({}, {__mode="k"})
        U.RealHumanoidState=nil
    end

    -- v5.14.76: old surface relay / touch / invisible-shoot helpers removed.
    -- Pure Popup Invisible never moves the parked real avatar back to the clone.

    function U.Restore(Silent,KeepToggle)
        if U.Switching then return false end
        U.Switching=true
        local Real=U.RealCharacter
        local Fake=U.FakeCharacter
        local Cam=workspace.CurrentCamera
        local CamCF=Cam and Cam.CFrame or nil
        local ReturnCF=U.StartCF
        if Fake and Fake.Parent then
            local FR=Fake:FindFirstChild("HumanoidRootPart")
            if FR then ReturnCF=FR.CFrame end
        end
        U.Active=false
        U.DisconnectAll()

        if Real then
            if not Real.Parent or Real.Parent~=workspace then pcall(function() Real.Parent=workspace end) end
            local RR=Real:FindFirstChild("HumanoidRootPart")
            local RH=Real:FindFirstChildOfClass("Humanoid")
            if RR and ReturnCF then pcall(function() RR.CFrame=ReturnCF end) end
            if Fake then pcall(function() Fake.Parent=game:GetService("Lighting") end) end
            pcall(function() Player.Character=Real end)
            pcall(function() Real.Parent=workspace end)
            if RR then pcall(function() RR.AssemblyLinearVelocity=Vector3.zero; RR.AssemblyAngularVelocity=Vector3.zero end) end
            U.RestoreRealCharacterPhysics()
            if Cam and RH then
                pcall(function()
                    Cam.CameraType=Enum.CameraType.Custom
                    Cam.CameraSubject=RH
                    if CamCF then Cam.CFrame=CamCF end
                end)
            end
            local Animate=Real:FindFirstChild("Animate")
            if Animate and Animate:IsA("LocalScript") then
                local WasDisabled=U.RealAnimateWasDisabled==true
                pcall(function()
                    if WasDisabled then
                        Animate.Disabled=true
                    else
                        Animate.Disabled=true
                        task.wait()
                        Animate.Disabled=false
                    end
                end)
            end
        end

        U.DestroyInstance(Fake)
        U.FakeCharacter=nil
        U.RealCharacter=nil
        U.StartCF=nil
        U.Profile=nil
        U.ProfileData=nil
        U.LastVisibleCFrame=nil
        U.ParkCFrame=nil
        U.FakeParts={}
        U.RealAnimateWasDisabled=nil
        U.Switching=false
        if not KeepToggle and Runtime.SetFlagValue then pcall(function() Runtime.SetFlagValue("Player_Invisible",false) end) end
        if not Silent then Notify("Invisible","OFF") end
        return true
    end

    function U.ResolveRealCharacter(Timeout)
        local Deadline=os.clock()+math.max(0.2,tonumber(Timeout) or 2.0)
        repeat
            local Candidate=Player.Character
            if Candidate and Candidate.Parent and Candidate~=U.FakeCharacter then
                local H=Candidate:FindFirstChildOfClass("Humanoid")
                local R=Candidate:FindFirstChild("HumanoidRootPart")
                if H and R and H.Health>0 then return Candidate end
            end
            task.wait(0.05)
        until os.clock()>=Deadline or Unloaded
        return nil
    end

    function U.CloneCharacterRobust(Real)
        if not Real then return nil,"character missing" end
        local H=Real:FindFirstChildOfClass("Humanoid")
        local R=Real:FindFirstChild("HumanoidRootPart")
        if not H or not R then return nil,"character rig incomplete" end
        local Old=Real.Archivable
        Real.Archivable=true
        local OK,Fake=pcall(function() return Real:Clone() end)
        Real.Archivable=Old
        if not OK or not Fake then return nil,"classic clone failed" end
        if not Fake:FindFirstChildOfClass("Humanoid") or not Fake:FindFirstChild("HumanoidRootPart") then
            U.DestroyInstance(Fake)
            return nil,"classic clone rig incomplete"
        end
        return Fake,"classic popup clone"
    end

    function U.Build(Real,Profile,Kind,Silent)
        if not Real or not Real.Parent then return false,"character missing" end
        local RH=Real:FindFirstChildOfClass("Humanoid")
        local RR=Real:FindFirstChild("HumanoidRootPart")
        if not RH or not RR or RH.Health<=0 then return false,"character not ready" end

        U.RealAnimateWasDisabled=nil
        local OriginalAnimate=Real:FindFirstChild("Animate")
        if OriginalAnimate and OriginalAnimate:IsA("LocalScript") then
            pcall(function() U.RealAnimateWasDisabled=OriginalAnimate.Disabled end)
        end

        local Fake,Reason=U.CloneCharacterRobust(Real)
        if not Fake then
            U.RealAnimateWasDisabled=nil
            return false,Reason
        end
        local FH=Fake:FindFirstChildOfClass("Humanoid")
        local FR=Fake:FindFirstChild("HumanoidRootPart")
        if not FH or not FR then U.DestroyInstance(Fake); return false,"clone not ready" end

        U.Profile=Kind
        U.ProfileData=Profile
        U.RealCharacter=Real
        U.FakeCharacter=Fake
        U.StartCF=RR.CFrame
        U.LastVisibleCFrame=RR.CFrame

        -- Popup Invis behavior: keep the clone outside Workspace until toggle-on,
        -- physically move the real character extremely far away first, allow the
        -- teleport to replicate for a couple physics frames, then park it in Lighting.
        Fake.Name=""
        Fake.Parent=game:GetService("Lighting")
        U.FakeParts={}
        for _,Obj in ipairs(Fake:GetDescendants()) do
            if Obj:IsA("BasePart") then
                table.insert(U.FakeParts,Obj)
                pcall(function()
                    Obj.Anchored=false
                    Obj.AssemblyLinearVelocity=Vector3.zero
                    Obj.AssemblyAngularVelocity=Vector3.zero
                    Obj.LocalTransparencyModifier=(Obj.Name=="HumanoidRootPart") and 1 or 0.50
                end)
            end
        end

        local Camera=workspace.CurrentCamera
        local CameraCF=Camera and Camera.CFrame or nil
        local VisibleCF=RR.CFrame
        U.ParkCFrame=U.SafeCFrame(Profile,VisibleCF)
        -- Pause the ORIGINAL real Animate only after the decoy clone exists.
        if OriginalAnimate and OriginalAnimate:IsA("LocalScript") and U.RealAnimateWasDisabled~=true then
            pcall(function() OriginalAnimate.Disabled=true end)
        end
        -- Hide the real avatar locally before it moves, then park it once.
        U.PrepareRealCharacter(Real)
        -- Hard-disappear behavior: first move the REAL avatar to the far park CFrame,
        -- then parent the real model into Lighting so it is completely absent from Workspace
        -- on the local client. The 50% clone is the only avatar left in Workspace.
        local ParkOK,ParkError=pcall(function()
            if Real.Parent~=workspace then Real.Parent=workspace end
            RR.Anchored=false
            Real:PivotTo(U.ParkCFrame)
            RR.CFrame=U.ParkCFrame
            RR.AssemblyLinearVelocity=Vector3.zero
            RR.AssemblyAngularVelocity=Vector3.zero
            RunService.Heartbeat:Wait()
            RunService.Heartbeat:Wait()
            RR.Anchored=true
            Real.Parent=Lighting
        end)
        if not ParkOK then
            U.DestroyInstance(Fake)
            U.FakeCharacter=nil
            U.RealCharacter=nil
            U.RestoreRealCharacterPhysics()
            return false,"real-avatar park failed: "..tostring(ParkError)
        end
        -- Instant swap: the clone stays at the activation point and becomes locally controlled.
        pcall(function() Fake.Parent=workspace end)
        pcall(function() FR.CFrame=VisibleCF end)
        pcall(function() Player.Character=Fake end)

        if Player.Character~=Fake then
            pcall(function() Fake.Parent=game:GetService("Lighting") end)
            pcall(function() Real.Parent=workspace end)
            pcall(function() RR.CFrame=VisibleCF end)
            pcall(function() Player.Character=Real end)
            U.RestoreRealCharacterPhysics()
            local RestoreAnimate=Real:FindFirstChild("Animate")
            if RestoreAnimate and RestoreAnimate:IsA("LocalScript") then
                pcall(function() RestoreAnimate.Disabled=U.RealAnimateWasDisabled==true end)
            end
            if Camera and RH then pcall(function() Camera.CameraType=Enum.CameraType.Custom; Camera.CameraSubject=RH; if CameraCF then Camera.CFrame=CameraCF end end) end
            U.DestroyInstance(Fake)
            U.FakeCharacter=nil; U.RealCharacter=nil
            return false,"character swap was blocked"
        end

        if Camera then
            pcall(function()
                Camera.CameraType=Enum.CameraType.Custom
                Camera.CameraSubject=FH
                if CameraCF then Camera.CFrame=CameraCF end
            end)
        end
        local Animate=Fake:FindFirstChild("Animate")
        if Animate and Animate:IsA("LocalScript") then pcall(function() Animate.Disabled=true; task.wait(); Animate.Disabled=false end) end

        U.Active=true
        table.insert(U.Connections,FH.Died:Connect(function()
            if U.Active and not U.Switching then task.defer(function() U.Restore(true,false) end) end
        end))
        table.insert(U.Connections,RH.Died:Connect(function()
            if U.Active and not U.Switching then task.defer(function() U.Restore(true,false) end) end
        end))
        -- Pure Popup Invis intentionally installs no E/F, mouse, tool or touch relay hooks.
        -- The real networked avatar is moved far away before being parked in Lighting
        -- until the user toggles Invisible OFF.

        -- Maintain only the classic clone/camera swap and fixed far-away park.
        local Acc=0
        table.insert(U.Connections,Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Dt)
            if not U.Active or Unloaded then return end
            Acc+=Dt
            if Acc<0.15 then return end
            Acc=0
            local LiveFake=U.FakeCharacter
            local LiveFR=LiveFake and LiveFake:FindFirstChild("HumanoidRootPart")
            local LiveFH=LiveFake and LiveFake:FindFirstChildOfClass("Humanoid")
            if LiveFR then U.LastVisibleCFrame=LiveFR.CFrame end
            if LiveFake and LiveFake.Parent and Player.Character~=LiveFake then pcall(function() Player.Character=LiveFake end) end
            for I=#(U.FakeParts or {}),1,-1 do
                local Part=U.FakeParts[I]
                if not Part or not Part.Parent then table.remove(U.FakeParts,I)
                else pcall(function() Part.LocalTransparencyModifier=(Part.Name=="HumanoidRootPart") and 1 or 0.50 end) end
            end
            local LiveReal=U.RealCharacter
            local LiveRR=LiveReal and LiveReal:FindFirstChild("HumanoidRootPart")
            if LiveReal then pcall(function() if LiveReal.Parent~=Lighting then LiveReal.Parent=Lighting end end) end
            if LiveRR and typeof(U.ParkCFrame)=="CFrame" then pcall(function()
                LiveRR.Anchored=true
                if (LiveRR.Position-U.ParkCFrame.Position).Magnitude>0.5 then
                    LiveReal:PivotTo(U.ParkCFrame)
                    LiveRR.CFrame=U.ParkCFrame
                end
                LiveRR.AssemblyLinearVelocity=Vector3.zero
                LiveRR.AssemblyAngularVelocity=Vector3.zero
                if LiveReal.Parent~=Lighting then LiveReal.Parent=Lighting end
            end) end
            local CurrentCam=workspace.CurrentCamera
            if CurrentCam and LiveFH and CurrentCam.CameraSubject~=LiveFH then pcall(function() CurrentCam.CameraType=Enum.CameraType.Custom; CurrentCam.CameraSubject=LiveFH end) end
        end),"Disconnect","UniversalInvisibleHeartbeat","UniversalInvisibleConnections"))

        if Runtime.DisguiseState and Runtime.DisguiseState.Enabled and Runtime.ApplyDisguiseCharacter then pcall(function() Runtime.ApplyDisguiseCharacter(Fake) end) end
        if not Silent then Notify("Invisible","ON") end
        return true
    end

    Runtime.SetUniversalInvisible=function(Enabled,Silent)
        Enabled=Enabled==true
        local Profile,Kind=U.GetProfile()
        -- Normal Invisible uses BananiHub's embedded Infinite Yield-style clone/swap backend.
        -- Do not run the older universal decoy builder underneath it.
        if Kind=="MM2" and Runtime.MM2SetInvisible then
            if U.Active then pcall(function() U.Restore(true,true) end) end
            local OK=Runtime.MM2SetInvisible(Enabled,Silent)
            Runtime.LastInvisibleError=if OK then nil else "Infinite Yield invis did not start"
            return OK==true
        end
        if not Enabled then
            if State and State.MM2OriginalInvisible and Runtime.MM2SetInvisible then pcall(function() Runtime.MM2SetInvisible(false,true) end) end
            return U.Restore(Silent,false)
        end
        if U.Active then return true end
        if U.Switching then return false end
        local Real=U.ResolveRealCharacter(3.0)
        if not Real then Runtime.LastInvisibleError="character did not finish loading"; return false end
        local OK,Reason=U.Build(Real,Profile,Kind,Silent)
        Runtime.LastInvisibleError=if OK then nil else tostring(Reason or "classic invis failed")
        return OK==true
    end

    Runtime.IsBananiInvisibleActive=function()
        return (State and State.MM2OriginalInvisible==true) or U.Active==true
    end

    Runtime.ForceDisableBananiInvisible=function(Silent)
        if State and State.MM2OriginalInvisible and Runtime.MM2SetInvisible then
            local OK,Result=pcall(function() return Runtime.MM2SetInvisible(false,Silent) end)
            return OK and Result~=false
        end
        local UState=Runtime.UniversalInvisibleState
        if UState and (UState.Active or UState.RealCharacter or UState.FakeCharacter) and UState.Restore then
            local OK,Result=pcall(function() return UState.Restore(Silent,false) end)
            return OK and Result~=false
        end
        State.MM2OriginalInvisible=false; State.MM2Invisible=false
        return true
    end
    Runtime.SyncInvisibleFlags=function(Enabled)
        if Runtime.InvisibleFlagSyncing then return end
        Runtime.InvisibleFlagSyncing=true
        for _,FlagName in ipairs({"Player_Invisible","GameProfile_MM2_Invisible"}) do
            local Flag=Rayfield and Rayfield.Flags and Rayfield.Flags[FlagName]
            if Flag and Flag.Set then pcall(function() Flag:Set(Enabled==true) end) end
        end
        Runtime.InvisibleFlagSyncing=false
    end
    Runtime.SetBananiInvisible=function(Enabled,Silent)
        Enabled=Enabled==true
        if Runtime.InvisibleTransitionBusy then
            local Current=Runtime.IsBananiInvisibleActive and Runtime.IsBananiInvisibleActive() or false
            if Runtime.SyncInvisibleFlags then Runtime.SyncInvisibleFlags(Current) end
            return false
        end
        Runtime.InvisibleTransitionBusy=true
        local CallOK,Ok=pcall(function()
            if not Enabled then
                return Runtime.ForceDisableBananiInvisible and Runtime.ForceDisableBananiInvisible(Silent)~=false
            elseif Runtime.MM2SetInvisible then
                -- Normal Invisible is intentionally the embedded Infinite Yield-style clone/swap path.
                -- Do not substitute the newer universal clone/hybrid implementation.
                return Runtime.MM2SetInvisible(true,Silent)==true
            end
            return false
        end)
        if not CallOK then
            Runtime.LastInvisibleError=tostring(Ok or "invisible transition failed")
            Ok=false
        end
        local Active=Runtime.IsBananiInvisibleActive and Runtime.IsBananiInvisibleActive() or false
        pcall(function() if Runtime.SyncInvisibleFlags then Runtime.SyncInvisibleFlags(Active) end end)
        if Runtime.RefreshFavoriteCard then task.defer(function() pcall(Runtime.RefreshFavoriteCard) end) end
        Runtime.InvisibleTransitionBusy=false
        return Ok==true
    end

    Runtime.ToggleBananiInvisible=function(Silent)
        -- Keyboard and Favorites both use this one toggle. Keep the busy flag from
        -- ever getting stuck if a game/executor throws while the character is swapping.
        if Runtime.InvisibleToggleBusy then
            return false, Runtime.IsBananiInvisibleActive and Runtime.IsBananiInvisibleActive() or false
        end
        Runtime.InvisibleToggleBusy=true
        local Active=Runtime.IsBananiInvisibleActive and Runtime.IsBananiInvisibleActive() or false
        local Target=not Active
        local CallOK,Result=pcall(function()
            return Runtime.SetBananiInvisible and Runtime.SetBananiInvisible(Target,Silent)==true
        end)
        if not CallOK then Runtime.LastInvisibleError=tostring(Result or "invisible toggle failed") end
        local Ok=CallOK and Result==true
        local NowActive=Runtime.IsBananiInvisibleActive and Runtime.IsBananiInvisibleActive() or false
        if Runtime.SyncInvisibleFlags then Runtime.SyncInvisibleFlags(NowActive) end
        if Runtime.RefreshFavoriteCard then task.defer(function() pcall(Runtime.RefreshFavoriteCard) end) end
        Runtime.InvisibleToggleBusy=false
        return Ok,NowActive
    end

end

-- Local disguise system based on v5.14.56.
-- No companion server script is required. Copy Avatar applies the selected
-- player's current HumanoidDescription to the locally controlled character
-- and mirrors the description's locomotion animation ids.
do
    Runtime.DisguiseState = Runtime.DisguiseState or {}
    local D=Runtime.DisguiseState
    D.Enabled=D.Enabled==true
    D.Mode=D.Mode
    D.TargetUserId=D.TargetUserId or Runtime.DisguiseTargetUserId
    D.Syncing=false
    D.CharacterConnection=D.CharacterConnection
    D.OriginalDescription=D.OriginalDescription
    D.AppliedDescription=D.AppliedDescription
    Runtime.LastDisguiseError=nil

    Runtime.RefreshDisguisePlayers=function()
        Runtime.DisguisePlayerMap={}
        local Options={}
        for _,Target in ipairs(Players:GetPlayers()) do
            if Target~=Player then
                local Label=tostring(Target.DisplayName).." (@"..tostring(Target.Name)..")"
                Runtime.DisguisePlayerMap[Label]=Target
                Options[#Options+1]=Label
            end
        end
        table.sort(Options,function(A,B) return string.lower(A)<string.lower(B) end)
        if #Options==0 then Options[1]="No other players in server" end
        return Options
    end

    function D.GetTarget()
        local Id=tonumber(D.TargetUserId or Runtime.DisguiseTargetUserId)
        if not Id then return nil end
        for _,Target in ipairs(Players:GetPlayers()) do
            if Target.UserId==Id then return Target end
        end
        return nil
    end

    function D.DestroyDescription(Desc)
        if Desc then pcall(function() Desc:Destroy() end) end
    end

    function D.CloneCurrentDescription(Character)
        local Humanoid=Character and Character:FindFirstChildOfClass("Humanoid")
        if not Humanoid then return nil end
        local Desc=nil
        pcall(function() Desc=Humanoid:GetAppliedDescription() end)
        if Desc then
            local Copy=nil
            pcall(function() Copy=Desc:Clone() end)
            D.DestroyDescription(Desc)
            return Copy
        end
        return nil
    end

    function D.GetTargetDescription(Target)
        if not Target then return nil,"Selected player is no longer in the server" end
        local Desc=D.CloneCurrentDescription(Target.Character)
        if Desc then return Desc,nil end
        local OK,Result=pcall(function()
            return Players:GetHumanoidDescriptionFromUserId(Target.UserId)
        end)
        if OK and Result then return Result,nil end
        return nil,"Could not read that player's avatar"
    end

    function D.SetAnimationId(Container,Name,AssetId)
        local Id=tonumber(AssetId)
        if not Container or not Id or Id<=0 then return end
        local Obj=Container:FindFirstChild(Name)
        if Obj and Obj:IsA("Animation") then
            pcall(function() Obj.AnimationId="rbxassetid://"..tostring(math.floor(Id)) end)
        end
    end

    function D.AnimationTable(Desc)
        if not Desc then return {} end
        return {
            IdleAnimation=tonumber(Desc.IdleAnimation) or 0,
            WalkAnimation=tonumber(Desc.WalkAnimation) or 0,
            RunAnimation=tonumber(Desc.RunAnimation) or 0,
            JumpAnimation=tonumber(Desc.JumpAnimation) or 0,
            FallAnimation=tonumber(Desc.FallAnimation) or 0,
            ClimbAnimation=tonumber(Desc.ClimbAnimation) or 0,
            SwimAnimation=tonumber(Desc.SwimAnimation) or 0,
        }
    end

    function D.RefreshAnimations(AnimationIds,Character)
        task.spawn(function()
            Character=Character or Player.Character
            local Humanoid=Character and Character:FindFirstChildOfClass("Humanoid")
            if not Character or not Humanoid then return end
            AnimationIds=type(AnimationIds)=="table" and AnimationIds or {}

            pcall(function()
                Humanoid.PlatformStand=false
                Humanoid.Sit=false
                Humanoid.AutoRotate=true
                if not Humanoid:FindFirstChildOfClass("Animator") then Instance.new("Animator",Humanoid) end
                for _,Track in ipairs(Humanoid:GetPlayingAnimationTracks()) do Track:Stop(0) end
                Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
            end)

            local Animate=Character:FindFirstChild("Animate")
            if Animate and Animate:IsA("LocalScript") then
                local Idle=Animate:FindFirstChild("idle")
                if Idle then
                    D.SetAnimationId(Idle,"Animation1",AnimationIds.IdleAnimation)
                    D.SetAnimationId(Idle,"Animation2",AnimationIds.IdleAnimation)
                end
                local Walk=Animate:FindFirstChild("walk")
                if Walk then D.SetAnimationId(Walk,"WalkAnim",AnimationIds.WalkAnimation) end
                local Run=Animate:FindFirstChild("run")
                if Run then D.SetAnimationId(Run,"RunAnim",AnimationIds.RunAnimation) end
                local Jump=Animate:FindFirstChild("jump")
                if Jump then D.SetAnimationId(Jump,"JumpAnim",AnimationIds.JumpAnimation) end
                local Fall=Animate:FindFirstChild("fall")
                if Fall then D.SetAnimationId(Fall,"FallAnim",AnimationIds.FallAnimation) end
                local Climb=Animate:FindFirstChild("climb")
                if Climb then D.SetAnimationId(Climb,"ClimbAnim",AnimationIds.ClimbAnimation) end
                local Swim=Animate:FindFirstChild("swim")
                if Swim then D.SetAnimationId(Swim,"Swim",AnimationIds.SwimAnimation) end
                local SwimIdle=Animate:FindFirstChild("swimidle")
                if SwimIdle then D.SetAnimationId(SwimIdle,"SwimIdle",AnimationIds.SwimAnimation) end

                pcall(function() Animate.Disabled=true end)
                RunService.Heartbeat:Wait()
                if Player.Character==Character and Animate.Parent==Character then
                    pcall(function() Animate.Disabled=false end)
                end
            end

            if Player.Character==Character and Humanoid.Health>0 then
                pcall(function() Humanoid:ChangeState(Enum.HumanoidStateType.Running) end)
            end
        end)
    end

    function D.EnsureOriginal(Character)
        if D.OriginalDescription then return D.OriginalDescription end
        D.OriginalDescription=D.CloneCurrentDescription(Character or Player.Character)
        return D.OriginalDescription
    end

    function D.BuildBaconDescription(Character)
        local Base=D.CloneCurrentDescription(Character or Player.Character) or D.EnsureOriginal(Character)
        if not Base then
            local OK,Desc=pcall(function() return Players:GetHumanoidDescriptionFromUserId(Player.UserId) end)
            if OK then Base=Desc end
        elseif Base==D.OriginalDescription then
            local Copy=nil
            pcall(function() Copy=Base:Clone() end)
            Base=Copy or Base
        end
        if not Base then return nil,"Could not build bacon avatar" end

        pcall(function()
            Base.HairAccessory="63690008"
            Base.HatAccessory=""
            Base.FaceAccessory=""
            Base.NeckAccessory=""
            Base.ShouldersAccessory=""
            Base.FrontAccessory=""
            Base.BackAccessory=""
            Base.WaistAccessory=""
            Base.Shirt=144076358
            Base.Pants=144076760
            Base.GraphicTShirt=0
            Base.Face=86487700
        end)

        local Original=D.OriginalDescription
        if Original then
            pcall(function()
                Base.IdleAnimation=Original.IdleAnimation
                Base.WalkAnimation=Original.WalkAnimation
                Base.RunAnimation=Original.RunAnimation
                Base.JumpAnimation=Original.JumpAnimation
                Base.FallAnimation=Original.FallAnimation
                Base.ClimbAnimation=Original.ClimbAnimation
                Base.SwimAnimation=Original.SwimAnimation
            end)
        end
        return Base,nil
    end

    function D.ApplyDescription(Desc,Character)
        Character=Character or Player.Character
        local Humanoid=Character and Character:FindFirstChildOfClass("Humanoid")
        if not Character or not Humanoid or not Desc then return false,"Character is not ready" end
        D.EnsureOriginal(Character)

        local OK,Err=pcall(function()
            if Humanoid.ApplyDescriptionReset then
                Humanoid:ApplyDescriptionReset(Desc)
            else
                Humanoid:ApplyDescription(Desc)
            end
        end)
        if not OK then
            OK,Err=pcall(function() Humanoid:ApplyDescription(Desc) end)
        end
        if not OK then return false,tostring(Err or "ApplyDescription failed") end

        D.DestroyDescription(D.AppliedDescription)
        pcall(function() D.AppliedDescription=Desc:Clone() end)
        D.RefreshAnimations(D.AnimationTable(Desc),Character)
        return true,nil
    end

    function D.Restore(Character)
        Character=Character or Player.Character
        local Original=D.OriginalDescription
        if not Original then return true end
        local RestoreCopy=nil
        pcall(function() RestoreCopy=Original:Clone() end)
        RestoreCopy=RestoreCopy or Original
        local OK,Err=D.ApplyDescription(RestoreCopy,Character)
        if RestoreCopy~=Original then D.DestroyDescription(RestoreCopy) end
        if not OK then return false,Err end
        D.DestroyDescription(D.AppliedDescription)
        D.AppliedDescription=nil
        D.DestroyDescription(D.OriginalDescription)
        D.OriginalDescription=nil
        return true,nil
    end

    Runtime.SetDisguiseTarget=function(Choice)
        local Label=type(Choice)=="table" and Choice[1] or Choice
        Runtime.RefreshDisguisePlayers()
        local Target=Runtime.DisguisePlayerMap and Runtime.DisguisePlayerMap[Label]
        if not Target then
            Runtime.LastDisguiseError="Select a player who is still in the server"
            return false
        end
        D.TargetUserId=Target.UserId
        Runtime.DisguiseTargetUserId=Target.UserId
        Runtime.DisguiseTargetLabel=Label

        if D.Enabled and D.Mode=="Copy" then
            local Desc,Err=D.GetTargetDescription(Target)
            if not Desc then Runtime.LastDisguiseError=Err; return false end
            local OK,ApplyErr=D.ApplyDescription(Desc)
            D.DestroyDescription(Desc)
            if not OK then Runtime.LastDisguiseError=ApplyErr; return false end
        end
        Runtime.LastDisguiseError=nil
        return true
    end

    function D.SetMode(Mode,Enabled,Silent)
        Enabled=Enabled==true
        if not Enabled then
            if D.Mode==Mode then
                local OK,Err=D.Restore()
                if not OK then
                    Runtime.LastDisguiseError=Err
                    if not Silent then Notify(Mode=="Bacon" and "Bacon Disguise" or "Copy Avatar",Err) end
                    return false
                end
                D.Enabled=false
                D.Mode=nil
            end
            if not Silent then Notify(Mode=="Bacon" and "Bacon Disguise" or "Copy Avatar","OFF") end
            return true
        end

        local Character=Player.Character
        local Humanoid=Character and Character:FindFirstChildOfClass("Humanoid")
        if not Character or not Humanoid then
            Runtime.LastDisguiseError="Character is not ready"
            return false
        end

        D.EnsureOriginal(Character)
        local Desc,Err=nil,nil
        local Target=nil
        if Mode=="Copy" then
            Target=D.GetTarget()
            if not Target then
                Runtime.LastDisguiseError="Pick a player in Copy Avatar Player first"
                if not Silent then Notify("Copy Avatar",Runtime.LastDisguiseError) end
                return false
            end
            Desc,Err=D.GetTargetDescription(Target)
        else
            Desc,Err=D.BuildBaconDescription(Character)
        end
        if not Desc then
            Runtime.LastDisguiseError=Err or "Could not build disguise"
            return false
        end

        local OK,ApplyErr=D.ApplyDescription(Desc,Character)
        D.DestroyDescription(Desc)
        if not OK then
            Runtime.LastDisguiseError=ApplyErr
            if not Silent then Notify(Mode=="Bacon" and "Bacon Disguise" or "Copy Avatar",ApplyErr) end
            return false
        end

        D.Enabled=true
        D.Mode=Mode
        Runtime.LastDisguiseError=nil
        D.Syncing=true
        if Runtime.SetFlagValue then
            if Mode=="Copy" then
                pcall(function() Runtime.SetFlagValue("Player_BaconDisguise",false) end)
            elseif Mode=="Bacon" then
                pcall(function() Runtime.SetFlagValue("Player_Disguise",false) end)
            end
        end
        D.Syncing=false

        if not Silent then
            if Mode=="Copy" then
                Notify("Copy Avatar","ON • copied @"..tostring(Target and Target.Name or "player"))
            else
                Notify("Bacon Disguise","ON")
            end
        end
        return true
    end

    Runtime.SetCopyAvatar=function(Enabled,Silent)
        return D.SetMode("Copy",Enabled,Silent)
    end
    Runtime.SetBaconDisguise=function(Enabled,Silent)
        return D.SetMode("Bacon",Enabled,Silent)
    end
    Runtime.SetDisguise=Runtime.SetCopyAvatar

    function Runtime.ApplyDisguiseCharacter(Character)
        if not D.Enabled then return false end
        task.defer(function()
            if Unloaded or not Character or not Character.Parent then return end
            local Desc=nil
            if D.Mode=="Copy" then
                local Target=D.GetTarget()
                if Target then Desc=D.GetTargetDescription(Target) end
            elseif D.Mode=="Bacon" then
                Desc=D.BuildBaconDescription(Character)
            end
            if Desc then
                D.ApplyDescription(Desc,Character)
                D.DestroyDescription(Desc)
            end
        end)
        return true
    end

    Runtime.ClearDisguise=function()
        if D.Enabled then pcall(function() D.Restore() end) end
        D.Enabled=false
        D.Mode=nil
        D.DestroyDescription(D.AppliedDescription)
        D.AppliedDescription=nil
        D.DestroyDescription(D.OriginalDescription)
        D.OriginalDescription=nil
    end

    if D.CharacterConnection then pcall(function() D.CharacterConnection:Disconnect() end) end
    D.CharacterConnection=Player.CharacterAdded:Connect(function(Character)
        if Unloaded then return end
        task.delay(0.35,function()
            if Unloaded or Player.Character~=Character then return end
            D.OriginalDescription=nil
            D.AppliedDescription=nil
            if D.Enabled then Runtime.ApplyDisguiseCharacter(Character) end
        end)
    end)
end

-- Copy Movement uses the same selected player as Copy Avatar.
-- It mirrors the target player's world-space movement direction, walk speed,
-- jump timing and sitting state while leaving the local player at their own
-- position. Disabling it restores the local Humanoid settings it changed.
do
    Runtime.CopyMovementState = Runtime.CopyMovementState or {}
    local M=Runtime.CopyMovementState
    M.Enabled=M.Enabled==true
    M.Connection=M.Connection
    M.Character=M.Character
    M.Humanoid=M.Humanoid
    M.Original=M.Original or nil
    M.LastTargetState=M.LastTargetState
    Runtime.LastCopyMovementError=nil

    function M.GetTarget()
        local D=Runtime.DisguiseState
        if D and D.GetTarget then return D.GetTarget() end
        local Id=tonumber(D and D.TargetUserId or Runtime.DisguiseTargetUserId)
        if not Id then return nil end
        for _,Target in ipairs(Players:GetPlayers()) do
            if Target.UserId==Id then return Target end
        end
        return nil
    end

    function M.Capture(Humanoid,Character)
        if M.Humanoid==Humanoid and M.Original then return end
        M.Character=Character
        M.Humanoid=Humanoid
        M.Original={
            WalkSpeed=Humanoid.WalkSpeed,
            AutoRotate=Humanoid.AutoRotate,
            UseJumpPower=Humanoid.UseJumpPower,
            JumpPower=Humanoid.JumpPower,
            JumpHeight=Humanoid.JumpHeight,
            Sit=Humanoid.Sit,
        }
    end

    function M.RestoreHumanoid()
        local H=M.Humanoid
        local O=M.Original
        if H and H.Parent then
            pcall(function() H:Move(Vector3.zero,false) end)
            pcall(function() H.Jump=false end)
            if O then
                pcall(function() H.WalkSpeed=O.WalkSpeed end)
                pcall(function() H.AutoRotate=O.AutoRotate end)
                pcall(function() H.UseJumpPower=O.UseJumpPower end)
                pcall(function() H.JumpPower=O.JumpPower end)
                pcall(function() H.JumpHeight=O.JumpHeight end)
                pcall(function() H.Sit=O.Sit end)
            end
        end
        M.Character=nil
        M.Humanoid=nil
        M.Original=nil
        M.LastTargetState=nil
    end

    function M.Stop(Silent)
        M.Enabled=false
        if M.Connection then pcall(function() M.Connection:Disconnect() end) end
        M.Connection=nil
        M.RestoreHumanoid()
        Runtime.LastCopyMovementError=nil
        if not Silent then Notify("Copy Movement","OFF") end
        return true
    end

    function M.Step()
        if Unloaded or not M.Enabled then return end
        local Target=M.GetTarget()
        if not Target then
            Runtime.LastCopyMovementError="Selected player left the server"
            task.defer(function()
                M.Stop(true)
                if Runtime.SetFlagValue then pcall(function() Runtime.SetFlagValue("Player_CopyMovement",false) end) end
                Notify("Copy Movement","Selected player left the server.")
            end)
            return
        end

        local TargetCharacter=Target.Character
        local TargetHumanoid=TargetCharacter and TargetCharacter:FindFirstChildOfClass("Humanoid")
        local Character=Player.Character
        local Humanoid=Character and Character:FindFirstChildOfClass("Humanoid")
        if not Character or not Humanoid or Humanoid.Health<=0 then return end
        if not TargetCharacter or not TargetHumanoid or TargetHumanoid.Health<=0 then
            pcall(function() Humanoid:Move(Vector3.zero,false) end)
            return
        end

        M.Capture(Humanoid,Character)
        local Direction=TargetHumanoid.MoveDirection
        if typeof(Direction)~="Vector3" then Direction=Vector3.zero end

        pcall(function()
            Humanoid.AutoRotate=true
            Humanoid.WalkSpeed=TargetHumanoid.WalkSpeed
            Humanoid.UseJumpPower=TargetHumanoid.UseJumpPower
            if TargetHumanoid.UseJumpPower then
                Humanoid.JumpPower=TargetHumanoid.JumpPower
            else
                Humanoid.JumpHeight=TargetHumanoid.JumpHeight
            end
            Humanoid:Move(Direction,false)
        end)

        local State=nil
        pcall(function() State=TargetHumanoid:GetState() end)
        if State==Enum.HumanoidStateType.Jumping and M.LastTargetState~=Enum.HumanoidStateType.Jumping then
            pcall(function() Humanoid.Jump=true end)
        end
        if TargetHumanoid.Sit~=Humanoid.Sit then
            pcall(function() Humanoid.Sit=TargetHumanoid.Sit end)
        end
        M.LastTargetState=State
    end

    Runtime.SetCopyMovement=function(Enabled,Silent)
        Enabled=Enabled==true
        if not Enabled then return M.Stop(Silent) end
        if M.Enabled then return true end
        local Target=M.GetTarget()
        if not Target then
            Runtime.LastCopyMovementError="Pick a player in Copy Avatar Player first"
            if not Silent then Notify("Copy Movement",Runtime.LastCopyMovementError) end
            return false
        end
        M.Enabled=true
        Runtime.LastCopyMovementError=nil
        if M.Connection then pcall(function() M.Connection:Disconnect() end) end
        M.Connection=Runtime.TrackCleanup(RunService.Heartbeat:Connect(M.Step),"Disconnect","CopyMovementHeartbeat","Connections")
        if not Silent then Notify("Copy Movement","ON • mimicking @"..tostring(Target.Name)) end
        return true
    end

    Runtime.ClearCopyMovement=function()
        return M.Stop(true)
    end
end


