        -- after rebinding it. A held-key lock guarantees one toggle per key press.
        if Unloaded or UserInputService:GetFocusedTextBox() then return end
        local Now=os.clock()
        if Now < (tonumber(Runtime.InvisibleKeyIgnoreUntil) or 0) then return end
        local Key=Enum.KeyCode[Runtime.InvisibleKeyName or State.MM2InvisibleKeyName or "V"]
        if Key and Input.KeyCode==Key and not Runtime.InvisibleKeyHeld then
            Runtime.InvisibleKeyHeld=true
