local TeleportToolName = "Banani Teleporter"
local function RemoveTeleportTool()
    local Backpack = Player:FindFirstChildOfClass("Backpack")
    local C = Character()
    local BackpackTool = Backpack and Backpack:FindFirstChild(TeleportToolName)
    local EquippedTool = C and C:FindFirstChild(TeleportToolName)
    if BackpackTool then BackpackTool:Destroy() end
    if EquippedTool then EquippedTool:Destroy() end
end
local function GiveTeleportTool()
    local Backpack = Player:FindFirstChildOfClass("Backpack")
    if not Backpack then
        Notify("Teleport Tool", "Your Backpack is not ready.")
        return
    end
    RemoveTeleportTool()
    local Tool = Instance.new("Tool")
    Tool.Name = TeleportToolName
    Tool.ToolTip = "Click anywhere to teleport"
    Tool.RequiresHandle = false
    Tool.CanBeDropped = false
    Tool.Parent = Backpack
    local Mouse = Player:GetMouse()
    local Cooldown = false

    TrackConnection(Tool.Activated:Connect(function()
        if Cooldown then return end
        local R = Root()
        if not R or not Mouse.Hit then return end
        Cooldown = true
        local Destination=CFrame.new(Mouse.Hit.Position + Vector3.new(0,3,0))
        if Runtime.TravelToCFrame then Runtime.TravelToCFrame(Destination,"Teleport","TeleportTool") else SafeTeleport(Destination) end
        task.delay(0.25, function() Cooldown = false end)
    end))
    Notify("🍌 Teleport Tool", "Equip Banani Teleporter and click anywhere.")
end

Runtime.GetRouteRemoveOptions = function()
    local Options = {}
    for Index, Name in ipairs(Runtime.WaypointRoute) do
        table.insert(Options, tostring(Index) .. ". " .. Name)
    end
    return Options
end
Runtime.RefreshRouteDropdowns = function()
    if Runtime.RouteAddDropdown then
        Runtime.RouteAddDropdown:Refresh(GetWaypointNames())
    end
    if Runtime.RouteRemoveDropdown then
        Runtime.RouteRemoveDropdown:Refresh(Runtime.GetRouteRemoveOptions())
    end
end
Runtime.UpdateRouteUI = function()
    local Route = Runtime.WaypointRoute
    local Lines = {}
    for Index, Name in ipairs(Route) do
        local Marker = ""
        if Runtime.RouteRunning and Index == Runtime.RouteCurrentIndex then
            Marker = Runtime.RoutePaused and "  ← Paused here" or "  ← Current"
        end
        table.insert(Lines, tostring(Index) .. ". " .. tostring(Name) .. Marker)
    end

    if Runtime.RoutePreviewParagraph then
    local RouteName = "Current Route"
        Runtime.RoutePreviewParagraph:Set({
            Title = "Current Route • " .. RouteName .. " (" .. tostring(#Route)
                .. (#Route == 1 and " Stop)" or " Stops)"),
            Content = #Lines > 0 and table.concat(Lines, "\n") or "No session waypoints added yet."
        })
    end

    local Total = #Route
    local DisplayIndex = 0
    if Total > 0 then
        if Runtime.RouteStatus == "Completed" then
            DisplayIndex = Total
        elseif Runtime.RouteRunning then
            DisplayIndex = math.clamp(Runtime.RouteCurrentIndex, 1, Total)
        end
    end

    local Segments = 10
    local Filled = Total > 0 and math.floor((DisplayIndex / Total) * Segments + 0.5) or 0
    Filled = math.clamp(Filled, 0, Segments)
    local ProgressBar = string.rep("█", Filled) .. string.rep("░", Segments - Filled)
    local CurrentName = (Total > 0 and Route[math.clamp(Runtime.RouteCurrentIndex, 1, Total)]) or "None"
    local NextName = "Finish"
    if Total > 0 and Runtime.RouteCurrentIndex < Total then
        NextName = tostring(Route[Runtime.RouteCurrentIndex + 1])
    end

    local ProgressContent =
        ProgressBar
        .. "  " .. tostring(DisplayIndex) .. " / " .. tostring(Total)
        .. "\nCurrent: " .. tostring(CurrentName)
        .. "\nNext: " .. tostring(NextName)

    if Runtime.RouteProgressParagraph then
        Runtime.RouteProgressParagraph:Set({
            Title = "🧭 Route Progress",
            Content = ProgressContent
        })
    end

    if Runtime.RouteStatusParagraph then
        local CheckpointText = Total > 0
            and (tostring(math.clamp(Runtime.RouteCurrentIndex, 1, Total)) .. " / " .. tostring(Total))
            or "0 / 0"
        local SpeedLine = ""
        if Runtime.RouteTravelMode == "Smooth Tween" or Runtime.RouteTravelMode == "Tween" then
            SpeedLine = "\nTween Speed: " .. tostring(Runtime.TweenSpeed) .. " studs/s"
        elseif Runtime.RouteTravelMode == "Walk" then
            local CurrentH = Humanoid()
            SpeedLine = "\nWalk Speed: " .. tostring(CurrentH and CurrentH.WalkSpeed or WalkSpeed)
        end
        Runtime.RouteStatusParagraph:Set({
            Title = "Route Status",
            Content =
                "Status: " .. tostring(Runtime.RouteStatus)
                .. "\nRoute: Current Route"
                .. "\nMode: " .. (Runtime.RouteLoop and "Loop Route" or "Play Once")
                .. "\nWaypoint: " .. CheckpointText
                .. "\nTravel: " .. tostring(Runtime.RouteTravelMode)
                .. SpeedLine
                .. "\nFailure: " .. tostring(Runtime.RouteFailureRule)
                .. (Runtime.RouteFailureRule == "Retry"
                    and (" (" .. tostring(Runtime.RouteRetryCount) .. "/" .. tostring(Runtime.RouteRetryLimit) .. ")")
                    or "")
                .. "\nStart: " .. (Runtime.RouteStartFromNearest and "Nearest waypoint" or "Waypoint 1")
                .. "\nRespawn Resume: " .. (Runtime.RouteResumeAfterRespawn and "On" or "Off")
                .. "\nDelay: " .. tostring(Runtime.RouteDelay)
                .. (Runtime.RouteDelay == 1 and " Second" or " Seconds")
        })
    end

    Runtime.RefreshRouteDropdowns()
end

Runtime.FindNearestRouteIndex = function()
    local R = Root()
    if not R or #Runtime.WaypointRoute == 0 then return 1 end
    local BestIndex = 1
    local BestDistance = math.huge
    for Index, Name in ipairs(Runtime.WaypointRoute) do
        local CF = DecodeCFrame(Waypoints[Name])
        if CF then
            local Distance = (R.Position - CF.Position).Magnitude
            if Distance < BestDistance then
                BestDistance = Distance
                BestIndex = Index
            end
        end
    end
    return BestIndex
end

Runtime.ReverseWaypointRoute = function()
    if #Runtime.WaypointRoute < 2 then
        Notify("Route", "Add at least two waypoints before reversing.")
        return
    end
    if Runtime.RouteRunning then
        Notify("Route", "Stop the running route before reversing it.")
        return
    end
    local Left = 1
    local Right = #Runtime.WaypointRoute
    while Left < Right do
        Runtime.WaypointRoute[Left], Runtime.WaypointRoute[Right] =
            Runtime.WaypointRoute[Right], Runtime.WaypointRoute[Left]
        Left += 1
        Right -= 1
    end
    Runtime.RouteCurrentIndex = 1
    Runtime.RouteSelectedCheckpoint = nil
    Runtime.UpdateRouteUI()
    Notify("Route", "Route order reversed.")
end

Runtime.HandleRouteFailure = function(ThisRun, WaypointName, Reason)
    if not Runtime.RouteRunning or Runtime.RouteRunId ~= ThisRun then
        return "stop"
    end

    local Rule = Runtime.RouteFailureRule or "Stop Route"
    local Label = tostring(WaypointName or "waypoint")
    local Why = tostring(Reason or "Could not reach destination")

    if Rule == "Retry" then
        Runtime.RouteRetryCount += 1
        if Runtime.RouteRetryCount <= Runtime.RouteRetryLimit then
            Runtime.RouteStatus =
                "Retrying " .. tostring(Runtime.RouteRetryCount)
                .. "/" .. tostring(Runtime.RouteRetryLimit)
            Runtime.UpdateRouteUI()
            Notify(
                "Route Retry",
                Label .. " failed. Retrying "
                    .. tostring(Runtime.RouteRetryCount) .. "/"
                    .. tostring(Runtime.RouteRetryLimit) .. "."
            )
            task.wait(0.25)
            return "retry"
        end

        Runtime.RoutePaused = true
        Runtime.RouteStatus = "Paused • Retry Limit"
        Runtime.UpdateRouteUI()
        Notify(
            "Route Paused",
            Label .. " still failed after " .. tostring(Runtime.RouteRetryLimit)
                .. " retries. Fix the path, then press Pause / Resume."
        )
        return "pause"
    end

    Runtime.RouteRetryCount = 0
    if Rule == "Skip" then
        Runtime.RouteStatus = "Skipped • " .. Label
        Runtime.RouteCurrentIndex += 1
        Runtime.UpdateRouteUI()
        Notify("Route Skip", Label .. " was skipped. " .. Why)
        return "skip"
    elseif Rule == "Pause" then
        Runtime.RoutePaused = true
        Runtime.RouteStatus = "Paused • Failed"
        Runtime.UpdateRouteUI()
        Notify("Route Paused", Label .. " failed. " .. Why)
        return "pause"
    else
        Runtime.RouteStatus = "Stopped • Failed"
        Runtime.UpdateRouteUI()
        Notify("Route Stopped", Label .. " failed. " .. Why)
        Runtime.StopWaypointRoute(true)
        return "stop"
    end
end

Runtime.WaitForRouteCharacter = function(ThisRun)
    if not Runtime.RouteResumeAfterRespawn then return false end
    Runtime.RouteStatus = "Waiting For Respawn"
    Runtime.UpdateRouteUI()

    while Runtime.RouteRunning and Runtime.RouteRunId == ThisRun and not Unloaded do
        if not Runtime.RouteResumeAfterRespawn then
            Notify("Route", "Respawn resume was turned off. Route stopped.")
            Runtime.StopWaypointRoute(true)
            return false
        end
        local H = Humanoid()
        local R = Root()
        if H and R and H.Health > 0 then

            local Settled = 0
            while Settled < 0.35 and Runtime.RouteRunning
                and Runtime.RouteRunId == ThisRun and not Unloaded do
                task.wait(0.05)
                Settled += 0.05
            end
            if Runtime.RouteRunning and Runtime.RouteRunId == ThisRun and not Unloaded then
                Runtime.RouteStatus = Runtime.RoutePaused
                    and "Paused"
                    or (Runtime.RouteLoop and "Looping" or "Running")
                Runtime.UpdateRouteUI()
                return true
            end
            return false
        end
        task.wait(0.10)
    end
    return false
end

Runtime.StopWaypointRoute = function(Silent)
    if Runtime.CancelTravel then Runtime.CancelTravel() else CancelTween() end
    Runtime.RouteRunId += 1
    Runtime.RouteRunning = false
    Runtime.RoutePaused = false
    Runtime.RouteRetryCount = 0
    Runtime.RouteStatus = "Idle"
    Runtime.RouteCurrentIndex = 1
    Runtime.UpdateRouteUI()
    if not Silent then
        Notify(
            "Route",
            Runtime.RouteStartFromNearest
                and "Stopped. Next play starts from the nearest route waypoint."
                or "Stopped. Next play starts from waypoint 1."
        )end
end

Runtime.TogglePauseRoute = function()
    if not Runtime.RouteRunning then
        Notify("Route", "The route is not running.")
        return
    end
    if Runtime.RoutePaused then
        if Runtime.RouteStatus == "Paused • Retry Limit" then
            Runtime.RouteRetryCount = 0
        end
        Runtime.RoutePaused = false
        Runtime.RouteStatus = (Runtime.RouteLoop and "Looping" or "Running")
        Runtime.UpdateRouteUI()
        Notify("Route", "Resumed from waypoint " .. tostring(Runtime.RouteCurrentIndex) .. ".")
    else
        Runtime.RoutePaused = true
        Runtime.RouteStatus = "Paused"
        if Runtime.CancelTravel then Runtime.CancelTravel() else CancelTween() end
        Runtime.UpdateRouteUI()
        Notify("Route", "Paused at waypoint " .. tostring(Runtime.RouteCurrentIndex) .. ".")
    end
end

Runtime.StartRoute = function(Loop)
    if #Runtime.WaypointRoute == 0 then
        Notify("Route", "Add at least one waypoint to the route first.")
        return
    end

    if Runtime.RouteRunning then
        if Runtime.RoutePaused then
            Runtime.RouteLoop = Loop == true
            Runtime.RoutePaused = false
            Runtime.RouteStatus = (Runtime.RouteLoop and "Looping" or "Running")
            Runtime.UpdateRouteUI()
            Notify("Route", "Resumed from waypoint " .. tostring(Runtime.RouteCurrentIndex) .. ".")
        else
            Notify("Route", "Already running. Stop first to switch mode.")
        end
        return
    end

    Runtime.RouteLoop = Loop == true

    if Runtime.RouteStatus == "Completed" then
        Runtime.RouteCurrentIndex = 1
    end

    if Runtime.RouteStartFromNearest then
        Runtime.RouteCurrentIndex = Runtime.FindNearestRouteIndex()
    else
        Runtime.RouteCurrentIndex = math.clamp(Runtime.RouteCurrentIndex, 1, #Runtime.WaypointRoute)
    end

    Runtime.RouteRetryCount = 0
    Runtime.RouteRunId += 1
    local ThisRun = Runtime.RouteRunId
    Runtime.RouteRunning = true
    Runtime.RoutePaused = false
    Runtime.RouteStatus = (Runtime.RouteLoop and "Looping" or "Running")
    Runtime.UpdateRouteUI()

    if Runtime.RouteStartFromNearest then
        Notify(
            "Route",
            "Starting from nearest: "
                .. tostring(Runtime.RouteCurrentIndex)
                .. ". "
                .. tostring(Runtime.WaypointRoute[Runtime.RouteCurrentIndex])
        )
    end

    task.spawn(function()
        while Runtime.RouteRunning and Runtime.RouteRunId == ThisRun and not Unloaded do
            while Runtime.RoutePaused and Runtime.RouteRunning
                and Runtime.RouteRunId == ThisRun and not Unloaded do
                task.wait(0.05)
            end
            if not Runtime.RouteRunning or Runtime.RouteRunId ~= ThisRun or Unloaded then break end

            if Runtime.RouteCurrentIndex > #Runtime.WaypointRoute then
                if Runtime.RouteLoop then
                    Runtime.RouteCurrentIndex = 1
                    Runtime.RouteRetryCount = 0
                    Runtime.RouteStatus = "Looping"
                    Runtime.UpdateRouteUI()
                else
                    Runtime.RouteRunning = false
                    Runtime.RoutePaused = false
                    Runtime.RouteRetryCount = 0
                    Runtime.RouteStatus = "Completed"
                    Runtime.RouteCurrentIndex = #Runtime.WaypointRoute
                    Runtime.UpdateRouteUI()
                    Notify("Route", "Route finished.")
                    break
                end
            end

            local WaypointName = Runtime.WaypointRoute[Runtime.RouteCurrentIndex]
            local TargetCFrame = DecodeCFrame(Waypoints[WaypointName])
            if not TargetCFrame then
                local Action = Runtime.HandleRouteFailure(
                    ThisRun,
                    WaypointName,
                    "Saved waypoint is missing."
                )
                if Action == "stop" then break end
                continue
            end

            local R = Root()
            local H = Humanoid()
            if not R or not H or H.Health <= 0 then
                if Runtime.RouteResumeAfterRespawn then
                    if Runtime.WaitForRouteCharacter(ThisRun) then

                        continue
                    end
                    break
                end
                local Action = Runtime.HandleRouteFailure(
                    ThisRun,
                    WaypointName,
                    "Your character is unavailable."
                )
                if Action == "stop" then break end
                continue
            end

            Runtime.UpdateRouteUI()
            local TravelReached = Runtime.TravelToCFrame(TargetCFrame, Runtime.RouteTravelMode, "Route")
            if not Runtime.RouteRunning or Runtime.RouteRunId ~= ThisRun or Unloaded then break end

            if not TravelReached then
                local AfterH = Humanoid()
                local AfterR = Root()
                local CharacterUnavailable = not AfterH or not AfterR or AfterH.Health <= 0

                if Runtime.RoutePaused then
                    Runtime.RouteStatus = "Paused"
                    Runtime.UpdateRouteUI()
                elseif CharacterUnavailable and Runtime.RouteResumeAfterRespawn then
                    if Runtime.WaitForRouteCharacter(ThisRun) then

                        continue
                    end
                    break
                else
                    local Action = Runtime.HandleRouteFailure(
                        ThisRun,
                        WaypointName,
                        "Travel could not reach the waypoint."
                    )
                    if Action == "stop" then break end
                    continue
                end
            end

            Runtime.RouteRetryCount = 0
            while Runtime.RoutePaused and Runtime.RouteRunning
                and Runtime.RouteRunId == ThisRun and not Unloaded do
                task.wait(0.05)
            end
            if not TravelReached then
                continue
            end

            local Waited = 0
            local RespawnedDuringDelay = false
            while Waited < Runtime.RouteDelay and Runtime.RouteRunning
                and Runtime.RouteRunId == ThisRun and not Unloaded do
                if Runtime.RoutePaused then
                    task.wait(0.05)
                else
                    local DelayH = Humanoid()
                    local DelayR = Root()
                    if Runtime.RouteResumeAfterRespawn
                        and (not DelayH or not DelayR or DelayH.Health <= 0) then
                        RespawnedDuringDelay = true
                        break
                    end
                    local Step = math.min(0.10, Runtime.RouteDelay - Waited)
                    task.wait(Step)
                    Waited += Step
                end
            end

            if RespawnedDuringDelay then
                if Runtime.WaitForRouteCharacter(ThisRun) then

                    continue
                end
                break
            end

            if Runtime.RouteRunning and Runtime.RouteRunId == ThisRun and not Runtime.RoutePaused then
                Runtime.RouteCurrentIndex += 1
                Runtime.UpdateRouteUI()
            end
        end
    end)
end

