        Callback = function(Value)
            Runtime.TweenSpeed = Value
            Runtime.UpdateRouteUI()
        end
    })
    TeleportTab:CreateDropdown({
        Name = "Delay Between Waypoints",
        Options = {"0.5 Seconds", "1 Second", "2 Seconds", "3 Seconds", "4 Seconds", "5 Seconds",
            "6 Seconds", "7 Seconds", "8 Seconds", "9 Seconds", "10 Seconds"},
        CurrentOption = {"0.5 Seconds"}, Flag = "Route_Delay",
        Callback = function(Option)
            local Text = type(Option) == "table" and Option[1] or Option
            Runtime.RouteDelay = math.clamp(tonumber(tostring(Text):match("[%d%.]+")) or 0.5, 0.5, 10)
            Runtime.UpdateRouteUI()
        end
    })
    local RoutePlaybackMode = "Play Once"
    TeleportTab:CreateDropdown({
        Name = "Playback Mode", Options = {"Play Once", "Loop Route"},
        CurrentOption = {"Play Once"}, Flag = "Route_PlaybackMode",
        Callback = function(Option)
            RoutePlaybackMode = type(Option) == "table" and Option[1] or Option
            Runtime.RouteLoop = RoutePlaybackMode == "Loop Route"
            Runtime.UpdateRouteUI()
        end
    })
    TeleportTab:CreateToggle({
        Name = "▶️ Start From Nearest", Flag = "Route_StartNearest", CurrentValue = false,
        Callback = function(Value)
            Runtime.RouteStartFromNearest = Value == true
            Runtime.UpdateRouteUI()
        end
    })
    TeleportTab:CreateToggle({
        Name = "💀 Resume After Respawn", Flag = "Route_ResumeRespawn", CurrentValue = false,
        Callback = function(Value)
            Runtime.RouteResumeAfterRespawn = Value == true
            Runtime.UpdateRouteUI()
        end
    })
    TeleportTab:CreateDropdown({
        Name = "🛑 If A Waypoint Fails",
        Options = {"Retry", "Skip", "Pause", "Stop Route"},
        CurrentOption = {Runtime.RouteFailureRule},
        Flag = "Route_FailureRule",
        Callback = function(Option)
            Runtime.RouteFailureRule = type(Option) == "table" and Option[1] or Option
            Runtime.RouteRetryCount = 0
            Runtime.UpdateRouteUI()
        end
    })
    TeleportTab:CreateDropdown({
        Name = "⚡ Reroute Sensitivity",
        Options = {"Fast", "Balanced", "Stable"},
        CurrentOption = {Runtime.RerouteSensitivity or "Balanced"},
        Flag = "Route_RerouteSensitivity",
        Callback = function(Option)
            local Value = type(Option) == "table" and Option[1] or Option
            Runtime.RerouteSensitivity = Value
            local Presets = {Fast = {0.05, 0.35, 0.20}, Balanced = {0.10, 0.75, 0.35}, Stable = {0.20, 1.50, 0.60}}
            local P = Presets[Value] or Presets.Balanced
            Runtime.Navigation.Interval, Runtime.Navigation.MoveThreshold, Runtime.Navigation.ObstacleInterval = P[1], P[2], P[3]
            Runtime.UpdateRouteUI()
        end
    })
    TeleportTab:CreateSlider({
        Name = "Retry Attempts",
        Range = {1, 10},
        Increment = 1,
        CurrentValue = Runtime.RouteRetryLimit,
        Flag = "Route_RetryLimit",
        Callback = function(Value)
            Runtime.RouteRetryLimit = math.clamp(math.floor(tonumber(Value) or 3), 1, 10)
            Runtime.UpdateRouteUI()
        end
    })
    Runtime.RouteProgressParagraph = TeleportTab:CreateParagraph({
        Title = "🧭 Route Progress",
        Content = "░░░░░░░░░░  0 / 0\nCurrent: None\nNext: Finish"
    })
    Runtime.RouteStatusParagraph = TeleportTab:CreateParagraph({
        Title = "Route Status",
        Content = "Status: Idle\nRoute: Current Route\nMode: Play Once\nWaypoint: 0 / 0\nTravel: Walk\nFailure: Retry (0/3)\nStart: Waypoint 1\nRespawn Resume: On\nDelay: 0.5 Seconds"
    })
    TeleportTab:CreateButton({
        Name = "▶ Start Route",
        Callback = function() Runtime.StartRoute(RoutePlaybackMode == "Loop Route") end
    })
    TeleportTab:CreateButton({ Name = "⏸ Pause / Resume", Callback = Runtime.TogglePauseRoute })
    TeleportTab:CreateButton({
        Name = "⏹ Stop Route",
        Callback = function() Runtime.StopWaypointRoute(false) end
    })
    Runtime.UpdateRouteUI()
end

