do
    local function GetPlayerStats(Target)
        local Lines = {}
        local SeenNames = {}
        local function ReadContainer(Container)
            if not Container then return end
            for _, Stat in ipairs(Container:GetChildren()) do
                if Stat:IsA("ValueBase") and not SeenNames[Stat.Name] then
                    SeenNames[Stat.Name] = true
                    table.insert(Lines, Stat.Name .. ": " .. tostring(Stat.Value))
                end
            end
        end
        ReadContainer(Target:FindFirstChild("leaderstats"))
        ReadContainer(Target:FindFirstChild("Stats"))
        ReadContainer(Target:FindFirstChild("Data"))
        ReadContainer(Target:FindFirstChild("PlayerData"))
        if #Lines == 0 then return "No public currency or stats found." end
        table.sort(Lines)
        return table.concat(Lines, "\n")
    end
    local function GetToolSummary(Target)
        local Names = {}
        local Seen = {}
        local function ReadTools(Container)
            if not Container then return end
            for _, Object in ipairs(Container:GetChildren()) do
                if Object:IsA("Tool") and not Seen[Object.Name] then
                    Seen[Object.Name] = true
                    table.insert(Names, Object.Name)
                end
            end
        end
        ReadTools(Target.Character)
        ReadTools(Target:FindFirstChildOfClass("Backpack"))
        table.sort(Names)
        if #Names == 0 then return "None" end
        if #Names > 8 then
            local HiddenCount = #Names - 8
            while #Names > 8 do table.remove(Names) end
            return table.concat(Names, ", ") .. " +" .. HiddenCount .. " more"
        end
        return table.concat(Names, ", ")
    end
    local function GetAvatarThumbnail(Target)
        if not Target then return nil end
        local Cached = Runtime.AvatarThumbnailCache[Target.UserId]
        if Cached then return Cached end
        local Success, Thumbnail = pcall(function()
            return Players:GetUserThumbnailAsync(Target.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size420x420)
        end)
        if Success and type(Thumbnail) == "string" then
            Runtime.AvatarThumbnailCache[Target.UserId] = Thumbnail
            return Thumbnail
        end
        return nil
    end
    local function FormatAccountAgeDays(Days)
        Days = math.max(0, math.floor(tonumber(Days) or 0))
        local Years = math.floor(Days / 365)
        local Remaining = Days % 365
        local Months = math.floor(Remaining / 30)
        local Parts = {tostring(Days) .. " days"}
        if Years > 0 then table.insert(Parts, tostring(Years) .. " year" .. (Years == 1 and "" or "s")) end
        if Months > 0 then table.insert(Parts, tostring(Months) .. " month" .. (Months == 1 and "" or "s")) end
        return table.concat(Parts, " / ")
    end
    local function StatsOptionLabel(Target)
        return Target.DisplayName .. " (@" .. Target.Name .. ")"
    end
    local BuildSuccess, BuildError = pcall(function()
        local StatsTab = Window:CreateTab("📊 Stats", 4483362458)
        StatsTab:CreateParagraph({ Title = "Live Profile", Content = "Pick a player to see their avatar, name, username, account age, character state, distance, tools, and public stats." })
        StatsTab:CreateSection("🔎 Player Search")
        Runtime.StatsPlayerMap = {}
        Runtime.RefreshStatsPlayers = function()
            local Options = {}
            local SelfLabel = StatsOptionLabel(Player)
            Runtime.StatsPlayerMap = {}
            for _, Target in ipairs(Runtime.CachedPlayers()) do
                local Label = StatsOptionLabel(Target)
                Runtime.StatsPlayerMap[Label] = Target
                table.insert(Options, Label)
            end
            table.sort(Options, function(A, B) return string.lower(A) < string.lower(B) end)
            local SelfIndex = table.find(Options, SelfLabel)
            if SelfIndex and SelfIndex ~= 1 then
                table.remove(Options, SelfIndex)
                table.insert(Options, 1, SelfLabel)
            end
            if StatsPlayerDropdown then StatsPlayerDropdown:Refresh(Options) end
            return Options
        end
        local StatsOptions = Runtime.RefreshStatsPlayers()
        StatsPlayerDropdown = StatsTab:CreateDropdown({
            Name = "Search or Select Player", Options = StatsOptions,
            CurrentOption = {StatsOptionLabel(Player)}, SearchBarEnabled = true, Flag = "Stats_SelectedPlayer",
            Callback = function(Option)
                local Label = type(Option) == "table" and Option[1] or Option
                local Target = Runtime.StatsPlayerMap and Runtime.StatsPlayerMap[Label]
                if Target then
                    SelectedStatsPlayer = Target
                    Runtime.StatsSelectedUserIdValue = Target.UserId
                    Runtime.LastStatsUserId = nil
                    Runtime.StatsSelectedThumbnail = nil
                    if Runtime.RefreshStats then Runtime.RefreshStats(true) end
                end
            end
        })
        StatsTab:CreateSection("📋 Live Profile")
        StatsAvatarLabel = StatsTab:CreateLabel("Avatar • " .. Player.DisplayName .. "  (@" .. Player.Name .. ")")
        StatsInformation = StatsTab:CreateParagraph({ Title = "Live Profile", Content = "Loading..." })
        Runtime.RefreshStats = function(RefreshAvatar)
            local Target = SelectedStatsPlayer
            if not Target or not Target.Parent then
                SelectedStatsPlayer = Player
                Target = Player
                Runtime.StatsSelectedUserIdValue = Player.UserId
                Runtime.LastStatsUserId = nil
            end
            Runtime.StatsSelectedUserIdValue = Target.UserId
            local TargetCharacter = Target.Character
            local H = TargetCharacter and TargetCharacter:FindFirstChildOfClass("Humanoid")
            local TargetRoot = TargetCharacter and TargetCharacter:FindFirstChild("HumanoidRootPart")
            local MyRoot = Root()
            local Health = H and (math.floor(H.Health) .. "/" .. math.floor(H.MaxHealth)) or "N/A"
            local Distance = MyRoot and TargetRoot
                and (math.floor((MyRoot.Position - TargetRoot.Position).Magnitude) .. " studs") or "N/A"
            local State = H and CharacterState(H) or "N/A"
            local EquippedTool = TargetCharacter and TargetCharacter:FindFirstChildOfClass("Tool")
            local TeamName = Target.Team and Target.Team.Name or "None"
            local HumanoidRig = H and H.RigType and tostring(H.RigType):gsub("Enum%.HumanoidRigType%.", "") or "Unknown"
            local WalkSpeed = H and math.floor(H.WalkSpeed or 0) or 0
            local JumpPower = H and math.floor(H.JumpPower or 0) or 0
            local ToolSummary = GetToolSummary(Target)
            local AgeText = FormatAccountAgeDays(Target.AccountAge)
            local RootPosition = TargetRoot and TargetRoot.Position
            local PositionText = RootPosition and string.format("%.0f, %.0f, %.0f", RootPosition.X, RootPosition.Y, RootPosition.Z) or "N/A"
            local VelocityText = TargetRoot and (tostring(math.floor(TargetRoot.AssemblyLinearVelocity.Magnitude + 0.5)) .. " studs/s") or "N/A"
            local FloorMaterial = H and tostring(H.FloorMaterial):gsub("Enum%.Material%.", "") or "N/A"
            local TeamColor = Target.Team and tostring(Target.Team.TeamColor) or "None"
            local Membership = tostring(Target.MembershipType or "Unknown"):gsub("Enum%.MembershipType%.", "")
            local FriendText = "Unknown"
            pcall(function() FriendText = Player:IsFriendsWith(Target.UserId) and "Yes" or "No" end)
            Runtime.StatsSnapshotText =
                "IDENTITY"
                .. "\nDisplay Name: " .. tostring(Target.DisplayName)
                .. "\nUsername: @" .. tostring(Target.Name)
                .. "\nUser ID: " .. tostring(Target.UserId)
                .. "\nAccount Age: " .. AgeText
                .. "\nMembership: " .. Membership
                .. "\nFriend With You: " .. FriendText
                .. "\n\nLIVE CHARACTER"
                .. "\nCharacter Loaded: " .. (TargetCharacter and "Yes" or "No")
                .. "\nTeam: " .. TeamName
                .. "\nTeam Color: " .. TeamColor
                .. "\nNeutral: " .. tostring(Target.Neutral == true)
                .. "\nHealth: " .. Health
                .. "\nState: " .. State
                .. "\nDistance: " .. Distance
                .. "\nPosition: " .. PositionText
                .. "\nVelocity: " .. VelocityText
                .. "\nRig: " .. HumanoidRig
                .. "\nWalk Speed: " .. tostring(WalkSpeed)
                .. "\nJump Power: " .. tostring(JumpPower)
                .. "\nHip Height: " .. tostring(H and math.floor((H.HipHeight or 0) * 10 + 0.5) / 10 or "N/A")
                .. "\nFloor: " .. FloorMaterial
                .. "\nSitting: " .. tostring(H and H.Sit == true or false)
                .. "\nPlatform Stand: " .. tostring(H and H.PlatformStand == true or false)
                .. "\n\nTOOLS"
                .. "\nEquipped: " .. (EquippedTool and EquippedTool.Name or "None")
                .. "\nBackpack: " .. ToolSummary
                .. "\n\nPUBLIC / LEADERSTATS\n" .. GetPlayerStats(Target)
            Runtime.StatsSelectedLabel = tostring(Target.DisplayName) .. "  (@" .. tostring(Target.Name) .. ")"
            Runtime.StatsSelectedUserId = tostring(Target.UserId)
            Runtime.StatsSelectedAge = AgeText
            Runtime.StatsSelectedTeam = TeamName
            Runtime.StatsSelectedTeamColor = Target.Team and Target.Team.TeamColor.Color or Color3.fromRGB(190,190,198)
            Runtime.StatsSelectedHealth = Health
            Runtime.StatsSelectedHealthCurrent = H and tonumber(H.Health) or nil
            Runtime.StatsSelectedHealthMax = H and tonumber(H.MaxHealth) or nil
            Runtime.StatsSelectedDistance = Distance
            Runtime.StatsSelectedState = State
            Runtime.StatsSelectedDisplayName = tostring(Target.DisplayName)
            Runtime.StatsSelectedUsername = "@" .. tostring(Target.Name)
            Runtime.StatsSelectedMembership = Membership
            Runtime.StatsSelectedFriend = FriendText
            Runtime.StatsSelectedCharacterLoaded = TargetCharacter and "Yes" or "No"
            Runtime.StatsSelectedRig = HumanoidRig
            Runtime.StatsSelectedWalkSpeed = tostring(WalkSpeed)
            Runtime.StatsSelectedJumpPower = tostring(JumpPower)
            Runtime.StatsSelectedEquipped = EquippedTool and EquippedTool.Name or "None"
            Runtime.StatsSelectedBackpack = ToolSummary
            Runtime.StatsSelectedPosition = PositionText
            Runtime.StatsSelectedVelocity = VelocityText
            Runtime.StatsSelectedFloor = FloorMaterial
            Runtime.StatsSelectedPublic = GetPlayerStats(Target)
            Runtime.StatsAccountText =
                "User ID: " .. tostring(Target.UserId)
                .. "\nAccount Age: " .. AgeText
                .. "\nMembership: " .. Membership
                .. "\nFriends With You: " .. FriendText
            Runtime.StatsCharacterText =
                "Character Loaded: " .. (TargetCharacter and "Yes" or "No")
                .. "\nTeam: " .. TeamName
                .. "\nTeam Color: " .. TeamColor
                .. "\nHealth: " .. Health
                .. "\nState: " .. State
                .. "\nDistance: " .. Distance
                .. "\nRig: " .. HumanoidRig
                .. "\nPosition: " .. PositionText
                .. "\nVelocity: " .. VelocityText
                .. "\nWalk Speed: " .. tostring(WalkSpeed)
                .. "\nJump Power: " .. tostring(JumpPower)
                .. "\nFloor: " .. FloorMaterial
                .. "\nSitting: " .. tostring(H and H.Sit == true or false)
            Runtime.StatsEquipmentText =
                "Equipped: " .. (EquippedTool and EquippedTool.Name or "None")
                .. "\nBackpack: " .. ToolSummary
            Runtime.StatsPublicText = GetPlayerStats(Target)
            if StatsInformation then
                pcall(function()
                    StatsInformation:Set({
                        Title = "Live Profile",
                        Content = Runtime.StatsSnapshotText or "Loading..."
                    })
                end)
            end
            if RefreshAvatar or Runtime.LastStatsUserId ~= Target.UserId then
                Runtime.LastStatsUserId = Target.UserId
                local RequestedUserId = Target.UserId
                if StatsAvatarLabel then
                    pcall(function() StatsAvatarLabel:Set("Avatar • " .. Target.DisplayName .. "  (@" .. Target.Name .. ")") end)
                end
                task.spawn(function()
                    local Thumbnail = GetAvatarThumbnail(Target)
                    if Unloaded or not Thumbnail or not SelectedStatsPlayer
                        or SelectedStatsPlayer.UserId ~= RequestedUserId then
                        return
                    end
                    if StatsAvatarLabel then
                        pcall(function() StatsAvatarLabel:Set("Avatar • " .. Target.DisplayName .. "  (@" .. Target.Name .. ")", Thumbnail) end)
                    end
                    Runtime.StatsSelectedThumbnail = Thumbnail
                end)
            end
        end
        StatsTab:CreateButton({
            Name = "🔄 Refresh Selected Player",
            Callback = function()
                Runtime.RefreshStatsPlayers()
                Runtime.RefreshStats(true)
            end
        })
        do
            local Accumulator = 2
            StatsStatusConnection = Runtime.TrackCleanup(RunService.Heartbeat:Connect(function(Delta)
                if Unloaded then return end
                Accumulator += Delta
                if Accumulator < 2 then return end
                Accumulator = 0
                Runtime.RefreshStats(false)
            end),"Disconnect","StatsHeartbeat","Connections")
        end
        Runtime.RefreshStats(true)
    end)
    if not BuildSuccess then
        warn("BANANIHUB | Stats tab failed: " .. tostring(BuildError))
    end
end

do
    local function GetPublicServers(Mode)
        local PlaceId=tonumber(game.PlaceId)
        if not PlaceId or PlaceId<=0 or PlaceId%1~=0 then return nil,"Invalid place ID." end
        local Order=Mode=="Largest" and "Desc" or "Asc"
        local Servers,Seen,Cursors={},{},{}
        local Cursor=nil
        -- Bound requests and detect repeated cursors; large games can have thousands of pages.
        for Page=1,10 do
            if Unloaded then return nil,"Cancelled." end
            local URL="https://games.roblox.com/v1/games/"..string.format("%.0f",PlaceId)
                .."/servers/Public?sortOrder="..Order.."&limit=100"
            if Cursor then URL=URL.."&cursor="..HttpService:UrlEncode(Cursor) end
            local OK,Body=pcall(function() return game:HttpGet(URL,true) end)
            if not OK then return nil,tostring(Body) end
            local Decoded,Data=pcall(function() return HttpService:JSONDecode(Body) end)
            if not Decoded or type(Data)~="table" or type(Data.data)~="table" then
                return nil,"The public server response was invalid."
            end
            for _,Server in ipairs(Data.data) do
                if type(Server)=="table" and type(Server.id)=="string" and not Seen[Server.id] then
                    Seen[Server.id]=true
                    table.insert(Servers,Server)
                end
            end
            Cursor=Data.nextPageCursor
            if type(Cursor)~="string" or Cursor=="" or Cursors[Cursor] then break end
            Cursors[Cursor]=true
            if Page<10 then task.wait(0.15) end
        end
        return Servers,nil
    end
    Runtime.FailedServers=Runtime.FailedServers or {}
    TrackConnection(TeleportService.TeleportInitFailed:Connect(function(Who,_,Message)
        if Who~=Player or not Runtime.PendingServerId then return end
        Runtime.FailedServers[Runtime.PendingServerId]=true
        Runtime.PendingServerId=nil
        Runtime.ServerRequestBusy=false
        Notify("Server Hop","Teleport failed: "..tostring(Message))
    end))
    Runtime.ServerHop = function(Mode)
        if Runtime.ServerRequestBusy then
            Notify("Server", "A server action is already running.")
            return
        end
        Runtime.ServerRequestBusy = true
        Notify("Server", "Searching for an available server...")
        task.spawn(function()
            local Success, Failure = pcall(function()
                local Servers, FetchError = GetPublicServers(Mode)
                if not Servers then error(FetchError or "Could not load the public server list.") end
                if Unloaded then return end
                local Available = {}
                for _, Server in ipairs(Servers) do
                    local ServerId = tostring(Server.id or "")
                    local Playing = tonumber(Server.playing) or 0
                    local Capacity = tonumber(Server.maxPlayers) or 0
                    local IsCurrent = ServerId == tostring(game.JobId)
                    local WasVisited = Runtime.VisitedServers[ServerId] == true
                    if ServerId ~= "" and Playing>=0 and Playing < Capacity
                        and not IsCurrent and not Runtime.FailedServers[ServerId]
                        and (not Runtime.AvoidVisitedServers or not WasVisited) then
                        table.insert(Available, Server)
                    end
                end
                if #Available == 0 then error("No available servers matched the selected filters.") end
                if Mode == "Smallest" then
                    table.sort(Available, function(A, B) return (tonumber(A.playing) or 0) < (tonumber(B.playing) or 0) end)
                elseif Mode == "Largest" then
                    table.sort(Available, function(A, B) return (tonumber(A.playing) or 0) > (tonumber(B.playing) or 0) end)
                else
                    local RandomIndex = math.random(1, #Available)
                    Available[1], Available[RandomIndex] = Available[RandomIndex], Available[1]
                end
                local SelectedServer = Available[1]
                local ServerId = tostring(SelectedServer.id)
                local Playing = tonumber(SelectedServer.playing) or 0
                local Capacity = tonumber(SelectedServer.maxPlayers) or 0
                Runtime.VisitedServers[ServerId] = true
                Runtime.PendingServerId=ServerId
                if Runtime.ServerSelectionParagraph then
                    Runtime.ServerSelectionParagraph:Set({
                        Title = "Selected Server",
                        Content = "Players: " .. Playing .. "/" .. Capacity
                            .. "\nPing estimate: Unknown\nServer ID: " .. ServerId .. "\nStatus: Available"
                    })
                end
                task.wait(0.35)
                if Unloaded then return end
                -- TeleportAsync is server-only in current Roblox documentation.
                -- BananiHub executes client-side, so specific public-instance joins keep
                -- TeleportToPlaceInstance here despite its deprecation for new server code.
                TeleportService:TeleportToPlaceInstance(game.PlaceId,ServerId,Player)
            end)
            if not Success or Unloaded then
                if Runtime.PendingServerId then Runtime.FailedServers[Runtime.PendingServerId]=true end
                Runtime.PendingServerId=nil
                Runtime.ServerRequestBusy=false
                if not Unloaded then Notify("Server Hop", "Failed: " .. tostring(Failure)) end
            else
                -- The request may fail asynchronously after TeleportToPlaceInstance returns.
                local Pending=Runtime.PendingServerId
                task.delay(15,function()
                    if not Unloaded and Pending and Runtime.PendingServerId==Pending then
                        Runtime.FailedServers[Pending]=true
                        Runtime.PendingServerId=nil
                        Runtime.ServerRequestBusy=false
                        Notify("Server Hop","TIMEOUT: teleport was not confirmed.")
                    end
                end)
            end
        end)
    end
end

