local function MasterReset()
    Runtime.ResetGeneration += 1
    if Runtime.CoreStopAllLoops then pcall(Runtime.CoreStopAllLoops) end
    if Runtime.GameProfileReset then pcall(function() Runtime.GameProfileReset(true) end) end
    if Runtime.VisualEngine and Runtime.VisualEngine.StopPickupAll then
        pcall(function() Runtime.VisualEngine.StopPickupAll(true) end)
    end
    if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
    if Runtime.ClearPathPreview then pcall(Runtime.ClearPathPreview) end
    pcall(StopFly)
    pcall(StopFreecam)
