    end
    BoxESPEnabled = false
    HealthESPEnabled = false
    if Runtime.PlayerESPState then Runtime.PlayerESPState.Enabled = false end
    pcall(function() SetAutoJump(false) end)
    InfiniteJumpEnabled = false
    pcall(function() SetAntiFling(false) end)
    AntiAFKEnabled = false
    if Runtime.SetAFKMode then pcall(function() Runtime.SetAFKMode(false, true) end) end
    pcall(function() SetFreeze(false) end)
    FastWalkEnabled = false
    HighJumpEnabled = false
