            Player_Fly = true, Player_Noclip = true, Player_SpiderClimb = true,
            Player_FastWalk = true, Player_HighJump = true, Player_InfiniteJump = true,
            Player_AutoJump = true, Player_AutoWalk = true, Player_Freeze = true,
            Player_AntiVoid = true, Player_AntiRagdoll = true, Player_AntiFling = true,
            Player_AntiAFK = true, Visuals_PlayerESP = true, Visuals_NPCChams = true,
