            Visuals_LowGraphics = true, Visuals_AFKMode = true, Camera_Shake = true,
            Spectator_Enabled = true
        }
        for FlagName, Flag in pairs(Rayfield.Flags) do
            if Flag and Flag.Set and typeof(Flag.CurrentValue) == "boolean"
                and (ActiveToggles[FlagName]
                    or FlagName:match("^Player_")
                    or FlagName:match("^Visuals_")
                    or FlagName:match("^Camera_")
                    or FlagName:match("^Spectator_")
                    or FlagName:match("^Freecam_")
                    or FlagName:match("^Travel_")
                    or FlagName:match("^Route_")
                    or FlagName:match("^GameProfile_")
                    or FlagName:match("^UIVisuals_")) then
