        local MultiDefaults = {
            Visuals_PlayerESPExtras = {"Glow", "Health Bar"},
            Visuals_RareExtras = {"Sound", "Direction Arrow"},
            UIVisuals_TextStyle = {},
            UIVisuals_RichTextOptions = {"Allow RichText When Needed"},
            Freecam_Extras = {}
        }
        for FlagName, DefaultValue in pairs(MultiDefaults) do
            local Flag = Rayfield.Flags[FlagName]
            if Flag and Flag.Set then
                pcall(function() Flag:Set(DefaultValue) end)
            end
        end
        local ItemCollectorDefaults = {
            Visuals_ItemWhitelist = "",
            Visuals_ItemBlacklist = "",
            Visuals_ItemAutoRescan = false,
            Visuals_ItemAutoRescanSeconds = 5
        }
        for FlagName, DefaultValue in pairs(ItemCollectorDefaults) do
            local Flag = Rayfield.Flags[FlagName]
            if Flag and Flag.Set then pcall(function() Flag:Set(DefaultValue) end) end
        end
    end
    Notify("Master Reset", "All active features were reset.")
end
local function UnloadBananiHub(Reason)
    -- Hard lifecycle guard: hiding/closing the UI must never terminate BananiHub.
    -- Full teardown is accepted only for an intentional Settings unload or when a
    -- newer BananiHub execution deliberately replaces this instance.
    if Reason~="explicit" and Reason~="replacement" then
        warn("[BananiHub] Blocked unintended unload request")
        return false
    end
    if Unloaded then return false end
    -- Restore any active decoy/invisible state before tearing down connections/UI.
    -- This prevents the next execution from inheriting a parked real character.
    if Runtime.MM2SetInvisible then pcall(function() Runtime.MM2SetInvisible(false,true) end) end
    if Runtime.SetUniversalInvisible then pcall(function() Runtime.SetUniversalInvisible(false,true) end) end
    if Runtime.CoreStopAllLoops then pcall(Runtime.CoreStopAllLoops) end
    if Runtime.GameProfileReset then pcall(function() Runtime.GameProfileReset(false) end) end
    Unloaded = true
    if Runtime.DestroyNavigation then pcall(Runtime.DestroyNavigation) end
    if Runtime.CancelTravel then pcall(Runtime.CancelTravel) end
    if Runtime.ClearPathPreview then pcall(Runtime.ClearPathPreview) end
    pcall(StopFly)
    pcall(StopFreecam)
    pcall(StopSpectating)
    pcall(function() SetCameraShake(false) end)
    if Runtime.ApplyPlayerESP then pcall(function() Runtime.ApplyPlayerESP(false) end)
    else
        pcall(function() SetChams(false) end)
        pcall(function() SetHitboxes(false) end)
    end
    pcall(function() SetNPCChams(false) end)
    if Runtime.VisualEngine then pcall(function() Runtime.VisualEngine.Shutdown() end) end
    pcall(function() SetLowGraphics(false) end)
    pcall(function() SetFullbright(false) end)
    pcall(function() SetAntiVoid(false) end)
    pcall(function() SetAntiRagdoll(false) end)
    pcall(function() SetSpiderClimb(false) end)
    pcall(function() SetAutoWalk(false) end)

    if Runtime.UIVisuals then
        pcall(function() Runtime.UIVisuals.KeepApplied = false end)
        pcall(function() Runtime.UIVisuals.Shutdown(true) end)
    end
    BoxESPEnabled = false
    HealthESPEnabled = false
    if Runtime.PlayerESPState then Runtime.PlayerESPState.Enabled = false end
    pcall(SetPlayerESP)
    pcall(RemoveTeleportTool)
    if Runtime.StopWaypointRoute then
        pcall(function() Runtime.StopWaypointRoute(true) end)
    end
    pcall(function() SetNoclip(false) end)
    pcall(function() SetAutoJump(false) end)
    InfiniteJumpEnabled = false
    pcall(function() SetAntiFling(false) end)
    AntiAFKEnabled = false
    if Runtime.SetAFKMode then pcall(function() Runtime.SetAFKMode(false, true) end) end
    pcall(function() SetFreeze(false) end)
    FastWalkEnabled = false
    HighJumpEnabled = false
    pcall(UpdateMovement)
    pcall(function() SetCharacterLocked(false) end)
    local Connections = {
        FlyConnection, AutoJumpConnection, AntiFlingConnection, NoclipConnection,
        ChamsConnection, NPCChamsConnection, HitboxConnection, FreecamConnection,
        FreecamMouseConnection, FreecamEndConnection, FreecamChangedConnection,
        CameraShakeConnection, SpectatorConnection,
        StatsStatusConnection, AntiVoidConnection, AntiRagdollConnection,
        SpiderClimbConnection, AutoWalkConnection, ESPConnection
    }
    for _, Connection in pairs(Connections) do
        if Connection then pcall(function() Connection:Disconnect() end) end
    end

    if Runtime.FreezeConnection then
        pcall(function() Runtime.FreezeConnection:Disconnect() end)
        Runtime.FreezeConnection = nil
    end
    if Runtime.MM2InvisibleKeyConnection then
        pcall(function() Runtime.MM2InvisibleKeyConnection:Disconnect() end)
        Runtime.MM2InvisibleKeyConnection = nil
    end
    if Runtime.UniversalInvisibleKeyConnection then
        pcall(function() Runtime.UniversalInvisibleKeyConnection:Disconnect() end)
        Runtime.UniversalInvisibleKeyConnection = nil
    end
    if Runtime.UniversalInvisibleKeyReleaseConnection then
        pcall(function() Runtime.UniversalInvisibleKeyReleaseConnection:Disconnect() end)
        Runtime.UniversalInvisibleKeyReleaseConnection = nil
    end
    if Runtime.DynamicIslandLevelConnection then pcall(function() Runtime.DynamicIslandLevelConnection:Disconnect() end); Runtime.DynamicIslandLevelConnection=nil end
    if Runtime.DynamicIslandPlayerDataConnection then pcall(function() Runtime.DynamicIslandPlayerDataConnection:Disconnect() end); Runtime.DynamicIslandPlayerDataConnection=nil end
    if Runtime.DynamicIslandDataChildConnection then pcall(function() Runtime.DynamicIslandDataChildConnection:Disconnect() end); Runtime.DynamicIslandDataChildConnection=nil end
    Runtime.DynamicIslandUIOnTakeover=nil
    Runtime.DynamicIslandPausedFlag=nil
    Runtime.DynamicIslandPausedSnapshot=nil
    Runtime.DynamicIslandPausedLabel=nil
    Runtime.InvisibleKeyHeld=false
    if Runtime.ClearCopyMovement then pcall(function() Runtime.ClearCopyMovement() end) end
    if Runtime.ClearDisguise then pcall(function() Runtime.ClearDisguise() end) end
    if Runtime.DisguiseState and Runtime.DisguiseState.CharacterConnection then
        pcall(function() Runtime.DisguiseState.CharacterConnection:Disconnect() end)
        Runtime.DisguiseState.CharacterConnection=nil
    end
    Runtime.InvisibleTransitionBusy=false
    Runtime.InvisibleToggleBusy=false
    for _, Connection in ipairs(Runtime.PerformanceConnections) do
        if Connection then pcall(function() Connection:Disconnect() end) end
    end
    Runtime.PerformanceConnections = {}
    for _,Connection in ipairs(Runtime.Connections) do
        if Connection then pcall(function() Connection:Disconnect() end) end
        Runtime.ReleaseCleanup(Connection)
    end
    Runtime.Connections = {}

    if Runtime.CleanupRegistry then

-- ==================================================================
-- [BH:UNLOAD] FULL UNLOAD / RE-EXECUTE CLEANUP
-- Feature restoration runs before the final central cleanup sweep.
-- ==================================================================
        pcall(function() Runtime.CleanupRegistry:CleanupAll() end)
    end
    pcall(function()
        for _, Target in ipairs(Runtime.CachedPlayers()) do
            RemoveESPFromCharacter(Target.Character)
        end
    end)
    pcall(function()
        for _, Object in ipairs(workspace:GetDescendants()) do
            if Object.Name == "BananiHitbox" or Object.Name == "BananiESP"
                or Object.Name == "BananiFlyVelocity" or Object.Name == "BananiFlyGyro"
                or Object.Name == "BananiMM2RoleGlow" or Object.Name == "BananiMM2GunGlow"
                or Object.Name == "BananiMM2KnifeGlow" or Object.Name == "BananiMM2Role"
                or Object.Name == "BananiMM2Object"
                or Object.Name == "BananiAdoptSafePlatform"
                or Object.Name == "BananiPathDot"
                or Object.Name == "BananiPathLine"
                or Object.Name == "BananiBloxEnemyESP"
                or Object.Name == "BananiHub_ShootingAid" then
                Object:Destroy()
            end
        end
    end)
    pcall(function()
        local C=Player.Character
        if C then
            for _,Object in ipairs(C:GetDescendants()) do
                if Object:IsA("BasePart") then Object.LocalTransparencyModifier=0 end
            end
        end
    end)
    pcall(function()
        local Parents={Player:FindFirstChildOfClass("PlayerGui"),game:GetService("CoreGui")}
        if gethui then
            local OK,HUI=pcall(gethui)
            if OK and HUI then table.insert(Parents,HUI) end
        end
        for _,Parent in ipairs(Parents) do
            if Parent then
                for _,Name in ipairs({"BananiMM2ESPPlus","BananiHubPremiumApple51412","BananiHubToastLayer","BananiBloxFruitDetector","BananiHubUI","BananiHubBootDiagnostic"}) do
                    local G=Parent:FindFirstChild(Name); if G then G:Destroy() end
                end
            end
        end
    end)
    if Runtime.AutomationStatus then
        for Name in pairs(Runtime.AutomationStatus) do
            pcall(function() Runtime.SetAutomationState(Name,"Idle","") end)
        end
    end
    pcall(function()
        Camera.CameraType = Enum.CameraType.Custom
        Camera.FieldOfView = Runtime.OriginalCameraFOV
        UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    end)
    do
        local Environment = getgenv and getgenv() or _G
        if Environment.__BANANIHUB_UNLOAD == UnloadBananiHub then Environment.__BANANIHUB_UNLOAD = nil end
        local ActiveInstance=Environment.__BANANIHUB_INSTANCE
        if type(ActiveInstance)=="table" and ActiveInstance.Token==BANANIHUB_INSTANCE_TOKEN then
            Environment.__BANANIHUB_INSTANCE=nil
        end
        local Premium=Environment.BananiHubPremiumUI
        if Premium and Premium.Gui then pcall(function() Premium.Gui:Destroy() end) end
        Environment.BananiHubPremiumUI=nil
    end
    local H = Humanoid()
    if H then Camera.CameraSubject = H end
    if Rayfield.Destroy then
        pcall(function() Rayfield:Destroy() end)
    elseif Rayfield.Unload then
        pcall(function() Rayfield:Unload() end)
    end
    return true
end
do
    local Environment = getgenv and getgenv() or _G
    Environment.__BANANIHUB_UNLOAD = UnloadBananiHub
    Environment.__BANANIHUB_INSTANCE = {
        Token = BANANIHUB_INSTANCE_TOKEN,
        Version = BANANIHUB_VERSION,
        Unload = UnloadBananiHub,
        StartedAt = os.clock()
    }
end

do
    local BuildSuccess, BuildError = pcall(function()
        local SettingsTab = Window:CreateTab("Settings", 4483362458)
        local NamedConfigFolder = "BANANIHUB/NamedConfigs"
        local SelectedConfigName = ""
        local SelectedConfigToLoad = nil
        local ConfigDropdown
        Runtime.SettingsInfoParagraph = SettingsTab:CreateParagraph({
            Title = "⚙️ BananiHub Preferences",
            Content = "Theme: Loading...\nKeybind: " .. UIToggleKey.Name .. "\nWaypoints: Loading...\nFavorites: Loading..."
        })
        SettingsTab:CreateButton({
            Name = "🔄 Refresh Summary",
            Callback = function() Runtime.UpdatePreferenceDisplays() end
        })

        SettingsTab:CreateSection("🎨 Appearance")
        local ThemePresets = { ["Default"] = DEFAULT_GRAY_THEME, ["🍌 Banana"] = CustomTheme,
            ["🌙 Midnight"] = "DarkBlue", ["🟣 Purple"] = "Amethyst", ["🌊 Ocean"] = "Ocean" }
        local function ApplyPresetTheme(Name)
            local Theme = ThemePresets[Name]
            if not Theme then Notify("Themes", "That theme is unavailable.") return end
            local Success = pcall(function() Window.ModifyTheme(Theme) end)
            if not Success then Notify("Themes", "Theme failed to apply.") return end
            Runtime.CurrentThemeName = Name
            Runtime.UpdatePreferenceDisplays()
        end
        SettingsTab:CreateDropdown({
            Name = "UI Theme", Flag = "Settings_Theme",
            Options = {"Default", "🍌 Banana", "🌙 Midnight", "🟣 Purple", "🌊 Ocean"},
            CurrentOption = {Runtime.CurrentThemeName},
            Callback = function(Option) ApplyPresetTheme(type(Option) == "table" and Option[1] or Option) end
        })
        SettingsTab:CreateDropdown({
            Name = "Interface Layout", Flag = "Settings_InterfaceLayout",
            Options = {"Normal", "Compact"},
            CurrentOption = {Runtime.CompactMode and "Compact" or "Normal"},
            Callback = function(Option)
                Runtime.SetInterfaceMode(type(Option) == "table" and Option[1] or Option, false)
            end
        })
        SettingsTab:CreateDropdown({
            Name = "Animation Speed", Flag = "Settings_AnimationMode",
            Options = {"Smooth", "Balanced", "Fast"},
            CurrentOption = {Runtime.AnimationMode or "Smooth"},
            Callback = function(Option)
                local Mode=type(Option)=="table" and Option[1] or Option
                if Mode~="Smooth" and Mode~="Balanced" and Mode~="Fast" then Mode="Smooth" end
                Runtime.AnimationMode=Mode
                if Runtime.ApplyAnimationSettings then pcall(Runtime.ApplyAnimationSettings) end
                Runtime.UpdatePreferenceDisplays()
            end
        })
        SettingsTab:CreateToggle({
            Name = "Reduced Motion", Flag = "Settings_ReducedMotion", CurrentValue = Runtime.ReducedMotion==true,
            Callback = function(Value)
                Runtime.ReducedMotion=Value==true
                if Runtime.ApplyAnimationSettings then pcall(Runtime.ApplyAnimationSettings) end
                Runtime.UpdatePreferenceDisplays()
            end
        })

        SettingsTab:CreateSection("💾 Presets & Configs")
        local function EnsureNamedConfigFolder()
            return pcall(function()
                if makefolder and isfolder then
                    if not isfolder("BANANIHUB") then makefolder("BANANIHUB") end
                    if not isfolder(NamedConfigFolder) then makefolder(NamedConfigFolder) end
                end
            end)
        end
        local function CleanConfigName(Name)
            local Clean = tostring(Name or ""):match("^%s*(.-)%s*$")
            return (Clean:gsub("[^%w%-%_ ]", ""))
        end
        local function GetConfigurations()
            local Names = {}
            if listfiles then
                local Success, Files = pcall(listfiles, NamedConfigFolder)
                if Success and type(Files) == "table" then
                    for _, FilePath in ipairs(Files) do
                        local Name = tostring(FilePath):match("([^/\\]+)%.json$")
                        if Name then table.insert(Names, Name) end
                    end
                end
            end
            table.sort(Names)
            return Names
        end
        local function RefreshConfigDropdown()
            if ConfigDropdown then ConfigDropdown:Refresh(GetConfigurations()) end
        end
        local function PackConfigValue(Value)
            local ValueType = typeof(Value)
            if ValueType == "Color3" then
                return { __type = "Color3", R = math.floor(Value.R * 255 + 0.5),
                    G = math.floor(Value.G * 255 + 0.5), B = math.floor(Value.B * 255 + 0.5) }
            elseif ValueType == "EnumItem" then
                return { __type = "EnumItem", EnumType = tostring(Value.EnumType), Name = Value.Name }
            end
            return Value
        end
        local function UnpackConfigValue(Value)
            if type(Value) ~= "table" then return Value end
            if Value.__type == "Color3" then
                return Color3.fromRGB(Value.R or 255, Value.G or 255, Value.B or 255)
            elseif Value.__type == "EnumItem" then
                local EnumTypeName = tostring(Value.EnumType or ""):match("^Enum%.(.+)$")
                local EnumType = EnumTypeName and Enum[EnumTypeName]
                if EnumType and Value.Name and EnumType[Value.Name] then return EnumType[Value.Name] end
            end
            return Value
        end
        local function ValidateConfigValue(FlagName, Value, Flag)
            local Kind = Runtime.ControlTypes[FlagName]
            if Kind == "CreateToggle" then
                assert(type(Value) == "boolean", "Toggle needs true/false")
            elseif Kind == "CreateSlider" then
                assert(type(Value) == "number" and Value == Value and math.abs(Value) < math.huge, "Invalid number")
                if Flag.Range then Value = math.clamp(Value, Flag.Range[1], Flag.Range[2]) end
            elseif Kind == "CreateDropdown" then
                if type(Value) == "string" then Value = {Value} end
                assert(type(Value) == "table", "Dropdown needs a selection")
                local Clean, Seen = {}, {}
                for _, Option in ipairs(Value) do
                    assert(type(Option) == "string" and table.find(Flag.Options or {}, Option), "Unavailable option")
                    if not Seen[Option] then table.insert(Clean, Option) Seen[Option] = true end
                end
                Value = Clean
            elseif Kind == "CreateInput" then
                assert(type(Value) == "string", "Input needs text")
            elseif Kind == "CreateKeybind" then
                local Key = Runtime.ResolveKeyCode(Value)
                assert(Key, "Invalid keybind")
                Value = Key.Name
            elseif Kind == "CreateColorPicker" then
                assert(typeof(Value) == "Color3", "Color picker needs a color")
                assert(Value.R == Value.R and Value.G == Value.G and Value.B == Value.B, "Invalid color")
            end
            return Value
        end
        local function CaptureCurrentConfig()
            local Data = {}
            for FlagName, Flag in pairs(Rayfield.Flags or {}) do
                local Value = Flag.CurrentValue or Flag.CurrentKeybind or Flag.CurrentOption or Flag.Color
                if typeof(Flag.CurrentValue) == "boolean" then Value = Flag.CurrentValue end
                if Value ~= nil then Data[FlagName] = PackConfigValue(Value) end
            end
            return HttpService:JSONEncode({Format = "BananiHub", Version = 2,
                Flags = Data, Session = Runtime.CaptureSession()})
        end
        SettingsTab:CreateParagraph({Title = "Save only when you choose", Content =
            "Every launch starts fresh. Save a configuration here to keep settings, favorites, waypoints and routes. Load it manually next time. Nothing is loaded automatically."})
        SettingsTab:CreateInput({
            Name = "Config Name", PlaceholderText = "Example: Grinding", RemoveTextAfterFocusLost = false,
            Callback = function(Value) SelectedConfigName = Value end})
        ConfigDropdown = SettingsTab:CreateDropdown({
            Name = "Saved Configurations", Options = GetConfigurations(), CurrentOption = {}, SearchBarEnabled = true,
            Callback = function(Option) SelectedConfigToLoad = type(Option) == "table" and Option[1] or Option end
        })
        SettingsTab:CreateButton({
            Name = "💾 Save New Configuration",
