                if not writefile then Notify("Configs", "File saving is unsupported.") return end
                local Path = NamedConfigFolder .. "/" .. Name .. ".json"
                if isfile and isfile(Path) then Notify("Configs", Name .. " already exists.") return end
                local Success = pcall(function() writefile(Path, CaptureCurrentConfig()) end)
                if Success then
                    SelectedConfigToLoad = Name
                    RefreshConfigDropdown()
                    Runtime.UpdatePreferenceDisplays()
                    Notify("Configs", "Saved " .. Name)
                else
                    Notify("Configs", "Could not save the config.")
                end
            end
        })
        SettingsTab:CreateButton({
            Name = "📂 Load Selected Configuration",
            Callback = function()
                local Name = CleanConfigName(SelectedConfigToLoad)
                if Name == "" then Notify("Configs", "Select a config first.") return end
                local Path = NamedConfigFolder .. "/" .. Name .. ".json"
                if not readfile or not isfile or not isfile(Path) then Notify("Configs", "That config was not found.") return end
                local Success, Data = pcall(function() return HttpService:JSONDecode(readfile(Path)) end)
                if not Success or type(Data) ~= "table" then Notify("Configs", "That config is invalid.") return end
                local Session
                if Data.Format == "BananiHub" then
                    if Data.Version ~= 2 or type(Data.Flags) ~= "table" then
                        Notify("Configs", "Unsupported configuration format.") return
                    end
                    Session, Data = Data.Session, Data.Flags
                end

                local LegacyParts = type(Data.Visuals_PlayerESPParts) == "table" and Data.Visuals_PlayerESPParts or {}
                local HadLegacyPlayerESP = Data.Visuals_PlayerESPParts ~= nil
                    or Data.Visuals_PlayerChams ~= nil or Data.Visuals_BoxESP ~= nil
                    or Data.Visuals_HealthESP ~= nil or Data.Visuals_Hitboxes ~= nil
                if Data.Visuals_PlayerESP == nil and HadLegacyPlayerESP then
                    Data.Visuals_PlayerESP = Data.Visuals_PlayerChams == true
                        or Data.Visuals_BoxESP == true or Data.Visuals_HealthESP == true
                        or Data.Visuals_Hitboxes == true
                        or table.find(LegacyParts, "Glow") ~= nil
                        or table.find(LegacyParts, "Box + Name + Distance") ~= nil
                        or table.find(LegacyParts, "Health") ~= nil
                end
                if Data.Visuals_PlayerESPExtras == nil and HadLegacyPlayerESP then
                    local Extras = {}
                    if Data.Visuals_PlayerChams == true or table.find(LegacyParts, "Glow") ~= nil then
                        table.insert(Extras, "Glow")
                    end
                    if Data.Visuals_HealthESP == true or table.find(LegacyParts, "Health") ~= nil then
                        table.insert(Extras, "Health Bar")
                    end
                    if Data.Visuals_Hitboxes == true then
                        table.insert(Extras, "Hitbox Outline")
                    end
                    Data.Visuals_PlayerESPExtras = Extras
                end
                if Data.Visuals_NPCFilter == nil and Data.Visuals_BossesOnly ~= nil then
                    Data.Visuals_NPCFilter = Data.Visuals_BossesOnly and "Bosses Only" or "All NPCs"
                end

                Data.Visuals_FocusMode = nil
                if Data.Visuals_RareExtras == nil
                    and (Data.Visuals_RareSound ~= nil or Data.Visuals_RareArrow ~= nil) then
                    local Extras = {}
                    if Data.Visuals_RareSound ~= false then table.insert(Extras, "Sound") end
                    if Data.Visuals_RareArrow ~= false then table.insert(Extras, "Direction Arrow") end
                    Data.Visuals_RareExtras = Extras
                end
                if Data.UIVisuals_TextStyle == nil then
                    local Styles = {}
                    if Data.UIVisuals_Bold == true then table.insert(Styles, "Bold") end
                    if Data.UIVisuals_Italic == true then table.insert(Styles, "Italic") end
                    if Data.UIVisuals_Underline == true then table.insert(Styles, "Underline") end
                    if Data.UIVisuals_Strike == true then table.insert(Styles, "Strikethrough") end
                    if #Styles > 0 or Data.UIVisuals_Bold ~= nil or Data.UIVisuals_Italic ~= nil
                        or Data.UIVisuals_Underline ~= nil or Data.UIVisuals_Strike ~= nil then
                        Data.UIVisuals_TextStyle = Styles
                    end
                end
                if Data.UIVisuals_RichTextOptions == nil
                    and (Data.UIVisuals_AllowEnableRich ~= nil or Data.UIVisuals_InputIsRich ~= nil) then
                    local RichOptions = {}
                    if Data.UIVisuals_AllowEnableRich ~= false then
                        table.insert(RichOptions, "Allow RichText When Needed")
                    end
                    if Data.UIVisuals_InputIsRich == true then
                        table.insert(RichOptions, "My Input Has RichText Tags")
                    end
                    Data.UIVisuals_RichTextOptions = RichOptions
                end
                if Data.Freecam_Extras == nil
                    and (Data.Freecam_Smooth ~= nil or Data.Freecam_Cinematic ~= nil) then
                    local CameraExtras = {}
                    if Data.Freecam_Smooth == true then table.insert(CameraExtras, "Smooth Movement") end
                    if Data.Freecam_Cinematic == true then table.insert(CameraExtras, "Cinematic Mode") end
                    Data.Freecam_Extras = CameraExtras
                end

                local AppliedCount, FailedCount = 0, 0
                local FlagNames = {}
                for FlagName in pairs(Data) do
                    if type(FlagName) == "string" then table.insert(FlagNames, FlagName) end
                end

                table.sort(FlagNames, function(A, B)
                    local AEnabled, BEnabled = Data[A] == true, Data[B] == true
                    if AEnabled ~= BEnabled then return not AEnabled end
                    return A < B
                end)
                if Runtime.ConfigLoadActive then
                    Notify("Configs", "A preset is already loading.")
                    return
                end
                MasterReset()
                Runtime.RestoreSession(Session)
                Runtime.ConfigLoadActive = true
                local ResetGeneration = Runtime.ResetGeneration
                for Index, FlagName in ipairs(FlagNames) do
                    if Unloaded or Runtime.ResetGeneration ~= ResetGeneration then break end
                    local Flag = Rayfield.Flags and Rayfield.Flags[FlagName]
                    if Flag and Flag.Set then
                        Runtime.ConfigCallbackFailed = false
                        local Applied = pcall(function() Flag:Set(ValidateConfigValue(FlagName, UnpackConfigValue(Data[FlagName]), Flag)) end)
                        if Applied and not Runtime.ConfigCallbackFailed then
                            AppliedCount += 1
                        else
                            FailedCount += 1
                        end
                    end
                    if Index % 20 == 0 then task.wait() end
                end
                Runtime.ConfigLoadActive = false
                Runtime.UpdatePreferenceDisplays()
                Notify("Configs", Name .. ": " .. AppliedCount .. " applied, " .. FailedCount .. " failed.")
            end
        })
        SettingsTab:CreateButton({ Name = "🔄 Refresh Configurations", Callback = RefreshConfigDropdown })

        SettingsTab:CreateSection("⭐ Pinned Features")
        Runtime.SelectedFavoriteFeature = Runtime.SelectedFavoriteFeature or Runtime.FavoriteOptions[1]
        SettingsTab:CreateDropdown({
            Name = "Select Feature", Options = Runtime.FavoriteOptions,
            CurrentOption = {Runtime.SelectedFavoriteFeature}, SearchBarEnabled = true,
            Callback = function(Option) Runtime.SelectedFavoriteFeature = type(Option) == "table" and Option[1] or Option end
        })
        SettingsTab:CreateButton({
            Name = "⭐ Pin Selected Feature",
            Callback = function()
                local Name = Runtime.SelectedFavoriteFeature
                if not Name or Name == "" then Notify("Favorites", "Select a feature first.") return end
                Runtime.Favorites[Name] = true
                Runtime.UpdatePreferenceDisplays()
            end
        })
        SettingsTab:CreateButton({
            Name = "➖ Unpin Selected Feature",
            Callback = function()
                local Name = Runtime.SelectedFavoriteFeature
                if not Name or Name == "" then Notify("Favorites", "Select a feature first.") return end
                Runtime.Favorites[Name] = nil
                Runtime.UpdatePreferenceDisplays()
            end
        })

        SettingsTab:CreateSection("⌨️ Interface Controls")
        SettingsTab:CreateKeybind({
            Name = "Open / Close BananiHub", CurrentKeybind = UIToggleKey.Name,
            HoldToInteract = false, CallOnChange = true, Flag = "Settings_UIKeybind",
            Callback = function(Key)
                local KeyName = typeof(Key) == "EnumItem" and Key.Name or tostring(Key or "")
                local ResolvedKey = Runtime.ResolveKeyCode(KeyName)
                if ResolvedKey then
                    UIToggleKey = ResolvedKey
                    Runtime.UpdatePreferenceDisplays()
                    Notify("Keybind", "UI key changed to " .. KeyName)
                end
            end
        })
        SettingsTab:CreateButton({
            Name = "👁️ Toggle BananiHub Now",
            Callback = function() if Rayfield.ToggleUI then Rayfield:ToggleUI() end end
        })
        SettingsTab:CreateSection("🩺 Diagnostics")
        Runtime.HealthParagraph = SettingsTab:CreateParagraph({
            Title = "Runtime Health",
            Content = "Run a health check after loading. Checks availability without activating features."
        })
        Runtime.RunHealthCheck = function()
            local Lines, Passed, Total = {}, 0, 0
            local ProfileReport = ""
            local function Check(Name, Condition)
                Total += 1
                if Condition then Passed += 1 end
                table.insert(Lines, (Condition and "PASS • " or "CHECK • ") .. Name)
            end
            Check("UI visibility control", type(Rayfield.ToggleUI) == "function")
            do
                local Env=(getgenv and getgenv()) or _G
                local PUI=(Runtime and Runtime.PremiumAppleUI) or (Env and Env.BananiHubPremiumUI)
                Check("Premium UI root", PUI~=nil and PUI.Gui~=nil and PUI.Gui.Parent~=nil)
            end
            Check("Main tab", Window ~= nil and type(Window.SelectTab) == "function")
            local HasSimple = false
            for _, UITab in ipairs(Rayfield._Tabs or {}) do
                if UITab.Name == "Simple" then HasSimple = true break end
            end
            Check("Simple tab removed", not HasSimple)
            Check("Live camera", workspace.CurrentCamera ~= nil)
            Check("Living character", Humanoid() ~= nil and Root() ~= nil and Humanoid().Health > 0)
            Check("Travel engine", type(Runtime.TravelToCFrame) == "function" and Runtime.Movement ~= nil)
            Check("Movement owner is valid", Runtime.Movement == nil or Runtime.Movement.Owner == nil or type(Runtime.Movement.Owner) == "string")
            Check("Item scanner", Runtime.VisualEngine ~= nil and type(Runtime.VisualEngine.PickUpAllItems) == "function")
            Check("UI editor", Runtime.UIVisuals ~= nil and type(Runtime.UIVisuals.Scan) == "function")
            Check("Premium motion system", type(Runtime.PremiumPolish)=="table" and Runtime.PremiumPolish.ReducedMotionAware==true)
            Check("Fruit notification isolated from notch", type(Runtime.PremiumPolish)=="table" and Runtime.PremiumPolish.FruitNotchIsolation==true)
            Check("No perpetual fruit-card animation", type(Runtime.PremiumPolish)=="table" and Runtime.PremiumPolish.FruitAlertLoopingAnimation==false)
            Check("Semantic status rows", type(Runtime.PremiumPolish)=="table" and Runtime.PremiumPolish.SemanticStatusRows==true)
            Check("Stable icon swap guard", type(Runtime.PremiumPolish)=="table" and Runtime.PremiumPolish.StableIconSwapGuard==true)
            Check("Compact restore guard", type(Runtime.PremiumPolish)=="table" and Runtime.PremiumPolish.CompactRestoreGuard==true)
            Check("Level-up interaction guard", type(Runtime.PremiumPolish)=="table" and Runtime.PremiumPolish.LevelUpInteractionGuard==true)
            Check("Priority notch queue", type(Runtime.AdvanceDynamicIslandNotificationQueue)=="function" and type(Runtime.GetDynamicIslandQueueStatus)=="function")
            Check("Notch importance levels", type(Runtime.DynamicIslandImportance)=="table" and Runtime.DynamicIslandImportance.CRITICAL==4 and Runtime.DynamicIslandImportance.LOW==1)
            Check("Saved-data support", type(readfile) == "function" and type(writefile) == "function" and type(isfile) == "function")
            for _, Name in ipairs({"Player_Fly", "Player_Noclip", "Visuals_PlayerESP",
                "Visuals_ItemESP", "Freecam_Enabled", "Settings_UIKeybind"}) do
                Check(Name, Rayfield.Flags ~= nil and Rayfield.Flags[Name] ~= nil)
            end
            if type(Runtime.GameProfileCheck)=="function" then
                local ProfileOK,Report=pcall(Runtime.GameProfileCheck)
                Check("Detected-game compatibility scan",ProfileOK and type(Report)=="string")
                if ProfileOK and type(Report)=="string" then ProfileReport="\n\n"..Report end
            end
            local SelfPassed,SelfRequired,SelfLines=0,0,{}
            if type(Runtime.RunProfileSelfTest)=="function" then
                local OK,A,B,C=pcall(Runtime.RunProfileSelfTest)
                if OK then SelfPassed,SelfRequired,SelfLines=A or 0,B or 0,C or {} end
            end
            local AutomationReport=type(Runtime.GetAutomationHealthReport)=="function"
                and Runtime.GetAutomationHealthReport(8) or "Automation health unavailable."
            local Scale=type(Runtime.GetVisualUpdateScale)=="function" and Runtime.GetVisualUpdateScale() or 1
            Runtime.HealthParagraph:Set({
                Title = "Runtime Health • " .. Passed .. "/" .. Total
                    .." • Profile "..tostring(SelfPassed).."/"..tostring(SelfRequired),
                Content = table.concat(Lines, "\n")
                    ..ProfileReport
                    .."\n\nPROFILE SELF-TEST\n"..table.concat(SelfLines,"\n")
                    .."\n\nAUTOMATION HEALTH\n"..AutomationReport
                    .."\n\nVisual update scale: x"..string.format("%.2f",Scale)
                    .."\nAvailability checks only; game-specific behavior still needs a live test."
            })
            return Passed == Total and SelfPassed==SelfRequired
        end
        SettingsTab:CreateButton({Name = "🩺 Run Full Health Check", Callback = function() Runtime.RunHealthCheck() end})
        SettingsTab:CreateButton({Name = "🧪 Run Profile Self-Test", Callback = function()
            local Passed,Required,Lines=Runtime.RunProfileSelfTest()
            Runtime.HealthParagraph:Set({
                Title="Profile Self-Test • "..tostring(Passed).."/"..tostring(Required),
                Content=table.concat(Lines,"\n").."\n\nNo features were activated by this test."
            })
        end})
        SettingsTab:CreateButton({Name = "📊 Show Automation Health", Callback = function()
            Runtime.HealthParagraph:Set({
                Title="Automation Health",
                Content=Runtime.GetAutomationHealthReport(12)
                    .."\n\nTiming is measured around each automation step; lower average ms is better."
            })
        end})

        SettingsTab:CreateSection("🧹 Reset & Unload")
        SettingsTab:CreateButton({ Name = "🚨 Reset All Active Features", Callback = MasterReset })
        Runtime.ExplicitUnloadArmedUntil=0
        SettingsTab:CreateButton({ Name = "🗑️ Unload BananiHub (Press Twice)", Callback = function()
            local Now=os.clock()
            if Now>(tonumber(Runtime.ExplicitUnloadArmedUntil) or 0) then
                Runtime.ExplicitUnloadArmedUntil=Now+3
                Notify("Unload BananiHub", "Press the unload button again within 3 seconds to fully stop the script.")
                return
            end
            Runtime.ExplicitUnloadArmedUntil=0
            UnloadBananiHub("explicit")
        end })
        Runtime.UpdatePreferenceDisplays()
    end)
    if not BuildSuccess then
        warn("BANANIHUB | Settings tab failed: " .. tostring(BuildError))
    end
end



