        local function PremiumMotionDuration(Duration)
            local Base=tonumber(Duration) or .18
            local Mode=tostring(Runtime.AnimationMode or "Smooth")
            if Runtime.ReducedMotion==true then return .01 end
            -- Smooth mode gets enough time to show intermediate frames without feeling slow.
            if Mode=="Smooth" then Base*=1.10
            elseif Mode=="Balanced" then Base*=.92
            elseif Mode=="Fast" then Base*=.76 end
            local FPS=tonumber(LiveTelemetry and LiveTelemetry.FPS) or 0
            local MinDuration=(Mode=="Fast") and .045 or ((Mode=="Balanced") and .052 or .060)
            local MaxDuration=(Mode=="Smooth") and 1.12 or ((Mode=="Balanced") and .86 or .84)
            if FPS>0 and FPS<32 then return math.clamp(Base*1.08,MinDuration,MaxDuration) end
            if FPS>0 and FPS<48 then return math.clamp(Base*1.04,MinDuration,MaxDuration) end
