            local Count=0
            for _ in pairs(Props) do Count=Count+1 end
            if Count>1 then
                local Last
                for Property,Value in pairs(Props) do
                    Last=Tw(Object,Duration,{[Property]=Value},Style,Direction,ExactDuration)
                end
                return Last
            elseif Count==0 then return end
            if Props.TextTransparency==0 and Object:GetAttribute("TaskActionEnabled")==false then
                Props=table.clone(Props)
                Props.TextTransparency=.48
            end
            local Bucket=PremiumActiveTweens[Object]
            if not Bucket then Bucket={}; PremiumActiveTweens[Object]=Bucket end
            for Property in pairs(Props or {}) do
                local Old=Bucket[Property]
