                end
                Runtime.ReleaseCleanup(X)
                S.TweenGoals[X]=nil
                local Current=PremiumActiveTweens[Object]
                if not Current then return end
                for Property in pairs(Props or {}) do if Current[Property]==X then Current[Property]=nil end end
                if next(Current)==nil then PremiumActiveTweens[Object]=nil end
