                CameraViewportConnection=nil
            end
            updateScale()
            local Current=workspace.CurrentCamera
            if Current then
                CameraViewportConnection=Runtime.TrackCleanup(Current:GetPropertyChangedSignal("ViewportSize"):Connect(updateScale),"Disconnect","PremiumCameraViewport","PremiumConnections")
            end
        end
        bindCameraViewport()
        trackPremiumConnection(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(bindCameraViewport))

        -- Closed-state Dynamic Island: one compact floating surface, fed by the shared FPS/ping sampler.
        -- Keep the original 8px floating gap. On single-click this SAME shell grows to contain
        -- the extra task information; there is no second card or visible bridge.
        local NotchTopY=8
        local Notch=N("TextButton",{
            Name="ClosedIsland",AnchorPoint=Vector2.new(.5,0),Position=UDim2.new(.5,0,0,NotchTopY),
            Size=UDim2.fromOffset(336,48),BackgroundColor3=Color3.fromRGB(3,3,4),BorderSizePixel=0,
            AutoButtonColor=false,Text="",Visible=false,ZIndex=220
        },Root)
        C(Notch,18)
        local NotchStroke=St(Notch,Color3.fromRGB(54,57,62),1,.16)
        local NotchGradient=G(Notch,Color3.fromRGB(15,15,17),Color3.fromRGB(2,2,3),0)
        local NotchScale=N("UIScale",{Scale=.90},Notch)

        -- v5.18.82 full native Blox Fruits Level Up feed mirror.
        -- The game itself is the animation source: BananiHub samples the live notification every frame
        -- instead of guessing timings. This includes shadow layers, movement, scale/size and fade.
        local LevelUpVFXToken=0
        local ActiveLevelUpVFX=nil
        local NativeBloxLevelStyleCache=nil

        local function PlainNativeNotificationText(Value)
            return tostring(Value or ""):gsub("<.->",""):gsub("%s+"," "):gsub("^%s+",""):gsub("%s+$","")
        end
        local function IsBananiGuiObject(Object)
            local IsOurs=false
            pcall(function() IsOurs=Object:IsDescendantOf(Gui) end)
            return IsOurs
        end
        local function NativeHierarchyVisible(Object)
            local Current=Object
            while Current and Current~=game do
                if Current:IsA("GuiObject") and Current.Visible==false then return false end
                if Current:IsA("ScreenGui") and Current.Enabled==false then return false end
                Current=Current.Parent
            end
            return true
        end
        local function NativeObjectOnScreen(Object)
            if not Object or not Object.Parent or not NativeHierarchyVisible(Object) then return false end
            if not Object:IsA("GuiObject") then return true end
            local Position=Object.AbsolutePosition
            local Size=Object.AbsoluteSize
            if Size.X<=0 or Size.Y<=0 then return false end
            local Camera=workspace.CurrentCamera
            local View=Camera and Camera.ViewportSize or Vector2.new(1920,1080)
            return Position.X+Size.X>0 and Position.Y+Size.Y>0 and Position.X<View.X and Position.Y<View.Y
        end
        local function NativeGroupVisibilityFactor(Object)
            local Factor=1
            local Parent=Object and Object.Parent
            while Parent and Parent~=game do
                if Parent:IsA("CanvasGroup") then
                    Factor*=1-math.clamp(tonumber(Parent.GroupTransparency) or 0,0,1)
                end
                Parent=Parent.Parent
            end
            return math.clamp(Factor,0,1)
        end
        local function EffectiveNativeTransparency(Object,Base)
            Base=math.clamp(tonumber(Base) or 0,0,1)
            local Factor=NativeGroupVisibilityFactor(Object)
            return 1-((1-Base)*Factor)
        end
        local function NotificationLabelMatches(Object,LevelNumber)
            if not Object or (not Object:IsA("TextLabel") and not Object:IsA("TextButton")) then return false end
            if IsBananiGuiObject(Object) then return false end
            local Plain=PlainNativeNotificationText(Object.Text)
            local Upper=string.upper(Plain)
            if not Upper:find("LEVEL UP",1,true) then return false end
            local Wanted=tostring(LevelNumber or "")
            if Wanted~="" and Wanted~="?" and not Plain:find(Wanted,1,true) then return false end
            return true
        end
        local function FindNativeBloxLevelVisuals(LevelNumber)
            local GuiRoot=Player and Player:FindFirstChildOfClass("PlayerGui")
            if not GuiRoot then return nil,{} end
            local Candidates={}
            for _,Object in ipairs(GuiRoot:GetDescendants()) do
                if NotificationLabelMatches(Object,LevelNumber) then
                    local Bounds=Object.TextBounds
                    local Area=(tonumber(Bounds.X) or 0)*(tonumber(Bounds.Y) or 0)
                    local Color=Object.TextColor3
                    local GreenBias=(Color.G*1.45)-(Color.R*.25)-(Color.B*.10)
                    local VisibleNow=NativeObjectOnScreen(Object) and EffectiveNativeTransparency(Object,Object.TextTransparency)<.995
                    local VisibleBonus=VisibleNow and 9000 or -9000
                    local AlphaBonus=(1-EffectiveNativeTransparency(Object,Object.TextTransparency))*2600
                    local Score=Area+GreenBias*1700+(tonumber(Object.TextSize) or 0)*20+VisibleBonus+AlphaBonus+(tonumber(Object.ZIndex) or 0)*4
                    table.insert(Candidates,{Object=Object,Score=Score,Visible=VisibleNow})
                end
            end
            table.sort(Candidates,function(A,B) return A.Score>B.Score end)
            local Primary=nil
            for _,Entry in ipairs(Candidates) do
                if Entry.Visible then Primary=Entry.Object; break end
            end
            if not Primary then return nil,{} end

            local PrimaryPlain=PlainNativeNotificationText(Primary.Text)
            local PCenter=Primary.AbsolutePosition+(Primary.AbsoluteSize/2)
            local Layers={}
            for _,Entry in ipairs(Candidates) do
                local Object=Entry.Object
                if PlainNativeNotificationText(Object.Text)==PrimaryPlain then
                    local Center=Object.AbsolutePosition+(Object.AbsoluteSize/2)
                    local DX=math.abs(Center.X-PCenter.X)
                    local DY=math.abs(Center.Y-PCenter.Y)
                    -- Blox Fruits uses closely-overlaid labels/shadows for parts of the notification feed.
                    if DX<=18 and DY<=18 then table.insert(Layers,Object) end
                end
            end
            if #Layers==0 then Layers={Primary} end
            table.sort(Layers,function(A,B)
                if A.ZIndex==B.ZIndex then return tostring(A.Name)<tostring(B.Name) end
                return A.ZIndex<B.ZIndex
            end)
            return Primary,Layers
        end
        local function CaptureNativeBloxLevelStyle(Source)
            if not Source or not Source.Parent then return nil end
            local Style={}
            local Props={"Font","TextSize","TextColor3","TextStrokeColor3","TextStrokeTransparency","TextTransparency","TextScaled","RichText","TextWrapped","TextXAlignment","TextYAlignment"}
            for _,Prop in ipairs(Props) do pcall(function() Style[Prop]=Source[Prop] end) end
            pcall(function() Style.FontFace=Source.FontFace end)
            Style.Text=tostring(Source.Text or "")
            NativeBloxLevelStyleCache=Style
            return Style
        end
        local function ApplyNativeBloxLevelStyle(Label,Style,LevelNumber)
            if not Label or not Label.Parent then return end
            Style=Style or NativeBloxLevelStyleCache
            if Style then
                local Props={"Font","TextSize","TextColor3","TextStrokeColor3","TextStrokeTransparency","TextTransparency","TextScaled","RichText","TextWrapped","TextXAlignment","TextYAlignment"}
                for _,Prop in ipairs(Props) do
                    local Value=Style[Prop]
                    if Value~=nil then pcall(function() Label[Prop]=Value end) end
                end
                if Style.FontFace then pcall(function() Label.FontFace=Style.FontFace end) end
                if Style.Text and Style.Text~="" then
                    local DisplayText=tostring(Style.Text)
                    if DisplayText:upper():find("LEVEL UP",1,true) then
                        DisplayText=DisplayText:gsub("%(%s*(%d+)%s*%)","%1")
                    end
                    Label.Text=DisplayText
                end
            else
                Label.Font=Enum.Font.GothamBold
                Label.TextSize=18
                Label.TextScaled=false
                Label.RichText=false
                Label.TextColor3=Color3.fromRGB(78,255,92)
                Label.TextStrokeColor3=Color3.fromRGB(18,18,18)
                Label.TextStrokeTransparency=.18
                Label.Text="LEVEL UP! "..tostring(LevelNumber or "?")
            end
        end
        local function SanitizeNativeVisualClone(Clone)
            for _,Object in ipairs(Clone:GetDescendants()) do
                if Object:IsA("LocalScript") or Object:IsA("Script") or Object:IsA("ModuleScript") or Object:IsA("UIScale") then
                    -- Source AbsoluteSize already contains the native UIScale result. Keeping the
                    -- cloned UIScale would apply the same scale twice inside the notch mirror.
                    Object:Destroy()
                elseif Object:IsA("GuiButton") then
                    pcall(function() Object.Active=false end)
                    pcall(function() Object.Selectable=false end)
                    pcall(function() Object.AutoButtonColor=false end)
                end
            end
            if Clone:IsA("GuiButton") then
                pcall(function() Clone.Active=false end)
                pcall(function() Clone.Selectable=false end)
                pcall(function() Clone.AutoButtonColor=false end)
            end
        end
        local function SyncNativeVisualPair(Source,Clone,IsRoot)
            if not Source or not Clone or not Source.Parent or not Clone.Parent then return end
            pcall(function() Clone.Visible=Source.Visible end)
            if Source:IsA("GuiObject") and Clone:IsA("GuiObject") then
                if not IsRoot then
                    pcall(function() Clone.Position=Source.Position end)
                    pcall(function() Clone.Size=Source.Size end)
                    pcall(function() Clone.AnchorPoint=Source.AnchorPoint end)
                end
                pcall(function() Clone.Rotation=Source.Rotation end)
                pcall(function() Clone.BackgroundColor3=Source.BackgroundColor3 end)
                pcall(function() Clone.BackgroundTransparency=EffectiveNativeTransparency(Source,Source.BackgroundTransparency) end)
                pcall(function() Clone.BorderSizePixel=Source.BorderSizePixel end)
            end
            if (Source:IsA("TextLabel") or Source:IsA("TextButton")) and (Clone:IsA("TextLabel") or Clone:IsA("TextButton")) then
                pcall(function()
                    local DisplayText=tostring(Source.Text or "")
                    if DisplayText:upper():find("LEVEL UP",1,true) then
                        DisplayText=DisplayText:gsub("%(%s*(%d+)%s*%)","%1")
                    end
                    Clone.Text=DisplayText
                end)
                pcall(function() Clone.RichText=Source.RichText end)
                pcall(function() Clone.TextColor3=Source.TextColor3 end)
                pcall(function() Clone.TextTransparency=EffectiveNativeTransparency(Source,Source.TextTransparency) end)
                pcall(function() Clone.TextStrokeColor3=Source.TextStrokeColor3 end)
                pcall(function() Clone.TextStrokeTransparency=EffectiveNativeTransparency(Source,Source.TextStrokeTransparency) end)
                pcall(function() Clone.TextSize=Source.TextSize end)
                pcall(function() Clone.TextScaled=Source.TextScaled end)
                pcall(function() Clone.TextWrapped=Source.TextWrapped end)
                pcall(function() Clone.TextXAlignment=Source.TextXAlignment end)
                pcall(function() Clone.TextYAlignment=Source.TextYAlignment end)
                pcall(function() Clone.Font=Source.Font end)
                pcall(function() Clone.FontFace=Source.FontFace end)
            elseif (Source:IsA("ImageLabel") or Source:IsA("ImageButton")) and (Clone:IsA("ImageLabel") or Clone:IsA("ImageButton")) then
                pcall(function() Clone.Image=Source.Image end)
                pcall(function() Clone.ImageColor3=Source.ImageColor3 end)
                pcall(function() Clone.ImageTransparency=EffectiveNativeTransparency(Source,Source.ImageTransparency) end)
                pcall(function() Clone.ScaleType=Source.ScaleType end)
            elseif Source:IsA("UIStroke") and Clone:IsA("UIStroke") then
                pcall(function() Clone.Color=Source.Color end)
                pcall(function() Clone.Thickness=Source.Thickness end)
                pcall(function() Clone.Transparency=EffectiveNativeTransparency(Source,Source.Transparency) end)
            elseif Source:IsA("UIGradient") and Clone:IsA("UIGradient") then
                pcall(function() Clone.Color=Source.Color end)
                pcall(function() Clone.Transparency=Source.Transparency end)
                pcall(function() Clone.Offset=Source.Offset end)
                pcall(function() Clone.Rotation=Source.Rotation end)
            elseif Source:IsA("UIScale") and Clone:IsA("UIScale") then
                pcall(function() Clone.Scale=Source.Scale end)
            elseif Source:IsA("UICorner") and Clone:IsA("UICorner") then
                pcall(function() Clone.CornerRadius=Source.CornerRadius end)
            elseif Source:IsA("CanvasGroup") and Clone:IsA("CanvasGroup") then
                pcall(function() Clone.GroupTransparency=Source.GroupTransparency end)
            end
        end
        local function PlayBloxFruitsLevelUpVFX(Info,OnFinished)
            if tostring(Runtime.DetectedGameProfileKind or "")~="BloxFruits" then return false end
            if not Root or not Root.Parent or not Notch or not Notch.Parent then return false end
            if type(Info)=="table" then
                Info.UIBound=true
                Info.HoldUntilUIFinish=true
                Info.UIFinished=false
            end
            LevelUpVFXToken+=1
            local Token=LevelUpVFXToken
            if ActiveLevelUpVFX and ActiveLevelUpVFX.Parent then pcall(function() ActiveLevelUpVFX:Destroy() end) end

            local LevelTitle=tostring((Info and Info.Title) or "LEVEL UP!")
            local LevelNumber=LevelTitle:match("(%d+)") or tostring(Runtime.DynamicIslandLastLevel or "?")
            local ExpectedText="LEVEL UP! "..tostring(LevelNumber)

            -- The native feed mirror lives directly inside the existing notch. The real Blox Fruits row
            -- is the only takeover content; its typography, motion, fade, scale, and lifetime stay native.
            local Layer=N("CanvasGroup",{
                Name="BloxFruitsExactLevelFeedInsideNotch",BackgroundTransparency=1,
                Position=UDim2.fromOffset(0,0),Size=UDim2.fromScale(1,1),
                GroupTransparency=0,ClipsDescendants=true,ZIndex=245
            },Notch)
            ActiveLevelUpVFX=Layer
            Runtime.BloxNativeLevelMirrorActive=true

            local NativeHolder=N("CanvasGroup",{
                Name="NativeFeedRow",AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
                Size=UDim2.fromOffset(1,1),BackgroundTransparency=1,GroupTransparency=0,
                ClipsDescendants=false,ZIndex=248
            },Layer)
            local NativeHolderScale=N("UIScale",{Scale=1},NativeHolder)

            -- v5.18.97: contained celebration layer. The notch stays pure black and all effects are
            -- clipped to its 336x48 shell, behind the native Blox Fruits LEVEL UP feed. The effects
            -- are short-lived decoration only; the native notification still owns takeover lifetime.
            local Celebration=N("CanvasGroup",{
                Name="ContainedLevelUpEffects",BackgroundTransparency=1,Position=UDim2.fromOffset(0,0),
                Size=UDim2.fromScale(1,1),GroupTransparency=0,ClipsDescendants=true,ZIndex=246
            },Layer)
            local Glow=N("Frame",{
                Name="GoldGlow",AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
                Size=UDim2.fromOffset(194,42),BackgroundColor3=Color3.fromRGB(255,181,52),
                BackgroundTransparency=.76,BorderSizePixel=0,ZIndex=246
            },Celebration); C(Glow,16)
            local GlowScale=N("UIScale",{Scale=.80},Glow)
            local Ring=N("Frame",{
                Name="GoldRing",AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
                Size=UDim2.fromOffset(20,20),BackgroundTransparency=1,BorderSizePixel=0,ZIndex=247
            },Celebration); C(Ring,999)
            local RingStroke=St(Ring,Color3.fromRGB(255,204,82),2.35,.025)
            local GoldTimeScale=1.45

            if Runtime.ReducedMotion==true then
                Glow.BackgroundTransparency=.88
                Tw(Glow,.28,{BackgroundTransparency=.72},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                task.delay(.32,function()
                    if Glow and Glow.Parent then Tw(Glow,.34,{BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out) end
                end)
            else
                Tw(GlowScale,.30*GoldTimeScale,{Scale=1.54},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                Tw(Glow,.24*GoldTimeScale,{BackgroundTransparency=.59},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Tw(Ring,.46*GoldTimeScale,{Size=UDim2.fromOffset(244,244)},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                Tw(RingStroke,.48*GoldTimeScale,{Transparency=1,Thickness=.8},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)

                local StreakAngles={8,48,92,136,184,228,272,316}
                for I,Angle in ipairs(StreakAngles) do
                    local Index=I
                    local Rad=math.rad(Angle)
                    local StartX=math.cos(Rad)*12
                    local StartY=math.sin(Rad)*5
                    local EndX=math.cos(Rad)*(74+((Index%3)*9))
                    local EndY=math.sin(Rad)*(15+((Index%2)*5))
                    local Streak=N("Frame",{
                        Name="Streak"..Index,AnchorPoint=Vector2.new(.5,.5),
                        Position=UDim2.new(.5,StartX,.5,StartY),Size=UDim2.fromOffset(2,8),
                        Rotation=Angle+90,BackgroundColor3=(Index%2==0) and Color3.fromRGB(255,228,137) or Color3.fromRGB(255,172,35),
                        BackgroundTransparency=.04,BorderSizePixel=0,ZIndex=247
                    },Celebration); C(Streak,2)
                    Tw(Streak,(.42+((Index%3)*.025))*GoldTimeScale,{
                        Position=UDim2.new(.5,EndX,.5,EndY),Size=UDim2.fromOffset(1,12),BackgroundTransparency=1
                    },Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                end

                local SparkAngles={6,27,49,72,95,118,141,164,187,210,233,256,279,302,325,348}
                for I,Angle in ipairs(SparkAngles) do
                    local Index=I
                    local Rad=math.rad(Angle)
                    local EndX=math.cos(Rad)*(68+((Index%4)*10))
                    local EndY=math.sin(Rad)*(14+((Index%3)*4))
                    local Spark=N("Frame",{
                        Name="Spark"..Index,AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
                        Size=UDim2.fromOffset((Index%3==0) and 4 or 3,(Index%3==0) and 4 or 3),
                        BackgroundColor3=(Index%2==0) and Color3.fromRGB(255,239,174) or Color3.fromRGB(255,191,60),
                        BackgroundTransparency=0,BorderSizePixel=0,ZIndex=247
                    },Celebration); C(Spark,999)
                    local Delay=(Index-1)*.012*GoldTimeScale
                    task.delay(Delay,function()
                        if not Spark or not Spark.Parent then return end
                        Tw(Spark,(.38+((Index%2)*.06))*GoldTimeScale,{Position=UDim2.new(.5,EndX,.5,EndY),Size=UDim2.fromOffset(1,1),BackgroundTransparency=1},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    end)
                end

                task.delay(.34*GoldTimeScale,function()
                    if Glow and Glow.Parent then
                        Tw(Glow,.42*GoldTimeScale,{BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        Tw(GlowScale,.42*GoldTimeScale,{Scale=1.88},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    end
                end)
            end
            local CelebrationLifetime=(Runtime.ReducedMotion==true) and .70 or S.MotionDelay(1.05*GoldTimeScale)
            task.delay(CelebrationLifetime,function()
                if Celebration and Celebration.Parent then pcall(function() Celebration:Destroy() end) end
            end)

            local Finished=false
            local NativePrimary=nil
            local NativeLayers={}
            local NativeClones={}
            local NativeBaseCenter=nil
            local NativeSeen=false
            local NativeLastVisibleAt=nil
            local NativeFitScale=1
            local MirrorConnection=nil

            local function StopMirrorConnection()
                if MirrorConnection then
                    pcall(function() MirrorConnection:Disconnect() end)
                    Runtime.ReleaseCleanup(MirrorConnection)
                    MirrorConnection=nil
                end
            end

            local function Finish()
                if Finished then return end
                Finished=true
                StopMirrorConnection()
                Runtime.BloxNativeLevelMirrorActive=false
                pcall(function() NotchScale.Scale=1 end)
                if Layer and Layer.Parent then pcall(function() Layer:Destroy() end) end
                if ActiveLevelUpVFX==Layer then ActiveLevelUpVFX=nil end

                local QueueItem=Runtime.DynamicIslandQueueActive or Runtime.DynamicIslandTakeover
                if QueueItem and tostring(QueueItem.IconKey or "")=="level" then
                    local Age=os.clock()-(tonumber(QueueItem.Started) or os.clock())
                    QueueItem.UIFinished=true
                    QueueItem.HoldUntilUIFinish=false
                    QueueItem.Duration=math.max(0,Age-.001)
                    if type(QueueItem.ResumeSnapshot)=="table" then
                        Runtime.DynamicIslandResumeSnapshot=Runtime.CopyDynamicIslandSnapshot(QueueItem.ResumeSnapshot)
                        Runtime.DynamicIslandResumeSnapshotUntil=os.clock()+.65
                    end
                    task.defer(function()
                        if type(Runtime.AdvanceDynamicIslandNotificationQueue)=="function" then Runtime.AdvanceDynamicIslandNotificationQueue() end
                    end)
                end
                if type(OnFinished)=="function" then task.defer(function() pcall(OnFinished) end) end
            end

            local function CloneNativeLayer(Source)
                if not Source or not Source.Parent then return nil end
                local OK,Clone=pcall(function() return Source:Clone() end)
                if not OK or not Clone then return nil end
                SanitizeNativeVisualClone(Clone)
                Clone.Name="Native_"..tostring(Source.Name)
                Clone.Parent=NativeHolder
                if Clone:IsA("GuiObject") then
                    Clone.AnchorPoint=Vector2.new(.5,.5)
                    Clone.BackgroundTransparency=1
                    Clone.Visible=true
                    pcall(function() Clone.Active=false end)
                end
                return Clone
            end

            local function SyncTextVisual(Source,Clone)
                if not Source or not Clone or not Source.Parent or not Clone.Parent then return end
                local PrimaryCenter=NativePrimary.AbsolutePosition+(NativePrimary.AbsoluteSize/2)
                local Center=Source.AbsolutePosition+(Source.AbsoluteSize/2)
                local Offset=Center-PrimaryCenter
                if Clone:IsA("GuiObject") then
                    Clone.Position=UDim2.fromOffset(Offset.X,Offset.Y)
                    Clone.Size=UDim2.fromOffset(math.max(1,Source.AbsoluteSize.X),math.max(1,Source.AbsoluteSize.Y))
                    Clone.Rotation=Source.AbsoluteRotation-NativePrimary.AbsoluteRotation
                    Clone.Visible=Source.Visible
                    pcall(function() Clone.ZIndex=248+math.clamp(Source.ZIndex-NativePrimary.ZIndex,-3,6) end)
                end
                if (Source:IsA("TextLabel") or Source:IsA("TextButton")) and (Clone:IsA("TextLabel") or Clone:IsA("TextButton")) then
                    local DisplayText=tostring(Source.Text or "")
                    if DisplayText:upper():find("LEVEL UP",1,true) then
                        DisplayText=DisplayText:gsub("%(%s*(%d+)%s*%)","%1")
                    end
                    Clone.Text=DisplayText
                    Clone.TextColor3=Source.TextColor3
                    Clone.TextTransparency=EffectiveNativeTransparency(Source,Source.TextTransparency)
                    Clone.TextStrokeColor3=Source.TextStrokeColor3
                    Clone.TextStrokeTransparency=EffectiveNativeTransparency(Source,Source.TextStrokeTransparency)
                    Clone.TextSize=Source.TextSize
                    Clone.TextScaled=Source.TextScaled
                    Clone.RichText=Source.RichText
                    Clone.TextWrapped=Source.TextWrapped
                    Clone.TextXAlignment=Source.TextXAlignment
                    Clone.TextYAlignment=Source.TextYAlignment
                    pcall(function() Clone.Font=Source.Font end)
                    pcall(function() Clone.FontFace=Source.FontFace end)
                end
                -- Keep native UIStroke / UIGradient descendants live as well. Their values can animate
                -- independently from the label itself in the notification feed.
                local SourceChildren=Source:GetChildren()
                local CloneChildren=Clone:GetChildren()
                for _,SC in ipairs(SourceChildren) do
                    if SC:IsA("UIStroke") or SC:IsA("UIGradient") then
                        for _,CC in ipairs(CloneChildren) do
                            if CC.ClassName==SC.ClassName and CC.Name==SC.Name then
                                SyncNativeVisualPair(SC,CC,false)
                                break
                            end
                        end
                    end
                end
            end

            local function BindNative(Primary,Layers)
                if Finished or Token~=LevelUpVFXToken or not Layer.Parent or not Primary or not Primary.Parent then return false end
                NativePrimary=Primary
                NativeLayers=Layers or {Primary}
                if #NativeLayers==0 then NativeLayers={Primary} end
                NativeBaseCenter=Primary.AbsolutePosition+(Primary.AbsoluteSize/2)
                CaptureNativeBloxLevelStyle(Primary)

                -- Size the feed row so its native typography fits inside the notch without changing
                -- proportions. The same uniform scale is applied to every native text/shadow layer.
                local MaxW,MaxH=math.max(1,Primary.AbsoluteSize.X),math.max(1,Primary.AbsoluteSize.Y)
                for _,Source in ipairs(NativeLayers) do
                    if Source and Source.Parent then
                        MaxW=math.max(MaxW,Source.AbsoluteSize.X)
                        MaxH=math.max(MaxH,Source.AbsoluteSize.Y)
                    end
                end
                local NotchW=math.max(1,Notch.AbsoluteSize.X)
                local NotchH=math.max(1,Notch.AbsoluteSize.Y)
                -- v5.18.98: use almost the whole physical notch instead of leaving the older wide
                -- safety margins. Allow a small upscale when the native feed row is naturally compact,
                -- but preserve aspect ratio and keep the final result clipped inside the black shell.
                NativeFitScale=math.min(1.16,(NotchW-8)/MaxW,(NotchH-2)/MaxH)
                NativeFitScale=math.clamp(NativeFitScale,.50,1.16)
                NativeHolderScale.Scale=NativeFitScale

                for _,Source in ipairs(NativeLayers) do
                    local Clone=CloneNativeLayer(Source)
                    if Clone then
                        table.insert(NativeClones,{Source=Source,Clone=Clone})
                        SyncTextVisual(Source,Clone)
                    end
                end
                if #NativeClones==0 then return false end

                -- No custom bounce: the Blox Fruits row itself supplies the movement, scale and fade.
                MirrorConnection=Runtime.TrackCleanup(game:GetService("RunService").RenderStepped:Connect(function()
                    if Finished or Token~=LevelUpVFXToken or not Layer.Parent then Finish(); return end
                    if not NativePrimary or not NativePrimary.Parent then Finish(); return end

                    local Center=NativePrimary.AbsolutePosition+(NativePrimary.AbsoluteSize/2)
                    local Delta=Center-(NativeBaseCenter or Center)
                    local Alpha=EffectiveNativeTransparency(NativePrimary,NativePrimary.TextTransparency)
                    local VisibleNow=NativeObjectOnScreen(NativePrimary) and Alpha<.985
                    if VisibleNow then
