                        NativeLastVisibleAt=os.clock()
                    end

                    -- A notification row can be recycled instead of destroyed. As soon as it stops being
                    -- the same LEVEL UP row, or is truly gone from the visible hierarchy/screen, restore.
                    if NativeSeen and not NotificationLabelMatches(NativePrimary,LevelNumber) then
                        Finish(); return
                    end
                    if NativeSeen and not VisibleNow and NativeLastVisibleAt and os.clock()-NativeLastVisibleAt>.14 then
