        local ExpandedLogoPosition=CompactLogoPosition -- keep the same compact icon presentation while expanded.
        local function RestoreCompactIconPresentation(Instant)
            local D=Instant and 0 or .16
            if D<=0 then
                NotchUI.Logo.Position=CompactLogoPosition
                NotchUI.Logo.BackgroundTransparency=0
                NotchLogoStroke.Transparency=.25
                NotchLogoGlow.BackgroundTransparency=.84
                NotchLogoSheen.BackgroundTransparency=.92
                ActivityIconScale.Scale=1
                AvatarScale.Scale=1
            else
                Tw(NotchUI.Logo,D,{Position=CompactLogoPosition,BackgroundTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                Tw(NotchLogoStroke,D,{Transparency=.25},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Tw(NotchLogoGlow,D,{BackgroundTransparency=.84},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Tw(NotchLogoSheen,D,{BackgroundTransparency=.92},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Tw(ActivityIconScale,math.max(.12,D),{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Tw(AvatarScale,math.max(.12,D),{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
            end
        end
        local function SetCompactLayerSuppressed(Suppressed,Instant)
            Suppressed=Suppressed==true
            CompactLayerSuppressed=Suppressed
            local Duration=Instant and 0 or (Suppressed and .145 or .185)
            local IconDuration=Instant and 0 or (Suppressed and .305 or .275)
            local function Apply(Object,Props,Style,Direction,OverrideDuration)
                if not Object or not Object.Parent then return end
                local D=OverrideDuration==nil and Duration or OverrideDuration
                if D<=0 then
                    for K,V in pairs(Props) do Object[K]=V end
                else
                    Tw(Object,D,Props,Style or Enum.EasingStyle.Sine,Direction or Enum.EasingDirection.Out)
                end
            end

            if Suppressed then
                -- Expanded state keeps exactly ONE piece of compact identity: the task icon.
                -- All compact text/status/progress disappears before expanded information reveals.
                Apply(NotchUI.Brand,{TextTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                Apply(NotchUI.State,{TextTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                NotchUI.BrandGhost.TextTransparency=1; NotchUI.StateGhost.TextTransparency=1
                Apply(NotchUI.Dot,{BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                Apply(NotchDotStroke,{Transparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                Apply(NotchUI.ProgressTrack,{BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                Apply(NotchUI.ProgressFill,{BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                NotchUI.Hint.TextTransparency=1

                -- The icon itself glides down/left into the expanded header instead of fading out
                -- and being replaced by a duplicate icon.
                Apply(NotchUI.Logo,{BackgroundTransparency=0,Position=ExpandedLogoPosition},Enum.EasingStyle.Quart,Enum.EasingDirection.Out,IconDuration)
                Apply(NotchLogoStroke,{Transparency=.25},Enum.EasingStyle.Sine,Enum.EasingDirection.Out,IconDuration)
                Apply(NotchLogoGlow,{BackgroundTransparency=.80},Enum.EasingStyle.Sine,Enum.EasingDirection.Out,IconDuration)
                Apply(NotchLogoSheen,{BackgroundTransparency=.92},Enum.EasingStyle.Sine,Enum.EasingDirection.Out,IconDuration)
                if NotchUI.ActivityIcon.Visible then
                    Apply(NotchUI.ActivityIcon,{GroupTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out,IconDuration)
                    NotchUI.Avatar.ImageTransparency=1
                else
                    Apply(NotchUI.Avatar,{ImageTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out,IconDuration)
                    NotchUI.ActivityIcon.GroupTransparency=1
                end
            else
                RestoreCompactIconPresentation(Instant or Runtime.ReducedMotion==true)
                Apply(NotchUI.Brand,{TextTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Apply(NotchUI.State,{TextTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Apply(NotchUI.Dot,{BackgroundTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Apply(NotchDotStroke,{Transparency=.15},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Apply(NotchUI.ProgressTrack,{BackgroundTransparency=.28},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                Apply(NotchUI.ProgressFill,{BackgroundTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                if NotchUI.ActivityIcon.Visible then
                    Apply(NotchUI.ActivityIcon,{GroupTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out,IconDuration)
                    NotchUI.Avatar.ImageTransparency=1
                else
                    HideTaskIconParts()
                    NotchUI.ActivityIcon.Visible=false
                    NotchUI.ActivityIcon.GroupTransparency=1
                    Apply(NotchUI.Avatar,{ImageTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out,IconDuration)
                end
            end
        end

        local function InvalidateNotchTextTransitions()
            for _,Label in ipairs({NotchUI.Brand,NotchUI.State}) do
