        local NotchHealthConnections={}
        local function ClearNotchHealthConnections()
            for _,Connection in ipairs(NotchHealthConnections) do pcall(function() Connection:Disconnect() end) end
            table.clear(NotchHealthConnections)
        end
        local function RefreshNotchHealth(Animate)
            local H=Humanoid()
            local Health=(H and tonumber(H.Health)) or 0
            local MaxHealth=(H and tonumber(H.MaxHealth)) or 0
            local Ratio=MaxHealth>0 and math.clamp(Health/MaxHealth,0,1) or 0
            if H and MaxHealth>0 then
                NotchUI.HPValue.Text=tostring(math.floor(Health+0.5)).."/"..tostring(math.floor(MaxHealth+0.5))
            else
                NotchUI.HPValue.Text="-- / --"
            end
            local TargetSize=UDim2.new(Ratio,0,1,0)
            if Animate and Notch.Visible then
                Tw(NotchUI.HPFill,.11,{Size=TargetSize},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            else
                NotchUI.HPFill.Size=TargetSize
            end
            local TargetColor
            if Ratio<=.25 then TargetColor=Color3.fromRGB(255,75,88)
            elseif Ratio<=.55 then TargetColor=Color3.fromRGB(245,190,66)
            else TargetColor=Color3.fromRGB(66,214,139) end
            if Animate and Notch.Visible then Tw(NotchUI.HPFill,.12,{BackgroundColor3=TargetColor},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            else NotchUI.HPFill.BackgroundColor3=TargetColor end
        end
        local function BindNotchHealth()
            local H=Humanoid()
            if H==NotchHealthHumanoid and (not H or H.Parent) then return end
            ClearNotchHealthConnections()
            NotchHealthHumanoid=H
            if H then
                local C1=H.HealthChanged:Connect(function() RefreshNotchHealth(true) end)
                local C2=H:GetPropertyChangedSignal("MaxHealth"):Connect(function() RefreshNotchHealth(true) end)
                table.insert(NotchHealthConnections,C1); table.insert(NotchHealthConnections,C2)
            end
            RefreshNotchHealth(false)
        end
        trackPremiumConnection(PPlayer.CharacterAdded:Connect(function()
            task.defer(function() if Gui.Parent then BindNotchHealth() end end)
        end))
        S.GetDynamicIslandLiveText=function()
            local Provider=Runtime.GetDynamicIslandDisplayStatus or Runtime.GetDynamicIslandStatus or Runtime.GetSmartIslandStatus
            if type(Provider)=="function" then
                local OK,Info=pcall(Provider)
                if OK and type(Info)=="table" then
                    local Title=tostring(Info.Title or "BananiHub")
                    local Detail=tostring(Info.Detail or "")
                    local StateText=tostring(Info.State or "")
                    local IconKey=tostring(Info.IconKey or "idle")
                    local Progress=math.clamp(tonumber(Info.Progress) or 0,0,1)

                    -- v5.18.63 hard guard: fruit detection/collection belongs ONLY to the separate
                    -- fruit notification. Even an old/custom status provider cannot make fruit take
                    -- over the notch. Auto Farm stays visible while it temporarily yields to fruit.
                    if IconKey=="fruit" then
                        local SafeInfo={}
                        for K,V in pairs(Info) do SafeInfo[K]=V end
                        if Runtime.BloxAutoLevelActive then
                            Title="Auto Farm"
                            Detail="Quest target"
                            StateText="Working"
                            IconKey="combat"
                            Progress=math.clamp(tonumber(Runtime.BloxQuestProgressPercent) or 0,0,1)
                            SafeInfo.Title=Title; SafeInfo.Detail=Detail; SafeInfo.State=StateText
                            SafeInfo.IconKey=IconKey; SafeInfo.Progress=Progress
                        else
                            Title="Blox Fruits"
                            Detail=""
                            StateText="Ready"
                            IconKey="idle"
                            Progress=0
                            SafeInfo.Title=Title; SafeInfo.Detail=Detail; SafeInfo.State=StateText
                            SafeInfo.IconKey=IconKey; SafeInfo.Progress=Progress
                        end
                        Info=SafeInfo
                    end

                    -- "Ready" is an idle state. Older notch logic treated it as active and
                    -- could show an activity icon/theme even when nothing was running.
                    local StateLower=string.lower(StateText)
                    local Active=not (StateLower=="" or StateLower=="idle" or StateLower=="ready" or StateLower=="off" or StateLower=="stopped"
                        or StateLower=="disabled" or StateLower=="inactive" or StateLower=="not active")
                    if IconKey=="level" or StateLower=="paused" then Active=true end

                    local function Trim(X)
                        X=tostring(X or "")
                        return X:gsub("^%s+",""):gsub("%s+$","")
                    end
                    local function Segments(X)
                        local Out={}
                        for Part in string.gmatch(tostring(X or ""),"[^•]+") do
                            Part=Trim(Part)
                            if Part~="" then table.insert(Out,Part) end
                        end
                        return Out
                    end
                    local Seg=Segments(Detail)
                    local Top=Title
                    local Bottom=""

                    -- Compact mode intentionally shows only activity + one short useful detail.
                    -- Everything else belongs in the tap-to-expand panel.
                    if IconKey=="level" then
                        Top=Title
                        Bottom="Level Up!"
                    elseif StateLower=="paused" then
                        Top=Title
                        Bottom="Tap to manage"
                    elseif IconKey=="raid" then
                        local Island,Clock=nil,nil
                        for _,V in ipairs(Seg) do
                            if not Island and string.lower(V):match("^island%s+%d+") then Island=V end
                            if not Clock then Clock=V:match("%d%d:%d%d") end
                        end
                        Top=Island and ("Raid • "..Island) or "Raid"
                        Bottom=Clock or StateText
                    elseif IconKey=="combat" and string.find(string.lower(Title),"auto farm",1,true) then
                        local Lvl=Title:match("[Ll]v%.?%s*(%d+)")
                        Top="Auto Farm"
                        if Lvl and Progress>0 then
                            Bottom="LV "..Lvl.."  •  "..tostring(math.floor(Progress*100+0.5)).."%"
                        elseif Lvl then
                            Bottom="LV "..Lvl
                        else
                            Bottom=StateText~="" and StateText or "Working"
                        end
                    elseif IconKey=="fruit" then
                        Top="Fruit"
                        Bottom=Seg[1] or "Collecting"
                    elseif IconKey=="fish" then
                        Top="Fishing"
                        Bottom=StateText~="" and StateText or (Seg[1] or "Fishing")
                    elseif IconKey=="boss" then
                        Top="Boss"
                        Bottom=Seg[1] or StateText or "Hunting"
                    elseif IconKey=="travel" then
                        Top="Traveling"
                        Bottom=Seg[1] or StateText or "Moving"
                    elseif IconKey=="coin" then
                        Top="Coin Farm"
                        Bottom=StateText~="" and StateText or "Collecting"
                    elseif IconKey=="care" then
                        Top="Auto Care"
                        Bottom=Seg[1] or StateText or "Caring"
                    elseif IconKey=="hidden" then
                        Top="Invisible"
                        Bottom="Active"
                    elseif IconKey=="shield" then
                        Top="Auto Survive"
                        Bottom=StateText~="" and StateText or "Watching"
                    elseif Active then
                        -- Remove repetitive game prefixes in the compact surface.
                        Top=Title:gsub("^MM2%s*•%s*",""):gsub("^Adopt Me%s*•%s*",""):gsub("^Blox Fruits%s*•%s*","")
                        Bottom=StateText~="" and StateText or (Seg[1] or "Active")
                    else
                        Top=Title
                        Bottom="Ready"
                    end

                    return Trim(Top),Trim(Bottom),Active,Info
                end
            end

            -- Compatibility fallback if the provider is unavailable during interrupted boot.
            local ActiveName=Runtime and Runtime.ActiveAutomationName or nil
            local ActiveState=Runtime and tostring(Runtime.ActiveAutomationState or "Idle") or "Idle"
            if ActiveName and ActiveState~="Idle" then
                local Feature=tostring(ActiveName):gsub("(%l)(%u)","%1 %2"):gsub("_"," ")
                return Feature,ActiveState,true,{Title=Feature,Detail=ActiveState,State=ActiveState,Progress=0,IconKey="work"}
            end
            return "BananiHub","Ready",false,{Title="BananiHub",Detail="",State="Idle",Progress=0,IconKey="idle"}
        end
        local function SemanticText(Value)
            Value=tostring(Value or "")
            -- Numeric-only live changes (timer, HP, counts, percentages) should not
            -- retrigger the full crossfade every refresh.
            return Value:gsub("%d+","0")
        end
        local function AnimateCompactText(Label,Ghost,NewText,BasePos,OldText)
            NewText=tostring(NewText or "")
            OldText=tostring(OldText or "")
            local Hidden=CompactLayerSuppressed or LevelUpDropActive
            if NewText==OldText then
                Label.Text=NewText
                Label.Position=BasePos
                Label.TextTransparency=Hidden and 1 or 0
                Ghost.TextTransparency=1
                return NewText
            end
            if Hidden then
                Label.Text=NewText
                Label.Position=BasePos
                Label.TextTransparency=1
                Ghost.TextTransparency=1
                return NewText
            end
            if Runtime.ReducedMotion==true or not Notch.Visible or SemanticText(NewText)==SemanticText(OldText) then
                Label.Text=NewText
                Label.TextTransparency=0
                Label.Position=BasePos
                Ghost.TextTransparency=1
                return NewText
            end
            local Token=(CompactTextTokens[Label] or 0)+1
            CompactTextTokens[Label]=Token
            Ghost.Text=OldText
            Ghost.Position=BasePos
            Ghost.TextTransparency=0
            Label.Text=NewText
            Label.Position=UDim2.new(BasePos.X.Scale,BasePos.X.Offset,BasePos.Y.Scale,BasePos.Y.Offset+2)
            Label.TextTransparency=1
            Tw(Ghost,.12,{TextTransparency=1,Position=UDim2.new(BasePos.X.Scale,BasePos.X.Offset,BasePos.Y.Scale,BasePos.Y.Offset-2)},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
            Tw(Label,.18,{TextTransparency=0,Position=BasePos},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
            task.delay(S.MotionDelay(.19),function()
                if not Gui.Parent or CompactTextTokens[Label]~=Token then return end
                Ghost.TextTransparency=1
                Ghost.Position=BasePos
            end)
            return NewText
        end
        local function AnimateMiniText(Label,Ghost,NewText,BasePos,OldText)
            NewText=tostring(NewText or "")
            OldText=tostring(OldText or "")
            if NewText==OldText then return NewText end
            if Runtime.ReducedMotion==true or not NotchMiniExpanded or not NotchMini.Visible or SemanticText(NewText)==SemanticText(OldText) then
                Label.Text=NewText
                Label.TextTransparency=0
                Label.Position=BasePos
                Ghost.TextTransparency=1
                return NewText
            end
            local Token=(MiniTextTokens[Label] or 0)+1
            MiniTextTokens[Label]=Token
            Ghost.Text=OldText
            Ghost.Position=BasePos
            Ghost.TextTransparency=0
            Label.Text=NewText
            Label.TextTransparency=1
            Label.Position=UDim2.new(BasePos.X.Scale,BasePos.X.Offset+3,BasePos.Y.Scale,BasePos.Y.Offset)
            Tw(Ghost,.11,{TextTransparency=1,Position=UDim2.new(BasePos.X.Scale,BasePos.X.Offset-3,BasePos.Y.Scale,BasePos.Y.Offset)},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
            Tw(Label,.17,{TextTransparency=0,Position=BasePos},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
            task.delay(S.MotionDelay(.18),function()
                if not Gui.Parent or MiniTextTokens[Label]~=Token then return end
                Ghost.TextTransparency=1
                Ghost.Position=BasePos
            end)
            return NewText
        end

        local NotchFeatureThemes={
            idle={Accent=Theme.Green,Stroke=Color3.fromRGB(54,57,62),Logo=Color3.fromRGB(21,21,23)},
            autofarm={Accent=Color3.fromRGB(255,193,63),Stroke=Color3.fromRGB(122,91,36),Logo=Color3.fromRGB(31,24,13)},
            raid={Accent=Color3.fromRGB(135,104,255),Stroke=Color3.fromRGB(92,72,165),Logo=Color3.fromRGB(23,18,42)},
            fruit={Accent=Color3.fromRGB(255,101,145),Stroke=Color3.fromRGB(139,65,89),Logo=Color3.fromRGB(39,17,25)},
            fish={Accent=Color3.fromRGB(74,196,225),Stroke=Color3.fromRGB(54,112,128),Logo=Color3.fromRGB(13,30,36)},
            boss={Accent=Color3.fromRGB(243,83,88),Stroke=Color3.fromRGB(137,55,59),Logo=Color3.fromRGB(39,15,17)},
            mm2={Accent=Color3.fromRGB(194,111,255),Stroke=Color3.fromRGB(111,68,143),Logo=Color3.fromRGB(31,18,40)},
            adopt={Accent=Color3.fromRGB(76,214,174),Stroke=Color3.fromRGB(55,125,105),Logo=Color3.fromRGB(14,34,29)},
            care={Accent=Color3.fromRGB(76,214,174),Stroke=Color3.fromRGB(55,125,105),Logo=Color3.fromRGB(14,34,29)},
            travel={Accent=Color3.fromRGB(87,158,255),Stroke=Color3.fromRGB(59,94,144),Logo=Color3.fromRGB(15,25,39)},
            shield={Accent=Color3.fromRGB(94,178,255),Stroke=Color3.fromRGB(63,101,150),Logo=Color3.fromRGB(16,27,40)},
            work={Accent=Color3.fromRGB(204,208,218),Stroke=Color3.fromRGB(91,95,105),Logo=Color3.fromRGB(22,23,27)}
        }
        local CurrentNotchThemeKey=nil
        local function ResolveNotchTheme(Info,Active)
            if not Active then return "idle",NotchFeatureThemes.idle end
            local IconKey=tostring(Info and Info.IconKey or "")
            local Kind=tostring(Info and Info.Kind or Runtime.DetectedGameProfileKind or "")
            local Title=tostring(Info and Info.Title or ""):lower()
            if IconKey=="raid" then return "raid",NotchFeatureThemes.raid end
            if IconKey=="fruit" then return "fruit",NotchFeatureThemes.fruit end
            if IconKey=="fish" then return "fish",NotchFeatureThemes.fish end
            if IconKey=="boss" then return "boss",NotchFeatureThemes.boss end
            if Kind=="MM2" or Title:find("mm2",1,true) or Title:find("murder mystery",1,true) then return "mm2",NotchFeatureThemes.mm2 end
            if Kind=="AdoptMe" or Title:find("adopt me",1,true) then return "adopt",NotchFeatureThemes.adopt end
            if IconKey=="care" then return "care",NotchFeatureThemes.care end
            if IconKey=="travel" then return "travel",NotchFeatureThemes.travel end
            if IconKey=="shield" then return "shield",NotchFeatureThemes.shield end
            if IconKey=="work" then return "work",NotchFeatureThemes.work end
            if IconKey=="combat" or Title:find("auto farm",1,true) or Title:find("material farm",1,true) then return "autofarm",NotchFeatureThemes.autofarm end
            return "work",NotchFeatureThemes.work
        end
        local function ApplyNotchTheme(Info,Active)
            local Key,Palette=ResolveNotchTheme(Info,Active)
            if Key==CurrentNotchThemeKey then return Palette end
            CurrentNotchThemeKey=Key
            local Animate=Notch.Visible and Runtime.ReducedMotion~=true
            local function Apply(Object,Property,Value,Duration)
                if Animate then Tw(Object,Duration or .20,{[Property]=Value},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                else Object[Property]=Value end
            end
            Apply(NotchStroke,"Color",Palette.Stroke,.20)
            Apply(NotchUI.Logo,"BackgroundColor3",Palette.Logo,.20)
            Apply(NotchLogoGlow,"BackgroundColor3",Palette.Accent,.18)
            for _,Part in ipairs(TaskIconParts) do
                if Part.Visible then Apply(Part,"BackgroundColor3",Palette.Accent,.18) end
            end
            Apply(NotchUI.ProgressFill,"BackgroundColor3",Palette.Accent,.18)
            Apply(NotchMiniAccent,"BackgroundColor3",Color3.fromRGB(255,255,255),.18)
            Apply(NotchBridgeAccent,"BackgroundColor3",Color3.fromRGB(255,255,255),.18)
            Apply(NotchMiniIconBack,"BackgroundColor3",Palette.Logo,.20)
            Apply(NotchMiniIconGlow,"BackgroundColor3",Palette.Accent,.18)
            for _,Part in ipairs(MiniTaskIconParts) do
                if Part.Visible then Apply(Part,"BackgroundColor3",Palette.Accent,.18) end
            end
            Apply(NotchMiniProgressFill,"BackgroundColor3",Palette.Accent,.18)
            Apply(NotchMiniState,"TextColor3",Theme.Text,.18)
            Apply(NotchMiniStroke,"Color",Palette.Stroke,.20)
            Apply(NotchMiniIconStroke,"Color",Palette.Stroke,.20)
            return Palette
        end

        local function ParseMiniDetail(Info)
            local Detail=tostring(Info and Info.Detail or "")
            local IconKey=tostring(Info and Info.IconKey or "")
            local Segments={}
            for Seg in string.gmatch(Detail,"[^•]+") do
                Seg=tostring(Seg):gsub("^%s+",""):gsub("%s+$","")
                if Seg~="" then table.insert(Segments,Seg) end
            end
            local Timer="—"
            for _,Seg in ipairs(Segments) do
                local Clock=Seg:match("(%d%d:%d%d)") or Seg:match("(%-%-:%-%-)")
                if Clock then Timer=Clock; break end
            end
            local function IsMeta(Seg)
                return Seg==Timer or Seg:match("^%d+%s*/%s*%d+$")~=nil
            end
            local Target=nil
            if IconKey=="raid" then
                for I=#Segments,1,-1 do
                    local Seg=Segments[I]
                    if not IsMeta(Seg) and not Seg:lower():match("^island%s+%d+") then Target=Seg; break end
                end
                if not Target then
                    for _,Seg in ipairs(Segments) do if not IsMeta(Seg) then Target=Seg; break end end
                end
            else
                for _,Seg in ipairs(Segments) do if not IsMeta(Seg) then Target=Seg; break end end
            end
            return Target or "—",Timer
        end
        local function ResolveMiniDetailLabel(Info,Target)
            local Explicit=tostring(Info and Info.DetailLabel or "")
            if Explicit~="" then return string.upper(Explicit) end
            local IconKey=tostring(Info and Info.IconKey or "")
            local Title=string.lower(tostring(Info and Info.Title or ""))
            local Detail=tostring(Target or "—")
            local Kind=tostring(Info and Info.Kind or "")
            if Title:find("build a boat",1,true) then return "STAGE" end
            if Title:find("bloxburg",1,true) then
                if Title:find("job",1,true) or Title:find("pizza",1,true) or Title:find("ice cream",1,true) then return "JOB" end
                if Title:find("skill",1,true) then return "SKILL" end
                return "ACTION"
            end
            if Kind=="BasketballLegends" or Title:find("basketball",1,true) then return "ACTION" end
            if Kind=="Arsenal" or Kind=="MVS" then return IconKey=="travel" and "MOVEMENT" or "TARGET" end
            if Kind=="PrisonLife" then
                if Title:find("gun",1,true) then return "WEAPON" end
                if Title:find("item",1,true) then return "ITEM" end
                return "TARGET"
            end
            if IconKey=="combat" then return "TARGET" end
            if IconKey=="boss" then return "BOSS" end
            if IconKey=="raid" then return Detail:lower():match("^island%s+%d+") and "ISLAND" or "DETAIL" end
            if IconKey=="fruit" then return "FRUIT" end
            if IconKey=="fish" then return "ACTION" end
            if IconKey=="travel" then return "LOCATION" end
            if IconKey=="coin" then return "ROUTE" end
            if IconKey=="care" then return "TASK" end
            if IconKey=="hidden" then return "MODE" end
            if IconKey=="shield" then return "STATUS" end
            if IconKey=="work" then return "ACTION" end
            if Title:find("factory",1,true) then return "EVENT" end
            return "DETAIL"
        end
        local function SetMiniChildTransparency(Object,Value)
            if not Object then return end
            if Object:IsA("TextLabel") or Object:IsA("TextButton") then
                Object.TextTransparency=Value
            elseif Object:IsA("ImageLabel") then
                Object.ImageTransparency=Value
            elseif Object:IsA("CanvasGroup") then
                Object.GroupTransparency=Value
            end
            if Object:IsA("TextButton") then
                Object.BackgroundTransparency=math.clamp(.08+Value*.88,0,1)
            elseif Object:IsA("Frame") then
                Object.BackgroundTransparency=math.clamp(Value,0,1)
            end
        end
        local function AnimateMiniReveal(Token,PreserveCurrent)
            -- Legacy expanded icon is compatibility-only. Never let reveal logic resurrect it.
            NotchMiniIconBack.Visible=false
            NotchMiniAvatar.Visible=false
            NotchMiniIcon.Visible=false
            NotchMiniIcon.GroupTransparency=1
            if Runtime.ReducedMotion==true then
                for _,Object in ipairs(MiniRevealObjects) do
                    if Object and Object.Parent then
                        if Object:IsA("TextLabel") or Object:IsA("TextButton") then Object.TextTransparency=Object:GetAttribute("TaskActionEnabled")==false and .48 or 0
                        elseif Object:IsA("ImageLabel") then Object.ImageTransparency=0
                        elseif Object:IsA("CanvasGroup") then Object.GroupTransparency=0 end
                        if Object:IsA("TextButton") then Object.BackgroundTransparency=.08
                        elseif Object:IsA("Frame") then Object.BackgroundTransparency=0 end
                    end
                end
                return
            end
            if not PreserveCurrent then
                for _,Object in ipairs(MiniRevealObjects) do
                    if Object and Object.Parent then SetMiniChildTransparency(Object,1) end
                end
            end
            local Groups={
                {{NotchMiniTitle,NotchMiniTask,NotchMiniState},.035},
                {{NotchMiniTargetLabel,NotchMiniTarget,NotchMiniTimerLabel,NotchMiniTimer,NotchMiniHPLabel,NotchMiniHP},.085},
                {{NotchMiniProgressLabel,NotchMiniProgressTrack,NotchMiniProgressFill,NotchMiniProgressText},.135},
                {{NotchMiniPause,NotchMiniStop},.180}
            }
            for _,Entry in ipairs(Groups) do
                local Objects,Delay=Entry[1],Entry[2]
                task.delay(S.MotionDelay(Delay),function()
                    if not Gui.Parent or Token~=NotchMiniToken or not NotchMiniExpanded then return end
                    for _,Object in ipairs(Objects) do
                        if Object and Object.Parent then
                            if Object:IsA("TextLabel") or Object:IsA("TextButton") then
                                Tw(Object,.23,{TextTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            elseif Object:IsA("ImageLabel") then
                                Tw(Object,.23,{ImageTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            elseif Object:IsA("CanvasGroup") then
                                Tw(Object,.23,{GroupTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            end
                            if Object:IsA("TextButton") then
                                Tw(Object,.24,{BackgroundTransparency=.08},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            elseif Object:IsA("Frame") then
                                Tw(Object,.24,{BackgroundTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            end
                        end
                    end
                end)
            end
        end
        local function AnimateActivityIcon(NewKey,_NewText,ShowIcon,Accent)
            NewKey=tostring(NewKey or "idle")
            Accent=Accent or Theme.GoldSoft
            local SameKey=(NewKey==CurrentNotchIconKey)

            local function SetToAvatarImmediate()
                HideTaskIconParts()
                NotchUI.ActivityIcon.Visible=false
                NotchUI.ActivityIcon.GroupTransparency=1
                NotchUI.ActivityIcon.Rotation=0
                ActivityIconScale.Scale=1
                NotchUI.Avatar.Visible=true
                NotchUI.Avatar.ImageTransparency=0
                AvatarScale.Scale=1
                NotchUI.BrandMark.Visible=false
            end
            local function SetToIconImmediate()
                RenderTaskIcon(NewKey,Accent)
                NotchUI.ActivityIcon.Visible=true
                NotchUI.ActivityIcon.GroupTransparency=0
                NotchUI.ActivityIcon.Rotation=0
                ActivityIconScale.Scale=1
                NotchUI.Avatar.Visible=false
                NotchUI.Avatar.ImageTransparency=1
                AvatarScale.Scale=1
                NotchUI.BrandMark.Visible=false
            end

            -- Same-state refreshes are extremely common. Do NOT reset Scale/Transparency every refresh;
            -- that was the main source of tiny icon stutters while the notch was animating.
            if SameKey then
                if ShowIcon then
                    if not NotchUI.ActivityIcon.Visible then
                        SetToIconImmediate()
                    else
                        RenderTaskIcon(NewKey,Accent)
                        NotchUI.Avatar.Visible=false
                        NotchUI.Avatar.ImageTransparency=1
                    end
                else
                    if NotchUI.ActivityIcon.Visible or not NotchUI.Avatar.Visible then SetToAvatarImmediate() end
                end
                return
            end

            ActivityIconSwapToken+=1
            local SwapToken=ActivityIconSwapToken
            CurrentNotchIconKey=NewKey
            if Runtime.ReducedMotion==true then
                if ShowIcon then SetToIconImmediate() else SetToAvatarImmediate() end
                return
            end

            -- Phase 1: old identity eases inward instead of vanishing.
            if NotchUI.ActivityIcon.Visible then
                Tw(NotchUI.ActivityIcon,.145,{GroupTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                Tw(ActivityIconScale,.145,{Scale=.94},Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
                Tw(NotchLogoGlow,.145,{BackgroundTransparency=.91},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
            elseif NotchUI.Avatar.Visible then
                Tw(NotchUI.Avatar,.145,{ImageTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                Tw(AvatarScale,.145,{Scale=.94},Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
                Tw(NotchLogoGlow,.145,{BackgroundTransparency=.91},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
            end

            task.delay(S.MotionDelay(.105),function()
                if not Gui.Parent or SwapToken~=ActivityIconSwapToken or NewKey~=CurrentNotchIconKey then return end
                NotchUI.BrandMark.Visible=false
                if ShowIcon then
                    RenderTaskIcon(NewKey,Accent)
                    NotchUI.Avatar.Visible=false
                    NotchUI.Avatar.ImageTransparency=1
                    AvatarScale.Scale=1
                    NotchUI.ActivityIcon.Visible=true
                    NotchUI.ActivityIcon.GroupTransparency=1
                    NotchUI.ActivityIcon.Rotation=0
                    ActivityIconScale.Scale=.94
                    -- Phase 2: new icon softly blooms in, then settles. No spin and no hard snap.
                    Tw(NotchUI.ActivityIcon,.235,{GroupTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    Tw(ActivityIconScale,.235,{Scale=1.008},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                    Tw(NotchLogoGlow,.235,{BackgroundTransparency=.76},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    task.delay(S.MotionDelay(.185),function()
                        if Gui.Parent and SwapToken==ActivityIconSwapToken and NewKey==CurrentNotchIconKey and NotchUI.ActivityIcon.Visible then
                            Tw(ActivityIconScale,.19,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            Tw(NotchLogoGlow,.22,{BackgroundTransparency=.84},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        end
                    end)
                else
                    HideTaskIconParts()
                    NotchUI.ActivityIcon.Visible=false
                    NotchUI.ActivityIcon.GroupTransparency=1
                    ActivityIconScale.Scale=1
                    NotchUI.Avatar.Visible=true
                    NotchUI.Avatar.ImageTransparency=1
                    AvatarScale.Scale=.94
                    Tw(NotchUI.Avatar,.235,{ImageTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    Tw(AvatarScale,.235,{Scale=1.008},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                    Tw(NotchLogoGlow,.235,{BackgroundTransparency=.76},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    task.delay(S.MotionDelay(.185),function()
                        if Gui.Parent and SwapToken==ActivityIconSwapToken and NewKey==CurrentNotchIconKey and NotchUI.Avatar.Visible then
                            Tw(AvatarScale,.19,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            Tw(NotchLogoGlow,.22,{BackgroundTransparency=.84},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        end
                    end)
                end
            end)
        end
        local function AnimateMiniActivityIcon(NewKey,Accent)
            -- v5.18.68: expanded mode reuses the minimized task icon. The hidden legacy mini icon
            -- is kept only for compatibility with old references and never renders a duplicate.
            CurrentMiniNotchIconKey=tostring(NewKey or "idle")
            NotchMiniIconBack.Visible=false
            NotchMiniAvatar.Visible=false
            NotchMiniIcon.Visible=false
            NotchMiniIcon.GroupTransparency=1
            NotchMiniIconScale.Scale=1
        end

        local function AnimateMiniDetailLabel(NewLabel)
            NewLabel=tostring(NewLabel or "DETAIL")
            if LastMiniDetailLabel==NewLabel then return end
            LastMiniDetailLabel=NewLabel
            if Runtime.ReducedMotion==true or not NotchMiniExpanded or not NotchMini.Visible then
                NotchMiniTargetLabel.Text=NewLabel
                NotchMiniTargetLabel.TextTransparency=0
                return
            end
            Tw(NotchMiniTargetLabel,.07,{TextTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
            task.delay(S.MotionDelay(.070),function()
                if not Gui.Parent or not NotchMiniExpanded or LastMiniDetailLabel~=NewLabel then return end
                NotchMiniTargetLabel.Text=NewLabel
                Tw(NotchMiniTargetLabel,.13,{TextTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
            end)
        end

        local function AnimateMiniProgressMode(HasMeasuredProgress)
            local Mode=HasMeasuredProgress and "progress" or "status"
            if LastMiniProgressMode==Mode then return end
            LastMiniProgressMode=Mode
            if Runtime.ReducedMotion==true or not NotchMiniExpanded or not NotchMini.Visible then
                NotchMiniProgressTrack.Visible=HasMeasuredProgress
                NotchMiniProgressFill.Visible=HasMeasuredProgress
                NotchMiniProgressTrack.BackgroundTransparency=HasMeasuredProgress and 0 or 1
                NotchMiniProgressFill.BackgroundTransparency=HasMeasuredProgress and 0 or 1
                NotchMiniProgressLabel.Position=HasMeasuredProgress and NotchMiniProgressLabelBase or NotchMiniStatusLabelPos
                NotchMiniProgressText.Position=HasMeasuredProgress and NotchMiniProgressTextBase or NotchMiniStatusTextPos
                return
            end
            Tw(NotchMiniProgressLabel,.07,{TextTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
            Tw(NotchMiniProgressText,.07,{TextTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
            if NotchMiniProgressTrack.Visible then
                Tw(NotchMiniProgressTrack,.07,{BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                Tw(NotchMiniProgressFill,.07,{BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
            end
            task.delay(S.MotionDelay(.080),function()
                if not Gui.Parent or not NotchMiniExpanded or LastMiniProgressMode~=Mode then return end
                NotchMiniProgressTrack.Visible=HasMeasuredProgress
                NotchMiniProgressFill.Visible=HasMeasuredProgress
                NotchMiniProgressLabel.Position=HasMeasuredProgress and NotchMiniProgressLabelBase or NotchMiniStatusLabelPos
                NotchMiniProgressText.Position=HasMeasuredProgress and NotchMiniProgressTextBase or NotchMiniStatusTextPos
                if HasMeasuredProgress then
                    NotchMiniProgressTrack.BackgroundTransparency=1
                    NotchMiniProgressFill.BackgroundTransparency=1
                    Tw(NotchMiniProgressTrack,.15,{BackgroundTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    Tw(NotchMiniProgressFill,.15,{BackgroundTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                end
                Tw(NotchMiniProgressLabel,.14,{TextTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                Tw(NotchMiniProgressText,.14,{TextTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
            end)
        end

        local function RefreshMiniPanel(Info)
            if not NotchMiniExpanded then return end
            EnforceExpandedSingleLayer()
            Info=Info or {}
            local H=Humanoid()
            local Health=(H and tonumber(H.Health)) or 0
            local MaxHealth=(H and tonumber(H.MaxHealth)) or 0
            local Ratio=MaxHealth>0 and math.clamp(Health/MaxHealth,0,1) or 0
            local Target,Timer=ParseMiniDetail(Info)
            local DetailLabel=ResolveMiniDetailLabel(Info,Target)
            local Progress=math.clamp(tonumber(Info.Progress) or 0,0,1)
            local IconKey=tostring(Info.IconKey or "idle")
            local IsBossFight=IconKey=="boss"
            local BossHealth=tonumber(Info.BossHealth)
            local BossMaxHealth=tonumber(Info.BossMaxHealth)
            if IsBossFight and (not BossHealth or not BossMaxHealth or BossMaxHealth<=0) then
                local BossTarget=Runtime.BloxCurrentCombatTarget
                local BossHum=BossTarget and BossTarget.Parent and BossTarget:FindFirstChildOfClass("Humanoid") or nil
                if BossHum then
                    BossHealth=tonumber(BossHum.Health)
                    BossMaxHealth=tonumber(BossHum.MaxHealth)
                    if BossTarget.Name and tostring(BossTarget.Name)~="" then Target=tostring(BossTarget.Name) end
                end
            end
            local BossRatio=(BossHealth and BossMaxHealth and BossMaxHealth>0) and math.clamp(BossHealth/BossMaxHealth,0,1) or nil
            if IsBossFight and BossRatio then Progress=BossRatio end
            local NewTask=tostring(Info.Title or "BananiHub")
            local NewState=tostring(Info.State or "Ready")
            LastMiniTask=AnimateMiniText(NotchMiniTask,NotchMiniTaskGhost,NewTask,NotchMiniTaskBase,LastMiniTask or NotchMiniTask.Text)
            LastMiniState=AnimateMiniText(NotchMiniState,NotchMiniStateGhost,NewState,NotchMiniStateBase,LastMiniState or NotchMiniState.Text)
            LastMiniTarget=AnimateMiniText(NotchMiniTarget,NotchMiniTargetGhost,Target,NotchMiniTargetBase,LastMiniTarget or NotchMiniTarget.Text)
            AnimateMiniDetailLabel(DetailLabel)
            local PaletteKey,Palette=ResolveNotchTheme(Info,NewState~="Ready" and NewState~="Idle")
            AnimateMiniActivityIcon(IconKey,(Palette and Palette.Accent) or Theme.GoldSoft)
            NotchMiniTimer.Text=Timer
            NotchMiniHPLabel.Text="HP"
            NotchMiniHP.Text=MaxHealth>0 and (tostring(math.floor(Health+0.5)).."/"..tostring(math.floor(MaxHealth+0.5))) or "—"
            local ExplicitProgress=tostring(Info.ProgressMode or "")=="progress"
            local HasMeasuredProgress=IsBossFight and BossRatio~=nil
                or ExplicitProgress
                or IconKey=="raid"
                or (IconKey=="combat" and NewTask:lower():find("auto farm",1,true)~=nil and Progress>0)
                or (tostring(Info.Kind or "")=="BuildABoat" and Progress>0)
            if IsBossFight and BossRatio then
                NotchMiniProgressLabel.Text="BOSS HP"
                NotchMiniProgressText.Text=tostring(math.floor(BossHealth+0.5)).."/"..tostring(math.floor(BossMaxHealth+0.5)).."  •  "..tostring(math.floor(BossRatio*100+0.5)).."%"
                NotchMiniProgressText.TextColor3=Theme.Muted
            elseif HasMeasuredProgress then
                NotchMiniProgressLabel.Text=tostring(Info.ProgressLabel or "PROGRESS")
                NotchMiniProgressText.Text=tostring(math.floor(Progress*100+0.5)).."%"
                NotchMiniProgressText.TextColor3=Theme.Muted
            else
                -- No fake progress: no bar at all. Just say whether the feature is actually enabled.
                local StateLower=string.lower(NewState)
                local ActivationText=tostring(Info.StatusText or "")
                if ActivationText=="" then ActivationText="ACTIVATED" end
                if Runtime.DynamicIslandPausedFlag or StateLower=="paused" then
                    ActivationText="PAUSED"
                elseif StateLower=="idle" or StateLower=="ready" or StateLower=="off" or StateLower=="stopped" or StateLower=="disabled"
                    or StateLower=="inactive" or StateLower=="not active" then
                    ActivationText="NOT ACTIVE"
                end
                NotchMiniProgressLabel.Text="STATUS"
                NotchMiniProgressText.Text=ActivationText
                NotchMiniProgressText.TextColor3=Theme.Text
            end
            AnimateMiniProgressMode(HasMeasuredProgress==true)
            local Goal=UDim2.new(HasMeasuredProgress and Progress or 0,0,1,0)
            if LastMiniProgress==nil or math.abs((HasMeasuredProgress and Progress or 0)-LastMiniProgress)>=.005 then
                LastMiniProgress=HasMeasuredProgress and Progress or 0
                if Runtime.ReducedMotion==true then NotchMiniProgressFill.Size=Goal
                else Tw(NotchMiniProgressFill,.24,{Size=Goal},Enum.EasingStyle.Quint,Enum.EasingDirection.Out) end
            end
            local CanPause=(Runtime.DynamicIslandPausedFlag~=nil)
            if not CanPause then
                local Kind=tostring(Info.Kind or Runtime.DetectedGameProfileKind or "")
                local Active=tostring(Runtime.ActiveAutomationName or "")
                local BloxCanPause=false
                if Kind=="BloxFruits" and Runtime.BloxControllerAPI and Runtime.BloxControllerAPI.ActiveFlag then
                    local OK,V=pcall(Runtime.BloxControllerAPI.ActiveFlag)
                    BloxCanPause=OK and V~=nil
                end
                CanPause=BloxCanPause
                    or Active=="MM2Coins" or Active=="MM2Survive" or Active=="AdoptSmartFarm" or Active=="AdoptWork"
                    or Active=="AdoptPetPen" or Active=="AdoptLures" or Active=="AdoptActivity" or Active=="AdoptNearbyCare"
                    or Active=="BuildABoatGoldFarm" or Active=="BloxburgJob"
            end
            NotchMiniPause.Text=Runtime.DynamicIslandPausedFlag and "RESUME" or "PAUSE"
            NotchMiniPause:SetAttribute("TaskActionEnabled",CanPause==true)
            NotchMiniStop:SetAttribute("TaskActionEnabled",CanPause==true)
            NotchMiniPause.TextTransparency=CanPause and 0 or .48
            NotchMiniStop.TextTransparency=CanPause and 0 or .48
        end

        local NotchLoopToFlag={
            MM2Coins="GameProfile_MM2_Coins",MM2Survive="GameProfile_MM2_Survive",
            AdoptSmartFarm="GameProfile_Adopt_SmartFarm",AdoptWork="GameProfile_Adopt_Work",
            AdoptPetPen="GameProfile_Adopt_PetPen",AdoptLures="GameProfile_Adopt_Lures",
            AdoptActivity="GameProfile_Adopt_Activity",AdoptNearbyCare="GameProfile_Adopt_NearbyCare",
            BuildABoatGoldFarm="GameProfile_BuildABoat_AutoFarm",BloxburgJob="GameProfile_Bloxburg_Job"
        }
        local function ResolveCurrentNotchFlag(Info)
            if Runtime.DynamicIslandPausedFlag then return Runtime.DynamicIslandPausedFlag end
            local Kind=tostring(Info and Info.Kind or Runtime.DetectedGameProfileKind or "")
            if Kind=="BloxFruits" then
                local IconKey=tostring(Info and Info.IconKey or "")
                local Title=tostring(Info and Info.Title or "")
                if IconKey=="fish" then return "GameProfile_Blox_AutoFish" end
                if IconKey=="raid" then return "GameProfile_Blox_SmartRaid" end
                if Title:find("Material Farm",1,true) then return "GameProfile_Blox_MaterialFarm" end
                if Title:find("Boss Farm",1,true) then return "GameProfile_Blox_AutoBoss" end
                if Runtime.BloxControllerAPI and Runtime.BloxControllerAPI.ActiveFlag then
                    local OK,V=pcall(Runtime.BloxControllerAPI.ActiveFlag)
                    if OK and V then return tostring(V) end
                end
            end
            return NotchLoopToFlag[tostring(Runtime.ActiveAutomationName or "")]
        end
        local function PauseResumeNotchTask()
            if Runtime.DynamicIslandPausedFlag then
                local Flag=Runtime.DynamicIslandPausedFlag
                local OK=false
                if Runtime.SetFlagValue then
                    local CallOK,Result=pcall(Runtime.SetFlagValue,Flag,true)
                    OK=CallOK and Result==true
                end
                if not OK then
                    Notify("Dynamic Island","Resume failed because that control is no longer available.")
                    return
                end
                Runtime.DynamicIslandPausedFlag=nil
                Runtime.DynamicIslandPausedSnapshot=nil
                Runtime.DynamicIslandPausedLabel=nil
                Notify("Dynamic Island","Resumed the paused task.")
                return
            end
            local _,_,_,Info=S.GetDynamicIslandLiveText()
            local Flag=ResolveCurrentNotchFlag(Info)
            if not Flag then
                Notify("Dynamic Island","This item does not have a Pause/Resume control.")
                return
            end
            local Snapshot=Runtime.CopyDynamicIslandSnapshot(Info) or Info
            local Label=tostring(Info and Info.Title or Runtime.ActiveAutomationName or "Task")
            local OK=false
            if Runtime.SetFlagValue then
                local CallOK,Result=pcall(Runtime.SetFlagValue,Flag,false)
                OK=CallOK and Result==true
            end
            if not OK then
                Notify("Dynamic Island","Pause failed because that control is unavailable.")
                return
            end
            Runtime.DynamicIslandPausedFlag=Flag
            Runtime.DynamicIslandPausedSnapshot=Snapshot
            Runtime.DynamicIslandPausedLabel=Label
            Notify("Dynamic Island","Paused "..Label..".")
        end
        local function StopNotchTask()
            local _,_,_,Info=S.GetDynamicIslandLiveText()
            local Flag=ResolveCurrentNotchFlag(Info)
            if not Flag then
                Runtime.DynamicIslandPausedFlag=nil
                Runtime.DynamicIslandPausedSnapshot=nil
                Runtime.DynamicIslandPausedLabel=nil
                Notify("Dynamic Island","No stoppable active task was detected.")
                return
            end
            local OK=false
            if Runtime.SetFlagValue then
                local CallOK,Result=pcall(Runtime.SetFlagValue,Flag,false)
                OK=CallOK and Result==true
            end
            if not OK then
                Notify("Dynamic Island","Stop failed because that control is unavailable.")
                return
            end
            Runtime.DynamicIslandPausedFlag=nil
            Runtime.DynamicIslandPausedSnapshot=nil
            Runtime.DynamicIslandPausedLabel=nil
            Notify("Dynamic Island","Stopped the current task.")
        end
-- ==================================================================
-- [BH:NOTCH] DYNAMIC ISLAND / NOTCH
-- Compact status, hover/hold one-piece expansion, normal click/tap full UI, isolated expanded controls.
-- ==================================================================
        local SetNotchHoverPeek=nil
        local function SetMiniExpanded(Value,Instant,KeepCompactHidden)
            Value=Value==true
            local WasMiniVisible=NotchMini.Visible
            -- Stop old geometry writers before an instant reset or reversal.
            for _,Object in ipairs({Notch,NotchScale,NotchStroke,NotchMini,NotchMiniScale}) do
                S.CancelObjectTweens(Object)
            end
            for _,Object in ipairs(MiniRevealObjects) do S.CancelObjectTweens(Object) end
            ActivityIconSwapToken+=1 -- cancel stale delayed icon/avatar callbacks before shell geometry changes
            NotchMiniToken+=1
            local Token=NotchMiniToken
            NotchMiniExpanded=Value
            InvalidateNotchTextTransitions()

            -- One-piece geometry. The SAME black shell grows downward. Compact text/status/progress
            -- disappears, the single task icon morphs into the header, then expanded information reveals.
            local CompactNotchSize=UDim2.fromOffset(336,48)
            local ExpandedNotchSize=UDim2.fromOffset(402,202)
            local FinalMiniPosition=UDim2.new(.5,0,0,20)
            local StartMiniPosition=UDim2.new(.5,0,0,26)
            local FinalMiniSize=UDim2.fromOffset(402,182)
            local MotionMode=tostring(Runtime.AnimationMode or "Smooth")
            local SmoothOneSecondMorph=(Runtime.ReducedMotion~=true and MotionMode=="Smooth")
            -- v5.18.100 staged choreography: compact content exits first; the one-piece shell
            -- gets a clean resize window; expanded content arrives late so the two layouts never
            -- visually fight each other. Closing uses the same idea in reverse.
            local OpenMorphDelay=SmoothOneSecondMorph and .18 or .15
            local OpenMorphDuration=SmoothOneSecondMorph and .82 or PremiumMotionDuration(.50)
            local OpenContentDelay=WasMiniVisible and (SmoothOneSecondMorph and .18 or .12) or (SmoothOneSecondMorph and .62 or .38)
            local OpenContentDuration=SmoothOneSecondMorph and .34 or .26
            local OpenSettleDelay=OpenMorphDelay+OpenMorphDuration
            local OpenSettleDuration=SmoothOneSecondMorph and .18 or .16
            local CloseContentDuration=SmoothOneSecondMorph and .24 or .18
            local CloseMorphDelay=SmoothOneSecondMorph and .04 or .03
            local CloseMorphDuration=SmoothOneSecondMorph and .80 or PremiumMotionDuration(.50)
            local CloseCompactRestoreDelay=CloseMorphDelay+(CloseMorphDuration*.64)
            local CloseCleanupDelay=CloseMorphDelay+CloseMorphDuration

            -- v5.18.55: no bridge, no second visible shell, and no duplicated compact layer while expanded.
            NotchBridge.Visible=false
            NotchBridge.BackgroundTransparency=1
            NotchBridgeAccent.BackgroundTransparency=1
            NotchBridgeAccent.Size=UDim2.fromOffset(0,1)
            if not WasMiniVisible then NotchMini.Position=FinalMiniPosition end
            NotchMini.Size=FinalMiniSize
            NotchMini.BackgroundTransparency=1
            NotchMiniStroke.Transparency=1

            if Value then
                if SetNotchHoverPeek then SetNotchHoverPeek(false,true,true) end
                CurrentMiniNotchIconKey="idle"
                LastMiniProgressMode=nil
                LastMiniDetailLabel=nil
                local _,_,_,Info=S.GetDynamicIslandLiveText()
                RefreshMiniPanel(Info)
                NotchMini.Visible=true
                NotchMiniIconBack.Visible=false
                NotchMiniAvatar.Visible=false
                NotchMiniIcon.Visible=false
                NotchMiniIcon.GroupTransparency=1
                SetCompactLayerSuppressed(true,Instant or Runtime.ReducedMotion==true)
                -- Give the compact labels/status/progress their own short exit beat before the
                -- expanded information is allowed to appear. The shared task identity remains single.
                EnforceExpandedSingleLayer()

                if Instant or Runtime.ReducedMotion==true then
                    Notch.Size=ExpandedNotchSize
                    NotchScale.Scale=1
                    NotchStroke.Transparency=.64
                    NotchMini.Position=FinalMiniPosition
                    NotchMini.GroupTransparency=0
                    NotchMiniScale.Scale=1
                    NotchMiniAccent.Size=UDim2.new(0,0,0,1)
                    for _,Object in ipairs(MiniRevealObjects) do
                        if Object and Object.Parent then
                            if Object:IsA("TextLabel") or Object:IsA("TextButton") then Object.TextTransparency=0
                            elseif Object:IsA("ImageLabel") then Object.ImageTransparency=0
                            elseif Object:IsA("CanvasGroup") then Object.GroupTransparency=0 end
                            if Object:IsA("TextButton") then Object.BackgroundTransparency=.08
                            elseif Object:IsA("Frame") then Object.BackgroundTransparency=0 end
                        end
                    end
                    RefreshMiniPanel(Info)
                else
                    -- Reverse from current opacity/position instead of resetting visible content.
                    if not WasMiniVisible then
                        NotchMini.Position=StartMiniPosition
                        NotchMini.GroupTransparency=1
                        NotchMiniScale.Scale=.985
                    end
                    NotchMiniAccent.Size=UDim2.new(0,0,0,1)
                    if not WasMiniVisible then
                        for _,Object in ipairs(MiniRevealObjects) do
                            if Object and Object.Parent then SetMiniChildTransparency(Object,1) end
                        end
                    end

                    -- Staged open: compact content is already fading; the shell starts just after
                    -- that exit begins, then the expanded layer arrives near the end of the resize.
                    Tw(NotchScale,OpenMorphDuration,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out,OpenMorphDuration)
                    Tw(NotchStroke,.12,{Transparency=.60},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                    task.delay(S.MotionDelay(OpenMorphDelay),function()
                        if not Gui.Parent or Token~=NotchMiniToken or not NotchMiniExpanded then return end
                        Tw(Notch,OpenMorphDuration,{Size=ExpandedNotchSize},Enum.EasingStyle.Quint,Enum.EasingDirection.Out,OpenMorphDuration)
                        Tw(NotchStroke,SmoothOneSecondMorph and .52 or .36,{Transparency=.57},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    end)
                    task.delay(S.MotionDelay(OpenContentDelay),function()
                        if not Gui.Parent or Token~=NotchMiniToken or not NotchMiniExpanded then return end
                        Tw(NotchMini,OpenContentDuration,{GroupTransparency=0,Position=FinalMiniPosition},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                        Tw(NotchMiniScale,OpenContentDuration,{Scale=1.0007},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        AnimateMiniReveal(Token,WasMiniVisible)
                    end)
                    task.delay(OpenSettleDelay,function()
                        if not Gui.Parent or Token~=NotchMiniToken or not NotchMiniExpanded then return end
                        Tw(NotchStroke,OpenSettleDuration,{Transparency=.64},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        Tw(NotchMiniScale,OpenSettleDuration,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    end)
                end
            else
                if not NotchMini.Visible then
                    NotchMiniExpanded=false
                    Notch.Size=CompactNotchSize
                    NotchScale.Scale=1
                    Notch.Position=UDim2.new(.5,0,0,NotchTopY)
                    NotchUI.Logo.Position=CompactLogoPosition
                    NotchStroke.Transparency=.78
                    if not KeepCompactHidden then SetCompactLayerSuppressed(false,true) end
                    return
                end

                if Instant or Runtime.ReducedMotion==true then
                    NotchMini.Visible=false
                    NotchMini.GroupTransparency=1
                    NotchMiniScale.Scale=1
                    NotchMini.Position=FinalMiniPosition
                    NotchMiniAccent.Size=UDim2.new(0,0,0,1)
                    Notch.Size=CompactNotchSize
                    NotchScale.Scale=1
                    NotchStroke.Transparency=.78
                    LastMiniProgressMode=nil
                    LastMiniDetailLabel=nil
                    CurrentMiniNotchIconKey="idle"
                    NotchUI.Logo.Position=CompactLogoPosition
                    if not KeepCompactHidden then
                        SetCompactLayerSuppressed(false,true)
                        local CTop,_,CActive,CInfo=S.GetDynamicIslandLiveText()
                        local CPalette=ApplyNotchTheme(CInfo,CActive)
                        AnimateActivityIcon(tostring(CInfo and CInfo.IconKey or "idle"),CTop,CActive,CPalette.Accent)
                    end
                else
                    -- v5.18.100 staged close: expanded information leaves first, the SAME shell
                    -- folds back cleanly, then compact content returns only once the shell is well
                    -- into its close. This avoids the old stacked/overlap look in both directions.
                    for _,Object in ipairs(MiniRevealObjects) do
                        if Object and Object.Parent then
                            if Object:IsA("TextLabel") or Object:IsA("TextButton") then
                                Tw(Object,CloseContentDuration,{TextTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                            end
                            if Object:IsA("TextButton") then
                                Tw(Object,CloseContentDuration,{BackgroundTransparency=.68},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                            end
                        end
                    end
                    Tw(NotchMiniAccent,CloseContentDuration,{Size=UDim2.new(0,0,0,1),BackgroundTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                    Tw(NotchMini,CloseContentDuration,{GroupTransparency=1,Position=StartMiniPosition},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                    Tw(NotchMiniScale,CloseContentDuration,{Scale=.993},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                    Tw(NotchScale,.14,{Scale=.9985},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                    task.delay(CloseMorphDelay,function()
                        if not Gui.Parent or Token~=NotchMiniToken or NotchMiniExpanded then return end
                        Tw(Notch,CloseMorphDuration,{Size=CompactNotchSize},Enum.EasingStyle.Quint,Enum.EasingDirection.Out,CloseMorphDuration)
                        Tw(NotchScale,CloseMorphDuration,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out,CloseMorphDuration)
                        Tw(NotchStroke,SmoothOneSecondMorph and .56 or .38,{Transparency=.76},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    end)
                    task.delay(CloseCompactRestoreDelay,function()
                        if Gui.Parent and Token==NotchMiniToken and not NotchMiniExpanded and not KeepCompactHidden then
                            SetCompactLayerSuppressed(false,false)
                        end
                    end)
                    task.delay(CloseCleanupDelay+.03,function()
                        if Gui.Parent and Token==NotchMiniToken and not NotchMiniExpanded then
                            NotchMini.Visible=false
                            NotchMini.GroupTransparency=1
                            NotchMiniScale.Scale=1
                            NotchMini.Position=FinalMiniPosition
                            NotchMini.Size=FinalMiniSize
                            NotchScale.Scale=1
                            NotchStroke.Transparency=.78
                            LastMiniProgressMode=nil
                            LastMiniDetailLabel=nil
                            CurrentMiniNotchIconKey="idle"
                            NotchUI.Logo.Position=CompactLogoPosition
                            if not KeepCompactHidden then
                                local CTop,_,CActive,CInfo=S.GetDynamicIslandLiveText()
                                local CPalette=ApplyNotchTheme(CInfo,CActive)
                                AnimateActivityIcon(tostring(CInfo and CInfo.IconKey or "idle"),CTop,CActive,CPalette.Accent)
                            end
                        end
                    end)
                end
            end
        end

        S.SettleNotchMotion=function()
            if not LevelUpDropActive and Notch.Visible and not S.Transitioning then
                SetMiniExpanded(NotchMiniExpanded,true)
            end
        end
        local NotchHoverPeekVisible=false
        local NotchHoverPeekToken=0
        local NotchHoverPeekOpenDelay=.16
        local NotchHoverPeekCloseDelay=.10
        local function PeekPriorityColor(Name)
            Name=tostring(Name or "NORMAL")
            if Name=="CRITICAL" then return Color3.fromRGB(255,88,96) end
            if Name=="HIGH" then return Color3.fromRGB(255,188,73) end
            if Name=="LOW" then return Color3.fromRGB(112,159,213) end
            return Color3.fromRGB(171,175,185)
        end
        local function RefreshNotchHoverPeek()
            local Top,Bottom,Active,Info=S.GetDynamicIslandLiveText()
            local Target="—"
            if type(ParseMiniDetail)=="function" then
                local OK,T=pcall(function() return ParseMiniDetail(Info) end)
                if OK and T then Target=tostring(T) end
            end
            local Label="DETAIL"
            if type(ResolveMiniDetailLabel)=="function" then
                local OK,L=pcall(ResolveMiniDetailLabel,Info,Target)
                if OK and L then Label=tostring(L) end
            end
            local Context
            if Active and Target~="—" and Target~="" then Context=Label.."  •  "..Target
            elseif Active then Context=tostring(Bottom~="" and Bottom or Top)
            else Context="Ready • hover for live activity details" end
            NotchPeekContext.Text=Context

            local ActiveItem=Runtime.DynamicIslandQueueActive or Runtime.DynamicIslandTakeover
            local Waiting=type(Runtime.DynamicIslandNotificationQueue)=="table" and #Runtime.DynamicIslandNotificationQueue or 0
            local Importance=ActiveItem and tostring(ActiveItem.Importance or "NORMAL") or nil
            if not Importance and Waiting>0 then
                local Best=nil
                for _,Item in ipairs(Runtime.DynamicIslandNotificationQueue) do
                    if not Best or (tonumber(Item.ImportanceValue) or 2)>(tonumber(Best.ImportanceValue) or 2) then Best=Item end
                end
                Importance=Best and tostring(Best.Importance or "NORMAL") or "NORMAL"
            end
            if ActiveItem then
                NotchPeekQueue.Text=Importance.." • ACTIVE"..(Waiting>0 and (" +"..Waiting) or "")
            elseif Waiting>0 then
                NotchPeekQueue.Text=Importance.." • "..Waiting.." WAITING"
            else
                NotchPeekQueue.Text="QUEUE CLEAR"
                Importance="NORMAL"
            end
            local C=PeekPriorityColor(Importance)
            NotchPeekQueue.TextColor3=C
            NotchPeekBadgeStroke.Color=C:Lerp(Color3.fromRGB(255,255,255),.18)
            NotchPeekBadge.BackgroundColor3=C:Lerp(Color3.fromRGB(8,9,12),.82)
        end
        SetNotchHoverPeek=function(Value,Instant,KeepShape)
            Value=Value==true
            NotchHoverPeekToken+=1
            local Token=NotchHoverPeekToken
            if Value then
                if S.Visible or S.Transitioning or LevelUpDropActive or NotchMiniExpanded or not Notch.Visible then return false end
                RefreshNotchHoverPeek()
                NotchHoverPeekVisible=true
                NotchPeek.Visible=true
                if Instant or Runtime.ReducedMotion==true then
                    Notch.Size=UDim2.fromOffset(366,82)
                    NotchScale.Scale=1
                    NotchStroke.Transparency=.64
                    NotchPeek.Position=UDim2.new(.5,0,0,48)
                    NotchPeek.GroupTransparency=0
                    return true
                end
                NotchPeek.Position=UDim2.new(.5,0,0,53)
                NotchPeek.GroupTransparency=1
                -- Shape gets a head start, just like a native shelf; content follows after it has room.
                Tw(Notch,.24,{Size=UDim2.fromOffset(366,82)},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                Tw(NotchScale,.24,{Scale=1.002},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                Tw(NotchStroke,.22,{Transparency=.64},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                task.delay(S.MotionDelay(.075),function()
                    if not Gui.Parent or Token~=NotchHoverPeekToken or not NotchHoverPeekVisible or NotchMiniExpanded then return end
                    Tw(NotchPeek,.19,{GroupTransparency=0,Position=UDim2.new(.5,0,0,48)},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                end)
                return true
            end

            NotchHoverPeekVisible=false
            if not NotchPeek.Visible then return true end
            if Instant or Runtime.ReducedMotion==true then
                NotchPeek.Visible=false
                NotchPeek.GroupTransparency=1
                NotchPeek.Position=UDim2.new(.5,0,0,48)
                if not KeepShape and not NotchMiniExpanded and Notch.Visible then
                    Notch.Size=UDim2.fromOffset(336,48)
                    NotchScale.Scale=1
                    NotchStroke.Transparency=.78
                end
                return true
            end
            -- Departure is quicker: content disappears first so the shell never crushes readable text.
            Tw(NotchPeek,.095,{GroupTransparency=1,Position=UDim2.new(.5,0,0,51)},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
            task.delay(S.MotionDelay(.080),function()
                if not Gui.Parent or Token~=NotchHoverPeekToken or NotchMiniExpanded then return end
                Tw(Notch,.18,{Size=UDim2.fromOffset(336,48)},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                Tw(NotchScale,.18,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                Tw(NotchStroke,.18,{Transparency=.78},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
            end)
            task.delay(S.MotionDelay(.20),function()
                if Gui.Parent and Token==NotchHoverPeekToken and not NotchHoverPeekVisible then
                    NotchPeek.Visible=false
                    NotchPeek.GroupTransparency=1
                    NotchPeek.Position=UDim2.new(.5,0,0,48)
                end
            end)
            return true
        end

        local function RefreshNotch()
            local FPS=tonumber(LiveTelemetry.FPS) or 0
            local Ping=tostring(LiveTelemetry.Ping or "--")
            NotchUI.FPSValue.Text=tostring(FPS)
            NotchUI.PingValue.Text=tostring(Ping)
            NotchUI.FPSBox.Visible=false; NotchUI.PingBox.Visible=false; NotchUI.HPGroup.Visible=false
            local Top,Bottom,Active,Info=S.GetDynamicIslandLiveText()
            LastCompactTop=AnimateCompactText(NotchUI.Brand,NotchUI.BrandGhost,Top,NotchBrandBase,LastCompactTop or NotchUI.Brand.Text)
            LastCompactBottom=AnimateCompactText(NotchUI.State,NotchUI.StateGhost,Bottom,NotchStateBase,LastCompactBottom or NotchUI.State.Text)
            local Palette=ApplyNotchTheme(Info,Active)
            if NotchMiniExpanded then RefreshMiniPanel(Info) end

            -- Idle = Roblox profile picture. Active = a task-specific vector icon drawn by UI
            -- primitives, so every state is distinct without relying on font/emoji availability.
            local IconKey=Info and tostring(Info.IconKey or "idle") or "idle"
            -- Idle identity is always the local Roblox headshot, never a generic/task icon.
            if not Active then IconKey="idle"
            elseif IconKey=="idle" then IconKey="work" end
            local ShowIcon=Active and IconKey~="idle"
            AnimateActivityIcon(IconKey,"",ShowIcon,(Palette and Palette.Accent) or Theme.GoldSoft)

            local Progress=Info and math.clamp(tonumber(Info.Progress) or 0,0,1) or 0
            local ShowProgress=(not NotchMiniExpanded) and (not LevelUpDropActive) and Active and Progress>0 and Progress<1
            NotchUI.ProgressTrack.Visible=ShowProgress
            if ShowProgress then
                if LastCompactProgress==nil or math.abs(Progress-LastCompactProgress)>=.005 then
                    LastCompactProgress=Progress
                    Tw(NotchUI.ProgressFill,.23,{Size=UDim2.new(Progress,0,1,0)},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                end
            else
                LastCompactProgress=nil -- hidden fill resets; repaint when visible again
                NotchUI.ProgressFill.Size=UDim2.fromScale((not NotchMiniExpanded and Progress>=1) and 1 or 0,1)
            end

            local DotColor
            if Info and tostring(Info.IconKey or "")=="level" then
                DotColor=Theme.GoldSoft
            elseif Active then
                DotColor=(Palette and Palette.Accent) or Theme.Gold
            elseif FPS>0 and FPS<35 then
                DotColor=Color3.fromRGB(235,174,70)
            else
                DotColor=Theme.Green
            end
            if LastDotColor~=DotColor then
                LastDotColor=DotColor
                Tw(NotchUI.Dot,.18,{BackgroundColor3=DotColor},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                if Runtime.ReducedMotion~=true and Notch.Visible then
                    NotchDotScale.Scale=.88
                    Tw(NotchDotScale,.16,{Scale=1.07},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    task.delay(S.MotionDelay(.13),function()
                        if Gui.Parent then Tw(NotchDotScale,.11,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out) end
                    end)
                end
            end
            if LevelUpDropActive or NotchMiniExpanded then
                NotchUI.Dot.BackgroundTransparency=1
                NotchDotStroke.Transparency=1
            else
                NotchUI.Dot.BackgroundTransparency=0
                NotchDotStroke.Transparency=.15
            end
            BindNotchHealth()
            RefreshNotchHealth(false)
            Runtime.DynamicIslandLastActive=Active==true
            if NotchHoverPeekVisible then RefreshNotchHoverPeek() end
            if NotchMiniExpanded then
                SetCompactLayerSuppressed(true,true)
                EnforceExpandedSingleLayer()
            end
        end
        local DynamicIslandTakeoverPulse=0
        local NotchPressToken=0 -- shared press generation; declared before visibility/interaction closures
        Runtime.DynamicIslandUIOnTakeover=function(Info)
            if not Gui.Parent then return end
            local IsLevel=Info and tostring(Info.IconKey or "")=="level"
            RefreshNotch()
            if IsLevel and NotchHoverPeekVisible and SetNotchHoverPeek then SetNotchHoverPeek(false,true) end
            if S.Visible or not Notch.Visible or (NotchHovered and not IsLevel) then return end

            DynamicIslandTakeoverPulse+=1
            local Pulse=DynamicIslandTakeoverPulse

            if IsLevel then
                LevelUpDropActive=true
                local WasExpanded=NotchMiniExpanded==true
                local Restored=false

                -- Strict level-only takeover: hide every normal/expanded datum immediately, collapse
                -- to the compact notch, remove the shell gradient/stroke, and use pure black behind
                -- the native Blox Fruits LEVEL UP feed. Nothing else is allowed to remain visible.
                for _,Object in ipairs({Notch,NotchScale,NotchStroke,NotchContent,NotchMini}) do S.CancelObjectTweens(Object) end
                NotchContent.GroupTransparency=1
                NotchMini.GroupTransparency=1
                Notch.Size=UDim2.fromOffset(336,48)
                NotchScale.Scale=1
                Notch.BackgroundColor3=Color3.fromRGB(0,0,0)
                Notch.BackgroundTransparency=0
                NotchStroke.Transparency=1
                if NotchGradient then NotchGradient.Enabled=false end

                local function RestoreAfterNativeLevel()
                    if Restored then return end
                    Restored=true
                    if not Gui.Parent or Pulse~=DynamicIslandTakeoverPulse then return end
                    LevelUpDropActive=false
                    if NotchGradient then NotchGradient.Enabled=true end
                    Notch.BackgroundColor3=Color3.fromRGB(3,3,4)
                    Notch.BackgroundTransparency=0
                    Notch.Size=WasExpanded and UDim2.fromOffset(402,202) or UDim2.fromOffset(336,48)
                    NotchScale.Scale=1
                    NotchStroke.Transparency=WasExpanded and .64 or .78
                    RefreshNotch()
                    if Runtime.ReducedMotion==true then
                        NotchContent.GroupTransparency=0
                        if WasExpanded then NotchMini.GroupTransparency=0 end
                    else
                        Tw(NotchContent,.16,{GroupTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        if WasExpanded then Tw(NotchMini,.16,{GroupTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out) end
                    end
                    if WasExpanded and NotchMiniExpanded then SetCompactLayerSuppressed(true,true) end
                end
                local OK,Started=pcall(PlayBloxFruitsLevelUpVFX,Info,RestoreAfterNativeLevel)
                if not OK or Started~=true then
                    if type(Info)=="table" then
                        Info.UIFinished=true
                        Info.HoldUntilUIFinish=false
                        local Age=os.clock()-(tonumber(Info.Started) or os.clock())
                        Info.Duration=math.max(0,Age-.001)
                        if type(Info.ResumeSnapshot)=="table" and not Runtime.DynamicIslandResumeSnapshot then
                            Runtime.DynamicIslandResumeSnapshot=Runtime.CopyDynamicIslandSnapshot(Info.ResumeSnapshot)
                            Runtime.DynamicIslandResumeSnapshotUntil=os.clock()+.65
                        end
                    end
                    if type(Runtime.AdvanceDynamicIslandNotificationQueue)=="function" then Runtime.AdvanceDynamicIslandNotificationQueue() end
                    task.defer(RestoreAfterNativeLevel)
                end
                return
            end

            if Runtime.ReducedMotion==true then return end

            -- Generic takeover pulse for non-level activities stays restrained and connected.
            if NotchMiniExpanded then
                Tw(NotchScale,.055,{Scale=.995},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                task.delay(S.MotionDelay(.040),function()
                    if not Gui.Parent or Pulse~=DynamicIslandTakeoverPulse or S.Visible or not NotchMiniExpanded then return end
                    Tw(Notch,.18,{Size=UDim2.fromOffset(406,205)},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                    Tw(NotchScale,.18,{Scale=1.004},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                    Tw(NotchStroke,.18,{Transparency=.50},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                end)
                task.delay(S.MotionDelay(.22),function()
                    if Gui.Parent and Pulse==DynamicIslandTakeoverPulse and not S.Visible and NotchMiniExpanded then
                        Tw(Notch,.16,{Size=UDim2.fromOffset(402,202)},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        Tw(NotchScale,.16,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        Tw(NotchStroke,.18,{Transparency=.64},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    end
                end)
                return
            end
            Tw(NotchScale,.055,{Scale=.993},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
            task.delay(S.MotionDelay(.040),function()
                if not Gui.Parent or Pulse~=DynamicIslandTakeoverPulse or S.Visible or NotchHovered then return end
                Tw(Notch,.18,{Size=UDim2.fromOffset(350,52)},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                Tw(NotchScale,.18,{Scale=1.004},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            end)
            task.delay(S.MotionDelay(.22),function()
                if Gui.Parent and Pulse==DynamicIslandTakeoverPulse and not S.Visible and not NotchHovered then
                    Tw(Notch,.18,{Size=UDim2.fromOffset(336,48)},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    Tw(NotchScale,.18,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                end
            end)
        end
        local function SetNotchVisible(Visible,Instant,FromWindow)
            NotchToken+=1
            local Token=NotchToken
            Visible=Visible==true
            if not Visible then
                DynamicIslandTakeoverPulse+=1
                if LevelUpDropActive and type(Runtime.ReleaseDynamicIslandUIHold)=="function" then
                    Runtime.ReleaseDynamicIslandUIHold(true)
                end
                LevelUpDropActive=false
                LevelUpVFXToken+=1
                if ActiveLevelUpVFX and ActiveLevelUpVFX.Parent then
                    pcall(function() ActiveLevelUpVFX:Destroy() end)
                end
                ActiveLevelUpVFX=nil
                NotchPressToken+=1
            end
            if Visible then
                NotchHovered=false
                if NotchUI.HPGroup then NotchUI.HPGroup.GroupTransparency=1 end
                RefreshNotch()
                Notch.Visible=true
                NotchUI.Hint.TextTransparency=1
                if Instant then
                    Notch.Size=UDim2.fromOffset(336,48)
                    NotchScale.Scale=1
                    Notch.Position=UDim2.new(.5,0,0,NotchTopY)
                    Notch.BackgroundTransparency=0
                    NotchStroke.Transparency=.78
                    NotchContent.GroupTransparency=0
                elseif FromWindow then
                    -- Seamless handoff from the collapsing window: the shell already matches the
                    -- final island dimensions, so only opacity/content/scale need to settle.
                    Notch.Size=UDim2.fromOffset(336,48)
                    Notch.Position=UDim2.new(.5,0,0,NotchTopY)
                    NotchScale.Scale=.985
                    Notch.BackgroundTransparency=.12
                    NotchStroke.Transparency=.96
                    NotchContent.GroupTransparency=1
                    Tw(Notch,.18,{BackgroundTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    Tw(NotchStroke,.18,{Transparency=.78},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    Tw(NotchContent,.20,{GroupTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    Tw(NotchScale,.20,{Scale=1},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                else
                    -- Standalone island reveal: stretch from a tight black capsule, overshoot,
                    -- then settle while the contents fade in a beat behind the shell.
                    Notch.Size=UDim2.fromOffset(246,28)
                    NotchScale.Scale=.72
                    Notch.Position=UDim2.new(.5,0,0,NotchTopY-10)
                    Notch.BackgroundTransparency=.44
                    NotchStroke.Transparency=1
                    NotchContent.GroupTransparency=1
                    Tw(Notch,.21,{Size=UDim2.fromOffset(348,52),Position=UDim2.new(.5,0,0,NotchTopY),BackgroundTransparency=0},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    Tw(NotchScale,.21,{Scale=1.025},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    Tw(NotchStroke,.19,{Transparency=.72},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    task.delay(S.MotionDelay(.060),function()
                        if not Gui.Parent or Token~=NotchToken or not Notch.Visible then return end
                        Tw(NotchContent,.16,{GroupTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    end)
                    task.delay(S.MotionDelay(.19),function()
                        if not Gui.Parent or Token~=NotchToken or not Notch.Visible then return end
                        Tw(Notch,.14,{Size=UDim2.fromOffset(336,48),Position=UDim2.new(.5,0,0,NotchTopY)},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        Tw(NotchScale,.14,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        Tw(NotchStroke,.14,{Transparency=.78},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    end)
                end
            else
                NotchHovered=false
                if SetNotchHoverPeek then SetNotchHoverPeek(false,true) end
                SetMiniExpanded(false,Instant)
                NotchBridge.Visible=false
                if NotchUI.HPGroup then NotchUI.HPGroup.GroupTransparency=1 end
                if not Notch.Visible then return end
                if Instant then
                    Notch.Visible=false
                    NotchScale.Scale=.90
                    Notch.Position=UDim2.new(.5,0,0,NotchTopY)
                    Notch.Size=UDim2.fromOffset(336,48)
                    Notch.BackgroundTransparency=0
                    NotchStroke.Transparency=.78
                    NotchContent.GroupTransparency=0
                    NotchUI.Hint.TextTransparency=1
                else
                    -- Opening handoff: a tiny press/squish, then the island is pulled upward and
                    -- inward while its contents dissolve into the expanding main window.
                    Tw(NotchScale,.075,{Scale=.98},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                    Tw(NotchContent,.085,{GroupTransparency=.30},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                    task.delay(S.MotionDelay(.080),function()
                        if not Gui.Parent or Token~=NotchToken or not Notch.Visible then return end
                        Tw(Notch,.16,{Size=UDim2.fromOffset(256,27),Position=UDim2.new(.5,0,0,NotchTopY-8),BackgroundTransparency=.48},Enum.EasingStyle.Quart,Enum.EasingDirection.In)
                        Tw(NotchScale,.16,{Scale=.72},Enum.EasingStyle.Quart,Enum.EasingDirection.In)
                        Tw(NotchStroke,.14,{Transparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                        Tw(NotchContent,.13,{GroupTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                    end)
                    task.delay(S.MotionDelay(.225),function()
                        if Gui.Parent and Token==NotchToken then
                            Notch.Visible=false
                            Notch.Size=UDim2.fromOffset(336,48)
                            Notch.Position=UDim2.new(.5,0,0,NotchTopY)
                            Notch.BackgroundTransparency=0
                            NotchScale.Scale=.90
                            NotchStroke.Transparency=.78
                            NotchContent.GroupTransparency=0
                        end
                    end)
                end
            end
        end
        -- v5.18.90 interaction model:
        --   desktop hover -> expand details; leaving the full notch/controller bounds for exactly 1.0s -> collapse
        --   normal click/tap -> open full hub
        --   long press/touch hold -> expand details (touch fallback)
        --   expanded controls -> Pause/Resume + Stop only
        -- Child controls arm a short input guard so their click can never fall through to the shell.
        local NotchHoverIntentToken=0
        local NotchHoverExpandDelay=.060
        local NotchHoverCollapseDelay=1.00 -- exact wall-clock grace; animation speed / Reduced Motion must not shorten it
        local NotchControlInputGuardUntil=0
        local NotchLongPressToken=0
        local NotchLongPressHeld=false
        S.ConsumedNotchInputs=setmetatable({}, {__mode="k"})
        local NotchLongPressDelay=.34

        local function ArmNotchControlInputGuard(Duration)
            NotchControlInputGuardUntil=math.max(NotchControlInputGuardUntil,os.clock()+(tonumber(Duration) or .14))
        end
        local function NotchControlInputIsGuarded()
            return os.clock()<NotchControlInputGuardUntil
        end
        S.RunNotchIntent=function(Token,Hovering,Action)
            if not Gui.Parent or Token~=NotchHoverIntentToken or NotchHovered~=Hovering then return end
            if S.Visible or S.Transitioning or not Notch.Visible then return end
            if LevelUpDropActive or NotchControlInputIsGuarded() then
                task.delay(.10,function() S.RunNotchIntent(Token,Hovering,Action) end)
                return
            end
            Action()
        end

        local function SetNotchHoverIntent(Hovering)
            if S.Visible or S.Transitioning then return end
            NotchHovered=Hovering==true
            NotchHoverIntentToken+=1
            local Token=NotchHoverIntentToken
            NotchHoverPeekToken+=1 -- invalidate legacy peek callbacks; hover now uses full expansion only.
            if SetNotchHoverPeek and NotchHoverPeekVisible then SetNotchHoverPeek(false,true,true) end

            if Hovering then
                if Runtime.ReducedMotion~=true and not LevelUpDropActive then
                    Tw(NotchScale,.11,{Scale=1.0015},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                    Tw(NotchStroke,.12,{Transparency=NotchMiniExpanded and .60 or .69},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                end
                if not NotchMiniExpanded then
                    task.delay(S.MotionDelay(NotchHoverExpandDelay),function()
                        S.RunNotchIntent(Token,true,function()
                            if not NotchMiniExpanded then SetMiniExpanded(true,false) end
                        end)
                    end)
                end
            else
                task.delay(NotchHoverCollapseDelay,function()
                    S.RunNotchIntent(Token,false,function()
                        if NotchMiniExpanded then
                            SetMiniExpanded(false,false)
                        else
                            Tw(NotchScale,.15,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                            Tw(NotchStroke,.16,{Transparency=.78},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        end
                    end)
                end)
            end
        end

        trackPremiumConnection(Notch.MouseEnter:Connect(function() SetNotchHoverIntent(true) end))
        trackPremiumConnection(Notch.MouseLeave:Connect(function() SetNotchHoverIntent(false) end))
        -- Moving onto the expanded overlay/buttons can make the shell receive a MouseLeave on some
        -- executors. Treat the overlay as part of the same hover region so it never folds mid-click.
        trackPremiumConnection(NotchMini.MouseEnter:Connect(function() SetNotchHoverIntent(true) end))
        trackPremiumConnection(NotchMini.MouseLeave:Connect(function() SetNotchHoverIntent(false) end))

        -- MouseEnter/MouseLeave can occasionally be dropped during a fast size tween on some executors.
        -- While expanded, verify the real desktop cursor is still inside either visible notch surface. Leaving starts the 1s grace timer; re-entry cancels it.
        local function CursorInsideGuiObject(Object,Point,Padding)
            if not Object or not Object.Parent or not Object.Visible then return false end
            Padding=tonumber(Padding) or 0
            local Position=Object.AbsolutePosition
            local Size=Object.AbsoluteSize
            return Point.X>=Position.X-Padding and Point.X<=Position.X+Size.X+Padding
                and Point.Y>=Position.Y-Padding and Point.Y<=Position.Y+Size.Y+Padding
        end
        local function CursorInsideNotchRegion()
            if not PUIS.MouseEnabled then return nil end
            local OK,Point=pcall(function() return PUIS:GetMouseLocation() end)
            if not OK or not Point then return nil end
            if CursorInsideGuiObject(Notch,Point,3) then return true end
            if NotchMiniExpanded and CursorInsideGuiObject(NotchMini,Point,3) then return true end
            return false
        end
        task.spawn(function()
            while Gui.Parent do
                if NotchMiniExpanded and not S.Visible and not S.Transitioning and not LevelUpDropActive
                    and not NotchControlInputIsGuarded() and PUIS.MouseEnabled then
                    local Inside=CursorInsideNotchRegion()
                    if Inside==false and NotchHovered then
                        SetNotchHoverIntent(false)
                    elseif Inside==true and not NotchHovered then
                        SetNotchHoverIntent(true)
                    end
                end
                task.wait(NotchMiniExpanded and .045 or .16)
            end
        end)

        local function NotchPressFeedback()
            if Runtime.ReducedMotion==true or LevelUpDropActive then return end
            NotchPressToken+=1
            local PressToken=NotchPressToken
            Tw(NotchScale,.050,{Scale=.991},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
            Tw(NotchStroke,.050,{Transparency=.54},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
            task.delay(S.MotionDelay(.035),function()
                if Gui.Parent and PressToken==NotchPressToken and not S.Visible and not LevelUpDropActive then
                    Tw(NotchScale,.095,{Scale=1.0015},Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                    Tw(NotchStroke,.095,{Transparency=NotchMiniExpanded and .60 or .68},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    task.delay(S.MotionDelay(.065),function()
                        if Gui.Parent and PressToken==NotchPressToken and not S.Visible and not LevelUpDropActive then
                            local RestStroke=NotchMiniExpanded and .64 or .78
                            Tw(NotchScale,.085,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                            Tw(NotchStroke,.085,{Transparency=RestStroke},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                        end
                    end)
                end
            end)
        end

        local function OpenHubFromNotch()
            if NotchControlInputIsGuarded() then return false end
            if SetNotchHoverPeek then SetNotchHoverPeek(false,true) end
            NotchPressToken+=1
            NotchHoverIntentToken+=1
            NotchHovered=false
            SetMiniExpanded(false,true,true)
            if not S.Visible and not S.Transitioning and Rayfield and Rayfield.ToggleUI then
                Rayfield:ToggleUI()
                return true
            end
            return false
        end

        -- Long-press is the touch/no-hover fallback. Releasing a consumed hold does NOT open the hub.
        trackPremiumConnection(Notch.InputBegan:Connect(function(Input)
            local Type=Input and Input.UserInputType
            if Type~=Enum.UserInputType.MouseButton1 and Type~=Enum.UserInputType.Touch then return end
            if S.Visible or S.Transitioning or LevelUpDropActive or NotchControlInputIsGuarded() then return end
            if NotchLongPressHeld then return end
            NotchLongPressHeld=true
            S.NotchHoldInput=Input
            NotchLongPressToken+=1
            local Token=NotchLongPressToken
            task.delay(NotchLongPressDelay,function()
                if not Gui.Parent or Token~=NotchLongPressToken or not NotchLongPressHeld then return end
                if S.Visible or S.Transitioning or LevelUpDropActive or NotchControlInputIsGuarded() then return end
                S.ConsumedNotchInputs[Input]=true
                NotchHovered=true
                if not NotchMiniExpanded then SetMiniExpanded(true,false) end
            end)
        end))
        trackPremiumConnection(PUIS.InputEnded:Connect(function(Input)
            if Input~=S.NotchHoldInput then return end
            S.NotchHoldInput=nil
            local Type=Input and Input.UserInputType
            if Type==Enum.UserInputType.MouseButton1 or Type==Enum.UserInputType.Touch then
                NotchLongPressHeld=false
                NotchLongPressToken+=1
                if S.ConsumedNotchInputs[Input] then
                    if Type==Enum.UserInputType.Touch then SetNotchHoverIntent(false) end
                end
            end
        end))

        trackPremiumConnection(Notch.Activated:Connect(function(Input)
            if S.Visible or S.Transitioning or LevelUpDropActive then return end
            if NotchControlInputIsGuarded() then return end
            if Input and S.ConsumedNotchInputs[Input] then return end
            NotchPressFeedback()
            OpenHubFromNotch()
        end))
        local function BindMiniButtonMotion(Button)
            local ScaleObj=N("UIScale",{Scale=1},Button)
            trackPremiumConnection(Button.MouseEnter:Connect(function()
                SetNotchHoverIntent(true)
                if Button.TextTransparency>=.40 or Runtime.ReducedMotion==true then return end
                Tw(Button,.14,{BackgroundColor3=Color3.fromRGB(29,30,34)},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                Tw(ScaleObj,.14,{Scale=1.004},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
            end))
            trackPremiumConnection(Button.MouseLeave:Connect(function()
                -- The expanded controller owns hover/collapse. Leaving one child button must not
                -- collapse the notch while the cursor is still inside another part of the panel.
                Tw(Button,.12,{BackgroundColor3=Color3.fromRGB(23,23,27)},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                Tw(ScaleObj,.12,{Scale=1},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
            end))
            trackPremiumConnection(Button.MouseButton1Down:Connect(function()
                ArmNotchControlInputGuard(.16)
                if Button.TextTransparency>=.40 then return end
                Tw(ScaleObj,.055,{Scale=.988},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
            end))
            trackPremiumConnection(Button.MouseButton1Up:Connect(function()
                ArmNotchControlInputGuard(.16)
                if Button.TextTransparency>=.40 then
                    ScaleObj.Scale=1
                    return
                end
                Tw(ScaleObj,.095,{Scale=1.002},Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                task.delay(S.MotionDelay(.065),function()
                    if Button.Parent then Tw(ScaleObj,.085,{Scale=1},Enum.EasingStyle.Sine,Enum.EasingDirection.Out) end
                end)
            end))
        end
        BindMiniButtonMotion(NotchMiniPause)
        BindMiniButtonMotion(NotchMiniStop)

        trackPremiumConnection(NotchMiniPause.Activated:Connect(function()
            ArmNotchControlInputGuard(.18)
            if NotchMiniPause:GetAttribute("TaskActionEnabled")~=true then return end
            PauseResumeNotchTask()
            task.delay(.05,function() if Gui.Parent then RefreshNotch() end end)
        end))
        trackPremiumConnection(NotchMiniStop.Activated:Connect(function()
            ArmNotchControlInputGuard(.18)
            if NotchMiniStop:GetAttribute("TaskActionEnabled")~=true then return end
            StopNotchTask()
            task.delay(.05,function() if Gui.Parent then RefreshNotch() end end)
        end))
        task.spawn(function()
            while Gui.Parent do
                RefreshNotch()
                -- HP itself is event-driven now; this loop only refreshes telemetry/automation state
                -- and catches rare Humanoid swaps (for example proxy/invisibility transitions).
                local WaitTime
                if NotchMiniExpanded then WaitTime=.28
                elseif NotchHovered then WaitTime=.35
                elseif Runtime.DynamicIslandLastActive then WaitTime=.48
                else WaitTime=1.00 end
                task.wait(WaitTime)
            end
            ClearNotchHealthConnections()
        end)

