        local function SetNavIconColor(RootIcon)
            if not RootIcon then return end
            local Name=RootIcon:GetAttribute("NavName") or "Main"
            local Primary=NavPrimary[Name] or NavPrimary.Main
            local Secondary=NavSecondary[Name] or NavSecondary.Main
            local Dark=NavDark[Name] or NavDark.Main
            for _,O in ipairs(RootIcon:GetDescendants()) do
                if O:IsA("Frame") then
                    if O.Name=="IconFillPrimary" then O.BackgroundColor3=Primary
                    elseif O.Name=="IconFillSecondary" then O.BackgroundColor3=Secondary
                    elseif O.Name=="IconFillDark" then O.BackgroundColor3=Dark
                    elseif O.Name=="IconPupil" then O.BackgroundColor3=SlateOutline end
                elseif O:IsA("UIStroke") then O.Color=SlateOutline end
            end
        end

