        local ChangeText=T(Changelog,"• Compact notch content now fades out before the shell begins its main expansion\n• Expanded details reveal late with a soft slide/fade instead of overlapping the compact layout\n• Collapse reverses the staging so compact content returns only after the shell is mostly closed\n• Preserves the warm contained gold Level Up burst, exact activity resume, and two-button controller",7.2,Theme.Muted,Enum.TextXAlignment.Left,Enum.Font.Gotham); ChangeText.Position=UDim2.fromOffset(11,42); ChangeText.Size=UDim2.new(1,-22,1,-46); ChangeText.TextWrapped=true; ChangeText.TextYAlignment=Enum.TextYAlignment.Top; ChangeText.TextTruncate=Enum.TextTruncate.AtEnd; ChangeText.LineHeight=.90


        local PlaceTitle=(PlaceInfo and PlaceInfo.Name) or game.Name or "Roblox"
        pcall(function()
            local Info=PMarket:GetProductInfo(game.PlaceId)
            if Info and Info.Name and tostring(Info.Name)~="" then PlaceTitle=tostring(Info.Name) end
        end)

        local UniverseId=tonumber(game.GameId) or 0
        local GameArt=(UniverseId>0)
            and ("rbxthumb://type=GameIcon&id="..tostring(UniverseId).."&w=150&h=150")
            or ""
        local GameArtFallbackURL=""

        local function detectedProfileName()
            local Kind=Runtime and Runtime.DetectedGameProfileKind
            if Kind and tostring(Kind)~="" then
                local Friendly={
                    BloxFruits="Blox Fruits",MM2="Murder Mystery 2",MVS="Murderers VS Sheriffs",
                    AdoptMe="Adopt Me!",BuildABoat="Build A Boat For Treasure",Bloxburg="Welcome to Bloxburg",
                    BasketballLegends="Basketball Legends",PrisonLife="Prison Life",Arsenal="Arsenal",
                    Adaptive=PlaceTitle
                }
                return Friendly[tostring(Kind)] or tostring(Kind)
            end
            return PlaceTitle
        end

        local function imageLoaded(ImageObject)
            local Loaded=false
            pcall(function() Loaded=ImageObject and ImageObject.IsLoaded==true end)
            return Loaded
        end
        local function gameArtLoaded()
            return imageLoaded(HeaderImage) or imageLoaded(DetectorImage)
        end

        local function applyGameArt(Content)
            Content=tostring(Content or "")
            if Content=="" then return false end
            GameArt=Content
            HeaderImage.Image=Content
            DetectorImage.Image=Content
            HeaderImage.Visible=true
            DetectorImage.Visible=true
            task.spawn(function()
                pcall(function() PContent:PreloadAsync({HeaderImage,DetectorImage}) end)
            end)
            return true
        end

        local function requestGameArtFallback()
            if UniverseId<=0 or GameArtFallbackURL~="" then return GameArtFallbackURL end
            local URL="https://thumbnails.roblox.com/v1/games/icons?universeIds="..tostring(UniverseId)
                .."&returnPolicy=PlaceHolder&size=150x150&format=Png&isCircular=false"
            local OK,Body=pcall(function() return game:HttpGet(URL,true) end)
            if not OK or type(Body)~="string" or Body=="" then return "" end
            local ParsedOK,Parsed=pcall(function() return PHttp:JSONDecode(Body) end)
            local Item=ParsedOK and type(Parsed)=="table" and type(Parsed.data)=="table" and Parsed.data[1] or nil
            local ImageURL=Item and tostring(Item.imageUrl or "") or ""
            if ImageURL~="" then GameArtFallbackURL=ImageURL end
            return GameArtFallbackURL
        end

        local refreshFavoriteCard
        local jumpToFeature=function() return false end
        local refreshDetectionInfo=function() end
        local function refreshHeader()
            local Name=detectedProfileName()
            if GameArt~="" then
                HeaderImage.Image=GameArt
                DetectorImage.Image=GameArt
                if Nav and Nav.Game and Nav.Game.Icon then
                    local Thumb=Nav.Game.Icon:FindFirstChild("GameThumb",true)
                    if Thumb and Thumb:IsA("ImageLabel") then Thumb.Image=GameArt end
                    local Fallback=Nav.Game.Icon:FindFirstChild("GameThumbFallback",true)
                    if Fallback then Fallback.Visible=false end
                end
            elseif Nav and Nav.Game and Nav.Game.Icon then
                local Fallback=Nav.Game.Icon:FindFirstChild("GameThumbFallback",true)
                if Fallback then Fallback.Visible=true end
            end
            local ArtReady=gameArtLoaded()

            HeaderFallback.Visible=not ArtReady
            DetectorFallback.Visible=not ArtReady
            DetName.Text=Name
            local Kind=tostring(Runtime and Runtime.DetectedGameProfileKind or "Adaptive")
            local Supported=Kind~="Adaptive"
            DetStatus.Text=(Supported and "SUPPORTED" or "ADAPTIVE").." • v"..tostring(BANANIHUB_VERSION)
            DetStatus.TextColor3=Supported and Theme.Green or Theme.GoldSoft
            TopGame.Text="Game: "..Name
            TopMode.Text="Mode: "..(Supported and "Dedicated Profile" or "Universal / Adaptive")
            GameTitle.Text=Name
            GameSub.Text="BananiHub • ready"
            if Nav and Nav.Game then Nav.Game.Label.Text=Name end
            if S.Page=="Game" then PageTitle.Text=Name end
            refreshDetectionInfo()
            if refreshFavoriteCard then refreshFavoriteCard() end
        end

        if GameArt~="" then applyGameArt(GameArt) end
        pcall(function() HeaderImage:GetPropertyChangedSignal("IsLoaded"):Connect(refreshHeader) end)
        pcall(function() DetectorImage:GetPropertyChangedSignal("IsLoaded"):Connect(refreshHeader) end)

        task.delay(2.25,function()
            if not Gui.Parent or gameArtLoaded() then return end
            local Fallback=requestGameArtFallback()
            if Fallback~="" and Gui.Parent then
                applyGameArt(Fallback)
                task.delay(.65,function() if Gui.Parent then refreshHeader() end end)
            end
        end)

        local Standard={Main=true,Game=true,Player=true,Travel=true,Visuals=true,["UI Editor"]=true,Camera=true,Stats=true,Guide=true,Settings=true}
        local function low(V) return string.lower(tostring(V or "")) end
        local function registry()
            local Raw=Rayfield and Rayfield._PremiumRegistry or {}
            table.sort(Raw,function(A,B) return (A.Order or 0)<(B.Order or 0) end)

            -- v5.14.37: never hide a feature just because another page has something
            -- with a similar name. Keep every unique registered control visible.
            -- Only collapse true duplicates: the same Flag or the exact same
            -- Tab/Section/Kind/Name record being registered twice.
            local Final,SeenFlag,SeenRecord={}, {}, {}
            for _,Record in ipairs(Raw) do
                if Record then
                    local FlagKey=Record.Flag and tostring(Record.Flag)~="" and tostring(Record.Flag) or nil
                    local RecordKey=table.concat({tostring(Record.Tab or ""),tostring(Record.Section or ""),tostring(Record.Kind or ""),tostring(Record.Name or "")},"|")
                    if (not FlagKey or not SeenFlag[FlagKey]) and not SeenRecord[RecordKey] then
                        if FlagKey then SeenFlag[FlagKey]=true end
                        SeenRecord[RecordKey]=true
                        table.insert(Final,Record)
                    end
                end
            end
            return Final
        end

        refreshDetectionInfo=function() end

        local function favoriteRecordByName(Name)
            local Wanted=low(Name):gsub("[^%w]+","")
            if Wanted=="" then return nil end
            local Best=nil
            for _,R in ipairs(registry()) do
                local RN=low(cleanName(R.Name)):gsub("[^%w]+","")
                if RN==Wanted then return R end
                if not Best and (string.find(RN,Wanted,1,true) or string.find(Wanted,RN,1,true)) then Best=R end
            end
            return Best
        end
        local function favoriteRecordByFlag(Flag)
            for _,R in ipairs(registry()) do if tostring(R.Flag or "")==tostring(Flag or "") then return R end end
            return nil
        end
        local FavoriteBindings={}
        local function favoriteTarget(Name)
            if Name=="Invisible" then return favoriteRecordByFlag("Player_Invisible") or favoriteRecordByName("Invisible") end
            if Name=="Fly" then return favoriteRecordByFlag("Player_Fly") or favoriteRecordByName("Fly") end
            if Name=="Noclip" then return favoriteRecordByFlag("Player_Noclip") or favoriteRecordByName("Noclip") or favoriteRecordByName("No Clip") end
            if Name=="Chams" then return favoriteRecordByFlag("Visuals_PlayerChams") or favoriteRecordByName("Player Chams") end
            return favoriteRecordByName(Name)
        end
        local function fireFavorite(Name)
            -- Invisible Favorites must use the same live Invisible state as the
            -- Player/MM2 buttons and keybind; do not trust a stale UI CurrentValue.
            if Name=="Invisible" and Runtime.ToggleBananiInvisible then
                local WasActive=Runtime.IsBananiInvisibleActive and Runtime.IsBananiInvisibleActive() or false
                local Ok,NowActive=Runtime.ToggleBananiInvisible(false)
                if (not WasActive) and not Ok and not NowActive then
                    Notify("Invisible","Invisible favorite failed: "..tostring(Runtime.LastInvisibleError or "swap failed"))
                end
                return Ok or WasActive
            end
            local R=favoriteTarget(Name)
            if not R then return false end
            if R.Kind=="Toggle" and R.Obj and R.Obj.Set then
                pcall(function() R.Obj:Set(not (R.Obj.CurrentValue==true)) end); return true
            elseif R.Kind=="Button" then
                if R.Callback then safeCall(R.Callback); return true end
            elseif R.Kind=="Keybind" or R.Kind=="Slider" or R.Kind=="Dropdown" or R.Kind=="Input" or R.Kind=="Color" then
                return jumpToFeature(cleanName(R.Name))
            end
            return false
        end
        refreshFavoriteCard=function()
            local Names={"Invisible","Fly","Noclip","Chams"}
            FavoritesSub.Text="Invisible • Fly • Noclip • Chams"
            for I,B in ipairs(FavoriteRows) do
                local Slot=I; local Name=Names[Slot]; local R=favoriteTarget(Name)
                B.Visible=true
                local IsOn
                if Name=="Invisible" then
                    IsOn=Runtime.IsBananiInvisibleActive and Runtime.IsBananiInvisibleActive() or false
                else
                    IsOn=R and R.Kind=="Toggle" and R.Obj and R.Obj.CurrentValue==true
                end
                B.Text=(IsOn and "●  " or "○  ")..Name
                B.TextColor3=IsOn and Theme.GoldSoft or Theme.Text
                if not FavoriteBindings[I] then
                    FavoriteBindings[I]=true
                    local CurrentName=Name
                    B.MouseButton1Click:Connect(function()
                        if CurrentName then fireFavorite(CurrentName); task.delay(.06,refreshFavoriteCard) end
                    end)
                end
            end
        end
        Runtime.RefreshFavoriteCard=refreshFavoriteCard

        local function isDetectedRecord(R) return R and R.Tab and not Standard[R.Tab] end
        local function containsAny(Text,List)
            Text=low(Text)
            for _,Needle in ipairs(List) do
                if string.find(Text,low(Needle),1,true) then return true end
            end
            return false
        end
        local function routePage(R)
            local Tab=tostring(R and R.Tab or "")
            local Section=low(R and R.Section or "")
            local Name=low(R and R.Name or "")

            if Tab=="Player" then return "Player" end
            if Tab=="Travel" then return "Teleports" end
            if Tab=="Visuals" or Tab=="UI Editor" or Tab=="Camera" then return "Visuals" end
            if Tab=="Stats" then return "Stats" end
            if Tab=="Settings" or Tab=="Guide" then return "Settings" end
            if Tab=="Game" then return "Main" end

            if isDetectedRecord(R) then
                local Kind=tostring(Runtime and Runtime.DetectedGameProfileKind or "")
                -- MM2 owns its complete organized page. Keep its Role ESP, Gun ESP,
                -- Knife ESP, Coin ESP, arrows/radar/chams beside the rest of MM2 instead
                -- of silently routing part of the profile to the universal Visuals page.
                if Kind=="MM2" then return "Game" end
                if Name=="bunny hop" then return "Player" end
                if containsAny(Section,{"prison life • esp"})
                    or containsAny(Name,{"enemy esp range","enemy esp + health + distance","prison esp + health + distance","player esp range","optional weapon text"}) then
                    return "Visuals"
                end
                return "Game"
            end

            return "Game"
        end
        local function groupFor(Page,R)
            local Tab=tostring(R and R.Tab or "")
            local Sec=tostring(R and R.Section or "General")
            local Sx=low(Sec)
            local Nx=low(R and R.Name or "")

            if Page=="Main" then
                return "Game"
            elseif Page=="Game" then
                local Kind=tostring(Runtime and Runtime.DetectedGameProfileKind or "")
                if Kind=="BloxFruits" then
                    -- v5.16.9: keep every Blox Fruits feature section as its own
                    -- premium category instead of merging unrelated sections together.
                    -- Only the profile overview gets the friendly General label.
                    if Sx=="blox fruits" then return "General" end
                    return Sec~="" and Sec or "General"
                end

                if containsAny(Sx,{"movement + world"}) then return "Pickups + Profile" end
                if containsAny(Sx,{"prison life • movement","prison life • movement"}) then return "Prison Life • Character" end
                if containsAny(Sx,{"player + movement"}) then return "MM2 Player Tools" end
                if Sx=="overview" then return "Core Features" end
                return Sec~="" and Sec or "Gameplay"
            elseif Page=="Player" then
                if string.find(Nx,"invisible",1,true) then return "Invisible" end
                if Nx=="bunny hop" then return "Speed & Jump" end
                if containsAny(Sx,{"character actions"}) then return "Character Actions" end
                if containsAny(Sx,{"tools & interactions","tools and interactions"}) then return "Tools & Interactions" end
                if containsAny(Sx,{"flight & collision","flight and collision"}) then return "Flight & Collision" end
                if containsAny(Sx,{"speed & jump","speed and jump"}) then return "Speed & Jump" end
                if containsAny(Sx,{"auto walk"}) then return "Auto Walk" end
                if containsAny(Sx,{"protection & session","protection and session"}) then return "Protection & Session" end
                if Sx=="overview" then return "Character" end
                return Sec~="" and Sec or "Player"
            elseif Page=="Visuals" then
                if Tab=="Camera" then return "Camera" end
                if Tab=="UI Editor" then return "UI Editor" end
                if isDetectedRecord(R) then
                    local K=tostring(Runtime and Runtime.DetectedGameProfileKind or "")
                    if K=="Arsenal" and containsAny(Nx,{"enemy esp"}) then return "Arsenal ESP" end
                    if K=="PrisonLife" and (containsAny(Sx,{"prison life • esp"}) or containsAny(Nx,{"prison esp","player esp range"})) then return "Prison Life ESP" end
                    if K=="MM2" and containsAny(Sx,{"mm2 esp"}) then return Sec end
                end
                if containsAny(Sx,{"player esp"}) then return "Player ESP" end
                if containsAny(Sx,{"npc esp"}) then return "NPC ESP" end
                if containsAny(Sx,{"item","rare"}) then return "Items / Alerts" end
                if containsAny(Sx,{"world","performance"}) then return "World / Performance" end
                if Sx=="overview" then return "Visuals" end
                return "Visuals"
            elseif Page=="Teleports" then
                if containsAny(Sx,{"player travel"}) then return "Players" end
                if containsAny(Sx,{"quick save"}) then return "Quick Save" end
                if containsAny(Sx,{"waypoint"}) then return "Waypoints" end
                if containsAny(Sx,{"route"}) then return "Routes" end
                if containsAny(Sx,{"teleporter tool"}) then return "Tool" end
                if Sx=="overview" then return "Travel" end
                return "Travel"
            elseif Page=="Stats" then

                return "Live Profile"
            elseif Page=="Settings" then
                if containsAny(Sx,{"appearance"}) then return "Appearance" end
                if containsAny(Sx,{"preset","config"}) then return "Configs" end
                if containsAny(Sx,{"interface control","keybind"}) then return "Keybinds" end
                if containsAny(Sx,{"diagnostic","health"}) then return "Diagnostics" end
                if containsAny(Sx,{"reset","unload"}) then return "Reset" end
                if containsAny(Sx,{"pinned","favorite"}) then return "Pinned" end
                if Tab=="Guide" then return "Guide" end
                return "Settings"
            end
            return (Sec~="" and low(Sec)~="overview") and Sec or "General"
        end

        local GroupPriority={
            Main={Game=1},
            Game={},
            Player={["Invisible"]=1,["Speed & Jump"]=2,["Flight & Collision"]=3,["Character Actions"]=4,["Auto Walk"]=5,["Tools & Interactions"]=6,["Protection & Session"]=7},
            Visuals={["Player ESP"]=1,["Items / Alerts"]=2,["NPC ESP"]=3,Visuals=4,["World / Performance"]=5,Camera=6,["UI Editor"]=7},
            Stats={["Live Profile"]=1},
            Teleports={Players=1,Travel=2,Waypoints=3,Routes=4,["Quick Save"]=5,Tool=6},
            Settings={Pinned=1,Keybinds=2,Appearance=3,Configs=4,Diagnostics=5,Guide=6,Reset=7,Settings=8},
        }
        local function groupsFor(Page)
            local Groups,Map={},{}
            local function add(GroupName,Record)
                GroupName=cleanName(GroupName or "General")
                if GroupName=="" then GroupName="General" end
                if not Map[GroupName] then
                    local Gp={Name=GroupName,Records={},FirstOrder=Record and Record.Order or 999999}
                    Map[GroupName]=Gp; table.insert(Groups,Gp)
                end
                table.insert(Map[GroupName].Records,Record)
            end
            for _,R in ipairs(registry()) do
                if routePage(R)==Page then add(groupFor(Page,R),R) end
            end
            local Priority=GroupPriority[Page] or {}
            local function GameRank(Name)
                if Page~="Game" then return nil end
                local K=tostring(Runtime and Runtime.DetectedGameProfileKind or "")
                local N=low(Name)
                local Lists={
                    BloxFruits={{"auto farm",1},{"fruits + collection",2},{"fishing",3},{"raid",4},{"progression",5},{"combat + materials",6},{"travel + sea",7},{"utility + esp",8}},
                    MM2={{"gun / sheriff",1},{"knife / murderer",2},{"coins",3},{"esp / chams",4},{"teleports",5},{"survival",6},{"player / movement",7},{"round info",8},{"misc",9},{"server",10}},
                    MVS={{"combat",1},{"aim",2},{"weapon",3},{"round",4},{"esp",5},{"server",8}},
                    AdoptMe={{"care",1},{"active",2},{"pet pen",3},{"inventory",4},{"egg",5},{"reward",6},{"job",7},{"trade",8},{"performance",9}},
                    Bloxburg={{"work",1},{"job",2},{"needs",3},{"house",4},{"vehicle",5},{"money",6},{"server",9}},
                    BuildABoat={{"gold farm",1},{"stage",2},{"boat",3},{"travel",4},{"treasure",5},{"performance",8},{"server",9}},
                    BasketballLegends={{"gameplay",1},{"shoot",2},{"defense",3},{"ball",4},{"stats",5},{"server",9}},
                    PrisonLife={{"combat",1},{"character",2},{"items",3},{"team",4},{"doors",5},{"server",9}},
                    Arsenal={{"combat",1},{"aim",2},{"weapon",3},{"esp",4},{"character",5},{"server",9}},
                    Adaptive={{"gameplay",1},{"combat",2},{"items",3},{"interaction",4},{"server",9}}
                }
                for _,Pair in ipairs(Lists[K] or {}) do if string.find(N,Pair[1],1,true) then return Pair[2] end end
                return 50
            end
            table.sort(Groups,function(A,B)
                local PA=GameRank(A.Name) or Priority[A.Name] or 100
                local PB=GameRank(B.Name) or Priority[B.Name] or 100
                if PA~=PB then return PA<PB end
                if A.FirstOrder~=B.FirstOrder then return A.FirstOrder<B.FirstOrder end
                return A.Name<B.Name
            end)
            if #Groups==0 then table.insert(Groups,{Name="No Features",Records={}}) end
            return Groups
        end

