                    local OK,V=pcall(Opt.DynamicOptions)
                    if OK and type(V)=="table" then List=V; if R.Obj and R.Obj.Refresh then pcall(function() R.Obj:Refresh(V) end) end end
                end
                local Out={}; local Seen={}
                for _,V in ipairs(List or {}) do local SV=tostring(V); if not Seen[SV] then Seen[SV]=true; table.insert(Out,SV) end end
                return Out
            end
            B.MouseButton1Click:Connect(function()
                local Now=os.clock()
