        local function renderStatsProfile(Records)
            local Selector=nil
            local Refresh=nil
            -- Refresh the live player list every time Stats is rendered so every current player is selectable.
            pcall(function() if Runtime.RefreshStatsPlayers then Runtime.RefreshStatsPlayers() end end)
            -- The selector lives in the Player Search section, not Live Profile.
            -- Pull it from the complete Stats registry so the picker is always visible here.
            for _,R in ipairs(registry()) do
                local N=low(R and R.Name or "")
                local TabName=low(R and R.Tab or "")
                if (TabName=="stats" or string.find(TabName,"stats",1,true)) and N=="search or select player" then Selector=R end
                if (TabName=="stats" or string.find(TabName,"stats",1,true)) and string.find(N,"refresh selected player",1,true) then Refresh=R end
            end
            if not Selector then
                for _,R in ipairs(Records or {}) do
                    local N=low(R and R.Name or "")
                    if N=="search or select player" then Selector=R
                    elseif string.find(N,"refresh selected player",1,true) then Refresh=R end
                end
            end

            local Lookup=sectionCard("Choose Player",1)
            -- Dedicated premium player picker. It reads Players:GetPlayers() directly,
            -- stores the chosen UserId separately from the legacy dropdown, and never
            -- lets a dropdown refresh silently reset the selected profile.
            local PersistedId=tonumber(Runtime.StatsSelectedUserIdValue)
            if PersistedId then
                for _,Candidate in ipairs(PPlayers:GetPlayers()) do
                    if Candidate.UserId==PersistedId then SelectedStatsPlayer=Candidate; break end
                end
            end
            local SearchRow=rowBase(Lookup,42,1)
            local SearchBox=N("TextBox",{BackgroundColor3=Color3.fromRGB(20,20,23),BorderSizePixel=0,ClearTextOnFocus=false,Text="",PlaceholderText="Search display name or @username...",PlaceholderColor3=Theme.Muted2,TextColor3=Theme.Text,TextSize=11.2,Font=Enum.Font.Gotham,TextXAlignment=Enum.TextXAlignment.Left,Position=UDim2.fromOffset(9,7),Size=UDim2.new(1,-18,0,28),ZIndex=12},SearchRow); C(SearchBox,7); St(SearchBox,Color3.fromRGB(70,66,58),1,.30); Pad(SearchBox,9,9,0,0)
            local PlayerList=N("ScrollingFrame",{BackgroundColor3=Color3.fromRGB(19,19,22),BackgroundTransparency=.08,BorderSizePixel=0,Active=true,Selectable=true,Visible=false,Size=UDim2.new(1,0,0,0),CanvasSize=UDim2.fromOffset(0,0),AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollBarThickness=4,ScrollBarImageColor3=Theme.GoldDark,LayoutOrder=2,ZIndex=10,ClipsDescendants=true},Lookup); C(PlayerList,8); St(PlayerList,Color3.fromRGB(66,61,52),1,.42); Pad(PlayerList,5,5,5,5)
            local PlayerListLayout=N("UIListLayout",{Padding=UDim.new(0,4),SortOrder=Enum.SortOrder.LayoutOrder},PlayerList)
            local PickerSignature=""
            local PickerOpen=false
            local function setStatsPickerOpen(Open)
                PickerOpen=Open==true
                PlayerList.Visible=PickerOpen
                PlayerList.Size=UDim2.new(1,0,0,PickerOpen and 174 or 0)
            end
            setStatsPickerOpen(false)
            local function chooseStatsPlayer(Target)
                if not Target or Target.Parent~=PPlayers then return end
                SelectedStatsPlayer=Target
                Runtime.StatsSelectedUserIdValue=Target.UserId
                Runtime.LastStatsUserId=nil
                Runtime.StatsSelectedThumbnail=nil
                if Runtime.RefreshStats then Runtime.RefreshStats(true) end
            end
            local function rebuildStatsPicker(Force)
                if not PlayerList.Parent then return false end
                local Q=string.lower(tostring(SearchBox.Text or ""))
                local PlayersNow=PPlayers:GetPlayers()
                table.sort(PlayersNow,function(A,B) return string.lower((A.DisplayName or A.Name)..A.Name)<string.lower((B.DisplayName or B.Name)..B.Name) end)
                if not SelectedStatsPlayer or SelectedStatsPlayer.Parent~=PPlayers then
                    local Wanted=tonumber(Runtime.StatsSelectedUserIdValue)
                    SelectedStatsPlayer=nil
                    if Wanted then for _,P in ipairs(PlayersNow) do if P.UserId==Wanted then SelectedStatsPlayer=P; break end end end
                    SelectedStatsPlayer=SelectedStatsPlayer or PPlayer
                    Runtime.StatsSelectedUserIdValue=SelectedStatsPlayer and SelectedStatsPlayer.UserId or nil
                    if Runtime.RefreshStats then Runtime.RefreshStats(true) end
                end
                local SelectedId=SelectedStatsPlayer and SelectedStatsPlayer.UserId or 0
                local Sig=Q.."|"..tostring(SelectedId).."|"..tostring(#PlayersNow)
                for _,P in ipairs(PlayersNow) do Sig=Sig.."|"..tostring(P.UserId) end
                if not Force and Sig==PickerSignature then return true end
                PickerSignature=Sig
                for _,Ch in ipairs(PlayerList:GetChildren()) do if Ch~=PlayerListLayout and not Ch:IsA("UIPadding") and not Ch:IsA("UICorner") and not Ch:IsA("UIStroke") then Ch:Destroy() end end
                local VisibleCount=0
                for _,P in ipairs(PlayersNow) do
                    local Hay=string.lower(tostring(P.DisplayName or "").." @"..tostring(P.Name or ""))
                    if Q=="" or string.find(Hay,Q,1,true) then
                        VisibleCount+=1
                        local IsSelected=SelectedStatsPlayer==P
                        local B=N("TextButton",{BackgroundColor3=IsSelected and Color3.fromRGB(76,55,24) or Color3.fromRGB(29,29,33),AutoButtonColor=false,Active=true,Selectable=true,Text="",Size=UDim2.new(1,-2,0,44),LayoutOrder=VisibleCount,ZIndex=11},PlayerList); C(B,7); if IsSelected then St(B,Theme.Gold,1,.10) else St(B,Color3.fromRGB(64,61,56),1,.50) end
                        local Avatar=N("ImageLabel",{BackgroundColor3=Color3.fromRGB(14,14,17),BorderSizePixel=0,Position=UDim2.fromOffset(5,5),Size=UDim2.fromOffset(34,34),ScaleType=Enum.ScaleType.Crop,Image="rbxthumb://type=AvatarHeadShot&id="..tostring(P.UserId).."&w=150&h=150",ZIndex=12},B); C(Avatar,9)
                        local DN=T(B,tostring(P.DisplayName or P.Name),10.8,Theme.Text,Enum.TextXAlignment.Left,Enum.Font.GothamBold); DN.Position=UDim2.fromOffset(47,5); DN.Size=UDim2.new(1,-57,0,16); DN.TextTruncate=Enum.TextTruncate.AtEnd; DN.ZIndex=12
                        local UN=T(B,"@"..tostring(P.Name),8.9,IsSelected and Theme.GoldSoft or Theme.Muted,Enum.TextXAlignment.Left,Enum.Font.GothamMedium); UN.Position=UDim2.fromOffset(47,22); UN.Size=UDim2.new(1,-57,0,14); UN.TextTruncate=Enum.TextTruncate.AtEnd; UN.ZIndex=12
                        B.Activated:Connect(function()
                            chooseStatsPlayer(P)
                            SearchBox.Text=""
                            SearchBox.PlaceholderText="Selected: "..tostring(P.DisplayName or P.Name).."  •  click to change"
                            setStatsPickerOpen(false)
                            pcall(function() SearchBox:ReleaseFocus() end)
                            rebuildStatsPicker(true)
                        end)
                    end
                end
                if VisibleCount==0 then
                    local Empty=T(PlayerList,"No players match that search.",9.4,Theme.Muted,Enum.TextXAlignment.Center,Enum.Font.GothamMedium); Empty.Size=UDim2.new(1,-4,0,38); Empty.LayoutOrder=1; Empty.ZIndex=11
                end
                return true
            end
            SearchBox.Focused:Connect(function()
                setStatsPickerOpen(true)
                rebuildStatsPicker(true)
            end)
            SearchBox.FocusLost:Connect(function()
                -- Delay very slightly so a player-row click gets its Activated event first.
                task.delay(0.12,function()
                    if PlayerList.Parent and UserInputService:GetFocusedTextBox()~=SearchBox then
                        setStatsPickerOpen(false)
                    end
                end)
            end)
            SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
                if SearchBox:IsFocused() then setStatsPickerOpen(true) end
                rebuildStatsPicker(true)
            end)
            rebuildStatsPicker(true)
            bindSync(function() return rebuildStatsPicker(false) end)

