        local function renderRecords(Records)
            clearCards()
            if S.Page=="Stats" and S.Group=="Live Profile" then
                renderStatsProfile(Records)
                return
            end
            local Sections,Order={},{}
            for _,R in ipairs(Records or {}) do
                local K
                if S.Page=="Stats" and S.Group=="Live Profile" then
                    local Keep=(R and (R.Name=="Search or Select Player" or R.Obj==StatsAvatarLabel or R.Obj==StatsInformation or string.find(low(R.Name or ""),"refresh selected player",1,true)))
                    if Keep then K="Live Profile" end
                else K=R.Section or "Features" end
                if K then
                    if not Sections[K] then Sections[K]={}; table.insert(Order,K) end
                    table.insert(Sections[K],R)
                end
            end
            if S.Page=="Stats" and Sections["Live Profile"] then
                local function StatsRank(R)
                    local N=low(R and R.Name or "")
                    if N=="search or select player" then return 1 end
                    if R and R.Obj==StatsAvatarLabel then return 2 end
                    if R and R.Obj==StatsInformation then return 3 end
                    if string.find(N,"refresh selected player",1,true) then return 4 end
                    return 10+(R.Order or 0)/100000
                end
                table.sort(Sections["Live Profile"],function(A,B)
                    local RA,RB=StatsRank(A),StatsRank(B)
                    if RA~=RB then return RA<RB end
                    return (A.Order or 0)<(B.Order or 0)
                end)
            end
            if #Order==0 then
                local H=sectionCard("No controls found",1); local R=rowBase(H,58,1); local L=T(R,"The detected profile is still loading. Press Game again in a moment.",8.5,Theme.Muted,Enum.TextXAlignment.Left); L.Position=UDim2.fromOffset(10,0); L.Size=UDim2.new(1,-20,1,0); L.TextWrapped=true
                return
            end
            for SI,SectionName in ipairs(Order) do
                local H=sectionCard(cleanName(SectionName),SI)
                if S.Page=="Main" and cleanName(SectionName)=="General" and S.RenderLocalHealthBar then S.RenderLocalHealthBar(H,-100) end
                for I,R in ipairs(Sections[SectionName]) do
                    local F=Renderers[R.Kind]
                    if F then
                        local OK,Err=xpcall(function() F(H,R,I) end,function(E) return tostring(E) end)
                        if not OK then
                            local ER=rowBase(H,39,I)
                            local EL=T(ER,(R.Name or R.Kind or "Control").." • UI render recovered",8.1,Color3.fromRGB(236,174,84),Enum.TextXAlignment.Left,Enum.Font.GothamMedium)
                            EL.Position=UDim2.fromOffset(10,0); EL.Size=UDim2.new(1,-20,1,0)
                            warn("[BananiHub Premium UI control] "..tostring(Err))
                        end
                    end
                end
            end
        end

