        local SearchIndex,SearchIndexCount=nil,-1
        local function SearchFeatureMatches(Query)
            Query=low(Query):gsub("^%s+",""):gsub("%s+$","")
            if Query=="" then return {},nil end
            local Words={}
            for Word in Query:gmatch("%S+") do table.insert(Words,Word) end
            local Matches={}
            local Raw=Rayfield and Rayfield._PremiumRegistry or {}
            if not SearchIndex or SearchIndexCount~=#Raw then
                SearchIndex=registry()
                SearchIndexCount=#Raw
            end
            for _,R in ipairs(SearchIndex) do
                local NameText=low(cleanName(R.Name))
                local SectionText=low(R.Section)
                local TabText=low(R.Tab)
                local Hay=NameText.." "..SectionText.." "..TabText
                local Score=0
                local All=true
                for _,Word in ipairs(Words) do
                    if not string.find(Hay,Word,1,true) then All=false break end
                    if NameText==Word then Score+=100
                    elseif string.sub(NameText,1,#Word)==Word then Score+=70
                    elseif string.find(NameText,Word,1,true) then Score+=52
                    elseif string.find(SectionText,Word,1,true) then Score+=30
                    else Score+=18 end
                end
                if All then table.insert(Matches,{Record=R,Score=Score}) end
            end
            table.sort(Matches,function(A,B)
                if A.Score==B.Score then return tostring(A.Record.Name)<tostring(B.Record.Name) end
                return A.Score>B.Score
            end)
            return Matches,Matches[1] and Matches[1].Record or nil
        end
        S.FeatureSearchResults=N("Frame",{Name="SearchResults",BackgroundColor3=Color3.fromRGB(18,18,21),BackgroundTransparency=.02,BorderSizePixel=0,Visible=false,ZIndex=480},Root)
        C(S.FeatureSearchResults,9); St(S.FeatureSearchResults,Theme.GoldDark,1,.18)
        N("UIListLayout",{Padding=UDim.new(0,3),SortOrder=Enum.SortOrder.LayoutOrder},S.FeatureSearchResults)
        Pad(S.FeatureSearchResults,5,5,5,5)
        S.HideFeatureSearchResults=function() if S.FeatureSearchResults then S.FeatureSearchResults.Visible=false end end
        S.FeatureSearchResultRows={}
        for I=1,7 do
            local B=N("TextButton",{BackgroundColor3=Color3.fromRGB(27,27,30),AutoButtonColor=false,Text="",Size=UDim2.new(1,0,0,31),LayoutOrder=I,ZIndex=482,Visible=false},S.FeatureSearchResults); C(B,6)
            local Name=T(B,"",10.2,Theme.Text,Enum.TextXAlignment.Left,Enum.Font.GothamMedium); Name.Position=UDim2.fromOffset(8,2); Name.Size=UDim2.new(1,-16,0,14); Name.ZIndex=483
            local Meta=T(B,"",8.1,Theme.Muted,Enum.TextXAlignment.Left,Enum.Font.Gotham); Meta.Position=UDim2.fromOffset(8,16); Meta.Size=UDim2.new(1,-16,0,12); Meta.ZIndex=483
            local Entry={Button=B,Name=Name,Meta=Meta,Record=nil,Page=nil,Group=nil}
