        end
        S.RebuildFeatureSearchResults=function(Query,Matches)
            Matches=Matches or select(1,SearchFeatureMatches(Query))
            if Query=="" or #Matches==0 or not FeatureSearch:IsFocused() then S.HideFeatureSearchResults(); return end
            local RootPos=Root.AbsolutePosition; local P=FeatureSearchWrap.AbsolutePosition
            local WinPos,WinSize=WindowFrame.AbsolutePosition,WindowFrame.AbsoluteSize
            local W=math.min(FeatureSearchWrap.AbsoluteSize.X,440,WinSize.X-20); local Count=math.min(#Matches,7)
            local X=math.clamp(P.X,WinPos.X+10,math.max(WinPos.X+10,WinPos.X+WinSize.X-W-10))
            local H=10+Count*34
            local Y=P.Y+FeatureSearchWrap.AbsoluteSize.Y+4
            if Y+H>WinPos.Y+WinSize.Y-10 then Y=P.Y-H-4 end
            Y=math.clamp(Y,WinPos.Y+10,math.max(WinPos.Y+10,WinPos.Y+WinSize.Y-H-10))
            S.FeatureSearchResults.Position=UDim2.fromOffset(X-RootPos.X,Y-RootPos.Y)
            S.FeatureSearchResults.Size=UDim2.fromOffset(W,H)
            S.FeatureSearchResults.Visible=true
            for I,Entry in ipairs(S.FeatureSearchResultRows) do
                local Match=Matches[I]
                Entry.Button.Visible=Match~=nil
                Entry.Record=Match and Match.Record or nil
                if Match then
                    Entry.Page=routePage(Entry.Record)
                    Entry.Group=groupFor(Entry.Page,Entry.Record)
                    Entry.Button.BackgroundColor3=I==1 and Color3.fromRGB(47,39,24) or Color3.fromRGB(27,27,30)
                    Entry.Name.Text=cleanName(Entry.Record.Name)
                    Entry.Name.TextColor3=I==1 and Theme.GoldSoft or Theme.Text
                    Entry.Meta.Text=tostring(Entry.Page).."  •  "..tostring(Entry.Group)
                end
            end
        end
        jumpToFeature=function(Query)
            local Matches,Best=SearchFeatureMatches(Query)
            if not Best then
                FeatureSearchHint.Text="No match"
                Tw(FeatureSearchStroke,.12,{Color=Color3.fromRGB(190,82,82),Transparency=.08})
                return false
            end
            local Page=routePage(Best)
            local Group=groupFor(Page,Best)
            selectPage(Page,false,Group)
            FeatureSearchHint.Text=tostring(#Matches).." match"..(#Matches==1 and "" or "es")
            return true
        end
        local SearchRevision=0
        FeatureSearch:GetPropertyChangedSignal("Text"):Connect(function()
            SearchRevision+=1
            local Rev=SearchRevision
            local Q=FeatureSearch.Text
            FeatureSearchClear.Visible=Q~=""
            task.delay(.06,function()
                if Rev~=SearchRevision or not FeatureSearch.Parent then return end
                if Q=="" then
                    FeatureSearchHint.Text="Enter"
                    S.HideFeatureSearchResults()
