                local Matches=SearchFeatureMatches(Q)
                FeatureSearchHint.Text=(#Matches>0) and (tostring(#Matches).." found") or "No match"
                Tw(FeatureSearchStroke,.14,{Color=(#Matches>0) and Theme.Gold or Color3.fromRGB(190,82,82),Transparency=.10})
                S.RebuildFeatureSearchResults(Q,Matches)
            end)
        end)
        FeatureSearchClear.MouseButton1Click:Connect(function()
