                if D.Scale then AppleHover(D.Scale,true,1.006) end
            end)
            D.Button.MouseLeave:Connect(function()
                if S.Page~=Name then Tw(D.Label,.20,{TextColor3=Theme.Muted},Enum.EasingStyle.Sine,Enum.EasingDirection.Out) end
