        if Window and Window.SelectTab then
            local OldSelect=Window.SelectTab
            Window.SelectTab=function(Self,Name)
                local Result
                pcall(function() Result=OldSelect(Self,Name) end)
                local Clean=cleanName(Name)
                local PageMap={Main="Main",Game="Game",Visuals="Visuals",Travel="Teleports",Player="Player",Camera="Visuals",["UI Editor"]="Visuals",Settings="Settings",Stats="Stats",Guide="Settings"}
                local PreferredMap={Game="Stats",Player="Invisible",Camera="Camera",["UI Editor"]="UI Editor",Stats="Live Profile",Guide="Guide"}
                local Mapped=PageMap[Clean]
                if not Mapped and Clean~="" then Mapped="Game" end
                if Mapped and Gui.Parent then task.defer(function() selectPage(Mapped,false,PreferredMap[Clean] or Clean) end) end
