        local Dragging=false; local DragStart; local StartCenter; local DragMoved=false; local LastDragEnded=0
        DragBar.InputBegan:Connect(function(I)
            if I.UserInputType==Enum.UserInputType.MouseButton1 or I.UserInputType==Enum.UserInputType.Touch then
                Dragging=true
                DragMoved=false
                DragStart=Vector2.new(I.Position.X,I.Position.Y)
                StartCenter=WindowFrame.AbsolutePosition+(WindowFrame.AbsoluteSize/2)
            end
        end)
        trackPremiumConnection(PUIS.InputChanged:Connect(function(I)
            if Dragging and StartCenter and (I.UserInputType==Enum.UserInputType.MouseMovement or I.UserInputType==Enum.UserInputType.Touch) then
                local Pointer=Vector2.new(I.Position.X,I.Position.Y)
                if DragStart and (Pointer-DragStart).Magnitude>=4 then DragMoved=true end
                local Center=StartCenter+(Pointer-DragStart)
                local View=(workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280,720)
                local Half=WindowFrame.AbsoluteSize/2
                local KeepVisible=90
                Center=Vector2.new(
                    math.clamp(Center.X,-math.max(Half.X-KeepVisible,0),View.X+math.max(Half.X-KeepVisible,0)),
                    math.clamp(Center.Y,22,View.Y+math.max(Half.Y-KeepVisible,0))
                )
                WindowFrame.Position=UDim2.fromOffset(Center.X,Center.Y)
            end
        end))
        trackPremiumConnection(PUIS.InputEnded:Connect(function(I)
            if I.UserInputType==Enum.UserInputType.MouseButton1 or I.UserInputType==Enum.UserInputType.Touch then
                if Dragging and DragMoved then LastDragEnded=os.clock() end
                Dragging=false
            end
        end))

        local VisibilityToken=0
        local ToggleBusy=false
        S.Transitioning=false
        local WindowPulseTween=nil
        local function setVisible(V,Instant)
            V=V==true
            if Runtime.ReducedMotion==true then Instant=true end
            if S.Transitioning and not Instant then return end
            closeDropdown()
            if S.Visible==V and WindowFrame.Visible==V and not Instant then return end
            VisibilityToken+=1
            local Token=VisibilityToken
            S.Visible=V
            S.Transitioning=not Instant
            local D=desiredScale()
            local FullSize=UDim2.fromOffset(980,610)
            -- Opening deliberately starts from the exact same canonical 336x48 notch rectangle
            -- that closing ends on. Hover expansion is folded back into the notch first, making
            -- open and close read as the same animation played in opposite directions.
            local IslandSize=UDim2.fromOffset(336/math.max(D,.05),48/math.max(D,.05))
            local IslandCenter=UDim2.new(.5,0,0,NotchTopY+24)
            pcall(function()
                local Focused=PUIS:GetFocusedTextBox()
                if Focused then Focused:ReleaseFocus(false) end
            end)

            -- Apple-style rule: one continuous shell morph. Do not chain multiple resize stages or
            -- animate UIScale at the same time; those competing transforms caused the visible jump.
            CancelPremiumTweens()
            Scale.Scale=D
            NotchHovered=false
            if NotchUI.HPGroup then NotchUI.HPGroup.GroupTransparency=1 end

            if V then
                if WindowPulseTween then pcall(function() WindowPulseTween:Play() end) end
                WindowFrame.Visible=true
                WindowFrame.ClipsDescendants=true
                if S.WindowVisualGroup then S.WindowVisualGroup.GroupTransparency=1 end

                if Instant then
                    if S.OpenMorphShell then S.OpenMorphShell.Visible=false end
                    SetNotchVisible(false,true)
                    WindowFrame.Size=FullSize
                    WindowFrame.Position=UDim2.fromScale(.5,.5)
                    WindowFrame.BackgroundTransparency=0
                    WindowCorner.CornerRadius=UDim.new(0,16)
                    WindowStroke.Transparency=.16
                    Glow.ImageTransparency=.80
                    if S.WindowVisualGroup then S.WindowVisualGroup.GroupTransparency=0 end
                    WindowFrame.ClipsDescendants=false
                    S.Transitioning=false
                    return
                end

                -- True reverse of the close morph. First settle any hover-expanded notch back
                -- to the exact 336x48 close endpoint, then expand one screen-space shell from that
                -- same endpoint to the full window. The real window only fades in at the end.
                WindowFrame.Visible=false
                local Shell=S.OpenMorphShell
                local ShellCorner=S.OpenMorphCorner
                local ShellStroke=S.OpenMorphStroke
                local RootSize=Root.AbsoluteSize
                local TargetW=980*D
                local TargetH=610*D
                local TargetCenter=UDim2.fromOffset(RootSize.X*.5,RootSize.Y*.5)
                Shell.Position=UDim2.fromOffset(RootSize.X*.5,NotchTopY+24)
                Shell.Size=UDim2.fromOffset(336,48)
                Shell.BackgroundTransparency=0
                ShellCorner.CornerRadius=UDim.new(0,18)
                ShellStroke.Transparency=.78
                Shell.Visible=false
                if S.OpenMorphTween then pcall(function() S.OpenMorphTween:Cancel() end) end
                if S.OpenMorphCornerTween then pcall(function() S.OpenMorphCornerTween:Cancel() end) end
                if S.OpenMorphStrokeTween then pcall(function() S.OpenMorphStrokeTween:Cancel() end) end

                -- 0.00 -> 0.07: fold the pressed/hovered state into the exact compact notch.
                Tw(Notch,.07,{Size=UDim2.fromOffset(336,48),Position=UDim2.new(.5,0,0,NotchTopY),BackgroundTransparency=0},Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
                Tw(NotchScale,.07,{Scale=1},Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
                Tw(NotchStroke,.07,{Transparency=.78},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                Tw(NotchContent,.06,{GroupTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)

                -- 0.05 -> ~0.43: grow one continuous shell directly from the floating notch.
                task.delay(S.MotionDelay(.05),function()
                    if not Gui.Parent or Token~=VisibilityToken or not S.Visible then return end
                    Shell.Position=UDim2.fromOffset(Root.AbsoluteSize.X*.5,NotchTopY+24)
                    Shell.Size=UDim2.fromOffset(336,48)
                    Shell.BackgroundTransparency=0
                    ShellCorner.CornerRadius=UDim.new(0,18)
                    ShellStroke.Transparency=.78
                    Shell.Visible=true
                    SetNotchVisible(false,true)
                    S.OpenMorphTween=PTween:Create(Shell,TweenInfo.new(PremiumMotionDuration(.42),Enum.EasingStyle.Quint,Enum.EasingDirection.InOut),{
                        Position=TargetCenter,Size=UDim2.fromOffset(TargetW,TargetH),BackgroundTransparency=0
                    })
                    S.OpenMorphCornerTween=PTween:Create(ShellCorner,TweenInfo.new(PremiumMotionDuration(.41),Enum.EasingStyle.Quint,Enum.EasingDirection.InOut),{CornerRadius=UDim.new(0,16)})
                    S.OpenMorphStrokeTween=PTween:Create(ShellStroke,TweenInfo.new(PremiumMotionDuration(.40),Enum.EasingStyle.Sine,Enum.EasingDirection.InOut),{Transparency=.16})
                    S.OpenMorphTween:Play(); S.OpenMorphCornerTween:Play(); S.OpenMorphStrokeTween:Play()
                end)

                -- ~0.37 -> 0.51: crossfade the finished shell into the real interface.
                task.delay(S.MotionDelay(.40),function()
                    if not Gui.Parent or Token~=VisibilityToken or not S.Visible then return end
                    WindowFrame.Visible=true
                    WindowFrame.Size=FullSize
                    WindowFrame.Position=UDim2.fromScale(.5,.5)
                    WindowFrame.BackgroundTransparency=1
                    WindowFrame.ClipsDescendants=true
                    WindowCorner.CornerRadius=UDim.new(0,16)
                    WindowStroke.Transparency=.16
                    Glow.ImageTransparency=1
                    Scale.Scale=D
                    if S.WindowVisualGroup then S.WindowVisualGroup.GroupTransparency=1 end
                    Tw(WindowFrame,.14,{BackgroundTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    Tw(Glow,.14,{ImageTransparency=.80},Enum.EasingStyle.Sine,Enum.EasingDirection.Out)
                    if S.WindowVisualGroup then Tw(S.WindowVisualGroup,.15,{GroupTransparency=0},Enum.EasingStyle.Sine,Enum.EasingDirection.Out) end
                    local Fade=PTween:Create(Shell,TweenInfo.new(PremiumMotionDuration(.14),Enum.EasingStyle.Sine,Enum.EasingDirection.Out),{BackgroundTransparency=1})
                    Fade:Play()
                end)
                task.delay(S.MotionDelay(.57),function()
                    if Gui.Parent and Token==VisibilityToken and S.Visible then
                        Shell.Visible=false
                        Shell.BackgroundTransparency=0
                        WindowFrame.Visible=true
                        WindowFrame.Size=FullSize
                        WindowFrame.Position=UDim2.fromScale(.5,.5)
                        WindowFrame.BackgroundTransparency=0
                        WindowFrame.ClipsDescendants=false
                        WindowCorner.CornerRadius=UDim.new(0,16)
                        WindowStroke.Transparency=.16
                        Scale.Scale=D
                        Glow.ImageTransparency=.80
                        if S.WindowVisualGroup then S.WindowVisualGroup.GroupTransparency=0 end
                        S.Transitioning=false
                    end
                end)
            else
                if S.OpenMorphShell then S.OpenMorphShell.Visible=false end
                if WindowPulseTween then pcall(function() WindowPulseTween:Pause() end) end
                SetNotchVisible(false,true)
                WindowFrame.Visible=true
                WindowFrame.ClipsDescendants=true
                WindowFrame.Size=FullSize
                WindowFrame.Position=UDim2.fromScale(.5,.5)
                WindowFrame.BackgroundTransparency=0
                WindowCorner.CornerRadius=UDim.new(0,16)
                WindowStroke.Transparency=.16
                Glow.ImageTransparency=.80

                if Instant then
                    if S.WindowVisualGroup then S.WindowVisualGroup.GroupTransparency=1 end
                    WindowFrame.Visible=false
                    WindowFrame.ClipsDescendants=false
                    if S.WindowVisualGroup then S.WindowVisualGroup.GroupTransparency=0 end
                    SetNotchVisible(true,true)
                    S.Transitioning=false
                    return
                end

                -- Fade controls first, then shrink only the clean outer shell. This is what keeps
                -- text/cards from resizing and snapping while the window is being sucked upward.
                if S.WindowVisualGroup then Tw(S.WindowVisualGroup,.12,{GroupTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In) end
                Tw(Glow,.12,{ImageTransparency=1},Enum.EasingStyle.Sine,Enum.EasingDirection.In)
                task.delay(S.MotionDelay(.08),function()
                    if not Gui.Parent or Token~=VisibilityToken or S.Visible then return end
                    Tw(WindowFrame,.38,{Size=IslandSize,Position=IslandCenter,BackgroundTransparency=.03},Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
                    Tw(WindowCorner,.38,{CornerRadius=UDim.new(0,18)},Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
                    Tw(WindowStroke,.36,{Transparency=.86},Enum.EasingStyle.Sine,Enum.EasingDirection.InOut)
                end)
                task.delay(S.MotionDelay(.41),function()
                    if Gui.Parent and Token==VisibilityToken and not S.Visible then SetNotchVisible(true,false,true) end
                end)
                task.delay(S.MotionDelay(.56),function()
                    if Gui.Parent and Token==VisibilityToken and not S.Visible then
                        WindowFrame.Visible=false
                        WindowFrame.ClipsDescendants=false
                        WindowFrame.Size=FullSize
                        WindowFrame.Position=UDim2.fromScale(.5,.5)
                        WindowFrame.BackgroundTransparency=0
                        WindowCorner.CornerRadius=UDim.new(0,16)
                        WindowStroke.Transparency=.16
                        Scale.Scale=D
                        Glow.ImageTransparency=.80
                        if S.WindowVisualGroup then S.WindowVisualGroup.GroupTransparency=0 end
                        S.Transitioning=false
                    end
                end)
            end
        end

        -- Keep late premium-UI callbacks on the existing state table instead of allocating
        -- more outer-scope locals. Luau has a hard local-register ceiling and the old build
        -- crossed it here, preventing the entire new instance from compiling.
        S.LastCloseRequest=S.LastCloseRequest or 0
        S.RequestClose=function()
            local Now=os.clock()
            -- A title-bar drag that ends over the minimize/close area must never hide the UI.
            if Now-LastDragEnded<0.30 then return end
            if Now-S.LastCloseRequest<0.15 then return end
            S.LastCloseRequest=Now
            -- Hide only. Never call UnloadBananiHub from a window control.
            setVisible(false)
        end
        -- Use Activated only. InputBegan + Activated could double-fire on some executors/touch paths
        -- and made the premium window appear to close on its own while dragging the title bar.
        trackPremiumConnection(Close.Activated:Connect(S.RequestClose))
        trackPremiumConnection(Min.Activated:Connect(S.RequestClose))
        S.LastScaleRequest=S.LastScaleRequest or 0
        S.RequestScaleToggle=function()
            local Now=os.clock(); if Now-S.LastScaleRequest<0.08 then return end; S.LastScaleRequest=Now
            local D=desiredScale(); Spring(Scale,{Scale=(Scale.Scale>D*.96) and D*.90 or D},.25)
        end
        trackPremiumConnection(Max.InputBegan:Connect(function(I) if I.UserInputType==Enum.UserInputType.MouseButton1 or I.UserInputType==Enum.UserInputType.Touch then S.RequestScaleToggle() end end))
        trackPremiumConnection(Max.Activated:Connect(S.RequestScaleToggle))

        if Rayfield then
            Runtime.RegistryToggleUI=Runtime.RegistryToggleUI or Rayfield.ToggleUI
            Rayfield.ToggleUI=function()
                if ToggleBusy or S.Transitioning then return end
                ToggleBusy=true
                local CurrentlyVisible=(S.Visible==true and WindowFrame.Visible==true)
                -- L/notch toggle is visibility-only and cannot unload the runtime.
                setVisible(not CurrentlyVisible,false)
                task.delay(S.MotionDelay(1.12),function() ToggleBusy=false end)
            end
        end

        S.PrettyEngineName=function(Value)
            Value=tostring(Value or "")
            local Map={BloxAutoLevel="Blox Auto Farm",BloxMaterialFarm="Blox Material Farm",MM2Coins="MM2 Coin Farm",AdoptSmartFarm="Adopt Me Care",AdoptCare="Adopt Me Care",Manual="Manual"}
            if Map[Value] then return Map[Value] end
            Value=Value:gsub("(%l)(%u)","%1 %2"):gsub("_"," ")
            return Value~="" and Value or "Manual"
        end
        S.RefreshEngineStatus=function()
            local M=Runtime.Movement
            local Owner=M and M.Owner or nil
            StatusGame.Text="Movement: "..S.PrettyEngineName(Owner or "Manual")
            local ActiveName,ActiveState,ActiveReason=nil,"Idle",""
            if Owner and Runtime.AutomationStatus and Runtime.AutomationStatus[Owner] then
                local E=Runtime.AutomationStatus[Owner]; ActiveName=Owner; ActiveState=E.State or "Working"; ActiveReason=E.Reason or ""
            else
                ActiveName=Runtime.ActiveAutomationName
                ActiveState=tostring(Runtime.ActiveAutomationState or "Idle")
                ActiveReason=tostring(Runtime.ActiveAutomationReason or "")
                if ActiveState=="Idle" then ActiveName=nil end
            end
            local Label=ActiveState
            if ActiveName then Label=Label.." • "..S.PrettyEngineName(ActiveName) end
            if ActiveReason~="" and ActiveState=="Recovering" then Label=Label.." • "..string.sub(ActiveReason,1,26) end
            StatusPage.Text="Automation: "..Label
            SDot.BackgroundColor3=(ActiveState=="Recovering" and Color3.fromRGB(235,174,70)) or (ActiveState=="Traveling" and Theme.Gold) or Theme.Green
        end
        task.spawn(function()
            local LastKind=""
            while Gui.Parent do
                local UIRefresh=(tonumber(LiveTelemetry and LiveTelemetry.FPS) or 60)<40 and 1.15 or 0.80
                task.wait(S.Visible and UIRefresh or 6)
                if S.Visible then
                    local Kept={}
                    for _,F in ipairs(S.Bindings) do local OK,Alive=pcall(F); if OK and Alive~=false then table.insert(Kept,F) end end
                    S.Bindings=Kept
                    if refreshFavoriteCard then pcall(refreshFavoriteCard) end
                    S.RefreshEngineStatus()
                    local Kind=tostring(Runtime and Runtime.DetectedGameProfileKind or "")
                    if Kind~=LastKind then LastKind=Kind; refreshHeader(); if S.Page=="Game" then rebuildGroups("Game",S.Group) end end
                end
            end
        end)

        S.WindowStroke=WindowFrame:FindFirstChildOfClass("UIStroke")
        WindowPulseTween=nil
        if S.WindowStroke then
            -- Static premium border: avoids a permanent looping tween while keeping the same look.
            S.WindowStroke.Transparency=.18
            WindowPulseTween=nil
        end
        trackPremiumConnection(Gui.AncestryChanged:Connect(function(_,Parent)
            -- Roblox/executors may temporarily detach PlayerGui/gethui children. The keepalive
            -- above will reattach the premium GUI, so only tear down its events on a real unload.
            if Parent==nil and Unloaded then
                if CameraViewportConnection then pcall(function() CameraViewportConnection:Disconnect() end); CameraViewportConnection=nil end
                if WindowPulseTween then pcall(function() WindowPulseTween:Cancel() end); WindowPulseTween=nil end
                ClearNotchHealthConnections()
                Runtime.DynamicIslandUIOnTakeover=nil
                disconnectPremiumConnections()
            end
        end))

        S.Page="Main"; S.Group=nil
        refreshHeader(); selectPage("Main",true)
        task.delay(.75,function()
            if Gui.Parent then
                S.Page="Main"; S.Group=nil
                refreshHeader(); selectPage("Main",true)
            end
        end)
        S.FinalScale=desiredScale(); Scale.Scale=S.FinalScale*.975; WindowFrame.Position=UDim2.new(.5,0,.5,5); WindowFrame.BackgroundTransparency=1; Tw(WindowFrame,.16,{BackgroundTransparency=0,Position=UDim2.fromScale(.5,.5)}); Tw(Scale,.16,{Scale=S.FinalScale})

        Runtime.PremiumAppleUI={
            Gui=Gui,Window=WindowFrame,Notch=Notch,SelectPage=selectPage,SetVisible=setVisible,SetNotchVisible=SetNotchVisible,
            Refresh=function() refreshHeader(); RefreshNotch(); selectPage(S.Page,true,S.Group) end,
            GetGameArt=function() return GameArt end,
            GetTelemetry=function() return {FPS=LiveTelemetry.FPS,Ping=LiveTelemetry.Ping,UpdatedAt=LiveTelemetry.UpdatedAt} end,
            UsesOriginalBackend=false,DefaultMenuKey="L"
        }
        S.PremiumEnvironment=(getgenv and getgenv()) or _G
        S.PremiumEnvironment.BananiHubPremiumUI=Runtime.PremiumAppleUI
        print("[BananiHub] v"..BANANIHUB_VERSION.." • premium-only UI • legacy renderer removed • premium telemetry • menu key L")
    end,PremiumTraceback)
    if not PremiumOK then
        warn("[BananiHub Premium UI] "..tostring(PremiumError))

        pcall(function()
            local Env=(getgenv and getgenv()) or _G
            local API=Env and Env.BananiHubPremiumUI
            if API and API.Gui then API.Gui:Destroy() end
        end)
        pcall(function()
            for _,Parent in ipairs({game:GetService("CoreGui"), Players.LocalPlayer and Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")}) do
                if Parent then local G=Parent:FindFirstChild("BananiHubPremiumApple51412"); if G then G:Destroy() end end
            end
            if gethui then local G=gethui():FindFirstChild("BananiHubPremiumApple51412"); if G then G:Destroy() end end
        end)
        pcall(function()
            if Rayfield then Rayfield._Visible=false end
        end)
    end
end

]==========]
local __BANANIHUB_BOOT_ENV=(getgenv and getgenv()) or _G
__BANANIHUB_BOOT_ENV.__BANANIHUB_SELF_SOURCE=__BANANIHUB_BOOT_SOURCE
__BANANIHUB_BOOT_ENV.__BANANIHUB_BOOTING=true
local __BANANIHUB_BOOT_LOADER,__BANANIHUB_BOOT_ERROR=loadstring(__BANANIHUB_BOOT_SOURCE)
assert(__BANANIHUB_BOOT_LOADER,"BANANIHUB bootstrap compile failed: "..tostring(__BANANIHUB_BOOT_ERROR))
local __BANANIHUB_BOOT_OK,__BANANIHUB_BOOT_RESULT=pcall(__BANANIHUB_BOOT_LOADER)
__BANANIHUB_BOOT_ENV.__BANANIHUB_BOOTING=nil
if not __BANANIHUB_BOOT_OK then error(__BANANIHUB_BOOT_RESULT,0) end
return __BANANIHUB_BOOT_RESULT
